  await pool.query(`ALTER TABLE league_custom_settings ADD COLUMN IF NOT EXISTS league_news_enabled BOOLEAN NOT NULL DEFAULT TRUE`);

  // 7J-138NEGOTIATION: generic (non-Madden) trade negotiation threads, per
