function buildHallOfFameEmbed(league, franchiseRows, awardRows) {
  const NL = String.fromCharCode(10);

  const titleLeaders = franchiseRows.length
    ? franchiseRows
        .slice(0, 10)
        .map((row, index) => `**${index + 1}. ${row.franchise_name}** — ${row.championships} titles`)
        .join(NL)
    : 'No championship records yet.';

  const awardLeaders = awardRows.length
    ? awardRows
        .slice(0, 10)
        .map((row, index) => `**${index + 1}. ${row.winner}** — ${row.award_count} awards`)
        .join(NL)
    : 'No award records yet.';

  return new EmbedBuilder()
    .setTitle(`${league?.league_name || 'League'} • Hall of Fame`)
    .setColor(0xB8860B)
    .addFields(
      { name: 'Championship Leaders', value: titleLeaders, inline: false },
      { name: 'Award Leaders', value: awardLeaders, inline: false }
    )
    .setFooter({ text: 'GG Sports • Hall of Fame' })
    .setTimestamp();
}

function shortGameId(gameId) {
  return String(gameId || '').split('-')[0];
}

function normalizeLeagueGameKey(gameKey = '') {
  return String(gameKey || '').trim().toLowerCase();
}

function isMlbLeague(league) {
  const key = normalizeLeagueGameKey(league?.game_key || league?.game || league?.league_name);
  return key.includes('mlb') || key.includes('baseball') || key.includes('show');
}

function isNbaLeague(league) {
  const key = normalizeLeagueGameKey(league?.game_key || league?.game || league?.league_name);
  return key.includes('nba') || key.includes('2k') || key.includes('basketball');
}

function isNhlLeague(league) {
  const key = normalizeLeagueGameKey(league?.game_key || league?.game || league?.league_name);
  return key.includes('nhl') || key.includes('hockey') || key.includes('chel');
}

// 7J-ALLLEAGUECONF: per Hxxdie — the NBA conference auto-detect existed but
// nothing else did, so every other league (NHL, NFL, MLB, MLS) had no
// fallback at all and showed every team as unassigned until a commissioner
// manually set each one by hand. Adding the same real-world structure for
// the other major leagues with fixed, well-established alignments.
// Deliberately uses EXACT (normalized, full-name) matching, not substring
// matching — the earlier NBA table used substring matching and it silently
// mis-assigned NHL's Chicago Blackhawks/Los Angeles Kings via accidental
// nickname collisions (see 7J-CONFCOLLISION). Never repeat that here.
function isNflLeague(league) {
  const key = normalizeLeagueGameKey(league?.game_key || league?.game || league?.league_name);
  return (key.includes('nfl') || key.includes('madden') || key.includes('football')) && !key.includes('cfb') && !key.includes('college');
}

function isMlsLeague(league) {
  const key = normalizeLeagueGameKey(league?.game_key || league?.game || league?.league_name);
  return key.includes('mls') || key.includes('fifa') || key.includes('soccer') || key.includes('fc ');
}

function isCfbLeague(league) {
  const key = normalizeLeagueGameKey(league?.game_key || league?.game || league?.league_name);
  return key.includes('cfb') || key.includes('ncaa') || key.includes('college football');
}

function isFcLeague(league) {
  const key = normalizeLeagueGameKey(league?.game_key || league?.game || league?.league_name);
  return key.includes('fc ') || key.startsWith('fc') || key.includes('soccer') || key.includes('fifa') || key.includes('efootball');
}

// This was missing entirely — every check elsewhere in the bot that gates a
// Madden-only feature behind `getLeagueSportKey(league) === 'madden'` was silently
// always false, because nothing here ever returned 'madden'. A league explicitly set
// to game_key = 'madden' (via /league game or /league create) fell through every
// is*League() check above and landed on the generic 'other' fallback. That's the root
// cause of Madden-only Commissioner Panel settings (League Leaders, Award Race, Madden
// Free Agents, etc.) not appearing even for genuine Madden leagues.
function isMaddenLeague(league) {
  const key = normalizeLeagueGameKey(league?.game_key || league?.game || league?.league_name);
  return key.includes('madden');
}

function getLeagueSportKey(league) {
  if (isMlbLeague(league)) return 'mlb';
  if (isNbaLeague(league)) return 'nba';
  if (isNhlLeague(league)) return 'nhl';
  if (isCfbLeague(league)) return 'cfb';
  if (isFcLeague(league)) return 'fc';
  if (isMaddenLeague(league)) return 'madden';
  return 'other';
}

