async function getTeamConferenceDivisionForLeague(guildId, leagueId, teamName, league = null) {
  const result = await pool.query(
    `SELECT conference, division FROM league_team_roles WHERE league_id::text = $1::text AND LOWER(role_name) = LOWER($2) LIMIT 1`,
    [String(leagueId), teamName]
  ).catch(() => ({ rows: [] }));
  const row = result.rows?.[0];
  let conference = row?.conference || null;
  let division = row?.division || null;

  // 7J-CONFDIVMERGE: per Hxxdie — this used to return as soon as EITHER
  // field was set manually, which meant a league with conference assigned
  // but division never touched (a very normal partial setup — conference
  // has its own UI, division doesn't) permanently blocked the real-world
  // auto-detect table below from ever filling in the missing division.
  // Playoff seeding for NHL/NFL/MLB specifically needs BOTH pieces to build
  // the real divisional bracket; a bracket that silently fell back to a
  // generic pairing because only division was missing (conference was
  // already right) was confusing — the bracket LOOKED conference-correct,
  // which hid that anything was wrong at all. Now fills in just the gap,
  // not an all-or-nothing choice between "trust the manual data" and
  // "trust the auto-detect table."
  if (!conference || !division) {
    // 7J-CONFCOLLISION: per Hxxdie — the old hardcoded NBA name-substring
    // fallback ran for every league regardless of sport, not just NBA. NHL's
    // Chicago Blackhawks ("...Hawks") and Los Angeles Kings ("...Kings") both
    // happen to contain an NBA team nickname (Atlanta Hawks, Sacramento
    // Kings) as a literal substring, so they were silently getting
    // auto-assigned to Eastern/Western conference before anyone had touched
    // conference assignment at all.
    // 7J-ALLLEAGUECONF: extended the same auto-detect idea to NHL, NFL, and
    // MLB (their conference/division structure is fixed and well known,
    // unlike MLS which realigns yearly and is deliberately left out — see
    // the table comments above). Every lookup here is EXACT full-name
    // matching only, never substring, to make sure the Blackhawks/Kings bug
    // class can't happen again for any of these.
    const normalizedName = String(teamName || '').trim().toLowerCase();
    let autoDetected = null;
    if (league && isNbaLeague(league)) {
      autoDetected = { conference: getTeamConference(teamName), division: null };
    } else if (league && isNhlLeague(league) && NHL_TEAM_CONF_DIV.has(normalizedName)) {
      autoDetected = NHL_TEAM_CONF_DIV.get(normalizedName);
    } else if (league && isNflLeague(league)) {
      // 7J-NFLCONFDIVABBR: per Hxxdie — real bug found reviewing the wild
      // card playoff picture story. EA/Madden exports team names as
      // mascot-only ("Broncos", "Buccaneers"), but this exact-match lookup
      // only had full "City Mascot" names ("Denver Broncos") as keys, so it
      // silently failed for essentially every real Madden league — every
      // team fell through to the generic conference/division fallback and
      // got compared against every OTHER team as if they were all in one
      // merged conference. Falls back to matching via the team's
      // abbreviation (through the same NFL_TEAM_ABBREVIATIONS table
      // already trusted elsewhere for display names) whenever the raw name
      // doesn't match a full name directly — covers mascot-only, full-name,
      // and city-only export formats without needing a second hand-typed
      // alias list.
      if (NFL_TEAM_CONF_DIV.has(normalizedName)) {
        autoDetected = NFL_TEAM_CONF_DIV.get(normalizedName);
      } else {
        const abbr = getMaddenTeamAbbrev(teamName);
        if (abbr) autoDetected = getNflTeamConfDivByAbbr().get(abbr.toUpperCase()) || null;
      }
    } else if (league && isMlbLeague(league) && MLB_TEAM_CONF_DIV.has(normalizedName)) {
      autoDetected = MLB_TEAM_CONF_DIV.get(normalizedName);
    }
    if (autoDetected) {
      conference = conference || autoDetected.conference || null;
      division = division || autoDetected.division || null;
    }
  }

  return { conference, division };
}

function calculateStandingsPointsForLeague(league, wins, losses, ties = 0, customSettings = null, otl = 0) {
  if (customSettings?.standings_system === 'points') {
    return (Number(wins || 0) * Number(customSettings.win_points ?? 2)) + (Number(losses || 0) * Number(customSettings.loss_points ?? 0)) + (Number(ties || 0) * Number(customSettings.tie_points ?? 1)) + (customSettings.otl_allowed ? Number(otl || 0) * Number(customSettings.otl_points ?? 1) : 0);
  }
  return isMlbLeague(league) ? (Number(wins || 0) * 3) + Number(losses || 0) : 0;
}

async function resolveAwardWinnerUserId(guild, winnerText) {
  const text = String(winnerText || '').trim();
  if (!guild || !text) return null;

  const mentionMatch = text.match(/<@!?(\d+)>|^(\d{17,20})$/);
  if (mentionMatch) return mentionMatch[1] || mentionMatch[2];

  const clean = text
    .replace(/^@/, '')
    .replace(/[“”"']/g, '')
    .trim()
    .toLowerCase();

  if (!clean) return null;
  await guild.members.fetch().catch(() => null);

  const exact = guild.members.cache.find(member => {
    const username = member.user.username.toLowerCase();
    const globalName = (member.user.globalName || '').toLowerCase();
    const displayName = (member.displayName || '').toLowerCase();
    return username === clean || globalName === clean || displayName === clean;
  });

  if (exact) return exact.id;

  const partial = guild.members.cache.find(member => {
    const username = member.user.username.toLowerCase();
    const globalName = (member.user.globalName || '').toLowerCase();
    const displayName = (member.displayName || '').toLowerCase();
    return username.includes(clean) || globalName.includes(clean) || displayName.includes(clean);
  });

  return partial?.id || null;
}

function buildScheduleEmbed(league, rows) {
  const NL = String.fromCharCode(10);

  const embed = new EmbedBuilder()
    .setTitle(`${league?.league_name || 'League'} • Schedule`)
    .setColor(0x5865F2)
    .setFooter({ text: 'GG Sports • Schedule' })
    .setTimestamp();

  if (!rows.length) {
    embed.setDescription('No games have been scheduled yet.');
    return embed;
  }

  const lines = rows.map(row => {
    const score = row.status === 'final' ? ` • Final: ${row.away_score}-${row.home_score}` : '';
    const date = row.scheduled_for ? ` • ${row.scheduled_for}` : '';
    const week = row.week_label ? ` • ${row.week_label}` : '';
    return `**${shortGameId(row.id)}** — ${row.away_team_name} @ ${row.home_team_name}${week}${date} • ${row.status}${score}`;
  });

  embed.setDescription(lines.join(NL));
  return embed;
}

async function buildStandingsEmbed(league, rows) {
  const NL = String.fromCharCode(10);
  const customSettings = league ? await ensureLeagueCustomSettings(league).catch(() => ({})) : {};
  const standingsSystem = customSettings.standings_system === 'points' || isMlbLeague(league) ? 'points' : customSettings.standings_system === 'point_differential' ? 'point_differential' : 'wl';
  const useConferences = customSettings.use_conferences ?? isNbaLeague(league);
  const useDivisions = customSettings.use_divisions ?? false;
  const showTies = customSettings.ties_allowed ?? false;
  const showOtl = customSettings.otl_allowed ?? false;

  const systemLabel = standingsSystem === 'points' ? 'Points Standings' : standingsSystem === 'point_differential' ? 'Point Differential Standings' : 'W/L Standings';
  const embed = new EmbedBuilder()
    .setTitle(`${league?.league_name || 'League'} • Standings`)
    .setColor(0x57F287)
    .setFooter({ text: `GG Sports • ${systemLabel}` })
    .setTimestamp();

  if (!rows.length) {
    embed.setDescription('No standings records yet. Report a game or adjust standings to begin.');
    return embed;
  }

  const formatLine = (row, index) => {
    const games = Number(row.wins) + Number(row.losses) + Number(row.ties || 0) + Number(row.otl || 0);
    const winPct = games > 0 ? ((Number(row.wins) + Number(row.ties || 0) * 0.5) / games).toFixed(3).replace(/^0/, '') : '.000';
    const diff = Number(row.points_for || 0) - Number(row.points_against || 0);
    const standingsPoints = Number(row.standings_points ?? calculateStandingsPointsForLeague(league, row.wins, row.losses, row.ties, customSettings, row.otl));
    // Record string builds up whichever extra columns this league has turned on —
    // W-L, W-L-T, W-L-OTL, or the full W-L-T-OTL, never showing a column that's off.
    let record = `${row.wins}-${row.losses}`;
    if (showTies) record += `-${row.ties || 0}`;
    if (showOtl) record += `-${row.otl || 0}`;
    const pointsText = standingsSystem === 'points' ? ' • ' + standingsPoints + ' PTS' : '';
    return `**${index + 1}. ${row.team_name}** — ${record} (${winPct})${pointsText} • DIFF ${diff >= 0 ? '+' : ''}${diff}`;
  };

  if (useConferences || useDivisions) {
    const guildId = rows[0]?.guild_id;
    const groupKey = useConferences ? 'conference' : 'division';
    const grouped = new Map();
    for (const row of rows) {
      const { conference, division } = await getTeamConferenceDivisionForLeague(guildId, league.league_id, row.team_name, league).catch(() => ({ conference: null, division: null }));
      const key = (useConferences ? conference : division) || `Unassigned ${useConferences ? 'Conference' : 'Division'}`;
      if (!grouped.has(key)) grouped.set(key, []);
      grouped.get(key).push(row);
    }
    for (const [groupName, groupRows] of grouped) {
      embed.addFields({ name: groupName, value: groupRows.map(formatLine).join(NL).slice(0, 1024), inline: false });
    }
    return embed;
  }

  embed.setDescription(rows.map(formatLine).join(NL));
  return embed;
}

// 7J-STANDINGSLOGOCONF: per Hxxdie — split the standings logo strip into
// conference/division sections so it visually lines up with the standings
// embed's own grouped fields, instead of one flat ranked strip. Mirrors the
// exact same grouping logic buildStandingsEmbed uses just above (same
// conference/division lookup, same "Unassigned ..." fallback key, same
// group order via Map insertion order) so the embed and the image never
// disagree on how teams are grouped. Returns null when the league doesn't
// use conferences/divisions, so callers fall back to the flat strip.
async function getStandingsLogoGroups(guildId, league, rows) {
  const customSettings = league ? await ensureLeagueCustomSettings(league).catch(() => ({})) : {};
  const useConferences = customSettings.use_conferences ?? isNbaLeague(league);
  const useDivisions = customSettings.use_divisions ?? false;
  if (!useConferences && !useDivisions) return null;

  const grouped = new Map();
  for (const row of rows) {
    const { conference, division } = await getTeamConferenceDivisionForLeague(guildId, league.league_id, row.team_name, league).catch(() => ({ conference: null, division: null }));
    const key = (useConferences ? conference : division) || `Unassigned ${useConferences ? 'Conference' : 'Division'}`;
    if (!grouped.has(key)) grouped.set(key, []);
    grouped.get(key).push(row.team_name);
  }

  return [...grouped.entries()].map(([label, teamNames]) => ({
    label,
    teams: teamNames.map((name, i) => ({ name, rank: i + 1 })),
  }));
}

function buildUserProfileEmbed(league, user, data) {
  const embed = new EmbedBuilder()
    .setTitle(`${league?.league_name || 'League'} • ${user.username} Profile`)
    .setColor(0x5865F2)
    .setThumbnail(user.displayAvatarURL({ dynamic: true }))
    .setImage('attachment://avatar.png')
    .addFields(
      { name: 'Team', value: data.teamName || 'No team assigned', inline: true },
      { name: 'Record', value: `${data.wins}-${data.losses}`, inline: true },
      { name: 'Games Played', value: String(data.gamesPlayed), inline: true },
      { name: 'Championships', value: String(data.championships), inline: true },
      { name: 'Finals Appearances', value: String(data.finalsAppearances), inline: true },
      { name: 'Awards', value: String(data.awardsWon), inline: true },
      { name: 'Approved Trades Involving Team', value: String(data.trades), inline: true },
      { name: 'Tournament Wins', value: String(data.tournamentWins || 0), inline: true },
      { name: 'Tournament MVPs', value: String(data.tournamentMvps || 0), inline: true }
    );

  if (data.legacyDisplay) embed.addFields({ name: '🏆 Legacy', value: data.legacyDisplay, inline: true });
  if (data.activityDisplay) embed.addFields({ name: '⚡ Activity', value: data.activityDisplay, inline: true });
  if (data.badgesDisplay) embed.addFields({ name: 'Badges', value: data.badgesDisplay, inline: false });
  if (data.streamDisplay) embed.addFields({ name: 'Stream', value: data.streamDisplay, inline: false });
  if (data.avatarDisplay) embed.addFields({ name: 'Cosmetics / Avatar', value: data.avatarDisplay, inline: false });

  return embed
    .setFooter({ text: 'GG Sports • User Profile' })
    .setTimestamp();
}

function buildUserStatsEmbed(league, user, data) {
  const NL = String.fromCharCode(10);
  const recentGames = data.recentGames.length
    ? data.recentGames.map(game => {
        const isHome = game.home_team_role_id === data.teamRoleId;
        const teamScore = isHome ? game.home_score : game.away_score;
        const oppScore = isHome ? game.away_score : game.home_score;
        const opponent = isHome ? game.away_team_name : game.home_team_name;
        const result = game.winner_team_role_id === data.teamRoleId ? 'W' : 'L';
        return `**${result}** vs ${opponent} • ${teamScore}-${oppScore}`;
      }).join(NL)
    : 'No recent games found.';

  return new EmbedBuilder()
    .setTitle(`${league?.league_name || 'League'} • ${user.username} Stats`)
    .setColor(0x57F287)
    .setThumbnail(user.displayAvatarURL({ dynamic: true }))
    .addFields(
      { name: 'Team', value: data.teamName || 'No team assigned', inline: true },
      { name: 'Record', value: `${data.wins}-${data.losses}`, inline: true },
      { name: 'Win %', value: data.winPct, inline: true },
      { name: 'Points For', value: String(data.pointsFor), inline: true },
      { name: 'Points Against', value: String(data.pointsAgainst), inline: true },
      { name: 'Point Differential', value: `${data.pointDiff >= 0 ? '+' : ''}${data.pointDiff}`, inline: true },
      { name: 'Avg Points For', value: data.avgFor, inline: true },
      { name: 'Avg Points Against', value: data.avgAgainst, inline: true },
      { name: 'Games Played', value: String(data.gamesPlayed), inline: true },
      { name: 'Recent Games', value: recentGames, inline: false }
    )
    .setFooter({ text: 'GG Sports • Competitive Stats' })
    .setTimestamp();
}

function buildTeamProfileEmbed(league, teamRole, data) {
  const NL = String.fromCharCode(10);
  const recentAwards = data.awards.length
    ? data.awards.map(row => `**${row.season_label}** — ${row.award_name}: ${row.winner}`).join(NL)
    : 'No awards recorded.';

  return new EmbedBuilder()
    .setTitle(`${league?.league_name || 'League'} • ${teamRole.name} Profile`)
    .setColor(0xFEE75C)
    .addFields(
      { name: 'Record', value: `${data.wins}-${data.losses}`, inline: true },
      { name: 'Games Played', value: String(data.gamesPlayed), inline: true },
      { name: 'Point Differential', value: String(data.pointDiff), inline: true },
      { name: 'Championships', value: String(data.championships), inline: true },
      { name: 'Finals Appearances', value: String(data.finalsAppearances), inline: true },
      { name: 'Trades', value: String(data.trades), inline: true },
      { name: 'Recent Awards', value: recentAwards, inline: false }
    )
    .setFooter({ text: 'GG Sports • Team Profile' })
    .setTimestamp();
}

async function savePanel(league, panelKey, channelId, messageId) {
  if (league?.league_id) {
    await pool.query(
      `INSERT INTO league_panels (league_id, panel_key, channel_id, message_id)
       VALUES ($1, $2, $3, $4)
       ON CONFLICT (league_id, panel_key)
       DO UPDATE SET channel_id = EXCLUDED.channel_id, message_id = EXCLUDED.message_id, updated_at = NOW()`,
      [league.league_id, panelKey, channelId, messageId]
    );
  } else {
    await pool.query(
      `INSERT INTO bot_panels (panel_key, channel_id, message_id)
       VALUES ($1, $2, $3)
       ON CONFLICT (panel_key)
       DO UPDATE SET channel_id = EXCLUDED.channel_id, message_id = EXCLUDED.message_id`,
      [panelKey, channelId, messageId]
    );
  }
}

// 7J-61LEAGUEHOF: reuses updatePersistentMaddenEmbed, the same generic
// helper the Madden boards use — confirmed via ensureMaddenLeagueSettings
// that this works for any league type despite the "madden" naming.
async function refreshLeagueHofBoard(guild, league) {
  if (!guild || !league?.league_id) return;
  await updatePersistentMaddenEmbed(guild, league, league.league_hof_channel_id, 'league_hof_message_id',
    async (settings) => {
      const currentView = (settings && settings.league_hof_current_view) || 'legacy';
      return buildLeagueHofBoardEmbed(guild.id, league, currentView);
    },
    (settings) => buildLeagueHofBoardComponents(league.league_id, (settings && settings.league_hof_current_view) || 'legacy'));
}

async function updatePanel(guild, league, panelKey, embed, components = [], files = []) {
  const result = league?.league_id
    ? await pool.query('SELECT channel_id, message_id FROM league_panels WHERE league_id = $1 AND panel_key = $2', [league.league_id, panelKey])
    : await pool.query('SELECT channel_id, message_id FROM bot_panels WHERE panel_key = $1', [panelKey]);

  if (result.rows.length === 0) return;
  const channel = await guild.channels.fetch(result.rows[0].channel_id).catch(() => null);
  if (!channel || !channel.isTextBased()) return;
  const message = await channel.messages.fetch(result.rows[0].message_id).catch(() => null);
  if (message) await message.edit({ embeds: [embed], components, files });
}

function buildTeamOwnersPanelComponents(leagueId) {
  return [new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`teamownerspanel_leave:${leagueId}`).setLabel('Leave Team').setEmoji('🚪').setStyle(ButtonStyle.Danger),
    // 7J-TOAPPLY: per Hxxdie — someone looking at Team Owners to see who's
    // available shouldn't have to go hunt down a separate Recruitment
    // panel just to apply for an open one. Reuses the exact same vacant-
    // team picker → modal flow as Browse Open Teams, just pre-scoped to
    // this league instead of asking which league first.
    new ButtonBuilder().setCustomId(`teamownerspanel_apply:${leagueId}`).setLabel('Apply to Join').setEmoji('🙋').setStyle(ButtonStyle.Primary),
    // 7J-TEAMSCHEDULE: per Hxxdie — a way to see any team's full season
    // schedule (structured leagues only — open-schedule has no fixed
    // schedule to show). Always shown rather than conditionally hidden
    // based on schedule style, since hiding it would require threading
    // schedule_style through every caller of this function; the handler
    // itself checks and gives a clear message if this league isn't
    // structured, matching how Coin Toss/Who's Got Next already check
    // their own preconditions at click time rather than in the button set.
    new ButtonBuilder().setCustomId(`teamownerspanel_schedule:${leagueId}`).setLabel('Team Schedule').setEmoji('📅').setStyle(ButtonStyle.Secondary),
  )];
}

async function updateTeamOwnersPanel(guild, league = null) {
  // Bug: this never passed components, so updatePanel's components=[]
  // default silently wiped the Leave Team button on every single refresh —
  // and every real ownership change (claim, kick, trade) calls this,
  // meaning the button would vanish almost immediately after being posted.
  await updatePanel(guild, league, 'team_owners', await buildTeamOwnersEmbed(guild, league), league ? buildTeamOwnersPanelComponents(league.league_id) : []);
}

// 7J-COMMANDHUB-TEAMOWNERSYNC: whether roleId is one of this league's
// registered team roles — used to gate an updateTeamOwnersPanel refresh so
// it only fires on actual ownership-relevant role changes, not any
// arbitrary role add/remove.
async function isRegisteredTeamRole(league, roleId) {
  if (!league?.league_id || !roleId) return false;
  const teamRoles = await getLeagueTeamRoles(league.league_id);
  return teamRoles.some(team => team.role_id === roleId);
}

// 7J-COMMANDHUB: shared by /commissioner assignrole|unassignrole and the
// new Commissioner Panel Assign/Remove Role buttons — one place for the
// role add/remove + Team Owners panel refresh + Madden ownership sync +
// pending-game-thread-owners-avatar check, instead of duplicating all of
// that a third time for the panel flow.
async function performCommissionerRoleAction(guild, league, targetUserId, roleId, action) {
  const targetMember = await guild.members.fetch(targetUserId).catch(() => null);
  const role = await guild.roles.fetch(roleId).catch(() => null);
  if (!targetMember || !role) return { ok: false, message: 'Could not find that member or role anymore.' };

  if (action === 'assign') await targetMember.roles.add(role).catch(() => null);
  else await targetMember.roles.remove(role).catch(() => null);

  const isTeamRole = await isRegisteredTeamRole(league, role.id);
  if (isTeamRole) {
    await updateTeamOwnersPanel(guild, league).catch(() => null);

    if (league?.league_id) {
      const newOwnerId = action === 'assign' ? targetUserId : null;
      await pool.query(
        `UPDATE madden_imported_team_stats SET owner_user_id = $3, imported_at = NOW()
         WHERE guild_id = $1 AND league_id::text = $2::text AND team_role_id = $4`,
        [guild.id, String(league.league_id), newOwnerId, role.id]
      ).catch(() => null);
      await pool.query(
        `UPDATE madden_franchises SET owner_user_id = $3, updated_at = NOW()
         WHERE guild_id = $1 AND league_id::text = $2::text AND team_role_id = $4`,
        [guild.id, String(league.league_id), newOwnerId, role.id]
      ).catch(() => null);

      if (newOwnerId) {
        const pendingGames = await pool.query(
          `SELECT * FROM madden_imported_games
           WHERE guild_id = $1 AND league_id::text = $2::text
             AND thread_id IS NOT NULL AND owners_avatar_posted = FALSE
             AND (away_team_role_id = $3 OR home_team_role_id = $3)`,
          [guild.id, String(league.league_id), role.id]
        ).catch(() => ({ rows: [] }));
        for (const pendingGame of pendingGames.rows) {
          await maybePostGameThreadOwnersAvatar(guild, league, pendingGame).catch(error =>
            console.error('[Game Thread Owners Avatar] post-role-action check failed:', error));
        }

        // 7J-GENERICAVATAR: same retroactive check as above, generic
        // (non-Madden) side — per Hxxdie, every UvU matchup thread should
        // get the avatar showcase, not just Madden's. isTeamRole is
        // already resolved generically above, so this runs for any league
        // type; league_games rows simply won't exist for a Madden league,
        // so this is a harmless no-op there.
        const pendingLeagueGames = await pool.query(
          `SELECT * FROM league_games
           WHERE guild_id = $1 AND league_id = $2
             AND thread_id IS NOT NULL AND owners_avatar_posted = FALSE
             AND (away_team_role_id = $3 OR home_team_role_id = $3)`,
          [guild.id, league.league_id, role.id]
        ).catch(() => ({ rows: [] }));
        for (const pendingGame of pendingLeagueGames.rows) {
          await maybePostLeagueGameThreadOwnersAvatar(guild, pendingGame).catch(error =>
            console.error('[Game Thread Owners Avatar] post-role-action check failed (generic):', error));
        }
      }
    }
  }

  return {
    ok: true,
    message: `${action === 'assign' ? 'Assigned' : 'Removed'} ${role} ${action === 'assign' ? 'to' : 'from'} ${targetMember}.`,
  };
}

async function updateTradeCountPanel(guild, league = null) {
  await updatePanel(guild, league, 'trade_count', await buildTradeCountEmbed(league));
}

async function getStandingsRows(guildId, leagueId) {
  const league = await getLeagueById(leagueId);
  const customSettings = league ? await ensureLeagueCustomSettings(league).catch(() => null) : null;
  const usesPoints = customSettings?.standings_system === 'points' || isMlbLeague(league);
  const usesDiff = customSettings?.standings_system === 'point_differential';
  const orderBy = usesPoints
    ? 'standings_points DESC, wins DESC, losses ASC, (points_for - points_against) DESC, team_name ASC'
    : usesDiff
      ? '(points_for - points_against) DESC, wins DESC, losses ASC, team_name ASC'
      : 'wins DESC, losses ASC, (points_for - points_against) DESC, team_name ASC';

  const result = await pool.query(
    `SELECT * FROM league_standings
     WHERE guild_id = $1 AND league_id = $2
     ORDER BY ${orderBy}`,
    [guildId, leagueId]
  );
  return result.rows;
}

// 7J-SPORTPLAYOFFFORMAT: per Hxxdie — every major league seeds its playoffs
// differently, and the generic conference/division/overall_record system
// below doesn't match any of them exactly. This classifies a league into a
// known real-world format so selectPlayoffTeamsForLeague and
// buildInitialPlayoffRound can each use the actual rules for that sport.
// Checked in a specific order since some game_key substrings overlap (e.g.
// 'football' could mean Madden/NFL or a generic label) — falls through to
// 'generic' (existing conference/division/overall_record behavior,
// untouched) for anything unrecognized. Real-world EPL has no playoff at
// all (the table itself decides the champion), so it intentionally has no
// dedicated case here — a league using this feature for a soccer league
// anyway gets the generic system, which is an optional add-on, not a claim
// that real EPL works this way.
function getPlayoffFormatKey(league) {
  if (isMlbLeague(league)) return 'mlb';
  if (isNhlLeague(league)) return 'nhl';
  if (isNbaLeague(league)) return 'nba';
  if (isMlsLeague(league)) return 'mls';
  if (isNflLeague(league) || isMaddenLeague(league)) return 'nfl';
  return 'generic';
}

// 7J-SEASONHISTORYV2: per Hxxdie — "Champion" should read as the real
// trophy name (Stanley Cup Champion, not just "Champion"). Suggested
// default per sport, overridable per-league via the Awards customization
// panel — commissioners running an unusual league setup aren't stuck with
// a suggestion that doesn't fit.
const DEFAULT_CHAMPIONSHIP_TROPHY_NAME = {
  nfl: 'Super Bowl Champion',
  nhl: 'Stanley Cup Champion',
  mlb: 'World Series Champion',
  nba: 'NBA Finals Champion',
  mls: 'MLS Cup Champion',
  generic: 'League Champion',
};
function getChampionshipTrophyName(league, customSettings) {
  return customSettings?.championship_trophy_name || DEFAULT_CHAMPIONSHIP_TROPHY_NAME[getPlayoffFormatKey(league)] || 'League Champion';
}

// 7J-SPORTPLAYOFFFORMAT: NFL — 7 per conference. The 4 division winners
// take seeds 1-4 (ranked among themselves by record), the next 3 best
// records in the conference (regardless of division) take seeds 5-7. Real
// rule, deliberately preserved even though it can feel odd: a wildcard
// team can never outrank a division winner in seeding no matter their
// record — matches confirmed against current-season sourcing.
async function selectNflPlayoffTeams(guildId, league, standingsRows) {
  const withMeta = await Promise.all(standingsRows.map(async team => {
    const { conference, division } = await getTeamConferenceDivisionForLeague(guildId, league.league_id, team.team_name, league).catch(() => ({}));
    return { ...team, resolvedConference: conference || 'Conference', resolvedDivision: division || 'Division' };
  }));
  const conferences = [...new Set(withMeta.map(t => t.resolvedConference))];
  const seeded = [];
  for (const conference of conferences) {
    // 7J-SEEDRANKFIX: per Hxxdie — standingsRows (and therefore inConf,
    // since filter preserves order) is already sorted by actual record.
    // Division winners MUST be seeded 1-4 by their OWN record relative to
    // each other — pulling them via `divisions.map(d => ...)` and seeding
    // in THAT order instead seeds them by whatever arbitrary order their
    // divisions happen to appear in this list, which has zero relationship
    // to who actually has the better record. Re-sorting by their position
    // in inConf (true rank order) before seeding fixes that; wildcards
    // were already fine since a plain filter() preserves relative order.
    const inConf = withMeta.filter(t => t.resolvedConference === conference);
    const divisions = [...new Set(inConf.map(t => t.resolvedDivision))];
    const divisionWinners = divisions.map(d => inConf.filter(t => t.resolvedDivision === d)[0]).filter(Boolean)
      .sort((a, b) => inConf.indexOf(a) - inConf.indexOf(b));
    const winnerNames = new Set(divisionWinners.map(t => t.team_name));
    const wildcards = inConf.filter(t => !winnerNames.has(t.team_name)).slice(0, 3);
    [...divisionWinners.slice(0, 4), ...wildcards].forEach((team, index) => {
      seeded.push({ ...team, seed: index + 1, conference, byeRound1: index === 0 });
    });
  }
  return seeded;
}

// 7J-MADDENPLAYOFFAUTOSTART: per Hxxdie — the playoff bracket panel had a
// channel and everything already auto-configured (see singleChannelSpecs'
// playoff_bracket_channel_id entry), but nothing ever actually built or
// posted a bracket for Madden leagues — autoPostPlayoffBracketPanel was
// only ever called from the manual "Start Playoffs" button, which is a
// structured-league flow Madden leagues have no reason to know exists.
// Same real seeding rule as selectNflPlayoffTeams (division winners 1-4 by
// within-conference record, next-3 records fill wildcards 5-7), sourced
// from madden_imported_team_stats since Madden leagues never populate
// league_standings (selectNflPlayoffTeams's normal data source — see the
// matching note on 7J-SEASONSCOPESTANDINGS/7J-PLAYOFFPICTURESEEDFIX for the
// same table-source distinction). Output shape matches selectNflPlayoffTeams
// exactly, so it drops straight into buildInitialPlayoffRound unchanged.
async function selectMaddenPlayoffTeams(guild, league) {
  const teamsResult = await pool.query(
    `SELECT team_name, wins, losses, ties, points_for, points_against FROM madden_imported_team_stats WHERE guild_id = $1 AND league_id::text = $2::text`,
    [guild.id, String(league.league_id)]
  ).catch(() => ({ rows: [] }));
  // 7J-H2HTIEBREAK: per Hxxdie — real NFL tie-breaking checks head-to-head
  // result BEFORE point differential; point-differential-only risked (and,
  // live, may have) landed on a different team than the real game actually
  // determined whenever head-to-head was the deciding factor. Pre-fetches
  // completed regular-season games into a lookup map so the sort
  // comparator (which must stay synchronous) can consult real head-to-head
  // results for any two tied teams. Still not the FULL real NFL tie-break
  // chain (division/conference record, common opponents, strength of
  // victory, etc. aren't implemented) — head-to-head is by far the most
  // common decider for the ordinary 2-team tie case, which covers the
  // large majority of real scenarios; anything head-to-head can't resolve
  // (no meeting, or a 3+-way tie it can't fully order) falls through to
  // point differential same as before.
  // 7J-BRACKETSEASONSCOPE: same missing-scope shape as
  // getMaddenPlayoffWeekGames below — madden_imported_games holds every
  // season's completed games forever, so an unscoped head-to-head lookup
  // could resolve a tie using a game from a prior season the two teams
  // played, rather than (or in addition to) any real meeting this season.
  // Lower-stakes than the matchup-pairing bug (this only feeds bye-team/
  // seed-label selection, never who plays whom), but the same real gap.
  const currentSeasonKeyForSeeding = await getMaddenCurrentSeasonKey(league).catch(() => null);
  const h2hGamesResult = await pool.query(
    `SELECT home_team, away_team, home_score, away_score, status
     FROM madden_imported_games
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND season_key = $3::text
       AND LOWER(COALESCE(status, '')) IN ('completed', 'final', 'completed_with_real_score', 'away_win', 'home_win', 'tie')`,
    [guild.id, String(league.league_id), currentSeasonKeyForSeeding]
  ).catch(() => ({ rows: [] }));
  const h2hWinner = new Map(); // key: "teamA|teamB" (lowercase, alpha-sorted) -> winning team name (lowercase)
  for (const g of h2hGamesResult.rows || []) {
    const home = String(g.home_team || '').toLowerCase();
    const away = String(g.away_team || '').toLowerCase();
    if (!home || !away) continue;
    const homeScore = Number(g.home_score) || 0;
    const awayScore = Number(g.away_score) || 0;
    let winner = null;
    if (homeScore > awayScore) winner = home;
    else if (awayScore > homeScore) winner = away;
    else {
      const s = String(g.status || '').toLowerCase();
      if (s === 'home_win') winner = home;
      else if (s === 'away_win') winner = away;
    }
    if (!winner) continue;
    // If these two teams played more than once, last write wins — a single
    // flag can't represent a split season series anyway, and a genuine
    // split falls through to point differential below regardless.
    h2hWinner.set([home, away].sort().join('|'), winner);
  }

  // 7J-SEEDTIEBREAKFIX: per Hxxdie — real bug that live-corrupted a bracket.
  // Multiple AFC teams were tied at 9-8 fighting for the last wildcard
  // spot; this sort had no tiebreaker beyond wins, which is identical for
  // tied teams, so the result silently fell back to whatever arbitrary
  // order Postgres happened to return rows in (no ORDER BY on the query
  // above) — non-deterministic, and could genuinely differ between two
  // separate computations of the same standings, which is exactly how the
  // bracket ended up seeding a different team than the playoff-picture
  // story reported as the real 7-seed. Added head-to-head (above) and
  // point differential as real tiebreakers (the latter matching the same
  // convention getStandingsRows already uses for structured-league
  // standings: wins, losses, point differential), plus team name as a
  // final deterministic fallback so this can never again depend on
  // incidental row order.
  const standingsRows = (teamsResult.rows || [])
    .map(t => {
      const gp = t.wins + t.losses + (t.ties || 0);
      return { ...t, pct: gp > 0 ? (t.wins + (t.ties || 0) * 0.5) / gp : 0, pointDiff: Number(t.points_for || 0) - Number(t.points_against || 0) };
    })
    .sort((a, b) => {
      if (b.pct !== a.pct) return b.pct - a.pct;
      if (b.wins !== a.wins) return b.wins - a.wins;
      const h2hKey = [a.team_name.toLowerCase(), b.team_name.toLowerCase()].sort().join('|');
      const h2hResult = h2hWinner.get(h2hKey);
      if (h2hResult === a.team_name.toLowerCase()) return -1;
      if (h2hResult === b.team_name.toLowerCase()) return 1;
      return b.pointDiff - a.pointDiff || a.team_name.localeCompare(b.team_name);
    });

  const withMeta = await Promise.all(standingsRows.map(async t => {
    const { conference, division } = await getTeamConferenceDivisionForLeague(guild.id, league.league_id, t.team_name, league).catch(() => ({}));
    return { ...t, resolvedConference: conference || 'Conference', resolvedDivision: division || 'Division' };
  }));
  const conferences = [...new Set(withMeta.map(t => t.resolvedConference))];
  const seeded = [];
  for (const conference of conferences) {
    const inConf = withMeta.filter(t => t.resolvedConference === conference);
    const divisions = [...new Set(inConf.map(t => t.resolvedDivision))];
    const divisionWinners = divisions.map(d => inConf.filter(t => t.resolvedDivision === d)[0]).filter(Boolean)
      .sort((a, b) => inConf.indexOf(a) - inConf.indexOf(b));
    const winnerNames = new Set(divisionWinners.map(t => t.team_name));
    const wildcards = inConf.filter(t => !winnerNames.has(t.team_name)).slice(0, 3);
    [...divisionWinners.slice(0, 4), ...wildcards].forEach((team, index) => {
      seeded.push({ ...team, seed: index + 1, conference, byeRound1: index === 0 });
    });
  }
  return seeded;
}

// 7J-REALBRACKETMATCHUPS: per Hxxdie — real insight: the regular weekly
// game-thread creation is trustworthy precisely because it READS EA's real
// synced schedule for the current week rather than trying to predict it.
// The bracket's matchups now work the same way. Building a round from
// selectMaddenPlayoffTeams' computed seeding required correctly guessing
// EA's internal tie-break rule for a close wildcard race — two separate
// attempts (non-deterministic sort, then point differential, then real
// head-to-head) all failed to reproduce it for a real 4-way 9-8 tie live.
// Reading the real matchup directly from madden_imported_games instead
// means the bracket can never disagree with what actually happened in the
// game, since it's the exact same ground-truth data source that already
// builds the (confirmed accurate) weekly game threads. Standings/seeding
// computation is used ONLY for two lower-risk things that don't determine
// who plays whom: identifying the bye team (the #1 seed is essentially
// never part of a close multi-way tie the way a 6/7 wildcard cutoff can
// be) and best-effort cosmetic seed LABELS for display.
async function getMaddenPlayoffWeekGames(guild, league, group, idx) {
  // 7J-BRACKETSEASONSCOPE: per Hxxdie — real bug, confirmed live at the end
  // of the Session 43 full-lifecycle test. madden_imported_games keeps
  // every season's rows forever (upsert key is (league_id,
  // external_game_id), never cleared), and this query had no season
  // filter at all — only guild_id/league_id, matched against week_label
  // via maddenWeekLabelSortKey. A prior season's "Super Bowl"-labeled game
  // between two completely unrelated teams was a valid candidate match
  // here the whole time, which is exactly what got picked live (bracket
  // posted a Super Bowl Preview matching neither the real prior season nor
  // the real current one). Same fix pattern as
  // createMaddenWeeklyGameThreadsCore/getMaddenSuperBowlResult
  // (7J-SEASONKEYALWAYS): scope by season_key, always populated, plain
  // equality, no "unfiltered if null" escape hatch.
  const currentSeasonKey = await getMaddenCurrentSeasonKey(league).catch(() => null);
  const gamesResult = await pool.query(
    `SELECT home_team, away_team, week_label
     FROM madden_imported_games
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND season_key = $3::text`,
    [guild.id, String(league.league_id), currentSeasonKey]
  ).catch(() => ({ rows: [] }));
  const matching = (gamesResult.rows || []).filter(g => {
    const [g2, i2] = maddenWeekLabelSortKey(g.week_label);
    return g2 === group && i2 === idx;
  });
  // Dedup by matchup (team-pair, order-independent) — a game can appear
  // more than once across syncs if EA re-exports it before it's played.
  const seen = new Set();
  const unique = [];
  for (const g of matching) {
    const key = [String(g.home_team).toLowerCase(), String(g.away_team).toLowerCase()].sort().join('|');
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(g);
  }
  return unique;
}

async function buildMaddenWildCardRoundFromRealGames(guild, league) {
  // Best-effort seed labels + bye-team identification only — never used to
  // determine matchups.
  const computedSeeding = await selectMaddenPlayoffTeams(guild, league).catch(() => []);
  const seedByTeamName = new Map(computedSeeding.map(t => [t.team_name.toLowerCase(), t.seed]));
  const byeTeams = computedSeeding.filter(t => t.byeRound1);

  const wildCardGames = await getMaddenPlayoffWeekGames(guild, league, 2, 0);
  const series = [];
  const gamesByConference = new Map();
  for (const g of wildCardGames) {
    const { conference } = await getTeamConferenceDivisionForLeague(guild.id, league.league_id, g.home_team, league).catch(() => ({}));
    const conf = conference || 'Conference';
    if (!gamesByConference.has(conf)) gamesByConference.set(conf, []);
    gamesByConference.get(conf).push(g);
  }

  for (const [conference, games] of gamesByConference) {
    const byeTeam = byeTeams.find(t => t.conference === conference);
    if (byeTeam) {
      series.push({ id: randomUUID(), teamA: { name: byeTeam.team_name, seed: 1 }, teamB: null, seriesLength: 1, winsA: 1, winsB: 0, winner: byeTeam.team_name, games: [], bye: true, conference });
    }
    for (const g of games) {
      series.push({
        id: randomUUID(),
        teamA: { name: g.home_team, seed: seedByTeamName.get(String(g.home_team).toLowerCase()) ?? null },
        teamB: { name: g.away_team, seed: seedByTeamName.get(String(g.away_team).toLowerCase()) ?? null },
        seriesLength: 1,
        winsA: 0,
        winsB: 0,
        winner: null,
        games: [],
        unlocksAt: null,
        disputed: false,
        conference,
      });
    }
  }
  return series;
}

// 7J-PROBOWLBRACKETGAP: real bug, confirmed live — the final round of a
// real bracket (Conference Championship -> Super Bowl) never built.
// maddenWeekLabelSortKey's real EA week-index space has FIVE values across
// the playoff stretch (Wild Card=0, Divisional=1, Conf. Championship=2,
// Pro Bowl=3, Super Bowl=4) because Pro Bowl — a real label, added in
// Session 43's stuck-loop fix — is a genuine all-star exhibition sitting
// between Conference Championship and Super Bowl, not a bracket round at
// all. The bracket's own round index only has FOUR values (0-3: Wild
// Card, Divisional, Conf. Championship, Super Bowl), and every call site
// below silently assumed those two index spaces were the same thing —
// correct for rounds 0-2 (which happen to line up 1:1), silently wrong
// starting exactly at the Conference Championship -> Super Bowl step,
// where EA's real Super Bowl index (4) is one past what the bracket's own
// indexing (3) asked for. That's index 3 in EA's space — Pro Bowl —
// which no franchise-team matchup will ever be found in, so the lookup
// came back empty every sync, indistinguishable from "EA hasn't exported
// it yet" (the case this code was actually built to wait out). Translates
// the bracket's own round index to the real EA week-label index at every
// site that queries madden_imported_games by round, instead of assuming
// they're interchangeable.
function maddenBracketRoundToWeekIdx(bracketRoundIndex) {
  return bracketRoundIndex >= 3 ? bracketRoundIndex + 1 : bracketRoundIndex;
}

// Rounds after Wild Card: same "read, don't predict" principle. Seed and
// conference are carried forward from whoever won each series in the
// previous round (real data, already confirmed by that round's own real
// results), and the actual pairing comes from EA's real synced schedule
// for the next round — never from a reseed formula guessing who plays whom.
async function buildMaddenNextRoundFromRealGames(guild, league, previousRound, nextRoundIdx) {
  const winnerInfo = new Map(); // lowercase team name -> { seed, conference }
  const conferenceOrder = []; // first-seen order, so this round's layout matches the previous round's
  for (const s of previousRound) {
    if (!s.winner) continue;
    const winnerTeam = s.teamA?.name === s.winner ? s.teamA : s.teamB;
    const conference = s.conference || null;
    winnerInfo.set(s.winner.toLowerCase(), { seed: winnerTeam?.seed ?? null, conference });
    if (conference && !conferenceOrder.includes(conference)) conferenceOrder.push(conference);
  }

  const roundGames = await getMaddenPlayoffWeekGames(guild, league, 2, nextRoundIdx);
  const builtSeries = [];
  for (const g of roundGames) {
    const homeInfo = winnerInfo.get(String(g.home_team).toLowerCase());
    const awayInfo = winnerInfo.get(String(g.away_team).toLowerCase());
    const conference = homeInfo?.conference && homeInfo.conference === awayInfo?.conference ? homeInfo.conference : null;
    builtSeries.push({
      id: randomUUID(),
      teamA: { name: g.home_team, seed: homeInfo?.seed ?? null },
      teamB: { name: g.away_team, seed: awayInfo?.seed ?? null },
      seriesLength: 1,
      winsA: 0,
      winsB: 0,
      winner: null,
      games: [],
      unlocksAt: null,
      disputed: false,
      conference,
    });
  }

  // 7J-BRACKETCONFORDER: per Hxxdie — real bug, confirmed live via
  // screenshot (matchups were correct, but the bracket image's connector
  // lines visually crossed between conferences). The PNG renderer
  // computes each round's vertical position as the average of its two
  // "parent" series in the previous round, purely by array index
  // (prev[i*2]/prev[i*2+1]) — that positional math only holds if this
  // round's series are grouped contiguously by conference, in the same
  // conference order the previous round used. Raw SQL-return order gave
  // no such guarantee. Grouping here (rather than at every render call
  // site) keeps the fix in the one place responsible for building this
  // data, matching where buildMaddenWildCardRoundFromRealGames already
  // does the same grouping for Round 1.
  const series = [];
  for (const conference of conferenceOrder) {
    series.push(...builtSeries.filter(s => s.conference === conference));
  }
  // Anything that didn't match a known conference (shouldn't happen in
  // practice) still gets included, just appended at the end rather than
  // silently dropped.
  series.push(...builtSeries.filter(s => !conferenceOrder.includes(s.conference)));
  return series;
}

// 7J-SPORTPLAYOFFFORMAT: NHL — top 3 per division (2 divisions per
// conference) auto-qualify (6 of 8 spots), plus the next 2 best conference
// records outside those top-3s fill the wildcard spots.
// 7J-SEEDRANKFIX: the displayed/returned .seed is the team's TRUE overall
// rank among all 8 conference qualifiers by actual record — NOT the order
// they get visited in while building division-then-wildcard groups
// internally (that grouping order is what qualifyType/divisionRank/
// wildcardRank exist for, and buildInitialPlayoffRound's NHL branch uses
// exactly those fields for pairing, never .seed). Conflating the two used
// to make a team's displayed seed jump around based on which division
// group it happened to be gathered from, completely disconnected from the
// Standings panel sitting right next to it.
async function selectNhlPlayoffTeams(guildId, league, standingsRows) {
  const withMeta = await Promise.all(standingsRows.map(async team => {
    const { conference, division } = await getTeamConferenceDivisionForLeague(guildId, league.league_id, team.team_name, league).catch(() => ({}));
    return { ...team, resolvedConference: conference || 'Conference', resolvedDivision: division || 'Division' };
  }));
  const conferences = [...new Set(withMeta.map(t => t.resolvedConference))];
  const seeded = [];
  for (const conference of conferences) {
    const inConf = withMeta.filter(t => t.resolvedConference === conference);
    const divisions = [...new Set(inConf.map(t => t.resolvedDivision))].slice(0, 2);
    const divisionTop3 = divisions.map(d => inConf.filter(t => t.resolvedDivision === d).slice(0, 3));
    const autoQualifiers = divisionTop3.flat();
    const autoNames = new Set(autoQualifiers.map(t => t.team_name));
    const wildcards = inConf.filter(t => !autoNames.has(t.team_name)).slice(0, 2);

    const trueSeedByName = new Map(
      [...autoQualifiers, ...wildcards]
        .sort((a, b) => inConf.indexOf(a) - inConf.indexOf(b))
        .map((t, i) => [t.team_name, i + 1])
    );

    divisionTop3.forEach((teams, divIndex) => {
      teams.forEach((team, i) => seeded.push({ ...team, seed: trueSeedByName.get(team.team_name), conference, division: divisions[divIndex], qualifyType: i === 0 ? 'division-leader' : 'division-rank', divisionRank: i + 1 }));
    });
    wildcards.forEach((team, i) => seeded.push({ ...team, seed: trueSeedByName.get(team.team_name), conference, qualifyType: 'wildcard', wildcardRank: i + 1 }));
  }
  return seeded;
}

// 7J-SPORTPLAYOFFFORMAT: MLB — 3 division winners per league take seeds
// 1-3 (ranked among themselves by record), next 3 best records
// (regardless of division) take seeds 4-6. Seeds 1-2 get a bye straight to
// the Division Series; the Wild Card round is 3v6, 4v5.
async function selectMlbPlayoffTeams(guildId, league, standingsRows) {
  const withMeta = await Promise.all(standingsRows.map(async team => {
    const { conference, division } = await getTeamConferenceDivisionForLeague(guildId, league.league_id, team.team_name, league).catch(() => ({}));
    return { ...team, resolvedConference: conference || 'League', resolvedDivision: division || 'Division' };
  }));
  const conferences = [...new Set(withMeta.map(t => t.resolvedConference))];
  const seeded = [];
  for (const conference of conferences) {
    // 7J-SEEDRANKFIX: same fix as NFL above — division winners re-sorted by
    // their own position in inConf (true record order) before seeding.
    const inConf = withMeta.filter(t => t.resolvedConference === conference);
    const divisions = [...new Set(inConf.map(t => t.resolvedDivision))];
    const divisionWinners = divisions.map(d => inConf.filter(t => t.resolvedDivision === d)[0]).filter(Boolean)
      .sort((a, b) => inConf.indexOf(a) - inConf.indexOf(b));
    const winnerNames = new Set(divisionWinners.map(t => t.team_name));
    const wildcards = inConf.filter(t => !winnerNames.has(t.team_name)).slice(0, 3);
    [...divisionWinners.slice(0, 3), ...wildcards].forEach((team, index) => {
      seeded.push({ ...team, seed: index + 1, conference, byeRound1: index < 2 });
    });
  }
  return seeded;
}

// 7J-SPORTPLAYOFFFORMAT: NBA/MLS both run a real play-in/wild-card
// mini-tournament before their main bracket (NBA: 7-8-9-10 double-elim
// mini-bracket; MLS: single-elimination 8-vs-9 game) — genuinely separate
// features from bracket seeding itself, not built here. This approximates
// both as straight top-N by conference record, which gets seeds 1-6/7
// exactly right but doesn't model the play-in games themselves for the
// final spot(s). Flagged clearly wherever this is surfaced to a
// commissioner.
async function selectTopRecordPlayoffTeams(guildId, league, standingsRows, teamCount) {
  const withConference = await Promise.all(standingsRows.map(async team => {
    const { conference } = await getTeamConferenceDivisionForLeague(guildId, league.league_id, team.team_name, league).catch(() => ({}));
    return { ...team, resolvedConference: conference || 'Conference' };
  }));
  const conferences = [...new Set(withConference.map(t => t.resolvedConference))];
  const seeded = [];
  for (const conference of conferences) {
    const inConf = withConference.filter(t => t.resolvedConference === conference).slice(0, teamCount);
    inConf.forEach((team, index) => seeded.push({ ...team, seed: index + 1, conference }));
  }
  return seeded;
}

async function selectPlayoffTeamsForLeague(guildId, league) {
  const standingsRows = await getStandingsRows(guildId, league.league_id);
  const formatKey = getPlayoffFormatKey(league);

  if (formatKey === 'nfl') return selectNflPlayoffTeams(guildId, league, standingsRows);
  if (formatKey === 'nhl') return selectNhlPlayoffTeams(guildId, league, standingsRows);
  if (formatKey === 'mlb') return selectMlbPlayoffTeams(guildId, league, standingsRows);
  if (formatKey === 'nba') return selectTopRecordPlayoffTeams(guildId, league, standingsRows, 8);
  if (formatKey === 'mls') return selectTopRecordPlayoffTeams(guildId, league, standingsRows, 8);

  // 7J-SPORTPLAYOFFFORMAT: unrecognized sport (includes soccer/EPL-style
  // leagues, which have no real-world playoff at all) — untouched original
  // generic behavior, driven by the league's own playoff_seeding_method
  // setting rather than a hardcoded real-world format.
  const customSettings = await ensureLeagueCustomSettings(league).catch(() => null);
  const seedingMethod = customSettings?.playoff_seeding_method || 'overall_record';
  const teamCount = Number(league.playoff_team_count || 8);

  if (seedingMethod === 'conference') {
    const withConference = await Promise.all(standingsRows.map(async team => {
      const { conference } = await getTeamConferenceDivisionForLeague(guildId, league.league_id, team.team_name, league);
      return { ...team, resolvedConference: conference || 'Unassigned Conference' };
    }));
    const conferences = [...new Set(withConference.map(t => t.resolvedConference).filter(c => c && c !== 'Unassigned Conference'))];
    const perConference = Math.max(1, Math.floor(teamCount / Math.max(1, conferences.length || 2)));
    const seeded = [];
    for (const conference of conferences.length ? conferences : ['Eastern Conference', 'Western Conference']) {
      const teamsInConference = withConference.filter(t => t.resolvedConference === conference).slice(0, perConference);
      teamsInConference.forEach((team, index) => seeded.push({ ...team, seed: index + 1, conference }));
    }
    const unassigned = withConference
      .filter(t => t.resolvedConference === 'Unassigned Conference')
      .slice(0, Math.max(0, teamCount - seeded.length))
      .map((team, index) => ({ ...team, seed: seeded.length + index + 1, conference: 'Unassigned Conference' }));
    return [...seeded, ...unassigned].slice(0, teamCount);
  }

  if (seedingMethod === 'division') {
    const withDivision = await Promise.all(standingsRows.map(async team => {
      const { division } = await getTeamConferenceDivisionForLeague(guildId, league.league_id, team.team_name, league);
      return { ...team, resolvedDivision: division || 'Unassigned Division' };
    }));
    const divisions = [...new Set(withDivision.map(t => t.resolvedDivision).filter(d => d && d !== 'Unassigned Division'))];
    if (!divisions.length) {
      return standingsRows.slice(0, teamCount).map((team, index) => ({ ...team, seed: index + 1 }));
    }
    const divisionLeaders = divisions
      .map(division => withDivision.filter(t => t.resolvedDivision === division)[0])
      .filter(Boolean);
    const remaining = withDivision
      .filter(t => !divisionLeaders.some(leader => leader.team_name === t.team_name))
      .slice(0, Math.max(0, teamCount - divisionLeaders.length));
    return [...divisionLeaders, ...remaining].slice(0, teamCount).map((team, index) => ({ ...team, seed: index + 1, division: team.resolvedDivision }));
  }

  // overall_record (default)
  const withOverallConference = await Promise.all(standingsRows.slice(0, teamCount).map(async (team, index) => {
    const { conference } = await getTeamConferenceDivisionForLeague(guildId, league.league_id, team.team_name, league).catch(() => ({ conference: null }));
    return { ...team, seed: index + 1, conference };
  }));
  return withOverallConference;
}

async function updateStandingsPanel(guild, league) {
  if (!guild || !league?.league_id) return;
  const rows = await getStandingsRows(guild.id, league.league_id);
  const embed = await buildStandingsEmbed(league, rows);
  // 7J-MULTISPORTLOGO-EVERYWHERE: per Hxxdie — logos "anywhere a team name
  // is mentioned." Standings order (rows) is already the correct order for
  // the logo strip, so no re-sorting needed here.
  const files = [];
  const logoGroups = await getStandingsLogoGroups(guild.id, league, rows).catch(() => null);
  const logoPng = await renderTeamLogoStripPng(league, rows.map(r => r.team_name), logoGroups ? { groups: logoGroups } : {}).catch(error => {
    console.error('[7J-MULTISPORTLOGO-EVERYWHERE] Standings logo strip render failed:', error?.message || error);
    return null;
  });
  if (logoPng) {
    files.push(new AttachmentBuilder(logoPng, { name: 'standings-logos.png' }));
    embed.setImage('attachment://standings-logos.png');
  }
  await updatePanel(guild, league, 'standings', embed, [], files);
}

// 7J-135GENERICNEWS: Power Rankings for non-Madden leagues — Madden's
// version (madden_power_rankings) is entirely EA-sync-driven (roster
// ratings, team stats from imported data); non-Madden leagues have none of
// that. This computes a power score purely from what a non-Madden league
// DOES have — league_standings — weighted heavily toward actual record
// (standings_points, which already accounts for whatever win/loss/tie/OTL
// point system this league uses) with point differential as a tiebreaker/
// secondary factor, so it reads as a real ranking rather than just a copy
// of the standings order. Movement arrows (▲▼NEW) mirror the Madden
// version's UX, computed against each team's own previous rank.
function buildLeaguePowerRankingsEmbed(league, rows) {
  const NL = String.fromCharCode(10);
  const lines = rows.map((r, i) => {
    const rank = i + 1;
    let movement = '🆕 NEW';
    if (r.previous_rank !== null && r.previous_rank !== undefined) {
      if (r.previous_rank > rank) movement = `▲ ${r.previous_rank - rank}`;
      else if (r.previous_rank < rank) movement = `▼ ${rank - r.previous_rank}`;
      else movement = '—';
    }
    return `**${rank}. ${r.team_name}** ${movement}`;
  });
  return new EmbedBuilder()
    .setTitle(`📊 ${league.league_name} • Power Rankings`)
    .setColor(0x5865F2)
    .setDescription(lines.join(NL) || 'No games played yet this season.')
    .setFooter({ text: 'GG Sports • Power Rankings • Based on record and point differential' })
    .setTimestamp();
}

// 7J-135GENERICNEWS: shared by computeAndPostLeaguePowerRankings (refresh —
// called after every reported game) and the league_power_rankings_panel
// branch below (initial post, which needs a brand-new message rather than
// editing one that doesn't exist yet) — this half just does the DB
// compute/upsert and hands back the ranked rows; each caller decides how to
// actually get them on screen.
// 7J-136NEWSEVENTS: win-streak/losing-skid detection — league_standings is
// a rolled-up aggregate (total wins/losses), not sequential, so streaks
// have to be computed from actual game history instead. Pulls each team's
// last 10 FINAL league_games (most recent first) and counts a run of
// identical outcomes from the front; stops at the first game that breaks
// the run (or a tie, which breaks both win and loss streaks). Ties in the
// game itself aren't a "streak" of anything, so the very first game in the
// window being a tie returns length 0.
async function getTeamResultStreak(guildId, leagueId, teamRoleId) {
  const result = await pool.query(
    `SELECT home_team_role_id, away_team_role_id, winner_team_role_id, home_score, away_score
     FROM league_games
     WHERE guild_id = $1 AND league_id = $2 AND status = 'final' AND archived_at IS NULL
       AND (home_team_role_id = $3 OR away_team_role_id = $3)
     ORDER BY updated_at DESC
     LIMIT 10`,
    [guildId, leagueId, teamRoleId]
  ).catch(() => ({ rows: [] }));

  if (!result.rows.length) return { type: null, length: 0 };

  const isTieRow = row => row.winner_team_role_id === null && row.home_score !== null && row.away_score !== null && row.home_score === row.away_score;
  const firstType = isTieRow(result.rows[0]) ? null : (result.rows[0].winner_team_role_id === teamRoleId ? 'win' : 'loss');
  if (!firstType) return { type: null, length: 0 };

  let length = 0;
  for (const row of result.rows) {
    if (isTieRow(row)) break;
    const rowType = row.winner_team_role_id === teamRoleId ? 'win' : 'loss';
    if (rowType !== firstType) break;
    length++;
  }
  return { type: firstType, length };
}

// 7J-NEWSVARIETY: same logic as getTeamResultStreak, but excludes the game
// that was just reported — used to check what a team's streak looked like
// going INTO their latest result, so a win right after a real losing skid
// (or a loss right after a perfect run) can be recognized as its own story,
// distinct from the plain per-game result and the "riding a streak"
// milestone posts.
async function getPriorTeamResultStreak(guildId, leagueId, teamRoleId, excludeGameId) {
  const result = await pool.query(
    `SELECT home_team_role_id, away_team_role_id, winner_team_role_id, home_score, away_score
     FROM league_games
     WHERE guild_id = $1 AND league_id = $2 AND status = 'final' AND id != $4 AND archived_at IS NULL
       AND (home_team_role_id = $3 OR away_team_role_id = $3)
     ORDER BY updated_at DESC
     LIMIT 10`,
    [guildId, leagueId, teamRoleId, excludeGameId]
  ).catch(() => ({ rows: [] }));

  if (!result.rows.length) return { type: null, length: 0 };

  const isTieRow = row => row.winner_team_role_id === null && row.home_score !== null && row.away_score !== null && row.home_score === row.away_score;
  const firstType = isTieRow(result.rows[0]) ? null : (result.rows[0].winner_team_role_id === teamRoleId ? 'win' : 'loss');
  if (!firstType) return { type: null, length: 0 };

  let length = 0;
  for (const row of result.rows) {
    if (isTieRow(row)) break;
    const rowType = row.winner_team_role_id === teamRoleId ? 'win' : 'loss';
    if (rowType !== firstType) break;
    length++;
  }
  return { type: firstType, length };
}

async function computeLeaguePowerRankingRows(guild, league) {
  const standingsResult = await pool.query(
    `SELECT * FROM league_standings WHERE guild_id = $1 AND league_id = $2`,
    [guild.id, league.league_id]
  ).catch(() => ({ rows: [] }));
  if (!standingsResult.rows.length) return [];

  const previousResult = await pool.query(
    `SELECT team_role_id, rank FROM league_power_rankings WHERE guild_id = $1 AND league_id = $2`,
    [guild.id, league.league_id]
  ).catch(() => ({ rows: [] }));
  const previousRankByRole = new Map(previousResult.rows.map(r => [r.team_role_id, r.rank]));

  const ranked = standingsResult.rows
    .map(r => ({
      team_role_id: r.team_role_id,
      team_name: r.team_name,
      power_score: Number(r.standings_points || 0) * 100 + (Number(r.points_for || 0) - Number(r.points_against || 0)),
      previous_rank: previousRankByRole.has(r.team_role_id) ? previousRankByRole.get(r.team_role_id) : null,
    }))
    .sort((a, b) => b.power_score - a.power_score);

  for (let i = 0; i < ranked.length; i++) {
    const row = ranked[i];
    await pool.query(
      `INSERT INTO league_power_rankings (guild_id, league_id, team_role_id, team_name, rank, previous_rank, power_score, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())
       ON CONFLICT (guild_id, league_id, team_role_id) DO UPDATE SET
         team_name = $4, previous_rank = league_power_rankings.rank, rank = $5, power_score = $7, updated_at = NOW()`,
      [guild.id, league.league_id, row.team_role_id, row.team_name, i + 1, row.previous_rank, row.power_score]
    ).catch(() => null);
  }
  return ranked;
}

async function computeAndPostLeaguePowerRankings(guild, league) {
  if (!guild || !league?.league_id) return;
  const ranked = await computeLeaguePowerRankingRows(guild, league);
  if (!ranked.length) return;
  const embed = buildLeaguePowerRankingsEmbed(league, ranked);
  // 7J-MULTISPORTLOGO-EVERYWHERE: ranked is already in power-ranking order.
  const files = [];
  const logoPng = await renderTeamLogoStripPng(league, ranked.map(r => r.team_name)).catch(error => {
    console.error('[7J-MULTISPORTLOGO-EVERYWHERE] Power rankings logo strip render failed:', error?.message || error);
    return null;
  });
  if (logoPng) {
    files.push(new AttachmentBuilder(logoPng, { name: 'power-rankings-logos.png' }));
    embed.setImage('attachment://power-rankings-logos.png');
  }
  await updatePanel(guild, league, 'league_power_rankings', embed, [], files);
}

// 7J-STRUCTUREDPRBATCH: per Hxxdie — structured leagues were recomputing
// Power Rankings (and firing "climbs to #1" movers news) after EVERY
// individual game report within a round, not once per round. Since
// computeLeaguePowerRankingRows diffs against whatever it last stored as
// previous_rank — i.e. the immediately-prior computation, not the state as
// of the last Advance — several games reported back-to-back within the same
// round could each nudge the standings and cascade through #1 in sequence:
// three different teams all "climbing to #1" the same week, none of it
// technically wrong, just misleadingly granular. Real power rankings are a
// weekly snapshot, not a live-updating leaderboard mid-round. This computes
// exactly once per round, called from the Advance flow after that round's
// games are locked in, comparing against rank as of the PREVIOUS Advance.
// Open-schedule leagues have no such round boundary at all and explicitly
// keep the existing per-game behavior — not touched here, per Hxxdie.
async function computeAndPostStructuredRoundPowerRankings(guild, league) {
  if (!guild || !league?.league_id) return;
  const rankedRows = await computeLeaguePowerRankingRows(guild, league);
  if (!rankedRows.length) return;

  const embed = buildLeaguePowerRankingsEmbed(league, rankedRows);
  const files = [];
  const logoPng = await renderTeamLogoStripPng(league, rankedRows.map(r => r.team_name)).catch(error => {
    console.error('[7J-MULTISPORTLOGO-EVERYWHERE] Power rankings logo strip render failed:', error?.message || error);
    return null;
  });
  if (logoPng) {
    files.push(new AttachmentBuilder(logoPng, { name: 'power-rankings-logos.png' }));
    embed.setImage('attachment://power-rankings-logos.png');
  }
  await updatePanel(guild, league, 'league_power_rankings', embed, [], files);

  for (const row of rankedRows) {
    const newRank = rankedRows.indexOf(row) + 1;
    if (row.previous_rank === null || row.previous_rank === undefined) continue;
    const delta = row.previous_rank - newRank;
    if (delta >= 3 || (newRank === 1 && row.previous_rank !== 1)) {
      await generateAndPostLeagueNewsEvent(guild, league, 'power_ranking_movers', {
        team: row.team_name, direction: 'up', oldRank: row.previous_rank, newRank,
      }).catch(() => null);
    } else if (delta <= -3) {
      await generateAndPostLeagueNewsEvent(guild, league, 'power_ranking_movers', {
        team: row.team_name, direction: 'down', oldRank: row.previous_rank, newRank,
      }).catch(() => null);
    }
  }
}

// 7J-136NEWSEVENTS: per Hxxdie — "feed the news system with all the same
// information Madden gets, minus sync data, using generic events off the
// same kinds of triggers: trade rumors, power ranking movement, win
// streaks/losing skids, official trade reporting, award winners, league
// champions." Generalized generateAndPostLeagueGameNews (was game-result-
// only) into one function covering all of these — each eventType gets its
// own system prompt (so the tone fits the news, not a generic reskin) and
// its own plain-text fallback template if the Claude API call fails or
// league_news_enabled is off. Every trigger below is best-effort
// (.catch(() => null) at the call site) and silently no-ops if the league
// hasn't configured a News channel — same pattern as every other optional
// board in this bot.
async function generateAndPostLeagueNewsEvent(guild, league, eventType, context) {
  if (!league?.league_news_channel_id) return;
  const newsChannel = await guild.channels.fetch(league.league_news_channel_id).catch(() => null);
  if (!newsChannel?.isTextBased?.()) return;

  const customSettings = await ensureLeagueCustomSettings(league).catch(() => ({}));
  const useClaudeApi = customSettings.league_news_enabled !== false;

  const EVENT_PROMPTS = {
    game_result: `Write one punchy headline (under 80 chars) and one blurb (1-2 sentences, under 150 chars) recapping this single game result. Vary tone based on the margin — a blowout reads differently than a nail-biter or a tie.`,
    win_streak: `Write a headline and blurb about a team riding a real winning streak. Frame it with real momentum/confidence energy — this team is rolling.`,
    losing_skid: `Write a headline and blurb about a team on a real losing streak. Frame it with genuine concern/pressure — fans losing patience, questions being asked — without inventing specifics not given.`,
    power_ranking_movers: `Write a headline and blurb about a team making a big jump (or a big fall) in this week's Power Rankings. Frame climbers with hype/momentum energy, and fallers with concern/"what's going wrong" energy.`,
    // 7J-139NEGOTIATIONRUMOR: trade_rumor now fires when two teams actually
    // START negotiating (a real thread, real interest between two real
    // owners) — trade_block_listing below covers just being put on the
    // block, a separate and less significant event.
    trade_rumor: `Write a headline and blurb about two teams entering trade talks. Frame it as breaking trade-rumor news — "discussions are underway," "the two sides are talking" — genuine rumor-mill energy, not a finalized trade.`,
    trade_block_listing: `Write a headline and blurb about a player just being put on the trade block. Frame it as "on the block," "gauging interest" — lower-key than an actual rumor of talks between two teams.`,
    trade_official: `Write a headline and blurb reporting a trade that has just been OFFICIALLY approved between two teams. This is a real, finalized trade — write it with the weight of a real trade-reaction piece, not a rumor.`,
    award_winner: `Write a headline and blurb celebrating a player who just won a league award. Genuine, celebratory tone — this is a real accomplishment.`,
    league_champion: `Write a headline and blurb crowning this season's league champion. This is the biggest story of the season — write it with real weight and celebration.`,
    // 7J-NEWSVARIETY: three new event types, per Hxxdie's call that the
    // News feed felt repetitive with only game_result/streaks/power-ranking
    // movers in rotation all season. All three reuse data already tracked
    // (league_games results, league_standings win totals) — no new schema.
    bounce_back_win: `Write a headline and blurb about a team snapping a real losing streak with this win — or, if they'd been winless all season, finally breaking through for their first win. Genuine feel-good redemption-story energy, warm and triumphant — the opposite of the concern/pressure framing used for a losing skid.`,
    unbeaten_streak_ends: `Write a headline and blurb about a team's perfect, undefeated season coming to an end with this loss. Frame it as a real "the streak is over" moment — genuine surprise/weight, not just a routine loss recap.`,
    win_milestone: `Write a headline and blurb marking a team reaching a real win-total milestone this season. Treat it as a genuine "state of the season" accomplishment, not just another game result.`,
  };
  const promptInstruction = EVENT_PROMPTS[eventType];
  if (!promptInstruction) return;

  let headline = null;
  let blurb = null;

  if (useClaudeApi) {
    try {
      const parsed = await callClaudeNewsApi(
        `You are a sports journalist covering a fan-run online league called "${league.league_name}". ${promptInstruction} Sound like a real beat writer, not a bot. Never invent facts not present in the data given. Return ONLY valid JSON: {"headline": "...", "blurb": "..."}. No markdown, no preamble.`,
        JSON.stringify({ leagueName: league.league_name, ...context }),
        300
      );
      if (parsed?.headline) { headline = parsed.headline; blurb = parsed.blurb || ''; }
    } catch (err) {
      console.warn(`[LEAGUE NEWS] Claude API failed for ${eventType}, falling back to template:`, err?.message);
    }
  }

  if (!headline) {
    const fallback = buildLeagueNewsFallbackTemplate(eventType, context);
    if (!fallback) return;
    headline = fallback.headline;
    blurb = fallback.blurb;
  }

  const embed = new EmbedBuilder()
    .setTitle(`📰 ${headline}`)
    .setColor(0x5865F2)
    .setDescription(blurb || '')
    .setFooter({ text: 'GG Sports • League News' })
    .setTimestamp();
  // 7J-MULTISPORTLOGO-EVERYWHERE: per Hxxdie — news posts are usually
  // "about" one specific team, so a thumbnail (not a multi-team composite)
  // is the right fit here, same reasoning as the game thread embeds.
  // Context shape varies by event type, so this checks every field name
  // that could plausibly hold the primary team across all the EVENT_PROMPTS
  // types above, in priority order — silently omitted if none resolve to a
  // team this league's sport has logo coverage for.
  const primaryTeamName = context.winner || context.team || context.champion || context.homeTeam || context.awayTeam || null;
  const newsLogoUrl = primaryTeamName ? getGenericTeamLogoUrl(primaryTeamName, league) : null;
  if (newsLogoUrl) embed.setThumbnail(newsLogoUrl);
  await newsChannel.send({ embeds: [embed] }).catch(() => null);
}

// 7J-136NEWSEVENTS: plain-text fallback for every event type above — used
// whenever the Claude API call fails or is disabled, so News never just
// silently produces nothing.
function buildLeagueNewsFallbackTemplate(eventType, context) {
  switch (eventType) {
    case 'game_result': {
      const { homeTeam, awayTeam, homeScore, awayScore, isTie, winner, loser, margin } = context;
      return isTie
        ? { headline: `${awayTeam} and ${homeTeam} play to a draw`, blurb: 'Neither side could find the separator.' }
        : { headline: `${winner} defeats ${loser} ${Math.max(homeScore, awayScore)}-${Math.min(homeScore, awayScore)}`, blurb: margin >= 3 ? `${winner} pulled away for the win.` : `${winner} held on in a close one.` };
    }
    case 'win_streak':
      return { headline: `${context.team} riding a ${context.streakLength}-game winning streak`, blurb: `${context.team} has won ${context.streakLength} straight.` };
    case 'losing_skid':
      return { headline: `${context.team} has dropped ${context.streakLength} in a row`, blurb: `${context.team} is looking for answers after a ${context.streakLength}-game slide.` };
    case 'power_ranking_movers':
      return { headline: context.direction === 'up'
        ? `${context.team} climbs to #${context.newRank} in Power Rankings`
        : `${context.team} slides to #${context.newRank} in Power Rankings`,
        blurb: `Moved from #${context.oldRank} to #${context.newRank} this week.` };
    case 'trade_rumor':
      return { headline: `${context.teamA} and ${context.teamB} talking trade`, blurb: `The two sides have opened trade discussions.` };
    case 'trade_block_listing':
      return { headline: `${context.playerName} hits the trade block`, blurb: `${context.teamName || 'A team'} is gauging interest in ${context.playerName}.` };
    case 'trade_official':
      return { headline: `Trade official: ${context.teamA} ↔ ${context.teamB}`, blurb: 'The deal has been approved by the trade committee.' };
    case 'award_winner':
      return { headline: `${context.playerName} wins ${context.awardName}`, blurb: `${context.playerName} takes home the ${context.awardName} for ${context.leagueName}.` };
    case 'league_champion':
      return { headline: `${context.championTeam} are your league champions!`, blurb: `${context.championTeam} closed out the season on top.` };
    case 'bounce_back_win':
      return context.snappedStreakLength
        ? { headline: `${context.team} snaps a ${context.snappedStreakLength}-game skid`, blurb: `${context.team} finally got back in the win column.` }
        : { headline: `${context.team} picks up their first win of the season`, blurb: `${context.team} breaks through after a winless start.` };
    case 'unbeaten_streak_ends':
      return { headline: `${context.team}'s perfect season is over`, blurb: `${context.team} drops their first game after starting ${context.priorWins}-0.` };
    case 'win_milestone':
      return { headline: `${context.team} reaches ${context.winCount} wins`, blurb: `${context.team} hits the ${context.winCount}-win mark this season.` };
    default:
      return null;
  }
}

// guildId is kept as a parameter purely so per-server payout rates (win/game-played/
// award) can still be read — the currency identity itself (name/icon) is fixed globally
// (adjustable via /botowner currencyidentity) and balances live in the global
// user_currency_balances table (see getBalance).
async function getCurrencySettings(guildId) {
  await pool.query(
    `INSERT INTO guild_currency_settings (guild_id)
     VALUES ($1)
     ON CONFLICT (guild_id) DO NOTHING`,
    [guildId]
  );

  const result = await pool.query(
    `SELECT win_payout, game_played_payout, award_payout FROM guild_currency_settings WHERE guild_id = $1`,
    [guildId]
  );

  const row = result.rows[0] || { win_payout: 100, game_played_payout: 25, award_payout: 50 };

  return {
    currency_name: currencyConfigCache.currency_name,
    currency_icon: currencyConfigCache.currency_icon,
    win_payout: clampPayoutRate('win_payout', row.win_payout),
    game_played_payout: clampPayoutRate('game_played_payout', row.game_played_payout),
    award_payout: clampPayoutRate('award_payout', row.award_payout),
  };
}

const SUPPORTED_LANGUAGES = [
  { value: 'en', label: 'English', emoji: '🇺🇸' },
  { value: 'es', label: 'Español', emoji: '🇪🇸' },
  { value: 'fr', label: 'Français', emoji: '🇫🇷' },
  { value: 'de', label: 'Deutsch', emoji: '🇩🇪' },
  { value: 'pt', label: 'Português', emoji: '🇵🇹' },
  { value: 'ja', label: '日本語', emoji: '🇯🇵' },
  { value: 'ko', label: '한국어', emoji: '🇰🇷' },
  { value: 'zh-TW', label: '繁體中文', emoji: '🇹🇼' },
];

// Server-wide language + onboarding-DM preference. Lazily creates the guilds row if
// one doesn't exist yet (mirrors getCurrencySettings' upsert-then-select pattern) —
// guilds are otherwise only inserted at league-create time, so a server that opens
// admin settings before creating a league still needs somewhere to write to.
async function getGuildSettings(guildId, guildName = null) {
  await pool.query(
    `INSERT INTO guilds (guild_id, guild_name) VALUES ($1, $2) ON CONFLICT (guild_id) DO NOTHING`,
    [guildId, guildName || guildId]
  );
  const result = await pool.query(`SELECT language, onboarding_enabled, welcome_leave_enabled, welcome_channel_id, leave_channel_id, ticket_channel_id, support_channel_id, ticket_admin_role_id FROM guilds WHERE guild_id = $1`, [guildId]);
  const row = result.rows[0] || { language: 'en', onboarding_enabled: true, welcome_leave_enabled: false, welcome_channel_id: null, leave_channel_id: null, ticket_channel_id: null, support_channel_id: null, ticket_admin_role_id: null };
  return {
    language: SUPPORTED_LANGUAGES.some(l => l.value === row.language) ? row.language : 'en',
    onboarding_enabled: row.onboarding_enabled !== false,
    welcome_leave_enabled: row.welcome_leave_enabled === true,
    welcome_channel_id: row.welcome_channel_id || null,
    leave_channel_id: row.leave_channel_id || null,
    // 7J-111TICKETSCOPE: guild-wide Tickets/Support channels + the optional
    // admin-notify role for tickets that aren't tied to a specific league.
    ticket_channel_id: row.ticket_channel_id || null,
    support_channel_id: row.support_channel_id || null,
    ticket_admin_role_id: row.ticket_admin_role_id || null,
  };
}

async function setGuildTicketSettings(guildId, guildName, { ticketChannelId, supportChannelId, ticketAdminRoleId } = {}) {
  await getGuildSettings(guildId, guildName); // ensure row exists
  const updates = [];
  const params = [guildId];
  if (ticketChannelId !== undefined) { params.push(ticketChannelId); updates.push(`ticket_channel_id = $${params.length}`); }
  if (supportChannelId !== undefined) { params.push(supportChannelId); updates.push(`support_channel_id = $${params.length}`); }
  if (ticketAdminRoleId !== undefined) { params.push(ticketAdminRoleId); updates.push(`ticket_admin_role_id = $${params.length}`); }
  if (!updates.length) return;
  await pool.query(`UPDATE guilds SET ${updates.join(', ')} WHERE guild_id = $1`, params);
}

// 7J-111TICKETSCOPE: who to ping on a ticket that ISN'T tied to a specific
// league (a guild-wide feature issue) — the configured ticket_admin_role_id if
// set, otherwise falls back to whichever of the guild's own roles actually
// carry Discord's Administrator permission (excluding managed/bot-integration
// roles, which can't be meaningfully "pinged for help"), so a real ping still
// goes out even before an admin has explicitly configured this. Best-effort:
// if genuinely nothing qualifies (e.g. only @everyone has admin, extremely
// unusual), returns an empty array and the ticket still opens, just unpinged.
async function resolveGuildTicketAdminMentionRoleIds(guild) {
  const settings = await getGuildSettings(guild.id, guild.name).catch(() => null);
  if (settings?.ticket_admin_role_id) return [settings.ticket_admin_role_id];
  const adminRoles = guild.roles.cache.filter(role => !role.managed && role.id !== guild.id && role.permissions.has(PermissionFlagsBits.Administrator));
  if (!adminRoles.size) return [];
  // Highest-position real admin role only, to avoid mass-pinging every admin
  // role in a server that has several (owner role, a legacy admin role, etc.).
  const topRole = [...adminRoles.values()].sort((a, b) => b.position - a.position)[0];
  return topRole ? [topRole.id] : [];
}

async function setGuildLanguage(guildId, guildName, language) {
  await getGuildSettings(guildId, guildName); // ensure row exists
  await pool.query(`UPDATE guilds SET language = $2 WHERE guild_id = $1`, [guildId, language]);
}

async function setGuildOnboardingEnabled(guildId, guildName, enabled) {
  await getGuildSettings(guildId, guildName); // ensure row exists
  await pool.query(`UPDATE guilds SET onboarding_enabled = $2 WHERE guild_id = $1`, [guildId, enabled]);
}

