// Translation lookup: t('es', 'admin_panel_title') → looks up TRANSLATIONS.es first,
// falls back to TRANSLATIONS.en, falls back to the key itself so a missing
// translation degrades to a visible-but-ugly string instead of crashing. vars is an
// optional {name: value} map for simple {name}-style interpolation within a string.
function t(language, key, vars = {}) {
  const dict = TRANSLATIONS[language] || TRANSLATIONS.en;
  let str = dict[key] ?? TRANSLATIONS.en[key] ?? key;
  for (const [varName, value] of Object.entries(vars)) {
    str = str.replaceAll(`{${varName}}`, String(value));
  }
  return str;
}

// Server-wide sportsbook betting/payout bounds — distinct from a single game's
// max_bet/max_payout (sportsbook_games, set via /sportsbook limits or the older
// per-game admin panel flow). NULL fields mean "this server hasn't set a bound," in
// which case nothing is enforced at that level (a game's own max_bet/max_payout, if
// set, still applies on its own). Non-null fields are always re-clamped against the
// bot-owner-global range on read, same defense-in-depth as getCurrencySettings, in
// case the bot owner tightened the global bounds after a server set its own value.
async function getGuildSportsbookBounds(guildId) {
  await pool.query(`INSERT INTO guild_currency_settings (guild_id) VALUES ($1) ON CONFLICT (guild_id) DO NOTHING`, [guildId]);
  const result = await pool.query(
    `SELECT sportsbook_min_bet, sportsbook_max_bet, sportsbook_min_payout, sportsbook_max_payout FROM guild_currency_settings WHERE guild_id = $1`,
    [guildId]
  );
  const row = result.rows[0] || {};
  return {
    min_bet: row.sportsbook_min_bet != null ? clampPayoutRate('sportsbook_bet', row.sportsbook_min_bet) : null,
    max_bet: row.sportsbook_max_bet != null ? clampPayoutRate('sportsbook_bet', row.sportsbook_max_bet) : null,
    min_payout: row.sportsbook_min_payout != null ? clampPayoutRate('sportsbook_payout', row.sportsbook_min_payout) : null,
    max_payout: row.sportsbook_max_payout != null ? clampPayoutRate('sportsbook_payout', row.sportsbook_max_payout) : null,
  };
}

// Validates a bet amount + computed payout against this guild's sportsbook bounds
// (see getGuildSportsbookBounds). Called alongside — not instead of — each game's own
// max_bet/max_payout checks; whichever limit is tighter wins. min_payout is stored
// for completeness/display but not enforced here: payout is derived from bet × odds,
// not something a bettor sets directly, so there's no single natural enforcement
// point for a payout floor without also picking a bet-amount minimum for it, which
// would double up with min_bet in a confusing way. Flagged as a known gap.
async function validateSportsbookBetAmount(guildId, amount, payout) {
  const bounds = await getGuildSportsbookBounds(guildId);
  if (bounds.min_bet != null && amount < bounds.min_bet) return { ok: false, message: `Minimum bet for this server is **${bounds.min_bet}**.` };
  if (bounds.max_bet != null && amount > bounds.max_bet) return { ok: false, message: `Maximum bet for this server is **${bounds.max_bet}**.` };
  if (bounds.max_payout != null && payout > bounds.max_payout) return { ok: false, message: `That bet would exceed this server's max payout of **${bounds.max_payout}**.` };
  return { ok: true };
}

function buildCurrencySettingsEmbed(settings) {
  const winBounds = CURRENCY_PAYOUT_TYPES.includes('win_payout') ? `${currencyConfigCache.win_payout_min}–${currencyConfigCache.win_payout_max}` : '';
  const gameBounds = `${currencyConfigCache.game_played_payout_min}–${currencyConfigCache.game_played_payout_max}`;
  const awardBounds = `${currencyConfigCache.award_payout_min}–${currencyConfigCache.award_payout_max}`;
  return new EmbedBuilder()
    .setTitle('Currency Settings')
    .setColor(0xFEE75C)
    .addFields(
      { name: 'Currency', value: `${settings.currency_icon || '🪙'} ${settings.currency_name || 'GG Coins'} (global — same everywhere, set via /botowner currencyidentity)`, inline: false },
      { name: 'Win Payout', value: `${settings.win_payout ?? 100} (allowed range: ${winBounds})`, inline: true },
      { name: 'Game Played Payout', value: `${settings.game_played_payout ?? 25} (allowed range: ${gameBounds})`, inline: true },
      { name: 'Award Payout', value: `${settings.award_payout ?? 50} (allowed range: ${awardBounds})`, inline: true },
    )
    .setFooter({ text: 'GG Sports • Economy' })
    .setTimestamp();
}

async function getBalance(guildId, userId) {
  await pool.query(
    `INSERT INTO user_currency_balances (user_id)
     VALUES ($1)
     ON CONFLICT (user_id) DO NOTHING`,
    [userId]
  );

  const result = await pool.query(
    `SELECT balance, lifetime_earned, lifetime_spent FROM user_currency_balances WHERE user_id = $1`,
    [userId]
  );

  return result.rows[0] || { balance: 0, lifetime_earned: 0, lifetime_spent: 0 };
}

async function addCurrency(guildId, userId, amount, transactionType, reason, issuedByUserId = null) {
  if (!Number.isInteger(amount) || amount <= 0) return;

  await pool.query(
    `INSERT INTO user_currency_balances (user_id, balance, lifetime_earned)
     VALUES ($1, $2, $2)
     ON CONFLICT (user_id)
     DO UPDATE SET
       balance = user_currency_balances.balance + $2,
       lifetime_earned = user_currency_balances.lifetime_earned + $2,
       updated_at = NOW()`,
    [userId, amount]
  );

  await pool.query(
    `INSERT INTO currency_transactions (id, guild_id, user_id, amount, transaction_type, reason, issued_by_user_id)
     VALUES ($1, $2, $3, $4, $5, $6, $7)`,
    [randomUUID(), guildId, userId, amount, transactionType, reason || null, issuedByUserId]
  );
}

async function removeCurrency(guildId, userId, amount, transactionType, reason, issuedByUserId = null) {
  if (!Number.isInteger(amount) || amount <= 0) return false;

  const balance = await getBalance(guildId, userId);
  if (Number(balance.balance) < amount) return false;

  await pool.query(
    `UPDATE user_currency_balances
     SET balance = balance - $2,
         lifetime_spent = lifetime_spent + $2,
         updated_at = NOW()
     WHERE user_id = $1`,
    [userId, amount]
  );

  await pool.query(
    `INSERT INTO currency_transactions (id, guild_id, user_id, amount, transaction_type, reason, issued_by_user_id)
     VALUES ($1, $2, $3, $4, $5, $6, $7)`,
    [randomUUID(), guildId, userId, -amount, transactionType, reason || null, issuedByUserId]
  );

  // 7J-40ACHIEVE: centralized total_wagered tracking — every sportsbook bet
  // placement (single bet or parlay) funnels through this one function via
  // removeCurrency's transactionType, so this covers all current and future
  // bet-placement call sites without needing a separate hook at each one.
  if (transactionType === 'sportsbook_bet' || transactionType === 'sportsbook_parlay_bet') {
    await incrementRecognitionStat(guildId, userId, 'total_wagered', amount).catch(() => null);
    await checkSportsbookAchievements(guildId, userId).catch(() => null);
  }

  return true;
}

function buildBalanceEmbed(settings, user, balanceRow) {
  return new EmbedBuilder()
    .setTitle(`${settings.currency_icon} ${user.username}'s Balance`)
    .setColor(0xFEE75C)
    .setThumbnail(user.displayAvatarURL({ dynamic: true }))
    .addFields(
      { name: 'Balance', value: `${settings.currency_icon} ${balanceRow.balance} ${settings.currency_name}`, inline: false },
      { name: 'Lifetime Earned', value: `${settings.currency_icon} ${balanceRow.lifetime_earned}`, inline: true },
      { name: 'Lifetime Spent', value: `${settings.currency_icon} ${balanceRow.lifetime_spent}`, inline: true }
    )
    .setFooter({ text: 'GG Sports • Server Economy' })
    .setTimestamp();
}

function shortItemId(itemId) {
  return String(itemId || '').split('-')[0];
}

async function findShopItem(guildId, itemInput) {
  const result = await pool.query(
    `SELECT * FROM shop_items
     WHERE (guild_id = $1 OR guild_id IS NULL) AND is_active = TRUE AND is_award_only = FALSE
       AND (LOWER(item_name) = LOWER($2) OR id::text LIKE $3)
     ORDER BY created_at DESC
     LIMIT 1`,
    [guildId, itemInput, `${itemInput}%`]
  );
  return result.rows[0] || null;
}

function buildShopEmbed(settings, rows) {
  const NL = String.fromCharCode(10);
  const embed = new EmbedBuilder()
    .setTitle(`${settings.currency_icon} Server Shop`)
    .setColor(0xFEE75C)
    .setFooter({ text: 'GG Sports • Server Shop' })
    .setTimestamp();

  if (!rows.length) {
    embed.setDescription('No active shop items yet. Staff can create one with /createshopitem.');
    return embed;
  }

  const lines = rows.map(row => {
    const stock = row.stock === null || row.stock === undefined ? 'Unlimited' : `${row.stock} left`;
    const description = row.description ? ` — ${row.description}` : '';
    return `**${shortItemId(row.id)} • ${row.item_name}**${description}${NL}${settings.currency_icon} ${row.price} ${settings.currency_name} • Stock: ${stock}`;
  });

  embed.setDescription(lines.join(`${NL}${NL}`));
  return embed;
}

// Item Info page — a single owned item's full detail, looked up by its unique
// lookup_tag (shown in /shop inventory), "item name #production number" for a
// specific unit, or free text. Joins shop_items for cosmetic/catalog detail
// when the source item still exists (a removed item still shows the ownership
// record itself, just without catalog fields), and marketplace_listings so
// collectors can tell at a glance if a matched item is currently for sale.
// 7J-109PRODNUM: redesigned per Hxxdie's feedback that the old version was
// confusing and didn't surface real collector info — now leads with the
// meaningful numbers (Production #, Limited Edition X/Y) instead of the raw
// inventory row id, and surfaces exclusive/purchasable/holiday/reward/release
// package/for-sale status explicitly rather than leaving them undiscoverable.
function buildItemInfoEmbed(settings, row) {
  const titleSuffix = row.production_number ? ` — Production #${row.production_number}` : '';
  const embed = new EmbedBuilder()
    .setTitle(`🔎 ${row.item_name}${titleSuffix}`)
    .setColor(0x5865F2)
    .setFooter({ text: 'GG Sports • Item Info' })
    .setTimestamp();

  const fields = [
    { name: 'Owner', value: `<@${row.user_id}>`, inline: true },
    { name: 'Status', value: row.status || 'owned', inline: true },
  ];

  if (row.production_number) {
    fields.push({ name: 'Production Number', value: `#${row.production_number}`, inline: true });
  }
  if (row.serial_number) {
    const runTotal = row.max_stock !== null && row.max_stock !== undefined ? `/${row.max_stock}` : '';
    fields.push({ name: 'Limited Edition', value: `#${row.serial_number}${runTotal}`, inline: true });
  }
  if (row.rarity) fields.push({ name: 'Rarity', value: row.rarity.charAt(0).toUpperCase() + row.rarity.slice(1), inline: true });
  if (row.avatar_slot) fields.push({ name: 'Slot', value: row.avatar_slot, inline: true });
  fields.push({ name: 'Price Paid', value: `${settings.currency_icon} ${row.price_paid}`, inline: true });
  fields.push({ name: 'Acquired', value: row.purchased_at ? new Date(row.purchased_at).toLocaleDateString('en-US') : 'Unknown', inline: true });

  // "Reward?" — award_type distinguishes a specific staff-granted reward
  // (MVP, Champion, birthday/Christmas gift, etc.) from an ordinary purchase.
  fields.push({ name: 'Reward?', value: row.award_type ? `Yes — ${row.award_type}` : 'No', inline: true });
  fields.push({ name: 'Exclusive?', value: row.is_exclusive ? 'Yes' : 'No', inline: true });
  if (row.gift_type) {
    fields.push({ name: 'Holiday?', value: `${row.gift_type.charAt(0).toUpperCase()}${row.gift_type.slice(1)}${row.gift_year ? ' ' + row.gift_year : ''}`, inline: true });
  }

  // "Purchasable?" reflects the item's CURRENT shop status, not whether this
  // particular owned copy could be bought again — a removed/deactivated/
  // sold-out/award-only source item still shows correctly here.
  let purchasableText = 'No';
  if (!row.item_id) purchasableText = 'No — item removed';
  else if (row.is_award_only) purchasableText = 'No — reward only';
  else if (row.is_active === false) purchasableText = 'No — deactivated';
  else if (row.current_stock !== null && row.current_stock !== undefined && Number(row.current_stock) <= 0) purchasableText = 'No — sold out';
  else if (row.is_active === true) purchasableText = 'Yes';
  fields.push({ name: 'Purchasable?', value: purchasableText, inline: true });

  if (row.release_package) fields.push({ name: 'Release Package', value: row.release_package, inline: true });
  if (row.lookup_tag) fields.push({ name: 'Lookup Tag', value: `\`${row.lookup_tag}\``, inline: true });

  // For Sale? — surfaces whether this exact owned copy is currently listed on
  // the (global, cross-server) Marketplace, per Hxxdie's ask that Item Info
  // cover "any owned items and any items posted for sale on the marketplace."
  fields.push({
    name: 'For Sale?',
    value: row.listing_id ? `Yes — ${settings.currency_icon} ${row.listing_price} (Marketplace)` : 'No',
    inline: true,
  });

  if (row.item_description) fields.push({ name: 'Description', value: row.item_description, inline: false });

  embed.addFields(fields);
  return embed;
}

// Shared search logic behind /shop iteminfo and the Marketplace panel's Item
// Info button — see buildItemInfoEmbed above for what gets displayed. Searches
// owned items (any status) and flags active Marketplace listings, so a single
// lookup answers both "what is this item" and "is anyone selling one."
// Returns { row, multipleMatches, content } where content is a ready-to-send
// error/disambiguation message when row is null.
// 7J-113ITEMINFOPATH: direct lookup by inventory row id — backs the select-menu
// click-through path (inventory list, Item Info disambiguation) which already
// knows exactly which row was picked, so it skips resolveItemInfoSearch's
// text-matching entirely rather than reconstructing a search string.
async function getItemInfoRowById(rowId) {
  const result = await pool.query(
    `SELECT ui.*, si.rarity, si.avatar_slot, si.description AS item_description,
       si.max_stock, si.is_exclusive, si.is_award_only, si.is_active, si.stock AS current_stock,
       si.gift_type, si.gift_year, si.release_package,
       ml.id AS listing_id, ml.asking_price AS listing_price
     FROM user_inventory ui
     LEFT JOIN shop_items si ON si.id = ui.item_id
     LEFT JOIN marketplace_listings ml ON ml.inventory_id = ui.id AND ml.status = 'active'
     WHERE ui.id = $1
     LIMIT 1`,
    [rowId]
  ).catch(() => ({ rows: [] }));
  return result.rows[0] || null;
}

async function resolveItemInfoSearch(guildId, search) {
  const NL = String.fromCharCode(10);
  const joinedSelect = `ui.*, si.rarity, si.avatar_slot, si.description AS item_description,
    si.max_stock, si.is_exclusive, si.is_award_only, si.is_active, si.stock AS current_stock,
    si.gift_type, si.gift_year, si.release_package,
    ml.id AS listing_id, ml.asking_price AS listing_price`;
  const joinedFrom = `user_inventory ui
    LEFT JOIN shop_items si ON si.id = ui.item_id
    LEFT JOIN marketplace_listings ml ON ml.inventory_id = ui.id AND ml.status = 'active'`;

  // 1. Exact tag match — lookup_tag is globally unique, so this alone is
  // enough to find the item regardless of which guild it's in.
  let row = null;
  const tagResult = await pool.query(
    `SELECT ${joinedSelect} FROM ${joinedFrom}
     WHERE LOWER(ui.lookup_tag) = LOWER($1) LIMIT 1`,
    [search]
  ).catch(() => ({ rows: [] }));
  if (tagResult.rows.length) row = tagResult.rows[0];

  // 2. "Item Name #serial" pattern (limited-edition run number) — scoped to
  // this guild. Also tries the item's production number, which is global.
  if (!row && guildId) {
    const serialMatch = search.match(/^(.+?)\s*#\s*(\d+)$/);
    if (serialMatch) {
      const byNameSerial = await pool.query(
        `SELECT ${joinedSelect} FROM ${joinedFrom}
         WHERE ui.guild_id = $1 AND LOWER(ui.item_name) = LOWER($2) AND ui.serial_number = $3 LIMIT 1`,
        [guildId, serialMatch[1].trim(), Number.parseInt(serialMatch[2], 10)]
      ).catch(() => ({ rows: [] }));
      if (byNameSerial.rows.length) row = byNameSerial.rows[0];

      if (!row) {
        const byNameProduction = await pool.query(
          `SELECT ${joinedSelect} FROM ${joinedFrom}
           WHERE LOWER(ui.item_name) = LOWER($1) AND ui.production_number = $2 LIMIT 1`,
          [serialMatch[1].trim(), Number.parseInt(serialMatch[2], 10)]
        ).catch(() => ({ rows: [] }));
        if (byNameProduction.rows.length) row = byNameProduction.rows[0];
      }
    }
  }

  // 3. Fallback: free-text name search, scoped to this guild — shows a pick
  // list if it's ambiguous rather than guessing which owner's copy.
  let multipleMatches = [];
  if (!row && guildId) {
    const nameResult = await pool.query(
      `SELECT ${joinedSelect} FROM ${joinedFrom}
       WHERE ui.guild_id = $1 AND ui.item_name ILIKE $2
       ORDER BY ui.production_number ASC NULLS LAST, ui.purchased_at DESC
       LIMIT 11`,
      [guildId, `%${search}%`]
    ).catch(() => ({ rows: [] }));
    if (nameResult.rows.length === 1) row = nameResult.rows[0];
    else if (nameResult.rows.length > 1) multipleMatches = nameResult.rows;
  }

  if (!row && !multipleMatches.length) {
    return { row: null, multipleMatches: [], content: `No item found matching **${search}**. Try the exact tag (shown in \`/shop inventory\`), or "Item Name #production number".` };
  }
  if (!row) {
    const lines = multipleMatches.slice(0, 10).map(r => {
      const numberText = r.production_number ? ' #' + r.production_number : '';
      const saleText = r.listing_id ? ` — 🏷️ for sale` : '';
      return `• **${r.item_name}${numberText}** — <@${r.user_id}> — tag \`${r.lookup_tag || 'n/a'}\`${saleText}`;
    });
    const more = multipleMatches.length > 10 ? `${NL}...and more. Narrow your search with a production number or exact tag.` : '';
    return { row: null, multipleMatches, content: `Multiple items match **${search}**:${NL}${lines.join(NL)}${more}` };
  }
  return { row, multipleMatches: [], content: null };
}

// 7J-113ITEMINFOPATH: shared by every Item Info search entry point — when the
// search is ambiguous, this turns resolveItemInfoSearch's multipleMatches
// into a clickable select menu (capped at Discord's 25-option limit) instead
// of leaving the person to retype a more specific search. Empty array if
// there's nothing to disambiguate (exact match, or no matches at all).
function buildItemInfoDisambiguationComponents(multipleMatches) {
  if (!multipleMatches || !multipleMatches.length) return [];
  const selectMenu = new StringSelectMenuBuilder()
    .setCustomId('inventory_iteminfo_select')
    .setPlaceholder('Which one?')
    .addOptions(multipleMatches.slice(0, 25).map(r => {
      const numberText = r.production_number ? ` #${r.production_number}` : '';
      return {
        label: `${r.item_name}${numberText}`.slice(0, 100),
        value: r.id,
        description: `owner tag ${r.lookup_tag || 'n/a'}${r.listing_id ? ' • for sale' : ''}`.slice(0, 100),
      };
    }));
  return [new ActionRowBuilder().addComponents(selectMenu)];
}

// 7J-109PRODNUM: redesigned per Hxxdie's feedback — the old version led with the
// raw inventory row id ("170b424c"), which read as a jumbled, meaningless code.
// Now leads with the item name and its real Production Number, with the lookup
// tag shown separately underneath for anyone who wants full detail via Item Info
// (the button/command that calls buildItemInfoEmbed above) — this list stays
// intentionally compact rather than trying to show every field inline.
// 7J-113ITEMINFOPATH: returns { embed, components } instead of a bare embed —
// per Hxxdie, "Item Info and My Inventory are still not giving any path to
// seeing more detailed info on items." The text hint alone (type the tag or
// "Item Name #number") wasn't a real path, just instructions to retype
// something. Now attaches a select menu (capped at Discord's 25-option limit)
// so tapping an item opens its Item Info directly — no retyping anything.
function buildInventoryEmbed(settings, user, rows) {
  const NL = String.fromCharCode(10);
  const embed = new EmbedBuilder()
    .setTitle(`${user.username}'s Inventory`)
    .setColor(0x5865F2)
    .setThumbnail(user.displayAvatarURL({ dynamic: true }))
    .setFooter({ text: 'GG Sports • Inventory' })
    .setTimestamp();

  if (!rows.length) {
    embed.setDescription('No inventory items yet.');
    return { embed, components: [] };
  }

  const lines = rows.map(row => {
    const date = row.purchased_at ? new Date(row.purchased_at).toLocaleDateString('en-US') : 'Unknown date';
    const note = row.request_note ? `${NL}Note: ${row.request_note}` : '';
    const numberText = row.production_number ? ` #${row.production_number}` : (row.serial_number ? ` #${row.serial_number}` : '');
    const tagLine = row.lookup_tag ? `${NL}Tag: \`${row.lookup_tag}\`` : '';
    return `**${row.item_name}${numberText}** — ${settings.currency_icon} ${row.price_paid} • ${date}${NL}Status: **${row.status}**${tagLine}${note}`;
  });

  const intro = rows.length > 25
    ? `Showing the first 25 of ${rows.length} — pick one below for full detail, or use **Item Info** directly (tag or "Item Name #number") for anything further down.`
    : 'Pick an item below for full detail.';
  embed.setDescription(intro + NL + NL + lines.join(`${NL}${NL}`));

  const selectMenu = new StringSelectMenuBuilder()
    .setCustomId('inventory_iteminfo_select')
    .setPlaceholder('View full detail on an item')
    .addOptions(rows.slice(0, 25).map(row => {
      const numberText = row.production_number ? ` #${row.production_number}` : (row.serial_number ? ` #${row.serial_number}` : '');
      return {
        label: `${row.item_name}${numberText}`.slice(0, 100),
        value: row.id,
        description: `${settings.currency_icon} ${row.price_paid} • ${row.status}`.slice(0, 100),
      };
    }));

  return { embed, components: [new ActionRowBuilder().addComponents(selectMenu)] };
}

