function buildTournamentRewardsEmbed(settings, rows) {
  const NL = String.fromCharCode(10);
  const embed = new EmbedBuilder()
    .setTitle('Tournament Rewards')
    .setColor(0xFEE75C)
    .setFooter({ text: 'GG Sports • Tournament Rewards' })
    .setTimestamp();

  if (!rows.length) {
    embed.setDescription('No tournament reward records found.');
    return embed;
  }

  const lines = rows.map(row => {
    const championPrize = Number(row.prize_paid || 0) > 0 ? ` • Champion Prize: ${settings.currency_icon} ${row.prize_paid}` : '';
    const mvp = row.mvp_user_id ? ` • MVP: <@${row.mvp_user_id}>` : '';
    const mvpPrize = Number(row.mvp_payout || 0) > 0 ? ` (${settings.currency_icon} ${row.mvp_payout})` : '';
    return `**${row.tournament_name}** — Champion: <@${row.champion_user_id}>${championPrize}${mvp}${mvpPrize}`;
  });

  embed.setDescription(lines.join(NL));
  return embed;
}

function shortMatchId(matchId) {
  return String(matchId || '').split('-')[0];
}

function buildTournamentMatchesEmbed(tournament, matches) {
  const NL = String.fromCharCode(10);
  const embed = new EmbedBuilder()
    .setTitle(`${tournament.tournament_name} • Matches`)
    .setColor(0xED4245)
    .setFooter({ text: 'GG Sports • Tournament Matches' })
    .setTimestamp();

  if (!matches.length) {
    embed.setDescription('No matches have been generated yet.');
    return embed;
  }

  const lines = matches.map(match => {
    const p1 = match.player1_user_id ? `<@${match.player1_user_id}>${match.player1_entry_name ? ` (${match.player1_entry_name})` : ''}` : 'BYE';
    const p2 = match.player2_user_id ? `<@${match.player2_user_id}>${match.player2_entry_name ? ` (${match.player2_entry_name})` : ''}` : 'BYE';
    const winner = match.winner_user_id ? ` • Winner: <@${match.winner_user_id}>` : '';
    return `**${shortMatchId(match.id)}** • Round ${match.round_number}, Match ${match.match_number}${NL}${p1} vs ${p2} • ${match.status}${winner}`;
  });

  embed.setDescription(lines.join(`${NL}${NL}`));
  return embed;
}

function buildTournamentMatchThreadEmbed(tournament, match) {
  const p1 = match.player1_user_id ? `<@${match.player1_user_id}>${match.player1_entry_name ? ` (${match.player1_entry_name})` : ''}` : 'BYE';
  const p2 = match.player2_user_id ? `<@${match.player2_user_id}>${match.player2_entry_name ? ` (${match.player2_entry_name})` : ''}` : 'BYE';

  return new EmbedBuilder()
    .setTitle(`${tournament.tournament_name} • Match ${shortMatchId(match.id)}`)
    .setColor(0xED4245)
    .addFields(
      { name: 'Round', value: String(match.round_number), inline: true },
      { name: 'Match', value: String(match.match_number), inline: true },
      { name: 'Match ID', value: shortMatchId(match.id), inline: true },
      { name: 'Player 1', value: p1, inline: false },
      { name: 'Player 2', value: p2, inline: false },
      { name: 'How to Report', value: 'Staff can click the winner button below, or use `/reportmatch` with this Match ID.', inline: false }
    )
    .setFooter({ text: 'GG Sports • Tournament Match Thread' })
    .setTimestamp();
}

function buildMatchWinnerButtons(match, disabled = false) {
  const row = new ActionRowBuilder();

  if (match.player1_user_id) {
    row.addComponents(
      new ButtonBuilder()
        .setCustomId(`tourney_match_winner:${match.id}:${match.player1_user_id}`)
        .setLabel('Player 1 Won')
        .setStyle(ButtonStyle.Success)
        .setDisabled(disabled)
    );
  }

  if (match.player2_user_id) {
    row.addComponents(
      new ButtonBuilder()
        .setCustomId(`tourney_match_winner:${match.id}:${match.player2_user_id}`)
        .setLabel('Player 2 Won')
        .setStyle(ButtonStyle.Primary)
        .setDisabled(disabled)
    );
  }

  return row;
}

async function finalizeTournamentMatch(guild, match, winnerUserId, reportedByUserId) {
  await pool.query(
    `UPDATE tournament_matches SET winner_user_id = $1, status = 'final', reported_by_user_id = $2, updated_at = NOW() WHERE id = $3`,
    [winnerUserId, reportedByUserId, match.id]
  );

  const allMatches = await getTournamentMatches(match.tournament_id);
  const currentRoundMatches = allMatches.filter(m => Number(m.round_number) === Number(match.round_number));
  const currentRoundComplete = currentRoundMatches.every(m => m.status === 'final' || m.status === 'bye' || m.winner_user_id);

  if (!currentRoundComplete) {
    const refreshedTournament = await findTournament(guild.id, match.tournament_name);
    if (refreshedTournament) await updateTournamentPanel(guild, refreshedTournament);
    return { complete: false, message: `Match reported. Winner: <@${winnerUserId}>.` };
  }

  const winners = currentRoundMatches
    .map(m => ({
      user_id: m.winner_user_id,
      entry_name: m.winner_user_id === m.player1_user_id ? m.player1_entry_name : m.player2_entry_name,
    }))
    .filter(w => w.user_id);

  if (winners.length === 1) {
    await pool.query(`UPDATE tournaments SET status = 'completed', updated_at = NOW() WHERE id = $1`, [match.tournament_id]);
    // 7J-TOURNEYPANELREFRESH: completion drops this tournament out of the
    // public panel's dropdown list — keep that panel in sync.
    await refreshAllMultiChannelPanelPostings(guild, 'tournament').catch(() => null);
    const settings = await getCurrencySettings(guild.id);
    let payoutText = '';

    if (Number(match.prize_pool) > 0) {
      await addCurrency(guild.id, winners[0].user_id, Number(match.prize_pool), 'tournament_prize', `Won ${match.tournament_name}`, reportedByUserId);
      payoutText = ` ${settings.currency_icon} <@${winners[0].user_id}> earned the prize pool of **${match.prize_pool} ${settings.currency_name}**.`;
    }

    const completedTournament = await findTournament(guild.id, match.tournament_name);
    if (completedTournament) {
      await pool.query(
        `INSERT INTO tournament_history (id, guild_id, league_id, tournament_id, tournament_name, game, format, champion_user_id, prize_paid)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
        [randomUUID(), guild.id, completedTournament.league_id || null, match.tournament_id, match.tournament_name, completedTournament.game, completedTournament.format, winners[0].user_id, Number(match.prize_pool || 0)]
      );
      await updateTournamentPanel(guild, { ...completedTournament, status: 'completed' });

      // 7J-TOURNAMENTCATEGORY / 7J-BRACKETIMG: champion + final bracket now
      // archived to the dedicated Tournament History channel instead of
      // wherever the tournament happened to be configured to announce.
      // Includes the actual rendered bracket graphic (not just the
      // round-by-round text embed) as an attachment, and its resulting CDN
      // URL is saved on the tournament_history row for permanence — same
      // convention as trade_offers.screenshot_url elsewhere in this file.
      const historySettings = await pool.query(`SELECT tournament_history_channel_id FROM guild_tournament_settings WHERE guild_id = $1`, [guild.id]).catch(() => ({ rows: [] }));
      const historyChannelId = historySettings.rows[0]?.tournament_history_channel_id;
      const historyChannel = historyChannelId ? await guild.channels.fetch(historyChannelId).catch(() => null) : null;
      if (historyChannel && historyChannel.isTextBased()) {
        const championSettings = await getCurrencySettings(guild.id);
        const finalMatches = await getTournamentMatches(match.tournament_id).catch(() => []);
        const bracketPng = await renderTournamentBracketPng(guild, completedTournament, finalMatches).catch(() => null);
        const files = bracketPng ? [new AttachmentBuilder(bracketPng, { name: 'final-bracket.png' })] : [];
        const historyMessage = await historyChannel.send({
          embeds: [
            buildTournamentChampionEmbed(championSettings, completedTournament, winners[0].user_id, Number(match.prize_pool || 0)),
            buildTournamentPanelEmbed(completedTournament, finalMatches),
          ],
          files,
        }).catch(() => null);
        const bracketImageUrl = historyMessage?.attachments?.first()?.url || null;
        if (bracketImageUrl) {
          await pool.query(`UPDATE tournament_history SET bracket_image_url = $1 WHERE tournament_id = $2`, [bracketImageUrl, match.tournament_id]).catch(() => null);
        }
      }

      // 7J-TOURNAMENTCATEGORY: temp channel (and every thread under it,
      // deleted automatically by Discord along with its parent channel)
      // cleaned up now that the bracket's been archived to history.
      if (completedTournament.temp_channel_id) {
        const tempChannel = await guild.channels.fetch(completedTournament.temp_channel_id).catch(() => null);
        if (tempChannel) await tempChannel.delete('Tournament completed — archived to history').catch(() => null);
      }
    }

    return { complete: true, message: `Tournament complete. Champion: <@${winners[0].user_id}>.${payoutText}` };
  }

  await createTournamentRound({ id: match.tournament_id, guild_id: guild.id }, winners, Number(match.round_number) + 1);
  const refreshedTournament = await findTournament(guild.id, match.tournament_name);
  if (refreshedTournament) {
    const refreshedMatches = await getTournamentMatches(match.tournament_id);
    await createMatchThreads(guild, refreshedTournament, refreshedMatches);
    await updateTournamentPanel(guild, refreshedTournament);
  }

  return {
    complete: true,
    message: `Round ${match.round_number} complete. Round ${Number(match.round_number) + 1} has been generated.`,
  };
}

// 7J-TOURNEYREGCHAN: per Hxxdie — the tournament's dedicated temp channel is
// now created immediately at tournament creation (finalizeTournamentCreation
// calls this too), not lazily on the first round, so the registration panel
// itself can live in that channel instead of requiring staff to hand-pick
// one during creation. Idempotent/reusable: if the temp channel already
// exists (registration already created it, or a later round is calling in),
// just fetch and return it.
async function ensureTournamentTempChannel(guild, tournament) {
  let channel = tournament.temp_channel_id
    ? await guild.channels.fetch(tournament.temp_channel_id).catch(() => null)
    : null;
  if (channel) return channel;

  const tournamentSettings = await pool.query(`SELECT tournament_channel_id FROM guild_tournament_settings WHERE guild_id = $1`, [guild.id]).catch(() => ({ rows: [] }));
  const parentChannel = tournamentSettings.rows[0]?.tournament_channel_id
    ? await guild.channels.fetch(tournamentSettings.rows[0].tournament_channel_id).catch(() => null)
    : null;
  const safeName = String(tournament.tournament_name || 'tournament').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 90) || 'tournament';
  channel = await guild.channels.create({
    name: safeName,
    type: ChannelType.GuildText,
    parent: parentChannel?.parentId || undefined,
  }).catch(() => null);
  if (channel) {
    await pool.query(`UPDATE tournaments SET temp_channel_id = $1, updated_at = NOW() WHERE id = $2`, [channel.id, tournament.id]).catch(() => null);
  }
  return channel;
}

async function createMatchThreads(guild, tournament, matches) {
  // 7J-TOURNAMENTCATEGORY: per Hxxdie — matches now live under a temporary
  // channel created for and named after this specific tournament, instead
  // of all sharing the one guild-wide Tournaments channel. Created once
  // (now at tournament creation, see ensureTournamentTempChannel/
  // finalizeTournamentCreation) and reused for every subsequent round;
  // deleted (along with all its threads) once the tournament completes.
  const channel = await ensureTournamentTempChannel(guild, tournament);
  if (!channel || !channel.isTextBased()) return;

  for (const match of matches) {
    if (!match.player1_user_id || !match.player2_user_id || match.status === 'final' || match.status === 'bye') continue;
    if (match.thread_id) continue;

    // 7J-MATCHTHREADDUP: per Hxxdie — a thread created FROM a channel
    // message (message.startThread()) leaves that origin message visibly
    // sitting in the parent channel *and* Discord's client also renders it
    // (as a non-interactive reference) at the top of the thread itself —
    // looking like two copies of the same matchup post, one with working
    // buttons (the real message, in the channel) and one that looks
    // greyed-out (the thread's read-only reference to it). Creating a
    // standalone thread instead (not anchored to any channel message, same
    // pattern already used for trade-negotiation threads elsewhere in this
    // file) and posting the real interactive matchup message *inside* the
    // thread avoids a parent-channel post entirely — the matchup now only
    // ever lives in the thread, with one real, always-interactive copy of
    // the winner buttons.
    const threadName = `${tournament.tournament_name} R${match.round_number} M${match.match_number}`.slice(0, 90);
    const thread = await channel.threads.create({
      name: threadName,
      type: ChannelType.PublicThread,
      autoArchiveDuration: 1440,
      reason: 'Tournament match thread',
    }).catch(() => null);

    if (thread) {
      await thread.send({
        content: `<@${match.player1_user_id}> vs <@${match.player2_user_id}> — Tournament match created.`,
        embeds: [buildTournamentMatchThreadEmbed(tournament, match)],
        components: [buildMatchWinnerButtons(match)],
        allowedMentions: { users: [match.player1_user_id, match.player2_user_id], roles: [] },
      }).catch(() => null);

      await thread.send({
        content: `<@${match.player1_user_id}> <@${match.player2_user_id}> schedule/play your match here. Staff can click the winner button on the match post, or use Match ID: **${shortMatchId(match.id)}**`,
        allowedMentions: { users: [match.player1_user_id, match.player2_user_id], roles: [] },
      }).catch(() => null);

      await pool.query(`UPDATE tournament_matches SET thread_id = $1, updated_at = NOW() WHERE id = $2`, [thread.id, match.id]);
    }
  }
}

function buildTournamentPanelEmbed(tournament, matches) {
  const NL = String.fromCharCode(10);
  const rounds = new Map();

  for (const match of matches) {
    const round = Number(match.round_number);
    if (!rounds.has(round)) rounds.set(round, []);
    rounds.get(round).push(match);
  }

  const embed = new EmbedBuilder()
    .setTitle(`${tournament.tournament_name} • Bracket Panel`)
    .setColor(0xED4245)
    .addFields(
      { name: 'Status', value: tournament.status || 'unknown', inline: true },
      { name: 'Format', value: tournament.format || 'single_elim', inline: true },
      { name: 'Game', value: tournament.game || 'TBD', inline: true }
    )
    .setFooter({ text: 'GG Sports • Live Tournament Bracket' })
    .setTimestamp();

  if (!matches.length) {
    embed.setDescription('Bracket has not been generated yet. Use /starttournament when registration is ready.');
    return embed;
  }

  for (const [round, roundMatches] of [...rounds.entries()].sort((a, b) => a[0] - b[0])) {
    const value = roundMatches.map(match => {
      const p1 = match.player1_user_id ? `<@${match.player1_user_id}>` : 'BYE';
      const p2 = match.player2_user_id ? `<@${match.player2_user_id}>` : 'BYE';
      const winner = match.winner_user_id ? ` → <@${match.winner_user_id}>` : '';
      return `**${shortMatchId(match.id)}** ${p1} vs ${p2} • ${match.status}${winner}`;
    }).join(NL);

    embed.addFields({ name: `Round ${round}`, value: value || 'No matches', inline: false });
  }

  return embed;
}

async function saveTournamentPanel(tournamentId, guildId, channelId, messageId) {
  await pool.query(
    `INSERT INTO tournament_panels (tournament_id, guild_id, channel_id, message_id, updated_at)
     VALUES ($1, $2, $3, $4, NOW())
     ON CONFLICT (tournament_id)
     DO UPDATE SET channel_id = $3, message_id = $4, updated_at = NOW()`,
    [tournamentId, guildId, channelId, messageId]
  );
}

// ---------------------------------------------------------------------------
// Tournament Panel — the slash commands for create/join/start/report/shuffle
// were registered but never actually implemented (they'd silently fail). The
// underlying engine (createTournamentRound, finalizeTournamentMatch,
// createMatchThreads, updateTournamentPanel) is real and solid, so this panel
// is the actual entry point for that engine rather than a wrapper around
// working commands.
// ---------------------------------------------------------------------------
async function buildTournamentManagerHomePayload(guild, { includeAdminBackButton = true } = {}) {
  const result = await pool.query(
    `SELECT * FROM tournaments WHERE guild_id = $1 AND status IN ('open','closed','active') ORDER BY created_at DESC LIMIT 25`,
    [guild.id]
  );
  // 7J-TOURNEYREGCHAN: per Hxxdie — the "Default Tournament Channel" field
  // (and the dropdown that used to set it from this panel) was removed.
  // Registration channels are fully automatic per tournament now
  // (ensureTournamentTempChannel), so this field had nothing meaningful
  // left to show here and was displaying a broken "#unknown" reference.
  const embed = new EmbedBuilder()
    .setTitle('🏆 Tournament Manager')
    .setColor(0xED4245)
    .setDescription(result.rows.length ? 'Pick a tournament to manage, or create a new one.' : 'No open tournaments. Create one to get started.')
    .setFooter({ text: 'GG Sports • Tournament Manager' })
    .setTimestamp();

  const components = [];
  if (result.rows.length) {
    // 7J-TOURNEYDROPDOWNSTUCK: per Hxxdie — a Discord select menu whose only
    // reachable option already matches what's showing as "selected" can
    // fail to fire a fresh interaction at all when you click it again
    // (nothing to actually change to, from the client's perspective). With
    // exactly one tournament, that made the dropdown a permanent dead end —
    // no way back to the control panel once dismissed. Buttons don't have
    // this failure mode, so small lists (≤4, one action row) get direct
    // per-tournament buttons instead of relying on the dropdown at all.
    // Larger lists keep the dropdown, where this is far less likely to bite
    // since picking a *different* tournament than last time is the norm.
    if (result.rows.length <= 4) {
      components.push(new ActionRowBuilder().addComponents(
        result.rows.map(t => new ButtonBuilder()
          .setCustomId(`tourneypanel_selectbtn:${t.id}`)
          .setLabel((t.tournament_name || 'Unnamed').slice(0, 80))
          .setStyle(ButtonStyle.Secondary))
      ));
    } else {
      const menu = new StringSelectMenuBuilder()
        .setCustomId('tourneypanel_select')
        .setPlaceholder('Choose a tournament to manage')
        .addOptions(result.rows.map(t => ({
          label: (t.tournament_name || 'Unnamed').slice(0, 100),
          value: t.id.slice(0, 100),
          description: `${t.game || 'Game TBD'} • ${t.status}`.slice(0, 100),
        })));
      components.push(new ActionRowBuilder().addComponents(menu));
    }
  }
  components.push(new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('tourneypanel_create').setLabel('Create Tournament').setEmoji('➕').setStyle(ButtonStyle.Success)
  ));
  // 7J-TOURNAMENTAUTOSETUP: this payload is now also posted as the public,
  // standing panel in the auto-created #tournaments channel (see
  // getMultiChannelPanelInfo) — "Back to Admin Panel" is meaningless there
  // since a regular member never came from the Admin Panel to begin with.
  // Create Tournament stays visible either way since it's already
  // staff-gated at click time, matching how Force Win/Reset Game buttons
  // work elsewhere in this codebase.
  if (includeAdminBackButton) {
    components.push(new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('adminpanel_back').setLabel('⬅ Back to Admin Panel').setStyle(ButtonStyle.Secondary)
    ));
  }
  return { embeds: [embed], components };
}

async function buildTournamentManagerViewPayload(guild, tournament, { includeAdminBackButton = true } = {}) {
  const settings = await getCurrencySettings(guild.id);
  const entries = await getTournamentEntries(tournament.id);
  const matches = await getTournamentMatches(tournament.id);
  const availability = await getTournamentActionAvailability(tournament, entries, matches);
  const embed = buildTournamentInfoEmbed(settings, tournament, entries, availability);
  const rows = buildTournamentActionRows(tournament, availability, includeAdminBackButton);
  return { embeds: [embed], components: rows };
}

// ---------------------------------------------------------------------------
// Tournament Creation Wizard — Format/Channel need real select menus (modals
// can't contain them), and the full field set (name/game/entries/buy-in/date/
// time/rules) exceeds a modal's 5-field cap, so this is a session-backed
// multi-step flow: selects first, then two bridged modals.
// ---------------------------------------------------------------------------
const TOURNAMENT_MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];

// No year select — a tournament date is essentially always "the next
// occurrence" of a given month/day, so we infer the year rather than adding
// a 3rd select row (Discord caps messages at 5 rows total, and this picker
// already needs most of that budget across its two steps).
function inferTournamentYear(month, day, ianaZone = null) {
  const now = new Date();
  // 7J-YEARINFERFIX2: per Hxxdie — the first fix (date-granularity, not
  // exact-time comparison) was real but insufficient on its own. The
  // deeper bug: "today" was computed from the SERVER's system clock
  // (now.getFullYear/getMonth/getDate use the machine's local timezone),
  // not the timezone the user actually selected for their proposed time.
  // Railway runs on UTC — if it's 9:46 PM ET, that's already after
  // midnight UTC, so the server's own "today" is already tomorrow. Picking
  // today's date (in the user's zone) then looked like picking yesterday
  // (in the server's zone), tripping the "already passed" branch and
  // silently adding a year. Verified numerically against this exact
  // scenario before shipping. Now computes "today" in the SAME timezone
  // the date/time is actually being entered for, when known.
  let nowYear, nowMonth, nowDate;
  if (ianaZone) {
    const parts = {};
    for (const p of new Intl.DateTimeFormat('en-US', { timeZone: ianaZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now)) parts[p.type] = p.value;
    nowYear = Number(parts.year); nowMonth = Number(parts.month); nowDate = Number(parts.day);
  } else {
    nowYear = now.getFullYear(); nowMonth = now.getMonth() + 1; nowDate = now.getDate();
  }
  const todayMidnight = new Date(nowYear, nowMonth - 1, nowDate);
  const candidate = new Date(nowYear, month - 1, day);
  return candidate < todayMidnight ? nowYear + 1 : nowYear;
}

// Best-effort parse of the OLD free-text start_time values (e.g. "7:30 PM
// EST") back into hour/minute/ampm for pre-filling Edit's picker. Falls back
// to nothing pre-selected if it doesn't match — acceptable, since the user
// re-picks it either way.
const TOURNAMENT_TIMEZONE_ALIASES = {
  EST: 'ET', EDT: 'ET', ET: 'ET',
  CST: 'CT', CDT: 'CT', CT: 'CT', // bare "CST" defaults to US Central, not Taiwan — too ambiguous to guess from free text either way
  MST: 'MT', MDT: 'MT', MT: 'MT',
  PST: 'PT', PDT: 'PT', PT: 'PT',
  COT: 'COT',
  CET: 'CET', CEST: 'CET',
  WET: 'WET', WEST: 'WET',
  BRT: 'BRT', BRST: 'BRT',
  JST: 'JST',
  KST: 'KST',
  UTC: 'UTC', GMT: 'UTC',
};

function parseLegacyTournamentTime(text) {
  if (!text) return {};
  const match = /(\d{1,2}):?(\d{2})?\s*(AM|PM)/i.exec(text);
  if (!match) return {};
  const hour = Number.parseInt(match[1], 10);
  const minute = match[2] ? Number.parseInt(match[2], 10) : 0;
  const roundedMinute = Math.round(minute / 30) * 30 % 60;
  if (hour < 1 || hour > 12) return {};
  const tzMatch = /\b(EST|EDT|ET|CST|CDT|CT|MST|MDT|MT|PST|PDT|PT|COT|CET|CEST|WET|WEST|BRT|BRST|JST|KST|UTC|GMT)\b/i.exec(text);
  const timezone = tzMatch ? TOURNAMENT_TIMEZONE_ALIASES[tzMatch[1].toUpperCase()] : undefined;
  return { hour, minute: roundedMinute, ampm: match[3].toUpperCase(), ...(timezone ? { timezone } : {}) };
}

// Step A of the date/time picker: month + day. `prefix` is either
// 'tourneycreate' or 'tourneyedit' so this one pair of builders serves both
// flows — each flow's session object just needs month/day/hour/minute/ampm
// fields, same shape either way.
function buildDateTimePickerStepA(prefix, token, session) {
  const monthMenu = new StringSelectMenuBuilder()
    .setCustomId(`${prefix}_dtmonth:${token}`)
    .setPlaceholder('Month')
    .addOptions(TOURNAMENT_MONTH_NAMES.map((name, i) => ({ label: name, value: String(i + 1), default: session.month === i + 1 })));
  // Discord caps a select menu at 25 options — 31 days doesn't fit in one,
  // and no month has ≤25 days (even February has 28), so this split is
  // unavoidable rather than being solvable by scoping to the chosen month.
  const day1Menu = new StringSelectMenuBuilder()
    .setCustomId(`${prefix}_dtday1:${token}`)
    .setPlaceholder('Day (1–16)')
    .addOptions(Array.from({ length: 16 }, (_, i) => ({ label: String(i + 1), value: String(i + 1), default: session.day === i + 1 })));
  const day2Menu = new StringSelectMenuBuilder()
    .setCustomId(`${prefix}_dtday2:${token}`)
    .setPlaceholder('Day (17–31)')
    .addOptions(Array.from({ length: 15 }, (_, i) => ({ label: String(i + 17), value: String(i + 17), default: session.day === i + 17 })));
  const continueRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`${prefix}_dtdatecontinue:${token}`).setLabel('Continue to Time').setStyle(ButtonStyle.Primary).setDisabled(!session.month || !session.day)
  );
  const picked = session.month && session.day ? `${TOURNAMENT_MONTH_NAMES[session.month - 1]} ${session.day}` : 'not picked yet';
  return {
    content: `**Pick a date — Step 1 of 2**\nDate: **${picked}**`,
    embeds: [], components: [new ActionRowBuilder().addComponents(monthMenu), new ActionRowBuilder().addComponents(day1Menu), new ActionRowBuilder().addComponents(day2Menu), continueRow],
  };
}

// Step B: hour (1-12) + minute (5-min increments) + AM/PM.
// Covers all 8 languages the bot supports (SUPPORTED_LANGUAGES above) plus
// the original 4 US zones — a select menu holds up to 25 options in one row
// regardless of count, so there's no cost to including all of these (unlike
// adding a whole extra select, which would've broken the 5-row cap).
const TOURNAMENT_TIMEZONE_OPTIONS = [
  { label: 'Eastern (ET) — US/Canada', value: 'ET' },
  { label: 'Central (CT) — US/Canada, Mexico', value: 'CT' },
  { label: 'Mountain (MT) — US/Canada', value: 'MT' },
  { label: 'Pacific (PT) — US/Canada', value: 'PT' },
  { label: 'Colombia/Peru (COT) — no DST', value: 'COT' },
  { label: 'Central European (CET) — FR/DE/ES', value: 'CET' },
  { label: 'Western European (WET) — Portugal, UK/Ireland', value: 'WET' },
  { label: 'Brasília (BRT) — Brazil, Argentina, Chile', value: 'BRT' },
  { label: 'Japan (JST)', value: 'JST' },
  { label: 'Korea (KST)', value: 'KST' },
  { label: 'Taiwan (CST)', value: 'TWT' },
  { label: 'UTC', value: 'UTC' },
];

// 7J-TOURNEYTZ: timezone was missing entirely from the original picker — the
// old free-text field let people type e.g. "8:00 PM EST" including zone,
// but the select-based replacement dropped it. Adding it back means a 4th
// select is needed here, and Discord caps a message at 5 component rows
// total (3 selects + AM/PM + Continue would've been 5 already, no room for
// a 4th). So Hour+Minute are merged into one "Time" select at 30-minute
// increments (down from 5-minute) to free up the row Timezone needed.
function buildDateTimePickerStepB(prefix, token, session) {
  const timeMenu = new StringSelectMenuBuilder()
    .setCustomId(`${prefix}_dttimeslot:${token}`)
    .setPlaceholder('Time')
    .addOptions(Array.from({ length: 24 }, (_, i) => {
      const hour = Math.floor(i / 2) + 1;
      const minute = i % 2 === 0 ? 0 : 30;
      const value = `${hour}:${minute}`;
      const label = `${hour}:${String(minute).padStart(2, '0')}`;
      return { label, value, default: session.hour === hour && session.minute === minute };
    }));
  const ampmMenu = new StringSelectMenuBuilder()
    .setCustomId(`${prefix}_dtampm:${token}`)
    .setPlaceholder('AM / PM')
    .addOptions([
      { label: 'AM', value: 'AM', default: session.ampm === 'AM' },
      { label: 'PM', value: 'PM', default: session.ampm === 'PM' },
    ]);
  const timezoneMenu = new StringSelectMenuBuilder()
    .setCustomId(`${prefix}_dttimezone:${token}`)
    .setPlaceholder('Time zone')
    .addOptions(TOURNAMENT_TIMEZONE_OPTIONS.map(tz => ({ ...tz, default: session.timezone === tz.value })));
  const continueRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`${prefix}_dttimecontinue:${token}`).setLabel('Continue').setStyle(ButtonStyle.Primary)
      .setDisabled(session.hour == null || session.minute == null || !session.ampm || !session.timezone)
  );
  const datePicked = `${TOURNAMENT_MONTH_NAMES[session.month - 1]} ${session.day}`;
  const timePicked = (session.hour != null && session.minute != null && session.ampm && session.timezone)
    ? `${session.hour}:${String(session.minute).padStart(2, '0')} ${session.ampm} ${session.timezone}` : 'not picked yet';
  return {
    content: `**Pick a time — Step 2 of 2**\nDate: **${datePicked}**\nTime: **${timePicked}**`,
    embeds: [], components: [new ActionRowBuilder().addComponents(timeMenu), new ActionRowBuilder().addComponents(ampmMenu), new ActionRowBuilder().addComponents(timezoneMenu), continueRow],
  };
}

// Maps each picker value to a real IANA zone so we can compute an accurate
// UTC moment (DST-aware for that specific date) using only built-in
// Intl/Date — no external timezone library needed.
const TOURNAMENT_TIMEZONE_IANA = {
  ET: 'America/New_York', CT: 'America/Chicago', MT: 'America/Denver', PT: 'America/Los_Angeles',
  COT: 'America/Bogota', CET: 'Europe/Paris', WET: 'Europe/Lisbon', BRT: 'America/Sao_Paulo',
  JST: 'Asia/Tokyo', KST: 'Asia/Seoul', TWT: 'Asia/Taipei', UTC: 'UTC',
};

// 7J-TOURNEYUTC: per Hxxdie — every viewer should see the tournament's start
// time converted to THEIR OWN local time, not just whatever zone the
// organizer picked. Discord itself does this automatically for us: a
// <t:EPOCH:F> tag in message content renders in each viewer's own device
// timezone/locale, client-side, with zero per-user setup needed. The only
// work on our end is computing an accurate UTC epoch from the organizer's
// picked wall-clock time + zone, which does need to be DST-aware (e.g. "7:30
// PM ET" is a different UTC moment in January than in July).
//
// Standard technique for converting "wall-clock time in zone X" to UTC using
// only Intl/Date: format a UTC guess back through the target zone, measure
// the drift, and correct for it.
function tournamentWallClockToUtcEpoch(year, month, day, hour24, minute, ianaZone) {
  const utcGuess = Date.UTC(year, month - 1, day, hour24, minute);
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: ianaZone, hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit',
  });
  const parts = {};
  for (const p of formatter.formatToParts(new Date(utcGuess))) parts[p.type] = p.value;
  const asUtc = Date.UTC(
    Number(parts.year), Number(parts.month) - 1, Number(parts.day),
    Number(parts.hour) === 24 ? 0 : Number(parts.hour), Number(parts.minute), Number(parts.second)
  );
  return utcGuess - (asUtc - utcGuess);
}

function tournamentDiscordTimestamp(session) {
  const ianaZone = TOURNAMENT_TIMEZONE_IANA[session.timezone];
  if (!ianaZone) return null;
  const hour24 = session.ampm === 'PM' ? (session.hour % 12) + 12 : session.hour % 12;
  const year = inferTournamentYear(session.month, session.day, ianaZone);
  const epochMs = tournamentWallClockToUtcEpoch(year, session.month, session.day, hour24, session.minute, ianaZone);
  return Math.floor(epochMs / 1000);
}

function finalizeTournamentDateTime(session) {
  const ianaZone = TOURNAMENT_TIMEZONE_IANA[session.timezone];
  const year = inferTournamentYear(session.month, session.day, ianaZone);
  session.date = `${year}-${String(session.month).padStart(2, '0')}-${String(session.day).padStart(2, '0')}`;
  session.time = `${session.hour}:${String(session.minute).padStart(2, '0')} ${session.ampm} ${session.timezone}`;
  session.startsAtEpoch = tournamentDiscordTimestamp(session);
}
// ---------------------------------------------------------------------------
// Scheduling — timezone + rough weekly availability, per Hxxdie. Reuses
// TOURNAMENT_TIMEZONE_IANA and tournamentWallClockToUtcEpoch above rather
// than a second timezone system; this is purely the availability/shared-
// window layer on top of that same proven conversion.
// ---------------------------------------------------------------------------
const SCHEDULING_DAY_LABELS = { sun: 'Sunday', mon: 'Monday', tue: 'Tuesday', wed: 'Wednesday', thu: 'Thursday', fri: 'Friday', sat: 'Saturday' };
const SCHEDULING_DAY_ORDER = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const SCHEDULING_DAY_INDEX = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
// [startHour, endHour) in the user's own local time. "night" wraps past
// midnight (21 -> 25, i.e. 9pm-1am) — handled by the mod-10080 wraparound
// in userAvailabilityToUtcIntervals below, not a special case here.
const SCHEDULING_BLOCKS = { morning: [6, 12], afternoon: [12, 17], evening: [17, 21], night: [21, 25] };
const SCHEDULING_BLOCK_LABELS = { morning: 'Morning (6am-12pm)', afternoon: 'Afternoon (12-5pm)', evening: 'Evening (5-9pm)', night: 'Night (9pm-1am)' };

// Current UTC offset (minutes) for an IANA zone — "current" rather than
// date-specific, since availability is a recurring weekly pattern, not tied
// to one calendar date. Trades perfect DST-transition-week accuracy for
// simplicity; acceptable at block-level (not minute-level) granularity.
function getCurrentUtcOffsetMinutes(ianaZone) {
  try {
    const parts = new Intl.DateTimeFormat('en-US', { timeZone: ianaZone, timeZoneName: 'shortOffset' }).formatToParts(new Date());
    const offsetPart = parts.find(p => p.type === 'timeZoneName')?.value || 'GMT+0';
    const match = offsetPart.match(/GMT([+-]\d+)(?::(\d+))?/);
    if (!match) return 0;
    const hours = Number(match[1]);
    const minutes = Number(match[2] || 0) * (hours < 0 ? -1 : 1);
    return hours * 60 + minutes;
  } catch {
    return 0;
  }
}

// Converts a saved availability row into UTC-based [start, end) intervals on
// a 0-10079 "minutes since Sunday 00:00 UTC" weekly timeline. Each interval
// is duplicated shifted ±10080 so overlap checks against another user's
// intervals correctly catch wraparound (e.g. a "night" block local to one
// user landing on the NEXT UTC day).
function userAvailabilityToUtcIntervals(availability) {
  if (!availability?.timezone) return [];
  const offsetMinutes = getCurrentUtcOffsetMinutes(availability.timezone);
  const intervals = [];
  for (const day of availability.available_days || []) {
    const dayIndex = SCHEDULING_DAY_INDEX[day];
    if (dayIndex === undefined) continue;
    for (const block of availability.available_blocks || []) {
      const range = SCHEDULING_BLOCKS[block];
      if (!range) continue;
      const localStart = dayIndex * 1440 + range[0] * 60;
      const localEnd = dayIndex * 1440 + range[1] * 60;
      const utcStart = localStart - offsetMinutes;
      const utcEnd = localEnd - offsetMinutes;
      for (const shift of [-10080, 0, 10080]) {
        intervals.push([utcStart + shift, utcEnd + shift]);
      }
    }
  }
  return intervals;
}

// Returns overlapping windows between two users' availability, each as
// { dayIndex, startMinuteOfDay, endMinuteOfDay } clipped to a single UTC day
// (a window spanning midnight is split into two entries) — display-ready.
function computeSharedAvailabilityWindows(availabilityA, availabilityB) {
  const intervalsA = userAvailabilityToUtcIntervals(availabilityA);
  const intervalsB = userAvailabilityToUtcIntervals(availabilityB);
  const overlaps = [];
  for (const [aStart, aEnd] of intervalsA) {
    for (const [bStart, bEnd] of intervalsB) {
      const start = Math.max(aStart, bStart);
      const end = Math.min(aEnd, bEnd);
      if (start < end && start >= 0 && start < 10080) {
        overlaps.push([start, Math.min(end, 10080)]);
      }
    }
  }
  // Split anything crossing a day boundary, dedupe near-identical windows.
  const split = [];
  for (const [start, end] of overlaps) {
    const startDay = Math.floor(start / 1440);
    const endDay = Math.floor((end - 1) / 1440);
    if (startDay === endDay) {
      split.push({ dayIndex: startDay, startMinuteOfDay: start - startDay * 1440, endMinuteOfDay: end - startDay * 1440 });
    } else {
      split.push({ dayIndex: startDay, startMinuteOfDay: start - startDay * 1440, endMinuteOfDay: 1440 });
      split.push({ dayIndex: endDay, startMinuteOfDay: 0, endMinuteOfDay: end - endDay * 1440 });
    }
  }
  const seen = new Set();
  const deduped = split.filter(w => {
    const key = `${w.dayIndex}:${w.startMinuteOfDay}:${w.endMinuteOfDay}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  deduped.sort((a, b) => a.dayIndex - b.dayIndex || a.startMinuteOfDay - b.startMinuteOfDay);
  return deduped;
}

function formatSchedulingMinuteOfDay(minuteOfDay) {
  const hour24 = Math.floor(minuteOfDay / 60) % 24;
  const minute = minuteOfDay % 60;
  const ampm = hour24 < 12 ? 'AM' : 'PM';
  const hour12 = hour24 % 12 === 0 ? 12 : hour24 % 12;
  return `${hour12}${minute ? ':' + String(minute).padStart(2, '0') : ''}${ampm}`;
}

function formatSharedAvailabilityWindow(window) {
  const dayLabel = SCHEDULING_DAY_LABELS[SCHEDULING_DAY_ORDER[window.dayIndex]] || 'Day';
  return `${dayLabel} ${formatSchedulingMinuteOfDay(window.startMinuteOfDay)}-${formatSchedulingMinuteOfDay(window.endMinuteOfDay)} UTC`;
}

async function getUserAvailability(guildId, userId) {
  const result = await pool.query(`SELECT * FROM user_availability WHERE guild_id = $1 AND user_id = $2`, [guildId, userId]).catch(() => ({ rows: [] }));
  return result.rows[0] || null;
}

// 7J-SCHEDULING: in-memory session accumulating picks across the 3 select
// menus below before a final Save — same pattern as tournament creation's
// own session maps just above.
const availabilitySessions = new Map();

function buildAvailabilityEditorPayload(userId) {
  const session = availabilitySessions.get(userId) || { timezone: null, days: [], blocks: [] };
  const timezoneMenu = new StringSelectMenuBuilder()
    .setCustomId('availability_timezone_select')
    .setPlaceholder('Your timezone')
    .addOptions(Object.entries(TOURNAMENT_TIMEZONE_IANA).map(([code, iana]) => ({ label: `${code} (${iana.replace('_', ' ')})`, value: code, default: session.timezone === code })));
  const daysMenu = new StringSelectMenuBuilder()
    .setCustomId('availability_days_select')
    .setPlaceholder('Which days are you usually available?')
    .setMinValues(1)
    .setMaxValues(7)
    .addOptions(SCHEDULING_DAY_ORDER.map(day => ({ label: SCHEDULING_DAY_LABELS[day], value: day, default: session.days.includes(day) })));
  const blocksMenu = new StringSelectMenuBuilder()
    .setCustomId('availability_blocks_select')
    .setPlaceholder('What time of day usually works?')
    .setMinValues(1)
    .setMaxValues(4)
    .addOptions(Object.entries(SCHEDULING_BLOCK_LABELS).map(([key, label]) => ({ label, value: key, default: session.blocks.includes(key) })));

  const summaryLines = [
    `**Timezone:** ${session.timezone || 'Not set'}`,
    `**Days:** ${session.days.length ? session.days.map(d => SCHEDULING_DAY_LABELS[d]).join(', ') : 'Not set'}`,
    `**Times:** ${session.blocks.length ? session.blocks.map(b => SCHEDULING_BLOCK_LABELS[b]).join(', ') : 'Not set'}`,
  ];
  const embed = new EmbedBuilder()
    .setTitle('🗓️ Set Your Availability')
    .setColor(0x5865F2)
    .setDescription(`This is a rough weekly pattern, not exact scheduling — when you get a new game thread, GG Sports compares your availability with your opponent's and suggests shared windows to help you agree on a time faster.\n\n${summaryLines.join('\n')}`)
    .setFooter({ text: 'GG Sports • Member Profile' });

  return {
    embeds: [embed],
    components: [
      new ActionRowBuilder().addComponents(timezoneMenu),
      new ActionRowBuilder().addComponents(daysMenu),
      new ActionRowBuilder().addComponents(blocksMenu),
      new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('availability_save').setLabel('Save Availability').setEmoji('✅').setStyle(ButtonStyle.Success)),
    ],
  };
}

// 7J-SCHEDULING: resolves a game (either a regular-season league_games row
// or a Madden madden_imported_games row — two different tables, hence
// gameSource) into the pieces the propose/accept flow needs: which league,
// who owns each side, and a display label.
async function findGameForScheduling(guild, gameSource, gameRef) {
  if (gameSource === 'madden') {
    const gameResult = await pool.query(`SELECT * FROM madden_imported_games WHERE id = $1`, [gameRef]);
    const game = gameResult.rows[0];
    if (!game) return null;
    const league = await getLeagueById(game.league_id).catch(() => null);
    const homeOwner = await getMaddenTeamOwnerForGameThread(guild, league, game.home_team, game.home_team_role_id).catch(() => null);
    const awayOwner = await getMaddenTeamOwnerForGameThread(guild, league, game.away_team, game.away_team_role_id).catch(() => null);
    return { league, homeOwner, awayOwner, label: `${maddenTeamDisplayName(game.away_team)} @ ${maddenTeamDisplayName(game.home_team)}` };
  }
  const gameResult = await pool.query(`SELECT * FROM league_games WHERE id = $1`, [gameRef]);
  const game = gameResult.rows[0];
  if (!game) return null;
  const league = await getLeagueById(game.league_id).catch(() => null);
  const homeOwner = await findTeamOwnerByRoleId(guild, game.home_team_role_id).catch(() => null);
  const awayOwner = await findTeamOwnerByRoleId(guild, game.away_team_role_id).catch(() => null);
  return { league, homeOwner, awayOwner, label: `${game.away_team_name} @ ${game.home_team_name}` };
}

// 7J-SCHEDULING: figures out the two owners of whichever game this thread
// belongs to (checking both possible tables by thread_id), then returns a
// short note listing shared availability windows if both have saved
// availability — used as a hint right before the Propose Time modal opens.
async function buildSchedulingSharedWindowsNote(guildId, channel) {
  if (!channel?.id) return '';
  const genericResult = await pool.query(`SELECT * FROM league_games WHERE thread_id = $1`, [channel.id]).catch(() => ({ rows: [] }));
  let homeOwnerId = null, awayOwnerId = null;
  if (genericResult.rows.length) {
    const game = genericResult.rows[0];
    const homeOwner = await findTeamOwnerByRoleId(channel.guild, game.home_team_role_id).catch(() => null);
    const awayOwner = await findTeamOwnerByRoleId(channel.guild, game.away_team_role_id).catch(() => null);
    homeOwnerId = homeOwner?.id; awayOwnerId = awayOwner?.id;
  } else {
    const maddenResult = await pool.query(`SELECT * FROM madden_imported_games WHERE thread_id = $1`, [channel.id]).catch(() => ({ rows: [] }));
    if (maddenResult.rows.length) {
      const game = maddenResult.rows[0];
      const league = await getLeagueById(game.league_id).catch(() => null);
      const homeOwner = await getMaddenTeamOwnerForGameThread(channel.guild, league, game.home_team, game.home_team_role_id).catch(() => null);
      const awayOwner = await getMaddenTeamOwnerForGameThread(channel.guild, league, game.away_team, game.away_team_role_id).catch(() => null);
      homeOwnerId = homeOwner?.id; awayOwnerId = awayOwner?.id;
    }
  }
  if (!homeOwnerId || !awayOwnerId) return '';
  const [availA, availB] = await Promise.all([getUserAvailability(guildId, homeOwnerId), getUserAvailability(guildId, awayOwnerId)]);
  if (!availA || !availB) return "💡 Tip: both of you can save your availability on your Member Profile (**Set Availability**) so GG Sports can suggest shared windows here next time.";
  const windows = computeSharedAvailabilityWindows(availA, availB);
  if (!windows.length) return '⚠️ No obvious shared windows found based on saved availability — you may need to work out a one-off time.';
  return `💡 Shared availability windows: ${windows.slice(0, 5).map(formatSharedAvailabilityWindow).join(', ')}`;
}

// 7J-SCHEDULING: per Hxxdie — real information for a commissioner resolving
// a scheduling dispute, not "I messaged him." Every proposal + response,
// in order, with who and when.
async function buildSchedulingHistoryEmbed(guildId, gameSource, gameRef) {
  const result = await pool.query(
    `SELECT * FROM game_schedule_proposals WHERE guild_id = $1 AND game_source = $2 AND game_ref = $3 ORDER BY created_at ASC`,
    [guildId, gameSource, gameRef]
  ).catch(() => ({ rows: [] }));
  const NL = String.fromCharCode(10);
  const STATUS_LABELS = { pending: '🕐 Pending', accepted: '✅ Accepted', declined: '❌ Declined', countered: '🔁 Countered', superseded: '⏭️ Superseded' };
  const lines = result.rows.map(row => {
    const parts = [`<t:${row.proposed_at_epoch}:f>`, `proposed by <@${row.proposer_user_id}>`, STATUS_LABELS[row.status] || row.status];
    if (row.responded_at) parts.push(`responded <t:${Math.floor(new Date(row.responded_at).getTime() / 1000)}:R>`);
    return `• ${parts.join(' — ')}`;
  });
  return new EmbedBuilder()
    .setTitle('🗓️ Scheduling History')
    .setColor(0x5865F2)
    .setDescription(lines.length ? lines.join(NL) : 'No scheduling proposals recorded for this game yet.')
    .setFooter({ text: 'GG Sports • Scheduling' })
    .setTimestamp();
}

// 7J-SCHEDPICKER: per Hxxdie — "eliminate typing" in Propose a Game Time.
// Reuses the exact same date/time picker (buildDateTimePickerStepA/B) and
// finalizeTournamentDateTime/tournamentDiscordTimestamp the tournament
// scheduler already has proven out, just with a 'schedpropose' prefix
// instead of building a second date/time UI from scratch.
const schedProposeSessions = new Map();

async function finalizeSchedulingProposal(interaction, gameSource, gameRef, proposedEpoch) {
  const lookup = await findGameForScheduling(interaction.guild, gameSource, gameRef).catch(() => null);
  if (!lookup) { await interaction.editReply({ content: 'Could not find this game anymore.' }); return; }
  const { league, homeOwner, awayOwner, label } = lookup;
  if (![homeOwner?.id, awayOwner?.id].includes(interaction.user.id) && !(await userCanUseLeagueSetup(interaction, league))) {
    await interaction.editReply({ content: 'Only the two teams in this game (or staff) can propose a time.' });
    return;
  }
  const opponentId = interaction.user.id === homeOwner?.id ? awayOwner?.id : homeOwner?.id;

  // Supersede any still-pending proposal for this game before creating a new one.
  await pool.query(`UPDATE game_schedule_proposals SET status = 'superseded' WHERE game_source = $1 AND game_ref = $2 AND status = 'pending'`, [gameSource, gameRef]).catch(() => null);

  const proposalId = randomUUID();
  await pool.query(
    `INSERT INTO game_schedule_proposals (id, guild_id, league_id, game_ref, game_source, thread_id, proposer_user_id, responder_user_id, proposed_at_epoch, status)
     VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, 'pending')`,
    [proposalId, interaction.guild.id, league?.league_id || null, gameRef, gameSource, interaction.channelId, interaction.user.id, opponentId || null, proposedEpoch]
  );

  const embed = new EmbedBuilder()
    .setTitle('🗓️ Game Time Proposed')
    .setColor(0xFEE75C)
    .setDescription(`<@${interaction.user.id}> proposed a time for **${label}**:\n<t:${proposedEpoch}:F> (<t:${proposedEpoch}:R>)`)
    .setFooter({ text: 'GG Sports • Scheduling' })
    .setTimestamp();
  const buttons = [
    new ButtonBuilder().setCustomId(`schedaccept:${proposalId}`).setLabel('Accept').setEmoji('✅').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`scheddecline:${proposalId}`).setLabel('Decline').setEmoji('❌').setStyle(ButtonStyle.Danger),
    new ButtonBuilder().setCustomId(`schedcounter:${proposalId}`).setLabel('Counter').setEmoji('🔁').setStyle(ButtonStyle.Secondary),
  ];
  // 7J-SCHEDPUBLICFIX: per Hxxdie — this used to editReply() the final
  // proposal onto the same ephemeral picker message the flow started with.
  // Discord's ephemeral flag is fixed at the very first response to an
  // interaction and can never be un-set by a later edit — so the opponent,
  // who actually needs to click Accept/Decline/Counter, could never even
  // SEE this message, let alone use it. Posted as a genuinely new, public
  // message in the channel instead; the original ephemeral picker just
  // gets a small closing confirmation only the proposer needed anyway.
  const publicMessage = await interaction.channel.send({
    content: opponentId ? `<@${opponentId}>` : undefined,
    embeds: [embed],
    components: [new ActionRowBuilder().addComponents(buttons)],
    allowedMentions: { users: opponentId ? [opponentId] : [] },
  }).catch(() => null);
  await interaction.editReply({
    content: publicMessage ? '✅ Proposal sent — visible to both teams in this thread.' : '⚠️ Could not post the proposal to this thread. Try again.',
    embeds: [], components: [],
  }).catch(() => null);
}


const tournamentCreateSessions = new Map();
const tournamentEditSessions = new Map();
const tournamentPostponeSessions = new Map();
const leagueKickConfirmations = new Map();

// Shared by staff-initiated removal (Commissioner Panel Kick button, /league
// kick) and self-service leave (GM Panel / Team Owners Panel Leave Team
// buttons) — both remove team + league roles via the exact same
// confirm/cancel button handler already wired up below for /league kick
// (leaguekick_confirm:/leaguekick_cancel:), since that handler works purely
// off the stored `pending` object and doesn't care who populated it.
function presentLeagueRoleRemoval(interaction, { league, targetUser, teamRoleIds, teamRoleNames, removeLeagueRole, reason, requestedByUserId, isSelfLeave }) {
  const confirmId = randomUUID();
  leagueKickConfirmations.set(confirmId, {
    guildId: interaction.guild.id,
    leagueId: league.league_id,
    leagueName: league.league_name,
    targetUserId: targetUser.id,
    reason,
    teamRoleIds,
    removeLeagueRole,
    requestedBy: requestedByUserId,
  });
  setTimeout(() => leagueKickConfirmations.delete(confirmId), 5 * 60 * 1000); // Confirmation expires in 5 minutes.

  const rolesSummary = [
    teamRoleNames.length ? `Team role(s): **${teamRoleNames.join(', ')}**` : null,
    removeLeagueRole ? 'League member role' : null,
  ].filter(Boolean).join('\n');

  const confirmEmbed = new EmbedBuilder()
    .setTitle(isSelfLeave ? '⚠️ Confirm Leave Team' : '⚠️ Confirm Removal')
    .setColor(0xED4245)
    .setDescription(isSelfLeave
      ? `Leave your team in **${league.league_name}**?`
      : `Remove **${targetUser.username}** from **${league.league_name}**?`)
    .addFields(
      { name: 'Roles to remove', value: rolesSummary, inline: false },
      { name: 'Reason', value: reason, inline: false },
    )
    .setFooter({ text: 'This removes league/team roles only — it does not remove them from the Discord server.' });

  const confirmRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`leaguekick_confirm:${confirmId}`).setLabel(isSelfLeave ? 'Leave Team' : 'Confirm Removal').setStyle(ButtonStyle.Danger),
    new ButtonBuilder().setCustomId(`leaguekick_cancel:${confirmId}`).setLabel('Cancel').setStyle(ButtonStyle.Secondary),
  );
  return { embed: confirmEmbed, row: confirmRow };
}
// 7J-COMMANDHUB-GAMESELECT: modals can't contain select menus (Discord API
// limitation — TextInput only), so the panel's "Create League" flow is
// modal-for-name, then a real select menu for game type, rather than
// asking someone to correctly type "nba/mlb/nhl/cfb/fc/madden/general"
// freehand — the whole point being to prevent a misnamed game type quietly
// breaking that league's auto-setup (wrong team-name list, wrong
// standings/playoff format, etc.). Short-lived, in-memory, same pattern as
// leagueKickConfirmations above.
const pendingPanelLeagueCreations = new Map();
const commissionerSeasonHistorySessions = new Map();
// 7J-DUPEGAMEFIX: holds a cleanup preview's computed delete list between the
// dry-run reply and the confirm button, same session-token pattern used
// throughout the bot for any destructive two-step confirm.
const gameCleanupDuplicateSessions = new Map();
// 7J-WIPEALLGAMES: same session-token confirm pattern, for the "wipe every
// game record for a league" tool — deliberately separate from
// gameCleanupDuplicateSessions since it's a distinct, more sweeping action.
const gameWipeAllSessions = new Map();

// 7J-SEASONHISTORYV2: resolves the display label for whatever the wizard is
// currently filling in — the trophy name for "champion", or the configured
// award's real label (not just its internal key) for anything else.
function seasonHistoryTargetLabel(session) {
  if (session.pendingTarget === 'champion') return session.trophyName;
  if (session.pendingTarget === 'runnerup') return 'Runner-Up';
  const configured = (session.leagueAwardsConfig || []).find(a => a.key === session.pendingTarget);
  return configured?.label || session.pendingTarget;
}

// 7J-SEASONHISTORYTEAMPICKER: per Hxxdie — a StringSelectMenu hard-caps at
// 25 options, so a league with more teams than that was silently losing
// every team past the 25th alphabetically. Rather than a search step,
// multiple dropdowns cover the full list directly — up to 4 menus (100
// teams), each routed through the exact same seasonhistory_pick_team
// handler regardless of which menu the pick came from.
async function buildSeasonHistoryTeamPickerPayload(token, session) {
  const teams = await pool.query(`SELECT role_id, role_name FROM league_team_roles WHERE league_id = $1 ORDER BY role_name ASC LIMIT 100`, [session.leagueId]).catch(() => ({ rows: [] }));

  const components = [];
  for (let i = 0; i < teams.rows.length; i += 25) {
    const chunk = teams.rows.slice(i, i + 25);
    const chunkNumber = Math.floor(i / 25) + 1;
    const label = chunk[0].role_name.slice(0, 1).toUpperCase() + '-' + chunk[chunk.length - 1].role_name.slice(0, 1).toUpperCase();
    // 7J-SEASONHISTORYTEAMPICKER-FIX: per Hxxdie — every chunk's dropdown
    // was reusing the exact same customId ('seasonhistory_pick_team:' +
    // token) with no per-chunk suffix, which Discord rejects outright
    // (component custom ids must be unique within a single message) —
    // this was breaking the picker completely for any league with more
    // than 25 teams. The pick_team handler already extracts the token via
    // split(':')[1], which still works correctly with this extra suffix.
    const teamMenu = new StringSelectMenuBuilder()
      .setCustomId('seasonhistory_pick_team:' + token + ':' + chunkNumber)
      .setPlaceholder(teams.rows.length > 25 ? `Teams ${label} (${chunkNumber} of ${Math.ceil(teams.rows.length / 25)})` : 'Which team?')
      .addOptions(chunk.map(t => ({ label: t.role_name.slice(0, 100), value: t.role_id })));
    components.push(new ActionRowBuilder().addComponents(teamMenu));
  }

  const content = `Setting: **${seasonHistoryTargetLabel(session)}** — pick the team below${components.length > 1 ? ' (split across multiple dropdowns since this league has more than 25 teams)' : ''}.`;

  return { content, embeds: [], components };
}

// 7J-SEASONHISTORYV2: the wizard's home screen — shows current progress
// (champion set/not, each configured award set/not) and a select menu to
// pick what to fill in next. Re-shown after every pick completes, same
// "persistent builder screen" pattern as the tournament creation flow.
function buildSeasonHistoryWizardPayload(token) {
  const session = commissionerSeasonHistorySessions.get(token);
  if (!session) return { content: 'This session expired. Start over from Operations → Season History.', embeds: [], components: [] };

  const lines = [
    `**Season:** ${session.seasonLabel}`,
    `**${session.trophyName}:** ${session.champion ? `${session.champion.team} — <@${session.champion.userId}>` : '_Not set_'}`,
    `**Runner-Up:** ${session.runnerUp ? `${session.runnerUp.team} — <@${session.runnerUp.userId}>` : '_Not set_'}`,
  ];
  const awardEntries = Object.entries(session.awards).filter(([, a]) => a);
  if (awardEntries.length) {
    lines.push('', '**Awards set so far:**');
    for (const [, a] of awardEntries) lines.push(`• ${a.label}: ${a.player} (${a.team}) — <@${a.userId}>`);
  }
  if (session.notes) lines.push('', `**Notes:** ${session.notes}`);

  const embed = new EmbedBuilder()
    .setTitle('📜 Season History Builder')
    .setColor(0xFEE75C)
    .setDescription(lines.join('\n'))
    .setFooter({ text: 'GG Sports • Season History' });

  const options = [
    { label: session.trophyName, value: 'champion', emoji: '🏆' },
    { label: 'Runner-Up (optional)', value: 'runnerup', emoji: '🥈', description: session.runnerUp ? `Currently: ${session.runnerUp.team}` : undefined },
  ];
  for (const award of session.leagueAwardsConfig || []) {
    options.push({ label: award.label.slice(0, 100), value: award.key, emoji: award.tieredCosmetic ? '🎁' : undefined, description: session.awards[award.key] ? 'Already set — pick to change' : undefined });
  }
  const targetMenu = new StringSelectMenuBuilder()
    .setCustomId('seasonhistory_pick_target:' + token)
    .setPlaceholder('Pick what to set next')
    .addOptions(options.slice(0, 25));

  // 7J-SEASONHISTORYV2: content explicitly cleared here (not just omitted)
  // — the intermediate "Setting: X — pick the team/user" prompts set real
  // content text via interaction.update(), and Discord's update() only
  // changes fields you actually pass. Without this, that prompt text would
  // stay stuck above the embed forever after the first pick completes.
  return {
    content: null,
    embeds: [embed],
    components: [
      new ActionRowBuilder().addComponents(targetMenu),
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('seasonhistory_notes:' + token).setLabel('Add Notes').setEmoji('📝').setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('seasonhistory_submit:' + token).setLabel('Submit').setEmoji('✅').setStyle(ButtonStyle.Success),
        new ButtonBuilder().setCustomId('seasonhistory_cancel:' + token).setLabel('Cancel').setStyle(ButtonStyle.Danger),
      ),
    ],
  };
}

