        await pool.query(`UPDATE leagues SET game_key = $1 WHERE league_id = $2`, [gameKey, activeLeague.league_id]);
        await interaction.reply({ content: 'Game type for **' + activeLeague.league_name + '** set to **' + gameKey + '**.', ephemeral: true });
