// 7J-152TICKETQUICKACTIONS: after a claim/reviewing/resolved quick action,
// re-render the button row on the original ticket-opened message itself
// (not just the ephemeral reply) so e.g. "Claim Ticket" disappears once
// claimed instead of sitting there clickable and stale. interaction.message
// is the message the button lives on; Close Ticket's row is rebuilt fresh
// alongside it since it's deterministic from ticketId, no extra query needed.
async function refreshTicketInfoButtonsOnMessage(interaction) {
  const [, ticketId] = interaction.customId.split(':');
  const fresh = await pool.query(`SELECT * FROM support_tickets WHERE id = $1 LIMIT 1`, [ticketId]);
  if (!fresh.rows.length || !interaction.message) return;
  const ticket = fresh.rows[0];
  const infoRow = buildTicketInfoButtons(ticket);
  const components = infoRow ? [buildTicketCloseRow(ticketId), infoRow] : [buildTicketCloseRow(ticketId)];
  await interaction.message.edit({ components }).catch(() => null);
}

async function buildTicketDashboardEmbed(guildId, filter = 'open') {
  const summary = await pool.query(
    `SELECT
       COUNT(*) FILTER (WHERE status != 'closed')::int AS active_count,
       COUNT(*) FILTER (WHERE status = 'open')::int AS open_count,
       COUNT(*) FILTER (WHERE priority IN ('high', 'urgent') AND status != 'closed')::int AS high_priority_count,
       COUNT(*) FILTER (WHERE assigned_staff_user_id IS NULL AND status != 'closed')::int AS unclaimed_count,
       COUNT(*) FILTER (WHERE assigned_staff_user_id IS NOT NULL AND status != 'closed')::int AS claimed_count
     FROM support_tickets
     WHERE guild_id = $1`,
    [guildId]
  );

  let latest;
  if (filter === 'urgent') {
    latest = await pool.query(
      `SELECT * FROM support_tickets
       WHERE guild_id = $1 AND status != 'closed' AND priority IN ('high', 'urgent')
       ORDER BY created_at DESC
       LIMIT 8`,
      [guildId]
    );
  } else if (filter === 'unclaimed') {
    latest = await pool.query(
      `SELECT * FROM support_tickets
       WHERE guild_id = $1 AND status != 'closed' AND assigned_staff_user_id IS NULL
       ORDER BY created_at DESC
       LIMIT 8`,
      [guildId]
    );
  } else if (filter === 'reviewing') {
    latest = await pool.query(
      `SELECT * FROM support_tickets
       WHERE guild_id = $1 AND status = 'reviewing'
       ORDER BY created_at DESC
       LIMIT 8`,
      [guildId]
    );
  } else {
    latest = await pool.query(
      `SELECT * FROM support_tickets
       WHERE guild_id = $1 AND status != 'closed'
       ORDER BY created_at DESC
       LIMIT 8`,
      [guildId]
    );
  }

  const row = summary.rows[0] || {};
  const NL = String.fromCharCode(10);
  const latestText = latest.rows.length
    ? latest.rows.map(ticket => {
        const assigned = ticket.assigned_staff_user_id ? ' • <@' + ticket.assigned_staff_user_id + '>' : ' • Unclaimed';
        return '**' + shortTicketId(ticket.id) + '** — ' + ticket.ticket_type + ' • ' + ticket.priority + ' • ' + ticket.status + assigned;
      }).join(NL)
    : 'No active tickets.';

  return new EmbedBuilder()
    .setTitle('🎫 Ticket Dashboard')
    .setColor(0xffcc00)
    .addFields(
      { name: 'Active', value: String(row.active_count || 0), inline: true },
      { name: 'Open', value: String(row.open_count || 0), inline: true },
      { name: 'High/Urgent', value: String(row.high_priority_count || 0), inline: true },
      { name: 'Claimed', value: String(row.claimed_count || 0), inline: true },
      { name: 'Unclaimed', value: String(row.unclaimed_count || 0), inline: true },
      { name: 'Current View', value: filter, inline: true },
      { name: 'Latest Active Tickets', value: latestText, inline: false }
    )
    .setFooter({ text: 'GG Sports • Live Ticket Dashboard' })
    .setTimestamp();
}

async function saveTicketPanel(guildId, channelId, messageId) {
  await pool.query(
    `INSERT INTO ticket_panels (guild_id, channel_id, message_id, updated_at)
     VALUES ($1, $2, $3, NOW())
     ON CONFLICT (guild_id)
     DO UPDATE SET channel_id = $2, message_id = $3, updated_at = NOW()`,
    [guildId, channelId, messageId]
  );
}

async function updateTicketPanel(guild) {
  const panelResult = await pool.query(
    `SELECT channel_id, message_id FROM ticket_panels WHERE guild_id = $1`,
    [guild.id]
  );

  if (!panelResult.rows.length) return;
  const channel = await guild.channels.fetch(panelResult.rows[0].channel_id).catch(() => null);
  if (!channel || !channel.isTextBased()) return;
  const message = await channel.messages.fetch(panelResult.rows[0].message_id).catch(() => null);
  if (!message) return;
  await message.edit({ embeds: [await buildTicketDashboardEmbed(guild.id)], components: [buildTicketDashboardButtons()] }).catch(() => null);
}

function shortSportsbookId(gameId) {
  return String(gameId || '').split('-')[0];
}

function calculateAmericanOddsPayout(amount, odds) {
  const stake = Number(amount);
  const americanOdds = Number(odds);
  if (!Number.isInteger(stake) || stake <= 0 || !Number.isInteger(americanOdds) || americanOdds === 0) return 0;
  if (americanOdds > 0) return stake + Math.floor((stake * americanOdds) / 100);
  return stake + Math.floor((stake * 100) / Math.abs(americanOdds));
}

function americanOddsToDecimal(odds) {
  const americanOdds = Number(odds);
  if (americanOdds > 0) return 1 + americanOdds / 100;
  return 1 + 100 / Math.abs(americanOdds);
}

function calculateParlayPayout(amount, oddsList) {
  const stake = Number(amount);
  if (!Number.isInteger(stake) || stake <= 0 || !oddsList.length) return { combinedDecimal: 0, payout: 0 };
  const combinedDecimal = oddsList.reduce((total, odds) => total * americanOddsToDecimal(odds), 1);
  return { combinedDecimal, payout: Math.floor(stake * combinedDecimal) };
}

// Booking fee — 10% of NET winnings only (not the stake), mirroring real sportsbook
// vig/rake. Doesn't double-punish losers on top of the odds-based house edge already
// baked into -110/-110 lines. Burned (not redistributed) — same deflationary treatment
// as the Marketplace fee; together they're the economy's two real currency sinks.
// Applies uniformly to straight bets, parlays, and props — settlement is settlement.
const SPORTSBOOK_BOOKING_FEE_RATE = 0.10;

function computeSportsbookNetPayout(potentialPayout, stake) {
  const gross = Number(potentialPayout) || 0;
  const netWinnings = Math.max(0, gross - (Number(stake) || 0));
  const feeAmount = Math.floor(netWinnings * SPORTSBOOK_BOOKING_FEE_RATE);
  return { payout: gross - feeAmount, feeAmount };
}

// Stat props reuse the existing sportsbook spine (bet_type = 'stat_prop', home = Over,
// away = Under). statType/field map straight onto madden_player_weekly_stats'
// stat_type + raw_payload keys, so settlement is a direct lookup — no new stat pipeline.
const SPORTSBOOK_PROP_STAT_TYPES = {
  passing_yards: { label: 'Passing Yards', statType: 'passing', field: 'passYds' },
  passing_tds: { label: 'Passing TDs', statType: 'passing', field: 'passTDs' },
  rushing_yards: { label: 'Rushing Yards', statType: 'rushing', field: 'rushYds' },
  rushing_tds: { label: 'Rushing TDs', statType: 'rushing', field: 'rushTDs' },
  receiving_yards: { label: 'Receiving Yards', statType: 'receiving', field: 'recYds' },
  receiving_tds: { label: 'Receiving TDs', statType: 'receiving', field: 'recTDs' },
  receptions: { label: 'Receptions', statType: 'receiving', field: 'recCatches' },
  sacks: { label: 'Sacks', statType: 'defense', field: 'defSacks' },
  interceptions: { label: 'Interceptions (Defense)', statType: 'defense', field: 'defInts' },
};

async function settleParlaysForSportsbookGame(guildId, sportsbookGameId, winnerSide, issuedByUserId) {
  const parlayResult = await pool.query(
    `SELECT DISTINCT p.*
     FROM sportsbook_parlays p
     JOIN sportsbook_parlay_legs l ON l.parlay_id = p.id
     WHERE p.guild_id = $1 AND l.sportsbook_game_id = $2 AND p.status = 'open'`,
    [guildId, sportsbookGameId]
  );

  let settledCount = 0;
  let parlayPaid = 0;
  const wonParlays = [];

  for (const parlay of parlayResult.rows) {
    await pool.query(
      `UPDATE sportsbook_parlay_legs
       SET status = CASE WHEN side = $1 THEN 'won' ELSE 'lost' END
       WHERE parlay_id = $2 AND sportsbook_game_id = $3`,
      [winnerSide, parlay.id, sportsbookGameId]
    );

    const legs = await pool.query(`SELECT * FROM sportsbook_parlay_legs WHERE parlay_id = $1`, [parlay.id]);
    const anyLost = legs.rows.some(leg => leg.status === 'lost');
    const allSettled = legs.rows.every(leg => leg.status === 'won' || leg.status === 'lost');

    if (anyLost) {
      await pool.query(`UPDATE sportsbook_parlays SET status = 'lost', settled_at = NOW() WHERE id = $1`, [parlay.id]);
      settledCount += 1;
    } else if (allSettled) {
      await pool.query(`UPDATE sportsbook_parlays SET status = 'won', settled_at = NOW() WHERE id = $1`, [parlay.id]);
      const { payout, feeAmount } = computeSportsbookNetPayout(parlay.potential_payout, parlay.amount);
      await addCurrency(guildId, parlay.user_id, payout, 'sportsbook_parlay_win', 'Won parlay' + (feeAmount ? ` (booking fee ${feeAmount} burned)` : ''), issuedByUserId);
      await incrementRecognitionStat(guildId, parlay.user_id, 'sportsbook_wins', 1);
      await incrementRecognitionStat(guildId, parlay.user_id, 'sportsbook_profit', payout - Number(parlay.amount));
      await checkSportsbookAchievements(guildId, parlay.user_id, payout).catch(() => null);
      // 7J-43ACTIVITY: parlays can theoretically span legs from different
      // leagues (unusual, but not structurally prevented) — best-effort
      // attribute to the first leg's league. If it's null, this simply
      // doesn't hit the league-scoped table, same as any other action with
      // no clean single-league attribution — still counts toward server +
      // universal either way.
      const parlayLeagueIdResult = await pool.query(
        `SELECT sg.league_id FROM sportsbook_parlay_legs spl
         JOIN sportsbook_games sg ON sg.id = spl.sportsbook_game_id
         WHERE spl.parlay_id = $1 LIMIT 1`,
        [parlay.id]
      ).catch(() => ({ rows: [] }));
      const parlayLeagueId = parlayLeagueIdResult.rows[0]?.league_id || null;
      await addRecognitionPoints(guildId, parlay.user_id, 6, 2, parlayLeagueId);
      await pool.query(`UPDATE sportsbook_parlays SET potential_payout = $2 WHERE id = $1`, [parlay.id, payout]);
      settledCount += 1;
      parlayPaid += payout;
      wonParlays.push({
        id: parlay.id,
        user_id: parlay.user_id,
        amount: Number(parlay.amount),
        potential_payout: payout,
        leg_count: legs.rows.length,
      });
    }
  }

  return { settledCount, parlayPaid, wonParlays };
}

// Replaces the old short-ID-labeled buttons (max 5, and the code meant nothing
// without cross-referencing the embed text — the actual "chaotic" complaint).
// Select menus support 25 real-named options each, so the visible label is always
// the actual matchup/prop, never a code; the game's UUID rides invisibly as the
// option value. Same downstream sportsbook_pick_game/pick_side flow either way.
function buildSportsbookBoardComponents(rows) {
  const moneylines = rows.filter(r => (r.bet_type || 'moneyline') === 'moneyline').slice(0, 25);
  const playerProps = rows.filter(r => r.bet_type === 'stat_prop').slice(0, 25);
  const freeformProps = rows.filter(r => r.bet_type === 'freeform_prop').slice(0, 25);

  const components = [];

  if (moneylines.length) {
    components.push(new ActionRowBuilder().addComponents(
      new StringSelectMenuBuilder()
        .setCustomId('sportsbook_pick_game_moneyline')
        .setPlaceholder('🏈 Bet a Moneyline')
        .addOptions(moneylines.map(row => ({
          label: stripDiscordEmojiMarkupForLabel(`${row.away_label} @ ${row.home_label}`).slice(0, 100),
          value: row.id,
          description: `${formatAmericanOdds(row.away_odds)} / ${formatAmericanOdds(row.home_odds)}`.slice(0, 100),
        })))
    ));
  }

  if (playerProps.length) {
    components.push(new ActionRowBuilder().addComponents(
      new StringSelectMenuBuilder()
        .setCustomId('sportsbook_pick_game_prop')
        .setPlaceholder('🎯 Bet a Player Prop')
        .addOptions(playerProps.map(row => ({
          label: `${row.subject_display_name} O/U ${row.stat_threshold} ${SPORTSBOOK_PROP_STAT_TYPES[row.stat_key]?.label || row.stat_key}`.slice(0, 100),
          value: row.id,
          description: `Over ${formatAmericanOdds(row.home_odds)} / Under ${formatAmericanOdds(row.away_odds)}`.slice(0, 100),
        })))
    ));
  }

  if (freeformProps.length) {
    components.push(new ActionRowBuilder().addComponents(
      new StringSelectMenuBuilder()
        .setCustomId('sportsbook_pick_game_freeform')
        .setPlaceholder('🎫 Bet a Featured Prop')
        .addOptions(freeformProps.map(row => ({
          label: row.game_label.slice(0, 100),
          value: row.id,
          description: `${row.home_label} ${formatAmericanOdds(row.home_odds)} / ${row.away_label} ${formatAmericanOdds(row.away_odds)}`.slice(0, 100),
        })))
    ));
  }

  components.push(new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('sportsbook_quick_mybets').setLabel('My Bets').setEmoji('📋').setStyle(ButtonStyle.Secondary),
    new ButtonBuilder().setCustomId('sportsbook_quick_leaderboards').setLabel('Leaderboards').setEmoji('🏅').setStyle(ButtonStyle.Secondary),
    new ButtonBuilder().setCustomId('sportsbook_quick_parlay').setLabel('Build a Parlay').setEmoji('🧾').setStyle(ButtonStyle.Primary),
  ));

  return components;
}

function buildSportsbookSideButtons(game) {
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder()
      .setCustomId('sportsbook_pick_side:' + game.id + ':away')
      .setLabel(stripDiscordEmojiMarkupForLabel(game.away_label) + ' ML ' + game.away_odds)
      .setStyle(ButtonStyle.Primary),
    new ButtonBuilder()
      .setCustomId('sportsbook_pick_side:' + game.id + ':home')
      .setLabel(stripDiscordEmojiMarkupForLabel(game.home_label) + ' ML ' + game.home_odds)
      .setStyle(ButtonStyle.Success)
  );
}

// 7J-19EMOJI: select-menu option labels and button labels are plain text only —
// unlike embed text, Discord does NOT render <:name:id> custom emoji markup
// inside them, so team labels built for embeds (which bake the emoji markup
// directly into the string, e.g. homeLabel = `${homeEmoji} ${team}`) show up as
// raw junk text ("<:packers:1522016232876802088> Packers") in these contexts
// instead of an icon. Strip it specifically here; embed text elsewhere is
// unaffected and still renders the real emoji correctly.
function stripDiscordEmojiMarkupForLabel(text) {
  return String(text || '').replace(/<a?:\w+:\d+>\s*/g, '').trim();
}

// "ML -110" reads fine for moneylines but oddly for a prop line ("Under 275.5 Passing
// Yards ML -110") — use plain odds for props instead.
function sportsbookOddsLabelSuffix(row) {
  return row.bet_type && row.bet_type !== 'moneyline' ? '' : ' ML';
}

function buildSportsbookEmbed(settings, rows) {
  const NL = String.fromCharCode(10);
  const embed = new EmbedBuilder()
    .setTitle('Sportsbook')
    .setColor(0x57F287)
    .setFooter({ text: 'GG Sports • Sportsbook' })
    .setTimestamp();

  if (!rows.length) {
    embed.setDescription('No open sportsbook games right now.');
    return embed;
  }

  const lines = rows.map(row => {
    const oddsSuffix = sportsbookOddsLabelSuffix(row);
    return '**' + shortSportsbookId(row.id) + ' • ' + row.game_label + '**' + NL +
      row.away_label + oddsSuffix + ' ' + row.away_odds + ' vs ' + row.home_label + oddsSuffix + ' ' + row.home_odds + NL +
      'Status: **' + row.status + '** • Bet with `/placebet`';
  });

  embed.setDescription(lines.join(NL + NL));
  return embed;
}

// American odds convention requires an explicit + on positive numbers — plain
// integers were printing "130" instead of "+130", which doesn't read as odds at
// all to anyone used to a real sportsbook.
function formatAmericanOdds(odds) {
  const n = Number(odds);
  if (!Number.isFinite(n)) return String(odds);
  return n > 0 ? `+${n}` : `${n}`;
}

async function buildParlayWizardPayload(guildId, userId) {
  const NL = String.fromCharCode(10);
  const draft = getParlayDraft(guildId, userId) || { legs: [] };
  const usedGameIds = new Set(draft.legs.map(leg => leg.gameId));

  const embed = new EmbedBuilder()
    .setTitle('🧾 Build a Parlay')
    .setColor(0x5865F2)
    .setFooter({ text: 'GG Sports • Sportsbook — 2 to 4 legs' })
    .setTimestamp();

  if (draft.legs.length) {
    embed.setDescription(draft.legs.map((leg, i) => `${i + 1}. **${leg.sideLabel}** ${formatAmericanOdds(leg.odds)} — ${leg.label}`).join(NL));
  } else {
    embed.setDescription('No legs added yet — pick your first one below.');
  }

  const components = [];

  if (draft.legs.length < 4) {
    const openResult = await pool.query(
      `SELECT * FROM sportsbook_games WHERE guild_id = $1 AND status = 'open' ORDER BY created_at DESC LIMIT 75`,
      [guildId]
    );
    const available = openResult.rows.filter(row => !usedGameIds.has(row.id)).slice(0, 25);
    if (available.length) {
      components.push(new ActionRowBuilder().addComponents(
        new StringSelectMenuBuilder()
          .setCustomId('sportsbook_parlay_add_leg')
          .setPlaceholder(draft.legs.length ? `Add leg ${draft.legs.length + 1}` : 'Choose your first leg')
          .addOptions(available.map(row => {
            const isProp = row.bet_type === 'stat_prop';
            const isFreeform = row.bet_type === 'freeform_prop';
            const label = stripDiscordEmojiMarkupForLabel(isProp
              ? `${row.subject_display_name} O/U ${row.stat_threshold} ${SPORTSBOOK_PROP_STAT_TYPES[row.stat_key]?.label || row.stat_key}`
              : isFreeform ? row.game_label : `${row.away_label} @ ${row.home_label}`);
            return { label: label.slice(0, 100), value: row.id, description: `${formatAmericanOdds(row.away_odds)} / ${formatAmericanOdds(row.home_odds)}`.slice(0, 100) };
          }))
      ));
    }
  }

  const actionRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('sportsbook_parlay_cancel').setLabel('Cancel').setStyle(ButtonStyle.Secondary),
  );
  if (draft.legs.length >= 2) {
    actionRow.addComponents(new ButtonBuilder().setCustomId('sportsbook_parlay_place').setLabel(`Place Parlay (${draft.legs.length} legs)`).setEmoji('✅').setStyle(ButtonStyle.Success));
  }
  components.push(actionRow);

  return { content: null, embeds: [embed], components };
}


async function buildSportsbookPanelEmbed(guildId) {
  const NL = String.fromCharCode(10);
  const openResult = await pool.query(
    `SELECT g.*,
       COALESCE(SUM(b.amount), 0)::int AS total_handle,
       COUNT(b.id)::int AS bet_count
     FROM sportsbook_games g
     LEFT JOIN sportsbook_bets b ON b.sportsbook_game_id = g.id
     WHERE g.guild_id = $1 AND g.status = 'open'
     GROUP BY g.id
     ORDER BY g.created_at DESC
     LIMIT 75`,
    [guildId]
  );

  // Sectioned by bet type — no exposed short-ID codes anywhere in here. Selection
  // now happens via select menus (real matchup/prop names as the visible option),
  // so there's nothing for a code to need to correlate to anymore.
  const moneylines = openResult.rows.filter(r => (r.bet_type || 'moneyline') === 'moneyline');
  const playerProps = openResult.rows.filter(r => r.bet_type === 'stat_prop');
  const freeformProps = openResult.rows.filter(r => r.bet_type === 'freeform_prop');

  const embed = new EmbedBuilder()
    .setTitle('🏆 GG Sports  •  Sportsbook')
    .setColor(0x057B33)
    .setFooter({ text: 'GG Sports • Live Sportsbook Board' })
    .setTimestamp();

  // 7J-SPORTGROUPING: per Hxxdie — everything was rendering under one
  // hardcoded "🏈 MONEYLINES" regardless of sport (an MLB matchup showed a
  // football emoji), and multiple leagues of the same sport were only
  // distinguishable by an accidental double-prefix in team names that got
  // cleaned up separately. Now groups by actual sport with the right
  // emoji, and only prefixes a line with its league name when that
  // specific sport has more than one distinct league among the currently
  // open lines — a guild running just one league per sport (the common
  // case) sees no added clutter at all.
  const distinctLeagueIds = [...new Set(openResult.rows.map(r => r.league_id).filter(Boolean))];
  const leagueLookup = new Map();
  if (distinctLeagueIds.length) {
    const leagueRows = await pool.query(
      `SELECT league_id, league_name, game_key FROM leagues WHERE league_id = ANY($1::uuid[])`,
      [distinctLeagueIds]
    ).catch(() => ({ rows: [] }));
    for (const row of leagueRows.rows) leagueLookup.set(row.league_id, row);
  }
  const sportEmoji = { madden: '🏈', nfl: '🏈', nba: '🏀', nhl: '🏒', mlb: '⚾', fc: '⚽', cfb: '🏈' };
  function groupBySport(rows) {
    const bySport = new Map();
    for (const row of rows) {
      const leagueInfo = leagueLookup.get(row.league_id);
      const sportKey = leagueInfo?.game_key || 'other';
      if (!bySport.has(sportKey)) bySport.set(sportKey, { emoji: sportEmoji[sportKey] || '🏆', label: sportKey.toUpperCase(), rows: [], leagueNames: new Set() });
      const group = bySport.get(sportKey);
      group.rows.push(row);
      if (leagueInfo?.league_name) group.leagueNames.add(leagueInfo.league_name);
    }
    return [...bySport.values()].sort((a, b) => b.rows.length - a.rows.length);
  }
  function leaguePrefix(group, row) {
    if (group.leagueNames.size <= 1) return '';
    const name = leagueLookup.get(row.league_id)?.league_name;
    return name ? `[${name}] ` : '';
  }

  // 7J-FIELDCAP: sport-grouping multiplies field count (one per section per
  // sport instead of one per section total) — safe for the realistic case
  // of a couple sports per guild, but capped defensively so a guild running
  // many sports/leagues at once can't blow past Discord's embed limits.
  let fieldsRemaining = 20;
  function addCappedField(name, value) {
    if (fieldsRemaining <= 0) return;
    embed.addFields({ name, value, inline: false });
    fieldsRemaining -= 1;
  }

  if (moneylines.length) {
    for (const group of groupBySport(moneylines)) {
      addCappedField(
        `${group.emoji} MONEYLINES — ${group.label}`,
        group.rows.slice(0, 8).map(row =>
          `**${leaguePrefix(group, row)}${row.away_label}** ${formatAmericanOdds(row.away_odds)}  @  **${leaguePrefix(group, row)}${row.home_label}** ${formatAmericanOdds(row.home_odds)}${NL}` +
          `↳ ${row.bet_count} bet(s) • ${row.total_handle} handle`
        ).join(NL).slice(0, 1024)
      );
    }
  }

  if (playerProps.length) {
    for (const group of groupBySport(playerProps)) {
      addCappedField(
        `🎯 PLAYER PROPS — ${group.label}`,
        group.rows.slice(0, 8).map(row => {
          const isStandardVig = Number(row.home_odds) === -110 && Number(row.away_odds) === -110;
          // 7J-PROPODDSCLUTTER: per Hxxdie — every prop showing "Over -110 •
          // Under -110" underneath it was pure repetition when that's the
          // standard default for every prop anyway. Only shown now when a
          // prop's odds were actually customized away from that default
          // (staff can set custom odds per prop via /sportsbook createprop)
          // — real information stays visible, the redundant common case
          // doesn't.
          return `**${leaguePrefix(group, row)}${row.subject_display_name}** — O/U ${row.stat_threshold} ${SPORTSBOOK_PROP_STAT_TYPES[row.stat_key]?.label || row.stat_key}` +
            (isStandardVig ? '' : `${NL}↳ Over ${formatAmericanOdds(row.home_odds)} • Under ${formatAmericanOdds(row.away_odds)}`);
        }).join(NL).slice(0, 1024)
      );
    }
  }

  if (freeformProps.length) {
    for (const group of groupBySport(freeformProps)) {
      addCappedField(
        `🎫 FEATURED PROPS — ${group.label}`,
        group.rows.slice(0, 8).map(row =>
          `**${leaguePrefix(group, row)}${row.game_label}**${NL}↳ ${row.home_label} ${formatAmericanOdds(row.home_odds)} • ${row.away_label} ${formatAmericanOdds(row.away_odds)}`
        ).join(NL).slice(0, 1024)
      );
    }
  }

  if (!moneylines.length && !playerProps.length && !freeformProps.length) {
    embed.addFields({ name: 'Open Lines', value: 'No open sportsbook lines right now — check back soon.', inline: false });
  }

  return embed;
}

async function saveSportsbookPanel(guildId, channelId, messageId) {
  await pool.query(
    `INSERT INTO sportsbook_panels (guild_id, channel_id, message_id, updated_at)
     VALUES ($1, $2, $3, NOW())
     ON CONFLICT (guild_id)
     DO UPDATE SET channel_id = $2, message_id = $3, updated_at = NOW()`,
    [guildId, channelId, messageId]
  );
}

async function updateSportsbookPanel(guild) {
  if (!guild) return;
  await refreshAllMultiChannelPanelPostings(guild, 'sportsbook');
}

function buildMyBetsEmbed(settings, rows) {
  const NL = String.fromCharCode(10);
  const embed = new EmbedBuilder()
    .setTitle('My Sportsbook Bets')
    .setColor(0x5865F2)
    .setFooter({ text: 'GG Sports • My Bets' })
    .setTimestamp();

  if (!rows.length) {
    embed.setDescription('No recent bets found.');
    return embed;
  }

  const lines = rows.map(row => {
    const sideLabel = row.side === 'home' ? row.home_label : row.away_label;
    return '**' + shortSportsbookId(row.id) + '** — ' + row.game_label + ' • ' + sideLabel + ' ML ' + row.odds + NL +
      'Stake: ' + settings.currency_icon + ' ' + row.amount + ' • Potential payout: ' + settings.currency_icon + ' ' + row.potential_payout + ' • ' + row.status;
  });

  embed.setDescription(lines.join(NL + NL));
  return embed;
}

function buildBettingHistoryEmbed(settings, user, summary, rows) {
  const NL = String.fromCharCode(10);
  const totalBets = Number(summary.total_bets || 0);
  const wins = Number(summary.wins || 0);
  const losses = Number(summary.losses || 0);
  const open = Number(summary.open_bets || 0);
  const totalWagered = Number(summary.total_wagered || 0);
  const totalWon = Number(summary.total_won || 0);
  const netProfit = totalWon - totalWagered;

  const embed = new EmbedBuilder()
    .setTitle(user.username + ' • Betting History')
    .setColor(0x5865F2)
    .setThumbnail(user.displayAvatarURL({ dynamic: true }))
    .addFields(
      { name: 'Bets', value: String(totalBets), inline: true },
      { name: 'Record', value: wins + '-' + losses, inline: true },
      { name: 'Open Bets', value: String(open), inline: true },
      { name: 'Total Wagered', value: settings.currency_icon + ' ' + totalWagered, inline: true },
      { name: 'Total Won', value: settings.currency_icon + ' ' + totalWon, inline: true },
      { name: 'Net Profit', value: settings.currency_icon + ' ' + netProfit, inline: true }
    )
    .setFooter({ text: 'GG Sports • Betting History' })
    .setTimestamp();

  if (!rows.length) {
    embed.addFields({ name: 'Recent Bets', value: 'No recent bets found.', inline: false });
    return embed;
  }

  const lines = rows.map(row => {
    const sideLabel = row.side === 'home' ? row.home_label : row.away_label;
    const wonText = row.status === 'won' ? ' • Paid: ' + settings.currency_icon + ' ' + row.potential_payout : '';
    return '**' + shortSportsbookId(row.id) + '** — ' + row.game_label + ' • ' + sideLabel + ' ML ' + row.odds + NL +
      'Stake: ' + settings.currency_icon + ' ' + row.amount + ' • ' + row.status + wonText;
  });

  embed.addFields({ name: 'Recent Bets', value: lines.join(NL + NL).slice(0, 3000), inline: false });
  return embed;
}

function buildBettingLeaderboardEmbed(settings, rows) {
  const NL = String.fromCharCode(10);
  const embed = new EmbedBuilder()
    .setTitle('Sportsbook Leaderboard')
    .setColor(0xFEE75C)
    .setFooter({ text: 'GG Sports • Betting Leaderboard' })
    .setTimestamp();

  if (!rows.length) {
    embed.setDescription('No settled betting results yet.');
    return embed;
  }

  const lines = rows.map((row, index) => {
    const totalWagered = Number(row.total_wagered || 0);
    const totalWon = Number(row.total_won || 0);
    const netProfit = totalWon - totalWagered;
    const wins = Number(row.wins || 0);
    const losses = Number(row.losses || 0);
    return '**' + (index + 1) + '. <@' + row.user_id + '>** — Net: ' + settings.currency_icon + ' ' + netProfit +
      ' • Record: ' + wins + '-' + losses + ' • Wagered: ' + settings.currency_icon + ' ' + totalWagered + ' • Won: ' + settings.currency_icon + ' ' + totalWon;
  });

  embed.setDescription(lines.join(NL));
  return embed;
}

const ACTIVITY_MILESTONES = [
  { key: 'activity_100', points: 100, title: 'Active Member', reward: 50 },
  { key: 'activity_500', points: 500, title: 'Veteran Grinder', reward: 150 },
  { key: 'activity_1000', points: 1000, title: 'Certified Grinder', reward: 300 },
  { key: 'activity_2500', points: 2500, title: 'Elite Contributor', reward: 750 },
  { key: 'activity_5000', points: 5000, title: 'Community Icon', reward: 1500 },
];

// 7J-40ACHIEVE: Track G — Achievements, sportsbook tier. Cumulative
// lifetime thresholds, same shape/claim-once semantics as
// ACTIVITY_MILESTONES above, checked against user_recognition's live
// counters (sportsbook_wins/sportsbook_profit already tracked on every
// settled bet before this session; total_wagered is new, incremented at
// bet-placement time). single_win is different in kind — checked once per
// bet at settlement against that one bet's own payout, not a running total.
// Thresholds/rewards here are a reasonable starting point, not final —
// easy to retune since they're just data, not scattered through logic.
const SPORTSBOOK_ACHIEVEMENTS = [
  { key: 'sb_wagered_1000', type: 'wagered', threshold: 1000, title: 'High Roller', reward: 100 },
  // 7J-60ITEMREWARD: per Hxxdie, Whale also unlocks the exclusive Casino Background
  // (matched by name — see the is_award_only migration above). itemNamePattern is
  // optional on every entry here; only these two currently carry one.
  { key: 'sb_wagered_10000', type: 'wagered', threshold: 10000, title: 'Whale', reward: 500, itemNamePattern: 'casino' },
  { key: 'sb_wagered_50000', type: 'wagered', threshold: 50000, title: 'Casino Legend', reward: 2000 },
  { key: 'sb_profit_2500', type: 'profit', threshold: 2500, title: 'In the Green', reward: 200 },
  { key: 'sb_profit_10000', type: 'profit', threshold: 10000, title: 'Sharp', reward: 750 },
  { key: 'sb_profit_50000', type: 'profit', threshold: 50000, title: 'The House Fears You', reward: 3000 },
  { key: 'sb_bigwin_1000', type: 'single_win', threshold: 1000, title: 'Big Winner', reward: 200 },
  // Jackpot also unlocks the exclusive Money Rain Effect, per Hxxdie.
  { key: 'sb_bigwin_5000', type: 'single_win', threshold: 5000, title: 'Jackpot', reward: 1000, itemNamePattern: 'money rain' },
];

// Generic achievement grant: dedup via achievements_claimed, pays currency
// once, returns whether it was newly granted (false if already claimed —
// callers use this to decide whether to announce/log). itemNamePattern is
// optional — when present, also grants a matching is_award_only shop item
// (e.g. Casino Background for the Whale milestone) via grantAwardItem,
// bypassing the shop/currency entirely, same as any other award item. A
// missing/renamed item is best-effort: it won't roll back the already-
// committed currency payout or dedup row, just silently skips the item.
async function grantAchievement(guildId, leagueId, userId, achievementKey, achievementType, title, rewardAmount, itemNamePattern = null) {
  if (!guildId || !userId || !achievementKey) return false;
  const claimedResult = await pool.query(
    `INSERT INTO achievements_claimed (guild_id, league_id, user_id, achievement_key, achievement_type, title, reward_amount)
     VALUES ($1, $2, $3, $4, $5, $6, $7)
     ON CONFLICT (guild_id, user_id, achievement_key) DO NOTHING
     RETURNING achievement_key`,
    [guildId, leagueId ? String(leagueId) : null, userId, achievementKey, achievementType, title || null, Number(rewardAmount || 0)]
  ).catch(() => ({ rows: [] }));
  if (!claimedResult.rows.length) return false;
  if (Number(rewardAmount) > 0) {
    await addCurrency(guildId, userId, Number(rewardAmount), 'achievement', title || achievementKey, null).catch(() => null);
  }
  if (itemNamePattern) {
    const item = await findAwardOnlyShopItemByNamePattern(guildId, itemNamePattern).catch(() => null);
    if (item) {
      await grantAwardItem(guildId, userId, item.id, title || achievementKey).catch(() => null);
    }
  }
  return true;
}

// Checks a user's live sportsbook counters against SPORTSBOOK_ACHIEVEMENTS
// and grants any newly-crossed thresholds. singleWinAmount is only passed
// at bet-settlement time (checked against that one payout, not cumulative).
async function checkSportsbookAchievements(guildId, userId, singleWinAmount = null) {
  const profileResult = await pool.query(
    `SELECT sportsbook_profit, total_wagered FROM user_recognition WHERE guild_id = $1 AND user_id = $2 LIMIT 1`,
    [guildId, userId]
  ).catch(() => ({ rows: [] }));
  const profile = profileResult.rows[0] || {};
  const wagered = Number(profile.total_wagered || 0);
  const profit = Number(profile.sportsbook_profit || 0);

  for (const achievement of SPORTSBOOK_ACHIEVEMENTS) {
    let qualifies = false;
    if (achievement.type === 'wagered') qualifies = wagered >= achievement.threshold;
    else if (achievement.type === 'profit') qualifies = profit >= achievement.threshold;
    else if (achievement.type === 'single_win') qualifies = singleWinAmount != null && Number(singleWinAmount) >= achievement.threshold;
    if (!qualifies) continue;
    await grantAchievement(guildId, null, userId, achievement.key, 'sportsbook_milestone', achievement.title, achievement.reward, achievement.itemNamePattern || null);
  }
}

// 7J-PUBLICPREP-INTENTS: trackPassiveMessageActivity (message-content-based
// activity points) removed along with the MessageContent intent — see the
// intents block near the top of the file. user_message_activity_cooldown's
// CREATE TABLE was removed too; per Hxxdie's standing convention, dead
// things get removed completely rather than left as unused scaffolding.

// 7J-43ACTIVITY: passive voice activity. In-memory session tracking
// (guildId:userId -> session state) rather than a persisted table —
// deliberate simplicity tradeoff: a bot restart mid-session loses whatever
// wasn't yet awarded, which is an acceptable, low-severity edge case for a
// passive point trickle, not worth the complexity of crash-safe session
// persistence.
//
// Per Hxxdie: solo voice time shouldn't earn anything — a session only
// accrues while 2+ non-bot members share the same channel. Each session
// tracks accumulatedMs (finalized eligible time) plus segmentStartAt (when
// the *current* eligible stretch began, or null if currently alone/
// ineligible) rather than a single join-to-leave timer, since eligibility
// can flip on and off repeatedly within one continuous voice session as
// other people join and leave around this user.
const activeVoiceSessions = new Map();

function voiceSessionKey(guildId, userId) {
  return `${guildId}:${userId}`;
}

function getEligibleVoiceMemberCount(guild, channelId, afkChannelId) {
  if (!channelId || channelId === afkChannelId) return 0;
  const channel = guild.channels.cache.get(channelId);
  if (!channel?.members) return 0;
  let count = 0;
  for (const member of channel.members.values()) {
    if (!member.user.bot) count += 1;
  }
  return count;
}

async function finalizeVoiceSession(guildId, userId, session) {
  let totalMs = session.accumulatedMs;
  if (session.segmentStartAt != null) totalMs += Date.now() - session.segmentStartAt;
  const minutes = Math.floor(totalMs / 60000);
  if (minutes > 0) {
    await addActivityPoints(guildId, userId, minutes * 0.2, 0).catch(error => console.warn('[7J-43ACTIVITY] voice tracking failed:', error?.message || error));
  }
}

// Re-checks whether a channel currently has 2+ real members and starts/stops
// the eligible-time segment for every tracked session in that channel
// accordingly. Called for both the channel someone just left and the
// channel they just joined, since one person's move can flip *other*
// people's eligibility too (e.g. the second person joining an
// otherwise-solo channel makes both of them eligible at once; the second
// person leaving makes the remaining one solo again).
function reevaluateVoiceChannelEligibility(guild, channelId, afkChannelId) {
  if (!channelId || channelId === afkChannelId) return;
  const isEligible = getEligibleVoiceMemberCount(guild, channelId, afkChannelId) >= 2;
  for (const session of activeVoiceSessions.values()) {
    if (session.channelId !== channelId) continue;
    if (isEligible && session.segmentStartAt === null) {
      session.segmentStartAt = Date.now();
    } else if (!isEligible && session.segmentStartAt !== null) {
      session.accumulatedMs += Date.now() - session.segmentStartAt;
      session.segmentStartAt = null;
    }
  }
}

async function trackVoiceActivity(oldState, newState) {
  const guild = newState.guild || oldState.guild;
  const userId = newState.id || oldState.id;
  const isBot = (newState.member || oldState.member)?.user?.bot;
  if (!guild || !userId || isBot) return;
  const guildId = guild.id;
  const key = voiceSessionKey(guildId, userId);
  const afkChannelId = guild.afkChannelId || null;

  const oldChannelId = oldState.channelId;
  const newChannelId = newState.channelId;
  if (oldChannelId === newChannelId) return; // mute/deafen/etc — no channel change, nothing to do

  const wasInRealChannel = oldChannelId && oldChannelId !== afkChannelId;
  const isInRealChannel = newChannelId && newChannelId !== afkChannelId;

  // Left a channel this user had a session in — finalize whatever eligible
  // time accrued and award it.
  if (wasInRealChannel && activeVoiceSessions.has(key)) {
    const session = activeVoiceSessions.get(key);
    activeVoiceSessions.delete(key);
    await finalizeVoiceSession(guildId, userId, session);
  }

  // Joined a new real channel — start a fresh session, not yet eligible
  // until the re-evaluation below confirms 2+ people are actually present.
  if (isInRealChannel) {
    activeVoiceSessions.set(key, { channelId: newChannelId, segmentStartAt: null, accumulatedMs: 0 });
  }

  if (wasInRealChannel) reevaluateVoiceChannelEligibility(guild, oldChannelId, afkChannelId);
  if (isInRealChannel) reevaluateVoiceChannelEligibility(guild, newChannelId, afkChannelId);
}

async function getActivitySettings(guildId) {
  await pool.query(
    `INSERT INTO activity_settings (guild_id)
     VALUES ($1)
     ON CONFLICT (guild_id) DO NOTHING`,
    [guildId]
  );

  const result = await pool.query(`SELECT * FROM activity_settings WHERE guild_id = $1`, [guildId]);
  return result.rows[0] || { guild_id: guildId, milestone_channel_id: null };
}

function buildMilestonesEmbed(user, activityPoints, claimedKeys) {
  const NL = String.fromCharCode(10);
  const claimed = new Set(claimedKeys || []);
  const lines = ACTIVITY_MILESTONES.map(milestone => {
    const unlocked = Number(activityPoints || 0) >= milestone.points;
    const claimedText = claimed.has(milestone.key) ? '✅ Claimed' : unlocked ? '🎁 Unlocked' : '🔒 Locked';
    return '**' + milestone.title + '** — ' + milestone.points + ' Activity Points • Reward: ' + milestone.reward + ' • ' + claimedText;
  });

  return new EmbedBuilder()
    .setTitle(user.username + ' • Activity Milestones')
    .setColor(0x57F287)
    .setThumbnail(user.displayAvatarURL({ dynamic: true }))
    .setDescription(lines.join(NL))
    .setFooter({ text: 'GG Sports • Activity Milestones' })
    .setTimestamp();
}

function buildMilestoneAnnouncementEmbed(userId, milestone, settings) {
  return new EmbedBuilder()
    .setTitle('⚡ Activity Milestone Unlocked')
    .setColor(0xFEE75C)
    .addFields(
      { name: 'Member', value: '<@' + userId + '>', inline: true },
      { name: 'Milestone', value: milestone.title, inline: true },
      { name: 'Activity Required', value: String(milestone.points), inline: true },
      { name: 'Reward', value: settings.currency_icon + ' ' + milestone.reward + ' ' + settings.currency_name, inline: false }
    )
    .setFooter({ text: 'GG Sports • Activity Rewards' })
    .setTimestamp();
}

async function checkActivityMilestones(guildId, userId) {
  const profileResult = await pool.query(
    `SELECT activity_points FROM user_recognition WHERE guild_id = $1 AND user_id = $2 LIMIT 1`,
    [guildId, userId]
  );

  const activityPoints = Number(profileResult.rows[0]?.activity_points || 0);
  const settings = await getCurrencySettings(guildId);
  const activitySettings = await getActivitySettings(guildId);

  for (const milestone of ACTIVITY_MILESTONES) {
    if (activityPoints < milestone.points) continue;

    const claimedResult = await pool.query(
      `INSERT INTO activity_milestones_claimed (guild_id, user_id, milestone_key)
       VALUES ($1, $2, $3)
       ON CONFLICT (guild_id, user_id, milestone_key) DO NOTHING
       RETURNING milestone_key`,
      [guildId, userId, milestone.key]
    );

    if (!claimedResult.rows.length) continue;

    if (milestone.reward > 0) {
      await addCurrency(guildId, userId, milestone.reward, 'activity_milestone', milestone.title, null);
    }

    if (activitySettings.milestone_channel_id) {
      const guild = await client.guilds.fetch(guildId).catch(() => null);
      const channel = guild ? await guild.channels.fetch(activitySettings.milestone_channel_id).catch(() => null) : null;
      if (channel && channel.isTextBased()) {
        await channel.send({ embeds: [buildMilestoneAnnouncementEmbed(userId, milestone, settings)] }).catch(() => null);
      }
    }
  }
}

// 7J-92LEGACYFLOOR: a dominant player's achievement total can never count
// for more than this multiple of their participation_score toward
// legacy_score — the mechanism that makes skill accelerate progress
// without letting it skip the time-served floor. Tuned (see the session's
// design discussion) so a consistently-active non-champion reaches the top
// legacy tier in ~4-4.5 years, and a repeat-champion elite player
// compresses that to ~2-2.5 years — never less, since participation itself
// can't be rushed. Expressed as thirds/halves to stay in integer math
// (Postgres integer division truncates, which is fine here).
// 7J-94CADENCEFIX: recalibrated per Hxxdie's real-world correction — most
// leagues run a 48-hour advance schedule (~50 days for a 17-game season
// incl. playoffs/offseason), landing around 6 completed seasons/year per
// league, not the original ~3/year assumption this constant and
// SEASON_PARTICIPATION_POINTS below were tuned against. Cap raised from
// 1.5x to 2.5x participation to compensate — at 6 seasons/year, a
// consistent non-champion now reaches GOAT in ~4.0 years and a repeat-
// champion elite player in ~2.3 years, matching the original target.
const LEGACY_ACHIEVEMENT_CAP_NUMERATOR = 5;
const LEGACY_ACHIEVEMENT_CAP_DENOMINATOR = 2; // 5/2 = 2.5x
// 7J-94CADENCEFIX: was 50, assuming ~3 seasons/year. At the corrected ~6
// seasons/year, per-game participation (1/game × ~17 games/season × 6
// seasons/year ≈ 102/year) is now the dominant participation source on its
// own — this constant is more of a "completed a season" bonus on top of
// that than the primary driver it originally was, which is fine; the cap
// mechanism doesn't care which component participation comes from.
const SEASON_PARTICIPATION_POINTS = 8;

// 7J-43ACTIVITY: leagueId is optional and additive — the existing
// server-scoped user_recognition update is completely unchanged, so every
// existing call site keeps working exactly as before with no leagueId
// passed. When a caller does have clean league context (award wins, game
// wins, sportsbook activity, championships), passing it also updates the
// league-scoped table. The universal/global table is always updated
// regardless, since every point-earning action anywhere should count
// toward a user's cross-server activity grade.
//
// 7J-92LEGACYFLOOR: legacyPoints here now means "raw achievement points" —
// it accrues into achievement_score_raw uncapped, but legacy_score (the
// number every leaderboard/profile actually displays) only ever credits up
// to LEGACY_ACHIEVEMENT_CAP_NUMERATOR/DENOMINATOR times current
// participation_score. Nothing is lost — a big achievement earned before
// enough participation exists just "banks" and unlocks gradually as
// participation (see addParticipationScore) catches up.
async function addActivityPoints(guildId, userId, points, legacyPoints = 0, leagueId = null) {
  await ensureRecognitionProfile(guildId, userId);

  await pool.query(
    `UPDATE user_recognition
     SET activity_points = activity_points + $3,
         achievement_score_raw = achievement_score_raw + $4,
         legacy_score = participation_score + LEAST(achievement_score_raw + $4, (participation_score * ${LEGACY_ACHIEVEMENT_CAP_NUMERATOR}) / ${LEGACY_ACHIEVEMENT_CAP_DENOMINATOR}),
         updated_at = NOW(),
         last_activity_at = NOW()
     WHERE guild_id = $1 AND user_id = $2`,
    [guildId, userId, Number(points || 0), Number(legacyPoints || 0)]
  );

  if (leagueId) {
    await pool.query(
      `INSERT INTO user_league_activity (guild_id, league_id, user_id, activity_points, achievement_score_raw, legacy_score)
       VALUES ($1, $2, $3, $4, $5, LEAST($5, 0))
       ON CONFLICT (guild_id, league_id, user_id)
       DO UPDATE SET
         activity_points = user_league_activity.activity_points + $4,
         achievement_score_raw = user_league_activity.achievement_score_raw + $5,
         legacy_score = user_league_activity.participation_score + LEAST(user_league_activity.achievement_score_raw + $5, (user_league_activity.participation_score * ${LEGACY_ACHIEVEMENT_CAP_NUMERATOR}) / ${LEGACY_ACHIEVEMENT_CAP_DENOMINATOR}),
         updated_at = NOW()`,
      [guildId, String(leagueId), userId, Number(points || 0), Number(legacyPoints || 0)]
    ).catch(() => null);
  }

  await pool.query(
    `INSERT INTO user_global_activity (user_id, activity_points, achievement_score_raw, legacy_score)
     VALUES ($1, $2, $3, LEAST($3, 0))
     ON CONFLICT (user_id)
     DO UPDATE SET
       activity_points = user_global_activity.activity_points + $2,
       achievement_score_raw = user_global_activity.achievement_score_raw + $3,
       legacy_score = user_global_activity.participation_score + LEAST(user_global_activity.achievement_score_raw + $3, (user_global_activity.participation_score * ${LEGACY_ACHIEVEMENT_CAP_NUMERATOR}) / ${LEGACY_ACHIEVEMENT_CAP_DENOMINATOR}),
       updated_at = NOW()`,
    [userId, Number(points || 0), Number(legacyPoints || 0)]
  ).catch(() => null);

  await checkActivityMilestones(guildId, userId).catch(() => null);
}

// 7J-92LEGACYFLOOR: the participation half of Legacy Score — the floor
// achievement can accelerate past but never skip. Fed by games played (a
// small trickle) and completed seasons (the dominant contributor — see the
// season-rollover hook in the EA sync pipeline). Recomputes legacy_score
// the same capped way as addActivityPoints, since raising participation
// can also retroactively unlock previously-banked achievement.
async function addParticipationScore(guildId, userId, points, leagueId = null, seasonsCompleted = 0) {
  await ensureRecognitionProfile(guildId, userId);

  await pool.query(
    `UPDATE user_recognition
     SET participation_score = participation_score + $3,
         seasons_completed = seasons_completed + $4,
         legacy_score = (participation_score + $3) + LEAST(achievement_score_raw, ((participation_score + $3) * ${LEGACY_ACHIEVEMENT_CAP_NUMERATOR}) / ${LEGACY_ACHIEVEMENT_CAP_DENOMINATOR}),
         updated_at = NOW(),
         last_activity_at = NOW()
     WHERE guild_id = $1 AND user_id = $2`,
    [guildId, userId, Number(points || 0), Number(seasonsCompleted || 0)]
  );

  if (leagueId) {
    await pool.query(
      `INSERT INTO user_league_activity (guild_id, league_id, user_id, participation_score, seasons_completed, legacy_score)
       VALUES ($1, $2, $3, $4, $5, $4)
       ON CONFLICT (guild_id, league_id, user_id)
       DO UPDATE SET
         participation_score = user_league_activity.participation_score + $4,
         seasons_completed = user_league_activity.seasons_completed + $5,
         legacy_score = (user_league_activity.participation_score + $4) + LEAST(user_league_activity.achievement_score_raw, ((user_league_activity.participation_score + $4) * ${LEGACY_ACHIEVEMENT_CAP_NUMERATOR}) / ${LEGACY_ACHIEVEMENT_CAP_DENOMINATOR}),
         updated_at = NOW()`,
      [guildId, String(leagueId), userId, Number(points || 0), Number(seasonsCompleted || 0)]
    ).catch(() => null);
  }

  await pool.query(
    `INSERT INTO user_global_activity (user_id, participation_score, seasons_completed, legacy_score)
     VALUES ($1, $2, $3, $2)
     ON CONFLICT (user_id)
     DO UPDATE SET
       participation_score = user_global_activity.participation_score + $2,
       seasons_completed = user_global_activity.seasons_completed + $3,
       legacy_score = (user_global_activity.participation_score + $2) + LEAST(user_global_activity.achievement_score_raw, ((user_global_activity.participation_score + $2) * ${LEGACY_ACHIEVEMENT_CAP_NUMERATOR}) / ${LEGACY_ACHIEVEMENT_CAP_DENOMINATOR}),
       updated_at = NOW()`,
    [userId, Number(points || 0), Number(seasonsCompleted || 0)]
  ).catch(() => null);
}

async function ensureRecognitionProfile(guildId, userId) {
  await pool.query(
    `INSERT INTO user_recognition (guild_id, user_id)
     VALUES ($1, $2)
     ON CONFLICT (guild_id, user_id) DO NOTHING`,
    [guildId, userId]
  );
}

async function addRecognitionPoints(guildId, userId, points, legacyPoints = 0, leagueId = null) {
  return addActivityPoints(guildId, userId, points, legacyPoints, leagueId);
}

async function incrementRecognitionStat(guildId, userId, field, amount = 1) {
  const allowedFields = [
    'championships',
    'sportsbook_wins',
    'sportsbook_profit',
    'tickets_resolved',
    'games_played',
    'activity_streak',
    'total_wagered'
  ];

  if (!allowedFields.includes(field)) return;

  await ensureRecognitionProfile(guildId, userId);
  await pool.query(
    `UPDATE user_recognition
     SET ${field} = ${field} + $3,
         updated_at = NOW(),
         last_activity_at = NOW()
     WHERE guild_id = $1 AND user_id = $2`,
    [guildId, userId, Number(amount || 1)]
  );
}

// 7J-92LEGACYFLOOR / 7J-94CADENCEFIX: recalibrated for the corrected ~6
// seasons/year cadence (48-hour advance leagues) and the participation-
// floor formula. A consistent player with zero championships reaches GOAT
// around 3.4-4 years depending on sportsbook engagement (betting wins
// contribute a modest, outcome-gated amount — not exploitable by placing
// lots of bets, since it only fires on wins); a repeat-champion elite
// player compresses that to roughly 2.3-2.5 years — never less, since
// participation itself can't be rushed. Thresholds unchanged from the
// first pass (200/450/750/1200) — the cap/season-points retune absorbed
// the cadence correction without needing to move these too.
function getLegacyTier(score) {
  const legacyScore = Number(score || 0);
  if (legacyScore >= 1200) return 'GOAT';
  if (legacyScore >= 750) return 'Legend';
  if (legacyScore >= 450) return 'Elite';
  if (legacyScore >= 200) return 'Veteran';
  return 'Rising Star';
}

function getActivityTier(score) {
  const activityScore = Number(score || 0);
  if (activityScore >= 5000) return 'Icon';
  if (activityScore >= 2500) return 'Elite';
  if (activityScore >= 1000) return 'Grinder';
  if (activityScore >= 500) return 'Veteran';
  if (activityScore >= 100) return 'Active';
  return 'Rookie';
}


// 7J-43ACTIVITY: universal activity grade. topPercent = what percentage of
// all GG Sports users this person's universal activity score beats or ties
// (lower topPercent = better standing, e.g. topPercent=8 means "top 8%").
// Grade bands are a reasonable starting curve, not final — easy to retune
// since it's just threshold data, not scattered through logic. Tier reuses
// the exact same getActivityTier scale as the per-server tier, just applied
// to the universal score instead, for naming consistency across the bot.
function computeActivityLetterGrade(topPercent) {
  if (topPercent <= 1) return 'S';
  if (topPercent <= 5) return 'A+';
  if (topPercent <= 10) return 'A';
  if (topPercent <= 20) return 'A-';
  if (topPercent <= 30) return 'B+';
  if (topPercent <= 40) return 'B';
  if (topPercent <= 50) return 'B-';
  if (topPercent <= 65) return 'C+';
  if (topPercent <= 80) return 'C';
  if (topPercent <= 90) return 'D';
  return 'F';
}

async function getUniversalActivityGrade(userId) {
  await pool.query(
    `INSERT INTO user_global_activity (user_id) VALUES ($1) ON CONFLICT (user_id) DO NOTHING`,
    [userId]
  ).catch(() => null);

  const result = await pool.query(
    `WITH me AS (
       SELECT activity_points FROM user_global_activity WHERE user_id = $1
     )
     SELECT
       me.activity_points AS my_points,
       (SELECT COUNT(*) FROM user_global_activity) AS total_users,
       (SELECT COUNT(*) FROM user_global_activity, me WHERE user_global_activity.activity_points >= me.activity_points) AS better_or_equal_count
     FROM me`,
    [userId]
  ).catch(() => ({ rows: [] }));

  const row = result.rows[0];
  const activityPoints = Number(row?.my_points || 0);
  const totalUsers = Number(row?.total_users || 0);
  const betterOrEqualCount = Number(row?.better_or_equal_count || 0);
  // With very few users in the global pool (early on), a percentile is
  // statistically meaningless — flag that instead of pretending precision.
  const smallSample = totalUsers < 20;
  const topPercent = totalUsers > 0 ? Math.max(0.1, Math.round((betterOrEqualCount / totalUsers) * 1000) / 10) : 100;

  return {
    activityPoints,
    totalUsers,
    topPercent,
    smallSample,
    grade: computeActivityLetterGrade(topPercent),
    tier: getActivityTier(activityPoints),
  };
}

function buildActivityEmbed(user, row, achievements = [], universalGrade = null) {
  const profile = row || {};
  const activityPoints = Number(profile.activity_points || profile.recognition_points || 0);
  const legacyScore = Number(profile.legacy_score || 0);
  const achievementCount = achievements.length;
  const recentAchievements = achievements.slice(0, 5).map(a => `🏆 ${a.title || a.achievement_key}`).join('\n') || 'None yet';
  const universalValue = universalGrade
    ? `**${universalGrade.grade}** • ${universalGrade.tier} • ${universalGrade.smallSample ? 'Not enough users yet for a reliable percentile' : `Top ${universalGrade.topPercent}% of GG Sports users`}`
    : 'Not available';

  return new EmbedBuilder()
    .setTitle(user.username + ' • Activity & Legacy Profile')
    .setColor(0xFEE75C)
    .setThumbnail(user.displayAvatarURL({ dynamic: true }))
    .addFields(
      { name: 'Activity Tier', value: getActivityTier(activityPoints), inline: true },
      { name: 'Activity Points', value: String(activityPoints), inline: true },
      { name: 'Activity Streak', value: String(profile.activity_streak || 0), inline: true },
      { name: 'Legacy Tier', value: getLegacyTier(legacyScore), inline: true },
      { name: 'Legacy Score', value: String(legacyScore), inline: true },
      { name: 'Championships', value: String(profile.championships || 0), inline: true },
      // 7J-153TOURNEYFIELD: Tournament Titles field removed per Hxxdie — it read
      // the dead, never-incremented user_recognition.tournament_titles column and
      // always showed 0/stale. The real, live-computed count already shows on the
      // Franchise Hub / League HOF Member Profile panel (see 7J-42TOURNEY).
      { name: 'Sportsbook Wins', value: String(profile.sportsbook_wins || 0), inline: true },
      { name: 'Sportsbook Profit', value: String(profile.sportsbook_profit || 0), inline: true },
      { name: 'Tickets Resolved', value: String(profile.tickets_resolved || 0), inline: true },
      { name: 'Games Played', value: String(profile.games_played || 0), inline: true },
      { name: `Achievements (${achievementCount})`, value: recentAchievements, inline: false },
      { name: '🌐 Universal Activity Grade', value: universalValue, inline: false }
    )
    .setFooter({ text: 'GG Sports • Activity & Legacy System' })
    .setTimestamp();
}



// =============================================================================
// 7J-PREMIUM: Real-money subscription infrastructure (Stripe).
// Per GG-Sports-Payment-Business-Infrastructure-Spec.md — business decisions
// finalized by Hxxdie. This block covers: the Stripe REST wrapper (raw fetch,
// same pattern as the EA integration — no SDK dependency added), guild-level
// entitlement read/write helpers, billing-event logging for metrics, DM/
// announcement notifications, free-tier league-cap locking, the shared lapse
// handler, checkout/cancel flows, webhook signature verification + dispatch,
// and the trial scheduler.
// =============================================================================

// --- Stripe REST wrapper ---------------------------------------------------
// Raw fetch, not the stripe npm package — same approach already used for the
// EA Direct integration elsewhere in this file, so no new dependency.
async function stripeApiRequest(method, path, formParams = null) {
  if (!STRIPE_SECRET_KEY) throw new Error('STRIPE_SECRET_KEY is not configured.');
  const headers = {
    Authorization: 'Basic ' + Buffer.from(STRIPE_SECRET_KEY + ':').toString('base64'),
  };
  let body;
  if (formParams) {
    headers['Content-Type'] = 'application/x-www-form-urlencoded';
    body = new URLSearchParams(formParams).toString();
  }
  const response = await fetch(STRIPE_API_BASE + path, { method, headers, body });
  const json = await response.json().catch(() => ({}));
  if (!response.ok) {
    const message = json?.error?.message || `Stripe API error (${response.status})`;
    throw new Error(message);
  }
  return json;
}

// Stripe's form-encoding for nested objects is bracket-style:
// metadata[guild_id]=123, nested arbitrarily deep for structures like
// subscription_data[metadata][guild_id]=123. Recurses to any depth rather
// than flattening one level only — a one-level version silently mishandled
// subscription_data.metadata (itself a nested object one level below
// subscription_data) by String()-ing it into the literal text
// "[object Object]", which Stripe correctly rejected with "Invalid value
// for `metadata`" the first time this ran against a real Checkout Session
// (2026-08-07).
function flattenStripeFormParams(params, parentKey = '') {
  const flat = {};
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue;
    const fullKey = parentKey ? `${parentKey}[${key}]` : key;
    if (typeof value === 'object' && !Array.isArray(value)) {
      Object.assign(flat, flattenStripeFormParams(value, fullKey));
    } else {
      flat[fullKey] = String(value);
    }
  }
  return flat;
}

// --- Entitlement read/write helpers -----------------------------------------

async function ensureGuildEntitlementRow(guildId) {
  // premium_entitlements.guild_id has an FK to guilds(guild_id) — but a
  // guild otherwise only gets a guilds row when /league create runs, and
  // someone can reasonably run Admin Panel → Premium & Billing → Start 14-Day Trial or Admin Panel → Premium & Billing → Subscribe before
  // ever creating a league. Upsert guilds first so that FK never fails.
  const guildName = client.guilds.cache.get(guildId)?.name || guildId;
  await pool.query(
    `INSERT INTO guilds (guild_id, guild_name) VALUES ($1, $2) ON CONFLICT (guild_id) DO NOTHING`,
    [guildId, guildName]
  );
  await pool.query(
    `INSERT INTO premium_entitlements (guild_id) VALUES ($1) ON CONFLICT (guild_id) DO NOTHING`,
    [guildId]
  );
}

async function getGuildEntitlement(guildId) {
  await ensureGuildEntitlementRow(guildId);
  const result = await pool.query(`SELECT * FROM premium_entitlements WHERE guild_id = $1 LIMIT 1`, [guildId]);
  return result.rows[0];
}

// True if this guild currently has Premium-tier access, whether via an
// active/trialing Stripe subscription or an unexpired manual comp grant.
function isEntitlementPremiumActive(entitlement) {
  if (!entitlement) return false;
  if (entitlement.source === 'manual') {
    if (!entitlement.manual_expires_at) return entitlement.status === 'active'; // permanent comp
    return entitlement.status === 'active' && new Date(entitlement.manual_expires_at).getTime() > Date.now();
  }
  if (entitlement.status === 'trialing') {
    return entitlement.trial_ends_at ? new Date(entitlement.trial_ends_at).getTime() > Date.now() : true;
  }
  if (entitlement.status === 'active' || entitlement.status === 'past_due') {
    // past_due still counts as active — spec Section 5: "No feature
    // degradation during retries," access only actually drops on full lapse.
    return true;
  }
  return false;
}

async function isGuildPremiumActive(guildId) {
  const entitlement = await getGuildEntitlement(guildId);
  return isEntitlementPremiumActive(entitlement);
}

// 7J-COMMANDHUB-PAYWALL: shared gate for actual Premium/Advanced features
// (as opposed to the Free Tier league-count cap, which is enforced
// separately at league creation). Per Hxxdie's audit request — before this,
// isGuildPremiumActive was only ever checked at league creation; every
// other "Premium" feature (GM tooling, Economy/Shop/Sportsbook, avatar
// depth, etc.) had zero real enforcement despite being documented as
// premium-only. Replies with a consistent upsell message and returns false
// if not premium; returns true (and replies nothing) if premium — callers
// do `if (!(await requirePremiumFeature(interaction, 'Shop'))) return;`
// right at the top of a handler, before any other work.
async function requirePremiumFeature(interaction, featureName) {
  if (!interaction.guild) return true; // DM-context commands aren't guild-tiered
  if (await isGuildPremiumActive(interaction.guild.id)) return true;
  const message = `**${featureName}** is a GG Sports Premium feature. This server hasn't unlocked it yet — a server admin can try \`Admin Panel → Premium & Billing → Start 14-Day Trial\` for 14 days of full access (no card required), or \`Admin Panel → Premium & Billing → Subscribe\` to go Premium for the whole server.`;
  if (interaction.deferred || interaction.replied) {
    await interaction.editReply({ content: message, embeds: [], components: [] }).catch(() => null);
  } else {
    await interaction.reply({ content: message, ephemeral: true }).catch(() => null);
  }
  return false;
}

async function recordPremiumBillingEvent(guildId, eventType, { plan = null, amountCents = null } = {}) {
  await pool.query(
    `INSERT INTO premium_billing_events (id, guild_id, event_type, plan, amount_cents) VALUES ($1, $2, $3, $4, $5)`,
    [randomUUID(), guildId, eventType, plan, amountCents]
  ).catch(error => console.error('[7J-PREMIUM] Failed to record billing event:', eventType, error?.message || error));
}

// Owner is always checked live (not cached) per spec Section 3. Billing
// manager is whatever's stored on the entitlement row, if anyone.
async function isBillingAuthorized(interaction, entitlement) {
  const guild = interaction.guild;
  if (!guild) return false;
  if (entitlement?.billing_manager_user_id === interaction.user.id) return true;
  const ownerId = guild.ownerId || (await guild.fetchOwner().catch(() => null))?.id;
  return ownerId === interaction.user.id;
}

// --- Notifications -----------------------------------------------------------

// Best-effort DM to the live server owner and, if set and different, the
// designated billing manager. Never throws — a closed-DMs owner shouldn't
// block the billing state change itself.
async function dmPremiumNotice(guild, entitlement, embed) {
  const owner = await guild.fetchOwner().catch(() => null);
  const targets = new Set();
  if (owner) targets.add(owner.id);
  if (entitlement?.billing_manager_user_id) targets.add(entitlement.billing_manager_user_id);

  for (const userId of targets) {
    const user = await client.users.fetch(userId).catch(() => null);
    if (!user) continue;
    await user.send({ embeds: [embed] }).catch(() => null);
  }
}

// Posts to every active league's configured announcement channel in the
// guild — Premium is a guild-level unlock, and a guild can have more than
// one active league, so every league's community should see why sportsbook/
// shop/tournaments etc. just appeared or disappeared.
async function postPremiumGuildAnnouncement(guild, embed) {
  const leagues = await getActiveLeaguesForGuild(guild.id).catch(() => []);
  for (const league of leagues) {
    const settingsResult = await pool.query(
      `SELECT league_announcement_channel_id FROM league_settings WHERE league_id = $1 LIMIT 1`,
      [league.league_id]
    ).catch(() => ({ rows: [] }));
    const channelId = settingsResult.rows[0]?.league_announcement_channel_id;
    if (!channelId) continue;
    const channel = await guild.channels.fetch(channelId).catch(() => null);
    if (!channel?.isTextBased?.()) continue;
    await channel.send({ embeds: [embed] }).catch(() => null);
  }
}

// --- Free-tier league cap ----------------------------------------------------

async function countActiveLeaguesForGuild(guildId) {
  const result = await pool.query(`SELECT COUNT(*)::int AS count FROM leagues WHERE guild_id = $1 AND is_active = TRUE`, [guildId]);
  return result.rows[0]?.count || 0;
}

// Called whenever a guild drops out of Premium (lapse, trial expiry, manual
// grant expiry). Locks (is_active = FALSE — the same soft-disable every
// other part of this codebase already uses and already filters on) the
// oldest active leagues beyond the Free Tier cap, keeping the most
// recently-created leagues active as the default selection. This is a
// deliberate default, not a picker UI (see handoff notes) — the owner/
// billing manager can rearrange afterward with /league delete (locks one)
// and /league reactivate (unlocks one, blocked if it would exceed the cap),
// both of which already exist / are added alongside this feature.
async function enforceFreeTierLeagueCap(guild) {
  const activeResult = await pool.query(
    `SELECT league_id, league_name FROM leagues WHERE guild_id = $1 AND is_active = TRUE ORDER BY created_at DESC`,
    [guild.id]
  );
  const active = activeResult.rows;
  if (active.length <= FREE_TIER_LEAGUE_CAP) return { lockedCount: 0, lockedNames: [] };

  const toLock = active.slice(FREE_TIER_LEAGUE_CAP);
  for (const league of toLock) {
    await pool.query(`UPDATE leagues SET is_active = FALSE, premium_locked_at = NOW() WHERE league_id = $1`, [league.league_id]);
  }
  return { lockedCount: toLock.length, lockedNames: toLock.map(l => l.league_name) };
}

// Reverses enforceFreeTierLeagueCap. Only ever restores leagues the BOT
// locked (premium_locked_at IS NOT NULL) — never touches leagues the owner
// deliberately deleted through League Setup, since those already had their
// Discord roles/channels removed and restoring is_active for them would
// leave the bot pointing at resources that no longer exist.
async function restorePremiumCapLockedLeagues(guildId) {
  const result = await pool.query(
    `UPDATE leagues SET is_active = TRUE, premium_locked_at = NULL
     WHERE guild_id = $1 AND premium_locked_at IS NOT NULL
     RETURNING league_name`,
    [guildId]
  );
  return { restoredCount: result.rows.length, restoredNames: result.rows.map(r => r.league_name) };
}

// --- Shared lapse handler -----------------------------------------------------

// One shared path for every way a guild can leave Premium: trial expiring
// unpaid, dunning exhausting all 3 attempts, or a cancellation reaching the
// end of its paid period. Spec Section 6 treats all three identically —
// lock (don't delete), 30-day grace period, notify.
async function lapsePremiumGuild(client, guildId, reason) {
  const guild = await client.guilds.fetch(guildId).catch(() => null);
  if (!guild) return;

  const entitlement = await getGuildEntitlement(guildId);
  await pool.query(
    `UPDATE premium_entitlements SET status = 'lapsed', lapsed_at = NOW(), updated_at = NOW() WHERE guild_id = $1`,
    [guildId]
  );

  const lockResult = await enforceFreeTierLeagueCap(guild).catch(() => ({ lockedCount: 0, lockedNames: [] }));

  // Cross-Server League Discoverability is a Premium feature — turn it off
  // for every league in this guild so it doesn't linger visible on the
  // Discover Leagues board after Premium lapses. The board query also
  // double-checks live Premium status independently (see
  // buildDiscoverLeaguesPayload), but clearing the flag here keeps the
  // toggle's own displayed state accurate too.
  await pool.query(
    `UPDATE league_settings SET recruitment_discoverable = FALSE
     WHERE league_id IN (SELECT league_id FROM leagues WHERE guild_id = $1)`,
    [guildId]
  ).catch(error => console.error('[7J-PREMIUM] Failed to clear recruitment_discoverable on lapse:', error?.message || error));

  await recordPremiumBillingEvent(guildId, reason === 'trial_expired' ? 'trial_lapsed' : 'lapsed', { plan: entitlement.plan });

  const reasonText = reason === 'trial_expired'
    ? "Your 14-day GG Sports Premium trial has ended without converting to a paid subscription."
    : reason === 'payment_failed'
      ? "GG Sports Premium billing failed after 3 attempts and the subscription has lapsed."
      : "Your GG Sports Premium subscription has ended.";

  const lockedNote = lockResult.lockedCount
    ? `\n\n**${lockResult.lockedCount} league(s) beyond the Free Tier cap (${FREE_TIER_LEAGUE_CAP}) have been locked, not deleted:** ${lockResult.lockedNames.join(', ')}. Nothing is lost — reactivating Premium restores full access instantly.`
    : '';

  const dmEmbed = new EmbedBuilder()
    .setTitle('⏬ GG Sports Premium — Downgraded to Free Tier')
    .setColor(0xED4245)
    .setDescription(
      `${reasonText}${lockedNote}\n\nLocked data is retained for **${PREMIUM_GRACE_PERIOD_DAYS} days**. Reactivate any time within that window with \`Admin Panel → Premium & Billing → Subscribe\` for full, instant restoration.`
    )
    .setFooter({ text: 'GG Sports • Premium' })
    .setTimestamp();
  await dmPremiumNotice(guild, entitlement, dmEmbed).catch(() => null);

  const announceEmbed = new EmbedBuilder()
    .setTitle('GG Sports Premium has ended for this server')
    .setColor(0xED4245)
    .setDescription(
      `This server's Premium subscription has ended, so some features/leagues are temporarily locked (not deleted) rather than the bot being broken. Server staff can reactivate any time with \`Admin Panel → Premium & Billing → Subscribe\`.`
    )
    .setTimestamp();
  await postPremiumGuildAnnouncement(guild, announceEmbed).catch(() => null);
}

// --- Stripe checkout / cancel flows ------------------------------------------

function priceIdForPlan(plan) {
  return plan === 'annual' ? STRIPE_PRICE_ID_ANNUAL : STRIPE_PRICE_ID_MONTHLY;
}

async function createPremiumCheckoutSession(guild, user, plan) {
  const priceId = priceIdForPlan(plan);
  if (!priceId) throw new Error('Stripe price ID is not configured for this plan yet — contact the bot owner.');
  const baseUrl = process.env.GGSPORTS_PUBLIC_BASE_URL;
  if (!baseUrl) throw new Error('GGSPORTS_PUBLIC_BASE_URL is not configured — Stripe Checkout needs a public return URL.');

  const session = await stripeApiRequest('POST', '/checkout/sessions', flattenStripeFormParams({
    mode: 'subscription',
    client_reference_id: guild.id,
    success_url: `${baseUrl}/premium/success`,
    cancel_url: `${baseUrl}/premium/cancel`,
    'line_items[0][price]': priceId,
    'line_items[0][quantity]': 1,
    metadata: { guild_id: guild.id, user_id: user.id, plan },
    subscription_data: { metadata: { guild_id: guild.id, plan } },
    'automatic_tax[enabled]': true,
  }));
  return session.url;
}

async function cancelPremiumSubscriptionAtPeriodEnd(entitlement) {
  if (!entitlement?.stripe_subscription_id) throw new Error('No active Stripe subscription found for this server.');
  await stripeApiRequest('POST', `/subscriptions/${entitlement.stripe_subscription_id}`, { cancel_at_period_end: 'true' });
  await pool.query(
    `UPDATE premium_entitlements SET cancel_at_period_end = TRUE, updated_at = NOW() WHERE guild_id = $1`,
    [entitlement.guild_id]
  );
}

// --- Webhook signature verification + dispatch -------------------------------

// Stripe-Signature header format: t=<timestamp>,v1=<hex hmac>[,v0=...]
// Signed payload is "<timestamp>.<raw body>", HMAC-SHA256 with the webhook
// signing secret. Constant-time compare via timingSafeEqual.
function verifyStripeWebhookSignature(rawBody, signatureHeader) {
  if (!STRIPE_WEBHOOK_SECRET) throw new Error('STRIPE_WEBHOOK_SECRET is not configured.');
  if (!signatureHeader) throw new Error('Missing Stripe-Signature header.');

  const parts = Object.fromEntries(
    signatureHeader.split(',').map(part => part.split('=')).map(([k, v]) => [k, v])
  );
  const timestamp = parts.t;
  const expectedSig = parts.v1;
  if (!timestamp || !expectedSig) throw new Error('Malformed Stripe-Signature header.');

  const signedPayload = `${timestamp}.${rawBody}`;
  const computedSig = createHmac('sha256', STRIPE_WEBHOOK_SECRET).update(signedPayload, 'utf8').digest('hex');

  const expectedBuf = Buffer.from(expectedSig, 'hex');
  const computedBuf = Buffer.from(computedSig, 'hex');
  if (expectedBuf.length !== computedBuf.length || !timingSafeEqual(expectedBuf, computedBuf)) {
    throw new Error('Stripe webhook signature mismatch.');
  }

  // Reject anything older than 5 minutes — standard Stripe replay-attack guard.
  const ageSeconds = Math.abs(Date.now() / 1000 - Number(timestamp));
  if (ageSeconds > 300) throw new Error('Stripe webhook timestamp too old.');
}

function planFromStripePriceId(priceId) {
  if (priceId === STRIPE_PRICE_ID_ANNUAL) return 'annual';
  if (priceId === STRIPE_PRICE_ID_MONTHLY) return 'monthly';
  return null;
}

async function handleStripeCheckoutCompleted(client, session) {
  const guildId = session.client_reference_id || session.metadata?.guild_id;
  if (!guildId) { console.error('[7J-PREMIUM] checkout.session.completed with no guild_id.'); return; }
  if (session.mode !== 'subscription' || !session.subscription) return;

  const subscription = await stripeApiRequest('GET', `/subscriptions/${session.subscription}`);
  const priceId = subscription.items?.data?.[0]?.price?.id;
  const plan = planFromStripePriceId(priceId) || session.metadata?.plan || null;
  const periodEnd = subscription.current_period_end ? new Date(subscription.current_period_end * 1000) : null;

  const existing = await getGuildEntitlement(guildId);
  const isFounderPricing = !existing.lapsed_at; // never lapsed before => first-ever subscribe => founder pricing

  await pool.query(
    `UPDATE premium_entitlements SET
       status = 'active', plan = $2, stripe_customer_id = $3, stripe_subscription_id = $4,
       current_period_end = $5, cancel_at_period_end = FALSE, is_founder_pricing = $6,
       payer_user_id = $7, dunning_attempt_count = 0, source = 'stripe',
       lapsed_at = NULL, grace_notice_sent_at = NULL, permanently_deleted_at = NULL, updated_at = NOW()
     WHERE guild_id = $1`,
    [guildId, plan, session.customer, session.subscription, periodEnd, isFounderPricing, session.metadata?.user_id || null]
  );

  await recordPremiumBillingEvent(guildId, existing.status === 'trialing' ? 'trial_converted' : 'payment_succeeded', { plan });

  // If this guild had leagues locked for exceeding the Free Tier cap (e.g.
  // resubscribing via a fresh checkout after a full lapse), restore them now.
  const restoreResult = await restorePremiumCapLockedLeagues(guildId).catch(() => ({ restoredCount: 0, restoredNames: [] }));

  const guild = await client.guilds.fetch(guildId).catch(() => null);
  if (!guild) return;
  const entitlement = await getGuildEntitlement(guildId);

  const restoredNote = restoreResult.restoredCount
    ? `\n\n**${restoreResult.restoredCount} previously-locked league(s) restored:** ${restoreResult.restoredNames.join(', ')}. Full access is back instantly.`
    : '';
  const dmEmbed = new EmbedBuilder()
    .setTitle('✅ GG Sports Premium — Active')
    .setColor(0x57F287)
    .setDescription(
      `Payment received — this server now has Premium access${isFounderPricing ? ' at **founder pricing**, locked in for as long as your subscription stays active without a lapse' : ''}.${restoredNote}`
    )
    .setFooter({ text: 'GG Sports • Premium' })
    .setTimestamp();
  await dmPremiumNotice(guild, entitlement, dmEmbed).catch(() => null);

  const announceEmbed = new EmbedBuilder()
    .setTitle('🎉 This server has upgraded to GG Sports Premium!')
    .setColor(0x57F287)
    .setDescription(buildPremiumFeaturesEmbed().data.description || 'Premium features are now unlocked.')
    .addFields(buildPremiumFeaturesEmbed().data.fields || [])
    .setTimestamp();
  await postPremiumGuildAnnouncement(guild, announceEmbed).catch(() => null);
}

async function handleStripeInvoicePaid(client, invoice) {
  const entResult = await pool.query(`SELECT * FROM premium_entitlements WHERE stripe_customer_id = $1 LIMIT 1`, [invoice.customer]);
  const entitlement = entResult.rows[0];
  if (!entitlement) return;

  // Renewal invoices don't go through checkout.session.completed again —
  // this is the ongoing "still paying" signal for month 2+/year 2+.
  const periodEnd = invoice.lines?.data?.[0]?.period?.end ? new Date(invoice.lines.data[0].period.end * 1000) : entitlement.current_period_end;
  const wasLapsedOrPastDue = entitlement.status === 'lapsed' || entitlement.status === 'past_due';
  await pool.query(
    `UPDATE premium_entitlements SET status = 'active', current_period_end = $2, dunning_attempt_count = 0, lapsed_at = NULL, updated_at = NOW() WHERE guild_id = $1`,
    [entitlement.guild_id, periodEnd]
  );

  // If this guild had leagues locked for exceeding the Free Tier cap,
  // restore them now that Premium is active again.
  const restoreResult = wasLapsedOrPastDue
    ? await restorePremiumCapLockedLeagues(entitlement.guild_id).catch(() => ({ restoredCount: 0, restoredNames: [] }))
    : { restoredCount: 0, restoredNames: [] };

  // Only fire the "payment succeeded" DM/announcement for renewals — the
  // very first payment on a subscription is already covered by
  // checkout.session.completed above, and invoice.paid also fires for that
  // first invoice, which would otherwise double-notify.
  if (invoice.billing_reason === 'subscription_cycle') {
    await recordPremiumBillingEvent(entitlement.guild_id, 'payment_succeeded', { plan: entitlement.plan, amountCents: invoice.amount_paid });
    const guild = await client.guilds.fetch(entitlement.guild_id).catch(() => null);
    if (guild) {
      const restoredNote = restoreResult.restoredCount
        ? `\n\n**${restoreResult.restoredCount} previously-locked league(s) restored:** ${restoreResult.restoredNames.join(', ')}. Full access is back instantly.`
        : '';
      const dmEmbed = new EmbedBuilder()
        .setTitle('✅ GG Sports Premium — Renewed')
        .setColor(0x57F287)
        .setDescription(`Your renewal payment went through — Premium continues uninterrupted.${restoredNote}`)
        .setFooter({ text: 'GG Sports • Premium' })
        .setTimestamp();
      await dmPremiumNotice(guild, entitlement, dmEmbed).catch(() => null);
    }
  }
}

async function handleStripeInvoicePaymentFailed(client, invoice) {
  const entResult = await pool.query(`SELECT * FROM premium_entitlements WHERE stripe_customer_id = $1 LIMIT 1`, [invoice.customer]);
  const entitlement = entResult.rows[0];
  if (!entitlement) return;

  const attemptCount = (entitlement.dunning_attempt_count || 0) + 1;
  await pool.query(
    `UPDATE premium_entitlements SET status = 'past_due', dunning_attempt_count = $2, updated_at = NOW() WHERE guild_id = $1`,
    [entitlement.guild_id, attemptCount]
  );
  await recordPremiumBillingEvent(entitlement.guild_id, 'payment_failed', { plan: entitlement.plan });

  const guild = await client.guilds.fetch(entitlement.guild_id).catch(() => null);
  if (!guild) return;
  const updatedEntitlement = await getGuildEntitlement(entitlement.guild_id);

  const dmEmbed = new EmbedBuilder()
    .setTitle(`⚠️ GG Sports Premium — Payment Attempt ${attemptCount} Failed`)
    .setColor(0xED4245)
    .setDescription(
      attemptCount >= PREMIUM_DUNNING_MAX_ATTEMPTS
        ? `The ${attemptCount}${attemptCount === 3 ? 'rd' : 'th'} and final payment attempt failed. Premium access will lapse — update your payment method and reactivate with \`Admin Panel → Premium & Billing → Subscribe\` to avoid any data lock.`
        : `A payment attempt failed (attempt ${attemptCount} of ${PREMIUM_DUNNING_MAX_ATTEMPTS}). Access is unaffected while retries continue, but please update your payment method to avoid a lapse.`
    )
    .setFooter({ text: 'GG Sports • Premium' })
    .setTimestamp();
  await dmPremiumNotice(guild, updatedEntitlement, dmEmbed).catch(() => null);

  // Stripe manages the actual retry cadence/count per its own dunning
  // settings — we mirror its outcome rather than drive it. If Stripe's
  // final attempt already reported 3+ failures, treat it as a full lapse
  // now rather than waiting on a separate subscription.deleted event that
  // may or may not follow immediately.
  if (attemptCount >= PREMIUM_DUNNING_MAX_ATTEMPTS) {
    await lapsePremiumGuild(client, entitlement.guild_id, 'payment_failed');
  }
}

async function handleStripeSubscriptionDeleted(client, subscription) {
  const entResult = await pool.query(`SELECT * FROM premium_entitlements WHERE stripe_subscription_id = $1 LIMIT 1`, [subscription.id]);
  const entitlement = entResult.rows[0];
  if (!entitlement || entitlement.status === 'lapsed') return; // already handled via dunning exhaustion above
  await lapsePremiumGuild(client, entitlement.guild_id, 'canceled');
}

async function handleStripeWebhookEvent(client, event) {
  switch (event.type) {
    case 'checkout.session.completed':
      await handleStripeCheckoutCompleted(client, event.data.object);
      break;
    case 'invoice.paid':
      await handleStripeInvoicePaid(client, event.data.object);
      break;
    case 'invoice.payment_failed':
      await handleStripeInvoicePaymentFailed(client, event.data.object);
      break;
    case 'customer.subscription.deleted':
      await handleStripeSubscriptionDeleted(client, event.data.object);
      break;
    case 'customer.subscription.updated': {
      const subscription = event.data.object;
      const entResult = await pool.query(`SELECT guild_id FROM premium_entitlements WHERE stripe_subscription_id = $1 LIMIT 1`, [subscription.id]);
      const guildId = entResult.rows[0]?.guild_id;
      if (guildId) {
        await pool.query(
          `UPDATE premium_entitlements SET cancel_at_period_end = $2, current_period_end = $3, updated_at = NOW() WHERE guild_id = $1`,
          [guildId, !!subscription.cancel_at_period_end, subscription.current_period_end ? new Date(subscription.current_period_end * 1000) : null]
        );
      }
      break;
    }
    default:
      break; // ignore anything we don't act on
  }
  console.log(`[7J-PREMIUM][TEMP-DEBUG] Processed webhook event: ${event.type}`); // TEMP: remove after live-mode testing is done
}

// --- Trial scheduler ----------------------------------------------------------

let premiumTrialSchedulerTimer = null;
let premiumTrialSchedulerRunning = false;

async function runPremiumTrialSchedulerTick(client) {
  if (premiumTrialSchedulerRunning) return;
  premiumTrialSchedulerRunning = true;
  try {
    // Warning pass — trials inside the last 24h, not yet warned.
    const warningWindow = await pool.query(
      `SELECT * FROM premium_entitlements
       WHERE status = 'trialing'
         AND trial_ends_at IS NOT NULL
         AND trial_ends_at <= NOW() + ($1::text || ' hours')::interval
         AND trial_ends_at > NOW()
         AND trial_warning_sent_at IS NULL`,
      [PREMIUM_TRIAL_WARNING_HOURS_BEFORE]
    ).catch(() => ({ rows: [] }));

    for (const entitlement of warningWindow.rows) {
      const guild = await client.guilds.fetch(entitlement.guild_id).catch(() => null);
      if (!guild) continue;
      const dmEmbed = new EmbedBuilder()
        .setTitle('⚠️ ATTENTION REQUIRED — GG Sports Premium Trial Ending Soon')
        .setColor(0xED4245)
        .setDescription(
          `Your 14-day Premium trial ends within the next ${PREMIUM_TRIAL_WARNING_HOURS_BEFORE} hours. Subscribe with \`Admin Panel → Premium & Billing → Subscribe\` to keep Premium access — otherwise this server will drop to the Free Tier and any leagues beyond the ${FREE_TIER_LEAGUE_CAP}-league cap will be locked (not deleted).`
        )
        .setFooter({ text: 'GG Sports • Premium' })
        .setTimestamp();
      await dmPremiumNotice(guild, entitlement, dmEmbed).catch(() => null);
      await pool.query(`UPDATE premium_entitlements SET trial_warning_sent_at = NOW() WHERE guild_id = $1`, [entitlement.guild_id]).catch(() => null);
    }

    // Expiry pass — trials past their end date, never converted to paid.
    const expired = await pool.query(
      `SELECT guild_id FROM premium_entitlements WHERE status = 'trialing' AND trial_ends_at IS NOT NULL AND trial_ends_at <= NOW()`
    ).catch(() => ({ rows: [] }));

    for (const row of expired.rows) {
      await lapsePremiumGuild(client, row.guild_id, 'trial_expired').catch(error =>
        console.error('[7J-PREMIUM] Trial expiry lapse failed for guild', row.guild_id, error?.message || error));
    }

    // Manual (comp) grant expiry — same idea, no Stripe involved.
    const manualExpired = await pool.query(
      `SELECT guild_id FROM premium_entitlements WHERE source = 'manual' AND status = 'active' AND manual_expires_at IS NOT NULL AND manual_expires_at <= NOW()`
    ).catch(() => ({ rows: [] }));
    for (const row of manualExpired.rows) {
      await lapsePremiumGuild(client, row.guild_id, 'canceled').catch(() => null);
    }
  } catch (error) {
    console.error('[7J-PREMIUM] Trial scheduler tick failed:', error);
  } finally {
    premiumTrialSchedulerRunning = false;
  }
}

function startPremiumTrialSchedulerLoop(client) {
  if (premiumTrialSchedulerTimer) clearInterval(premiumTrialSchedulerTimer);
  // Hourly — trial warnings/expiry don't need finer granularity, and this
  // matches the cadence of the other hourly scheduler (birthday/Christmas
  // gifts) already in this file.
  premiumTrialSchedulerTimer = setInterval(() => {
    runPremiumTrialSchedulerTick(client).catch(error => console.error('[7J-PREMIUM] Trial scheduler tick failed:', error));
  }, 60 * 60 * 1000);
  setTimeout(() => runPremiumTrialSchedulerTick(client).catch(() => null), 45 * 1000);
}

// --- Grace-period expiry notice + automated permanent deletion --------------

// 7J-PREMIUM-PURGE: per Hxxdie — permanent deletion after the 30-day grace
// period is now real, not notify-only. Two-stage to keep "make a reasonable
// effort to notify before deletion" actually meaningful rather than notice
// and deletion firing in the same tick: the grace-notice DM goes out once
// lapsed_at is 30+ days old, then actual deletion only happens
// PREMIUM_PURGE_BUFFER_HOURS after THAT notice — giving the owner a real
// window to react to the exact message warning them, not just a courtesy
// heads-up moments before the row is gone. Self-correcting: if the guild
// reactivates in between (handleStripeCheckoutCompleted / manual grant),
// status leaves 'lapsed' and both queries below stop matching that guild
// automatically — no separate "cancel the purge" step needed.
//
// Deletion only ever touches LOCKED leagues (is_active = FALSE, the excess
// beyond the Free Tier cap) — active leagues within the cap are never
// purged, since those remain fully accessible on the Free Tier. Safe from
// an FK standpoint: every table referencing leagues(league_id) already
// declares ON DELETE CASCADE or ON DELETE SET NULL (checked directly
// against the schema before wiring this up), so a real DELETE FROM leagues
// cleans up correctly.
const PREMIUM_PURGE_BUFFER_HOURS = 72;

let premiumGraceNoticeTimer = null;
let premiumGraceNoticeRunning = false;

async function runPremiumGraceNoticeTick(client) {
  if (premiumGraceNoticeRunning) return;
  premiumGraceNoticeRunning = true;
  try {
    const pastGrace = await pool.query(
      `SELECT * FROM premium_entitlements
       WHERE status = 'lapsed'
         AND lapsed_at IS NOT NULL
         AND lapsed_at <= NOW() - ($1::text || ' days')::interval
         AND grace_notice_sent_at IS NULL`,
      [PREMIUM_GRACE_PERIOD_DAYS]
    ).catch(() => ({ rows: [] }));

    for (const entitlement of pastGrace.rows) {
      const guild = await client.guilds.fetch(entitlement.guild_id).catch(() => null);
      const lockedResult = await pool.query(
        `SELECT league_name FROM leagues WHERE guild_id = $1 AND premium_locked_at IS NOT NULL ORDER BY created_at DESC`,
        [entitlement.guild_id]
      ).catch(() => ({ rows: [] }));
      const lockedNames = lockedResult.rows.map(r => r.league_name);

      if (guild && lockedNames.length) {
        const dmEmbed = new EmbedBuilder()
          .setTitle('⚠️ FINAL NOTICE — GG Sports Premium Data Deletion')
          .setColor(0xED4245)
          .setDescription(
            `The ${PREMIUM_GRACE_PERIOD_DAYS}-day grace period for this server's locked data has passed. **The following locked league(s) will be permanently deleted in ${PREMIUM_PURGE_BUFFER_HOURS / 24} days unless Premium is reactivated:** ${lockedNames.join(', ')}.\n\nReactivate any time before then with \`Admin Panel → Premium & Billing → Subscribe\` to restore everything with no data loss. After deletion, this cannot be undone.`
          )
          .setFooter({ text: 'GG Sports • Premium' })
          .setTimestamp();
        await dmPremiumNotice(guild, entitlement, dmEmbed).catch(() => null);
      }
      await pool.query(`UPDATE premium_entitlements SET grace_notice_sent_at = NOW() WHERE guild_id = $1`, [entitlement.guild_id]).catch(() => null);
    }
  } catch (error) {
    console.error('[7J-PREMIUM] Grace notice tick failed:', error);
  } finally {
    premiumGraceNoticeRunning = false;
  }
}

function startPremiumGraceNoticeLoop(client) {
  if (premiumGraceNoticeTimer) clearInterval(premiumGraceNoticeTimer);
  premiumGraceNoticeTimer = setInterval(() => {
    runPremiumGraceNoticeTick(client).catch(error => console.error('[7J-PREMIUM] Grace notice tick failed:', error));
  }, 6 * 60 * 60 * 1000); // every 6 hours — a day-granularity threshold doesn't need hourly polling
  setTimeout(() => runPremiumGraceNoticeTick(client).catch(() => null), 90 * 1000);
}

let premiumPurgeTimer = null;
let premiumPurgeRunning = false;

async function runPremiumPurgeTick(client) {
  if (premiumPurgeRunning) return;
  premiumPurgeRunning = true;
  try {
    const duePurge = await pool.query(
      `SELECT * FROM premium_entitlements
       WHERE status = 'lapsed'
         AND grace_notice_sent_at IS NOT NULL
         AND grace_notice_sent_at <= NOW() - ($1::text || ' hours')::interval
         AND permanently_deleted_at IS NULL`,
      [PREMIUM_PURGE_BUFFER_HOURS]
    ).catch(() => ({ rows: [] }));

    for (const entitlement of duePurge.rows) {
      const lockedResult = await pool.query(
        `SELECT league_id, league_name FROM leagues WHERE guild_id = $1 AND premium_locked_at IS NOT NULL`,
        [entitlement.guild_id]
      ).catch(() => ({ rows: [] }));
      const lockedLeagues = lockedResult.rows;

      // Nothing locked (e.g. they were never over the Free Tier cap to
      // begin with) — nothing to purge, just mark this guild done so the
      // tick stops re-checking it every run.
      if (!lockedLeagues.length) {
        await pool.query(`UPDATE premium_entitlements SET permanently_deleted_at = NOW() WHERE guild_id = $1`, [entitlement.guild_id]).catch(() => null);
        continue;
      }

      const leagueIds = lockedLeagues.map(l => l.league_id);
      const leagueNames = lockedLeagues.map(l => l.league_name);

      try {
        await pool.query(`DELETE FROM leagues WHERE league_id = ANY($1::uuid[])`, [leagueIds]);
      } catch (error) {
        console.error('[7J-PREMIUM] Purge DELETE failed for guild', entitlement.guild_id, error);
        continue; // leave permanently_deleted_at NULL — will retry next tick
      }

      await pool.query(`UPDATE premium_entitlements SET permanently_deleted_at = NOW() WHERE guild_id = $1`, [entitlement.guild_id]).catch(() => null);
      await recordPremiumBillingEvent(entitlement.guild_id, 'data_purged', {});

      const guild = await client.guilds.fetch(entitlement.guild_id).catch(() => null);
      if (guild) {
        const dmEmbed = new EmbedBuilder()
          .setTitle('🗑️ GG Sports Premium — Locked Data Deleted')
          .setColor(0x2B2D31)
          .setDescription(`The following locked league(s) have been permanently deleted after the grace period elapsed with no reactivation: **${leagueNames.join(', ')}**. This cannot be undone.`)
          .setFooter({ text: 'GG Sports • Premium' })
          .setTimestamp();
        await dmPremiumNotice(guild, entitlement, dmEmbed).catch(() => null);
      }
    }
  } catch (error) {
    console.error('[7J-PREMIUM] Purge tick failed:', error);
  } finally {
    premiumPurgeRunning = false;
  }
}

function startPremiumPurgeLoop(client) {
  if (premiumPurgeTimer) clearInterval(premiumPurgeTimer);
  premiumPurgeTimer = setInterval(() => {
    runPremiumPurgeTick(client).catch(error => console.error('[7J-PREMIUM] Purge tick failed:', error));
  }, 6 * 60 * 60 * 1000);
  setTimeout(() => runPremiumPurgeTick(client).catch(() => null), 120 * 1000);
}

