// --- Business metrics (spec Section 10) --------------------------------------

async function buildPremiumMetricsEmbed() {
  const [activeStripeResult, manualResult, mrrInputResult, trialStartedResult, trialConvertedResult,
    everPaidResult, lapsedResult, recoveryResult] = await Promise.all([
    pool.query(`SELECT plan, COUNT(*)::int AS count FROM premium_entitlements WHERE source = 'stripe' AND status IN ('active','past_due') GROUP BY plan`),
    pool.query(`SELECT COUNT(*)::int AS count FROM premium_entitlements WHERE source = 'manual' AND status = 'active' AND (manual_expires_at IS NULL OR manual_expires_at > NOW())`),
    pool.query(`SELECT plan, COUNT(*)::int AS count FROM premium_entitlements WHERE source = 'stripe' AND status IN ('active','past_due') GROUP BY plan`),
    pool.query(`SELECT COUNT(DISTINCT guild_id)::int AS count FROM premium_billing_events WHERE event_type = 'trial_started'`),
    pool.query(`SELECT COUNT(DISTINCT guild_id)::int AS count FROM premium_billing_events WHERE event_type = 'trial_converted'`),
    pool.query(`SELECT COUNT(DISTINCT guild_id)::int AS count FROM premium_billing_events WHERE event_type IN ('payment_succeeded', 'trial_converted')`),
    pool.query(`SELECT COUNT(DISTINCT guild_id)::int AS count FROM premium_billing_events WHERE event_type = 'lapsed'`),
    pool.query(`
      WITH lapses AS (
        SELECT guild_id, created_at AS lapsed_at FROM premium_billing_events WHERE event_type = 'lapsed'
      )
      SELECT
        COUNT(*)::int AS total_lapses,
        COUNT(*) FILTER (WHERE EXISTS (
          SELECT 1 FROM premium_billing_events e
          WHERE e.guild_id = lapses.guild_id
            AND e.event_type IN ('payment_succeeded', 'manual_grant')
            AND e.created_at > lapses.lapsed_at
            AND e.created_at <= lapses.lapsed_at + INTERVAL '${PREMIUM_GRACE_PERIOD_DAYS} days'
        ))::int AS recovered_count
      FROM lapses
    `),
  ]);

  const activeByPlan = Object.fromEntries(mrrInputResult.rows.map(r => [r.plan || 'unknown', r.count]));
  const monthlyCount = activeByPlan.monthly || 0;
  const annualCount = activeByPlan.annual || 0;
  const manualCount = manualResult.rows[0]?.count || 0;
  const mrrCents = monthlyCount * PREMIUM_MONTHLY_PRICE_CENTS + annualCount * (PREMIUM_ANNUAL_PRICE_CENTS / 12);
  const activePaidCount = monthlyCount + annualCount;

  const trialStarted = trialStartedResult.rows[0]?.count || 0;
  const trialConverted = trialConvertedResult.rows[0]?.count || 0;
  const conversionRate = trialStarted ? (trialConverted / trialStarted) * 100 : 0;

  const everPaid = everPaidResult.rows[0]?.count || 0;
  const lapsedCount = lapsedResult.rows[0]?.count || 0;
  const churnRate = everPaid ? (lapsedCount / everPaid) * 100 : 0;

  const arpu = activePaidCount ? mrrCents / activePaidCount / 100 : 0;

  const totalLapses = recoveryResult.rows[0]?.total_lapses || 0;
  const recoveredCount = recoveryResult.rows[0]?.recovered_count || 0;
  const recoveryRate = totalLapses ? (recoveredCount / totalLapses) * 100 : 0;

  return new EmbedBuilder()
    .setTitle('GG Sports Premium — Business Metrics')
    .setColor(0x5865F2)
    .addFields(
      { name: 'MRR', value: `$${(mrrCents / 100).toFixed(2)}`, inline: true },
      { name: 'Active Paid Guilds', value: `${activePaidCount} (${monthlyCount} monthly / ${annualCount} annual)`, inline: true },
      { name: 'Manual Comp Guilds', value: String(manualCount), inline: true },
      { name: 'Trial → Paid Conversion', value: `${conversionRate.toFixed(1)}% (${trialConverted}/${trialStarted})`, inline: true },
      { name: 'Churn Rate (lifetime)', value: `${churnRate.toFixed(1)}% (${lapsedCount}/${everPaid} ever-paid)`, inline: true },
      { name: 'ARPU', value: `$${arpu.toFixed(2)}/mo`, inline: true },
      { name: `Grace Recovery (${PREMIUM_GRACE_PERIOD_DAYS}d)`, value: `${recoveryRate.toFixed(1)}% (${recoveredCount}/${totalLapses})`, inline: true },
    )
    .setFooter({ text: 'GG Sports • Premium Metrics (v1, lifetime totals)' })
    .setTimestamp();
}


function buildLegacyLeaderboardEmbed(rows) {
  const NL = String.fromCharCode(10);
  const embed = new EmbedBuilder()
    .setTitle('🏆 Legacy Leaderboard')
    .setColor(0xFEE75C)
    .setFooter({ text: 'GG Sports • Legacy Rankings' })
    .setTimestamp();

  if (!rows.length) {
    embed.setDescription('No legacy profiles found yet.');
    return embed;
  }

  embed.setDescription(
    rows.map((row, index) => {
      const activityPoints = Number(row.activity_points || row.recognition_points || 0);
      return '**' + (index + 1) + '. <@' + row.user_id + '>** — Legacy: ' + row.legacy_score + ' • Activity: ' + activityPoints + ' • Tier: ' + getLegacyTier(row.legacy_score);
    }).join(NL)
  );

  return embed;
}

function buildActivityLeaderboardEmbed(rows, title = '⚡ Activity Leaderboard') {
  const NL = String.fromCharCode(10);
  const embed = new EmbedBuilder()
    .setTitle(title)
    .setColor(0x57F287)
    .setFooter({ text: 'GG Sports • Activity Rankings' })
    .setTimestamp();

  if (!rows.length) {
    embed.setDescription('No activity profiles found yet.');
    return embed;
  }

  embed.setDescription(
    rows.map((row, index) => {
      const activityPoints = Number(row.activity_points || row.recognition_points || 0);
      // 7J-43ACTIVITY: activity_streak only exists on the server-scoped
      // table — league/universal rows won't have it, hence the || 0 fallback
      // rendering it as 0 rather than throwing on the missing field.
      return '**' + (index + 1) + '. <@' + row.user_id + '>** — Activity: ' + activityPoints + ' • Streak: ' + (row.activity_streak || 0) + ' • Tier: ' + getActivityTier(activityPoints);
    }).join(NL)
  );

  return embed;
}

async function getSportsbookSettings(guildId) {
  await pool.query(
    `INSERT INTO sportsbook_settings (guild_id)
     VALUES ($1)
     ON CONFLICT (guild_id) DO NOTHING`,
    [guildId]
  );

  const result = await pool.query(`SELECT * FROM sportsbook_settings WHERE guild_id = $1`, [guildId]);
  return result.rows[0] || { guild_id: guildId, feed_channel_id: null, big_bet_threshold: 500 };
}

// 7J-FEEDCHANNELFIX: per Hxxdie — the feed stayed completely silent even
// after the earlier logging fix, because it was silently no-op'ing on its
// very first line (no channel configured) before ever reaching that
// logging. Root cause: two disconnected "sportsbook feed channel" settings
// existed in this codebase. Madden's own sportsbook-line posting path
// already correctly prioritizes league.sportsbook_channel_id (the
// per-league setting Auto Setup actually creates a real "sportsbook-feed"
// channel for) — this generic function instead only ever read the
// guild-wide sportsbook_settings.feed_channel_id, which nothing
// auto-populates and which nobody had manually configured. Now takes an
// optional leagueId and prioritizes the per-league channel, matching
// Madden's already-correct behavior, while still falling back to the
// guild-wide setting for anyone who did configure that manually.
async function postSportsbookFeed(guild, embed, leagueId = null) {
  const settings = await getSportsbookSettings(guild.id);
  let feedChannelId = settings.feed_channel_id || null;
  if (leagueId) {
    const league = await getLeagueById(leagueId).catch(() => null);
    if (league?.sportsbook_channel_id) feedChannelId = league.sportsbook_channel_id;
  }
  if (!feedChannelId) return;

  const channel = await guild.channels.fetch(feedChannelId).catch(err => {
    console.error(`[SPORTSBOOK FEED] channel fetch failed for ${feedChannelId}:`, err?.message || err);
    if (isDiscordPermissionError(err)) {
      notifyOwnerOfBotPermissionIssue(guild, `sportsbookfeed:${feedChannelId}`, feedChannelId,
        `I can't see your Sportsbook Feed channel, so nothing has been posting there.`).catch(() => null);
    }
    return null;
  });
  if (!channel || !channel.isTextBased()) return;
  await channel.send({ embeds: [embed] }).catch(err => {
    console.error(`[SPORTSBOOK FEED] send failed in #${channel.name}:`, err?.message || err);
    if (isDiscordPermissionError(err)) {
      notifyOwnerOfBotPermissionIssue(guild, `sportsbookfeed:${feedChannelId}`, feedChannelId,
        `I don't have permission to send messages in **#${channel.name}**, so your Sportsbook Feed hasn't been posting.`).catch(() => null);
    }
  });
}

// 7J-PAYOUTDISCLOSURE: "Potential Payout" was showing the pre-fee gross
// figure (calculateAmericanOddsPayout's raw output) at bet-placement time,
// but settlement always pays out net of the 10% booking fee on winnings
// (computeSportsbookNetPayout, above). A bettor advertised 116 and actually
// paid 107 has no way to know that gap is an intentional, disclosed fee
// rather than a bug — so this now shows the real number they'll get if they
// win, and states the fee explicitly rather than leaving it to be inferred
// after the fact.
