function getLegacyTierIcon(tier) {
  const name = String(tier?.name || tier || '').toLowerCase();
  if (name.includes('goat')) return '👑';
  if (name.includes('legend')) return '🔥';
  if (name.includes('elite')) return '💎';
  if (name.includes('veteran')) return '🛡';
  return '⭐';
}

function getActivityTierIcon(tier) {
  const name = String(tier?.name || tier || '').toLowerCase();
  if (name.includes('grinder') || name.includes('icon')) return '💀';
  if (name.includes('dedicated') || name.includes('elite')) return '🏹';
  if (name.includes('active')) return '🚀';
  if (name.includes('casual') || name.includes('rookie')) return '⚡';
  return '🌱';
}

function normalizeActivityTierName(tier) {
  const name = String(tier?.name || tier || '').toLowerCase();
  if (name.includes('grinder') || name.includes('icon')) return 'Grinder';
  if (name.includes('dedicated') || name.includes('elite')) return 'Dedicated';
  if (name.includes('active')) return 'Active';
  if (name.includes('casual') || name.includes('rookie')) return 'Casual';
  return 'Inactive';
}


async function awardUserBadge(guildId, userId, badgeKey, badgeLabel, badgeIcon, source = null) {
  await pool.query(
    `INSERT INTO user_badges (guild_id, user_id, badge_key, badge_label, badge_icon, source)
     VALUES ($1, $2, $3, $4, $5, $6)
     ON CONFLICT (guild_id, user_id, badge_key)
     DO UPDATE SET badge_label = $4, badge_icon = $5, source = COALESCE($6, user_badges.source)`,
    [guildId, userId, badgeKey, badgeLabel, badgeIcon, source]
  );
}

async function getUserStreamUrl(guildId, userId) {
  const result = await pool.query(
    `SELECT stream_url FROM guild_stream_links WHERE guild_id = $1 AND user_id = $2
     UNION
     SELECT stream_url FROM stream_links WHERE user_id = $2
     LIMIT 1`,
    [guildId, userId]
  );
  return result.rows[0]?.stream_url || null;
}

async function syncProfileBadges(guildId, userId, recognition = null) {
  const row = recognition || (await pool.query(
    `SELECT * FROM user_recognition WHERE guild_id = $1 AND user_id = $2 LIMIT 1`,
    [guildId, userId]
  )).rows[0] || {};

  const legacyScore = Number(row.legacy_score || 0);
  const activityPoints = Number(row.activity_points || 0);
  const championships = Number(row.championships || 0);
  const sportsbookWins = Number(row.sportsbook_wins || 0);
  const sportsbookProfit = Number(row.sportsbook_profit || 0);

  const legacyTier = typeof getLegacyTier === 'function' ? getLegacyTier(legacyScore) : { name: 'Rising Star' };
  const activityTier = typeof getActivityTier === 'function' ? getActivityTier(activityPoints) : { name: 'Inactive' };
  const legacyName = legacyTier.name || legacyTier;
  const activityName = normalizeActivityTierName(activityTier);

  if (legacyName === 'GOAT') await awardUserBadge(guildId, userId, 'legacy_goat', 'GOAT Legacy', '👑', 'legacy');
  if (legacyName === 'Legend') await awardUserBadge(guildId, userId, 'legacy_legend', 'Legend Legacy', '🔥', 'legacy');
  if (legacyName === 'Elite') await awardUserBadge(guildId, userId, 'legacy_elite', 'Elite Legacy', '💎', 'legacy');
  if (activityName === 'Dedicated') await awardUserBadge(guildId, userId, 'activity_dedicated', 'Dedicated Activity', '🏹', 'activity');
  if (activityName === 'Grinder') await awardUserBadge(guildId, userId, 'activity_grinder', 'Grinder Activity', '💀', 'activity');
  if (sportsbookWins > 0) await awardUserBadge(guildId, userId, 'sportsbook_winner', 'Sportsbook Winner', '🎰', 'sportsbook');
  if (sportsbookProfit >= 10000) await awardUserBadge(guildId, userId, 'big_bettor', 'Big Bettor', '💰', 'sportsbook');
  if (championships > 0) await awardUserBadge(guildId, userId, 'champion', 'Champion', '🏆', 'legacy');

  const streamUrl = await getUserStreamUrl(guildId, userId).catch(() => null);
  if (streamUrl) await awardUserBadge(guildId, userId, 'streamer', 'Streamer', '📺', 'stream');
}





const VISUAL_AVATAR_SLOTS = ['hair', 'headwear', 'top', 'bottom', 'accessory', 'footwear', 'pet', 'effect', 'background'];

// Accessory items (avatar_slot = 'accessory') are further grouped by type so a player
// can equip one of each type at once (necklace + bracelet + glasses) via
// avatar_equipped_accessories, rather than being limited to a single accessory overall.
const ACCESSORY_TYPES = ['neck', 'wrist', 'face', 'ears', 'legs', 'other'];
// Total simultaneous accessories a player can have equipped at once, regardless of how
// many distinct types exist — keeps avatars from getting visually cluttered as more
// accessory types get added later.
const ACCESSORY_EQUIP_CAP = 4;

// Render order, back to front — headwear is drawn after hair specifically so it visually
// covers/replaces it; the renderer additionally skips the hair layer outright whenever
// headwear is equipped (see buildAvatarProfileAttachment) rather than relying on draw
// order alone, since some headwear art may not fully occlude hair drawn beneath it.
// Hair is drawn after top (not before) — per Hxxdie, longer hairstyles are designed to
// flow down over a top/shirt, so hair needs to composite on top of it, not underneath.
const AVATAR_LAYER_RENDER_ORDER = ['background', 'pet', 'body', 'bottom', 'top', 'hair', 'footwear', 'headwear', 'accessory', 'effect'];

// Short, human-typeable lookup code for a purchased/awarded inventory item (e.g.
// "GG-7F3K9Q"), surfaced in the Locker Room so a player can pull up an item's full
// details (rarity, exclusive status, serial number, purchase date, price paid) later.
function generateInventoryLookupTag() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no 0/O/1/I to avoid ambiguity
  let code = '';
  for (let i = 0; i < 6; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return `GG-${code}`;
}

// Assigns the next serial number for a limited-stock item: (units already sold + 1).
// Returns null for items with unlimited stock (nothing to number). Call this inside the
// same purchase flow that decrements shop_items.stock, before the decrement, so the
// count reflects units sold prior to this purchase.
async function getNextSerialNumber(dbPool, itemId) {
  const itemResult = await dbPool.query(`SELECT stock FROM shop_items WHERE id = $1`, [itemId]);
  const item = itemResult.rows[0];
  if (!item || item.stock === null || item.stock === undefined) return null; // unlimited stock, not numbered
  const soldResult = await dbPool.query(
    `SELECT COUNT(*)::int AS count FROM user_inventory WHERE item_id = $1 AND serial_number IS NOT NULL`,
    [itemId]
  );
  return Number(soldResult.rows[0].count) + 1;
}

// 7J-109PRODNUM: assigns the next global "production number" for an item, keyed by
// item NAME (case-insensitive, trimmed) — NOT scoped to guild, item_id, or stock
// limits. Every unit of e.g. "Hoodie" ever purchased/awarded/gifted, anywhere this
// bot runs, shares one forever-incrementing sequence — distinct from
// getNextSerialNumber above, which is scoped to a single shop_items row and only
// fires for limited-stock runs (that one powers the "#7/50" limited-edition display).
// quantity > 1 atomically reserves a contiguous block (e.g. buying 3 in one cart
// checkout gets #41, #42, #43) in a single round trip rather than one query per unit.
async function getNextProductionNumber(dbPool, itemName, quantity = 1) {
  const key = String(itemName || '').trim().toLowerCase();
  if (!key || !Number.isInteger(quantity) || quantity < 1) return null;
  await dbPool.query(
    `INSERT INTO item_production_counters (item_name_key, next_number) VALUES ($1, 1)
     ON CONFLICT (item_name_key) DO NOTHING`,
    [key]
  );
  const result = await dbPool.query(
    `UPDATE item_production_counters SET next_number = next_number + $2
     WHERE item_name_key = $1 RETURNING next_number - $2 AS assigned`,
    [key, quantity]
  );
  return Number(result.rows[0].assigned);
}

const VISUAL_AVATAR_STARTERS = [
  { item: 'Basic Sneakers', slot: 'footwear', source: 'starter' },
  { item: 'Ghost Wristband', slot: 'accessory', source: 'starter' },
  { item: 'Locker Room', slot: 'background', source: 'starter' },
];

function avatarColorForItem(itemName, fallback) {
  const item = String(itemName || '').toLowerCase();
  if (item.includes('ghost')) return '#f5d742';
  if (item.includes('gold')) return '#f6c343';
  if (item.includes('silver')) return '#cfd8dc';
  if (item.includes('elite')) return '#00b0ff';
  if (item.includes('crown')) return '#ffd700';
  if (item.includes('betting') || item.includes('shades')) return '#111827';
  if (item.includes('hoodie')) return '#111111';
  if (item.includes('jersey')) return '#2563eb';
  if (item.includes('championship')) return '#7c3aed';
  if (item.includes('varsity')) return '#dc2626';
  if (item.includes('basic tee')) return '#ffffff';
  if (item.includes('black')) return '#111111';
  if (item.includes('white')) return '#ffffff';
  if (item.includes('red')) return '#dc2626';
  if (item.includes('blue')) return '#2563eb';
  if (item.includes('green')) return '#16a34a';
  if (item.includes('purple')) return '#7c3aed';
  if (item.includes('pink')) return '#db2777';
  if (item.includes('orange')) return '#ea580c';
  if (item.includes('shorts')) return '#2f3542';
  if (item.includes('joggers')) return '#111827';
  if (item.includes('pants')) return '#374151';
  if (item.includes('sneakers')) return '#f8fafc';
  if (item.includes('slides')) return '#fde68a';
  return fallback;
}

async function grantVisualAvatarItem(guildId, userId, itemName, slot, source = 'unlock') {
  await pool.query(
    `INSERT INTO user_avatar_inventory (guild_id, user_id, item_name, slot, source)
     VALUES ($1, $2, $3, $4, $5)
     ON CONFLICT (guild_id, user_id, item_name)
     DO UPDATE SET slot = $4, source = COALESCE(user_avatar_inventory.source, $5)`,
    [guildId, userId, itemName, slot, source]
  );
}

async function ensureVisualAvatar(guildId, userId) {
  await pool.query(
    `INSERT INTO user_avatar (guild_id, user_id)
     VALUES ($1, $2)
     ON CONFLICT (guild_id, user_id) DO NOTHING`,
    [guildId, userId]
  );

  for (const item of VISUAL_AVATAR_STARTERS) {
    await grantVisualAvatarItem(guildId, userId, item.item, item.slot, item.source);
  }

  const result = await pool.query(
    `SELECT * FROM user_avatar WHERE guild_id = $1 AND user_id = $2 LIMIT 1`,
    [guildId, userId]
  );

  return result.rows[0] || {
    equipped_top: 'none',
    equipped_bottom: 'none',
    equipped_headwear: 'none',
    equipped_accessory: 'Ghost Wristband',
    equipped_footwear: 'Basic Sneakers',
    equipped_pet: 'none',
    equipped_effect: 'none',
    equipped_background: 'Locker Room',
  };
}

async function syncVisualAvatarUnlocks(guildId, userId, recognition = null) {
  await ensureVisualAvatar(guildId, userId);

  const row = recognition || (await pool.query(
    `SELECT * FROM user_recognition WHERE guild_id = $1 AND user_id = $2 LIMIT 1`,
    [guildId, userId]
  )).rows[0] || {};

  const activityTier = typeof getActivityTier === 'function' ? getActivityTier(Number(row.activity_points || 0)) : { name: 'Inactive' };
  const legacyTier = typeof getLegacyTier === 'function' ? getLegacyTier(Number(row.legacy_score || 0)) : { name: 'Rising Star' };
  const activityName = typeof normalizeActivityTierName === 'function' ? normalizeActivityTierName(activityTier) : String(activityTier.name || activityTier);
  const legacyName = legacyTier.name || legacyTier;
  const sportsbookWins = Number(row.sportsbook_wins || 0);

  if (['Active', 'Dedicated', 'Grinder'].includes(activityName)) await grantVisualAvatarItem(guildId, userId, 'Ghost Wristband', 'accessory', 'activity');
  if (['Dedicated', 'Grinder'].includes(activityName)) await grantVisualAvatarItem(guildId, userId, 'Ghost Hoodie', 'top', 'activity');
  if (activityName === 'Grinder') await grantVisualAvatarItem(guildId, userId, 'Elite Sneakers', 'footwear', 'activity');

  if (['Veteran', 'Elite', 'Legend', 'GOAT'].includes(legacyName)) await grantVisualAvatarItem(guildId, userId, 'Silver Chain', 'accessory', 'legacy');
  if (['Elite', 'Legend', 'GOAT'].includes(legacyName)) await grantVisualAvatarItem(guildId, userId, 'Gold Chain', 'accessory', 'legacy');
  if (['Legend', 'GOAT'].includes(legacyName)) await grantVisualAvatarItem(guildId, userId, 'Aura Effect', 'effect', 'legacy');
  if (legacyName === 'GOAT') await grantVisualAvatarItem(guildId, userId, 'Crown', 'headwear', 'legacy');

  if (sportsbookWins >= 1) await grantVisualAvatarItem(guildId, userId, 'Betting Shades', 'headwear', 'sportsbook');
  if (sportsbookWins >= 10) await grantVisualAvatarItem(guildId, userId, 'High Roller Watch', 'accessory', 'sportsbook');

  await grantVisualAvatarItem(guildId, userId, 'Arena Tunnel', 'background', 'starter');
  await grantVisualAvatarItem(guildId, userId, 'Practice Court', 'background', 'starter');
}





function avatarHexToRgb(hex, fallback = [255, 255, 255]) {
  const clean = String(hex || '').replace('#', '');
  if (clean.length !== 6) return fallback;
  return [
    parseInt(clean.slice(0, 2), 16),
    parseInt(clean.slice(2, 4), 16),
    parseInt(clean.slice(4, 6), 16),
  ];
}

function avatarCrc32(buffer) {
  let crc = 0xffffffff;
  for (let i = 0; i < buffer.length; i++) {
    crc ^= buffer[i];
    for (let j = 0; j < 8; j++) {
      crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1));
    }
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function avatarPngChunk(type, data) {
  const typeBuffer = Buffer.from(type);
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length, 0);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(avatarCrc32(Buffer.concat([typeBuffer, data])), 0);
  return Buffer.concat([length, typeBuffer, data, crc]);
}

function avatarEncodePng(width, height, rgba) {
  const raw = Buffer.alloc((width * 4 + 1) * height);
  for (let y = 0; y < height; y++) {
    const rowStart = y * (width * 4 + 1);
    raw[rowStart] = 0;
    rgba.copy(raw, rowStart + 1, y * width * 4, (y + 1) * width * 4);
  }

  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8;
  ihdr[9] = 6;
  ihdr[10] = 0;
  ihdr[11] = 0;
  ihdr[12] = 0;

  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    avatarPngChunk('IHDR', ihdr),
    avatarPngChunk('IDAT', zlib.deflateSync(raw)),
    avatarPngChunk('IEND', Buffer.alloc(0)),
  ]);
}

function avatarCanvas(width, height, color = [24, 24, 27, 255]) {
  const buffer = Buffer.alloc(width * height * 4);
  for (let i = 0; i < width * height; i++) {
    const p = i * 4;
    buffer[p] = color[0];
    buffer[p + 1] = color[1];
    buffer[p + 2] = color[2];
    buffer[p + 3] = color[3];
  }
  return buffer;
}

function avatarPixel(buffer, width, height, x, y, color) {
  if (x < 0 || y < 0 || x >= width || y >= height) return;
  const p = (Math.floor(y) * width + Math.floor(x)) * 4;
  buffer[p] = color[0];
  buffer[p + 1] = color[1];
  buffer[p + 2] = color[2];
  buffer[p + 3] = color[3] ?? 255;
}

function avatarRect(buffer, width, height, x, y, w, h, color) {
  for (let yy = Math.max(0, y); yy < Math.min(height, y + h); yy++) {
    for (let xx = Math.max(0, x); xx < Math.min(width, x + w); xx++) {
      avatarPixel(buffer, width, height, xx, yy, color);
    }
  }
}

function avatarEllipse(buffer, width, height, cx, cy, rx, ry, color) {
  const minX = Math.floor(cx - rx);
  const maxX = Math.ceil(cx + rx);
  const minY = Math.floor(cy - ry);
  const maxY = Math.ceil(cy + ry);
  for (let y = minY; y <= maxY; y++) {
    for (let x = minX; x <= maxX; x++) {
      const dx = (x - cx) / rx;
      const dy = (y - cy) / ry;
      if (dx * dx + dy * dy <= 1) avatarPixel(buffer, width, height, x, y, color);
    }
  }
}

function avatarLine(buffer, width, height, x0, y0, x1, y1, thickness, color) {
  const steps = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
  for (let i = 0; i <= steps; i++) {
    const t = steps === 0 ? 0 : i / steps;
    const x = x0 + (x1 - x0) * t;
    const y = y0 + (y1 - y0) * t;
    avatarEllipse(buffer, width, height, x, y, thickness, thickness, color);
  }
}

function avatarTriangle(buffer, width, height, points, color) {
  const [p0, p1, p2] = points;
  const minX = Math.floor(Math.min(p0[0], p1[0], p2[0]));
  const maxX = Math.ceil(Math.max(p0[0], p1[0], p2[0]));
  const minY = Math.floor(Math.min(p0[1], p1[1], p2[1]));
  const maxY = Math.ceil(Math.max(p0[1], p1[1], p2[1]));
  const area = (p1[1] - p2[1]) * (p0[0] - p2[0]) + (p2[0] - p1[0]) * (p0[1] - p2[1]);
  for (let y = minY; y <= maxY; y++) {
    for (let x = minX; x <= maxX; x++) {
      const a = ((p1[1] - p2[1]) * (x - p2[0]) + (p2[0] - p1[0]) * (y - p2[1])) / area;
      const b = ((p2[1] - p0[1]) * (x - p2[0]) + (p0[0] - p2[0]) * (y - p2[1])) / area;
      const c = 1 - a - b;
      if (a >= 0 && b >= 0 && c >= 0) avatarPixel(buffer, width, height, x, y, color);
    }
  }
}

// ---------------------------------------------------------------------------
// Real avatar system (Universal Avatar) — global per-user profile, real owned
// user_inventory rows per slot instead of name strings. Placeholder rendering reuses
// the existing hand-rolled pixel/PNG primitives above (avatarRect/avatarEllipse/
// avatarTriangle/avatarLine/avatarCanvas/avatarEncodePng) rather than adding a new
// dependency — when real AI-generated art lands, only renderAvatarProfilePng's
// internals need to change (draw calls -> layered PNG composites); the schema, equip
// logic, Locker Room, and Shop Hub below don't need to change at all.
// ---------------------------------------------------------------------------

const AVATAR_SLOTS = ['background', 'effect', 'pet', 'footwear', 'bottom', 'top', 'hair', 'headwear', 'accessory'];
const AVATAR_SLOT_LABELS = {
  background: 'Background', effect: 'Aura', pet: 'Pet', footwear: 'Shoes',
  bottom: 'Bottoms', top: 'Tops', hair: 'Hair', headwear: 'Hats', accessory: 'Accessories',
};
const AVATAR_BUILD_SCALE = { slim: 0.85, athletic: 1.0, built: 1.15, heavy: 1.3 };
const AVATAR_BUILDS = ['slim', 'athletic', 'built', 'heavy'];
const AVATAR_SKIN_TONES = {
  light: [240, 205, 172, 255],
  medium: [216, 164, 127, 255],
  tan: [186, 128, 86, 255],
  deep: [117, 79, 54, 255],
};
const AVATAR_SILHOUETTES = ['a', 'b'];

// Deterministic color for items avatarColorForItem's keyword list doesn't recognize —
// so two different unrecognized cosmetics still render visually distinct instead of
// both collapsing onto the same fallback color.
function avatarDeterministicColor(seed) {
  const str = String(seed || 'item');
  let hash = 0;
  for (let i = 0; i < str.length; i++) hash = (hash * 31 + str.charCodeAt(i)) >>> 0;
  const hue = hash % 360;
  const s = 0.55, l = 0.55;
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs((hue / 60) % 2 - 1));
  const m = l - c / 2;
  let r, g, b;
  if (hue < 60) [r, g, b] = [c, x, 0];
  else if (hue < 120) [r, g, b] = [x, c, 0];
  else if (hue < 180) [r, g, b] = [0, c, x];
  else if (hue < 240) [r, g, b] = [0, x, c];
  else if (hue < 300) [r, g, b] = [x, 0, c];
  else [r, g, b] = [c, 0, x];
  return [Math.round((r + m) * 255), Math.round((g + m) * 255), Math.round((b + m) * 255), 255];
}

async function getOrCreateAvatarProfile(userId) {
  await pool.query(
    `INSERT INTO avatar_profiles (user_id) VALUES ($1) ON CONFLICT (user_id) DO NOTHING`,
    [userId]
  );
  const result = await pool.query(`SELECT * FROM avatar_profiles WHERE user_id = $1`, [userId]);
  return result.rows[0];
}

async function getAvatarProfileWithEquipment(userId) {
  const profile = await getOrCreateAvatarProfile(userId);
  const result = await pool.query(
    `SELECT
       bg.item_name AS background_name, bg.id AS background_id, bg_si.art_asset_key AS background_art_key, bg.color_hex AS background_color_hex, COALESCE(bg_si.is_colorable, FALSE) AS background_is_colorable,
       eff.item_name AS effect_name, eff.id AS effect_id, eff_si.art_asset_key AS effect_art_key, eff.color_hex AS effect_color_hex, COALESCE(eff_si.is_colorable, FALSE) AS effect_is_colorable,
       pet.item_name AS pet_name, pet.id AS pet_id, pet_si.art_asset_key AS pet_art_key, pet.color_hex AS pet_color_hex, COALESCE(pet_si.is_colorable, FALSE) AS pet_is_colorable, COALESCE(pet_si.pet_position, 'left') AS pet_position, pet_si.pet_scale AS pet_scale,
       foot.item_name AS footwear_name, foot.id AS footwear_id, foot_si.art_asset_key AS footwear_art_key, foot.color_hex AS footwear_color_hex, COALESCE(foot_si.is_colorable, FALSE) AS footwear_is_colorable, COALESCE(foot_si.heel_lift_px, 0) AS footwear_heel_lift_px, foot_si.body_variant AS footwear_body_variant,
       bot.item_name AS bottom_name, bot.id AS bottom_id, bot_si.art_asset_key AS bottom_art_key, bot.color_hex AS bottom_color_hex, COALESCE(bot_si.is_colorable, FALSE) AS bottom_is_colorable,
       top.item_name AS top_name, top.id AS top_id, top_si.art_asset_key AS top_art_key, top.color_hex AS top_color_hex, COALESCE(top_si.is_colorable, FALSE) AS top_is_colorable,
       hair.item_name AS hair_name, hair.id AS hair_id, hair_si.art_asset_key AS hair_art_key, hair.color_hex AS hair_color_hex, COALESCE(hair_si.is_colorable, FALSE) AS hair_is_colorable,
       head.item_name AS headwear_name, head.id AS headwear_id, head_si.art_asset_key AS headwear_art_key, head.color_hex AS headwear_color_hex, COALESCE(head_si.is_colorable, FALSE) AS headwear_is_colorable,
       acc.item_name AS accessory_name, acc.id AS accessory_id, acc_si.art_asset_key AS accessory_art_key, acc.color_hex AS accessory_color_hex, COALESCE(acc_si.is_colorable, FALSE) AS accessory_is_colorable
     FROM avatar_profiles ap
     LEFT JOIN user_inventory bg   ON bg.id = ap.equipped_background_id
     LEFT JOIN shop_items bg_si    ON bg_si.id = bg.item_id
     LEFT JOIN user_inventory eff  ON eff.id = ap.equipped_effect_id
     LEFT JOIN shop_items eff_si   ON eff_si.id = eff.item_id
     LEFT JOIN user_inventory pet  ON pet.id = ap.equipped_pet_id
     LEFT JOIN shop_items pet_si   ON pet_si.id = pet.item_id
     LEFT JOIN user_inventory foot ON foot.id = ap.equipped_footwear_id
     LEFT JOIN shop_items foot_si  ON foot_si.id = foot.item_id
     LEFT JOIN user_inventory bot  ON bot.id = ap.equipped_bottom_id
     LEFT JOIN shop_items bot_si   ON bot_si.id = bot.item_id
     LEFT JOIN user_inventory top  ON top.id = ap.equipped_top_id
     LEFT JOIN shop_items top_si   ON top_si.id = top.item_id
     LEFT JOIN user_inventory hair ON hair.id = ap.equipped_hair_id
     LEFT JOIN shop_items hair_si  ON hair_si.id = hair.item_id
     LEFT JOIN user_inventory head ON head.id = ap.equipped_headwear_id
     LEFT JOIN shop_items head_si  ON head_si.id = head.item_id
     LEFT JOIN user_inventory acc  ON acc.id = ap.equipped_accessory_id
     LEFT JOIN shop_items acc_si   ON acc_si.id = acc.item_id
     WHERE ap.user_id = $1`,
    [userId]
  );
  const row = result.rows[0] || {};
  const equipped = {};
  for (const slot of AVATAR_SLOTS) {
    equipped[slot] = row[`${slot}_name`]
      ? { item_name: row[`${slot}_name`], inventory_id: row[`${slot}_id`], art_asset_key: row[`${slot}_art_key`] || null, color_hex: row[`${slot}_color_hex`] || null, is_colorable: !!row[`${slot}_is_colorable`] }
      : null;
  }
  // heel_lift_px and body_variant only exist on footwear — attached separately here
  // rather than adding columns to every slot's row-mapping above, since they're
  // meaningless everywhere else.
  if (equipped.footwear) {
    equipped.footwear.heel_lift_px = Number(row.footwear_heel_lift_px) || 0;
    equipped.footwear.body_variant = row.footwear_body_variant || null;
  }
  // pet_position/pet_scale only exist on pet, same reasoning.
  if (equipped.pet) {
    equipped.pet.pet_position = row.pet_position || 'left';
    equipped.pet.pet_scale = row.pet_scale !== null && row.pet_scale !== undefined ? Number(row.pet_scale) : null;
  }
  // Accessories are multi-equip (see avatar_equipped_accessories) — the legacy single
  // equipped.accessory field above still reflects the old equipped_accessory_id column
  // (left in place, unused going forward) so nothing relying on it breaks; new code
  // should use equipped.accessories (plural, array) instead.
  const accessoryRows = await pool.query(
    `SELECT eq.accessory_type, ui.id AS inventory_id, ui.item_name, ui.color_hex, si.art_asset_key, COALESCE(si.is_colorable, FALSE) AS is_colorable
     FROM avatar_equipped_accessories eq
     JOIN user_inventory ui ON ui.id = eq.item_id
     LEFT JOIN shop_items si ON si.id = ui.item_id
     WHERE eq.user_id = $1
     ORDER BY eq.accessory_type`,
    [userId]
  );
  equipped.accessories = accessoryRows.rows.map(r => ({
    accessory_type: r.accessory_type, item_name: r.item_name, inventory_id: r.inventory_id,
    art_asset_key: r.art_asset_key || null, color_hex: r.color_hex || null, is_colorable: !!r.is_colorable,
  }));
  return { profile, equipped };
}

// Validates ownership + slot match, then equips. Returns { ok, message }.
async function equipAvatarItem(userId, slot, inventoryId) {
  if (!AVATAR_SLOTS.includes(slot)) return { ok: false, message: 'Unknown slot.' };

  const itemResult = await pool.query(
    `SELECT ui.*, si.avatar_slot AS shop_avatar_slot, si.gender_lock AS shop_gender_lock
     FROM user_inventory ui
     LEFT JOIN shop_items si ON si.id = ui.item_id
     WHERE ui.id = $1 AND ui.user_id = $2
     LIMIT 1`,
    [inventoryId, userId]
  );
  const item = itemResult.rows[0];
  if (!item) return { ok: false, message: 'You do not own that item.' };

  const resolvedSlot = item.shop_avatar_slot || inferAvatarSlotFromItem(item);
  if (resolvedSlot !== slot) {
    return { ok: false, message: `**${item.item_name}** is a ${AVATAR_SLOT_LABELS[resolvedSlot] || resolvedSlot} item, not ${AVATAR_SLOT_LABELS[slot] || slot}.` };
  }

  const profileForGenderCheck = await getOrCreateAvatarProfile(userId);
  if (item.shop_gender_lock && genderFromBodyKey(profileForGenderCheck.body_key) !== item.shop_gender_lock) {
    return { ok: false, message: `**${item.item_name}** isn't available for your current body type.` };
  }

  await pool.query(
    `UPDATE avatar_profiles SET equipped_${slot}_id = $1, updated_at = NOW() WHERE user_id = $2`,
    [inventoryId, userId]
  );
  return { ok: true, message: `Equipped **${item.item_name}**.` };
}

async function unequipAvatarSlot(userId, slot) {
  if (!AVATAR_SLOTS.includes(slot)) return { ok: false, message: 'Unknown slot.' };
  await getOrCreateAvatarProfile(userId);
  await pool.query(`UPDATE avatar_profiles SET equipped_${slot}_id = NULL, updated_at = NOW() WHERE user_id = $1`, [userId]);
  return { ok: true, message: `Unequipped ${AVATAR_SLOT_LABELS[slot] || slot}.` };
}

// Multi-equip accessories (necklace + bracelet + glasses simultaneously) — separate
// from equipAvatarItem/unequipAvatarSlot above, which only handle single-column slots.
// One item per accessory_type at a time (equipping a second necklace replaces the
// first, via the table's PRIMARY KEY (user_id, accessory_type)); total simultaneous
// accessories across all types capped at ACCESSORY_EQUIP_CAP.
async function equipAvatarAccessory(userId, inventoryId) {
  const itemResult = await pool.query(
    `SELECT ui.*, si.avatar_slot AS shop_avatar_slot, si.accessory_type
     FROM user_inventory ui
     LEFT JOIN shop_items si ON si.id = ui.item_id
     WHERE ui.id = $1 AND ui.user_id = $2
     LIMIT 1`,
    [inventoryId, userId]
  );
  const item = itemResult.rows[0];
  if (!item) return { ok: false, message: 'You do not own that item.' };

  const resolvedSlot = item.shop_avatar_slot || inferAvatarSlotFromItem(item);
  if (resolvedSlot !== 'accessory') {
    return { ok: false, message: `**${item.item_name}** is not an accessory.` };
  }
  const accessoryType = ACCESSORY_TYPES.includes(item.accessory_type) ? item.accessory_type : 'other';

  const existingResult = await pool.query(`SELECT accessory_type FROM avatar_equipped_accessories WHERE user_id = $1`, [userId]);
  const alreadyHasThisType = existingResult.rows.some(r => r.accessory_type === accessoryType);
  if (!alreadyHasThisType && existingResult.rows.length >= ACCESSORY_EQUIP_CAP) {
    return { ok: false, message: `You can only have ${ACCESSORY_EQUIP_CAP} accessories equipped at once. Unequip one first.` };
  }

  await pool.query(
    `INSERT INTO avatar_equipped_accessories (user_id, item_id, accessory_type, equipped_at)
     VALUES ($1, $2, $3, NOW())
     ON CONFLICT (user_id, accessory_type) DO UPDATE SET item_id = EXCLUDED.item_id, equipped_at = NOW()`,
    [userId, inventoryId, accessoryType]
  );
  return { ok: true, message: `Equipped **${item.item_name}**.` };
}

async function unequipAvatarAccessory(userId, accessoryType) {
  await pool.query(`DELETE FROM avatar_equipped_accessories WHERE user_id = $1 AND accessory_type = $2`, [userId, accessoryType]);
  return { ok: true, message: `Unequipped ${accessoryType}.` };
}

// Looks up an exclusive (is_award_only) item by a loose case-insensitive name match,
// scoped to this guild's own items plus universal (guild_id IS NULL) ones. findShopItem
// can't be reused here since it deliberately filters is_award_only = FALSE (so award
// items can't be found/bought through normal shop browsing) — this is the mirror-image
// lookup for the handful of places, like achievement rewards, that need to grant one
// of those items on purpose.
async function findAwardOnlyShopItemByNamePattern(guildId, namePattern) {
  const result = await pool.query(
    `SELECT * FROM shop_items
     WHERE (guild_id = $1 OR guild_id IS NULL) AND is_active = TRUE AND is_award_only = TRUE
       AND item_name ILIKE $2
     ORDER BY created_at DESC
     LIMIT 1`,
    [guildId, `%${namePattern}%`]
  );
  return result.rows[0] || null;
}

// Grants an award item (MVP, Champion, Rookie of the Year, etc.) directly into a
// user's inventory, bypassing the shop entirely — no currency deducted, no stock
// decremented (award items aren't expected to set a stock limit; if one is set anyway,
// it's intentionally not enforced here since awards are earned, not bought). Tags the
// row with award_type so it's distinguishable from a normal purchase in the Locker Room
// / lookup-tag detail view. Does not auto-equip, matching how other grants work.
async function grantAwardItem(guildId, userId, itemId, awardType) {
  const itemResult = await pool.query(`SELECT * FROM shop_items WHERE id = $1 AND (guild_id = $2 OR guild_id IS NULL) LIMIT 1`, [itemId, guildId]);
  const item = itemResult.rows[0];
  if (!item) return { ok: false, message: 'Could not find that item.' };

  const inventoryId = randomUUID();
  const productionNumber = await getNextProductionNumber(pool, item.item_name);
  await pool.query(
    `INSERT INTO user_inventory (id, guild_id, user_id, item_id, item_name, price_paid, status, award_type, production_number, lookup_tag)
     VALUES ($1, $2, $3, $4, $5, 0, 'owned', $6, $7, $8)`,
    [inventoryId, guildId, userId, item.id, item.item_name, awardType, productionNumber, generateInventoryLookupTag()]
  );
  return { ok: true, item, inventoryId };
}

// 7J-AUTOAWARDS: per Hxxdie — replaces commissioners hand-picking which
// cosmetic to grant. Counts how many times this person has already won
// this exact milestone (champion or MVP), picks the highest tier item
// they've earned (an item tagged tier 3 requires 3 prior wins — "prior"
// because the current win, if this is being called for the win that just
// happened, hasn't been archived to user_season_history yet), and grants
// it automatically. Falls back to the highest tier that actually exists if
// the server hasn't set up every tier yet, so a repeat winner still gets
// SOMETHING rather than nothing just because tier 4 doesn't exist.
async function autoGrantTieredAward(guild, league, ownerId, teamName, triggerType) {
  if (!guild || !ownerId || !['champion', 'mvp'].includes(triggerType)) return null;

  const priorWinsResult = await pool.query(
    `SELECT COUNT(*)::int AS n FROM user_season_history WHERE guild_id = $1 AND user_id = $2 AND ${triggerType === 'champion' ? 'champion' : 'mvp'} = TRUE`,
    [guild.id, ownerId]
  ).catch(() => ({ rows: [{ n: 0 }] }));
  const targetTier = Number(priorWinsResult.rows[0]?.n || 0) + 1;

  const itemResult = await pool.query(
    `SELECT * FROM shop_items
     WHERE (guild_id = $1 OR guild_id IS NULL) AND is_award_only = TRUE AND award_trigger = $2 AND award_trigger_tier <= $3
     ORDER BY award_trigger_tier DESC LIMIT 1`,
    [guild.id, triggerType, targetTier]
  );
  const item = itemResult.rows[0];
  if (!item) return null; // No item tagged for this trigger yet — nothing to grant, not an error.

  const awardTypeLabel = triggerType === 'champion' ? `Champion (Tier ${targetTier})` : `MVP (Tier ${targetTier})`;
  const grantResult = await grantAwardItem(guild.id, ownerId, item.id, awardTypeLabel);
  if (!grantResult.ok) return null;

  // 7J-AWARDDM: per Hxxdie — congratulate the recipient directly, not just
  // a note in a thread they may not even be in. DMs closed just means this
  // silently skips, same as every other DM in the bot — the grant itself
  // already happened regardless.
  const dmMember = await guild.members.fetch(ownerId).catch(() => null);
  if (dmMember) {
    const dmEmbed = new EmbedBuilder()
      .setTitle(triggerType === 'champion' ? '🏆 Congratulations, Champion!' : '⭐ Congratulations!')
      .setColor(0xFEE75C)
      .setDescription(
        triggerType === 'champion'
          ? `You led **${teamName}** to the **${league.league_name}** championship!`
          : `You were named **MVP** of **${league.league_name}**!`
      )
      .addFields({ name: 'Reward', value: `**${item.item_name}**${targetTier > 1 ? ` (Tier ${targetTier})` : ''} — already added to your inventory.`, inline: false })
      .setFooter({ text: 'GG Sports' })
      .setTimestamp();
    await dmMember.send({ embeds: [dmEmbed] }).catch(() => null); // DMs closed — skip silently, same as everywhere else.
  }

  // 7J-AUTOAWARDS: deliberately does NOT post a news event here —
  // postLeagueSeasonHistory (Season History) already posts league_champion
  // and award_winner news for every award, MVP included. Posting again here
  // would duplicate it. This function's only job is the item grant itself.
  // 7J-CHAMPIONROLLBACK: inventoryId is returned so the champion-decided
  // branch in recordPlayoffGameResult can track exactly which grant to
  // revoke if a dispute later rolls back this result with a different
  // winner — see resolvePlayoffDispute.
  return { item, tier: targetTier, inventoryId: grantResult.inventoryId };
}

// Grants a specific gift item to a specific user, once. Dedupes by checking whether
// this user already owns THIS item row — safe to call every scheduler tick without
// re-granting, since each year's gift is a distinct shop_items row (this year's
// Christmas item is a different id than last year's), so "already owns this exact
// item" is equivalent to "already got this year's gift."
async function grantGiftItemOnce(guildId, userId, item, giftType) {
  const existing = await pool.query(`SELECT id FROM user_inventory WHERE user_id = $1 AND item_id = $2 LIMIT 1`, [userId, item.id]);
  if (existing.rows.length) return false;
  const inventoryId = randomUUID();
  const productionNumber = await getNextProductionNumber(pool, item.item_name);
  await pool.query(
    `INSERT INTO user_inventory (id, guild_id, user_id, item_id, item_name, price_paid, status, award_type, production_number, lookup_tag)
     VALUES ($1, $2, $3, $4, $5, 0, 'owned', $6, $7, $8)`,
    [inventoryId, guildId, userId, item.id, item.item_name, giftType, productionNumber, generateInventoryLookupTag()]
  );
  return true;
}

// Christmas: grant to every non-bot member of the guild that owns this item's row.
// Full member fetch only happens on Dec 25 itself (see tick below), not every tick.
async function grantChristmasGiftToGuildMembers(guild, item) {
  const members = await guild.members.fetch().catch(() => null);
  if (!members) return 0;
  let granted = 0;
  for (const [, member] of members) {
    if (member.user.bot) continue;
    if (await grantGiftItemOnce(guild.id, member.id, item, 'christmas')) granted++;
  }
  return granted;
}

// ---------------------------------------------------------------------------
// Birthday & Christmas gift scheduler — checks once a day whether today is
// Christmas and/or anyone's stored birthday, and auto-grants that year's gift item
// (see shop_items.gift_type/gift_year, createcosmetic gift_type option) if one
// exists for this guild. Both are opt-in per guild: nothing is granted unless a bot
// owner has created that year's gift item for that specific guild via
// /shop createcosmetic gift_type:birthday|christmas.
// ---------------------------------------------------------------------------
// Sends a DM to the bot owner at most once per calendar year per reminder_key —
// dedupes via system_reminder_state so an hourly-ticking scheduler doesn't spam the
// same reminder all day, and a restart doesn't re-send one already sent this year.
async function sendAnnualReminderOnce(client, reminderKey, year, message) {
  if (!botOwnerUserId) return;
  const existing = await pool.query(`SELECT last_sent_year FROM system_reminder_state WHERE reminder_key = $1`, [reminderKey]);
  if (existing.rows[0]?.last_sent_year === year) return;
  const owner = await client.users.fetch(botOwnerUserId).catch(() => null);
  if (!owner) return;
  await owner.send({ content: message }).catch(error => console.error(`Failed to DM bot owner reminder '${reminderKey}':`, error));
  await pool.query(
    `INSERT INTO system_reminder_state (reminder_key, last_sent_year) VALUES ($1, $2)
     ON CONFLICT (reminder_key) DO UPDATE SET last_sent_year = $2`,
    [reminderKey, year]
  );
}

async function runBirthdayChristmasGiftSchedulerTick(client) {
  const now = new Date();
  const month = now.getUTCMonth() + 1;
  const day = now.getUTCDate();
  const year = now.getUTCFullYear();

  if (month === 12 && day === 1) {
    await sendAnnualReminderOnce(client, 'december_gift_items', year,
      `🎁 **Reminder: it's December 1st.** Time to create this year's gift items if you haven't yet — ` +
      `\`/shop createcosmetic gift_type:christmas gift_year:${year}\` for Christmas (auto-grants Dec 25), and ` +
      `\`/shop createcosmetic gift_type:birthday gift_year:${year}\` for birthdays, per server that wants them. ` +
      `Nothing grants automatically until these exist for a given server.`
    ).catch(error => console.error('December 1 gift-item reminder failed:', error));
  }

  if (month === 12 && day === 25) {
    const christmasItems = await pool.query(
      `SELECT * FROM shop_items WHERE gift_type = 'christmas' AND gift_year = $1 AND is_active = TRUE`,
      [year]
    );
    for (const item of christmasItems.rows) {
      const guild = client.guilds.cache.get(item.guild_id);
      if (!guild) continue;
      await grantChristmasGiftToGuildMembers(guild, item).catch(error =>
        console.error(`Christmas gift grant failed for guild ${item.guild_id}:`, error));
    }
  }

  const birthdayUsers = await pool.query(
    `SELECT user_id FROM user_birthdays WHERE birthday_month = $1 AND birthday_day = $2`,
    [month, day]
  );
  if (birthdayUsers.rows.length) {
    const birthdayItems = await pool.query(
      `SELECT * FROM shop_items WHERE gift_type = 'birthday' AND gift_year = $1 AND is_active = TRUE`,
      [year]
    );
    for (const item of birthdayItems.rows) {
      const guild = client.guilds.cache.get(item.guild_id);
      if (!guild) continue;
      for (const row of birthdayUsers.rows) {
        const member = await guild.members.fetch(row.user_id).catch(() => null);
        if (!member || member.user.bot) continue;
        await grantGiftItemOnce(guild.id, row.user_id, item, 'birthday').catch(error =>
          console.error(`Birthday gift grant failed for user ${row.user_id} in guild ${guild.id}:`, error));
      }
    }
  }
}

let birthdayChristmasGiftSchedulerTimer = null;
function startBirthdayChristmasGiftSchedulerLoop(client) {
  if (birthdayChristmasGiftSchedulerTimer) clearInterval(birthdayChristmasGiftSchedulerTimer);
  // Hourly tick — a gift only needs to land sometime during the right day, not to the
  // minute, and grantGiftItemOnce's dedupe makes repeat ticks on the same day free.
  birthdayChristmasGiftSchedulerTimer = setInterval(() => {
    runBirthdayChristmasGiftSchedulerTick(client).catch(error => console.error('Birthday/Christmas gift scheduler tick failed:', error));
  }, 60 * 60 * 1000);
  setTimeout(() => runBirthdayChristmasGiftSchedulerTick(client).catch(() => null), 30 * 1000);
}

// 7J-101REVIEW: two passes. Discovery finds every user currently holding a
// team role in any active league on any server the bot is in, and records
// the first time each one is ever seen (ON CONFLICT DO NOTHING — never
// overwrites an existing first_seen_at, so re-running this doesn't reset
// anyone's clock). Prompting DMs whoever has crossed the first-prompt or
// repeat-prompt threshold and hasn't confirmed a review yet. Both best-
// effort throughout — DMs closed, a user who left every mutual server, etc.
// all just silently skip rather than blocking the rest of the run.
async function runReviewPromptSchedulerTick(client) {
  if (!botSettingsCache.review_link || !botSettingsCache.review_prompt_enabled) return;

  // Discovery pass. 7J-PUBLICPREP-REVIEWSCALE: previously one awaited
  // INSERT per member (guild × league × team × member, all sequential) —
  // fine at 2 test servers, but a real cost once this runs across many
  // public guilds on a single daily tick. Now collects unique member IDs
  // per guild first and does one batched INSERT per guild instead. Same
  // ON CONFLICT DO NOTHING semantics, just fewer round trips.
  for (const guild of client.guilds.cache.values()) {
    const leagues = await getActiveLeaguesForGuild(guild.id).catch(() => []);
    const memberIds = new Set();
    for (const league of leagues) {
      const teams = await getLeagueTeamRoles(league.league_id).catch(() => []);
      for (const team of teams) {
        const role = guild.roles.cache.get(team.role_id);
        if (!role) continue;
        for (const member of role.members.values()) {
          if (member.user.bot) continue;
          memberIds.add(member.id);
        }
      }
    }
    if (!memberIds.size) continue;
    await pool.query(
      `INSERT INTO user_review_prompts (user_id)
       SELECT * FROM unnest($1::text[])
       ON CONFLICT (user_id) DO NOTHING`,
      [Array.from(memberIds)]
    ).catch(() => null);
  }

  // Prompting pass.
  const eligible = await pool.query(
    `SELECT user_id FROM user_review_prompts
     WHERE review_confirmed = FALSE
       AND first_seen_at <= NOW() - ($1::text || ' days')::interval
       AND (last_prompted_at IS NULL OR last_prompted_at <= NOW() - ($2::text || ' days')::interval)`,
    [REVIEW_PROMPT_FIRST_DELAY_DAYS, REVIEW_PROMPT_REPEAT_DAYS]
  ).catch(() => ({ rows: [] }));

  for (const row of eligible.rows) {
    const user = await client.users.fetch(row.user_id).catch(() => null);
    if (!user) continue;
    const embed = new EmbedBuilder()
      .setTitle('⭐ Enjoying GG Sports?')
      .setColor(0xFEE75C)
      .setDescription("You've been playing in a GG Sports league for a bit now — if it's been a good experience, a quick rating helps a lot.")
      .setFooter({ text: 'GG Sports' })
      .setTimestamp();
    const buttons = new ActionRowBuilder().addComponents(
      new ButtonBuilder().setLabel('Leave a Review').setEmoji('⭐').setStyle(ButtonStyle.Link).setURL(botSettingsCache.review_link),
      new ButtonBuilder().setCustomId('reviewprompt_confirm').setLabel('I Left My 5 Star Review').setStyle(ButtonStyle.Success),
    );
    const sent = await user.send({ embeds: [embed], components: [buttons] }).catch(() => null);
    // Only bump last_prompted_at on an actual successful send — if their
    // DMs are closed, leave it alone so this keeps retrying every tick
    // instead of silently going quiet on them for 30 days.
    if (sent) {
      await pool.query(`UPDATE user_review_prompts SET last_prompted_at = NOW(), updated_at = NOW() WHERE user_id = $1`, [row.user_id]).catch(() => null);
    }
  }
}

let reviewPromptSchedulerTimer = null;
function startReviewPromptSchedulerLoop(client) {
  if (reviewPromptSchedulerTimer) clearInterval(reviewPromptSchedulerTimer);
  // Daily tick — day-granularity thresholds (10/30 days), no need for
  // anything finer, and the discovery pass touches every guild/league/team
  // role on every tick, so keeping it infrequent matters more here than
  // for the hourly birthday-gift tick above.
  reviewPromptSchedulerTimer = setInterval(() => {
    runReviewPromptSchedulerTick(client).catch(error => console.error('Review prompt scheduler tick failed:', error));
  }, 24 * 60 * 60 * 1000);
  setTimeout(() => runReviewPromptSchedulerTick(client).catch(() => null), 60 * 1000);
}

// ---------------------------------------------------------------------------
// Holiday & championship exclusive auto-scheduling — periodically flips is_active on
// any shop_items row with an exclusive_window_start/end set, based on whether NOW()
// falls inside that window. Fixed-date holidays (Christmas, Halloween, etc.) can have
// their window set once per year and left alone; floating-date holidays (Easter,
// Mother's/Father's Day, Thanksgiving) and championship windows (dates unknown until
// each season) need an admin/bot owner to update the window before each occurrence —
// see Avatar Item Build Roadmap.
// ---------------------------------------------------------------------------
async function runExclusiveWindowSchedulerTick() {
  await pool.query(
    `UPDATE shop_items SET is_active = TRUE, updated_at = NOW()
     WHERE is_exclusive = TRUE AND is_active = FALSE
       AND exclusive_window_start IS NOT NULL AND exclusive_window_end IS NOT NULL
       AND NOW() BETWEEN exclusive_window_start AND exclusive_window_end`
  );
  await pool.query(
    `UPDATE shop_items SET is_active = FALSE, updated_at = NOW()
     WHERE is_exclusive = TRUE AND is_active = TRUE
       AND exclusive_window_start IS NOT NULL AND exclusive_window_end IS NOT NULL
       AND NOW() NOT BETWEEN exclusive_window_start AND exclusive_window_end`
  );
}

let exclusiveWindowSchedulerTimer = null;
function startExclusiveWindowSchedulerLoop() {
  if (exclusiveWindowSchedulerTimer) clearInterval(exclusiveWindowSchedulerTimer);
  // 15-minute tick — exclusive windows don't need per-minute precision like Madden
  // autosync does, and this keeps it cheap to run continuously.
  exclusiveWindowSchedulerTimer = setInterval(() => {
    runExclusiveWindowSchedulerTick().catch(error => console.error('Exclusive window scheduler tick failed:', error));
  }, 15 * 60 * 1000);
  setTimeout(() => runExclusiveWindowSchedulerTick().catch(() => null), 15 * 1000);
}

async function updateAvatarBodyCustomization(userId, { bodyKey, skinTone, hairStyle, hairColor }) {
  await getOrCreateAvatarProfile(userId);
  const sets = [];
  const values = [];
  let i = 1;
  if (bodyKey) { sets.push(`body_key = $${i++}`); values.push(bodyKey); }
  if (skinTone) { sets.push(`skin_tone = $${i++}`); values.push(skinTone); }
  if (hairStyle) { sets.push(`hair_style = $${i++}`); values.push(hairStyle); }
  if (hairColor) { sets.push(`hair_color = $${i++}`); values.push(hairColor); }
  if (!sets.length) return;
  sets.push('updated_at = NOW()');
  values.push(userId);
  await pool.query(`UPDATE avatar_profiles SET ${sets.join(', ')} WHERE user_id = $${i}`, values);
}

// Uses avatarColorForItem's keyword match if the item name matches something
// recognized, otherwise falls back to a deterministic hash color so unrecognized
// items still render visually distinct instead of collapsing onto one default.
function avatarResolvedColor(itemName, fallbackHex) {
  const matched = avatarColorForItem(itemName, null);
  if (matched) return [...avatarHexToRgb(matched, avatarHexToRgb(fallbackHex)), 255];
  return [...avatarDeterministicColor(itemName).slice(0, 3), 255];
}

// equipped: { top: {item_name}|null, bottom: ..., headwear: ..., accessory: ...,
// footwear: ..., pet: ..., effect: ..., background: ... } — caller resolves which set
// to pass (real equip state, or real state with one slot swapped for a shop preview).
function renderAvatarProfilePngPlaceholder(profile, equipped) {
  const width = 900;
  const height = 1200;
  const scale = AVATAR_BUILD_SCALE[profile.build] || 1.0;
  const skin = AVATAR_SKIN_TONES[profile.skin_tone] || AVATAR_SKIN_TONES.medium;
  const silhouette = AVATAR_SILHOUETTES.includes(profile.silhouette) ? profile.silhouette : 'a';

  const topName = equipped.top?.item_name || 'none';
  const bottomName = equipped.bottom?.item_name || 'none';
  const headwearName = equipped.headwear?.item_name || null;
  const accessoryName = equipped.accessory?.item_name || null;
  const footwearName = equipped.footwear?.item_name || 'Basic Sneakers';
  const petName = equipped.pet?.item_name || null;
  const effectName = equipped.effect?.item_name || null;
  const backgroundName = equipped.background?.item_name || 'Locker Room';

  const bgLower = String(backgroundName).toLowerCase();
  const bg = bgLower.includes('court') ? [120, 53, 15, 255]
    : bgLower.includes('tunnel') ? [17, 24, 39, 255]
    : bgLower.includes('locker') ? [24, 24, 27, 255]
    : avatarDeterministicColor(backgroundName).slice(0, 3).concat(255);

  const img = avatarCanvas(width, height, bg);
  const gold = [250, 204, 21, 255];
  const black = [15, 23, 42, 255];
  const topColor = avatarResolvedColor(topName, '#ffffff');
  const bottomColor = avatarResolvedColor(bottomName, '#2f3542');
  const shoeColor = avatarResolvedColor(footwearName, '#f8fafc');
  const accColor = accessoryName ? avatarResolvedColor(accessoryName, '#f5d742') : gold;
  const headColor = headwearName ? avatarResolvedColor(headwearName, '#374151') : null;

  // panel/background frame
  avatarRect(img, width, height, 65, 75, 770, 1050, [0, 0, 0, 55]);
  avatarRect(img, width, height, 70, 80, 10, 1040, gold);

  // effect/aura — any equipped effect glows, not just keyword-matched names.
  // Coarser step than the old renderer (20 vs 8) — each pass is a full ellipse
  // rasterize, and rendering happens on every button click, so keeping this cheap
  // matters more here than it did for a one-off /shop preview.
  if (effectName) {
    for (let r = 260; r > 0; r -= 20) {
      avatarEllipse(img, width, height, 450, 570, r, r, [...avatarDeterministicColor(effectName).slice(0, 3), Math.max(8, Math.floor(60 * (1 - r / 270)))]);
    }
  }

  // shadow
  avatarEllipse(img, width, height, 450, 1015, 220, 38, [0, 0, 0, 95]);

  // legs and body (thickness scaled by build)
  const limbW = Math.round(40 * scale);
  avatarLine(img, width, height, 385, 675, 380, 960, limbW, skin);
  avatarLine(img, width, height, 515, 675, 520, 960, limbW, skin);

  // shorts/bottom (width scaled by build)
  const legW = Math.round(105 * Math.min(scale, 1.2));
  avatarRect(img, width, height, 345, 655, legW, 210, bottomColor);
  avatarRect(img, width, height, 450, 655, legW, 210, bottomColor);
  avatarRect(img, width, height, 345, 655, 210, 70, bottomColor);

  // shoes
  avatarEllipse(img, width, height, 375, 995, 70, 35, shoeColor);
  avatarEllipse(img, width, height, 525, 995, 70, 35, shoeColor);
  avatarRect(img, width, height, 330, 1000, 95, 8, black);
  avatarRect(img, width, height, 475, 1000, 95, 8, black);

  // arms (thickness scaled by build)
  const armW = Math.round(28 * scale);
  avatarLine(img, width, height, 345, 465, 250, 675, armW, skin);
  avatarLine(img, width, height, 555, 465, 650, 675, armW, skin);
  avatarEllipse(img, width, height, 245, 685, 30, 30, skin);
  avatarEllipse(img, width, height, 655, 685, 30, 30, skin);

  // torso/top (width scaled by build — wider shoulders for built/heavy)
  const torsoSpread = Math.round(30 * (scale - 1));
  avatarTriangle(img, width, height, [[320 - torsoSpread, 455], [580 + torsoSpread, 455], [545 + torsoSpread / 2, 690]], topColor);
  avatarTriangle(img, width, height, [[320 - torsoSpread, 455], [545 + torsoSpread / 2, 690], [355 - torsoSpread / 2, 690]], topColor);
  avatarLine(img, width, height, 340, 470, 255, 650, 32, topColor);
  avatarLine(img, width, height, 560, 470, 645, 650, 32, topColor);

  // neck/head/hair — silhouette 'a' vs 'b' gives a different hair shape
  avatarRect(img, width, height, 410, 400, 80, 80, skin);
  avatarEllipse(img, width, height, 450, 330, 90, 95, skin);
  if (silhouette === 'b') {
    avatarEllipse(img, width, height, 450, 270, 105, 60, black);
    avatarRect(img, width, height, 345, 270, 210, 40, black);
  } else {
    avatarEllipse(img, width, height, 450, 285, 92, 45, black);
  }

  // face
  const hasShades = headwearName && (String(headwearName).toLowerCase().includes('shades') || String(headwearName).toLowerCase().includes('betting'));
  if (hasShades) {
    avatarRect(img, width, height, 385, 315, 55, 28, black);
    avatarRect(img, width, height, 460, 315, 55, 28, black);
    avatarRect(img, width, height, 435, 327, 30, 8, black);
  } else {
    avatarEllipse(img, width, height, 420, 330, 7, 7, black);
    avatarEllipse(img, width, height, 480, 330, 7, 7, black);
  }
  avatarLine(img, width, height, 420, 370, 480, 370, 3, [124, 45, 18, 255]);

  // headwear — any equipped hat draws a generic cap; recognized keywords add a bonus
  if (headwearName && !hasShades) {
    avatarEllipse(img, width, height, 450, 275, 100, 55, headColor);
    avatarRect(img, width, height, 350, 275, 200, 15, headColor);
    if (String(headwearName).toLowerCase().includes('crown')) {
      avatarTriangle(img, width, height, [[370, 250], [405, 170], [430, 250]], gold);
      avatarTriangle(img, width, height, [[425, 250], [450, 180], [480, 250]], gold);
      avatarTriangle(img, width, height, [[475, 250], [510, 170], [535, 250]], gold);
      avatarRect(img, width, height, 370, 245, 165, 30, gold);
    }
  }

  // accessory — any equipped accessory draws a generic neck accent; recognized
  // keywords add bonus shapes
  if (accessoryName) {
    avatarLine(img, width, height, 395, 455, 450, 500, 7, accColor);
    avatarLine(img, width, height, 505, 455, 450, 500, 7, accColor);
    const accLower = String(accessoryName).toLowerCase();
    if (accLower.includes('watch')) avatarRect(img, width, height, 625, 640, 50, 30, gold);
    if (accLower.includes('wristband')) avatarRect(img, width, height, 220, 640, 55, 30, gold);
  }

  // GG on shirt
  avatarRect(img, width, height, 405, 530, 90, 55, [0, 0, 0, 70]);

  // pet — any equipped pet draws a generic companion shape
  if (petName) {
    const petColor = [...avatarDeterministicColor(petName).slice(0, 3), 255];
    avatarEllipse(img, width, height, 675, 930, 75, 50, petColor);
    avatarEllipse(img, width, height, 640, 895, 35, 35, petColor);
    avatarEllipse(img, width, height, 630, 888, 5, 5, black);
    avatarEllipse(img, width, height, 650, 888, 5, 5, black);
  }

  return avatarEncodePng(width, height, img);
}

// ---------------------------------------------------------------------------
// Real-art renderer — composites the actual generated base-body PNGs via sharp.
// Falls back to the procedural placeholder above if the art files haven't been
// deployed yet, so an update to this code doesn't hard-crash a server that hasn't
// added the asset files to its repo yet.
//
// Known, deliberate scope limits for this pass:
// - Cosmetic items (tops/bottoms/shoes/hats/accessories/pets) are NOT yet visually
//   composited onto the real body — no real cosmetic art exists yet, and overlaying
//   the old procedural shapes onto photoreal art looked worse than just leaving them
//   off. They're still fully tracked/equippable and listed in the embed text field;
//   only the visual layer is pending real cosmetic art.
// - Skin tone is an approximate sharp .tint() over already-toned art, not true
//   programmatic tinting of neutral-toned art (the design doc's original plan) —
//   the generated reference sheet has one baked-in tone, not a neutral base.
// ---------------------------------------------------------------------------

const AVATAR_BODY_KEYS = ['male_slim', 'male_athletic', 'male_built', 'male_heavy', 'female_slim', 'female_athletic', 'female_built', 'female_heavy'];
const AVATAR_BODY_LABELS = {
  male_slim: 'Male • Slim', male_athletic: 'Male • Athletic', male_built: 'Male • Built', male_heavy: 'Male • Heavy',
  female_slim: 'Female • Slim', female_athletic: 'Female • Athletic', female_built: 'Female • Built', female_heavy: 'Female • Heavy',
};
// 'medium' matches the reference sheet's native tone, so it's a pass-through (no
// tint applied) rather than tinting toward itself.
const AVATAR_SKIN_TONE_TINTS = {
  light: { r: 235, g: 205, b: 180 },
  medium: null,
  tan: { r: 170, g: 124, b: 92 },
  deep: { r: 92, g: 62, b: 45 },
};

// Preset swatches for colorable items — tap-to-select, no typing required. "Custom
// Color" (handled separately via parseAvatarHexColor) covers everything else.
const AVATAR_COLOR_PALETTE = [
  { name: 'White', hex: '#F5F5F5' },
  { name: 'Black', hex: '#1A1A1A' },
  { name: 'Red', hex: '#C62828' },
  { name: 'Green', hex: '#2E7D32' },
  { name: 'Blue', hex: '#1565C0' },
  { name: 'Grey', hex: '#757575' },
  { name: 'Navy', hex: '#1A2A52' },
  { name: 'Pink', hex: '#E91E8C' },
  { name: 'Purple', hex: '#7B1FA2' },
  { name: 'Orange', hex: '#EF6C00' },
];

// The 6 free default hairstyles (3 per gender) plus Buzzcut, art_asset_key values
// matching assets/avatar/layers/hair/{key}/{bodyKey}.png exactly (see Avatar Item
// Build Roadmap), except Buzzcut which is a sentinel, not a real art key — the real
// body files already have a buzzed/bald look baked in, so "Buzzcut" just means
// "render no hair layer at all" rather than pointing at real art. It's available to
// both genders (unlike the other 6, which are gender-gated) since it's just "go back
// to what the body already looks like".
const BUZZCUT_HAIR_STYLE = 'buzzcut';
const HAIR_STYLES_BY_GENDER = {
  male: [BUZZCUT_HAIR_STYLE, 'caesar', 'faux_hawk', 'afro'],
  female: [BUZZCUT_HAIR_STYLE, 'high_ponytail', 'long_curly', 'messy_bun'],
};
const HAIR_STYLE_LABELS = {
  [BUZZCUT_HAIR_STYLE]: 'Buzzcut (Default)',
  caesar: 'Caesar', faux_hawk: 'Faux Hawk', afro: 'Afro',
  high_ponytail: 'High Ponytail', long_curly: 'Long Curly', messy_bun: 'Messy Bun',
};
// Buzzcut is the starting default for both genders now, rather than a named style —
// matches the actual out-of-the-box body art with zero extra layer drawn.
const DEFAULT_HAIR_STYLE_FOR_GENDER = { male: BUZZCUT_HAIR_STYLE, female: BUZZCUT_HAIR_STYLE };

// Natural tap-to-select tones for the free default hairstyles — a deliberately
// constrained palette (unlike AVATAR_COLOR_PALETTE's arbitrary-color shop items),
// since real hair only comes in real hair colors. More styles/colors arrive later
// as purchasable shop cosmetics (is_colorable, full AVATAR_COLOR_PALETTE) — this
// palette is for the free starter styles only.
const HAIR_COLOR_PALETTE = [
  { name: 'Black', hex: '#0B0A09' },
  { name: 'Dark Brown', hex: '#3B2314' },
  { name: 'Medium Brown', hex: '#5C3A21' },
  { name: 'Light Brown', hex: '#8D5B3F' },
  { name: 'Dirty Blonde', hex: '#A98358' },
  { name: 'Blonde', hex: '#D9B36C' },
  { name: 'Strawberry Blonde', hex: '#C98550' },
  { name: 'Red', hex: '#8C3B23' },
  { name: 'Auburn', hex: '#6B2E1E' },
  { name: 'Grey', hex: '#9B9B9B' },
  { name: 'White', hex: '#E8E4DD' },
];

function genderFromBodyKey(bodyKey) {
  return String(bodyKey || '').startsWith('female') ? 'female' : 'male';
}

// Resolves the profile's effective default hair style, falling back to a
// gender-appropriate default and self-correcting if the stored style doesn't match
// the current body's gender (e.g. after a body_key change) rather than rendering
// nothing.
function resolveDefaultHairStyle(profile) {
  const gender = genderFromBodyKey(profile.body_key);
  const allowed = HAIR_STYLES_BY_GENDER[gender];
  if (profile.hair_style && allowed.includes(profile.hair_style)) return profile.hair_style;
  return DEFAULT_HAIR_STYLE_FOR_GENDER[gender];
}

// Validates and parses any hex color string (with or without '#', 3 or 6 digits) into
// an {r,g,b} object for sharp's .tint(), or null if invalid. Backs the "Custom Color"
// option so the palette above isn't actually a hard limit.
function parseAvatarHexColor(input) {
  if (!input) return null;
  const clean = String(input).trim().replace(/^#/, '');
  let hex = clean;
  if (/^[0-9a-fA-F]{3}$/.test(clean)) {
    hex = clean.split('').map(c => c + c).join('');
  }
  if (!/^[0-9a-fA-F]{6}$/.test(hex)) return null;
  return {
    r: parseInt(hex.slice(0, 2), 16),
    g: parseInt(hex.slice(2, 4), 16),
    b: parseInt(hex.slice(4, 6), 16),
  };
}

function normalizeAvatarHexColor(input) {
  const rgb = parseAvatarHexColor(input);
  if (!rgb) return null;
  return '#' + [rgb.r, rgb.g, rgb.b].map(n => n.toString(16).padStart(2, '0')).join('').toUpperCase();
}

const AVATAR_BODY_ASSET_DIR = path.join(process.cwd(), 'assets', 'avatar', 'bodies');
const avatarBodyBufferCache = new Map();

const AVATAR_BODY_VARIANT_ASSET_DIR = path.join(process.cwd(), 'assets', 'avatar', 'bodies_variant');

async function loadAvatarBodyBuffer(bodyKey, variant = null) {
  const cacheKey = variant ? `${variant}:${bodyKey}` : bodyKey;
  if (avatarBodyBufferCache.has(cacheKey)) return avatarBodyBufferCache.get(cacheKey);
  const filePath = variant
    ? path.join(AVATAR_BODY_VARIANT_ASSET_DIR, variant, `${bodyKey}.png`)
    : path.join(AVATAR_BODY_ASSET_DIR, `${bodyKey}.png`);
  try {
    const buffer = await fs.promises.readFile(filePath);
    avatarBodyBufferCache.set(cacheKey, buffer);
    return buffer;
  } catch (error) {
    if (variant) {
      // Variant art not uploaded yet (or missing for this bodyKey) — fall back to the
      // normal body rather than breaking the render entirely. The foot-shape mismatch
      // this variant exists to fix will be visible, but that's a strict improvement
      // over not rendering the avatar at all.
      console.error(`[Avatar] Missing body variant "${variant}" for "${bodyKey}" at ${filePath} — falling back to standard body.`);
      return loadAvatarBodyBuffer(bodyKey, null);
    }
    console.error(`[Avatar] Missing body asset for "${bodyKey}" at ${filePath} — falling back to placeholder renderer.`);
    return null;
  }
}

// Cosmetic layer art — assets/avatar/layers/{slot}/{artKey}/{bodyKey}.png. Cropped to
// the exact same canvas/offset as the base body it corresponds to, so it can be
// composited at the same {left, top} the body itself uses. Missing file -> null,
// handled gracefully (item just doesn't render a visual layer yet) rather than
// throwing, since most cosmetics won't have real art for a while.
const AVATAR_LAYER_ASSET_DIR = path.join(process.cwd(), 'assets', 'avatar', 'layers');
const avatarLayerBufferCache = new Map();

async function loadAvatarLayerBuffer(slot, artKey, bodyKey) {
  if (!artKey) return null;
  const cacheKey = `${slot}/${artKey}/${bodyKey}`;
  if (avatarLayerBufferCache.has(cacheKey)) return avatarLayerBufferCache.get(cacheKey);
  const filePath = path.join(AVATAR_LAYER_ASSET_DIR, slot, artKey, `${bodyKey}.png`);
  try {
    const buffer = await fs.promises.readFile(filePath);
    avatarLayerBufferCache.set(cacheKey, buffer);
    return buffer;
  } catch (error) {
    avatarLayerBufferCache.set(cacheKey, null);
    return null;
  }
}

// Background/effect art — assets/avatar/layers/{slot}/{artKey}.png (a single file,
// NOT per-bodyKey like loadAvatarLayerBuffer above) since these cover the whole
// canvas and don't fit a specific body's silhouette — a nightclub backdrop or a
// confetti burst looks the same behind a Slim or Heavy build. Resized with
// fit:'cover' at render time to whatever canvas size is in play (700x1000 normal,
// 1000x1400 showcase), so one reasonably high-res source image covers both.
const AVATAR_FULLCANVAS_ASSET_DIR = path.join(process.cwd(), 'assets', 'avatar', 'layers');
const avatarFullCanvasBufferCache = new Map();

async function loadAvatarFullCanvasBuffer(slot, artKey) {
  if (!artKey) return null;
  const cacheKey = `${slot}/${artKey}`;
  if (avatarFullCanvasBufferCache.has(cacheKey)) return avatarFullCanvasBufferCache.get(cacheKey);
  const filePath = path.join(AVATAR_FULLCANVAS_ASSET_DIR, slot, `${artKey}.png`);
  try {
    const buffer = await fs.promises.readFile(filePath);
    avatarFullCanvasBufferCache.set(cacheKey, buffer);
    return buffer;
  } catch (error) {
    avatarFullCanvasBufferCache.set(cacheKey, null);
    return null;
  }
}

// Used by createcosmetic (both the slash command and the Bot Owner Panel button) to
// warn if an item is created with no matching art on disk yet. background/effect use
// the single-file full-canvas loader above; every other slot is body-keyed, checked
// against one representative body (male_athletic) since art either exists for all 8
// bodies or none.
const AVATAR_FULLCANVAS_SLOTS = ['background', 'effect', 'pet'];
async function avatarArtExistsForSlot(slot, artKey) {
  if (!artKey) return false;
  if (AVATAR_FULLCANVAS_SLOTS.includes(slot)) {
    return loadAvatarFullCanvasBuffer(slot, artKey).then(buf => !!buf).catch(() => false);
  }
  return loadAvatarLayerBuffer(slot, artKey, 'male_athletic').then(buf => !!buf).catch(() => false);
}

// Soft radial glow, rasterized from SVG rather than a per-pixel JS loop — much
// cheaper than the placeholder renderer's concentric-ellipse approach, and
// composited with a 'screen' blend so it reads as light coming off the character
// rather than a translucent disc sitting on top of it.
async function buildAvatarAuraGlowBuffer(sharp, width, height, effectName) {
  const [r, g, b] = avatarDeterministicColor(effectName);
  const cx = Math.round(width / 2);
  const cy = Math.round(height * 0.55);
  const radius = Math.round(Math.min(width, height) * 0.42);
  const svg = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <radialGradient id="glow" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stop-color="rgb(${r},${g},${b})" stop-opacity="0.55"/>
        <stop offset="100%" stop-color="rgb(${r},${g},${b})" stop-opacity="0"/>
      </radialGradient>
    </defs>
    <circle cx="${cx}" cy="${cy}" r="${radius}" fill="url(#glow)"/>
  </svg>`;
  return sharp(Buffer.from(svg)).png().toBuffer();
}

// sharp's built-in .tint() preserves the base image's original lightness and only
// shifts hue — confirmed broken for our purposes (black rendered as light gray, navy
// and blue were nearly identical). A pure multiply blend was tried next and fixed
// that, but multiply can only ever DARKEN — it mathematically cannot produce
// anything brighter than the base pixel's own value, so "white" stayed stuck looking
// like the gray base fabric. This uses a real Overlay blend instead (the same formula
// Photoshop's Overlay/Color blend modes use): darkens below mid-gray, brightens above
// it, so it can reach genuine black AND genuine white while still preserving the
// garment's own fold/shading detail as light/dark variation. Alpha is untouched.
async function applyAvatarColorize(sharpLib, buffer, targetRgb) {
  const { data, info } = await sharpLib(buffer).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const out = Buffer.alloc(data.length);
  const target = [targetRgb.r, targetRgb.g, targetRgb.b];
  for (let i = 0; i < data.length; i += 4) {
    for (let c = 0; c < 3; c++) {
      const base = data[i + c] / 255;
      const t = target[c] / 255;
      const blended = base < 0.5 ? (2 * base * t) : (1 - 2 * (1 - base) * (1 - t));
      out[i + c] = Math.round(Math.min(255, Math.max(0, blended * 255)));
    }
    out[i + 3] = data[i + 3];
  }
  return sharpLib(out, { raw: { width: info.width, height: info.height, channels: 4 } }).png().toBuffer();
}

// A flat blend-toward-target (previous approach) provably destroyed detail: measured
// the shading variation (std dev) of skin pixels before/after and an 80%-strength
// blend cut it by exactly 80%, which is why facial shadow lines and definition
// visibly flattened. This scales each pixel by (target / this body's own native
// average skin tone) instead — a pure multiplicative ratio, so relative shading stays
// exactly proportional (verified: coefficient of variation is unchanged, not just
// "less flattened"). Shadows stay proportionally darker, highlights stay
// proportionally brighter, only the overall balance shifts.
async function applyAvatarSkinToneColorize(sharpLib, buffer, targetRgb) {
  const { data, info } = await sharpLib(buffer).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const out = Buffer.from(data);
  const target = [targetRgb.r, targetRgb.g, targetRgb.b];

  // First pass: find this body's own native average skin tone as the reference point.
  // Threshold raised to r>110 (was 80) so darker shadow/outline strokes are excluded
  // from detection entirely — they should never be recolored to begin with.
  let sumR = 0, sumG = 0, sumB = 0, count = 0;
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i], g = data[i + 1], b = data[i + 2], a = data[i + 3];
    if (a < 10) continue;
    if (r > g && g >= b && r > 110 && (r - b) > 15) {
      sumR += r; sumG += g; sumB += b; count++;
    }
  }
  if (count === 0) return sharpLib(data, { raw: { width: info.width, height: info.height, channels: 4 } }).png().toBuffer();
  const nativeAvg = [sumR / count, sumG / count, sumB / count];
  const ratio = [target[0] / nativeAvg[0], target[1] / nativeAvg[1], target[2] / nativeAvg[2]];

  // Second pass: apply the ratio only to skin-like pixels.
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i], g = data[i + 1], b = data[i + 2], a = data[i + 3];
    if (a < 10) continue;
    if (!(r > g && g >= b && r > 110 && (r - b) > 15)) continue;
    out[i] = Math.round(Math.min(255, Math.max(0, r * ratio[0])));
    out[i + 1] = Math.round(Math.min(255, Math.max(0, g * ratio[1])));
    out[i + 2] = Math.round(Math.min(255, Math.max(0, b * ratio[2])));
  }
  return sharpLib(out, { raw: { width: info.width, height: info.height, channels: 4 } }).png().toBuffer();
}

function avatarBackgroundColorFor(backgroundName) {
  const bgLower = String(backgroundName || 'Locker Room').toLowerCase();
  if (bgLower.includes('court')) return { r: 120, g: 53, b: 15, alpha: 1 };
  if (bgLower.includes('tunnel')) return { r: 17, g: 24, b: 39, alpha: 1 };
  if (bgLower.includes('locker')) return { r: 24, g: 24, b: 27, alpha: 1 };
  // Casino/mall/ski lodge — placeholder tones shown until Gemini-generated art lands
  // at assets/avatar/layers/background/{art_key}.png (see item creation notes).
  if (bgLower.includes('casino')) return { r: 76, g: 12, b: 20, alpha: 1 }; // deep red/felt
  if (bgLower.includes('mall')) return { r: 226, g: 232, b: 240, alpha: 1 }; // bright mall-white
  if (bgLower.includes('ski') || bgLower.includes('lodge')) return { r: 92, g: 64, b: 51, alpha: 1 }; // warm cabin brown
  const [r, g, b] = avatarDeterministicColor(backgroundName);
  return { r, g, b, alpha: 1 };
}

// options.showcase renders a larger, more dramatic hero-shot canvas (build order #4,
// the "Flex" showcase pipeline) using the same body art and equip state — no
// pose-specific art exists yet, so this is a stylized presentation of the standard
// pose rather than a true alternate pose. True multi-pose showcase needs its own art
// pass later; this delivers the on-demand "hero shot" value now without waiting on it.
// sharp is loaded lazily and defensively — a missing/broken native dependency for a
// cosmetic art feature must never be able to crash the whole bot (this exact failure
// mode happened with a static top-level import). Loaded once, cached either way; if it
// fails, every render call below transparently falls back to the placeholder renderer
// instead of the bot refusing to boot.
let sharpModule = null;
let sharpLoadAttempted = false;
async function getSharp() {
  if (sharpLoadAttempted) return sharpModule;
  sharpLoadAttempted = true;
  try {
    const mod = await import('sharp');
    sharpModule = mod.default;
    console.log('[Avatar] sharp loaded — real-art avatar rendering enabled.');
  } catch (error) {
    console.error('[Avatar] sharp is not installed/loadable — avatar rendering will use the placeholder renderer until this is fixed. Run `npm install` with sharp in package.json and redeploy. Error:', error?.message || error);
    sharpModule = null;
  }
  return sharpModule;
}

async function renderAvatarProfilePng(profile, equipped, options = {}) {
  try {
    return await renderAvatarProfilePngRealArt(profile, equipped, options);
  } catch (error) {
    console.error('[Avatar] Real-art render failed, falling back to placeholder renderer:', error);
    return renderAvatarProfilePngPlaceholder(profile, equipped);
  }
}

async function renderAvatarProfilePngRealArt(profile, equipped, options = {}) {
  const sharp = await getSharp();
  if (!sharp) return renderAvatarProfilePngPlaceholder(profile, equipped);

  const bodyKey = AVATAR_BODY_KEYS.includes(profile.body_key) ? profile.body_key : 'male_athletic';
  const bodyVariant = equipped.footwear?.body_variant || null;
  const bodyBuffer = await loadAvatarBodyBuffer(bodyKey, bodyVariant);
  if (!bodyBuffer) return renderAvatarProfilePngPlaceholder(profile, equipped);

  const width = options.showcase ? 1000 : 700;
  const height = options.showcase ? 1400 : 1000;
  const bgColor = avatarBackgroundColorFor(equipped.background?.item_name);

  const targetHeight = Math.floor(height * (options.showcase ? 0.92 : 0.88));
  const bodyOrigMeta = await sharp(bodyBuffer).metadata();
  let bodyImage = sharp(bodyBuffer).resize({ height: targetHeight });
  let bodyResizedBuffer = await bodyImage.png().toBuffer();

  const tint = AVATAR_SKIN_TONE_TINTS[profile.skin_tone];
  if (tint) bodyResizedBuffer = await applyAvatarSkinToneColorize(sharp, bodyResizedBuffer, tint);

  const bodyMeta = await sharp(bodyResizedBuffer).metadata();
  const left = Math.floor((width - bodyMeta.width) / 2);
  const top = height - bodyMeta.height - Math.floor(height * (options.showcase ? 0.02 : 0.03));

  // Elevated footwear (heels, skates) — heel_lift_px is measured at the body's native
  // (pre-resize) resolution, so scale it by the same ratio the body itself was resized
  // by before applying it here. Shifts body + every wearable layer except footwear/pet
  // up so they sit correctly on top of the raised sole instead of sinking into it; the
  // footwear layer and pet stay planted at the true ground line (pet deliberately does
  // NOT lift with the wearer — see Avatar Item Build Roadmap).
  const heelLiftNative = equipped.footwear?.heel_lift_px || 0;
  const heelLiftPx = heelLiftNative > 0
    ? Math.round(heelLiftNative * (targetHeight / bodyOrigMeta.height))
    : 0;
  const liftedTop = top - heelLiftPx;

  const composites = [];

  // Background art (assets/avatar/layers/background/{artKey}.png) replaces the flat
  // color fill when it exists — falls back to the keyword-matched solid color
  // (avatarBackgroundColorFor) for any background item that doesn't have real art
  // yet, so nothing breaks for existing/placeholder background items.
  const backgroundArtKey = equipped.background?.art_asset_key || null;
  const backgroundBuffer = await loadAvatarFullCanvasBuffer('background', backgroundArtKey);
  if (backgroundBuffer) {
    const backgroundResized = await sharp(backgroundBuffer).resize({ width, height, fit: 'cover' }).png().toBuffer();
    composites.push({ input: backgroundResized, left: 0, top: 0 });
  }

  if (options.showcase) {
    // Dramatic spotlight/vignette backdrop for the hero shot — cheap SVG rasterize,
    // no new art needed.
    const spotlightSvg = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <radialGradient id="spot" cx="50%" cy="38%" r="65%">
          <stop offset="0%" stop-color="rgb(255,255,255)" stop-opacity="0.18"/>
          <stop offset="100%" stop-color="rgb(255,255,255)" stop-opacity="0"/>
        </radialGradient>
        <radialGradient id="vig" cx="50%" cy="50%" r="75%">
          <stop offset="60%" stop-color="rgb(0,0,0)" stop-opacity="0"/>
          <stop offset="100%" stop-color="rgb(0,0,0)" stop-opacity="0.45"/>
        </radialGradient>
      </defs>
      <rect width="${width}" height="${height}" fill="url(#spot)"/>
      <rect width="${width}" height="${height}" fill="url(#vig)"/>
    </svg>`;
    composites.push({ input: await sharp(Buffer.from(spotlightSvg)).png().toBuffer(), left: 0, top: 0 });
  }

  composites.push({ input: bodyResizedBuffer, left, top: liftedTop });

  // Wearable layers, in z-order (footwear -> bottom -> top -> hair -> headwear ->
  // accessory), each resized identically to the body so they align at the same
  // {left, top} — they were extracted from a source image cropped the same way as
  // the base bodies. Items without real art (art_asset_key null) simply don't
  // contribute a layer; they're still fully equipped/owned, just not drawn yet.
  // Hair is skipped outright whenever headwear is equipped (rather than relying on
  // headwear art visually covering it), since some headwear art may not fully occlude
  // hair drawn beneath it — see Avatar Item Build Roadmap. Accessories are multi-equip
  // (see equipped.accessories) so they're composited as a list, not a single slot.
  // 'footwear' is excluded from the heel-lift shift below — it has to stay planted at
  // the true ground line, since it IS the thing creating the lift. Pet is handled
  // separately after this loop — see PET_POSITIONS below.
  // 7J-SHOESUNDERPANTS: this local order previously started with 'footwear'
  // (drawn first, i.e. UNDERNEATH bottom/top), directly contradicting the
  // canonical AVATAR_LAYER_RENDER_ORDER constant above (which correctly
  // puts footwear after bottom/top) — pant legs were compositing straight
  // over the shoes on every avatar. Reordered to match that canonical
  // order: footwear now draws after both bottom and top.
  // 7J-HAIROVERTOP: hair moved after top (not before) — per Hxxdie, longer
  // hairstyles are designed to flow down over a top/shirt, so hair needs to
  // draw on top of it, not get covered by it. Still drawn before footwear/
  // headwear as before.
  const wearableLayerOrder = ['bottom', 'top', 'hair', 'footwear', 'headwear'];
  for (const slot of wearableLayerOrder) {
    if (slot === 'hair' && equipped.headwear?.art_asset_key) continue;

    let artAssetKey = equipped[slot]?.art_asset_key || null;
    let colorHex = equipped[slot]?.color_hex || null;

    // Hair falls back to the free default hairstyle (avatar_profiles.hair_style/
    // hair_color) whenever no paid shop hair item is equipped — a paid item, if
    // equipped, always wins. This is the only slot with a non-inventory fallback;
    // every other slot simply renders nothing when unequipped, same as before.
    // Buzzcut is explicitly skipped here (rather than left to fail loadAvatarLayerBuffer's
    // file-not-found catch) since it's a real, common selection, not an edge case —
    // no assets/avatar/layers/hair/buzzcut/ folder exists or ever will, since Buzzcut
    // means "the body's own baked-in look, draw nothing extra."
    if (slot === 'hair' && !artAssetKey) {
      const defaultStyle = resolveDefaultHairStyle(profile);
      if (defaultStyle !== BUZZCUT_HAIR_STYLE) {
        artAssetKey = defaultStyle;
        colorHex = profile.hair_color;
      }
    }

    if (!artAssetKey) continue;
    const layerBuffer = await loadAvatarLayerBuffer(slot, artAssetKey, bodyKey);
    if (!layerBuffer) continue;
    let layerResizedBuffer = await sharp(layerBuffer).resize({ height: targetHeight }).png().toBuffer();
    const colorRgb = parseAvatarHexColor(colorHex);
    if (colorRgb) layerResizedBuffer = await applyAvatarColorize(sharp, layerResizedBuffer, colorRgb);
    let slotTop = slot === 'footwear' ? top : liftedTop;
    // High Ponytail sits ~3px too high against the body art — small one-off nudge,
    // not a general hairstyle offset system (every other hairstyle is correctly
    // aligned as-is).
    if (slot === 'hair' && artAssetKey === 'high_ponytail') slotTop += 3;
    composites.push({ input: layerResizedBuffer, left, top: slotTop });
  }
  for (const accessory of (equipped.accessories || [])) {
    if (!accessory.art_asset_key) continue;
    const layerBuffer = await loadAvatarLayerBuffer('accessory', accessory.art_asset_key, bodyKey);
    if (!layerBuffer) continue;
    let layerResizedBuffer = await sharp(layerBuffer).resize({ height: targetHeight }).png().toBuffer();
    const colorRgb = parseAvatarHexColor(accessory.color_hex);
    if (colorRgb) layerResizedBuffer = await applyAvatarColorize(sharp, layerResizedBuffer, colorRgb);
    composites.push({ input: layerResizedBuffer, left, top: liftedTop });
  }

  // Pet — positioned by formula rather than the shared same-canvas-as-body trick
  // every other slot uses (see the pet_position/pet_scale schema comments for why:
  // floating-above-head needs a taller effective canvas, which would change the
  // resize scale and break alignment with every other layer if done the "normal"
  // way). Composited last/frontmost for every position — 'left'/'right' never
  // overlap the body so front-vs-behind doesn't matter for them, and every other
  // position needs to be in front regardless, so one unified pass covers all of them.
  const petArtKey = equipped.pet?.art_asset_key || null;
  if (petArtKey) {
    const petBuffer = await loadAvatarFullCanvasBuffer('pet', petArtKey); // pets aren't body-specific art — same single-file convention as background/effect
    if (petBuffer) {
      const petPosition = equipped.pet?.pet_position || 'left';
      const petScale = equipped.pet?.pet_scale || 0.3; // generic fallback until tuned per item
      const petTargetHeight = Math.max(1, Math.round(targetHeight * petScale));
      let petResizedBuffer = await sharp(petBuffer).resize({ height: petTargetHeight }).png().toBuffer();
      const petColorRgb = parseAvatarHexColor(equipped.pet?.color_hex);
      if (petColorRgb) petResizedBuffer = await applyAvatarColorize(sharp, petResizedBuffer, petColorRgb);
      const petMeta = await sharp(petResizedBuffer).metadata();
      const pw = petMeta.width, ph = petMeta.height;
      const gapX = Math.round(bodyMeta.width * 0.02);
      const gapY = Math.round(bodyMeta.height * 0.02);
      const edgePad = 5; // never let a pet render fully flush against the canvas edge

      // Ground positions anchor on the body's true (unlifted) top so the pet stays
      // planted on the floor even when the wearer is elevated by heels/skates — same
      // rationale as footwear. Body-anchored positions (shoulder, floating) use
      // liftedTop instead, since they move with the wearer's actual body position.
      let petLeft, petTop;
      switch (petPosition) {
        case 'right':
          // Clamped so a wide pet (relative to the ~180px canvas margin outside the
          // body) never renders partially off the right edge — it'll sit closer to
          // the body instead of clipping.
          petLeft = Math.min(left + bodyMeta.width + gapX, width - pw - edgePad);
          petTop = top + bodyMeta.height - ph;
          break;
        case 'front':
          petLeft = left + Math.round(bodyMeta.width / 2 - pw / 2);
          petTop = top + bodyMeta.height - ph;
          break;
        case 'shoulder': {
          // Right shoulder. Anchored near the TOP of the pet's own bounding box,
          // not its vertical center — a perching pose (e.g. a bird with a long
          // tail hanging below its feet) has most of its visual mass below the
          // actual perch point, so centering the whole bbox on the target height
          // placed the perch itself too high (looked like it was on the ear, not
          // the shoulder). Tunable constants — nothing architectural depends on
          // these exact fractions.
          petLeft = left + Math.round(bodyMeta.width * 0.85 - pw / 2);
          petTop = liftedTop + Math.round(bodyMeta.height * 0.16 - ph * 0.18);
          break;
        }
        case 'float_left':
        case 'float_right':
        case 'float_center': {
          // Clamped to the actual clear space above the head (liftedTop is exactly
          // that distance from the canvas top) rather than a fixed fraction of the
          // pet's height — a fixed fraction clipped badly for a tall pet like the
          // dragon, since there's usually only ~90px of headroom regardless of how
          // big the pet's own art is. A pet too tall to fully clear the head within
          // that space will overlap down into the hair instead of clipping off
          // the top of the canvas entirely. The gap has to be included INSIDE the
          // clamped budget, not added after it — adding it separately pushed the
          // result back off-canvas even when the clamp itself looked correct.
          const maxTotalOffset = Math.max(edgePad, liftedTop - edgePad);
          const desiredTotalOffset = (petPosition === 'float_center' ? ph * 0.55 : ph * 0.45) + gapY;
          const totalOffset = Math.min(desiredTotalOffset, maxTotalOffset);
          petTop = Math.round(liftedTop - totalOffset);
          if (petPosition === 'float_left') petLeft = left + Math.round(bodyMeta.width * 0.05 - pw * 0.3);
          else if (petPosition === 'float_right') petLeft = left + Math.round(bodyMeta.width * 0.95 - pw * 0.7);
          else petLeft = left + Math.round(bodyMeta.width / 2 - pw / 2);
          break;
        }
        case 'left':
        default:
          // Same clamping as 'right', mirrored — never off the left edge.
          petLeft = Math.max(edgePad, left - pw - gapX);
          petTop = top + bodyMeta.height - ph;
          break;
      }
      composites.push({ input: petResizedBuffer, left: petLeft, top: petTop });
    }
  }

  const effectName = equipped.effect?.item_name;
  const effectArtKey = equipped.effect?.art_asset_key || null;
  if (effectArtKey) {
    // Real effect art (assets/avatar/layers/effect/{artKey}.png) — a transparent
    // full-canvas overlay (confetti, sparks, etc.), composited normally (not
    // 'screen') since it's expected to already look right on its own, unlike the
    // procedural glow below which relies on 'screen' blending to read as light.
    const effectBuffer = await loadAvatarFullCanvasBuffer('effect', effectArtKey);
    if (effectBuffer) {
      const effectResized = await sharp(effectBuffer).resize({ width, height, fit: 'cover' }).png().toBuffer();
      composites.push({ input: effectResized, left: 0, top: 0 });
    } else if (effectName) {
      composites.push({ input: await buildAvatarAuraGlowBuffer(sharp, width, height, effectName), left: 0, top: 0, blend: 'screen' });
    }
  } else if (effectName) {
    composites.push({ input: await buildAvatarAuraGlowBuffer(sharp, width, height, effectName), left: 0, top: 0, blend: 'screen' });
  }

  const canvas = sharp({ create: { width, height, channels: 4, background: bgColor } });
  return canvas.composite(composites).png().toBuffer();
}

async function buildAvatarProfileAttachment(profile, equipped, options = {}) {
  const png = await renderAvatarProfilePng(profile, equipped, options);
  return new AttachmentBuilder(png, { name: 'avatar.png' });
}

// ---------------------------------------------------------------------------
// Locker Room — equip/swap owned items. No shopping here by design (separate panel,
// per the "locker room vs shop" decision).
// ---------------------------------------------------------------------------

function buildAvatarLockerEmbed(user, profile, equipped) {
  const NL = String.fromCharCode(10);
  const lines = AVATAR_SLOTS.filter(slot => slot !== 'accessory').map(slot => {
    // Hair is special-cased: equipped.hair is only populated for a PAID shop item
    // (equipped_hair_id). With no paid item equipped, the free default hairstyle is
    // still rendering (see resolveDefaultHairStyle) — show that instead of a
    // misleading "none".
    if (slot === 'hair' && !equipped.hair) {
      const styleKey = resolveDefaultHairStyle(profile);
      if (styleKey === BUZZCUT_HAIR_STYLE) return `${AVATAR_SLOT_LABELS.hair}: ${HAIR_STYLE_LABELS[styleKey]}`;
      const colorName = HAIR_COLOR_PALETTE.find(c => c.hex.toUpperCase() === String(profile.hair_color || '').toUpperCase())?.name || 'Custom';
      return `${AVATAR_SLOT_LABELS.hair}: ${HAIR_STYLE_LABELS[styleKey]} (${colorName})`;
    }
    return `${AVATAR_SLOT_LABELS[slot]}: ${equipped[slot]?.item_name || 'none'}`;
  });
  const accessoryList = (equipped.accessories || []).length
    ? equipped.accessories.map(a => a.item_name).join(', ')
    : 'none';
  lines.push(`${AVATAR_SLOT_LABELS.accessory}: ${accessoryList}`);
  return new EmbedBuilder()
    .setTitle(`🔒 ${user.username} • Locker Room`)
    .setColor(0xFEE75C)
    .setImage('attachment://avatar.png')
    .setDescription(lines.join(NL))
    .setFooter({ text: `GG Sports • ${AVATAR_BODY_LABELS[profile.body_key] || profile.body_key} • Skin: ${profile.skin_tone}` })
    .setTimestamp();
}

function buildAvatarLockerComponents() {
  const slotMenu = new StringSelectMenuBuilder()
    .setCustomId('avatarlocker_slot_select')
    .setPlaceholder('Manage a slot')
    .addOptions(AVATAR_SLOTS.map(slot => ({ label: AVATAR_SLOT_LABELS[slot], value: slot })));
  return [
    new ActionRowBuilder().addComponents(slotMenu),
    new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('avatarlocker_customize').setLabel('Customize Body').setEmoji('🧍').setStyle(ButtonStyle.Secondary),
      new ButtonBuilder().setCustomId('avatarlocker_recolor').setLabel('Recolor').setEmoji('🎨').setStyle(ButtonStyle.Secondary),
      new ButtonBuilder().setCustomId('avatarlocker_flex').setLabel('Flex').setEmoji('📸').setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('avatarlocker_myinventory').setLabel('My Inventory').setEmoji('🎒').setStyle(ButtonStyle.Secondary)
    ),
  ];
}

// Slot-select for recoloring — only lists slots where the CURRENTLY EQUIPPED item is
// colorable, since recolor changes that specific owned copy's color_hex.
function buildAvatarRecolorSlotComponents(equipped) {
  const colorableSlots = AVATAR_SLOTS.filter(slot => equipped[slot]?.is_colorable);
  const backRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('avatarlocker_back').setLabel('⬅ Back to Locker').setStyle(ButtonStyle.Secondary)
  );
  if (!colorableSlots.length) return [backRow];
  const menu = new StringSelectMenuBuilder()
    .setCustomId('avatarlocker_recolor_slot_select')
    .setPlaceholder('Which item do you want to recolor?')
    .addOptions(colorableSlots.map(slot => ({ label: `${AVATAR_SLOT_LABELS[slot]} — ${equipped[slot].item_name}`, value: slot })));
  return [new ActionRowBuilder().addComponents(menu), backRow];
}

function buildAvatarRecolorColorComponents(slot, currentColorHex) {
  const menu = new StringSelectMenuBuilder()
    .setCustomId(`avatarlocker_recolor_color_select:${slot}`)
    .setPlaceholder('Choose a color')
    .addOptions([
      ...AVATAR_COLOR_PALETTE.map(c => ({ label: c.name, value: c.hex.replace('#', ''), default: c.hex === currentColorHex })),
      { label: '🎨 Custom Color…', value: 'custom' },
    ]);
  return [
    new ActionRowBuilder().addComponents(menu),
    new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('avatarlocker_recolor').setLabel('⬅ Back').setStyle(ButtonStyle.Secondary)),
  ];
}

async function getOwnedItemsForAvatarSlot(userId, slot) {
  const result = await pool.query(
    `SELECT ui.id, ui.item_name, si.avatar_slot AS shop_avatar_slot, si.item_category
     FROM user_inventory ui
     LEFT JOIN shop_items si ON si.id = ui.item_id
     WHERE ui.user_id = $1
     ORDER BY ui.purchased_at DESC`,
    [userId]
  );
  return result.rows.filter(row => (row.shop_avatar_slot || inferAvatarSlotFromItem(row)) === slot);
}

// Owned accessories filtered to one accessory_type (neck/wrist/face/other) — used by the
// Locker Room's multi-accessory equip flow, since each type is equipped independently.
async function getOwnedAccessoryItemsByType(userId, accessoryType) {
  const result = await pool.query(
    `SELECT ui.id, ui.item_name, si.avatar_slot AS shop_avatar_slot, si.accessory_type
     FROM user_inventory ui
     LEFT JOIN shop_items si ON si.id = ui.item_id
     WHERE ui.user_id = $1
     ORDER BY ui.purchased_at DESC`,
    [userId]
  );
  return result.rows.filter(row => {
    const slot = row.shop_avatar_slot || inferAvatarSlotFromItem(row);
    if (slot !== 'accessory') return false;
    const type = ACCESSORY_TYPES.includes(row.accessory_type) ? row.accessory_type : 'other';
    return type === accessoryType;
  });
}

async function buildAvatarLockerSlotPayload(user, profile, equipped, slot) {
  if (slot === 'accessory') return buildAvatarLockerAccessoryTypePayload(user, profile, equipped);

  const ownedItems = await getOwnedItemsForAvatarSlot(user.id, slot);
  const options = [
    { label: 'Unequip', value: '__unequip__', description: `Remove ${AVATAR_SLOT_LABELS[slot]}`, emoji: '🚫' },
    ...ownedItems.slice(0, 24).map(item => ({ label: item.item_name.slice(0, 100), value: item.id })),
  ];
  const menu = new StringSelectMenuBuilder()
    .setCustomId(`avatarlocker_item_select:${slot}`)
    .setPlaceholder(ownedItems.length ? `Choose a ${AVATAR_SLOT_LABELS[slot]} item` : `No owned ${AVATAR_SLOT_LABELS[slot]} items yet`)
    .addOptions(options);
  return {
    content: null,
    embeds: [buildAvatarLockerEmbed(user, profile, equipped)],
    files: [await buildAvatarProfileAttachment(profile, equipped)],
    components: [
      new ActionRowBuilder().addComponents(menu),
      new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('avatarlocker_back').setLabel('⬅ Back to Locker').setStyle(ButtonStyle.Secondary)),
    ],
  };
}

// Accessories are multi-equip (one item per type, up to ACCESSORY_EQUIP_CAP total), so
// unlike every other slot this needs a type picker first, rather than going straight to
// an item list — see equipAvatarAccessory/unequipAvatarAccessory.
async function buildAvatarLockerAccessoryTypePayload(user, profile, equipped) {
  const equippedByType = {};
  for (const a of (equipped.accessories || [])) equippedByType[a.accessory_type] = a.item_name;

  const menu = new StringSelectMenuBuilder()
    .setCustomId('avatarlocker_accessory_type_select')
    .setPlaceholder(`Manage an accessory type (${(equipped.accessories || []).length}/${ACCESSORY_EQUIP_CAP} equipped)`)
    .addOptions(ACCESSORY_TYPES.map(type => ({
      label: type.charAt(0).toUpperCase() + type.slice(1),
      value: type,
      description: equippedByType[type] ? `Equipped: ${equippedByType[type]}`.slice(0, 100) : 'Nothing equipped',
    })));
  return {
    content: null,
    embeds: [buildAvatarLockerEmbed(user, profile, equipped)],
    files: [await buildAvatarProfileAttachment(profile, equipped)],
    components: [
      new ActionRowBuilder().addComponents(menu),
      new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('avatarlocker_back').setLabel('⬅ Back to Locker').setStyle(ButtonStyle.Secondary)),
    ],
  };
}

async function buildAvatarLockerAccessoryItemPayload(user, profile, equipped, accessoryType) {
  const ownedItems = await getOwnedAccessoryItemsByType(user.id, accessoryType);
  const typeLabel = accessoryType.charAt(0).toUpperCase() + accessoryType.slice(1);
  const options = [
    { label: 'Unequip', value: '__unequip__', description: `Remove your equipped ${typeLabel}`, emoji: '🚫' },
    ...ownedItems.slice(0, 24).map(item => ({ label: item.item_name.slice(0, 100), value: item.id })),
  ];
  const menu = new StringSelectMenuBuilder()
    .setCustomId(`avatarlocker_accessory_item_select:${accessoryType}`)
    .setPlaceholder(ownedItems.length ? `Choose a ${typeLabel} item` : `No owned ${typeLabel} items yet`)
    .addOptions(options);
  return {
    content: null,
    embeds: [buildAvatarLockerEmbed(user, profile, equipped)],
    files: [await buildAvatarProfileAttachment(profile, equipped)],
    components: [
      new ActionRowBuilder().addComponents(menu),
      new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('avatarlocker_accessory_back').setLabel('⬅ Back to Accessory Types').setStyle(ButtonStyle.Secondary)),
    ],
  };
}

// profile is required (not optional) so the hairstyle menu can be gender-gated to
// the current body_key and both new menus can show the user's actual current
// selection as the default-highlighted option, same pattern as the body/skin menus.
function buildAvatarCustomizeComponents(profile) {
  const bodyMenu = new StringSelectMenuBuilder().setCustomId('avatarlocker_customize_body').setPlaceholder('Choose your body')
    .addOptions(AVATAR_BODY_KEYS.map(key => ({ label: AVATAR_BODY_LABELS[key], value: key, default: key === profile.body_key })));
  const skinMenu = new StringSelectMenuBuilder().setCustomId('avatarlocker_customize_skin').setPlaceholder('Choose skin tone')
    .addOptions(Object.keys(AVATAR_SKIN_TONE_TINTS).map(t => ({ label: t.charAt(0).toUpperCase() + t.slice(1), value: t, default: t === profile.skin_tone })));

  // Hairstyle choices only show the 4 styles matching the current body's gender
  // (Buzzcut + the 3 named styles) — switching Male<->Female bodies switches this
  // list too (see genderFromBodyKey). If the profile's stored hair_style isn't valid for the current gender (e.g. body
  // was just switched), resolveDefaultHairStyle picks the gender's default so the
  // menu always has a real current selection rather than defaulting to nothing.
  const gender = genderFromBodyKey(profile.body_key);
  const effectiveHairStyle = resolveDefaultHairStyle(profile);
  const hairStyleMenu = new StringSelectMenuBuilder().setCustomId('avatarlocker_customize_hairstyle').setPlaceholder('Choose your hairstyle')
    .addOptions(HAIR_STYLES_BY_GENDER[gender].map(key => ({ label: HAIR_STYLE_LABELS[key], value: key, default: key === effectiveHairStyle })));
  const hairColorMenu = new StringSelectMenuBuilder().setCustomId('avatarlocker_customize_haircolor').setPlaceholder('Choose your hair color')
    .addOptions(HAIR_COLOR_PALETTE.map(c => ({ label: c.name, value: c.hex.replace('#', ''), default: c.hex.replace('#', '').toUpperCase() === String(profile.hair_color || '').replace('#', '').toUpperCase() })));

  return [
    new ActionRowBuilder().addComponents(bodyMenu),
    new ActionRowBuilder().addComponents(skinMenu),
    new ActionRowBuilder().addComponents(hairStyleMenu),
    new ActionRowBuilder().addComponents(hairColorMenu),
    new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('avatarlocker_back').setLabel('⬅ Back to Locker').setStyle(ButtonStyle.Secondary)),
  ];
}

// ---------------------------------------------------------------------------
