// 7J-89RECRUIT: v1 vacancy detection — a team is "open" if its Discord role
// currently has zero non-bot members. No stored/manual "recruiting" flag;
// this is computed live every time so it can never drift from reality (an
// owner leaving the server, or a commissioner removing the role, shows up
// immediately without anyone having to remember to flag it).
// 7J-97SUSPEND: called once per team per reported game. Case-insensitive
// team name match since Madden team names get formatted/displayed several
// different ways across this codebase (with logos, abbreviations, etc.) —
// matches on the raw stored team_name.
// 7J-97SUSPEND: shared by the slash command, the Commissioner Panel button,
// and the posted board refresh — one implementation.
function buildSuspensionsListEmbed(league, rows) {
  const NL = String.fromCharCode(10);
  return new EmbedBuilder()
    .setTitle(`🚫 Player Suspensions • ${league.league_name}`)
    .setColor(0xED4245)
    .setDescription(rows.length
      ? rows.map(r => `**${r.player_name}** (${r.team_name}) — ${r.games_remaining}/${r.games_total} games left${r.reason ? NL + `Reason: ${r.reason}` : ''}${NL}ID: \`${r.id.slice(0, 8)}\``).join(NL + NL)
      : 'No active suspensions.')
    .setFooter({ text: 'GG Sports • Informational only — no in-game enforcement' })
    .setTimestamp();
}

// Posts a fresh copy to the configured channel if none exists yet there, or
// edits the existing message in place — same single-channel-per-league
// pattern as Standings/Tournament (league_settings.*_channel_id +
// league_panels), not the multi-channel mechanism Shop/Marketplace use.
async function refreshSuspensionsBoard(guild, league) {
  if (!league.suspensions_channel_id) return;
  const channel = await guild.channels.fetch(league.suspensions_channel_id).catch(() => null);
  if (!channel?.isTextBased?.()) return;
  const result = await pool.query(
    `SELECT * FROM league_player_suspensions WHERE league_id = $1 AND games_remaining > 0 ORDER BY team_name ASC, player_name ASC`,
    [league.league_id]
  );
  const embed = buildSuspensionsListEmbed(league, result.rows);
  const existing = await pool.query(
    `SELECT channel_id, message_id FROM league_panels WHERE league_id = $1 AND panel_key = 'suspensions' LIMIT 1`,
    [league.league_id]
  );
  if (existing.rows.length && existing.rows[0].channel_id === league.suspensions_channel_id) {
    const message = await channel.messages.fetch(existing.rows[0].message_id).catch(() => null);
    if (message) { await message.edit({ embeds: [embed] }).catch(() => null); return; }
  }
  const newMessage = await channel.send({ embeds: [embed] }).catch(() => null);
  if (newMessage) {
    await pool.query(
      `INSERT INTO league_panels (league_id, panel_key, channel_id, message_id)
       VALUES ($1, 'suspensions', $2, $3)
       ON CONFLICT (league_id, panel_key) DO UPDATE SET channel_id = $2, message_id = $3`,
      [league.league_id, channel.id, newMessage.id]
    ).catch(() => null);
  }
}

async function decrementActiveSuspensionsForTeam(guildId, leagueId, teamName) {
  if (!teamName) return;
  await pool.query(
    `UPDATE league_player_suspensions
     SET games_remaining = GREATEST(0, games_remaining - 1)
     WHERE guild_id = $1 AND league_id = $2 AND games_remaining > 0 AND LOWER(team_name) = LOWER($3)`,
    [guildId, leagueId, teamName]
  );
}

// 7J-98WAITLIST: DMs every waitlist entry watching this team (or watching
// "any team" — team_names IS NULL) for this league. Best-effort, DMs
// closed is a silent skip like everywhere else in this bot. Does NOT
// remove the waitlist entry after notifying — someone might want to hear
// about the next opening too if this one doesn't work out for them.
// 7J-98WAITLIST: the other clear "team just became vacant" moment — a
// member with a team role leaving the server. member.roles.cache still
// reflects their roles as of the moment they left.
async function notifyWaitlistForMemberLeaveIfTeamHolder(member) {
  if (member.user?.bot) return;
  const leagues = await getActiveLeaguesForGuild(member.guild.id).catch(() => []);
  for (const league of leagues) {
    const teams = await getLeagueTeamRoles(league.league_id).catch(() => []);
    for (const team of teams) {
      if (member.roles.cache.has(team.role_id)) {
        await notifyWaitlistForVacantTeam(member.guild, league, team.role_name).catch(() => null);
      }
    }
  }
}

// 7J-99WAGER: settles any accepted wager tied to this game once it has a
// real final score. Winner determined by comparing the wager's recorded
// team names to which side actually won — a tie refunds both sides rather
// than guessing. Both amounts were already escrowed at acceptance, so this
// only ever pays out/refunds, never deducts again.
async function settleGameWager(guild, game, forcedWinningTeamName = null) {
  const result = await pool.query(
    `SELECT * FROM game_wagers WHERE game_id = $1 AND status = 'accepted' LIMIT 1`,
    [game.id]
  ).catch(() => ({ rows: [] }));
  const wager = result.rows[0];
  if (!wager) return null;

  const pot = wager.amount * 2;
  let winningTeam;

  // 7J-155FORCEDWINWAGER: a staff-forced result (forfeit/dispute override)
  // has no real score by design — game.home_score/away_score are NULL — so
  // there's nothing to compare. The caller already knows exactly who won
  // (that's the whole point of a forced result), so it passes the winning
  // team name directly instead, skipping the score comparison and the
  // tie/push path entirely (a forced result is never a tie — winnerSide is
  // always explicitly 'home' or 'away').
  if (forcedWinningTeamName) {
    winningTeam = forcedWinningTeamName;
  } else {
    const homeScore = Number(game.home_score);
    const awayScore = Number(game.away_score);
    if (!Number.isFinite(homeScore) || !Number.isFinite(awayScore)) return null;

    if (homeScore === awayScore) {
      await addCurrency(wager.guild_id, wager.proposer_user_id, wager.amount, 'wager_refund', 'Wager push (tie) — refunded', null);
      await addCurrency(wager.guild_id, wager.opponent_user_id, wager.amount, 'wager_refund', 'Wager push (tie) — refunded', null);
      await pool.query(`UPDATE game_wagers SET status = 'pushed', settled_at = NOW() WHERE id = $1`, [wager.id]);
      return { pushed: true };
    }
    winningTeam = homeScore > awayScore ? game.home_team : game.away_team;
  }

  const winnerUserId = String(wager.proposer_team).toLowerCase() === String(winningTeam).toLowerCase()
    ? wager.proposer_user_id
    : String(wager.opponent_team).toLowerCase() === String(winningTeam).toLowerCase()
      ? wager.opponent_user_id
      : null;
  if (!winnerUserId) return null; // team names didn't match either side — leave it for staff to sort out manually rather than guess

  await addCurrency(wager.guild_id, winnerUserId, pot, 'wager_win', `Wager won: ${game.away_team} @ ${game.home_team}`, null);
  await pool.query(`UPDATE game_wagers SET status = 'settled', winner_user_id = $1, settled_at = NOW() WHERE id = $2`, [winnerUserId, wager.id]);
  const winnerUser = await client.users.fetch(winnerUserId).catch(() => null);
  const settings = await getCurrencySettings(guild.id).catch(() => ({ currency_icon: '🪙' }));
  await winnerUser?.send({ content: `🎉 You won your wager on **${game.away_team} @ ${game.home_team}**! ${settings.currency_icon} ${pot} has been added to your balance.` }).catch(() => null);
  return { settled: true, winnerUserId, pot };
}

async function notifyWaitlistForVacantTeam(guild, league, teamName) {
  if (!teamName) return;
  const result = await pool.query(
    `SELECT * FROM league_waitlist WHERE guild_id = $1 AND league_id = $2
       AND (team_names IS NULL OR team_names ILIKE $3)`,
    [guild.id, league.league_id, `%${teamName}%`]
  ).catch(() => ({ rows: [] }));
  for (const entry of result.rows) {
    const user = await client.users.fetch(entry.user_id).catch(() => null);
    await user?.send({
      content: `🎉 **${teamName}** just opened up in **${league.league_name}** (${guild.name}) — you're on the waitlist! Head to the Recruitment panel and use \`Browse Open Teams\` to apply before someone else does.`,
    }).catch(() => null);
  }
}

// 7J-112SERVERSETUP: guild-wide counterpart to autoCreateLeagueChannels below —
// creates one "GG Sports" category (not named after any one league, since
// none of these panel types are league-specific — the 7 real multi-channel
// panels are guild-wide via multi_channel_panels, keyed by guild_id/panel_type/
// channel_id only) and posts each board immediately via the existing
// postOrRefreshMultiChannelPanel. Lives in the Admin Panel's Server Setup
// category per Hxxdie (moved here from League Setup — this function was never
// actually league-specific, so Server Setup is the more honest home).
// Also creates Welcome/Leave channels here when that feature is enabled but
// channels aren't set yet, per Hxxdie's ask to fold that into this flow too —
// skipped entirely (not just left unset) if welcome_leave_enabled is off, so
// this doesn't create channels for a feature the server hasn't turned on.
async function autoCreateGuildMultiChannelPanels(guild) {
  const category = await guild.channels.create({ name: 'GG Sports', type: ChannelType.GuildCategory });
  const created = [];

  // 7J-CHANORDER: per Hxxdie — channel creation order now matches the exact
  // order Hxxdie manually arranged the GG Sports category into: Welcome &
  // Goodbye first, then Recruitment, Member Profile, Avatar, Bank, Shop,
  // Marketplace, Sportsbook Board, Support, Tickets. Previously this ran
  // shop/sportsbook/marketplace/avatar/bank/profile/recruitment first and
  // created Welcome/Leave dead last, which didn't match the order a fresh
  // server actually wants these to land in.
  // 7J-WELCOMEGOODBYE: renamed from "welcome-and-leave" to
  // "welcome-and-goodbye" per Hxxdie — same channel, same
  // welcome_channel_id/leave_channel_id dual-purpose behavior below, just a
  // friendlier name.
  const refreshedGuildSettings = await getGuildSettings(guild.id, guild.name).catch(() => null);
  const existingWelcomeChannel = refreshedGuildSettings?.welcome_channel_id
    ? await guild.channels.fetch(refreshedGuildSettings.welcome_channel_id).catch(() => null)
    : null;
  const existingLeaveChannel = refreshedGuildSettings?.leave_channel_id
    ? await guild.channels.fetch(refreshedGuildSettings.leave_channel_id).catch(() => null)
    : null;
  if (!existingWelcomeChannel && !existingLeaveChannel) {
    const welcomeLeaveChannel = await guild.channels.create({ name: 'welcome-and-goodbye', type: ChannelType.GuildText, parent: category.id }).catch(() => null);
    if (welcomeLeaveChannel) {
      await setGuildWelcomeChannel(guild.id, guild.name, welcomeLeaveChannel.id);
      await setGuildLeaveChannel(guild.id, guild.name, welcomeLeaveChannel.id);
      created.push(welcomeLeaveChannel);
    }
  } else if (!existingWelcomeChannel) {
    const welcomeChannel = await guild.channels.create({ name: 'welcome', type: ChannelType.GuildText, parent: category.id }).catch(() => null);
    if (welcomeChannel) {
      await setGuildWelcomeChannel(guild.id, guild.name, welcomeChannel.id);
      created.push(welcomeChannel);
    }
  } else if (!existingLeaveChannel) {
    const leaveChannel = await guild.channels.create({ name: 'goodbye', type: ChannelType.GuildText, parent: category.id }).catch(() => null);
    if (leaveChannel) {
      await setGuildLeaveChannel(guild.id, guild.name, leaveChannel.id);
      created.push(leaveChannel);
    }
  }
  await setGuildWelcomeLeaveEnabled(guild.id, guild.name, true);

  // 7J-COMMANDHUB-PAYWALL: per Hxxdie's full free/premium breakdown —
  // shop/sportsbook/marketplace/avatar/bank/member-profile are all
  // Premium; recruitment (applications) stays free (only the cross-server
  // Discover Leagues *discoverability toggle* is Premium, gated separately
  // where that toggle actually flips). Free Tier guilds simply don't get
  // the premium-only channels created here at all — combined with the
  // centralized interaction gate, this means neither the channel nor a
  // working panel exists for Free Tier, rather than an unusable channel
  // sitting there.
  const isPremium = await isGuildPremiumActive(guild.id);
  const allPanelSpecs = [
    ['recruitment', 'recruitment', false],
    ['profile', 'member-profile', true],
    ['avatar', 'avatar', true],
    ['bank', 'bank', true],
    ['shop', 'shop', true],
    ['marketplace', 'marketplace', true],
    ['sportsbook', 'sportsbook-board', true],
  ];
  const panelSpecs = allPanelSpecs
    .filter(([, , premiumOnly]) => !premiumOnly || isPremium)
    .map(([panelType, channelName]) => [panelType, channelName]);
  for (const [panelType, channelName] of panelSpecs) {
    const channel = await guild.channels.create({ name: channelName, type: ChannelType.GuildText, parent: category.id }).catch(() => null);
    if (!channel) continue;
    await postOrRefreshMultiChannelPanel(guild, panelType, channel).catch(() => null);
    created.push(channel);
  }

  // 7J-TOURNAMENTCATEGORY: per Hxxdie — tournaments get their own category
  // now, not folded into the shared "GG Sports" category. "Tournaments" is
  // where staff create tournaments and the registration panel posts (same
  // multi_channel_panel type as before, just relocated); "Tournament
  // History" is a plain destination channel — past brackets and champions
  // get archived there once a tournament completes and its temporary
  // per-tournament channel gets deleted. Still Premium-gated like the
  // other optional channels.
  if (isPremium) {
    const tournamentCategory = await guild.channels.create({ name: '🏆 Tournaments', type: ChannelType.GuildCategory }).catch(() => null);
    if (tournamentCategory) {
      const tournamentChannel = await guild.channels.create({ name: 'tournaments', type: ChannelType.GuildText, parent: tournamentCategory.id }).catch(() => null);
      const tournamentHistoryChannel = await guild.channels.create({ name: 'tournament-history', type: ChannelType.GuildText, parent: tournamentCategory.id }).catch(() => null);
      if (tournamentChannel) {
        await postOrRefreshMultiChannelPanel(guild, 'tournament', tournamentChannel).catch(() => null);
        created.push(tournamentChannel);
      }
      if (tournamentHistoryChannel) created.push(tournamentHistoryChannel);
      await pool.query(
        `INSERT INTO guild_tournament_settings (guild_id, tournament_channel_id, tournament_history_channel_id, updated_at)
         VALUES ($1, $2, $3, NOW())
         ON CONFLICT (guild_id) DO UPDATE SET tournament_channel_id = $2, tournament_history_channel_id = $3, updated_at = NOW()`,
        [guild.id, tournamentChannel?.id || null, tournamentHistoryChannel?.id || null]
      ).catch(() => null);
    }
  }

  // 7J-149TICKETSAUTOSETUP: per Hxxdie — Tickets/Support are guild-wide
  // (7J-111TICKETSCOPE), so they belong in this same guild-wide auto-setup
  // flow rather than needing to be configured by hand afterward. Only
  // creates whichever of the two isn't already set, same "don't clobber an
  // existing setup" behavior as the Welcome/Leave block above.
  // 7J-COMMANDHUB-PAYWALL: Tickets/Support are Premium (per Hxxdie's full
  // free/premium breakdown) — gated the same way as shop/sportsbook/etc.
  // above, so Free Tier doesn't get a channel for a feature it can't
  // actually use (the /ticket command and ticket_ panel buttons are
  // already gated separately).
  // 7J-COMMANDHUB-TICKETSUPPORTSPLIT: Tickets gets the plain instructional
  // panel (/ticket open|dispute|game usage); Support gets the richer
  // button-based panel — matches the existing distinction between
  // /ticket panel and /ticket supportpanel elsewhere in this codebase,
  // rather than posting the same content to both.
  // 7J-CHANORDER: Support now created before Tickets (previously the
  // reverse), matching Hxxdie's reordered category.
  const guildSettings = await getGuildSettings(guild.id, guild.name).catch(() => null);
  if (isPremium) {
    const existingSupportChannel = guildSettings?.support_channel_id
      ? await guild.channels.fetch(guildSettings.support_channel_id).catch(() => null)
      : null;
    if (!existingSupportChannel) {
      const supportChannel = await guild.channels.create({ name: 'support', type: ChannelType.GuildText, parent: category.id }).catch(() => null);
      if (supportChannel) {
        await setGuildTicketSettings(guild.id, guild.name, { supportChannelId: supportChannel.id });
        await supportChannel.send({ embeds: [buildSupportPanelEmbed()], components: [buildSupportPanelButtons()] }).catch(() => null);
        created.push(supportChannel);
      }
    }

    // 7J-STALECHANNELCHECK: per Hxxdie — Support channel wasn't getting
    // (re)created during auto-setup. Root cause: this only checked whether
    // a channel ID was *stored*, not whether that channel still actually
    // exists — if it was deleted at some point (manually, or during
    // testing cleanup) without the stored ID ever being cleared, this
    // silently treated it as "already set up" forever. Now verifies the
    // channel genuinely resolves before trusting it, same fix class as the
    // Check Bot Permissions audit elsewhere in this file. Applied to both
    // Tickets and Support since both share the identical risk.
    const existingTicketChannel = guildSettings?.ticket_channel_id
      ? await guild.channels.fetch(guildSettings.ticket_channel_id).catch(() => null)
      : null;
    if (!existingTicketChannel) {
      // 7J-TICKETPRIVATE: per Hxxdie — Tickets is a staff-only triage
      // dashboard (Open/Urgent/Unclaimed/Reviewing filters), not something
      // members should see or post in directly — Support is the actual
      // member-facing entry point for that. Denies @everyone View Channel
      // and explicitly grants every active league's staff role in this
      // guild, since Tickets is guild-wide and there's no single "guild
      // staff role" concept to target instead. Administrators/Manage
      // Server holders can always see it regardless, per Discord's own
      // permission model.
      const staffRoleRows = await pool.query(
        `SELECT DISTINCT s.staff_role_id FROM league_settings s
         JOIN leagues l ON l.league_id = s.league_id
         WHERE l.guild_id = $1 AND l.is_active = TRUE AND s.staff_role_id IS NOT NULL`,
        [guild.id]
      ).catch(() => ({ rows: [] }));
      // 7J-BOTLOCKOUT: real bug found and fixed — denying @everyone
      // includes the bot itself unless explicitly granted back, and this
      // never was. The bot silently lost View Channel on the very channel
      // it had just created, so the dashboard post right after this
      // (requireTextChannel checks the bot's own permissions) failed
      // quietly — the auto-setup call site discards the result via
      // .catch(() => null) with no logging, so nothing visible happened
      // anywhere. Explicit bot-role grant added; also worth remembering
      // for any future private-channel creation in this file.
      const botMember = await guild.members.fetchMe();
      const permissionOverwrites = [
        { id: guild.roles.everyone.id, deny: [PermissionFlagsBits.ViewChannel] },
        { id: botMember.id, allow: [PermissionFlagsBits.ViewChannel, PermissionFlagsBits.SendMessages, PermissionFlagsBits.EmbedLinks] },
        ...staffRoleRows.rows.map(row => ({ id: row.staff_role_id, allow: [PermissionFlagsBits.ViewChannel, PermissionFlagsBits.SendMessages] })),
      ];
      const ticketChannel = await guild.channels.create({ name: 'tickets', type: ChannelType.GuildText, parent: category.id, permissionOverwrites }).catch(() => null);
      if (ticketChannel) {
        await setGuildTicketSettings(guild.id, guild.name, { ticketChannelId: ticketChannel.id });
        created.push(ticketChannel);
      }
    }
    const ticketPanelResult = await createConfiguredPanelFromSetup({ guild, channel: null }, null, 'ticket_panel').catch(err => {
      console.error('[Auto Setup] Ticket dashboard post failed:', err?.message || err);
      return null;
    });
    console.log('[Auto Setup] Ticket dashboard result:', ticketPanelResult);
  }

  return { category, channels: created };
}

// 7J-110RELOCATE: creates the three per-league roles (league/staff/trade
// 7J-ROLECONFIRM: per Hxxdie — misclicked this instead of Create League
// (they sit stacked in the same League Setup section, both green) and it
// silently created a second, orphaned set of league roles for a league that
// already had them. runAdminPanelAutoCreateLeagueRoles always creates brand
// new Discord roles regardless of whether ones already exist — only which
// ones league_settings ends up *pointing at* is conditional (COALESCE), so
// a duplicate run doesn't just confuse things, it leaves real dangling
// roles in the server's role list with nothing referencing them. This
// builds a confirm step naming the exact league and, if it already has any
// of the three roles set, an explicit warning before anything gets created.
function buildAutoCreateRolesConfirmPayload(league) {
  const existing = [
    league.league_role_id ? `League Role: <@&${league.league_role_id}>` : null,
    league.staff_role_id ? `Staff Role: <@&${league.staff_role_id}>` : null,
    league.trade_committee_role_id ? `Trade Committee Role: <@&${league.trade_committee_role_id}>` : null,
  ].filter(Boolean);

  const warning = existing.length
    ? `\n\n⚠️ **${league.league_name}** already has role(s) set:\n${existing.join('\n')}\n\nRunning this again will create **brand new** Discord roles and leave these existing ones in place, unassigned and orphaned, unless you delete them yourself afterward.`
    : '';

  const content = `Auto-create League/Staff/Trade Committee roles for **${league.league_name}**?${warning}`;
  const components = [new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`adminpanel_autosetup_roles_confirm:${league.league_id}:yes`).setLabel(existing.length ? 'Create Duplicate Roles Anyway' : 'Create Roles').setEmoji('✅').setStyle(existing.length ? ButtonStyle.Danger : ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`adminpanel_autosetup_roles_confirm:${league.league_id}:no`).setLabel('Cancel').setEmoji('❌').setStyle(ButtonStyle.Secondary),
  )];
  return { content, components };
}

// committee) and saves them via the canonical Setup Dashboard columns, then
// offers a button straight into that league's Commissioner Panel so the
// admin can keep going without hunting for it. Called either right after a
// deferReply (single-league case) or after an interaction.update (multi-
// league picker case) — editReply works in both since either acknowledgment
// leaves the interaction in an editable state.
async function runAdminPanelAutoCreateLeagueRoles(interaction, league) {
  const leagueRole = await interaction.guild.roles.create({ name: `${league.league_name} League`, mentionable: true, reason: `Auto-created league role for ${league.league_name}` }).catch(() => null);
  const staffRole = await interaction.guild.roles.create({ name: `${league.league_name} Staff`, mentionable: true, reason: `Auto-created staff role for ${league.league_name}` }).catch(() => null);
  const committeeRole = await interaction.guild.roles.create({ name: `${league.league_name} Trade Committee`, mentionable: true, reason: `Auto-created trade committee role for ${league.league_name}` }).catch(() => null);

  await pool.query(
    `INSERT INTO league_settings (league_id, league_role_id, staff_role_id, trade_committee_role_id, updated_at)
     VALUES ($1, $2, $3, $4, NOW())
     ON CONFLICT (league_id) DO UPDATE SET
       league_role_id = COALESCE($2, league_settings.league_role_id),
       staff_role_id = COALESCE($3, league_settings.staff_role_id),
       trade_committee_role_id = COALESCE($4, league_settings.trade_committee_role_id),
       updated_at = NOW()`,
    [league.league_id, leagueRole?.id || null, staffRole?.id || null, committeeRole?.id || null]
  );

  const created = [leagueRole, staffRole, committeeRole].filter(Boolean);
  const continueRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`adminpanel_open_commissioner:${league.league_id}`).setLabel('Continue in Commissioner Panel').setEmoji('➡️').setStyle(ButtonStyle.Primary)
  );
  await interaction.editReply({
    content: `Created **${created.length}** role${created.length === 1 ? '' : 's'} for **${league.league_name}**: ${created.map(r => r.toString()).join(', ') || 'none — role creation failed'}. Continue league-specific setup (core channels, trade setup channels, team roles) in the Commissioner Panel.`,
    components: [continueRow],
  });
}

// 7J-100AUTOSETUP: creates a category + a curated set of channels for a
// league and wires each single-channel setting into league_settings
// immediately, plus (7J-110RELOCATE) the trade-setup channels and their
// panels, so a league is functional out of the box right after creation.
// The 7 Multi-Channel Panel channels (Shop/Marketplace/Avatar/Recruitment/
// Bank/Member Profile/Sportsbook Board) moved OUT of this function per
// Hxxdie — they're guild-wide, not league-specific, so they now live in the
// Admin Panel's League Setup page instead (see autoCreateGuildMultiChannelPanels
// above). This function is what's left: core channels + trade setup, both of
// which genuinely are per-league. Curated rather than exhaustive: this bot
// has 40+ possible channel settings, most of them niche/optional — this
// covers what a new league actually needs to get going, and anything else
// is still one click away in the Setup Dashboard.
// 7J-128CATEGORYEMOJI: category emoji used to be a hardcoded football
// regardless of sport — an NHL league got 🏈. Picks a real sport-specific
// emoji instead, falling back to a generic trophy for cfb/fc/other where a
// single emoji can't represent "every team in the sport" meaningfully.
function leagueCategoryEmoji(league) {
  const sportKey = getLeagueSportKey(league);
  const map = { madden: '🏈', nfl: '🏈', nba: '🏀', nhl: '🏒', mlb: '⚾', fc: '⚽', cfb: '🏈' };
  return map[sportKey] || '🏆';
}

async function autoCreateLeagueChannels(guild, league, isMadden) {
  const category = await guild.channels.create({ name: `${leagueCategoryEmoji(league)} ${league.league_name}`.slice(0, 100), type: ChannelType.GuildCategory });
  const created = [];

  // 7J-COMMANDHUB-PAYWALL: per Hxxdie's full free/premium breakdown for
  // per-league channels — Free Tier gets: announcements, rules, staff,
  // standings, streaming, game threads/center, trade block/negotiation/
  // committee/verdicts/counts, team owners, active check, suspensions,
  // league chat. Premium adds: free agents, news, power rankings, history,
  // playoff bracket, and (for non-Madden) their generic equivalents plus
  // League HOF (ties to the already-Premium /legacy system). Checked once
  // here and reused below for both channel creation and panel posting, so
  // the two stay in sync.
  const isPremiumLeague = await isGuildPremiumActive(guild.id);

  // 7J-145SCHEDULEFIX: real bug — this used to decide Game Threads vs. Game
  // Center purely off isMadden, but per Hxxdie's original ask a NON-Madden
  // league can also use the structured schedule (Advance/Start League)
  // system, in which case it needs Game Threads too, not Game Center. Only
  // a non-Madden league on the OPEN schedule style actually wants Game
  // Center. Checking league_custom_settings.schedule_style is the real
  // signal here, not the sport.
  const customSettings = !isMadden ? await ensureLeagueCustomSettings(league).catch(() => ({})) : {};
  const isStructuredNonMadden = !isMadden && customSettings.schedule_style === 'structured';

  // 7J-CHANNELREORDER: per Hxxdie — the previous order (rules,
  // announcements, staff, standings, streaming, games...) didn't match what
  // was actually wanted (team-owners/league-chat/league-news up near the
  // top, staff near the bottom). Rebuilt as a straightforward sequence of
  // conditional pushes in the exact desired final order, rather than
  // splice-based insertion at fixed indices — splice-index math gets
  // fragile to reason about once the order itself has this many
  // sport-conditional branches.
  let singleChannelSpecs = [
    ['league_rules_channel_id', 'rules'],
    ['league_announcement_channel_id', 'announcements'],
    ['team_owners_channel_id', 'team-owners'],
    ['league_chat_channel_id', 'league-chat'],
  ];
  if (isMadden) {
    singleChannelSpecs.push(['madden_news_channel_id', 'madden-news', true]);
  } else {
    singleChannelSpecs.push(['league_news_channel_id', 'league-news', true]);
  }
  if (isMadden || isStructuredNonMadden) {
    singleChannelSpecs.push(['game_threads_channel_id', 'game-threads']);
  } else {
    singleChannelSpecs.push(['game_center_channel_id', 'game-center']);
  }
  singleChannelSpecs.push(['live_channel_id', 'streaming']);
  singleChannelSpecs.push(['sportsbook_channel_id', 'sportsbook-feed', true]);
  if (isMadden) {
    singleChannelSpecs.push(['madden_standings_channel_id', 'madden-standings']);
    singleChannelSpecs.push(['madden_power_rankings_channel_id', 'power-rankings', true]);
  } else {
    singleChannelSpecs.push(['standings_channel_id', 'standings']);
    singleChannelSpecs.push(['league_power_rankings_channel_id', 'power-rankings', true]);
  }
  singleChannelSpecs.push(['trade_block_channel_id', 'trade-block']);
  // 7J-COMMANDHUB-TRADESPLIT: per Hxxdie (live-tested) — Trade Negotiation
  // Starter (buildMaddenTradeNegotiationStarterEmbed) is Madden-only; Trade
  // Offer (buildOfferTradePanelEmbed, the generic system /league
  // offerpanel also uses) is non-Madden-only. Was previously creating both
  // channels unconditionally for every league and posting both starter
  // panels regardless of sport — Madden leagues were getting the wrong
  // (non-Madden) Trade Offer panel.
  singleChannelSpecs.push(isMadden ? ['trade_negotiation_channel_id', 'trade-negotiation'] : ['trade_offer_channel_id', 'trade-offer']);
  singleChannelSpecs.push(['trade_committee_channel_id', 'trade-committee']);
  // 7J-TRADEDECISIONS: approved-trades and denied-trades merged into one
  // channel, per Hxxdie — both outcomes post to the same place now instead
  // of two separate channels.
  singleChannelSpecs.push(['trade_decisions_channel_id', 'trade-committee-decisions']);
  singleChannelSpecs.push(['trade_count_channel_id', 'trade-count']);
  singleChannelSpecs.push(['suspensions_channel_id', 'suspensions']);
  singleChannelSpecs.push(['active_check_channel_id', 'active-check']);
  singleChannelSpecs.push(['playoff_bracket_channel_id', 'playoff-bracket', true]);
  singleChannelSpecs.push(['history_channel_id', 'history', true]);
  if (!isMadden) {
    singleChannelSpecs.push(['league_hof_channel_id', 'league-hof', true]);
  }
  singleChannelSpecs.push(['staff_channel_id', 'staff']);

  if (isMadden) {
    // 7J-COMMANDHUB-AUTOSETUP: madden-gm and franchise-hub added per
    // Hxxdie — "no point in having a commissioner manually create and post
    // 3 channels when all the others are created and populated." Both
    // Premium; weekly-updates is a plain destination channel (Madden sync
    // posts into it over time, no starter panel to post) and stays Free.
    // 7J-COMMANDHUB-FULLCOVERAGE: player-search, league-leaders,
    // award-race, draft-recap, madden-sportsbook were all confirmed
    // missing entirely from auto-setup (live-tested by Hxxdie against a
    // Premium league — "still missing many major features") — added here.
    singleChannelSpecs.push(
      ['madden_free_agents_channel_id', 'free-agents', true],
      ['gm_panel_channel_id', 'madden-gm', true],
      ['madden_franchise_hub_channel_id', 'franchise-hub', true],
      ['madden_weekly_updates_channel_id', 'weekly-updates'],
      ['player_search_channel_id', 'player-search', true],
      ['league_leaders_channel_id', 'league-leaders', true],
      ['award_race_channel_id', 'award-race', true],
      ['draft_recap_channel_id', 'draft-recap', true],
      ['madden_sportsbook_channel_id', 'madden-sportsbook', true],
    );
  }

  if (!isPremiumLeague) {
    singleChannelSpecs = singleChannelSpecs.filter(([, , premiumOnly]) => !premiumOnly);
  }

  // 7J-STAFFCHANNELPRIVATE: per Hxxdie — the per-league Staff channel was
  // being created fully public, same gap as the guild-wide Tickets channel
  // had. Fresh league fetch here in case the staff role was only just
  // created moments earlier in the same setup flow (role creation and
  // channel creation are separate steps with no guaranteed order). Bot's
  // own role explicitly granted access too — the exact lockout mistake
  // just found and fixed on the Tickets channel, not repeating it here.
  const freshLeagueForStaffRole = await getLeagueById(league.league_id).catch(() => null);
  const staffRoleId = freshLeagueForStaffRole?.staff_role_id || null;
  const botMemberForChannels = await guild.members.fetchMe();

  for (let i = 0; i < singleChannelSpecs.length; i++) {
    const [column, channelName] = singleChannelSpecs[i];
    const createOptions = { name: channelName, type: ChannelType.GuildText, parent: category.id, position: i };
    if (column === 'staff_channel_id') {
      createOptions.permissionOverwrites = [
        { id: guild.roles.everyone.id, deny: [PermissionFlagsBits.ViewChannel] },
        { id: botMemberForChannels.id, allow: [PermissionFlagsBits.ViewChannel, PermissionFlagsBits.SendMessages, PermissionFlagsBits.EmbedLinks] },
        ...(staffRoleId ? [{ id: staffRoleId, allow: [PermissionFlagsBits.ViewChannel, PermissionFlagsBits.SendMessages] }] : []),
      ];
    }
    const channel = await guild.channels.create(createOptions).catch(() => null);
    if (!channel) continue;
    await pool.query(`UPDATE league_settings SET ${column} = $2, updated_at = NOW() WHERE league_id = $1`, [league.league_id, channel.id]).catch(() => null);
    created.push(channel);
  }

  // 7J-110RELOCATE / 7J-125FULLCOVERAGE: post league boards/panels in the
  // appropriate channels right away, same "functional out of the box" goal
  // this function always had — the Multi-Channel Panels (guild-wide) already
  // do this themselves; this is the equivalent for the per-league channels
  // just created above. Streaming/Staff/History/Playoff Bracket/Active
  // Check/Draft Recap/Madden Sportsbook don't have a static panel to post
  // (they're destinations for live/manual/periodic content, not persistent
  // boards), so only the channels that actually have a corresponding panel
  // type get one. Uses a minimal interaction-shaped object since
  // createConfiguredPanelFromSetup only reads .guild (and .channel as a
  // fallback we don't need, since every channel id it looks up was just
  // set on freshLeague below). ticket_panel is deliberately NOT posted
  // here (7J-111TICKETSCOPE) — Tickets/Support are guild-wide now, not
  // per-league, handled by Auto Setup Server Channels instead.
  // 7J-145SCHEDULEFIX: game_center_panel is only posted for the non-Madden
  // OPEN case — a structured non-Madden league's game-threads channel stays
  // empty (no panel, no threads) until Start League is actually pressed,
  // same as Madden's game-threads channel never gets a pre-populated panel.
  // 7J-COMMANDHUB-FULLCOVERAGE: trade_negotiation_starter_panel and
  // league_rules_panel are Free, all league types — league_rules_panel in
  // particular was never posted by this function at all before (the
  // channel got created but sat empty). player_search_panel,
  // league_leaders_panel, award_race_panel, madden_standings_panel are all
  // Madden-only additions matching the new channels above.
  const freshLeague = await getLeagueById(league.league_id).catch(() => null);
  if (freshLeague) {
    const fakeInteraction = { guild, channel: null };
    // 7J-COMMANDHUB-TRADESPLIT: trade_negotiation_starter_panel (Madden)
    // and trade_offer_panel (non-Madden) are mutually exclusive per sport,
    // same as game_center_panel/game_threads or league_hof/franchise_hub
    // — fixed here alongside the matching channel-creation fix above.
    let panelTypesToPost = isMadden
      ? ['league_rules_panel', 'trade_block_board_panel', 'trade_negotiation_starter_panel', 'team_owners_panel', 'trade_count_panel', 'madden_standings_panel', 'madden_free_agents_panel', 'player_search_panel', 'league_leaders_panel', 'award_race_panel', 'gm_panel_starter_panel', 'madden_franchise_hub_panel']
      : isStructuredNonMadden
        ? ['league_rules_panel', 'standings_panel', 'trade_block_board_panel', 'trade_offer_panel', 'team_owners_panel', 'trade_count_panel', 'league_hof_panel', 'league_power_rankings_panel']
        : ['league_rules_panel', 'standings_panel', 'trade_block_board_panel', 'trade_offer_panel', 'team_owners_panel', 'trade_count_panel', 'league_hof_panel', 'game_center_panel', 'league_power_rankings_panel'];
    if (!isPremiumLeague) {
      const PREMIUM_AUTO_PANEL_TYPES = new Set(['madden_free_agents_panel', 'gm_panel_starter_panel', 'madden_franchise_hub_panel', 'league_hof_panel', 'league_power_rankings_panel', 'player_search_panel', 'league_leaders_panel', 'award_race_panel']);
      panelTypesToPost = panelTypesToPost.filter(type => !PREMIUM_AUTO_PANEL_TYPES.has(type));
    }
    for (const panelType of panelTypesToPost) {
      await createConfiguredPanelFromSetup(fakeInteraction, freshLeague, panelType).catch(() => null);
    }
    await refreshSuspensionsBoard(guild, freshLeague).catch(() => null);
  }

  return { category, channels: created };
}

// 7J-116LEAGUEDELETE: full cleanup when a league is deleted, per Hxxdie — the
// old behavior was purely a soft delete (is_active = FALSE), leaving every
// role/channel/category the league ever had sitting around in Discord
// forever, orphaned. This deletes the real Discord objects (best-effort —
// one missing/already-deleted role or channel doesn't abort the rest) and
// nulls out the league_settings columns that pointed to them, since league
// creation re-activates an existing row by (guild_id, league_name) on a name
// collision — without nulling these out, recreating a league with the same
// name would silently resurrect references to deleted channels/roles.
// Deliberately does NOT touch guilds.ticket_channel_id/support_channel_id —
// those are guild-wide (7J-111TICKETSCOPE), not this league's to delete.
const LEAGUE_OWNED_CHANNEL_COLUMNS = [
  'league_announcement_channel_id', 'league_rules_channel_id', 'standings_channel_id',
  'trade_block_channel_id', 'sportsbook_channel_id', 'suspensions_channel_id',
  'team_owners_channel_id', 'trade_offer_channel_id', 'trade_committee_channel_id',
  'approved_trades_channel_id', 'denied_trades_channel_id', 'trade_decisions_channel_id', 'trade_count_channel_id',
  'live_channel_id', 'history_channel_id', 'tournament_channel_id', 'league_hof_channel_id',
  'madden_free_agents_channel_id', 'trade_negotiation_channel_id', 'player_search_channel_id',
  'gm_panel_channel_id', 'staff_channel_id', 'league_leaders_channel_id', 'award_race_channel_id',
  'member_profile_channel_id', 'bank_channel_id', 'playoff_bracket_channel_id',
  'game_threads_channel_id', 'madden_news_channel_id', 'madden_weekly_updates_channel_id',
  'madden_standings_channel_id', 'madden_power_rankings_channel_id', 'madden_sportsbook_channel_id',
  'game_center_channel_id', 'active_check_channel_id', 'draft_recap_channel_id',
  'madden_franchise_hub_channel_id',
  // 7J-135GENERICNEWS
  'league_power_rankings_channel_id', 'league_news_channel_id',
  // 7J-154WHOGOTNEXT
  'league_chat_channel_id',
  // 7K-ROSTERPANEL
  'team_roster_channel_id',
];
const LEAGUE_OWNED_ROLE_COLUMNS = ['league_role_id', 'staff_role_id', 'trade_committee_role_id', 'committee_role_id'];

// 7J-PERMAUDIT: on-demand counterpart to the automatic alert in
// refreshAllMultiChannelPanelPostings — that one only fires reactively, the
// next time something actually tries to post and fails. This checks every
// configured channel across every league in the guild (plus the 7 guild-wide
// multi-channel panels) in one pass, so a commissioner can catch a broken
// permission before it silently breaks something for weeks, per Hxxdie's ask.
//
// 7J-PERMAUDITCLEANUP: per Hxxdie — a deleted channel was being reported
// every single time this ran, forever, because nothing ever cleared the
// stale reference — the audit was purely diagnostic, not self-healing. Worse,
// every OTHER feature that tries to post to that same stale channel_id
// (panel refreshes, history posts, etc.) was silently failing against it in
// the background continuously, since those all just .catch(() => null) a
// dead channel fetch with no cleanup either. Now genuinely deleted channels
// (Discord error code 10003 specifically — not a permissions issue, which
// stays reportable-but-not-auto-fixed since that's something staff need to
// actually go grant, not something this bot can clear its way out of) get
// their stale reference cleaned up automatically: multi_channel_panels rows
// get deleted outright (nothing left to edit), league_settings columns get
// nulled back to "not configured" so features correctly detect that instead
// of retrying a dead ID forever.
async function auditGuildChannelPermissions(guild) {
  const REQUIRED_PERMS = ['ViewChannel', 'SendMessages', 'EmbedLinks', 'ReadMessageHistory'];
  const problems = [];
  const checked = new Set();

  async function checkOne(channelId, label) {
    if (!channelId || checked.has(channelId)) return null;
    checked.add(channelId);
    const channel = await guild.channels.fetch(channelId).catch(err => ({ __error: err }));
    if (!channel || channel.__error) {
      const code = channel?.__error?.code;
      if (code === 10003) {
        const problem = { channelId, label, issue: 'Channel no longer exists (deleted) — reference cleared automatically.', deleted: true };
        problems.push(problem);
        return problem;
      }
      problems.push({ channelId, label, issue: `Could not access this channel (${channel?.__error?.message || 'unknown error'}).` });
      return null;
    }
    if (!channel.isTextBased?.()) return null;
    const me = await guild.members.fetchMe().catch(() => null);
    if (!me) return null;
    const perms = channel.permissionsFor(me);
    const missing = REQUIRED_PERMS.filter(p => !perms?.has(PermissionFlagsBits[p]));
    if (missing.length) {
      problems.push({ channelId, label, issue: `Missing: ${missing.join(', ')}` });
    }
    return null;
  }

  const leaguesResult = await pool.query(`SELECT league_id FROM leagues WHERE guild_id = $1 AND is_active = TRUE`, [guild.id]).catch(() => ({ rows: [] }));
  for (const row of leaguesResult.rows || []) {
    const league = await getLeagueById(row.league_id).catch(() => null);
    if (!league) continue;
    for (const col of LEAGUE_OWNED_CHANNEL_COLUMNS) {
      if (!league[col]) continue;
      const deletedProblem = await checkOne(league[col], `${league.league_name} — ${col.replace(/_channel_id$/, '').replace(/_/g, ' ')}`);
      if (deletedProblem) {
        await pool.query(`UPDATE league_settings SET ${col} = NULL WHERE league_id = $1`, [league.league_id]).catch(error => {
          console.error(`[7J-PERMAUDITCLEANUP] Failed to clear ${col} for league ${league.league_id}:`, error?.message || error);
        });
      }
    }
  }

  const panelRows = await pool.query(`SELECT DISTINCT channel_id, panel_type FROM multi_channel_panels WHERE guild_id = $1`, [guild.id]).catch(() => ({ rows: [] }));
  for (const row of panelRows.rows || []) {
    const info = getMultiChannelPanelInfo(row.panel_type);
    const deletedProblem = await checkOne(row.channel_id, info?.label || row.panel_type);
    if (deletedProblem) {
      await pool.query(`DELETE FROM multi_channel_panels WHERE guild_id = $1 AND channel_id = $2`, [guild.id, row.channel_id]).catch(error => {
        console.error(`[7J-PERMAUDITCLEANUP] Failed to remove stale multi_channel_panels row for channel ${row.channel_id}:`, error?.message || error);
      });
    }
  }

  return problems;
}

async function deleteLeagueDiscordInfrastructure(guild, league) {
  const deletedChannelIds = [];
  let deletedRoles = 0;
  let deletedChannels = 0;

  // Roles: the three league-level roles plus every registered team role.
  const roleIds = new Set(LEAGUE_OWNED_ROLE_COLUMNS.map(col => league[col]).filter(Boolean));
  const teamRoles = await getLeagueTeamRoles(league.league_id).catch(() => []);
  for (const tr of teamRoles) roleIds.add(tr.role_id);

  for (const roleId of roleIds) {
    const role = await guild.roles.fetch(roleId).catch(() => null);
    if (role) {
      await role.delete('League deleted').catch(() => null);
      deletedRoles++;
    }
  }

  // Channels: every league-owned channel column that's actually set.
  const channelIds = new Set(LEAGUE_OWNED_CHANNEL_COLUMNS.map(col => league[col]).filter(Boolean));
  for (const channelId of channelIds) {
    const channel = await guild.channels.fetch(channelId).catch(() => null);
    if (channel) {
      deletedChannelIds.push(channel.parentId);
      await channel.delete('League deleted').catch(() => null);
      deletedChannels++;
    }
  }

  // Category: best-effort — only delete it if it's now actually empty, since
  // a category the league shares with something else (manually reorganized,
  // or a channel we didn't know about) shouldn't get deleted out from under it.
  let deletedCategory = false;
  const uniqueParentIds = [...new Set(deletedChannelIds.filter(Boolean))];
  for (const parentId of uniqueParentIds) {
    const category = await guild.channels.fetch(parentId).catch(() => null);
    if (!category) continue;
    const remainingChildren = guild.channels.cache.filter(c => c.parentId === parentId);
    if (remainingChildren.size === 0) {
      await category.delete('League deleted — category emptied out').catch(() => null);
      deletedCategory = true;
    }
  }

  // DB cleanup: drop the team role records (the roles themselves are gone)
  // and null out every channel/role column so a same-named league recreated
  // later doesn't inherit references to things that no longer exist.
  await pool.query(`DELETE FROM league_team_roles WHERE league_id = $1`, [league.league_id]).catch(() => null);
  const nullColumns = [...LEAGUE_OWNED_CHANNEL_COLUMNS, ...LEAGUE_OWNED_ROLE_COLUMNS].map(col => `${col} = NULL`).join(', ');
  await pool.query(`UPDATE league_settings SET ${nullColumns}, updated_at = NOW() WHERE league_id = $1`, [league.league_id]).catch(() => null);

  return { deletedRoles, deletedChannels, deletedCategory };
}

// 7J-FACTORYRESET: tables deliberately never touched by the factory reset —
// billing/subscription records (Stripe-tied, not "gameplay" data — see
// premium_entitlements.guild_id ... REFERENCES guilds(guild_id) ON DELETE
// CASCADE, which is exactly why `guilds` itself is also excluded: deleting
// that row would cascade-delete premium_entitlements regardless of this
// list) and premium_trial_claims (keyed by owner_user_id, not guild_id, so
// it's naturally untouched by a guild_id-scoped wipe anyway).
const FACTORY_RESET_EXCLUDED_TABLES = new Set([
  'guilds', 'premium_memberships', 'premium_entitlements', 'premium_billing_events',
]);

// 7J-FACTORYRESET: discovers every table with a guild_id column via
// information_schema rather than hand-maintaining a list — on a codebase
// this size (100+ tables), a hand-maintained list is guaranteed to drift
// out of date and silently miss newly-added tables. This stays correct by
// construction as the schema grows.
async function getFactoryResetTargetTables() {
  const result = await pool.query(
    `SELECT DISTINCT table_name FROM information_schema.columns
     WHERE table_schema = 'public' AND column_name = 'guild_id'`
  );
  return (result.rows || [])
    .map(r => r.table_name)
    .filter(name => !FACTORY_RESET_EXCLUDED_TABLES.has(name));
}

// 7J-FACTORYRESET: per Hxxdie — one-time pre-launch reset so testers don't
// carry a head start into real subscriber launch. Wipes every guild the bot
// is currently in: deletes all bot-created Discord infrastructure (league
// channels/roles via the existing per-league cleanup, plus the guild-wide
// GG Sports and Tournaments categories from auto-setup), then wipes every
// guild-scoped data table (see getFactoryResetTargetTables). Billing data
// is never touched. Best-effort per guild — one guild's failure doesn't
// abort the rest, since a partial reset finished for every OTHER guild is
// far better than one bad guild blocking the whole operation.
async function factoryResetOneGuild(guild, targetTables) {
  const errors = [];
  let leaguesRemoved = 0;
  let rowsDeleted = 0;

  const leaguesResult = await pool.query(`SELECT league_id FROM leagues WHERE guild_id = $1`, [guild.id]).catch(() => ({ rows: [] }));
  for (const row of leaguesResult.rows || []) {
    const league = await getLeagueById(row.league_id).catch(() => null);
    if (!league) continue;
    await deleteLeagueDiscordInfrastructure(guild, league).catch(error => {
      errors.push(`${guild.name} — league infra cleanup failed for ${league.league_name}: ${error?.message || error}`);
    });
    leaguesRemoved++;
  }

  // Guild-wide auto-setup categories aren't league-owned, so they need
  // their own cleanup — matched by the exact names autoCreateGuildMultiChannelPanels
  // uses when creating them.
  for (const categoryName of ['GG Sports', '🏆 Tournaments']) {
    const category = guild.channels.cache.find(c => c.type === ChannelType.GuildCategory && c.name === categoryName);
    if (!category) continue;
    const children = guild.channels.cache.filter(c => c.parentId === category.id);
    for (const child of children.values()) {
      await child.delete('Factory reset').catch(error => {
        errors.push(`${guild.name} — failed to delete channel #${child.name}: ${error?.message || error}`);
      });
    }
    await category.delete('Factory reset').catch(error => {
      errors.push(`${guild.name} — failed to delete category ${categoryName}: ${error?.message || error}`);
    });
  }

  // Data wipe — one DELETE per discovered table, wrapped in a transaction
  // so a mid-wipe failure doesn't leave this guild in a half-wiped state.
  const dbClient = await pool.connect();
  try {
    await dbClient.query('BEGIN');
    for (const table of targetTables) {
      const result = await dbClient.query(`DELETE FROM "${table}" WHERE guild_id = $1`, [guild.id]).catch(error => {
        errors.push(`${guild.name} — wipe failed for table ${table}: ${error?.message || error}`);
        return { rowCount: 0 };
      });
      rowsDeleted += result.rowCount || 0;
    }
    await dbClient.query('COMMIT');
  } catch (error) {
    await dbClient.query('ROLLBACK').catch(() => null);
    errors.push(`${guild.name} — transaction rolled back: ${error?.message || error}`);
  } finally {
    dbClient.release();
  }

  // guilds row itself is preserved (see FACTORY_RESET_EXCLUDED_TABLES
  // comment above) — just reset the specific columns that matter for a
  // clean re-run of Auto Setup Server Channels.
  await pool.query(
    `UPDATE guilds SET ticket_channel_id = NULL, support_channel_id = NULL, welcome_channel_id = NULL, leave_channel_id = NULL, welcome_leave_enabled = FALSE WHERE guild_id = $1`,
    [guild.id]
  ).catch(error => {
    errors.push(`${guild.name} — failed to reset guilds row: ${error?.message || error}`);
  });

  return { leaguesRemoved, rowsDeleted, errors };
}

async function runFactoryResetAllGuilds(client) {
  const targetTables = await getFactoryResetTargetTables();
  let guildsProcessed = 0;
  let leaguesRemoved = 0;
  let rowsDeleted = 0;
  const errors = [];

  for (const guild of client.guilds.cache.values()) {
    try {
      const result = await factoryResetOneGuild(guild, targetTables);
      leaguesRemoved += result.leaguesRemoved;
      rowsDeleted += result.rowsDeleted;
      errors.push(...result.errors);
    } catch (error) {
      errors.push(`${guild.name} (${guild.id}) — guild-level failure, skipped: ${error?.message || error}`);
      console.error('[7J-FACTORYRESET] Guild-level failure:', guild.id, error?.stack || error?.message || error);
    }
    guildsProcessed++;
  }

  console.log(`[7J-FACTORYRESET] Complete. Guilds: ${guildsProcessed}, leagues removed: ${leaguesRemoved}, rows deleted: ${rowsDeleted}, tables: ${targetTables.length}, errors: ${errors.length}`);
  return { guildsProcessed, leaguesRemoved, rowsDeleted, tablesWiped: targetTables.length, errors };
}

// 7J-100AUTOSETUP: real team names for madden(NFL)/nba/nhl/mlb (REAL_TEAM_NAMES),
// placeholder "Team 1".."Team N" for everything else (fc/cfb/other — per
// Hxxdie, fc has too many real teams to enumerate, and club/pro-am leagues
// don't have real team names to begin with). teamCount only matters for the
// placeholder path — the real lists are always used in full.
// 7J-COMMANDHUB-ROLEPREFIX: builds the Discord-visible role name — team
// name always stays fully intact and untruncated (that's the part people
// actually need to read), the league-name prefix gets shortened first if
// the combination would exceed Discord's 100-char role name cap. Distinct
// from what gets stored in league_team_roles.role_name (see below) — the
// DB column stays the plain team name always, since it's exact-matched
// (case-insensitive) against EA sync team names and other lookups
// elsewhere in this codebase; only the Discord-facing display name changes.
function buildPrefixedTeamRoleName(leagueName, teamName, guild) {
  const suffix = ' ' + teamName;
  let safeLeagueName = leagueName;
  if (('[' + safeLeagueName + ']' + suffix).length > 100) {
    const maxLeagueNameLen = Math.max(1, 100 - suffix.length - 2);
    safeLeagueName = leagueName.slice(0, maxLeagueNameLen);
  }
  let candidate = `[${safeLeagueName}]${suffix}`.slice(0, 100);
  // Safety net — collisions shouldn't happen once every league is prefixed
  // with its own name, but a second league with an identical or truncated-
  // identical name is possible, so fall back to a numeric suffix rather
  // than silently creating another duplicate.
  if (guild && guild.roles.cache.some(r => r.name === candidate)) {
    for (let n = 2; n < 20; n++) {
      const numbered = `${candidate.slice(0, 100 - String(n).length - 1)} ${n}`;
      if (!guild.roles.cache.some(r => r.name === numbered)) { candidate = numbered; break; }
    }
  }
  return candidate;
}

async function autoCreateLeagueTeamRoles(guild, league, teamCount = 32) {
  const sportKey = getLeagueSportKey(league);
  const names = REAL_TEAM_NAMES[sportKey] || Array.from({ length: teamCount }, (_, i) => `Team ${i + 1}`);
  const createdRoles = [];
  for (const name of names) {
    // 7J-COMMANDHUB-ROLEPREFIX: per Hxxdie (live-tested) — two leagues of
    // the same sport (e.g. two Madden leagues) were creating two fully
    // identical sets of 32 role names, with no way to tell them apart in
    // the server's role list. Discord-visible name gets the league prefix;
    // role_name in the DB stays the plain team name (see
    // buildPrefixedTeamRoleName's comment for why that split matters).
    const displayName = buildPrefixedTeamRoleName(league.league_name, name, guild);
    const role = await guild.roles.create({ name: displayName, mentionable: true, reason: `Auto-created team role for ${league.league_name}` }).catch(() => null);
    if (!role) continue;
    await pool.query(
      `INSERT INTO league_team_roles (league_id, role_id, role_name) VALUES ($1, $2, $3)
       ON CONFLICT (league_id, role_id) DO UPDATE SET role_name = $3`,
      [league.league_id, role.id, name]
    ).catch(() => null);
    createdRoles.push(role);
  }
  return createdRoles;
}

async function getVacantLeagueTeams(guild, league) {
  const teams = await getLeagueTeamRoles(league.league_id);
  const vacant = [];
  for (const team of teams) {
    const role = guild.roles.cache.get(team.role_id) || await guild.roles.fetch(team.role_id).catch(() => null);
    if (!role) continue; // role deleted from the server — not a valid team to recruit for
    const memberCount = role.members.filter(m => !m.user.bot).size;
    if (memberCount === 0) vacant.push(team);
  }
  return vacant;
}

function buildRecruitmentStarterEmbed() {
  return new EmbedBuilder()
    .setTitle('🎯 Recruitment')
    .setColor(0x57F287)
    .setDescription('Browse open team slots and apply — no need to ask around in chat. Applications go to the commissioner for approval before a team role is assigned.')
    .setFooter({ text: 'GG Sports • Recruitment' })
    .setTimestamp();
}

function buildRecruitmentStarterComponents() {
  return [
    // 7J-131RECRUITMOVE: Review Applications / Discoverable Setting removed
    // from here per Hxxdie — both are staff-only, league-scoped actions that
    // didn't belong mixed in with member-facing buttons on a panel every
    // member in the server can see. Moved to each league's Commissioner
    // Panel > Operations instead (commissioner_op:recruitreview /
    // commissioner_op:recruitdiscoverable).
    new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('recruitmentpanel_browse').setLabel('Browse Open Teams').setEmoji('🔍').setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('recruitmentpanel_discover').setLabel('Discover Leagues').setEmoji('🌐').setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('recruitmentpanel_discovertourney_page:0').setLabel('Discover Tournaments').setEmoji('🏆').setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('recruitmentpanel_myapplications').setLabel('My Applications').setEmoji('📄').setStyle(ButtonStyle.Secondary),
    ),
    // 7J-LEAGUERULESET: per Hxxdie — any member (not just staff) should be
    // able to see what kind of league this actually is before/after
    // applying — quarter length, difficulty, sim/comp, etc.
    new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('recruitmentpanel_leagueinfo').setLabel('League Info').setEmoji('📝').setStyle(ButtonStyle.Secondary),
    ),
    // 7J-98WAITLIST
    new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('recruitmentpanel_waitlist_join').setLabel('Join Waitlist').setEmoji('📋').setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('recruitmentpanel_waitlist_mine').setLabel('My Waitlist').setEmoji('📄').setStyle(ButtonStyle.Secondary),
    ),
  ];
}

// 7J-106LEAGUEPICK: resolveLeague's fallback (getDefaultLeague — oldest
// active league, no real "default" concept) worked fine for single-league
// guilds but silently picked the wrong league for multi-league guilds
// whenever Recruitment wasn't posted in a channel bound to one specific
// league (it's a guild-wide multi-channel panel, so it usually isn't).
// Confirmed live: locked onto MLB in a guild that also runs other leagues.
// Returns the league directly when there's only one (identical behavior/
// speed to before), otherwise shows a picker and returns null so the
// caller knows to stop — the picker's own select handler re-invokes the
// same action body function once a league is chosen.
async function resolveOrPickRecruitmentLeague(interaction, actionKey) {
  const leagues = await getActiveLeaguesForGuild(interaction.guild.id).catch(() => []);
  if (!leagues.length) {
    await interaction.editReply({ content: 'No active league found for this server.' });
    return null;
  }
  if (leagues.length === 1) return leagues[0];

  const menu = new StringSelectMenuBuilder()
    .setCustomId(`recruitmentpanel_leaguepick:${actionKey}`)
    .setPlaceholder('Which league?')
    .addOptions(leagues.slice(0, 25).map(l => ({ label: l.league_name.slice(0, 100), value: l.league_id })));
  await interaction.editReply({ content: 'This server runs more than one league — which one?', components: [new ActionRowBuilder().addComponents(menu)] });
  return null;
}

// 7J-APPNOTIFY: per Hxxdie — a pending application previously sat silent
// until someone happened to open the Recruitment panel and check. DMs
// everyone holding the league's staff role (the closest match this
// codebase has to "the commissioners" for a specific league — staff isn't
// a single person). Falls back to the live guild owner if no staff role is
// configured, or if one is configured but nobody currently holds it, so a
// fresh/lightly-staffed league doesn't just get skipped silently.
async function notifyLeagueStaffOfNewApplication(guild, league, teamName, applicant) {
  const targets = new Set();
  if (league?.staff_role_id) {
    const staffRole = await guild.roles.fetch(league.staff_role_id).catch(() => null);
    if (staffRole) {
      for (const member of staffRole.members.filter(m => !m.user.bot).values()) targets.add(member.id);
    }
  }
  if (!targets.size) {
    const owner = await guild.fetchOwner().catch(() => null);
    if (owner) targets.add(owner.id);
  }
  if (!targets.size) return;

  const embed = new EmbedBuilder()
    .setTitle('📥 New Recruitment Application')
    .setColor(0x5865F2)
    .setDescription(`**${applicant.tag || applicant.username}** applied for **${teamName}** in **${league.league_name}** (${guild.name}).`)
    .addFields({ name: 'Review it', value: 'Open the Recruitment panel in that server and use **Review Applications**.', inline: false })
    .setFooter({ text: 'GG Sports • Recruitment' })
    .setTimestamp();

  for (const userId of targets) {
    const user = await client.users.fetch(userId).catch(() => null);
    await user?.send({ embeds: [embed] }).catch(() => null);
  }
}


// 7J-LEAGUERULESET: public counterpart to the commissioner-editable
// ruleset section — same shared embed builder, so what a prospective
// member sees here always matches what's actually configured.
async function runRecruitmentLeagueInfo(interaction, league) {
  const customSettings = await ensureLeagueCustomSettings(league).catch(() => ({}));
  await interaction.editReply({ embeds: [buildLeagueRulesetEmbed(league, customSettings)] });
}

async function runRecruitmentBrowse(interaction, league) {
  const vacant = await getVacantLeagueTeams(interaction.guild, league);
  if (!vacant.length) { await interaction.editReply({ content: `No open teams in **${league.league_name}** right now — every team role has at least one member.` }); return; }
  // 7J-RECRUITPAGE: a single select menu hard-caps at 25 options, but a
  // league can easily have 30+ team roles (e.g. a full 32-team NFL league).
  // Split across up to 5 select menus (Discord's per-message action-row cap)
  // instead of silently truncating to the first 25 — each menu shares the
  // same customId prefix so the one handler below covers all of them.
  const rows = [];
  for (let i = 0; i < vacant.length && rows.length < 5; i += 25) {
    const chunk = vacant.slice(i, i + 25);
    const menuIndex = rows.length;
    const menu = new StringSelectMenuBuilder()
      .setCustomId(`recruitmentpanel_apply_team_select${menuIndex ? menuIndex : ''}:${league.league_id}`)
      .setPlaceholder(rows.length === 0 && vacant.length <= 25
        ? 'Pick a team to apply for'
        : `Pick a team to apply for (${i + 1}-${Math.min(i + 25, vacant.length)})`)
      .addOptions(chunk.map(t => ({ label: t.role_name.slice(0, 100), value: t.role_id })));
    rows.push(new ActionRowBuilder().addComponents(menu));
  }
  await interaction.editReply({
    content: `**${vacant.length}** open team${vacant.length === 1 ? '' : 's'} in **${league.league_name}**. Pick one to apply:`,
    components: rows,
  });
}

async function runRecruitmentWaitlistJoin(interaction, league) {
  const teams = await getLeagueTeamRoles(league.league_id);
  if (!teams.length) { await interaction.editReply({ content: `**${league.league_name}** doesn't have any team roles set up yet.` }); return; }
  const menu = new StringSelectMenuBuilder()
    .setCustomId(`recruitmentpanel_waitlist_select:${league.league_id}`)
    .setPlaceholder('Pick specific team(s), or leave it as "Any Team"')
    .setMinValues(1)
    .setMaxValues(Math.min(teams.length + 1, 25))
    .addOptions([
      { label: 'Any Team', description: "Notify me when any team opens up", value: '__any__' },
      ...teams.slice(0, 24).map(t => ({ label: t.role_name.slice(0, 100), value: t.role_id })),
    ]);
  await interaction.editReply({
    content: `Join the waitlist for **${league.league_name}**. Pick "Any Team" or one/more specific teams — you'll get a DM when a match opens up.`,
    components: [new ActionRowBuilder().addComponents(menu)],
  });
}

async function runRecruitmentReview(interaction, league) {
  if (!(await memberHasStaff(interaction.member, league))) { await interaction.editReply({ content: 'You need staff permissions to review applications.' }); return; }
  const result = await pool.query(
    `SELECT * FROM league_recruitment_applications WHERE league_id = $1 AND status = 'pending' ORDER BY created_at ASC LIMIT 25`,
    [league.league_id]
  );
  if (!result.rows.length) { await interaction.editReply({ content: `No pending applications for **${league.league_name}**.` }); return; }
  const menu = new StringSelectMenuBuilder()
    .setCustomId('recruitmentpanel_review_select')
    .setPlaceholder('Pick an application to review')
    .addOptions(await Promise.all(result.rows.map(async r => {
      const applicantMember = await interaction.guild.members.fetch(r.applicant_user_id).catch(() => null);
      const applicantName = applicantMember?.user?.username || `User ${r.applicant_user_id}`;
      return {
        label: `${r.team_name} — ${applicantName}`.slice(0, 100),
        description: `Applied ${new Date(r.created_at).toLocaleDateString('en-US')}`,
        value: r.id,
      };
    })));
  await interaction.editReply({ content: `**${result.rows.length}** pending application${result.rows.length === 1 ? '' : 's'} for **${league.league_name}**:`, components: [new ActionRowBuilder().addComponents(menu)] });
}

async function runRecruitmentDiscoverableSettings(interaction, league) {
  if (!(await memberHasStaff(interaction.member, league))) { await interaction.editReply({ content: 'You need staff permissions to change this setting.' }); return; }
  const isOn = Boolean(league.recruitment_discoverable);
  await interaction.editReply({
    content: `**${league.league_name}** is currently **${isOn ? 'discoverable' : 'not discoverable'}** on the cross-server Discover Leagues board.` +
      `${isOn ? '' : ' Same-guild Browse Open Teams still works either way — this only controls whether other servers can find your open teams.'}`,
    components: [new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId(`recruitmentpanel_discoverable_set:${league.league_id}:true`).setLabel('Turn On').setStyle(ButtonStyle.Success).setDisabled(isOn),
      new ButtonBuilder().setCustomId(`recruitmentpanel_discoverable_set:${league.league_id}:false`).setLabel('Turn Off').setStyle(ButtonStyle.Danger).setDisabled(!isOn),
    )],
  });
}

function recruitmentStatusEmoji(status) {
  if (status === 'approved') return '✅';
  if (status === 'declined') return '❌';
  return '⏳';
}

// 7J-90DISCOVERY: shared between the Recruitment panel's Discover Leagues
// button and the /discoverleagues slash command (which is DM-reachable) —
// one implementation, two entry points.
async function buildDiscoverLeaguesPayload(page) {
  const pageSize = 5;
  // Joined against premium_entitlements so a guild that lapses stops
  // appearing here immediately, even if recruitment_discoverable never got
  // cleared for some reason — the toggle alone isn't trusted as the sole
  // gate, since discoverability is a Premium feature.
  const countResult = await pool.query(
    `SELECT COUNT(*)::int AS count FROM leagues l
     JOIN league_settings s ON s.league_id = l.league_id
     JOIN premium_entitlements p ON p.guild_id = l.guild_id
     WHERE l.is_active = TRUE AND s.recruitment_discoverable = TRUE AND p.status IN ('active', 'trialing', 'past_due')`
  );
  const totalLeagues = countResult.rows[0]?.count || 0;
  const leaguesResult = await pool.query(
    `SELECT l.league_id, l.guild_id, l.league_name FROM leagues l
     JOIN league_settings s ON s.league_id = l.league_id
     JOIN premium_entitlements p ON p.guild_id = l.guild_id
     WHERE l.is_active = TRUE AND s.recruitment_discoverable = TRUE AND p.status IN ('active', 'trialing', 'past_due')
     ORDER BY l.league_name ASC LIMIT $1 OFFSET $2`,
    [pageSize, page * pageSize]
  );

  const NL = String.fromCharCode(10);
  const lines = [];
  const openLeagues = [];
  for (const league of leaguesResult.rows) {
    const guild = client.guilds.cache.get(league.guild_id);
    if (!guild) continue; // bot no longer in that server — skip silently
    const vacant = await getVacantLeagueTeams(guild, league);
    // 7J-LEAGUERULESET: per Hxxdie — most players want to join a specific
    // type of league, so showing quarter length/difficulty/sim-comp right
    // here (before even opening a league) saves someone applying to a
    // league that isn't what they're looking for. Only appended when at
    // least one field is actually filled in, so leagues that haven't set
    // this up yet don't get a line full of "Not set."
    const rulesetSettings = await ensureLeagueCustomSettings(league).catch(() => ({}));
    const rulesetBits = [rulesetSettings.quarter_length, rulesetSettings.game_difficulty, rulesetSettings.sim_or_comp].filter(Boolean);
    const rulesetTag = rulesetBits.length ? ` — ${rulesetBits.join(' • ')}` : '';
    lines.push(`**${league.league_name}** — ${guild.name} — ${vacant.length} open team${vacant.length === 1 ? '' : 's'}${rulesetTag}`);
    if (vacant.length) openLeagues.push({ league_id: league.league_id, league_name: league.league_name, guildName: guild.name });
  }

  const embed = new EmbedBuilder()
    .setTitle('🌐 Discover Leagues')
    .setColor(0x57F287)
    .setDescription(lines.length ? lines.join(NL) : 'No leagues to show on this page.')
    .setFooter({ text: `GG Sports • Recruitment • Page ${page + 1} of ${Math.max(1, Math.ceil(totalLeagues / pageSize))}` })
    .setTimestamp();

  const rows = [];
  if (openLeagues.length) {
    rows.push(new ActionRowBuilder().addComponents(
      new StringSelectMenuBuilder()
        .setCustomId('recruitmentpanel_discover_select')
        .setPlaceholder('Pick a league to see open teams')
        .addOptions(openLeagues.map(l => ({ label: l.league_name.slice(0, 100), description: l.guildName.slice(0, 100), value: l.league_id })))
    ));
  }
  rows.push(new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`recruitmentpanel_discover_page:${Math.max(0, page - 1)}`).setLabel('◀ Back').setStyle(ButtonStyle.Secondary).setDisabled(page === 0),
    new ButtonBuilder().setCustomId(`recruitmentpanel_discover_page:${page + 1}`).setLabel('Next ▶').setStyle(ButtonStyle.Secondary).setDisabled((page + 1) * pageSize >= totalLeagues),
  ));

  return { embeds: [embed], components: rows };
}

// 7J-TOURNEYDISCOVERY: per Hxxdie — same shape as buildDiscoverLeaguesPayload
// just above, deliberately: same Premium gate, same pagination, same
// "informational, not an instant cross-server join" approach. A tournament's
// buy-in/prize economy lives in that server's own currency, so joining still
// has to happen there — this is about being found, not about registering
// without ever visiting that server.
async function buildDiscoverTournamentsPayload(page) {
  const pageSize = 5;
  const countResult = await pool.query(
    `SELECT COUNT(*)::int AS count FROM tournaments t
     JOIN premium_entitlements p ON p.guild_id = t.guild_id
     WHERE t.status = 'open' AND t.discoverable = TRUE AND p.status IN ('active', 'trialing', 'past_due')`
  );
  const totalTournaments = countResult.rows[0]?.count || 0;
  const tournamentsResult = await pool.query(
    `SELECT t.* FROM tournaments t
     JOIN premium_entitlements p ON p.guild_id = t.guild_id
     WHERE t.status = 'open' AND t.discoverable = TRUE AND p.status IN ('active', 'trialing', 'past_due')
     ORDER BY t.starts_at_epoch ASC NULLS LAST, t.created_at DESC LIMIT $1 OFFSET $2`,
    [pageSize, page * pageSize]
  );

  const NL = String.fromCharCode(10);
  const lines = [];
  for (const tournament of tournamentsResult.rows) {
    const guild = client.guilds.cache.get(tournament.guild_id);
    if (!guild) continue; // bot no longer in that server — skip silently
    const entryCount = await pool.query(`SELECT COUNT(*)::int AS n FROM tournament_entries WHERE tournament_id = $1`, [tournament.id]).then(r => r.rows[0]?.n || 0).catch(() => 0);
    const slotsBit = tournament.max_entries ? `${entryCount}/${tournament.max_entries} entered` : `${entryCount} entered`;
    const buyInBit = tournament.buy_in > 0 ? `Buy-in ${tournament.buy_in}` : 'Free entry';
    const startBit = tournament.starts_at_epoch ? `<t:${tournament.starts_at_epoch}:R>` : 'Start time TBD';
    lines.push(`**${tournament.tournament_name}** — ${guild.name} — ${slotsBit} • ${buyInBit} • ${startBit}`);
  }

  const embed = new EmbedBuilder()
    .setTitle('🌐 Discover Tournaments')
    .setColor(0x57F287)
    .setDescription(lines.length ? lines.join(NL) : 'No open, discoverable tournaments to show on this page.')
    .setFooter({ text: `GG Sports • Recruitment • Page ${page + 1} of ${Math.max(1, Math.ceil(totalTournaments / pageSize))}` })
    .setTimestamp();

  const rows = [new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`recruitmentpanel_discovertourney_page:${Math.max(0, page - 1)}`).setLabel('◀ Back').setStyle(ButtonStyle.Secondary).setDisabled(page === 0),
    new ButtonBuilder().setCustomId(`recruitmentpanel_discovertourney_page:${page + 1}`).setLabel('Next ▶').setStyle(ButtonStyle.Secondary).setDisabled((page + 1) * pageSize >= totalTournaments),
  )];

  return { embeds: [embed], components: rows };
}

// 7J-90DISCOVERY: called from GuildMemberAdd. Grants any role(s) this
// member has an approved-but-not-yet-granted recruitment application for in
// the server they just joined.
async function grantPendingRecruitmentRolesOnJoin(member) {
  const result = await pool.query(
    `SELECT * FROM league_recruitment_applications WHERE guild_id = $1 AND applicant_user_id = $2 AND status = 'approved' AND role_granted_at IS NULL`,
    [member.guild.id, member.id]
  );
  for (const app of result.rows) {
    const role = member.guild.roles.cache.get(app.team_role_id) || await member.guild.roles.fetch(app.team_role_id).catch(() => null);
    if (!role) continue;
    if (role.members.filter(m => !m.user.bot).size > 0) {
      // Team got filled by someone else while this applicant was still
      // outside the server — nothing to grant now, just close it out.
      await pool.query(`UPDATE league_recruitment_applications SET decision_note = COALESCE(decision_note, '') || ' (team filled before they joined)' WHERE id = $1`, [app.id]);
      continue;
    }
    await member.roles.add(role).catch(err => console.error('[Recruitment] grantPendingRecruitmentRolesOnJoin role add failed:', err?.message));
    // League role too, same pairing as the immediate-approval path.
    const league = await getLeagueById(app.league_id).catch(() => null);
    if (league?.league_role_id) {
      await member.roles.add(league.league_role_id).catch(err => console.error('[Recruitment] grantPendingRecruitmentRolesOnJoin league role add failed:', err?.message));
    }
    // 7J-COMMANDHUB-TEAMOWNERSYNC: same as the immediate-approval path —
    // this is always a team role, so refresh the panel now that the owner
    // has actually joined and received it.
    if (league) await updateTeamOwnersPanel(member.guild, league).catch(() => null);
    await pool.query(`UPDATE league_recruitment_applications SET role_granted_at = NOW() WHERE id = $1`, [app.id]);
    await member.send({ content: `🎉 Welcome! Your **${role.name}** team role from your approved recruitment application has been assigned.` }).catch(() => null);
  }
}

async function buildBankHomeEmbed(guild, targetUser) {
  const settings = await getCurrencySettings(guild.id);
  const balance = await getBalance(guild.id, targetUser.id);
  return new EmbedBuilder()
    .setTitle(`🏦 ${targetUser.username} • Bank`)
    .setColor(0xFEE75C)
    .setThumbnail(targetUser.displayAvatarURL({ dynamic: true }))
    .addFields(
      { name: 'Balance', value: `${settings.currency_icon} ${balance.balance}`, inline: true },
      { name: 'All-Time Earned', value: `${settings.currency_icon} ${balance.lifetime_earned}`, inline: true },
      { name: 'All-Time Spent', value: `${settings.currency_icon} ${balance.lifetime_spent}`, inline: true },
    )
    .setFooter({ text: 'GG Sports • Bank' })
    .setTimestamp();
}

function buildBankHomeComponents() {
  const row = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('bankpanel_transfer').setLabel('Transfer Currency').setEmoji('💸').setStyle(ButtonStyle.Primary),
    new ButtonBuilder().setCustomId('bankpanel_purchases').setLabel('Recent Purchases').setEmoji('🛍️').setStyle(ButtonStyle.Secondary),
    new ButtonBuilder().setCustomId('bankpanel_transactions').setLabel('Transaction History').setEmoji('📜').setStyle(ButtonStyle.Secondary),
  );
  return [row];
}

async function showBankHome(interaction, targetUser, { update = false } = {}) {
  const embed = await buildBankHomeEmbed(interaction.guild, targetUser);
  const payload = { content: null, embeds: [embed], components: buildBankHomeComponents() };
  return update ? interaction.update(payload) : interaction.reply({ ...payload, ephemeral: true });
}

async function buildBankPurchasesEmbed(guild, targetUser) {
  const settings = await getCurrencySettings(guild.id);
  const result = await pool.query(
    `SELECT * FROM user_inventory WHERE user_id = $1 ORDER BY purchased_at DESC LIMIT 15`,
    [targetUser.id]
  );
  return new EmbedBuilder()
    .setTitle(`${targetUser.username} • Recent Purchases`)
    .setColor(0xFEE75C)
    .setDescription(result.rows.length
      ? result.rows.map(row => `**${row.item_name}** — ${settings.currency_icon} ${row.price_paid} • ${row.status}`).join('\n')
      : 'No purchases found yet.')
    .setFooter({ text: 'GG Sports • Bank' })
    .setTimestamp();
}

async function buildBankTransactionsEmbed(guild, targetUser) {
  const settings = await getCurrencySettings(guild.id);
  const result = await pool.query(
    `SELECT * FROM currency_transactions WHERE guild_id = $1 AND user_id = $2 ORDER BY created_at DESC LIMIT 15`,
    [guild.id, targetUser.id]
  );
  return new EmbedBuilder()
    .setTitle(`${targetUser.username} • Transaction History`)
    .setColor(0xFEE75C)
    .setDescription(result.rows.length
      ? result.rows.map(row => `${row.amount >= 0 ? '+' : ''}${row.amount} ${settings.currency_icon} • ${row.type}${row.reason ? ' • ' + row.reason : ''}`).join('\n')
      : 'No transactions found yet.')
    .setFooter({ text: 'GG Sports • Bank' })
    .setTimestamp();
}

async function getExpandedUserBadges(guildId, userId, recognition = null) {
  await syncExpandedProfileBadges(guildId, userId, recognition).catch(() => null);
  const result = await pool.query(
    `SELECT * FROM user_badges WHERE guild_id = $1 AND user_id = $2 ORDER BY unlocked_at ASC LIMIT 20`,
    [guildId, userId]
  );
  return result.rows;
}

function formatBadgeLine(badge) {
  return badge.badge_icon + ' **' + badge.badge_label + '**' + (badge.description ? ' — ' + badge.description : '');
}

function buildBadgesEmbed(user, badges) {
  const NL = String.fromCharCode(10);
  return new EmbedBuilder()
    .setTitle(user.username + ' Badges')
    .setColor(0xFEE75C)
    .setThumbnail(user.displayAvatarURL({ dynamic: true }))
    .setDescription(badges.length ? badges.map(formatBadgeLine).join(NL).slice(0, 4096) : 'No badges unlocked yet.')
    .setFooter({ text: 'GG Sports • Badges' })
    .setTimestamp();
}

function buildBadgeProgressEmbed(user, recognition = {}) {
  const championships = Number(recognition.championships || 0);
  const sportsbookWins = Number(recognition.sportsbook_wins || 0);
  const sportsbookProfit = Number(recognition.sportsbook_profit || 0);
  const ticketsResolved = Number(recognition.tickets_resolved || 0);
  const gamesPlayed = Number(recognition.games_played || 0);

  const lines = [
    '🏆 Champion: ' + Math.min(championships, 1) + '/1 championship',
    '👑 Dynasty: ' + Math.min(championships, 5) + '/5 championships',
    '🎰 Sportsbook Winner: ' + Math.min(sportsbookWins, 1) + '/1 win',
    '🎯 Sharp Bettor: ' + Math.min(sportsbookWins, 10) + '/10 wins',
    '💰 High Roller: ' + Math.min(sportsbookProfit, 10000) + '/10000 profit',
    '🛠️ Ticket Helper: ' + Math.min(ticketsResolved, 10) + '/10 tickets',
    '🎮 League Grinder: ' + Math.min(gamesPlayed, 25) + '/25 games',
  ];

  return new EmbedBuilder()
    .setTitle(user.username + ' Badge Progress')
    .setColor(0x5865F2)
    .setDescription(lines.join(String.fromCharCode(10)))
    .setFooter({ text: 'GG Sports • Badge Progress' })
    .setTimestamp();
}



