function maddenWeekSortValue(weekLabel) {
  const label = String(weekLabel || '').toLowerCase();
  const n = Number((label.match(/\d+/) || [999])[0]);
  if (label.includes('preseason')) return n - 100;
  // 7J-DIVPLAYOFFFIX3: per Hxxdie — same root cause as
  // maddenWeekLabelSortKey (see 7J-DIVPLAYOFFFIX). 'wildcard' (no space)
  // never matched the real "Wild Card" label (which has a space), and
  // 'divisional' never matched the real "Div. Playoff" label — both fell
  // through to the final `return 999` fallback, identical to an
  // unclassified garbage label, which broke any chronological sort relying
  // on this function for playoff-week games. Numeric scale intentionally
  // unchanged (100/101/102/103) — several call sites compare this against
  // raw regular-season week numbers via >= 4 / >= 8, so only the matching
  // needed fixing, not the value scheme.
  if (label.includes('wild card')) return 100;
  if (label.includes('super bowl')) return 103;
  if (label.includes('div')) return 101; // "Divisional", "Div. Playoff", etc.
  if (label.includes('conf')) return 102; // "Conference Championship", "Conf. Championship", etc.
  if (label.includes('championship')) return 103;
  if (label.includes('week')) return n;
  return 999;
}


function normalizeMaddenWeekFilterInput(week) {
  if (!week) return null;
  const value = String(week).trim();
  if (!value) return null;

  const compact = value.toLowerCase().replace(/\s+/g, '');
  const numberOnly = compact.match(/^\d+$/);
  if (numberOnly) return 'Week ' + value;

  const weekNumber = compact.match(/^week(\d+)$/);
  if (weekNumber) return 'Week ' + weekNumber[1];

  const preseasonNumber = compact.match(/^preseason(?:week)?(\d+)$/);
  if (preseasonNumber) return 'Preseason Week ' + preseasonNumber[1];

  return value.replace(/^week\s*(\d+)$/i, 'Week $1').replace(/^preseason\s*week\s*(\d+)$/i, 'Preseason Week $1');
}



function formatMaddenGameScore(game) {
  const away = game.away_score;
  const home = game.home_score;
  const hasScore = away !== null && away !== undefined && home !== null && home !== undefined;
  if (!hasScore) return '';

  const awayNum = Number(away);
  const homeNum = Number(home);
  const realScore = awayNum !== 0 || homeNum !== 0 || String(game.status || '').toLowerCase() === 'completed_with_real_score';
  if (!realScore) return '';

  return ' • ' + away + '-' + home;
}



function getMaddenDivisionSortRank(divisionName) {
  const order = [
    'AFC East', 'AFC North', 'AFC South', 'AFC West',
    'NFC East', 'NFC North', 'NFC South', 'NFC West',
  ];
  const idx = order.findIndex(item => item.toLowerCase() === String(divisionName || '').toLowerCase());
  return idx === -1 ? 999 : idx;
}

function getMaddenConferenceSortRank(conferenceName) {
  const conf = String(conferenceName || '').toUpperCase();
  if (conf === 'AFC') return 1;
  if (conf === 'NFC') return 2;
  return 999;
}

function inferMaddenConferenceFromDivision(divisionName) {
  const div = String(divisionName || '');
  if (/^AFC/i.test(div)) return 'AFC';
  if (/^NFC/i.test(div)) return 'NFC';
  return 'League';
}

function getMaddenDivisionForTeam(teamName) {
  const name = String(teamName || '').toLowerCase();
  const map = {
    'bills': 'AFC East',
    'dolphins': 'AFC East',
    'patriots': 'AFC East',
    'jets': 'AFC East',

    'ravens': 'AFC North',
    'bengals': 'AFC North',
    'browns': 'AFC North',
    'steelers': 'AFC North',

    'texans': 'AFC South',
    'colts': 'AFC South',
    'jaguars': 'AFC South',
    'titans': 'AFC South',

    'broncos': 'AFC West',
    'chiefs': 'AFC West',
    'raiders': 'AFC West',
    'chargers': 'AFC West',

    'cowboys': 'NFC East',
    'giants': 'NFC East',
    'eagles': 'NFC East',
    'commanders': 'NFC East',

    'bears': 'NFC North',
    'lions': 'NFC North',
    'packers': 'NFC North',
    'vikings': 'NFC North',

    'falcons': 'NFC South',
    'panthers': 'NFC South',
    'saints': 'NFC South',
    'buccaneers': 'NFC South',

    'cardinals': 'NFC West',
    'rams': 'NFC West',
    '49ers': 'NFC West',
    'seahawks': 'NFC West',
  };

  for (const [key, division] of Object.entries(map)) {
    if (name === key || name.includes(key)) return division;
  }

  return 'League';
}

function getMaddenConferenceForTeam(teamName) {
  return inferMaddenConferenceFromDivision(getMaddenDivisionForTeam(teamName));
}


function formatMaddenStandingsRecord(team) {
  const wins = Number(team.wins || 0);
  const losses = Number(team.losses || 0);
  const ties = Number(team.ties || 0);
  return ties ? `${wins}-${losses}-${ties}` : `${wins}-${losses}`;
}

function sortMaddenStandingRows(rows) {
  return [...(rows || [])].sort((a, b) =>
    Number(b.wins || 0) - Number(a.wins || 0) ||
    Number(a.losses || 0) - Number(b.losses || 0) ||
    (Number(b.points_for || 0) - Number(b.points_against || 0)) - (Number(a.points_for || 0) - Number(a.points_against || 0)) ||
    Number(b.points_for || 0) - Number(a.points_for || 0) ||
    String(a.team_name || '').localeCompare(String(b.team_name || ''))
  );
}

function formatMaddenStandingLine(team, index) {
  const pf = Number(team.points_for || 0);
  const pa = Number(team.points_against || 0);
  const diff = pf - pa;
  const seed = team.seed ? `${team.seed}. ` : `${index + 1}. `;
  const rank = team.rank ? ` • Rank #${team.rank}` : '';
  const teamDisplay = maddenTeamDisplayNameWithLogo(team.team_name);
  return `**${seed}${teamDisplay}** — ${formatMaddenStandingsRecord(team)} • PF ${pf} • PA ${pa} • DIFF ${diff >= 0 ? '+' : ''}${diff}${rank}`;
}


function formatMaddenPowerMovement(row) {
  const currentRank = Number(row.rank || 0);
  const previousRank = row.previous_rank == null ? null : Number(row.previous_rank || 0);
  if (!previousRank || !currentRank) return 'NEW';
  const movement = previousRank - currentRank;
  if (movement > 0) return '▲ +' + movement;
  if (movement < 0) return '▼ ' + movement;
  return '—';
}

function formatMaddenPowerScore(value) {
  const n = Number(value || 0);
  if (!Number.isFinite(n)) return '0';
  return n.toFixed(1).replace(/\.0$/, '');
}

async function recalculateMaddenPowerRankings(guildId, leagueId) {
  const previousResult = await pool.query(
    `SELECT team_name, rank
     FROM madden_power_rankings
     WHERE league_id::text = $1::text`,
    [leagueId]
  );
  const previousRanks = new Map(previousResult.rows.map(row => [String(row.team_name || '').toLowerCase(), Number(row.rank || 0)]));

  const result = await pool.query(
    `WITH base AS (
       SELECT
         team_name,
         wins,
         losses,
         ties,
         points_for,
         points_against,
         GREATEST(COALESCE(NULLIF(scored_games, 0), wins + losses + ties), 1) AS games_played
       FROM madden_imported_team_stats
       WHERE guild_id = $1::text
         AND league_id::text = $2::text
     ), ranked AS (
       SELECT
         *,
         (points_for - points_against) AS point_diff,
         DENSE_RANK() OVER (ORDER BY (points_for::numeric / games_played::numeric) DESC) AS offense_rank,
         DENSE_RANK() OVER (ORDER BY (points_against::numeric / games_played::numeric) ASC) AS defense_rank
       FROM base
     ), scored AS (
       SELECT
         *,
         ((wins * 100)
          + ((points_for - points_against) * 3)
          + ((33 - offense_rank) * 5)
          + ((33 - defense_rank) * 5))::numeric AS power_score
       FROM ranked
     )
     SELECT *
     FROM scored
     ORDER BY power_score DESC, wins DESC, losses ASC, point_diff DESC, points_for DESC, team_name ASC`,
    [guildId, leagueId]
  );

  const rankings = result.rows.map((row, index) => ({
    ...row,
    rank: index + 1,
    previous_rank: previousRanks.get(String(row.team_name || '').toLowerCase()) || null,
  }));

  for (const row of rankings) {
    await pool.query(
      `INSERT INTO madden_power_rankings (league_id, team_name, rank, previous_rank, power_score, updated_at)
       VALUES ($1, $2, $3, $4, $5, NOW())
       ON CONFLICT (league_id, team_name)
       DO UPDATE SET
         rank = EXCLUDED.rank,
         previous_rank = EXCLUDED.previous_rank,
         power_score = EXCLUDED.power_score,
         updated_at = NOW()`,
      [leagueId, row.team_name, row.rank, row.previous_rank, row.power_score]
    );
  }

  return rankings;
}

function buildMaddenPowerRankingsEmbed(league, rankings) {
  const NL = String.fromCharCode(10);

  if (!rankings?.length) {
    return new EmbedBuilder()
      .setTitle('🏆 Madden Power Rankings • ' + league.league_name)
      .setColor(0xFEE75C)
      .setDescription('No imported Madden team stats found yet. Run Operations → Run Sync first, then try `/madden powerrankings`.')
      .setFooter({ text: 'GG Sports • 7J-7ZQ-R Power Rankings' })
      .setTimestamp();
  }

  const lines = rankings.map(row => {
    const wins = Number(row.wins || 0);
    const losses = Number(row.losses || 0);
    const ties = Number(row.ties || 0);
    const record = ties ? `${wins}-${losses}-${ties}` : `${wins}-${losses}`;
    const diff = Number(row.point_diff || 0);
    const diffText = diff >= 0 ? '+' + diff : String(diff);
    const teamDisplay = maddenTeamDisplayNameWithLogo(row.team_name);
    return `**${row.rank}. ${teamDisplay}** (${record}) — ${formatMaddenPowerMovement(row)}\nScore ${formatMaddenPowerScore(row.power_score)} • DIFF ${diffText} • OFF #${row.offense_rank || 'N/A'} • DEF #${row.defense_rank || 'N/A'}`;
  });

  return new EmbedBuilder()
    .setTitle(`${GG_EMOJI} Madden Power Rankings • ${league.league_name}`)
    .setColor(0xFEE75C)
    .setDescription(lines.join(NL + NL).slice(0, 4096))
    .setFooter({ text: 'GG Sports • 7J-7ZQ-R Power Rankings' })
    .setTimestamp();
}


function maddenTeamNameMatches(candidate, target) {
  const c = String(candidate || '').trim().toLowerCase();
  const t = String(target || '').trim().toLowerCase();
  if (!c || !t) return false;
  const cAbbr = String(getMaddenTeamAbbrev(candidate) || '').trim().toLowerCase();
  const tAbbr = String(getMaddenTeamAbbrev(target) || '').trim().toLowerCase();
  return c === t || (!!cAbbr && cAbbr === t) || (!!tAbbr && c === tAbbr) || (!!cAbbr && !!tAbbr && cAbbr === tAbbr);
}

function maddenRecordWinPct(row) {
  const wins = Number(row?.wins || 0);
  const losses = Number(row?.losses || 0);
  const ties = Number(row?.ties || 0);
  const games = wins + losses + ties;
  return games > 0 ? (wins + (ties * 0.5)) / games : 0;
}

// 7J-47PPG: was wins+losses+ties — see the schema comment on scored_games
// above for why that's wrong specifically for PPG/PAPG math (it counts
// games with no real score, which contribute 0 to points_for/points_against
// but still inflated this denominator). Falls back to wins+losses+ties only
// for rows that haven't been through a sync since this fix shipped yet
// (scored_games would be 0/stale) — self-heals on the next sync.
function maddenTeamGamesPlayed(row) {
  const scoredGames = Number(row?.scored_games || 0);
  if (scoredGames > 0) return scoredGames;
  return Math.max(1, Number(row?.wins || 0) + Number(row?.losses || 0) + Number(row?.ties || 0));
}

function formatMaddenOneDecimal(value) {
  const n = Number(value || 0);
  if (!Number.isFinite(n)) return '0.0';
  return n.toFixed(1);
}

async function getMaddenImportedTeamRow(guildId, leagueId, teamName) {
  const result = await pool.query(
    `SELECT *
     FROM madden_imported_team_stats
     WHERE guild_id = $1::text
       AND league_id::text = $2::text
       AND (
         LOWER(team_name) = LOWER($3)
         OR LOWER(team_name) = LOWER($4)
       )
     LIMIT 1`,
    [guildId, leagueId, teamName, getMaddenTeamAbbrev(teamName)]
  );
  return result.rows?.[0] || null;
}

async function getMaddenTeamSeasonLeader(guildId, leagueId, teamName, categoryKey) {
  const result = await getMaddenLeagueLeaders(guildId, leagueId, categoryKey, null, 250).catch(() => ({ rows: [] }));
  return (result.rows || []).find(row => maddenTeamNameMatches(row.resolved_team_name || row.stat_team_name || row.team_name, teamName)) || null;
}

function formatMaddenMatchupLeader(row, statLabel = 'Yards', fallback = 'No data') {
  if (!row) return fallback;
  const team = getMaddenTeamAbbrev(row.resolved_team_name || row.stat_team_name || row.team_name);
  const position = row.position ? String(row.position).toUpperCase() : '';
  const meta = [team, position].filter(Boolean).join('\n');
  const value = row.leader_value != null ? formatMaddenLeaderNumber(row.leader_value) + ' ' + statLabel : 'No stat';
  return `**${row.player_name || 'Unknown'}**${meta ? ` (${meta})` : ''}\n${value}`;
}

