// 7J-MULTISPORTLOGO: single dispatcher used by the rest of the codebase —
// picks the right slug table by league sport (falling back through Madden's
// existing NFL table for non-Madden NFL-style leagues too) so callers don't
// need to know which table to use themselves.
function getGenericTeamLogoUrl(teamName, league) {
  if (!teamName) return null;
  if (isNhlLeague(league)) {
    const slug = NHL_TEAM_LOGO_SLUGS[teamName];
    return slug ? `https://a.espncdn.com/i/teamlogos/nhl/500/${slug}.png` : null;
  }
  if (isNbaLeague(league)) {
    const slug = NBA_TEAM_LOGO_SLUGS[teamName];
    return slug ? `https://a.espncdn.com/i/teamlogos/nba/500/${slug}.png` : null;
  }
  if (isMlbLeague(league)) {
    const slug = MLB_TEAM_LOGO_SLUGS[teamName];
    return slug ? `https://a.espncdn.com/i/teamlogos/mlb/500/${slug}.png` : null;
  }
  if (isNflLeague(league)) {
    return getMaddenTeamLogoUrl(teamName);
  }
  return null;
}

// 7J-MULTISPORTLOGO: composites real team logos (fetched live from ESPN's
// CDN at render time — this bot already makes outbound fetch() calls
// elsewhere, e.g. Stripe/EA Direct, so this is the same kind of network
// access, not new infrastructure) into a single labeled grid image via
// sharp, the same rendering approach as the tournament/playoff brackets.
// Built specifically to solve the Active Check "logos" gap: Discord embed
// fields can only hold text, and true inline emoji-logos would require
// actually uploading each one as a real custom Discord emoji to the guild
// (an entirely separate, one-time asset-provisioning step this function
// does not attempt) — rendering a real image instead sidesteps that
// limitation and works immediately for any team in any of these leagues,
// no per-server emoji setup required.
// 7J-MULTISPORTLOGO-EVERYWHERE: per Hxxdie — same idea as the Active Check
// grid, applied to an ORDERED list (standings/power-ranking position
// matters here, unlike Active Check's two unordered groups). Wraps to
// multiple rows for a full 30+ team league instead of one very wide image.
// 7J-STANDINGSLOGOCONF: now accepts an optional third `options.groups` param
// — an array of { label, teams: [{ name, rank }] } — to render separate
// labeled sections (e.g. Eastern/Western Conference) side by side
// horizontally, each independently wrapped and ranked, so the image stays a
// compact strip instead of growing tall. When omitted, behavior is
// unchanged: `orderedTeamNames` renders as a single unlabeled group ranked
// 1..N in the order given (existing Power Rankings/Active-Check-adjacent
// callers are untouched).
async function renderTeamLogoStripPng(league, orderedTeamNames = [], options = {}) {
  const sharp = await getSharp();
  if (!sharp) return null;

  const rawGroups = options.groups && options.groups.length
    ? options.groups
    : (orderedTeamNames.length ? [{ label: null, teams: orderedTeamNames.slice(0, 30).map((name, i) => ({ name, rank: i + 1 })) }] : []);
  if (!rawGroups.length) return null;

  const logoSize = 44;
  const gap = 14;
  const marginLeft = 16;
  const marginTop = 28;
  const groupLabelHeight = 30;
  const groupGapX = 28;
  // Side-by-side groups get a tighter per-group wrap (fewer columns each)
  // so multiple conferences/divisions fit next to each other instead of
  // stacking the image tall — a single ungrouped strip keeps the wider
  // 10-per-row layout it always had.
  const perRow = rawGroups.length > 1 ? 8 : 10;
  const cellW = logoSize + gap;
  const cellH = logoSize + 22;

  async function fetchLogoBuffer(teamName) {
    const url = getGenericTeamLogoUrl(teamName, league);
    if (!url) return null;
    try {
      const res = await fetch(url);
      if (!res.ok) return null;
      const arrayBuffer = await res.arrayBuffer();
      return await sharp(Buffer.from(arrayBuffer)).resize(logoSize, logoSize, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }).png().toBuffer();
    } catch {
      return null;
    }
  }

  const resolvedGroups = await Promise.all(rawGroups.map(async group => {
    const capped = (group.teams || []).slice(0, 30);
    const logos = await Promise.all(capped.map(t => fetchLogoBuffer(t.name)));
    const present = logos.map((buf, i) => (buf ? { buf, rank: capped[i].rank } : null)).filter(Boolean);
    return { label: group.label, present };
  }));
  const nonEmptyGroups = resolvedGroups.filter(g => g.present.length);
  if (!nonEmptyGroups.length) return null;

  const showLabels = nonEmptyGroups.some(g => g.label);

  // Lay groups out left to right. Each group's own width is driven by its
  // own column count (capped at perRow); each group's own height is driven
  // by its own row count — the overall canvas height is just the tallest
  // group, so adding a second conference widens the image, not heightens it.
  const groupLayouts = nonEmptyGroups.map(group => {
    const cols = Math.min(perRow, group.present.length);
    const rowCount = Math.ceil(group.present.length / perRow);
    const blockWidth = marginLeft * 2 + cols * cellW;
    const blockHeight = (showLabels && group.label ? groupLabelHeight : 0) + marginTop + rowCount * cellH;
    return { ...group, cols, rowCount, blockWidth, blockHeight };
  });

  const width = groupLayouts.reduce((w, g, i) => w + g.blockWidth + (i > 0 ? groupGapX : 0), 0);
  const height = Math.max(...groupLayouts.map(g => g.blockHeight));

  const svgParts = [];
  const composites = [];
  let x0 = 0;
  groupLayouts.forEach((group, gi) => {
    if (gi > 0) x0 += groupGapX;
    let y0 = 0;
    if (showLabels) {
      const labelText = group.label || 'Other';
      svgParts.push(`<text x="${x0 + marginLeft}" y="${y0 + 20}" font-family="DejaVu Sans" font-size="16" font-weight="bold" fill="#dcddde">${tournamentBracketEscapeXml(labelText)}</text>`);
      y0 += groupLabelHeight;
    }
    group.present.forEach((entry, i) => {
      const col = i % perRow;
      const row = Math.floor(i / perRow);
      const x = x0 + marginLeft + col * cellW;
      const y = y0 + marginTop + row * cellH;
      svgParts.push(`<text x="${x + logoSize / 2}" y="${y - 8}" font-family="DejaVu Sans" font-size="13" font-weight="bold" fill="#949ba4" text-anchor="middle">#${entry.rank}</text>`);
      composites.push({ input: entry.buf, left: x, top: y });
    });
    x0 += group.blockWidth;
  });

  const labelSvg = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">${svgParts.join('')}</svg>`;

  return sharp({ create: { width, height, channels: 4, background: { r: 30, g: 31, b: 34, alpha: 1 } } })
    .composite([{ input: Buffer.from(labelSvg) }, ...composites])
    .png()
    .toBuffer();
}

async function renderTeamLogoGridPng(league, respondedTeams = [], pendingTeams = []) {
  const sharp = await getSharp();
  if (!sharp) return null;

  const logoSize = 48;
  const gap = 10;
  const marginLeft = 16;
  const rowLabelHeight = 26;
  const rowGap = 20;

  async function fetchLogoBuffer(teamName) {
    const url = getGenericTeamLogoUrl(teamName, league);
    if (!url) return null;
    try {
      const res = await fetch(url);
      if (!res.ok) return null;
      const arrayBuffer = await res.arrayBuffer();
      return await sharp(Buffer.from(arrayBuffer)).resize(logoSize, logoSize, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } }).png().toBuffer();
    } catch {
      return null;
    }
  }

  async function buildRow(teams) {
    const buffers = await Promise.all(teams.slice(0, 20).map(fetchLogoBuffer));
    return buffers.filter(Boolean);
  }

  const [respondedLogos, pendingLogos] = await Promise.all([buildRow(respondedTeams), buildRow(pendingTeams)]);
  if (!respondedLogos.length && !pendingLogos.length) return null;

  const maxPerRow = Math.max(1, respondedLogos.length, pendingLogos.length);
  const width = marginLeft * 2 + maxPerRow * logoSize + Math.max(0, maxPerRow - 1) * gap;
  const rows = [
    { label: `Responded (${respondedLogos.length})`, logos: respondedLogos },
    { label: `Still to check in (${pendingLogos.length})`, logos: pendingLogos },
  ].filter(r => r.logos.length);
  const height = rows.reduce((h, r) => h + rowLabelHeight + logoSize, 0) + Math.max(0, rows.length - 1) * rowGap + 12;

  const labelSvgParts = [];
  let y = 12;
  const composites = [];
  for (const row of rows) {
    labelSvgParts.push(`<text x="${marginLeft}" y="${y + 16}" font-family="DejaVu Sans" font-size="15" font-weight="bold" fill="#dcddde">${tournamentBracketEscapeXml(row.label)}</text>`);
    const logoY = y + rowLabelHeight;
    row.logos.forEach((logoBuf, i) => {
      composites.push({ input: logoBuf, left: marginLeft + i * (logoSize + gap), top: logoY });
    });
    y += rowLabelHeight + logoSize + rowGap;
  }

  const labelSvg = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">${labelSvgParts.join('')}</svg>`;

  return sharp({ create: { width, height, channels: 4, background: { r: 30, g: 31, b: 34, alpha: 1 } } })
    .composite([{ input: Buffer.from(labelSvg) }, ...composites])
    .png()
    .toBuffer();
}

