function buildMaddenMatchupStoryline(homeName, awayName, home, away, homePower, awayPower) {
  const homeWins = Number(home?.wins || 0);
  const homeLosses = Number(home?.losses || 0);
  const awayWins = Number(away?.wins || 0);
  const awayLosses = Number(away?.losses || 0);
  const homeRank = Number(homePower?.rank || 0);
  const awayRank = Number(awayPower?.rank || 0);
  if (homeLosses === 0 && awayLosses === 0) return 'Two unbeaten teams collide with early-season positioning on the line.';
  if (homeWins === 0 && awayWins === 0) return 'Both teams are chasing their first win and a chance to reset the season.';
  if (homeWins === 0) return `${homeName} looks to avoid a deeper slide while ${awayName} tries to take care of business.`;
  if (awayWins === 0) return `${awayName} looks to avoid a deeper slide while ${homeName} tries to take care of business.`;
  if (homeRank && awayRank && Math.abs(homeRank - awayRank) <= 5) return 'A tight power-ranking matchup that could swing the league picture.';
  const favorite = homeRank && awayRank ? (homeRank < awayRank ? homeName : awayName) : null;
  return favorite ? `${favorite} enters with the stronger profile, but the numbers still leave upset potential.` : 'A key matchup with playoff-picture momentum already starting to build.';
}

function getMaddenMatchupTeamScore(team, powerRow) {
  const pointDiff = Number(team?.points_for || 0) - Number(team?.points_against || 0);
  // 7J-47PPG: was a local wins+losses+ties recomputation — same bug as
  // maddenTeamGamesPlayed, and this feeds the actual prediction/win-
  // probability score shown in the matchup preview, so it's not just a
  // display issue here.
  const games = maddenTeamGamesPlayed(team);
  const winPct = maddenRecordWinPct(team);
  const offenseRank = Number(powerRow?.offense_rank || 33);
  const defenseRank = Number(powerRow?.defense_rank || 33);
  return (winPct * 100) + ((pointDiff / games) * 6) + ((33 - offenseRank) * 4) + ((33 - defenseRank) * 4);
}

function getMaddenProjectedScore(team, opponent, teamScore, opponentScore) {
  const games = maddenTeamGamesPlayed(team);
  const oppGames = maddenTeamGamesPlayed(opponent);
  const ppg = Number(team?.points_for || 0) / games;
  const oppPapg = Number(opponent?.points_against || 0) / oppGames;
  const base = (ppg + oppPapg) / 2;
  const edge = Math.max(-10, Math.min(10, (teamScore - opponentScore) / 12));
  return Math.max(10, Math.round(base + edge));
}

async function getMaddenMatchupPreviewData(guildId, leagueId, homeTeamName, awayTeamName) {
  const [home, away, rankings] = await Promise.all([
    getMaddenImportedTeamRow(guildId, leagueId, homeTeamName),
    getMaddenImportedTeamRow(guildId, leagueId, awayTeamName),
    recalculateMaddenPowerRankings(guildId, leagueId).catch(() => []),
    getMaddenAwardsRace(guildId, leagueId, 'mvp', 1).catch(() => []),
    getMaddenAwardsRace(guildId, leagueId, 'oroy', 1).catch(() => []),
    getMaddenAwardsRace(guildId, leagueId, 'droy', 1).catch(() => []),
  ]);

  const homeName = home?.team_name || homeTeamName;
  const awayName = away?.team_name || awayTeamName;
  const homePower = (rankings || []).find(row => maddenTeamNameMatches(row.team_name, homeName)) || null;
  const awayPower = (rankings || []).find(row => maddenTeamNameMatches(row.team_name, awayName)) || null;

  const [homeQB, awayQB, homeRB, awayRB, homeWR, awayWR] = await Promise.all([
    getMaddenTeamSeasonLeader(guildId, leagueId, homeName, 'passing'),
    getMaddenTeamSeasonLeader(guildId, leagueId, awayName, 'passing'),
    getMaddenTeamSeasonLeader(guildId, leagueId, homeName, 'rushing'),
    getMaddenTeamSeasonLeader(guildId, leagueId, awayName, 'rushing'),
    getMaddenTeamSeasonLeader(guildId, leagueId, homeName, 'receiving'),
    getMaddenTeamSeasonLeader(guildId, leagueId, awayName, 'receiving'),
  ]);

  const homeScore = getMaddenMatchupTeamScore(home, homePower);
  const awayScore = getMaddenMatchupTeamScore(away, awayPower);
  const projectedHome = getMaddenProjectedScore(home, away, homeScore, awayScore);
  const projectedAway = getMaddenProjectedScore(away, home, awayScore, homeScore);
  const totalScore = Math.max(1, homeScore + awayScore);
  const homeProb = Math.max(5, Math.min(95, Math.round((homeScore / totalScore) * 100)));
  const awayProb = 100 - homeProb;

  return {
    home,
    away,
    homePower,
    awayPower,
    leaders: { homeQB, awayQB, homeRB, awayRB, homeWR, awayWR },
    prediction: { projectedHome, projectedAway, homeProb, awayProb, homeScore, awayScore },
  };
}

function buildMaddenMatchupPreviewEmbed(league, matchup) {
  const home = matchup.home;
  const away = matchup.away;
  const homeGames = maddenTeamGamesPlayed(home);
  const awayGames = maddenTeamGamesPlayed(away);
  const homePf = Number(home.points_for || 0);
  const homePa = Number(home.points_against || 0);
  const awayPf = Number(away.points_for || 0);
  const awayPa = Number(away.points_against || 0);
  const homeDiff = homePf - homePa;
  const awayDiff = awayPf - awayPa;
  const homeName = home.team_name;
  const awayName = away.team_name;
  const homeLogo = getMaddenTeamLogoUrl(homeName);
  const awayLogo = getMaddenTeamLogoUrl(awayName);
  const favorite = matchup.prediction.projectedHome === matchup.prediction.projectedAway
    ? 'Even matchup'
    : (matchup.prediction.projectedHome > matchup.prediction.projectedAway ? homeName : awayName);
  const storyline = buildMaddenMatchupStoryline(homeName, awayName, home, away, matchup.homePower, matchup.awayPower);

  const embed = new EmbedBuilder()
    .setTitle(`${GG_EMOJI} Madden Matchup Preview • ${league.league_name || 'Madden League'}`)
    .setColor(0x5865F2)
    .setDescription(`**${getMaddenTeamEmoji(awayName) || ''} ${awayName} vs ${getMaddenTeamEmoji(homeName) || ''} ${homeName}**\n${storyline}`)
    .addFields(
      { name: 'Record', value: `${formatMaddenStandingsRecord(away)} vs ${formatMaddenStandingsRecord(home)}`, inline: true },
      { name: 'PPG', value: `${formatMaddenOneDecimal(awayPf / awayGames)} vs ${formatMaddenOneDecimal(homePf / homeGames)}`, inline: true },
      { name: 'PAPG', value: `${formatMaddenOneDecimal(awayPa / awayGames)} vs ${formatMaddenOneDecimal(homePa / homeGames)}`, inline: true },
      { name: 'Point Differential', value: `${awayDiff >= 0 ? '+' : ''}${awayDiff} vs ${homeDiff >= 0 ? '+' : ''}${homeDiff}`, inline: true },
      { name: 'Power Rank', value: `#${matchup.awayPower?.rank || 'N/A'} vs #${matchup.homePower?.rank || 'N/A'}`, inline: true },
      { name: 'Off / Def Rank', value: `OFF #${matchup.awayPower?.offense_rank || 'N/A'} • DEF #${matchup.awayPower?.defense_rank || 'N/A'}\nOFF #${matchup.homePower?.offense_rank || 'N/A'} • DEF #${matchup.homePower?.defense_rank || 'N/A'}`, inline: true },
      { name: 'Top QB', value: `${formatMaddenMatchupLeader(matchup.leaders.awayQB, 'Pass Yards')}\nvs\n${formatMaddenMatchupLeader(matchup.leaders.homeQB, 'Pass Yards')}`, inline: true },
      { name: 'Top RB', value: `${formatMaddenMatchupLeader(matchup.leaders.awayRB, 'Rush Yards')}\nvs\n${formatMaddenMatchupLeader(matchup.leaders.homeRB, 'Rush Yards')}`, inline: true },
      { name: 'Top WR', value: `${formatMaddenMatchupLeader(matchup.leaders.awayWR, 'Rec Yards')}\nvs\n${formatMaddenMatchupLeader(matchup.leaders.homeWR, 'Rec Yards')}`, inline: true },
      { name: '🤖 GG Sports Prediction', value: `**${getMaddenTeamEmoji(awayName) || ''} ${awayName} ${matchup.prediction.projectedAway}**\n**${getMaddenTeamEmoji(homeName) || ''} ${homeName} ${matchup.prediction.projectedHome}**\n\nFavorite: **${favorite}**\n\nWin Probability\n${awayName}: **${matchup.prediction.awayProb}%**\n${homeName}: **${matchup.prediction.homeProb}%**`, inline: false }
    )
    .setFooter({ text: 'GG Sports • 7J-7ZS-D Matchup Preview' })
    .setTimestamp();

  if (awayLogo) embed.setAuthor({ name: `${getMaddenTeamAbbrev(awayName)} at ${getMaddenTeamAbbrev(homeName)}`, iconURL: awayLogo });
  if (homeLogo) embed.setThumbnail(homeLogo);
  return embed;
}

function buildMaddenImportedStandingsEmbed(league, rows, scope = 'division') {
  const NL = String.fromCharCode(10);
  const cleanRows = rows || [];

  if (!cleanRows.length) {
    return new EmbedBuilder()
      .setTitle(`${GG_EMOJI} Madden Standings • ${league.league_name}`)
      .setColor(0x57F287)
      .setDescription('No imported Madden standings found yet. Use Operations → Run Sync first.')
      .setFooter({ text: 'GG Sports • Madden Standings' })
      .setTimestamp();
  }

  const normalizedScope = String(scope || 'division').toLowerCase();
  const embed = new EmbedBuilder()
    .setTitle(`${GG_EMOJI} Madden Standings • ${league.league_name}`)
    .setColor(0x57F287)
    .setFooter({ text: 'GG Sports • Madden Standings' })
    .setTimestamp();

  if (normalizedScope === 'conference') {
    const grouped = new Map();
    for (const row of cleanRows) {
      const conference = getMaddenConferenceForTeam(row.team_name);
      if (!grouped.has(conference)) grouped.set(conference, []);
      grouped.get(conference).push(row);
    }

    const groups = [...grouped.entries()].sort((a, b) => getMaddenConferenceSortRank(a[0]) - getMaddenConferenceSortRank(b[0]));
    for (const [conference, groupRows] of groups) {
      const lines = sortMaddenStandingRows(groupRows).map((team, index) => formatMaddenStandingLine(team, index));
      embed.addFields({ name: conference || 'Conference', value: lines.join(NL).slice(0, 1024), inline: false });
    }
    return embed;
  }

  if (normalizedScope === 'league') {
    const lines = sortMaddenStandingRows(cleanRows).map((team, index) => formatMaddenStandingLine(team, index));
    embed.setDescription(lines.join(NL).slice(0, 4096));
    return embed;
  }

  const grouped = new Map();
  for (const row of cleanRows) {
    const division = getMaddenDivisionForTeam(row.team_name);
    if (!grouped.has(division)) grouped.set(division, []);
    grouped.get(division).push(row);
  }

  const groups = [...grouped.entries()].sort((a, b) => getMaddenDivisionSortRank(a[0]) - getMaddenDivisionSortRank(b[0]));
  for (const [division, groupRows] of groups) {
    const lines = sortMaddenStandingRows(groupRows).map((team, index) => formatMaddenStandingLine(team, index));
    embed.addFields({ name: division || 'Division', value: lines.join(NL).slice(0, 1024), inline: false });
  }

  return embed;
}

function getMostRecentImportedWeekLabel(rows) {
  const labels = [...new Set((rows || [])
    .map(row => row.week_label)
    .filter(label => label && String(label).toLowerCase() !== 'week tbd'))];

  if (!labels.length) return null;

  labels.sort((a, b) => maddenWeekSortValue(b) - maddenWeekSortValue(a));
  return labels[0] || null;
}

function buildMaddenScheduleUnavailableEmbed(league, requestedWeek, availableWeek = null) {
  const normalizedRequested = normalizeMaddenWeekFilterInput(requestedWeek) || requestedWeek || 'that week';
  const message =
    '**' + normalizedRequested + '** is not available from EA Direct yet.' + String.fromCharCode(10) + String.fromCharCode(10) +
    'EA Direct currently exposes the active/imported weekly schedule snapshot' +
    (availableWeek ? ', which is **' + availableWeek + '** right now.' : '.') + String.fromCharCode(10) +
    'After the franchise advances and **Operations → Run Sync** is run, that new week will become available.';

  return new EmbedBuilder()
    .setTitle('Madden Schedule Not Available Yet • ' + league.league_name)
    .setColor(0xFEE75C)
    .setDescription(message)
    .setFooter({ text: 'GG Sports • EA Direct Current-Week Schedule' })
    .setTimestamp();
}



function maddenGameTeamKeys(teamName) {
  const abbr = getMaddenTeamAbbrev(teamName);
  return [teamName, abbr].filter(Boolean).map(value => String(value).toLowerCase());
}


function maddenGameHasImportedStats(game) {
  const raw = game?.raw_payload || {};
  if (raw && typeof raw === 'object') {
    if (raw.hasStats === true || raw.statsImported === true || raw.has_stats === true) return true;
    if (Array.isArray(raw.playerStats) && raw.playerStats.length) return true;
    if (Array.isArray(raw.stats) && raw.stats.length) return true;
    if (Array.isArray(raw.playerPassingStatInfoList) && raw.playerPassingStatInfoList.length) return true;
    if (Array.isArray(raw.playerRushingStatInfoList) && raw.playerRushingStatInfoList.length) return true;
    if (Array.isArray(raw.playerReceivingStatInfoList) && raw.playerReceivingStatInfoList.length) return true;
    if (Array.isArray(raw.playerDefensiveStatInfoList) && raw.playerDefensiveStatInfoList.length) return true;
  }
  return false;
}

function maddenIsGameFinalLike(game) {
  const status = String(game?.status || '').toLowerCase();
  if (status === 'scheduled' || status === 'not_played' || status === 'not played') return false;

  // 7J-9B-J: Never treat winner-only zero-score rows as final.
  // EA schedule rows can expose gameResult/forceWin-style values before kickoff, which previously
  // produced fake Week 9 finals. A winner status only counts as final when supported by a real
  // score, imported stat lines, or a trusted played/completed timestamp.
  const hasCompletionEvidence =
    maddenGameHasScore(game) ||
    maddenGameHasImportedStats(game) ||
    Boolean(game?.played_at || game?.completed_at || game?.finalized_at);
  if (['away_win', 'home_win', 'tie'].includes(status)) return hasCompletionEvidence;

  return ['final', 'completed', 'complete', 'completed_with_real_score'].includes(status) && hasCompletionEvidence;
}

function getMaddenGameWinner(game) {
  if (!maddenIsGameFinalLike(game)) return null;
  const status = String(game?.status || '').toLowerCase();
  if (status === 'away_win') return game.away_team;
  if (status === 'home_win') return game.home_team;
  if (status === 'tie') return 'Tie';
  if (!maddenGameHasScore(game)) return null;
  const awayScore = Number(game?.away_score || 0);
  const homeScore = Number(game?.home_score || 0);
  if (awayScore > homeScore) return game.away_team;
  if (homeScore > awayScore) return game.home_team;
  return 'Tie';
}

function formatMaddenGameResultForTeam(game, teamName) {
  const team = String(teamName || '').toLowerCase();
  const isHome = String(game.home_team || '').toLowerCase() === team || String(getMaddenTeamAbbrev(game.home_team) || '').toLowerCase() === team;
  const opponent = isHome ? game.away_team : game.home_team;
  const venue = isHome ? 'vs' : '@';

  if (!maddenIsGameFinalLike(game)) {
    return `**${game.week_label || 'Week TBD'}** ${venue} ${opponent} — Scheduled`;
  }

  const awayScore = Number(game.away_score || 0);
  const homeScore = Number(game.home_score || 0);
  const hasScore = maddenGameHasScore(game);
  const teamScore = isHome ? homeScore : awayScore;
  const oppScore = isHome ? awayScore : homeScore;
  let result = 'Final';

  if (hasScore) {
    if (teamScore > oppScore) result = `W ${teamScore}-${oppScore}`;
    else if (teamScore < oppScore) result = `L ${teamScore}-${oppScore}`;
    else result = `T ${teamScore}-${oppScore}`;
  } else {
    const winner = getMaddenGameWinner(game);
    if (winner === 'Tie') result = 'T';
    else if (winner && String(winner).toLowerCase() === String(isHome ? game.home_team : game.away_team).toLowerCase()) result = 'W';
    else if (winner) result = 'L';
  }

  return `**${game.week_label || 'Week TBD'}** ${venue} ${opponent} — ${result}`;
}

function formatMaddenRecentGameLine(game) {
  const finalLike = maddenIsGameFinalLike(game);
  const awayScore = Number(game.away_score || 0);
  const homeScore = Number(game.home_score || 0);
  const winner = getMaddenGameWinner(game);
  const score = maddenGameHasScore(game)
    ? `${game.away_team} ${awayScore} @ ${game.home_team} ${homeScore}`
    : `${game.away_team} @ ${game.home_team}`;
  const resultText = finalLike
    ? (winner && winner !== 'Tie' ? `Final • ${winner} won` : winner === 'Tie' ? 'Final • Tie' : 'Final')
    : formatMaddenGameStatus(game);
  return `**${game.week_label || 'Week TBD'}** — ${score} • ${resultText}`;
}


function maddenGameHasScore(game) {
  const awayScore = Number(game?.away_score || 0);
  const homeScore = Number(game?.home_score || 0);
  return awayScore > 0 || homeScore > 0 || String(game?.status || '').toLowerCase() === 'completed_with_real_score';
}

function formatMaddenGameScoreLine(game, hasStats = false) {
  const awayScore = Number(game?.away_score || 0);
  const homeScore = Number(game?.home_score || 0);
  if (!maddenGameHasScore(game)) return `${game.away_team} @ ${game.home_team}`;
  return `${game.away_team} ${awayScore}\n${game.home_team} ${homeScore}`;
}

function formatMaddenGameStatus(game, hasStats = false) {
  if (hasStats || maddenIsGameFinalLike(game)) return 'Final';
  const status = String(game?.status || 'scheduled');
  return status.charAt(0).toUpperCase() + status.slice(1);
}

function maddenAnyPerformerStats(performers) {
  return !!(performers?.passing || performers?.rushing || performers?.receiving || performers?.defense);
}

async function getMaddenTeamRecordRow(guildId, leagueId, teamName) {
  const result = await pool.query(
    `SELECT team_name, wins, losses, ties, points_for, points_against
     FROM madden_imported_team_stats
     WHERE guild_id = $1::text
       AND league_id::text = $2::text
       AND (
         LOWER(team_name) = LOWER($3)
         OR LOWER(team_name) = LOWER($4)
       )
     LIMIT 1`,
    [guildId, leagueId, teamName, getMaddenTeamAbbrev(teamName)]
  );
  return result.rows?.[0] || null;
}

function formatMaddenTeamWithRecord(teamName, recordRow) {
  const abbr = getMaddenTeamAbbrev(teamName);
  const record = recordRow ? formatMaddenStandingsRecord(recordRow) : null;
  return `${teamName}${abbr ? ` (${abbr})` : ''}${record ? ` • ${record}` : ''}`;
}

function getMaddenGameMvpCandidate(teamName, performers) {
  const candidates = [];

  if (performers?.passing) {
    const yards = Number(performers.passing.value || 0);
    const tds = Number(performers.passing.extra_0 || 0);
    const ints = Number(performers.passing.extra_1 || 0);
    candidates.push({
      teamName,
      playerName: performers.passing.player_name,
      label: 'Passing',
      score: yards + (tds * 45) - (ints * 30),
      line: `${maddenFormatCompactNumber(yards)} YDS • ${maddenFormatCompactNumber(tds)} TD • ${maddenFormatCompactNumber(ints)} INT`,
    });
  }

  if (performers?.rushing) {
    const yards = Number(performers.rushing.value || 0);
    const tds = Number(performers.rushing.extra_0 || 0);
    const att = Number(performers.rushing.extra_1 || 0);
    candidates.push({
      teamName,
      playerName: performers.rushing.player_name,
      label: 'Rushing',
      score: yards + (tds * 55) + Math.min(att, 25),
      line: `${maddenFormatCompactNumber(yards)} YDS • ${maddenFormatCompactNumber(tds)} TD • ${maddenFormatCompactNumber(att)} ATT`,
    });
  }

  if (performers?.receiving) {
    const yards = Number(performers.receiving.value || 0);
    const tds = Number(performers.receiving.extra_0 || 0);
    const rec = Number(performers.receiving.extra_1 || 0);
    candidates.push({
      teamName,
      playerName: performers.receiving.player_name,
      label: 'Receiving',
      score: yards + (tds * 60) + (rec * 5),
      line: `${maddenFormatCompactNumber(yards)} YDS • ${maddenFormatCompactNumber(tds)} TD • ${maddenFormatCompactNumber(rec)} REC`,
    });
  }

  if (performers?.defense) {
    const tackles = Number(performers.defense.value || 0);
    const sacks = Number(performers.defense.extra_0 || 0);
    const ints = Number(performers.defense.extra_1 || 0);
    candidates.push({
      teamName,
      playerName: performers.defense.player_name,
      label: 'Defense',
      score: (tackles * 4) + (sacks * 30) + (ints * 45),
      line: `${maddenFormatCompactNumber(tackles)} TKL • ${maddenFormatCompactNumber(sacks)} SACK • ${maddenFormatCompactNumber(ints)} INT`,
    });
  }

  return candidates.sort((a, b) => b.score - a.score)[0] || null;
}

function getMaddenGameMvp(awayTeam, awayPerformers, homeTeam, homePerformers) {
  const candidates = [
    getMaddenGameMvpCandidate(awayTeam, awayPerformers),
    getMaddenGameMvpCandidate(homeTeam, homePerformers),
  ].filter(Boolean);
  return candidates.sort((a, b) => b.score - a.score)[0] || null;
}

async function findMaddenGameCenterGame(guildId, leagueId, teamName, week = null, opponent = null) {
  const teamKeys = maddenGameTeamKeys(teamName);
  const oppKeys = opponent ? maddenGameTeamKeys(opponent) : [];

  const weekFilter = normalizeMaddenWeekFilterInput(week) || week;

  // 7J-10F: Game Center current-playoff lookup fix.
  // When no exact week is requested, Game Center should prefer the current/upcoming
  // matchup for those teams, especially playoff rows like Conf./Div. Playoff.
  // Previously it prioritized old completed rows, so a scheduled Ravens @ Bills
  // conference title game could display an older Ravens/Bills final instead.
  const result = await pool.query(
    `SELECT *
     FROM madden_imported_games
     WHERE guild_id = $1::text
       AND league_id::text = $2::text
       AND (
         LOWER(home_team) = ANY($3::text[])
         OR LOWER(away_team) = ANY($3::text[])
       )
       AND (
         $4::text IS NULL
         OR LOWER(week_label) = LOWER($4::text)
       )
       AND (
         $5::text[] IS NULL
         OR LOWER(home_team) = ANY($5::text[])
         OR LOWER(away_team) = ANY($5::text[])
       )
     ORDER BY
       CASE
         WHEN $4::text IS NULL AND LOWER(COALESCE(status, 'scheduled')) = 'scheduled' THEN 0
         WHEN $4::text IS NULL THEN 1
         WHEN LOWER(COALESCE(status, '')) IN ('final', 'completed', 'complete', 'home_win', 'away_win', 'tie', 'completed_with_real_score') THEN 0
         ELSE 1
       END,
       CASE
         WHEN LOWER(COALESCE(week_label, '')) LIKE '%super%' THEN 1000
         WHEN LOWER(COALESCE(week_label, '')) LIKE '%conf%' THEN 900
         WHEN LOWER(COALESCE(week_label, '')) LIKE '%div%' THEN 800
         WHEN LOWER(COALESCE(week_label, '')) LIKE '%wild%' THEN 700
         ELSE COALESCE(NULLIF(regexp_replace(COALESCE(week_label, ''), '[^0-9]', '', 'g'), ''), '0')::int
       END DESC,
       imported_at DESC,
       COALESCE(home_score, 0) + COALESCE(away_score, 0) DESC
     LIMIT 1`,
    [guildId, leagueId, teamKeys, weekFilter || null, oppKeys.length ? oppKeys : null]
  );

  return result.rows?.[0] || null;
}

async function getMaddenGameTopPerformer(guildId, leagueId, game, teamName, statType, primaryKey, extraDefs = []) {
  await ensureMaddenPlayerPersistenceTables();

  const teamKeys = maddenGameTeamKeys(teamName);
  const metricSql = maddenJsonNumberSql(primaryKey).replaceAll('raw_payload', 's.raw_payload');
  const extraSelects = extraDefs.map((def, index) => `${maddenJsonNumberSql(def.key).replaceAll('raw_payload', 's.raw_payload')} AS extra_${index}`);

  const scheduleId = game?.external_game_id ? String(game.external_game_id) : null;

  const result = await pool.query(
    `SELECT
       COALESCE(NULLIF(p.full_name, ''), NULLIF(s.full_name, ''), 'Unknown Player') AS player_name,
       COALESCE(NULLIF(p.team_name, ''), NULLIF(s.team_name, '')) AS resolved_team_name,
       ${metricSql} AS value
       ${extraSelects.length ? ',' + extraSelects.join(',') : ''}
     FROM madden_player_weekly_stats s
     LEFT JOIN madden_players p
       ON p.guild_id = s.guild_id
      AND p.league_id::text = s.league_id::text
      AND NULLIF(s.roster_id, '') IS NOT NULL
      AND p.roster_id::text = s.roster_id::text
     WHERE s.guild_id = $1::text
       AND s.league_id::text = $2::text
       AND s.stat_type = $3::text
       AND (
         $4::text IS NULL
         OR s.schedule_id::text = $4::text
       )
       AND (
         LOWER(COALESCE(p.team_name, s.team_name, '')) = ANY($5::text[])
         OR LOWER(COALESCE(p.team_id, s.team_id, '')) = ANY($5::text[])
       )
       AND ${metricSql} > 0
     ORDER BY value DESC, player_name ASC
     LIMIT 1`,
    [guildId, leagueId, statType, scheduleId, teamKeys]
  );

  return result.rows?.[0] || null;
}

function formatMaddenPerformerLine(row, mainUnit, extraDefs = []) {
  if (!row) return 'No stats found.';
  const pieces = [`${maddenFormatCompactNumber(row.value)} ${mainUnit}`];
  extraDefs.forEach((def, index) => {
    const value = Number(row[`extra_${index}`] || 0);
    if (value > 0 || def.showZero) pieces.push(`${maddenFormatCompactNumber(value)} ${def.unit}`);
  });
  return `**${row.player_name}**\n${pieces.join(' • ')}`;
}

async function getMaddenGameTopPerformers(guildId, leagueId, game, teamName) {
  const [passing, rushing, receiving, defense] = await Promise.all([
    getMaddenGameTopPerformer(guildId, leagueId, game, teamName, 'passing', 'passYds', [
      { key: 'passTDs', unit: 'TD' },
      { key: 'passInts', unit: 'INT', showZero: true },
    ]),
    getMaddenGameTopPerformer(guildId, leagueId, game, teamName, 'rushing', 'rushYds', [
      { key: 'rushTDs', unit: 'TD' },
      { key: 'rushAtt', unit: 'ATT' },
    ]),
    getMaddenGameTopPerformer(guildId, leagueId, game, teamName, 'receiving', 'recYds', [
      { key: 'recTDs', unit: 'TD' },
      { key: 'recCatches', unit: 'REC' },
    ]),
    getMaddenGameTopPerformer(guildId, leagueId, game, teamName, 'defense', 'defTotalTackles', [
      { key: 'defSacks', unit: 'SACK' },
      { key: 'defInts', unit: 'INT' },
    ]),
  ]);

  return { passing, rushing, receiving, defense };
}

function buildMaddenGameCenterEmbed(league, game, awayPerformers, homePerformers, awayRecord = null, homeRecord = null) {
  const NL = String.fromCharCode(10);
  const awayTeam = game.away_team || 'Away';
  const homeTeam = game.home_team || 'Home';
  const week = game.week_label || 'Week TBD';
  const hasStats = maddenAnyPerformerStats(awayPerformers) || maddenAnyPerformerStats(homePerformers);
  const status = formatMaddenGameStatus(game, hasStats);
  const mvp = getMaddenGameMvp(awayTeam, awayPerformers, homeTeam, homePerformers);

  const embed = new EmbedBuilder()
    .setTitle(`${GG_EMOJI} Madden Game Center • ${week}`)
    .setDescription(`**${formatMaddenTeamWithRecord(awayTeam, awayRecord)}**\n@ **${formatMaddenTeamWithRecord(homeTeam, homeRecord)}**`)
    .setColor(status === 'Final' ? 0x57F287 : 0xFEE75C)
    .addFields(
      { name: maddenGameHasScore(game) ? 'Final Score' : 'Matchup', value: formatMaddenGameScoreLine(game, hasStats), inline: false },
      { name: 'Status', value: status, inline: true },
      { name: 'League', value: league.league_name, inline: true }
    )
    .setFooter({ text: 'GG Sports • Madden Game Center' })
    .setTimestamp();

  const gameLogo = getMaddenTeamLogoUrl(homeTeam) || getMaddenTeamLogoUrl(awayTeam);
  if (gameLogo) embed.setThumbnail(gameLogo);

  if (mvp) {
    embed.addFields({
      name: '⭐ Game MVP',
      value: `**${mvp.playerName}** (${getMaddenTeamAbbrev(mvp.teamName) || mvp.teamName})\n${mvp.label} • ${mvp.line}`,
      inline: false,
    });
  }

  const awayLines = [
    `**Passing:** ${formatMaddenPerformerLine(awayPerformers.passing, 'YDS', [{ unit: 'TD' }, { unit: 'INT', showZero: true }])}`,
    `**Rushing:** ${formatMaddenPerformerLine(awayPerformers.rushing, 'YDS', [{ unit: 'TD' }, { unit: 'ATT' }])}`,
    `**Receiving:** ${formatMaddenPerformerLine(awayPerformers.receiving, 'YDS', [{ unit: 'TD' }, { unit: 'REC' }])}`,
    `**Defense:** ${formatMaddenPerformerLine(awayPerformers.defense, 'TKL', [{ unit: 'SACK' }, { unit: 'INT' }])}`,
  ];

  const homeLines = [
    `**Passing:** ${formatMaddenPerformerLine(homePerformers.passing, 'YDS', [{ unit: 'TD' }, { unit: 'INT', showZero: true }])}`,
    `**Rushing:** ${formatMaddenPerformerLine(homePerformers.rushing, 'YDS', [{ unit: 'TD' }, { unit: 'ATT' }])}`,
    `**Receiving:** ${formatMaddenPerformerLine(homePerformers.receiving, 'YDS', [{ unit: 'TD' }, { unit: 'REC' }])}`,
    `**Defense:** ${formatMaddenPerformerLine(homePerformers.defense, 'TKL', [{ unit: 'SACK' }, { unit: 'INT' }])}`,
  ];

  embed.addFields(
    { name: `${awayTeam} Top Performers`, value: awayLines.join(NL).slice(0, 1024), inline: false },
    { name: `${homeTeam} Top Performers`, value: homeLines.join(NL).slice(0, 1024), inline: false }
  );

  return embed;
}

function buildMaddenImportedScheduleEmbed(league, rows, week = null) {
  const NL = String.fromCharCode(10);
  const sorted = [...rows].sort((a, b) =>
    maddenWeekSortValue(a.week_label) - maddenWeekSortValue(b.week_label) ||
    String(a.away_team || '').localeCompare(String(b.away_team || ''))
  );

  const lines = sorted.map(game => {
    const awayEmoji = getMaddenTeamEmoji(game.away_team);
    const homeEmoji = getMaddenTeamEmoji(game.home_team);
    const awayDisplay = `${awayEmoji ? awayEmoji + ' ' : ''}${game.away_team || 'Away'}`;
    const homeDisplay = `${homeEmoji ? homeEmoji + ' ' : ''}${game.home_team || 'Home'}`;
    const statusLabel = String(game.status || 'scheduled') === 'completed_with_real_score' ? 'Final' : (game.status || 'Scheduled');
    return '**' + (game.week_label || 'Week TBD') + '** — ' +
      awayDisplay + ' @ ' + homeDisplay +
      formatMaddenGameScore(game) +
      ' • ' + statusLabel;
  });

  return new EmbedBuilder()
    .setTitle('Madden Imported Schedule' + (week ? ' • ' + week : '') + ' • ' + league.league_name)
    .setColor(0x5865F2)
    .setDescription(lines.length ? lines.join(NL).slice(0, 4096) : 'No imported Madden games found yet. Use /madden importgames or Operations → Run Sync.')
    .setFooter({ text: 'GG Sports • Madden Schedule • EA Direct weekly snapshot' })
    .setTimestamp();
}


const DEV_EMOJIS = {
  hidden: '<:hidden:1514330868154634372>',
  normal: '<:normal:1514330608493531236>',
  star: '<:star:1514330674214080612>',
  superstar: '<:superstar:1514330752043716699>',
  xfactor: '<:xfactor:1514330812127121530>',
};

function getMaddenDevTraitSortValue(devTrait) {
  const dev = String(devTrait || '').toLowerCase();
  if (dev.includes('x-factor') || dev.includes('xfactor')) return 5;
  if (dev.includes('superstar')) return 4;
  if (dev.includes('star')) return 3;
  if (dev.includes('hidden')) return 2;
  if (dev.includes('normal')) return 1;
  return 0;
}

function maddenRosterPositionGroup(position) {
  const pos = String(position || '').toUpperCase();
  if (['QB'].includes(pos)) return 'QB';
  if (['HB', 'RB', 'FB'].includes(pos)) return 'Backfield';
  if (['WR', 'TE'].includes(pos)) return 'Receivers';
  if (['LT', 'LG', 'C', 'RG', 'RT', 'OL'].includes(pos)) return 'Offensive Line';
  if (['LE', 'RE', 'DT', 'LOLB', 'MLB', 'ROLB', 'EDGE', 'REDGE', 'LEDGE', 'MIKE', 'WILL', 'SAM'].includes(pos)) return 'Front Seven';
  if (['CB', 'FS', 'SS', 'DB'].includes(pos)) return 'Secondary';
  if (['K', 'P'].includes(pos)) return 'Special Teams';
  return 'Other';
}

function maddenRosterGroupSortValue(group) {
  const order = ['QB', 'Backfield', 'Receivers', 'Offensive Line', 'Front Seven', 'Secondary', 'Special Teams', 'Other'];
  const idx = order.indexOf(group);
  return idx === -1 ? 999 : idx;
}

function maddenPlayerDevBadge(devTrait) {
  const dev = String(devTrait || '').toLowerCase();
  if (dev.includes('x-factor') || dev.includes('xfactor')) return `${DEV_EMOJIS.xfactor} X-Factor`;
  if (dev.includes('superstar')) return `${DEV_EMOJIS.superstar} Superstar`;
  if (dev.includes('star')) return `${DEV_EMOJIS.star} Star`;
  if (dev.includes('hidden')) return `${DEV_EMOJIS.hidden} Hidden`;
  if (dev.includes('normal')) return `${DEV_EMOJIS.normal} Normal`;
  return devTrait ? String(devTrait) : `${DEV_EMOJIS.normal} Normal`;
}

function maddenPlayerDevEmojiOnly(devTrait) {
  const dev = String(devTrait || '').toLowerCase();
  if (dev.includes('x-factor') || dev.includes('xfactor')) return DEV_EMOJIS.xfactor;
  if (dev.includes('superstar')) return DEV_EMOJIS.superstar;
  if (dev.includes('star')) return DEV_EMOJIS.star;
  if (dev.includes('hidden')) return DEV_EMOJIS.hidden;
  if (dev.includes('normal')) return DEV_EMOJIS.normal;
  return DEV_EMOJIS.normal;
}

function maddenPlayerDevEmbedColor(devTrait) {
  const dev = String(devTrait || '').toLowerCase();
  if (dev.includes('x-factor') || dev.includes('xfactor')) return 0xED4245;
  if (dev.includes('superstar')) return 0xFEE75C;
  if (dev.includes('star')) return 0xC0C0C0;
  if (dev.includes('hidden')) return 0x5865F2;
  return 0x7F8C8D;
}

function formatMaddenImportedPlayerLine(player, index = null, compact = false) {
  const name = player.player_name || maddenPlayerDisplayName(player);
  const team = player.resolved_team_name || player.team_name || 'FA';
  const abbr = getMaddenTeamAbbrev(team) || team;
  const pos = player.position || 'POS';
  const ovr = player.overall !== null && player.overall !== undefined ? `${player.overall} OVR` : 'OVR N/A';
  const dev = maddenPlayerDevEmojiOnly(player.dev_trait);
  const age = !compact && player.age ? `Age ${player.age}` : null;
  const prefix = index !== null ? `**${index + 1}. ${name}**` : `**${name}**`;

  // Contract info — pull from raw_payload first (EA: contractYearsLeft, capHit, contractSalary)
  // then fall back to joined table columns (pa/pv)
  let contractText = null;
  if (!compact) {
    const raw = extractMaddenPlayerContractFromRaw(player);
    const yrs = raw.yrs ?? (Number(player.years_left ?? -1) > 0 ? Number(player.years_left) : null);
    const cap = raw.cap ?? (Number(player.cap_hit || player.salary || 0) > 0 ? Number(player.cap_hit || player.salary) : null);
    if (yrs && cap) {
      contractText = `${yrs}yr • $${(cap / 1000000).toFixed(1)}M`;
    } else if (cap) {
      contractText = `$${(cap / 1000000).toFixed(1)}M`;
    } else if (yrs) {
      contractText = `${yrs}yr`;
    }
  }

  const details = [abbr, pos, ovr, dev, age, contractText].filter(Boolean).join(' • ');
  return `${prefix}\n— ${details}`;
}

function buildMaddenRosterGroupedText(rows) {
  const groups = new Map();
  for (const player of rows || []) {
    const group = maddenRosterPositionGroup(player.position);
    if (!groups.has(group)) groups.set(group, []);
    groups.get(group).push(player);
  }

  const lines = [];
  for (const [group, players] of [...groups.entries()].sort((a, b) => maddenRosterGroupSortValue(a[0]) - maddenRosterGroupSortValue(b[0]))) {
    lines.push(`**${group}**`);
    for (const player of players.slice(0, 14)) {
      const name = player.player_name || maddenPlayerDisplayName(player);
      const pos = player.position || 'POS';
      const ovr = player.overall !== null && player.overall !== undefined ? player.overall : 'N/A';
      const ageText = Number(player.age || 0) > 0 && Number(player.age || 0) <= 24 ? ` • Age ${player.age}` : '';
      const rawContract = extractMaddenPlayerContractFromRaw(player);
      const yrs = rawContract.yrs ?? (Number(player.years_left ?? -1) > 0 ? Number(player.years_left) : null);
      const cap = rawContract.cap ?? (Number(player.cap_hit || 0) > 0 ? Number(player.cap_hit) : null);
      const contractText = yrs && cap
        ? ` • ${yrs}yr $${(cap / 1000000).toFixed(1)}M`
        : yrs ? ` • ${yrs}yr` : '';
      lines.push(`${name} — ${pos} • ${ovr} OVR • ${maddenPlayerDevEmojiOnly(player.dev_trait)}${ageText}${contractText}`);
    }
  }

  return lines.join('\n');
}

// 7J-10BY-GT2: Player search two-mode view (Info / Attributes)
// EA stores ratings as camelCase with Rating suffix: accelRating, agilityRating, etc.
function extractMaddenPlayerAttributesForDisplay(player) {
  const raw = player.raw_payload && typeof player.raw_payload === 'object' ? player.raw_payload : {};
  const flat = maddenDiagFlattenObject7J10BYDB(raw);

  // Normalized lookup: last path segment (stripped) → numeric value
  const lookup = {};
  for (const [path, value] of Object.entries(flat)) {
    const key = path.split('.').pop().toLowerCase().replace(/[^a-z0-9]/g, '');
    const num = Number(value);
    if (!isNaN(num) && num > 0) lookup[key] = num;
  }

  const get = (...keys) => {
    for (const k of keys) {
      const norm = k.toLowerCase().replace(/[^a-z0-9]/g, '');
      if (lookup[norm] !== undefined) return lookup[norm];
    }
    return null;
  };

  const pos = String(player.position || '').toUpperCase();
  const results = [];

  // Athletic — EA sends XxxRating; keep fallback aliases for other sync sources
  const spd = get('speedRating', 'speed', 'spd');
  const acc = get('accelRating', 'accelerationRating', 'acceleration', 'accel');
  const agi = get('agilityRating', 'changeOfDirectionRating', 'agility', 'agi');
  const str = get('strengthRating', 'strength', 'str');
  const awr = get('awareRating', 'awarenessRating', 'awareness', 'awr');

  if (spd) results.push(`SPD ${spd}`);
  if (acc) results.push(`ACC ${acc}`);
  if (agi) results.push(`AGI ${agi}`);
  if (str) results.push(`STR ${str}`);

  if (pos === 'QB') {
    const thp = get('throwPowerRating', 'throwPower', 'thp');
    const sac = get('shortAccuracyRating', 'shortAccuracy', 'sac');
    const mac = get('medAccuracyRating', 'mediumAccuracyRating', 'mediumAccuracy', 'mac');
    const dac = get('deepAccuracyRating', 'deepAccuracy', 'dac');
    const tup = get('throwUnderPressureRating', 'throwUnderPressure', 'tup');
    const tor = get('throwOnRunRating', 'throwOnRun', 'tor');
    if (thp) results.push(`THP ${thp}`);
    if (sac) results.push(`SAC ${sac}`);
    if (mac) results.push(`MAC ${mac}`);
    if (dac) results.push(`DAC ${dac}`);
    if (tup) results.push(`TUP ${tup}`);
    if (tor) results.push(`TOR ${tor}`);
  } else if (['HB', 'FB'].includes(pos)) {
    const car = get('carryRating', 'carryingRating', 'carrying', 'car');
    const btk = get('breakTackleRating', 'breakTackle', 'btk');
    const trk = get('truckingRating', 'trucking', 'trk');
    const juk = get('jukeMoveRating', 'jukeMovesRating', 'juke', 'juk');
    const cth = get('catchRating', 'catchingRating', 'catching', 'cth');
    if (car) results.push(`CAR ${car}`);
    if (btk) results.push(`BTK ${btk}`);
    if (trk) results.push(`TRK ${trk}`);
    if (juk) results.push(`JUK ${juk}`);
    if (cth) results.push(`CTH ${cth}`);
  } else if (['WR', 'TE'].includes(pos)) {
    const cth = get('catchRating', 'catchingRating', 'catching', 'cth');
    const cit = get('cITRating', 'catchInTrafficRating', 'catchInTraffic', 'cit');
    const spc = get('specCatchRating', 'spectacularCatchRating', 'spectacularCatch', 'spc');
    const rls = get('releaseRating', 'release', 'rls');
    const srr = get('shortRouteRunRating', 'shortRouteRunningRating', 'shortRouteRunning', 'srr');
    const mrr = get('medRouteRunRating', 'mediumRouteRunningRating', 'mediumRouteRunning', 'mrr');
    if (cth) results.push(`CTH ${cth}`);
    if (cit) results.push(`CIT ${cit}`);
    if (spc) results.push(`SPC ${spc}`);
    if (rls) results.push(`RLS ${rls}`);
    if (srr) results.push(`SRR ${srr}`);
    if (mrr) results.push(`MRR ${mrr}`);
  } else if (['LT', 'LG', 'C', 'RG', 'RT'].includes(pos)) {
    const pbk = get('passBlockRating', 'passBlock', 'pbk');
    const rbk = get('runBlockRating', 'runBlock', 'rbk');
    const ibl = get('impactBlockRating', 'impactBlock', 'ibl');
    const pbp = get('passBlockPowerRating', 'passBlockPower', 'pbp');
    const pbf = get('passBlockFinesseRating', 'passBlockFinesse', 'pbf');
    if (pbk) results.push(`PBK ${pbk}`);
    if (rbk) results.push(`RBK ${rbk}`);
    if (ibl) results.push(`IBL ${ibl}`);
    if (pbp) results.push(`PBP ${pbp}`);
    if (pbf) results.push(`PBF ${pbf}`);
  } else if (['LE', 'RE', 'DT'].includes(pos)) {
    const tak = get('tackleRating', 'tackle', 'tak');
    const pur = get('pursuitRating', 'pursuit', 'pur');
    const pmv = get('powerMovesRating', 'powerMoveRating', 'powerMove', 'pmv');
    const fmv = get('finessMovesRating', 'finesseMovesRating', 'finessMove', 'fmv');
    const bsh = get('blockShedRating', 'blockShed', 'bsh');
    if (tak) results.push(`TAK ${tak}`);
    if (pur) results.push(`PUR ${pur}`);
    if (pmv) results.push(`PMV ${pmv}`);
    if (fmv) results.push(`FMV ${fmv}`);
    if (bsh) results.push(`BSH ${bsh}`);
  } else if (['LOLB', 'MLB', 'ROLB'].includes(pos)) {
    const tak = get('tackleRating', 'tackle', 'tak');
    const pur = get('pursuitRating', 'pursuit', 'pur');
    const prc = get('playRecognitionRating', 'playRecognition', 'prc');
    const bsh = get('blockShedRating', 'blockShed', 'bsh');
    const mcv = get('manCoverageRating', 'manCoverage', 'mcv');
    const zcv = get('zoneCoverageRating', 'zoneCoverage', 'zcv');
    if (tak) results.push(`TAK ${tak}`);
    if (pur) results.push(`PUR ${pur}`);
    if (prc) results.push(`PRC ${prc}`);
    if (bsh) results.push(`BSH ${bsh}`);
    if (mcv) results.push(`MCV ${mcv}`);
    if (zcv) results.push(`ZCV ${zcv}`);
  } else if (['CB', 'FS', 'SS'].includes(pos)) {
    const mcv = get('manCoverageRating', 'manCoverage', 'mcv');
    const zcv = get('zoneCoverageRating', 'zoneCoverage', 'zcv');
    const prs = get('pressRating', 'press', 'prs');
    const tak = get('tackleRating', 'tackle', 'tak');
    const pur = get('pursuitRating', 'pursuit', 'pur');
    const prc = get('playRecognitionRating', 'playRecognition', 'prc');
    if (mcv) results.push(`MCV ${mcv}`);
    if (zcv) results.push(`ZCV ${zcv}`);
    if (prs) results.push(`PRS ${prs}`);
    if (tak) results.push(`TAK ${tak}`);
    if (pur) results.push(`PUR ${pur}`);
    if (prc) results.push(`PRC ${prc}`);
  } else if (['K', 'P'].includes(pos)) {
    const kpw = get('kickPowerRating', 'kickPower', 'kpw');
    const kac = get('kickAccuracyRating', 'kickAccuracy', 'kac');
    if (kpw) results.push(`KPW ${kpw}`);
    if (kac) results.push(`KAC ${kac}`);
  }

  if (awr) results.push(`AWR ${awr}`);
  return results.slice(0, 7);
}

// Extract contract data from raw_payload using EA's actual field names
function extractMaddenPlayerContractFromRaw(player) {
  const raw = player.raw_payload && typeof player.raw_payload === 'object' ? player.raw_payload : {};
  const flat = maddenDiagFlattenObject7J10BYDB(raw);
  const lookup = {};
  for (const [path, value] of Object.entries(flat)) {
    const key = path.split('.').pop().toLowerCase().replace(/[^a-z0-9]/g, '');
    lookup[key] = value;
  }
  const get = (...keys) => {
    for (const k of keys) {
      const norm = k.toLowerCase().replace(/[^a-z0-9]/g, '');
      if (lookup[norm] !== undefined) return lookup[norm];
    }
    return null;
  };
  const yrs = Number(get('contractYearsLeft', 'yearsLeft', 'years_left', 'contractlength') ?? -1);
  const cap = Number(get('capHit', 'cap_hit', 'contractSalary', 'salary') || 0);
  return {
    yrs: yrs > 0 ? yrs : null,
    cap: cap > 0 ? cap : null,
    capText: cap > 0 ? `$${(cap / 1000000).toFixed(1)}M` : null,
  };
}

function buildMaddenPlayersAttributesEmbed(league, rows, filters = {}) {
  const NL = String.fromCharCode(10);
  const filterText = [
    filters.team ? 'Team: ' + filters.team : null,
    filters.position ? 'Position: ' + filters.position : null,
    filters.dev ? 'Dev: ' + filters.dev : null,
  ].filter(Boolean).join(' • ');

  let hasAnyAttributes = false;
  const lines = rows.map((player, index) => {
    const name = player.player_name || maddenPlayerDisplayName(player);
    const pos = player.position || 'POS';
    const ovr = player.overall != null ? player.overall : 'N/A';
    const dev = maddenPlayerDevEmojiOnly(player.dev_trait);
    const attrs = extractMaddenPlayerAttributesForDisplay(player);
    if (attrs.length) hasAnyAttributes = true;
    const attrLine = attrs.length ? attrs.join(' • ') : '— no attribute data in payload';
    return `**${index + 1}. ${name}** — ${pos} ${ovr} OVR ${dev}\n${attrLine}`;
  });

  const body = lines.join(NL).slice(0, 3900);
  const noDataNote = !hasAnyAttributes
    ? NL + NL + '_No attribute ratings found in raw payload. EA may not include these in the current sync endpoint — check `/maddendiagnostics` for details._'
    : '';

  return new EmbedBuilder()
    .setTitle('⚡ Player Attributes • ' + league.league_name)
    .setColor(0x5865F2)
    .setDescription((filterText ? '_' + filterText + '_' + NL + NL : '') + (body || 'No players found.') + noDataNote)
    .setFooter({ text: `GG Sports • Player Attributes • Showing ${Math.min(rows.length, 50)}` })
    .setTimestamp();
}

