// ---------------------------------------------------------------------------
// Click-only player picker (Team -> Player) — replaces free-text name entry for
// negotiation start and player search, since Discord modals cannot autocomplete
// and player names are easy to misspell.
// ---------------------------------------------------------------------------
async function getMaddenLeagueTeamNames(guildId, leagueId, { excludeFreeAgents = false, excludeTeam = null } = {}) {
  const result = await pool.query(
    `SELECT DISTINCT COALESCE(NULLIF(p.team_name, ''), NULLIF(t.team_name, '')) AS team_name
     FROM madden_players p
     LEFT JOIN madden_imported_team_stats t
       ON t.guild_id = p.guild_id::text AND t.league_id::text = p.league_id::text AND p.team_id IS NOT NULL AND t.external_team_id::text = p.team_id
     WHERE p.guild_id = $1 AND p.league_id = $2
       AND COALESCE(NULLIF(p.team_name, ''), NULLIF(t.team_name, '')) IS NOT NULL
       ${excludeFreeAgents ? 'AND COALESCE(p.is_free_agent, false) = false' : ''}
     ORDER BY team_name ASC`,
    [String(guildId), String(leagueId)]
  );
  const names = (result.rows || []).map(r => r.team_name).filter(Boolean);
  if (!excludeTeam) return names;
  return names.filter(name => name.toLowerCase() !== String(excludeTeam).toLowerCase());
}

function buildMaddenTeamPickerComponents(flow, leagueId, teams) {
  const groups = [];
  let bucket = [];
  for (const team of teams) {
    bucket.push(team);
    if (bucket.length === 25) { groups.push(bucket); bucket = []; }
  }
  if (bucket.length) groups.push(bucket);
  const rows = groups.slice(0, 4).map((group, idx) => new ActionRowBuilder().addComponents(
    new StringSelectMenuBuilder()
      .setCustomId(`madpick:team:${flow}:${leagueId}:${idx}`)
      .setPlaceholder(groups.length > 1 ? `Choose a team (${idx + 1}/${groups.length})` : 'Choose a team')
      .addOptions(group.map(name => ({ label: String(name).slice(0, 100), value: String(name).slice(0, 100) })))
  ));
  return rows;
}

async function getMaddenTeamRosterPage(guildId, leagueId, teamName, { offset = 0, limit = 25, excludeFreeAgents = false } = {}) {
  const result = await pool.query(
    `SELECT p.*, COALESCE(NULLIF(CONCAT_WS(' ', p.first_name, p.last_name), ''), p.full_name) AS player_name
     FROM madden_players p
     LEFT JOIN madden_imported_team_stats t
       ON t.guild_id = p.guild_id::text AND t.league_id::text = p.league_id::text AND p.team_id IS NOT NULL AND t.external_team_id::text = p.team_id
     WHERE p.guild_id = $1 AND p.league_id = $2
       AND COALESCE(NULLIF(p.team_name, ''), NULLIF(t.team_name, '')) = $3
       ${excludeFreeAgents ? 'AND COALESCE(p.is_free_agent, false) = false' : ''}
     ORDER BY p.overall DESC NULLS LAST, player_name ASC
     OFFSET $4 LIMIT $5`,
    [String(guildId), String(leagueId), teamName, offset, limit]
  );
  const countResult = await pool.query(
    `SELECT COUNT(*)::int AS count
     FROM madden_players p
     WHERE p.guild_id = $1 AND p.league_id = $2
       AND COALESCE(NULLIF(p.team_name, ''), '') = $3
       ${excludeFreeAgents ? 'AND COALESCE(p.is_free_agent, false) = false' : ''}`,
    [String(guildId), String(leagueId), teamName]
  ).catch(() => ({ rows: [{ count: (result.rows || []).length }] }));
  return { rows: result.rows || [], total: countResult.rows?.[0]?.count || (result.rows || []).length };
}

function buildMaddenRosterPickerComponents(flow, leagueId, teamName, rows, offset, total) {
  const encTeam = encodeURIComponent(teamName).slice(0, 80);
  const components = [new ActionRowBuilder().addComponents(
    new StringSelectMenuBuilder()
      .setCustomId(`madpick:player:${flow}:${leagueId}:${encTeam}:${offset}`)
      .setPlaceholder(`Choose a player from ${String(teamName).slice(0, 60)}`)
      .addOptions((rows.length ? rows : [{ player_name: 'No players found', position: '', overall: '' }]).map(r => ({
        label: String(r.player_name || 'Unknown').slice(0, 100),
        value: String(r.player_name || 'unknown').slice(0, 100),
        description: (r.position ? `${r.position} • ${r.overall || 'N/A'} OVR` : 'No roster data').slice(0, 100),
      })))
      .setDisabled(!rows.length)
  )];

  const navButtons = [
    new ButtonBuilder().setCustomId(`madpick:backteam:${flow}:${leagueId}`).setLabel('⬅ Change Team').setStyle(ButtonStyle.Secondary),
  ];
  if (total > 25) {
    const prevOffset = Math.max(0, offset - 25);
    const nextOffset = offset + 25;
    navButtons.push(
      new ButtonBuilder().setCustomId(`madpick:rosterpage:${flow}:${leagueId}:${encTeam}:${prevOffset}`).setLabel('Previous').setStyle(ButtonStyle.Secondary).setDisabled(offset <= 0),
      new ButtonBuilder().setCustomId(`madpick:rosterpage:${flow}:${leagueId}:${encTeam}:${nextOffset}`).setLabel('Next').setStyle(ButtonStyle.Primary).setDisabled(nextOffset >= total),
    );
  }
  components.push(new ActionRowBuilder().addComponents(...navButtons));
  return components;
}

async function showMaddenTeamPicker(interaction, flow, idOrToken, { update = false } = {}) {
  const league = await resolveMaddenPickerLeague(flow, idOrToken);
  if (!league) {
    const payload = { content: 'League not found.', embeds: [], components: [] };
    return update ? interaction.update(payload) : interaction.reply({ ...payload, ephemeral: true });
  }
  const excludeFreeAgents = flow === 'neg';
  const excludeTeam = (flow === 'wizardB' && maddenTradeWizardSessions.get(idOrToken)?.sideA?.team)
    // 7J-SELFTRADE: per Hxxdie — the same self-trade gap fixed on the
    // generic (non-Madden) offer flow existed here too. "Start a Trade
    // Negotiation" never excluded the requesting GM's own team from the
    // team picker, so someone who owns the Ducks could pick "Ducks" as the
    // team they're negotiating a trade with.
    || (flow === 'neg' ? (await getMaddenTeamOwnedByUser(interaction.guild.id, league.league_id, interaction.user.id))?.team_name : null)
    || null;
  const teams = await getMaddenLeagueTeamNames(interaction.guild.id, league.league_id, { excludeFreeAgents, excludeTeam });
  const label = flow === 'compareA' ? 'Compare Players — Player A'
    : flow === 'compareB' ? 'Compare Players — Player B'
    : flow === 'wizardA' ? 'Side A — Choose a team'
    : flow === 'wizardB' ? 'Side B — Choose a team'
    : flow === 'neg' ? 'Start a Trade Negotiation'
    : 'Search for a Player';
  const content = teams.length
    ? `**${label}** — pick a team, then pick a player. No typing needed.`
    : 'No team rosters found yet. Run Operations → Run Sync first.';
  const payload = { content, embeds: [], components: teams.length ? buildMaddenTeamPickerComponents(flow, idOrToken, teams) : [] };
  return update ? interaction.update(payload) : interaction.reply({ ...payload, ephemeral: true });
}

// ---------------------------------------------------------------------------
// Trade Wizard — shared by GM Panel "Trade Builder" (1 player/side, no picks)
// and "Trade Analyzer" (up to 3 players + 2 picks/side), both powered by the
// same resolveMaddenTradeAnalyzerSide / buildMaddenTradeAnalyzerEmbed the
// /maddentrade analyze slash command already uses.
// ---------------------------------------------------------------------------
async function showMaddenTradeWizardSidePickers(interaction, token, { update = true } = {}) {
  const session = maddenTradeWizardSessions.get(token);
  if (!session) {
    const payload = { content: 'This trade session expired. Start again from the GM Panel.', embeds: [], components: [] };
    return update ? interaction.update(payload) : interaction.editReply(payload);
  }
  const league = await getLeagueById(session.leagueId);
  if (!league) {
    const payload = { content: 'League not found.', embeds: [], components: [] };
    return update ? interaction.update(payload) : interaction.editReply(payload);
  }
  const sideKey = session.currentSide === 'A' ? 'sideA' : 'sideB';
  const side = session[sideKey];
  const rosterPage = side.rosterPage || 0;
  const { rows, total } = await getMaddenTeamRosterPage(interaction.guild.id, league.league_id, side.team, { offset: rosterPage * 25, limit: 25, excludeFreeAgents: true });

  const componentRows = [];
  if (rows.length) {
    const playerMenu = new StringSelectMenuBuilder()
      .setCustomId(`madwiz:players:${token}`)
      .setPlaceholder(session.maxPlayers === 1 ? 'Select a player' : `Select up to ${session.maxPlayers} player(s)`)
      .setMinValues(0)
      .setMaxValues(Math.min(session.maxPlayers, rows.length))
      .addOptions(rows.map(r => ({
        label: String(r.player_name || 'Unknown').slice(0, 100),
        value: String(r.player_name || 'unknown').slice(0, 100),
        description: `${r.position || 'POS'} • ${r.overall || 'N/A'} OVR`.slice(0, 100),
        default: side.players.includes(r.player_name),
      })));
    componentRows.push(new ActionRowBuilder().addComponents(playerMenu));
  }

  if (total > 25) {
    const totalPages = Math.ceil(total / 25);
    componentRows.push(new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId(`madwiz:rosterpage:${token}:${Math.max(0, rosterPage - 1)}`).setLabel(`Previous (${rosterPage + 1}/${totalPages})`).setStyle(ButtonStyle.Secondary).setDisabled(rosterPage <= 0),
      new ButtonBuilder().setCustomId(`madwiz:rosterpage:${token}:${Math.min(totalPages - 1, rosterPage + 1)}`).setLabel(`Next (${rosterPage + 1}/${totalPages})`).setStyle(ButtonStyle.Primary).setDisabled(rosterPage >= totalPages - 1),
    ));
  }

  if (session.includePicks) {
    const slotMap = await getMaddenProjectedDraftSlotMap(interaction.guild.id, league.league_id).catch(() => new Map());
    const pickPool = maddenTradeFinderPickPool(side.team, slotMap).slice(0, 25);
    if (pickPool.length) {
      const pickMenu = new StringSelectMenuBuilder()
        .setCustomId(`madwiz:picks:${token}`)
        .setPlaceholder('Select up to 2 draft picks (optional)')
        .setMinValues(0)
        .setMaxValues(Math.min(2, pickPool.length))
        .addOptions(pickPool.map(p => ({
          label: p.label.slice(0, 100),
          value: p.raw.slice(0, 100),
          default: side.picks.includes(p.raw),
        })));
      componentRows.push(new ActionRowBuilder().addComponents(pickMenu));
    }
  }

  const continueLabel = session.currentSide === 'A' ? 'Continue to Side B' : 'Analyze Trade';
  const continueRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`madwiz:continue:${token}`).setLabel(continueLabel).setStyle(ButtonStyle.Primary)
  );
  if (session.currentSide === 'B') {
    continueRow.addComponents(new ButtonBuilder().setCustomId(`madwiz:changeteam:${token}`).setLabel('Change Team').setStyle(ButtonStyle.Secondary));
  }
  componentRows.push(continueRow);

  const pickSummary = session.includePicks ? `\nPicks: ${side.picks.length ? side.picks.map(raw => parseMaddenDraftPickAsset(raw)?.label || raw).join(', ') : 'none selected'}` : '';
  const content = `**${session.mode === 'builder' ? 'Trade Builder' : 'Trade Analyzer'} — Side ${session.currentSide}**\nTeam: **${side.team}**\nPlayers: ${side.players.length ? side.players.join(', ') : 'none selected'}${pickSummary}`;

  const payload = { content, embeds: [], components: componentRows };
  return update ? interaction.update(payload) : interaction.editReply(payload);
}

function maddenTradeWizardOfferSummary(side) {
  const parts = [...(side.players || [])];
  for (const raw of side.picks || []) {
    const pick = parseMaddenDraftPickAsset(raw);
    if (pick) parts.push(pick.label);
  }
  return parts.length ? parts.join(' + ') : 'No assets selected';
}

async function buildMaddenTradeWizardResultPayload(interaction, token) {
  const session = maddenTradeWizardSessions.get(token);
  if (!session) return { content: 'This trade session expired. Start again from the GM Panel.', embeds: [], components: [] };
  const league = await getLeagueById(session.leagueId);
  if (!league) return { content: 'League not found.', embeds: [], components: [] };

  const [sideA, sideB] = await Promise.all([
    resolveMaddenTradeAnalyzerSide(interaction.guild.id, league.league_id, session.sideA.players.join(', '), session.sideA.picks),
    resolveMaddenTradeAnalyzerSide(interaction.guild.id, league.league_id, session.sideB.players.join(', '), session.sideB.picks),
  ]);

  const embed = buildMaddenTradeAnalyzerEmbed(league, {
    labelA: session.sideA.team,
    labelB: session.sideB.team,
    sideA,
    sideB,
  });
  const negotiateRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`madwiz_negotiate:${token}`).setLabel(`Start Negotiation with ${session.sideB.team}`).setEmoji('🤝').setStyle(ButtonStyle.Success)
  );
  return { content: null, embeds: [embed], components: [negotiateRow, buildMaddenGmPanelBackRow(session.leagueId, session.returnToTeam || session.sideA.team)] };
}

// ---------------------------------------------------------------------------
// Compare Players — reuses the Team -> Player picker twice, no new UI pattern
// ---------------------------------------------------------------------------
const maddenCompareSessions = new Map();

const maddenTradeWizardSessions = new Map();

async function resolveMaddenPickerLeague(flow, idOrToken) {
  if (flow === 'compareA' || flow === 'compareB') {
    const session = maddenCompareSessions.get(idOrToken);
    if (!session) return null;
    return getLeagueById(session.leagueId);
  }
  if (flow === 'wizardA' || flow === 'wizardB') {
    const session = maddenTradeWizardSessions.get(idOrToken);
    if (!session) return null;
    return getLeagueById(session.leagueId);
  }
  return getLeagueById(idOrToken);
}

// ---------------------------------------------------------------------------
// Browse Players — full pagination/sort/position filter/click-to-view, same
// mechanics as the Trade Block Board rather than a second bespoke pattern.
// ---------------------------------------------------------------------------
const maddenPlayerBrowseSessions = new Map();
const MADDEN_BROWSE_PAGE_SIZE = 10;
const MADDEN_BROWSE_SORTS = [
  { value: 'overall', label: 'Sort: Overall', column: 'p.overall DESC NULLS LAST, player_name ASC' },
  { value: 'name', label: 'Sort: Name (A-Z)', column: 'player_name ASC' },
  { value: 'position', label: 'Sort: Position', column: 'p.position ASC NULLS LAST, p.overall DESC NULLS LAST' },
  { value: 'age', label: 'Sort: Age', column: 'p.age ASC NULLS LAST, p.overall DESC NULLS LAST' },
  { value: 'team', label: 'Sort: Team', column: 'resolved_team_name ASC NULLS LAST, p.overall DESC NULLS LAST' },
];

async function getMaddenBrowsePlayers(guildId, leagueId, { position = null, sort = 'overall' } = {}) {
  const sortCol = (MADDEN_BROWSE_SORTS.find(s => s.value === sort) || MADDEN_BROWSE_SORTS[0]).column;
  const result = await pool.query(
    `SELECT p.*,
            COALESCE(NULLIF(p.team_name, ''), NULLIF(t.team_name, '')) AS resolved_team_name,
            COALESCE(NULLIF(CONCAT_WS(' ', p.first_name, p.last_name), ''), p.full_name) AS player_name
     FROM madden_players p
     LEFT JOIN madden_imported_team_stats t
       ON t.guild_id = p.guild_id::text AND t.league_id::text = p.league_id::text AND p.team_id IS NOT NULL AND t.external_team_id::text = p.team_id
     WHERE p.guild_id = $1 AND p.league_id = $2
     ORDER BY ${sortCol}`,
    [String(guildId), String(leagueId)]
  );
  const rows = result.rows || [];
  const wantedPosition = normalizeMaddenFreeAgentFilter(position);
  if (!wantedPosition) return rows;
  return rows.filter(row => maddenFreeAgentPositionMatches(row, wantedPosition));
}

function buildMaddenBrowseEmbed(league, allRows, { page = 0, sort = 'overall', position = null } = {}) {
  const pageSize = MADDEN_BROWSE_PAGE_SIZE;
  const totalPages = Math.max(1, Math.ceil(allRows.length / pageSize));
  const safePage = Math.min(Math.max(page, 0), totalPages - 1);
  const pageRows = allRows.slice(safePage * pageSize, safePage * pageSize + pageSize);
  const sortLabel = (MADDEN_BROWSE_SORTS.find(s => s.value === sort) || MADDEN_BROWSE_SORTS[0]).label.replace('Sort: ', '');
  const positionText = position ? ` • ${normalizeMaddenFreeAgentFilter(position)}` : '';

  const embed = new EmbedBuilder()
    .setTitle(`📋 ${league.league_name} • Browse Players${positionText}`)
    .setColor(0x5865F2)
    .setFooter({ text: `GG Sports • Page ${safePage + 1}/${totalPages} • Sorted by ${sortLabel} • ${allRows.length} total` })
    .setTimestamp();

  if (!allRows.length) {
    embed.setDescription('No players found. Run Operations → Run Sync first.');
    return embed;
  }

  embed.setDescription(maddenSafeEmbedText(pageRows.map((r, i) => {
    const idx = safePage * pageSize + i + 1;
    const team = maddenTeamDisplayName(r.resolved_team_name || r.team_name || 'Free Agent');
    return `**${idx}. ${r.player_name}** — ${team} • ${r.position || 'POS'} • ${r.overall || 'N/A'} OVR${r.age ? ' • Age ' + r.age : ''}`;
  }).join('\n'), 4096));

  return embed;
}

function buildMaddenBrowseComponents(token, page, totalPages, sort, position, pageRows) {
  const posValue = position || 'ALL';

  const navRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder()
      .setCustomId(`madbrowse:page:${token}:${Math.max(0, page - 1)}:prev`)
      .setLabel(`Previous (${page + 1}/${Math.max(1, totalPages)})`)
      .setStyle(ButtonStyle.Secondary)
      .setDisabled(page <= 0),
    new ButtonBuilder()
      .setCustomId(`madbrowse:page:${token}:${Math.min(totalPages - 1, page + 1)}:next`)
      .setLabel(`Next (${page + 1}/${Math.max(1, totalPages)})`)
      .setStyle(ButtonStyle.Primary)
      .setDisabled(page >= totalPages - 1),
  );

  const sortMenu = new StringSelectMenuBuilder()
    .setCustomId(`madbrowse:sort:${token}`)
    .setPlaceholder('Sort by...')
    .addOptions(MADDEN_BROWSE_SORTS.map(s => ({ label: s.label, value: s.value, default: s.value === sort })));

  const posOptions = ['ALL', 'QB', 'HB', 'WR', 'TE', 'OL', 'DL', 'LB', 'DB'].map(p => ({
    label: p === 'ALL' ? 'All Positions' : p,
    value: p,
    default: posValue === p,
  }));
  const posMenu = new StringSelectMenuBuilder()
    .setCustomId(`madbrowse:pos:${token}`)
    .setPlaceholder('Filter position...')
    .addOptions(posOptions);

  const rows = [
    navRow,
    new ActionRowBuilder().addComponents(sortMenu),
    new ActionRowBuilder().addComponents(posMenu),
  ];

  if (pageRows.length) {
    const playerMenu = new StringSelectMenuBuilder()
      .setCustomId(`madbrowse:view:${token}`)
      .setPlaceholder("View a player's full profile...")
      .addOptions(pageRows.slice(0, 25).map(r => ({
        label: String(r.player_name || 'Unknown').slice(0, 100),
        value: String(r.player_name || 'unknown').slice(0, 100),
        description: `${r.position || 'POS'} • ${r.overall || 'N/A'} OVR`.slice(0, 100),
      })));
    rows.push(new ActionRowBuilder().addComponents(playerMenu));
  }

  return rows;
}

function buildMaddenBrowseProfileActionRow(token, leagueId, playerName) {
  return [new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`madbrowse:backlist:${token}`).setLabel('⬅ Back to List').setStyle(ButtonStyle.Secondary),
    new ButtonBuilder()
      .setCustomId('madneg_from_profile:' + leagueId + ':' + encodeURIComponent(String(playerName || '').slice(0, 80)))
      .setLabel('Start Negotiation')
      .setEmoji('🤝')
      .setStyle(ButtonStyle.Primary),
  )];
}

async function renderMaddenBrowsePage(interaction, token, { update = true } = {}) {
  const session = maddenPlayerBrowseSessions.get(token);
  if (!session) {
    const payload = { content: 'This browse session expired. Click **Browse Players** again.', embeds: [], components: [] };
    return update ? interaction.update(payload) : interaction.editReply(payload);
  }
  const league = await getLeagueById(session.leagueId);
  if (!league) {
    const payload = { content: 'League not found.', embeds: [], components: [] };
    return update ? interaction.update(payload) : interaction.editReply(payload);
  }
  const allRows = await getMaddenBrowsePlayers(session.guildId, session.leagueId, { position: session.position, sort: session.sort });
  const pageSize = MADDEN_BROWSE_PAGE_SIZE;
  const totalPages = Math.max(1, Math.ceil(allRows.length / pageSize));
  session.page = Math.min(Math.max(session.page, 0), totalPages - 1);
  const pageRows = allRows.slice(session.page * pageSize, session.page * pageSize + pageSize);
  const payload = {
    content: null,
    embeds: [buildMaddenBrowseEmbed(league, allRows, { page: session.page, sort: session.sort, position: session.position })],
    components: buildMaddenBrowseComponents(token, session.page, totalPages, session.sort, session.position, pageRows),
  };
  return update ? interaction.update(payload) : interaction.editReply(payload);
}

function buildMaddenImportedPlayersEmbed(league, rows, filters = {}) {
  const NL = String.fromCharCode(10);
  const hasTeamFilter = !!filters.team;
  const filterText = [
    filters.team ? 'Team: ' + filters.team : null,
    filters.position ? 'Position: ' + filters.position : null,
    filters.dev ? 'Dev: ' + filters.dev : null,
  ].filter(Boolean).join(' • ');

  const body = hasTeamFilter
    ? buildMaddenRosterGroupedText(rows).slice(0, 3900)
    : rows.map((player, index) => formatMaddenImportedPlayerLine(player, index)).join(NL).slice(0, 3900);

  return new EmbedBuilder()
    .setTitle((hasTeamFilter ? 'Madden Roster' : 'Madden Imported Players') + ' • ' + league.league_name)
    .setColor(0xFEE75C)
    .setDescription((filterText ? '_' + filterText + '_' + NL + NL : '') + (body || 'No imported Madden players found yet. Use Operations → Run Sync.'))
    .setFooter({ text: `GG Sports • Madden Players • Dev-sorted • Showing ${Math.min(rows.length, 50)}` })
    .setTimestamp();
}


function summarizeMaddenRosterRows(rows = []) {
  const total = rows.length;
  const avgOvr = total ? (rows.reduce((sum, p) => sum + Number(p.overall || 0), 0) / total).toFixed(1) : '0.0';
  const counts = { xfactor: 0, superstar: 0, star: 0, hidden: 0, normal: 0 };

  for (const player of rows) {
    const dev = String(player.dev_trait || '').toLowerCase();
    if (dev.includes('x-factor') || dev.includes('xfactor')) counts.xfactor += 1;
    else if (dev.includes('superstar')) counts.superstar += 1;
    else if (dev === 'star' || dev.includes('star')) counts.star += 1;
    else if (dev.includes('hidden')) counts.hidden += 1;
    else counts.normal += 1;
  }

  return { total, avgOvr, counts };
}

function maddenRosterEmbedColor(rows = []) {
  const best = Math.max(0, ...rows.map(player => getMaddenDevTraitSortValue(player.dev_trait)));
  if (best >= 5) return 0xED4245;
  if (best >= 4) return 0xFEE75C;
  if (best >= 3) return 0xC0C0C0;
  if (best >= 2) return 0x5865F2;
  return 0xCD7F32;
}

function buildMaddenRosterSummaryText(rows = []) {
  const summary = summarizeMaddenRosterRows(rows);
  return [
    `**Players:** ${summary.total}`,
    `**Avg OVR:** ${summary.avgOvr}`,
    `${DEV_EMOJIS.xfactor} X-Factor: ${summary.counts.xfactor}`,
    `${DEV_EMOJIS.superstar} Superstar: ${summary.counts.superstar}`,
    `${DEV_EMOJIS.star} Star: ${summary.counts.star}`,
    `${DEV_EMOJIS.hidden} Hidden: ${summary.counts.hidden}`,
    `${DEV_EMOJIS.normal} Normal: ${summary.counts.normal}`,
  ].join('\n');
}

function buildMaddenCornerstonesText(rows = []) {
  const featured = [...rows]
    .sort((a, b) =>
      getMaddenDevTraitSortValue(b.dev_trait) - getMaddenDevTraitSortValue(a.dev_trait) ||
      Number(b.overall || 0) - Number(a.overall || 0) ||
      String(a.player_name || a.full_name || '').localeCompare(String(b.player_name || b.full_name || ''))
    )
    .slice(0, 5);

  if (!featured.length) return 'No cornerstone players found.';

  return featured.map((player, index) => {
    const name = player.player_name || maddenPlayerDisplayName(player);
    const pos = player.position || 'POS';
    const ovr = player.overall !== null && player.overall !== undefined ? player.overall : 'N/A';
    const age = player.age ? ` • Age ${player.age}` : '';
    return `${index + 1}. ${name} — ${pos} • ${ovr} OVR • ${maddenPlayerDevEmojiOnly(player.dev_trait)}${age}`;
  }).join('\n');
}


function splitMaddenEmbedFieldText(text, maxLength = 1000) {
  const lines = String(text || '').split('\n');
  const chunks = [];
  let current = '';

  for (const line of lines) {
    const next = current ? current + '\n' + line : line;
    if (next.length > maxLength) {
      if (current) chunks.push(current);
      current = line.length > maxLength ? line.slice(0, maxLength) : line;
    } else {
      current = next;
    }
  }

  if (current) chunks.push(current);
  return chunks.length ? chunks : ['No data found.'];
}


function maddenComparePair(label, aValue, bValue, higherIsBetter = true) {
  const av = Number(aValue || 0);
  const bv = Number(bValue || 0);
  let aMark = '➖';
  let bMark = '➖';
  if (av !== bv) {
    const aWins = higherIsBetter ? av > bv : av < bv;
    aMark = aWins ? '✅' : '';
    bMark = aWins ? '' : '✅';
  }
  return `**${label}:** ${aMark} ${aValue ?? 'N/A'} vs ${bMark} ${bValue ?? 'N/A'}`;
}

function maddenCompareText(label, aValue, bValue) {
  return `**${label}:** ${aValue || 'N/A'} vs ${bValue || 'N/A'}`;
}

function maddenStatOfType(rows = [], type) {
  return (rows || []).find(row => row.stat_type === type) || {};
}

function maddenPlayerCompareMode(a, b) {
  const pa = String(a?.position || '').toUpperCase();
  const pb = String(b?.position || '').toUpperCase();
  if (pa === 'QB' || pb === 'QB') return 'passing';
  if (['HB','RB','FB'].includes(pa) || ['HB','RB','FB'].includes(pb)) return 'rushing';
  if (['WR','TE'].includes(pa) || ['WR','TE'].includes(pb)) return 'receiving';
  return 'defense';
}

function maddenPlayerMini(player) {
  const name = player.player_name || maddenPlayerDisplayName(player);
  const team = player.resolved_team_name || player.team_name || 'FA';
  const abbr = getMaddenTeamAbbrev(team) || team;
  const age = player.age ? ` • Age ${player.age}` : '';
  const ovr = player.overall !== null && player.overall !== undefined ? `${player.overall} OVR` : 'OVR N/A';
  return `**${name}**\n${abbr} • ${player.position || 'POS'} • ${ovr} • ${maddenPlayerDevBadge(player.dev_trait)}${age}`;
}


const MADDEN_DRAFT_PICK_VALUE_TABLE = {
  1: [3000, 2600, 2200, 1800, 1700, 1600, 1500, 1400, 1350, 1300, 1250, 1200, 1150, 1100, 1050, 1000, 950, 900, 875, 850, 800, 780, 760, 740, 720, 700, 680, 660, 640, 620, 600, 590],
  2: [580, 560, 550, 540, 530, 520, 510, 500, 490, 480, 470, 460, 450, 440, 430, 420, 410, 400, 390, 380, 370, 360, 350, 340, 330, 320, 310, 300, 292, 294, 276, 270],
  3: [265, 260, 255, 250, 245, 240, 235, 230, 225, 220, 215, 210, 205, 200, 195, 190, 185, 180, 175, 170, 165, 160, 155, 150, 145, 140, 136, 132, 128, 124, 120, 116],
  4: [112, 108, 104, 100, 96, 92, 88, 86, 84, 82, 80, 78, 76, 74, 72, 70, 68, 66, 64, 62, 60, 58, 56, 54, 52, 50, 49, 48, 47, 46, 45, 44],
  5: [43, 42, 41, 40, 39.5, 39, 38.5, 38, 37.5, 37, 36.5, 36, 35.5, 35, 34.5, 34, 33.5, 33, 32.6, 32.2, 31.8, 31.4, 31, 30.6, 30.2, 29.8, 29.4, 29, 28.6, 28.2, 27.8, 27.4],
  6: [27, 26.6, 26.2, 25.8, 25.4, 25, 24.6, 24.2, 23.8, 23.4, 23, 22.6, 22.2, 21.8, 21.4, 21, 20.6, 20.2, 19.8, 19.4, 19, 18, 18.2, 17.8, 17.4, 17, 16.6, 16.2, 15.8, 15.4, 15, 14.6],
  7: [14.2, 13.8, 13.4, 13, 12.6, 12.2, 11.8, 11.4, 11, 10.6, 10.2, 9.8, 9.4, 9, 8.6, 8.2, 7.8, 7.4, 7, 6.6, 6.2, 5.8, 5.4, 5, 4.6, 4.2, 3.8, 3.4, 3, 2.6, 2.2, 1.8],
};


function maddenDraftPickTeamKeys(teamName) {
  const raw = String(teamName || '').trim();
  const abbr = getMaddenTeamAbbrev(raw) || raw;
  const keys = new Set();
  if (raw) keys.add(raw.toLowerCase());
  if (abbr) keys.add(String(abbr).toLowerCase());
  return [...keys].filter(Boolean);
}

function maddenDraftPickOrderSort(a, b) {
  const aw = Number(a.wins || 0);
  const bw = Number(b.wins || 0);
  if (aw !== bw) return aw - bw;
  const al = Number(a.losses || 0);
  const bl = Number(b.losses || 0);
  if (al !== bl) return bl - al;
  const apd = Number(a.points_for || 0) - Number(a.points_against || 0);
  const bpd = Number(b.points_for || 0) - Number(b.points_against || 0);
  if (apd !== bpd) return apd - bpd;
  return String(a.team_name || '').localeCompare(String(b.team_name || ''));
}

async function getMaddenProjectedDraftSlotMap(guildId, leagueId) {
  const map = new Map();
  const put = (teamName, slot) => {
    if (!teamName || !slot) return;
    for (const key of maddenDraftPickTeamKeys(teamName)) map.set(key, Number(slot));
  };

  const teamsResult = await pool.query(
    `SELECT team_name, wins, losses, ties, points_for, points_against
     FROM madden_imported_team_stats
     WHERE guild_id = $1::text AND league_id::text = $2::text
     ORDER BY wins ASC, losses DESC, (points_for - points_against) ASC, team_name ASC`,
    [guildId, String(leagueId)]
  ).catch(() => ({ rows: [] }));

  const teams = (teamsResult.rows || []).map(row => ({ ...row, team_name: row.team_name }));
  if (!teams.length) return map;

  const teamByKey = new Map();
  for (const team of teams) {
    for (const key of maddenDraftPickTeamKeys(team.team_name)) teamByKey.set(key, team);
  }

  // 7J-DRAFTORDERSEASONSCOPE: real bug, confirmed live — found during a full
  // sweep for this exact pattern (per Hxxdie, after several rounds of
  // finding this same shape one instance at a time). No season_key filter
  // at all: without it, a prior season's completed playoff games (including
  // its actual Super Bowl) are indistinguishable from this season's, which
  // could assign draft slots 31/32 and the late playoff-loser slots based
  // on last season's results — potentially before this season's real
  // playoffs have even started. Same pattern already fixed in
  // getMaddenSuperBowlResult (7J-SEASONSCOPESB) — mirrors that function's
  // approach for resolving a season_key from just a guildId/leagueId pair.
  const projSeasonYearResult = await pool.query(
    `SELECT madden_season_year FROM league_settings WHERE league_id = $1`,
    [leagueId]
  ).catch(() => ({ rows: [] }));
  const projSeasonKey = await getMaddenCurrentSeasonKey({
    league_id: leagueId,
    madden_season_year: projSeasonYearResult.rows[0]?.madden_season_year ?? null,
  }).catch(() => null);

  const playoffResult = await pool.query(
    `SELECT week_label, home_team, away_team, home_score, away_score, status
     FROM madden_imported_games
     WHERE guild_id = $1::text
       AND league_id::text = $2::text
       AND week_label IN ('Wild Card','Div. Playoff','Conf. Playoff','Super Bowl')
       AND LOWER(COALESCE(status, '')) IN ('final','completed','home_win','away_win')
       AND home_score IS NOT NULL
       AND away_score IS NOT NULL
       AND ($3::text IS NULL OR season_key = $3::text)`,
    [guildId, String(leagueId), projSeasonKey]
  ).catch(() => ({ rows: [] }));

  const playoffTeams = new Set();
  const losersByRound = { 'Wild Card': [], 'Div. Playoff': [], 'Conf. Playoff': [], 'Super Bowl': [] };
  let superBowlWinner = null;
  let superBowlLoser = null;

  for (const game of playoffResult.rows || []) {
    const home = game.home_team;
    const away = game.away_team;
    if (home) playoffTeams.add(home);
    if (away) playoffTeams.add(away);
    const hs = Number(game.home_score || 0);
    const as = Number(game.away_score || 0);
    if (hs === as) continue;
    const winner = hs > as ? home : away;
    const loser = hs > as ? away : home;
    if (game.week_label === 'Super Bowl') {
      superBowlWinner = winner;
      superBowlLoser = loser;
    } else if (losersByRound[game.week_label]) {
      losersByRound[game.week_label].push(loser);
    }
  }

  const assigned = new Set();
  const assignTeams = (teamNames, startSlot) => {
    const rows = teamNames
      .map(name => teamByKey.get(String(name || '').toLowerCase()) || teams.find(t => String(t.team_name || '').toLowerCase() === String(name || '').toLowerCase()) || { team_name: name })
      .filter(row => row && row.team_name)
      .sort(maddenDraftPickOrderSort);
    rows.forEach((row, idx) => {
      put(row.team_name, startSlot + idx);
      assigned.add(String(row.team_name || '').toLowerCase());
    });
  };

  const sbPlayed = Boolean(superBowlWinner && superBowlLoser);
  if (sbPlayed) {
    put(superBowlLoser, 31);
    put(superBowlWinner, 32);
    assigned.add(String(superBowlLoser).toLowerCase());
    assigned.add(String(superBowlWinner).toLowerCase());
  }

  // Completed playoff loser ranges. These naturally lock in as rounds complete.
  assignTeams(losersByRound['Wild Card'], 19);
  assignTeams(losersByRound['Div. Playoff'], 25);
  assignTeams(losersByRound['Conf. Playoff'], 29);

  const nonAssignedPlayoff = [...playoffTeams].filter(name => !assigned.has(String(name || '').toLowerCase()));
  if (!sbPlayed && nonAssignedPlayoff.length) {
    const start = Math.max(19, 33 - nonAssignedPlayoff.length);
    assignTeams(nonAssignedPlayoff, start);
  }

  const nonPlayoff = teams
    .filter(team => !playoffTeams.has(team.team_name) && !assigned.has(String(team.team_name || '').toLowerCase()))
    .sort(maddenDraftPickOrderSort);
  nonPlayoff.forEach((team, idx) => put(team.team_name, idx + 1));

  // Fallback for any teams that did not receive a postseason-aware slot.
  let nextSlot = 1;
  for (const team of teams.sort(maddenDraftPickOrderSort)) {
    const keys = maddenDraftPickTeamKeys(team.team_name);
    if (keys.some(key => map.has(key))) continue;
    while ([...map.values()].includes(nextSlot) && nextSlot <= 32) nextSlot += 1;
    put(team.team_name, Math.min(nextSlot, 32));
    nextSlot += 1;
  }

  return map;
}

function getMaddenProjectedDraftSlot(slotMap, teamName) {
  if (!slotMap || !teamName) return null;
  for (const key of maddenDraftPickTeamKeys(teamName)) {
    if (slotMap.has(key)) return Number(slotMap.get(key));
  }
  return null;
}

async function buildMaddenDraftPickAutocompleteChoices(input = '', context = {}) {
  const query = String(input || '').toLowerCase().trim();
  const teamName = context.teamName || '';
  if (!teamName) return [];
  const slotMap = context.slotMap || await getMaddenProjectedDraftSlotMap(context.guildId, context.leagueId);
  const slot = getMaddenProjectedDraftSlot(slotMap, teamName);
  if (!slot) return [];
  const years = [2026, 2027, 2028];
  const teamLabel = maddenTeamDisplayName(teamName);
  const abbr = getMaddenTeamAbbrev(teamName) || teamName;
  const choices = [];
  for (const year of years) {
    for (let round = 1; round <= 7; round++) {
      const value = `${year}|${abbr}|${round}|${slot}`;
      const pick = parseMaddenDraftPickAsset(value);
      const name = `${year} ${teamLabel} Round ${round} Pick ${slot} • Value ${Number(pick?.valueScore || 0).toFixed(1)}`;
      choices.push({ name: name.slice(0, 100), value });
    }
  }
  if (!query) return choices;
  return choices.filter(choice =>
    String(choice.name || '').toLowerCase().includes(query) ||
    String(choice.value || '').toLowerCase().includes(query)
  );
}

function maddenDraftPickRoundMedianValue(round) {
  const values = MADDEN_DRAFT_PICK_VALUE_TABLE[Number(round)] || [];
  if (!values.length) return 0;
  const sorted = [...values].map(Number).sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function maddenDraftPickFutureMultiplier(year) {
  const y = Number(year || 0);
  if (!y || y <= 2026) return 1;
  if (y === 2027) return 0.5;
  return 0.5;
}

function parseMaddenDraftPickAsset(input) {
  const raw = String(input || '').trim();
  if (!raw) return null;

  let year = 2026;
  let round = null;
  let pick = null;
  let team = null;

  if (raw.includes('|')) {
    const parts = raw.split('|').map(part => part.trim()).filter(Boolean);
    year = Number(parts[0] || 2026);
    team = parts[1] || null;
    round = Number(parts[2] || 0);
    pick = Math.max(1, Math.min(32, Number(parts[3] || 0)));
  } else {
    const yearMatch = raw.match(/20\d{2}/);
    year = yearMatch ? Number(yearMatch[0]) : 2026;
    const slotMatch = raw.match(/(?:20\d{2})?\s*([1-7])\s*[.\-:]\s*(\d{1,2})/);
    if (slotMatch) {
      round = Number(slotMatch[1]);
      pick = Math.max(1, Math.min(32, Number(slotMatch[2])));
    } else {
      const roundMatch = raw.match(/\b([1-7])(?:st|nd|rd|th)?\b/i);
      round = roundMatch ? Number(roundMatch[1]) : null;
    }
  }

  if (!round || round < 1 || round > 7) return null;

  const base = pick
    ? Number((MADDEN_DRAFT_PICK_VALUE_TABLE[round] || [])[pick - 1] || maddenDraftPickRoundMedianValue(round))
    : maddenDraftPickRoundMedianValue(round);
  const multiplier = maddenDraftPickFutureMultiplier(year);
  const valueScore = Number((base * multiplier).toFixed(1));
  const teamText = team ? `${maddenTeamDisplayName(team)} ` : '';
  const slotText = pick ? ` Pick ${pick}` : '';
  const label = `${year} ${teamText}Round ${round}${slotText} Pick`.replace(/\s+/g, ' ').trim();
  return { raw, year, round, pick, team, base, multiplier, valueScore, label, tradeTier: 'Draft Pick' };
}

function maddenDraftPickAssetLine(pick, index = 0) {
  const baseText = pick.pick ? ` • Base ${Number(pick.base || 0).toFixed(1)}` : '';
  return `${index + 1}. **${pick.label}** — Trade Value **${Number(pick.valueScore || 0).toFixed(1)}**${baseText}${Number(pick.multiplier || 1) !== 1 ? ` • ${pick.multiplier}x future` : ''}`;
}

function maddenTradeFinderPickPool(teamName = null, slotMap = null) {
  const picks = [];
  const slot = getMaddenProjectedDraftSlot(slotMap, teamName) || null;
  const abbr = teamName ? (getMaddenTeamAbbrev(teamName) || teamName) : null;
  for (const year of [2026, 2027, 2028]) {
    for (let round = 1; round <= 7; round++) {
      const raw = slot && abbr ? `${year}|${abbr}|${round}|${slot}` : `${year} ${round}`;
      const pick = parseMaddenDraftPickAsset(raw);
      if (pick) picks.push(pick);
    }
  }
  return picks;
}


function maddenTradeNormalizeTeamKey(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const abbr = getMaddenTeamAbbrev(raw) || raw;
  return String(abbr || raw).trim().toLowerCase();
}


// 7J-10BM: Depth-chart based team needs engine.
// Standardized Madden front-office groups. LS is intentionally excluded from need models.
function maddenPositionNeedGroup(position) {
  const p = String(position || '').toUpperCase();
  if (['LS'].includes(p)) return 'IGNORE';
  if (['QB'].includes(p)) return 'QB';
  if (['HB', 'RB', 'FB'].includes(p)) return 'HB';
  if (['WR'].includes(p)) return 'WR';
  if (['TE'].includes(p)) return 'TE';
  if (['LT', 'RT'].includes(p)) return 'OT';
  if (['LG', 'C', 'RG'].includes(p)) return 'IOL';
  if (['LEDGE', 'REDGE', 'EDGE', 'LE', 'RE', 'LOLB', 'ROLB', 'SAM', 'WILL'].includes(p)) return 'EDGE';
  if (['DT'].includes(p)) return 'DT';
  if (['MIKE', 'MLB'].includes(p)) return 'LB';
  if (['CB'].includes(p)) return 'CB';
  if (['FS', 'SS', 'DB'].includes(p)) return 'S';
  if (['K', 'P'].includes(p)) return 'K/P';
  return p || 'OTHER';
}

const MADDEN_NEED_GROUP_CONFIG = {
  QB: { starters: 1, depth: 1, weight: 1.20, sort: 1 },
  HB: { starters: 1, depth: 2, weight: 0.95, sort: 2 },
  WR: { starters: 3, depth: 2, weight: 1.00, sort: 3 },
  TE: { starters: 1, depth: 1, weight: 0.85, sort: 4 },
  OT: { starters: 2, depth: 1, weight: 1.00, sort: 5 },
  IOL: { starters: 3, depth: 1, weight: 0.95, sort: 6 },
  EDGE: { starters: 2, depth: 1, weight: 1.10, sort: 7 },
  DT: { starters: 2, depth: 1, weight: 0.95, sort: 8 },
  LB: { starters: 2, depth: 1, weight: 0.85, sort: 9 },
  CB: { starters: 3, depth: 2, weight: 1.05, sort: 10 },
  S: { starters: 2, depth: 1, weight: 0.95, sort: 11 },
  'K/P': { starters: 2, depth: 0, weight: 0.35, sort: 12 },
};

function maddenNeedGroupSort(group) {
  return MADDEN_NEED_GROUP_CONFIG[group]?.sort || 999;
}

function maddenAverageOverall(players) {
  const list = (players || []).filter(Boolean);
  if (!list.length) return 0;
  return list.reduce((sum, p) => sum + Number(p.overall || 0), 0) / list.length;
}

function maddenAverageValue(players) {
  const list = (players || []).filter(Boolean);
  if (!list.length) return 0;
  return list.reduce((sum, p) => sum + Number(calculateMaddenPlayerValue(p).valueScore || 0), 0) / list.length;
}

// 7J-10BU: User-friendly need labels. Internal need scores stay hidden from users.
function maddenTeamNeedSeverity(score) {
  const n = Number(score || 0);
  if (n >= 30) return { emoji: '🔴', label: 'Critical Need', stars: '★★★★★' };
  if (n >= 22) return { emoji: '🟠', label: 'Major Need', stars: '★★★★☆' };
  if (n >= 14) return { emoji: '🟡', label: 'Moderate Need', stars: '★★★☆☆' };
  if (n >= 8) return { emoji: '🟢', label: 'Depth Need', stars: '★★☆☆☆' };
  return { emoji: '✅', label: 'Stable', stars: '★☆☆☆☆' };
}


function maddenTeamNeedUserLine(row, index, includeDepth = true) {
  const severity = maddenTeamNeedSeverity(row?.needScore);
  const starter = row?.starterAvg ? `${Number(row.starterAvg).toFixed(1)} starter` : 'no starter';
  const depth = row?.depthAvg ? `${Number(row.depthAvg).toFixed(1)} depth` : 'thin depth';
  const details = includeDepth ? ` • ${starter} • ${depth} • ${row?.count || 0} players` : ` • ${starter}`;
  return `${index + 1}. ${severity.emoji} **${row.position}** — ${severity.label} ${severity.stars}${details}`;
}

function maddenBuildNeedRow(teamKey, teamName, position, players) {
  const config = MADDEN_NEED_GROUP_CONFIG[position] || { starters: 2, depth: 1, weight: 0.75, sort: 999 };
  const sorted = [...(players || [])].sort((a, b) => Number(b.overall || 0) - Number(a.overall || 0));
  const starters = sorted.slice(0, config.starters);
  const depth = sorted.slice(config.starters, config.starters + config.depth);
  const starterAvg = maddenAverageOverall(starters);
  const depthAvg = maddenAverageOverall(depth);
  const avgOverall = maddenAverageOverall(sorted.slice(0, Math.max(1, config.starters + config.depth)));
  const avgValue = maddenAverageValue(sorted.slice(0, Math.max(1, config.starters + config.depth)));
  const missingStarters = Math.max(0, Number(config.starters || 1) - starters.length);
  const missingDepth = Math.max(0, Number(config.depth || 0) - depth.length);

  // Need score favors weak starter quality first, then weak depth, then missing bodies.
  const starterWeakness = Math.max(0, 88 - (starterAvg || 55));
  const depthWeakness = Math.max(0, 78 - (depthAvg || 50));
  const shortagePenalty = (missingStarters * 18) + (missingDepth * 8);
  const needScore = Math.round(Math.min(100, ((starterWeakness * 1.6) + (depthWeakness * 0.65) + shortagePenalty) * Number(config.weight || 1)));
  const strengthScore = Math.round((starterAvg || 0) + Math.min(10, depthAvg ? (depthAvg - 70) / 2 : 0) + Math.min(8, avgValue / 900));

  return {
    teamKey,
    teamName,
    position,
    players: sorted,
    starters,
    depth,
    count: sorted.length,
    requiredStarters: config.starters,
    requiredDepth: config.depth,
    starterAvg,
    depthAvg,
    avgOverall,
    avgValue,
    needScore,
    strengthScore,
  };
}

async function buildMaddenTeamNeedsModel(guildId, leagueId, teamFilter = null) {
  const rows = await getMaddenTradeFinderPlayerRows(guildId, leagueId, teamFilter || null);
  const grouped = new Map();
  const teams = new Map();

  for (const row of rows) {
    const position = maddenPositionNeedGroup(row.position);
    if (position === 'IGNORE' || position === 'OTHER') continue;
    const teamName = row.resolved_team_name || row.team_name || 'Unknown';
    const teamKey = maddenTradeNormalizeTeamKey(teamName);
    if (!teamKey) continue;
    if (!teams.has(teamKey)) teams.set(teamKey, { teamKey, teamName, players: [] });
    teams.get(teamKey).players.push(row);
    const key = `${teamKey}:${position}`;
    if (!grouped.has(key)) grouped.set(key, { teamKey, teamName, position, players: [] });
    grouped.get(key).players.push(row);
  }

  const rowsByTeam = new Map();
  for (const team of teams.values()) rowsByTeam.set(team.teamKey, []);

  for (const team of teams.values()) {
    for (const position of Object.keys(MADDEN_NEED_GROUP_CONFIG)) {
      const key = `${team.teamKey}:${position}`;
      const players = grouped.get(key)?.players || [];
      const row = maddenBuildNeedRow(team.teamKey, team.teamName, position, players);
      rowsByTeam.get(team.teamKey).push(row);
    }
  }

  const byTeam = new Map();
  for (const team of teams.values()) {
    const positionRows = (rowsByTeam.get(team.teamKey) || [])
      .filter(row => row.position !== 'K/P');
    const weaknesses = [...positionRows]
      .sort((a, b) => b.needScore - a.needScore || a.starterAvg - b.starterAvg || maddenNeedGroupSort(a.position) - maddenNeedGroupSort(b.position))
      .slice(0, 6);
    const strengths = [...positionRows]
      .sort((a, b) => b.strengthScore - a.strengthScore || b.starterAvg - a.starterAvg || maddenNeedGroupSort(a.position) - maddenNeedGroupSort(b.position))
      .slice(0, 6);
    const teamAvgOverall = team.players.reduce((sum, p) => sum + Number(p.overall || 0), 0) / Math.max(1, team.players.length);
    // Direction is intentionally conservative when standings context is unavailable.
    const isContender = teamAvgOverall >= 74.5;
    const isRebuilder = teamAvgOverall <= 72.5;
    byTeam.set(team.teamKey, { ...team, positions: positionRows, weaknesses, strengths, teamAvgOverall, isContender, isRebuilder });
  }

  return byTeam;
}

function maddenTeamNeedScore(teamNeed, targetPosition) {
  if (!teamNeed) return { score: 0, label: 'Unknown need' };
  const targetGroup = maddenPositionNeedGroup(targetPosition);
  if (!targetGroup || ['IGNORE', 'OTHER', 'K/P'].includes(targetGroup)) return { score: 0, label: `${targetGroup || 'POS'}: neutral` };
  const row = (teamNeed.positions || []).find(item => item.position === targetGroup);
  if (!row) return { score: 0, label: `${targetGroup}: unknown` };
  const rank = (teamNeed.weaknesses || []).findIndex(item => item.position === targetGroup) + 1;
  const rankText = rank > 0 ? `need #${rank}` : 'depth area';
  return {
    score: Math.round(Number(row.needScore || 0)),
    label: `${targetGroup} ${rankText} • Need ${Math.round(Number(row.needScore || 0))}`,
    group: targetGroup,
    rank: rank || null,
    row,
  };
}


// 7J-10BN: Availability engine for realistic GM/trade recommendations.
function maddenPlayerAvailability(player, teamNeed = null) {
  const overall = Number(player?.overall || 0);
  const age = Number(player?.age || 0);
  const value = calculateMaddenPlayerValue(player);
  const valueScore = Number(value.valueScore || 0);
  const devSort = getMaddenDevTraitSortValue(player?.dev_trait);
  const group = maddenPositionNeedGroup(player?.position);
  const teamGroup = teamNeed?.positions?.find(row => row.position === group);
  const strengthRank = teamNeed ? ((teamNeed.strengths || []).findIndex(row => row.position === group) + 1) : 0;
  const needRank = teamNeed ? ((teamNeed.weaknesses || []).findIndex(row => row.position === group) + 1) : 0;
  const yearsLeft = Number(value.yearsLeft || 0);

  let score = 48;
  const reasons = [];
  let marketClass = 'Normal';
  let hardHideTarget = false;

  // 7J-10BU: Realistic trade market protections.
  const isFranchiseQb = group === 'QB' && overall >= 90 && (!age || age <= 34) && devSort >= 3;
  const isEliteQb = group === 'QB' && overall >= 88 && (!age || age <= 30) && devSort >= 3;
  const isYoungCoreStar = age > 0 && age <= 27 && (overall >= 90 || valueScore >= 1600 || devSort >= 4);
  const isYoungHighAsset = age > 0 && age <= 25 && (overall >= 84 || valueScore >= 900) && devSort >= 3;
  const isPremiumPrimeAsset = overall >= 95 && (!age || age <= 30);
  const isContenderCore = teamNeed?.isContender && (overall >= 88 || valueScore >= 1100) && age < 32;
  const isRebuilderVeteran = teamNeed?.isRebuilder && age >= 29 && overall >= 78;

  if (isFranchiseQb) {
    score = Math.min(score, 4);
    marketClass = 'Untouchable Franchise QB';
    reasons.push('franchise QB');
    hardHideTarget = true;
  } else if (isEliteQb) {
    score -= 35;
    marketClass = 'Very Low Availability QB';
    reasons.push('core QB');
    hardHideTarget = true;
  }

  if (isYoungCoreStar) {
    score -= 38;
    marketClass = marketClass === 'Normal' ? 'Core Young Asset' : marketClass;
    reasons.push('core young asset');
    hardHideTarget = hardHideTarget || overall >= 92 || valueScore >= 2000;
  } else if (isYoungHighAsset) {
    score -= 24;
    marketClass = marketClass === 'Normal' ? 'Young Building Block' : marketClass;
    reasons.push('young building block');
  }

  if (isPremiumPrimeAsset) {
    score -= 28;
    marketClass = marketClass === 'Normal' ? 'Premium Core Asset' : marketClass;
    reasons.push('premium core');
  }

  if (isContenderCore) {
    score -= 22;
    reasons.push('contender core');
  }

  // Older/contract-risk/depth/surplus players are more realistic trade pieces.
  if (isRebuilderVeteran) {
    score += 26;
    reasons.push('rebuilder veteran');
  } else if (age >= 32) {
    score += 28;
    reasons.push('veteran');
  } else if (age >= 29) {
    score += 16;
    reasons.push('older asset');
  }
  if (yearsLeft === 1) {
    score += 14;
    reasons.push('contract year');
  } else if (yearsLeft === 0) {
    score += 8;
    reasons.push('short contract');
  }
  if (strengthRank && strengthRank <= 3) {
    score += 16;
    reasons.push('surplus group');
  }
  if (needRank && needRank <= 3) {
    score -= 14;
    reasons.push('team need');
  }
  if (teamGroup && Number(teamGroup.count || 0) > Number((MADDEN_NEED_GROUP_CONFIG[group] || {}).starters || 1) + Number((MADDEN_NEED_GROUP_CONFIG[group] || {}).depth || 1) + 2) {
    score += 8;
    reasons.push('deep position');
  }
  if (overall < 78) score += 12;
  if (valueScore < 650) score += 10;

  score = Math.max(0, Math.min(100, Math.round(score)));
  let label = 'Medium';
  if (score >= 75) label = 'High';
  else if (score >= 55) label = 'Medium';
  else if (score >= 30) label = 'Low';
  else if (score >= 10) label = 'Very Low';
  else label = 'Untouchable';

  const hideAsTarget = hardHideTarget || score < 18;
  return { score, label, hideAsTarget, reasons: [...new Set(reasons)], valueScore, marketClass };
}




// 7J-10BO: GM Assistant 2.0 target scoring.
// Targets should be useful upgrades, not simply the most available players at a needed position.
function maddenNeedStarterForGroup(teamNeed, group) {
  if (!teamNeed || !group) return null;
  return (teamNeed.positions || []).find(row => row.position === group) || null;
}

function maddenGmTargetScore(candidate, targetTeamNeed, sourceTeamNeed = null) {
  const group = maddenPositionNeedGroup(candidate?.position);
  const needRow = maddenNeedStarterForGroup(targetTeamNeed, group);
  const availability = maddenPlayerAvailability(candidate, sourceTeamNeed);
  const value = calculateMaddenPlayerValue(candidate);
  const overall = Number(candidate?.overall || 0);
  const starterAvg = Number(needRow?.starterAvg || 72);
  const upgrade = overall - starterAvg;
  const needScore = Number(needRow?.needScore || 0);
  const valueScore = Number(value.valueScore || 0);

  // 7J-10BU: realistic market score. Need fit and availability now matter more than raw star power.
  const needFit = Math.min(40, needScore * 1.05);
  const upgradeScore = Math.max(-18, Math.min(25, upgrade * 1.4));
  const availabilityScore = Math.min(25, Number(availability.score || 0) * 0.25);
  const valueEfficiency = valueScore > 0 ? Math.max(0, Math.min(10, 10 - (valueScore / 1200))) : 4;

  let score = needFit + upgradeScore + availabilityScore + valueEfficiency;
  if (availability.hideAsTarget) score -= 80;
  if (Number(availability.score || 0) < 30) score -= 25;
  if (upgrade < 1) score -= 28;
  if (upgrade < 4 && overall < 86) score -= 18;

  let tier = '✅ Realistic Target';
  if (Number(availability.score || 0) >= 55 && upgrade >= 10 && overall >= 86) tier = '🔥 Major Upgrade';
  if (Number(availability.score || 0) >= 70 && upgrade >= 6) tier = '✅ Realistic Target';
  if (Number(availability.score || 0) < 35) tier = 'Low Availability Option';

  return { score, tier, upgrade, needScore, availability, value, group, needRow, needFit, upgradeScore, availabilityScore, valueEfficiency };
}

function maddenGmTargetLine(item, index) {
  const row = item.row;
  const team = getMaddenTeamAbbrev(row.resolved_team_name || row.team_name) || row.team_name || 'FA';
  const upgradeText = Number.isFinite(Number(item.upgrade)) ? ` • Upgrade ${item.upgrade >= 0 ? '+' : ''}${Number(item.upgrade).toFixed(1)}` : '';
  const availabilityLabel = item.availability?.label || 'Medium';
  const marketNote = item.availability?.marketClass && item.availability.marketClass !== 'Normal' ? ` (${item.availability.marketClass})` : '';
  return `${index + 1}. **${maddenValuePlayerName(row)}** — ${team} ${row.position || 'POS'} • ${row.overall || 'N/A'} OVR • ${Number(item.value?.valueScore || 0).toFixed(0)} • ${availabilityLabel} availability${marketNote}${upgradeText}`;
}


// 7J-10BV: Suggested trade package engine for GM Assistant target rows.
function maddenGmAssetShortLabel(asset) {
  if (!asset) return 'Unknown Asset';
  if (asset.type === 'pick') return asset.pick?.label || 'Draft Pick';
  const row = asset.row || asset.player || asset;
  const team = getMaddenTeamAbbrev(row.resolved_team_name || row.team_name) || row.resolved_team_name || row.team_name || 'FA';
  return `${maddenValuePlayerName(row)} (${team} ${row.position || 'POS'})`;
}

function maddenGmPackageLikelihood(gap, targetItem) {
  const targetValue = Math.max(1, Number(targetItem?.value?.valueScore || calculateMaddenPlayerValue(targetItem?.row || {}).valueScore || 0));
  const pct = Math.abs(Number(gap || 0)) / targetValue;
  const targetAvail = Number(targetItem?.availability?.score || 50);
  if (targetAvail < 18 || pct > 0.55) return 'Very Low';
  if (targetAvail < 32 || pct > 0.35) return 'Low';
  if (pct <= 0.12 && targetAvail >= 45) return 'High';
  return 'Medium';
}

function maddenBuildSuggestedPackageForTarget(targetItem, tradeChips = [], slotMap = null, fromTeamName = null) {
  const targetValue = Number(targetItem?.value?.valueScore || calculateMaddenPlayerValue(targetItem?.row || {}).valueScore || 0);
  if (!targetItem?.row || !targetValue) return null;

  const chips = (tradeChips || [])
    .filter(item => item && !item.protected && item.row)
    .map(item => ({
      type: 'player',
      row: item.row,
      value: Number(item.value?.valueScore || calculateMaddenPlayerValue(item.row).valueScore || 0),
      category: item.category || 'depth',
      availability: item.availability,
      reasons: item.reasons || []
    }))
    .filter(asset => asset.value > 0)
    .sort((a, b) => {
      const pref = { depth: 0, veteran: 1, premium: 2 };
      return (pref[a.category] ?? 1) - (pref[b.category] ?? 1) || Math.abs(a.value - targetValue) - Math.abs(b.value - targetValue);
    })
    .slice(0, 10);

  const pickPool = maddenTradeFinderPickPool(fromTeamName, slotMap)
    .filter(pick => Number(pick.valueScore || 0) > 0)
    .sort((a, b) => Number(b.valueScore || 0) - Number(a.valueScore || 0))
    .slice(0, 16)
    .map(pick => ({ type: 'pick', pick, value: Number(pick.valueScore || 0) }));

  const candidates = [];
  const push = (assets) => {
    const clean = (assets || []).filter(Boolean);
    if (!clean.length || clean.length > 3) return;
    const key = clean.map(asset => asset.type === 'pick' ? `pick:${asset.pick?.label}` : `player:${maddenTradeFinderPlayerKey(asset.row)}`).sort().join('|');
    if (candidates.some(c => c.key === key)) return;
    const total = clean.reduce((sum, asset) => sum + Number(asset.value || 0), 0);
    const gap = total - targetValue;
    const assetPenalty = (clean.length - 1) * 20;
    const premiumPenalty = clean.some(asset => asset.category === 'premium') ? 35 : 0;
    candidates.push({ key, assets: clean, total, gap, score: Math.abs(gap) + assetPenalty + premiumPenalty });
  };

  for (const chip of chips) {
    push([chip]);
    const bestPicks = pickPool
      .sort((a, b) => Math.abs((chip.value + a.value) - targetValue) - Math.abs((chip.value + b.value) - targetValue))
      .slice(0, 4);
    for (const pick of bestPicks) push([chip, pick]);
  }

  for (let i = 0; i < Math.min(chips.length, 8); i++) {
    for (let j = i + 1; j < Math.min(chips.length, 8); j++) {
      const combo = [chips[i], chips[j]];
      const comboTotal = combo[0].value + combo[1].value;
      push(combo);
      const bestPick = pickPool
        .sort((a, b) => Math.abs((comboTotal + a.value) - targetValue) - Math.abs((comboTotal + b.value) - targetValue))[0];
      if (bestPick) push([...combo, bestPick]);
    }
  }

  const best = candidates.sort((a, b) => a.score - b.score || Math.abs(a.gap) - Math.abs(b.gap))[0];
  if (!best) return null;
  return {
    ...best,
    likelihood: maddenGmPackageLikelihood(best.gap, targetItem),
    label: best.assets.map(maddenGmAssetShortLabel).join(' + ')
  };
}

function maddenGmSuggestedPackageText(targetItem, tradeChips = [], slotMap = null, fromTeamName = null) {
  const pkg = maddenBuildSuggestedPackageForTarget(targetItem, tradeChips, slotMap, fromTeamName);
  if (!pkg) return '';
  const gapText = `${pkg.gap >= 0 ? '+' : ''}${Number(pkg.gap || 0).toFixed(0)}`;
  return `\n> 📦 Offer: **${pkg.label}**\n> Value **${Number(pkg.total || 0).toFixed(0)}** • Gap **${gapText}** • Likelihood **${pkg.likelihood}**`;
}

function maddenGmTieredTargetText(scoredTargets, maxTotal = 9) {
  const used = [];
  const sections = [];
  const tierOrder = ['⭐ Franchise Target', '🔥 Major Upgrade', '✅ Realistic Target'];
  for (const tier of tierOrder) {
    const items = scoredTargets.filter(item => item.tier === tier && !used.includes(item)).slice(0, tier === '✅ Realistic Target' ? 4 : 3);
    if (!items.length) continue;
    used.push(...items);
    sections.push(`**${tier}s**\n${items.map((item, index) => maddenGmTargetLine(item, index)).join('\n')}`);
    if (used.length >= maxTotal) break;
  }
  if (!sections.length) {
    const fallback = scoredTargets.slice(0, maxTotal);
    if (fallback.length) sections.push(`**Realistic Options**\n${fallback.map((item, index) => maddenGmTargetLine(item, index)).join('\n')}`);
  }
  return sections.join('\n\n');
}

// 7J-10BQ: Position-aware GM target display and trade-chip engine.
// Keep targets separated by the actual need group so a QB target is not ranked beside an IOL target.
function maddenGmTargetSectionTitle(group, items = []) {
  const bestTier = items.some(item => item.tier === '⭐ Franchise Target')
    ? '⭐'
    : items.some(item => item.tier === '🔥 Major Upgrade')
      ? '🔥'
      : '✅';
  return `${bestTier} ${group} Targets`;
}

function maddenGmPositionAwareTargetSections(scoredTargets, needRows = [], maxGroups = 4, perGroup = 3, tradeChips = null, slotMap = null, fromTeamName = null) {
  const rows = (needRows || []).filter(row => row && row.position && !['IGNORE', 'OTHER', 'K/P'].includes(row.position));
  const sections = [];
  for (const need of rows.slice(0, maxGroups)) {
    const group = need.position;
    const items = (scoredTargets || [])
      .filter(item => item.group === group)
      .sort((a, b) => Number(b.score || 0) - Number(a.score || 0) || Number(b.value?.valueScore || 0) - Number(a.value?.valueScore || 0))
      .slice(0, perGroup);
    if (!items.length) continue;
    sections.push({
      title: maddenGmTargetSectionTitle(group, items),
      text: items.map((item, index) => maddenGmTargetLine(item, index) + maddenGmSuggestedPackageText(item, tradeChips, slotMap, fromTeamName)).join('\n\n'),
    });
  }
  if (!sections.length) {
    const fallbackText = maddenGmTieredTargetText(scoredTargets || [], maxGroups * perGroup);
    if (fallbackText) sections.push({ title: 'Suggested Targets', text: fallbackText });
  }
  return sections;
}

function maddenGmPositionAwareTargetText(scoredTargets, needRows = [], maxGroups = 4, perGroup = 3, tradeChips = null, slotMap = null, fromTeamName = null) {
  const sections = maddenGmPositionAwareTargetSections(scoredTargets, needRows, maxGroups, perGroup, tradeChips, slotMap, fromTeamName);
  return sections.map(s => `**${s.title}**\n${s.text}`).join('\n\n');
}

function maddenRosterGroupRankMap(roster = []) {
  const grouped = new Map();
  for (const row of roster || []) {
    const group = maddenPositionNeedGroup(row.position);
    if (!group || ['IGNORE', 'OTHER', 'K/P'].includes(group)) continue;
    if (!grouped.has(group)) grouped.set(group, []);
    grouped.get(group).push(row);
  }
  const rankMap = new Map();
  for (const [group, rows] of grouped.entries()) {
    rows.sort((a, b) => Number(b.overall || 0) - Number(a.overall || 0) || Number(calculateMaddenPlayerValue(b).valueScore || 0) - Number(calculateMaddenPlayerValue(a).valueScore || 0));
    rows.forEach((row, index) => rankMap.set(maddenTradeFinderPlayerKey(row), { group, rank: index + 1, count: rows.length }));
  }
  return rankMap;
}

// 7J-10BQ: Trade Chip Engine 2.0.
// Score every roster player into premium chips, movable veterans, and depth assets.
function maddenBuildTradeChipItems(roster = [], teamNeed = null, limit = 12) {
  const rankMap = maddenRosterGroupRankMap(roster);
  const weaknessGroups = new Set((teamNeed?.weaknesses || []).slice(0, 4).map(row => row.position));
  const strengthGroups = new Set((teamNeed?.strengths || []).slice(0, 5).map(row => row.position));

  const rosterRows = Array.isArray(roster) ? roster : [];
  const rosterByValue = [...rosterRows]
    .map(row => ({ row, value: calculateMaddenPlayerValue(row) }))
    .sort((a, b) => Number(b.value?.valueScore || 0) - Number(a.value?.valueScore || 0));
  const topRosterKeys = new Set(rosterByValue.slice(0, 3).map(item => maddenTradeFinderPlayerKey(item.row)));

  const bestByGroup = new Map();
  for (const row of rosterRows) {
    const group = maddenPositionNeedGroup(row.position);
    if (!group || ['IGNORE', 'OTHER', 'K/P'].includes(group)) continue;
    const current = bestByGroup.get(group);
    const value = calculateMaddenPlayerValue(row);
    const score = Number(row.overall || 0) * 100 + Number(value.valueScore || 0);
    if (!current || score > current.score) bestByGroup.set(group, { row, score });
  }

  const evaluated = [];
  let protectedCount = 0;
  let coreYoungCount = 0;
  let needExcludedCount = 0;
  let surplusCount = 0;

  for (const row of rosterRows) {
    const group = maddenPositionNeedGroup(row.position);
    if (!group || ['IGNORE', 'OTHER', 'K/P'].includes(group)) continue;

    const value = calculateMaddenPlayerValue(row);
    const availability = maddenPlayerAvailability(row, teamNeed);
    const playerKey = maddenTradeFinderPlayerKey(row);
    const groupRank = rankMap.get(playerKey) || { group, rank: 99, count: 0 };
    const config = MADDEN_NEED_GROUP_CONFIG[group] || { starters: 1, depth: 1 };
    const rank = Number(groupRank.rank || 99);
    const count = Number(groupRank.count || 0);
    const age = Number(row.age || 0);
    const overall = Number(row.overall || 0);
    const valueScore = Number(value.valueScore || 0);
    const devSort = getMaddenDevTraitSortValue(row.dev_trait);
    const isStarter = rank <= Number(config.starters || 1);
    const isDepthAsset = rank > Number(config.starters || 1);
    const isDeepDepth = rank > Number(config.starters || 1) + Number(config.depth || 1);
    const isNeedGroup = weaknessGroups.has(group);
    const isSurplus = strengthGroups.has(group) || count > Number(config.starters || 1) + Number(config.depth || 1) + 1;
    const isBestInGroup = bestByGroup.get(group)?.row && maddenTradeFinderPlayerKey(bestByGroup.get(group).row) === playerKey;

    const isFranchiseQb = group === 'QB' && (overall >= 88 || valueScore >= 1500);
    const isYoungElite = overall >= 93 && age > 0 && age <= 27 && devSort >= 4;
    const isTopNeedPlayer = isNeedGroup && rank === 1;

    // 7J-10BS: protect young/core roster building blocks from being suggested as trade chips.
    const isRecentHighPick = age > 0 && age <= 24 && Number(row.draft_round || row.draftRound || 0) > 0 && Number(row.draft_round || row.draftRound || 99) <= 2;
    const isYoungHighValue = age > 0 && age <= 27 && (valueScore >= 1200 || overall >= 88 || devSort >= 3);
    const isYoungCornerstonePosition = age > 0 && age <= 27 && isBestInGroup && ['QB', 'OT', 'WR', 'EDGE', 'CB', 'HB', 'S'].includes(group) && (overall >= 84 || valueScore >= 650 || devSort >= 3);
    const isTopRosterAsset = topRosterKeys.has(playerKey) && age > 0 && age <= 27 && (overall >= 84 || valueScore >= 700 || devSort >= 3);
    const isCoreYoungAsset = isYoungHighValue || isYoungCornerstonePosition || isTopRosterAsset || isRecentHighPick;

    const isProtected = isFranchiseQb || isYoungElite || isTopNeedPlayer || isCoreYoungAsset;

    if (isProtected) protectedCount += 1;
    if (isCoreYoungAsset) coreYoungCount += 1;
    if (isNeedGroup && isStarter) needExcludedCount += 1;
    if (isSurplus) surplusCount += 1;

    let score = 12;
    score += Math.min(34, valueScore / 120);
    score += Number(availability.score || 0) * 0.5;
    if (isSurplus) score += 28;
    if (isDepthAsset) score += 18;
    if (isDeepDepth) score += 18;
    if (age >= 32) score += 22;
    else if (age >= 29) score += 12;
    if (overall >= 88 && age >= 29) score += 10;
    if (valueScore >= 900 && !isNeedGroup) score += 10;
    if (isNeedGroup && isStarter) score -= 28;
    if (isTopNeedPlayer) score -= 30;
    if (isCoreYoungAsset) score -= 70;
    if (isProtected) score -= 45;
    if (valueScore < 120 && !isDeepDepth) score -= 10;

    const reasons = [];
    if (isSurplus) reasons.push('surplus');
    if (isDeepDepth) reasons.push('deep depth');
    else if (isDepthAsset) reasons.push('depth');
    if (age >= 29) reasons.push('veteran');
    if (availability.reasons?.[0]) reasons.push(availability.reasons[0]);
    if (isNeedGroup && isStarter) reasons.push('need starter');
    if (isCoreYoungAsset) reasons.push('core young asset');
    if (isProtected && !isCoreYoungAsset) reasons.push('protected core');

    let category = 'depth';
    if (valueScore >= 1000 || (overall >= 87 && !isNeedGroup)) category = 'premium';
    else if (age >= 29 || Number(availability.score || 0) >= 62) category = 'veteran';

    evaluated.push({
      row,
      group,
      value,
      availability,
      groupRank,
      score: Math.max(0, Math.round(score)),
      category,
      protected: isProtected,
      coreYoungAsset: isCoreYoungAsset,
      isNeedGroup,
      isSurplus,
      reasons: [...new Set(reasons)].slice(0, 3),
    });
  }

  let items = evaluated
    .filter(item => !item.protected)
    .filter(item => Number(item.score || 0) >= 24)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0) || Number(b.value.valueScore || 0) - Number(a.value.valueScore || 0))
    .slice(0, limit);

  let fallbackUsed = false;
  if (!items.length) {
    fallbackUsed = true;
    items = evaluated
      .filter(item => !item.protected)
      .sort((a, b) => {
        const aScore = Number(a.value?.valueScore || 0) + (a.isSurplus ? 350 : 0) + (a.groupRank?.rank > 1 ? 175 : 0) + Number(a.availability?.score || 0) * 8;
        const bScore = Number(b.value?.valueScore || 0) + (b.isSurplus ? 350 : 0) + (b.groupRank?.rank > 1 ? 175 : 0) + Number(b.availability?.score || 0) * 8;
        return bScore - aScore;
      })
      .slice(0, Math.min(limit, 8))
      .map(item => ({ ...item, category: item.category || 'depth', fallback: true }));
  }

  items.debug = {
    playersEvaluated: evaluated.length,
    protectedCount,
    coreYoungCount,
    needExcludedCount,
    surplusCount,
    premiumCount: items.filter(item => item.category === 'premium').length,
    veteranCount: items.filter(item => item.category === 'veteran').length,
    depthCount: items.filter(item => item.category === 'depth').length,
    fallbackUsed,
  };
  return items;
}

function maddenTradeChipLine(item, index) {
  const row = item.row;
  const reason = item.reasons?.length ? ` • ${item.reasons.join(', ')}` : '';
  return `${index + 1}. **${maddenValuePlayerName(row)}** — ${row.position || 'POS'} • ${row.overall || 'N/A'} OVR • ${Number(item.value?.valueScore || 0).toFixed(0)} • ${item.availability?.label || 'Medium'} availability${reason}`;
}


function maddenTradeChipSections(items = []) {
  if (!items.length) return [{ title: 'Possible Trade Chips', text: 'No movable assets found after fallback.' }];
  const premium = items.filter(item => item.category === 'premium').slice(0, 4);
  const veterans = items.filter(item => item.category === 'veteran').slice(0, 4);
  const depth = items.filter(item => item.category === 'depth').slice(0, 4);
  const fallback = items.filter(item => item.fallback).slice(0, 6);
  const sections = [];
  if (premium.length) sections.push({ title: '💰 Premium Chips', text: premium.map((item, index) => maddenTradeChipLine(item, index)).join('\n') });
  if (veterans.length) sections.push({ title: '🔄 Movable Veterans', text: veterans.map((item, index) => maddenTradeChipLine(item, index)).join('\n') });
  if (depth.length) sections.push({ title: '📦 Depth Assets', text: depth.map((item, index) => maddenTradeChipLine(item, index)).join('\n') });
  if (!sections.length && fallback.length) sections.push({ title: '📦 Most Movable Assets', text: fallback.map((item, index) => maddenTradeChipLine(item, index)).join('\n') });
  if (!sections.length) sections.push({ title: 'Possible Trade Chips', text: items.slice(0, 8).map((item, index) => maddenTradeChipLine(item, index)).join('\n') });
  return sections;
}



function maddenBuildGmTargetList(allPlayers, teamKey, needGroups, targetTeamNeed, allNeedsModel, limit = 12) {
  return (allPlayers || [])
    .filter(row => maddenTradeAnalyzerTeamKey(row) !== teamKey)
    .filter(row => needGroups.has(maddenPositionNeedGroup(row.position)))
    .map(row => ({ row, ...maddenGmTargetScore(row, targetTeamNeed, allNeedsModel.get(maddenTradeAnalyzerTeamKey(row))) }))
    .filter(item => !item.availability?.hideAsTarget)
    .filter(item => Number(item.availability?.score || 0) >= 30)
    .filter(item => Number(item.upgrade || 0) >= 3 || Number(item.row?.overall || 0) >= 86)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0) || Number(b.availability?.score || 0) - Number(a.availability?.score || 0) || Number(b.value?.valueScore || 0) - Number(a.value?.valueScore || 0))
    .slice(0, limit);
}

async function buildMaddenTradeNeedsEmbed(guildId, league, teamName) {
  const model = await buildMaddenTeamNeedsModel(guildId, league.league_id, teamName);
  const wanted = maddenTradeNormalizeTeamKey(teamName);
  let teamNeed = model.get(wanted) || Array.from(model.values()).find(item => String(item.teamName || '').toLowerCase().includes(String(teamName || '').toLowerCase()));
  if (!teamNeed) {
    return new EmbedBuilder().setTitle('Madden Team Needs').setColor(0xED4245).setDescription(`Could not find **${String(teamName || '').slice(0, 80)}** in ${league?.league_name || 'this league'}.`).setFooter({ text: 'GG Sports • 7J-10BW-A Trade Block Integrations' }).setTimestamp();
  }

  const formatNeed = (row, index) => maddenTeamNeedUserLine(row, index, true);
  const formatStrength = (row, index) => `${index + 1}. **${row.position}** — ${Number(row.starterAvg || 0).toFixed(1)} starter • ${Number(row.depthAvg || row.avgOverall || 0).toFixed(1)} depth • ${row.count || 0} players`;

  const weaknessLines = (teamNeed.weaknesses || []).slice(0, 6).map(formatNeed);
  const strengthLines = (teamNeed.strengths || []).slice(0, 6).map(formatStrength);

  const allRows = await getMaddenTradeFinderPlayerRows(guildId, league.league_id, null).catch(() => []);
  const teamKey = teamNeed.teamKey;
  const topNeedGroups = new Set((teamNeed.weaknesses || []).slice(0, 3).map(row => row.position));
  const allNeedsModel = await buildMaddenTeamNeedsModel(guildId, league.league_id, null).catch(() => new Map());
  const slotMap = await getMaddenProjectedDraftSlotMap(guildId, league.league_id).catch(() => new Map());
  const teamRoster = allRows.filter(row => maddenTradeAnalyzerTeamKey(row) === teamKey);
  const tradableItems = maddenBuildTradeChipItems(teamRoster, teamNeed, 12);
  const scoredTargets = maddenBuildGmTargetList(allRows, teamKey, topNeedGroups, teamNeed, allNeedsModel, 9);
  const targets = maddenGmPositionAwareTargetText(scoredTargets, teamNeed.weaknesses || [], 3, 3, tradableItems, slotMap, teamNeed.teamName);

  const surplus = (teamNeed.strengths || []).slice(0, 3).map(row => row.position).join(', ') || 'None detected';
  const abbr = getMaddenTeamAbbrev(teamNeed.teamName) || teamNeed.teamName;
  const tradeNeedsEmbed = new EmbedBuilder()
    .setTitle(`Madden Team Needs • ${maddenTeamDisplayName(teamNeed.teamName)}`)
    .setColor(0x5865F2)
    .setDescription(`${league?.league_name || 'Madden League'}\nRoster Avg OVR: **${Number(teamNeed.teamAvgOverall || 0).toFixed(1)}** • Team: **${abbr}**`)
    .addFields(
      { name: 'Biggest Needs', value: maddenSafeEmbedText(weaknessLines.join('\n') || 'No needs found.', 1024), inline: false },
      { name: 'Biggest Strengths', value: maddenSafeEmbedText(strengthLines.join('\n') || 'No strengths found.', 1024), inline: false },
      { name: 'Suggested Targets', value: maddenSafeEmbedText(targets || 'No realistic outside targets found for top needs.', 1024), inline: false },
      { name: 'GM Notes', value: `Surplus groups: **${surplus}**\nNeeds are based on starter quality, depth quality, missing bodies, and positional importance. Suggested targets are grouped by need position, then paired with suggested offers using movable chips and dynamic draft picks.`, inline: false }
    )
    .setFooter({ text: 'GG Sports • 7J-10BW-A Trade Block Integrations' })
    .setTimestamp();
  const needsLogo = getMaddenTeamLogoUrl(teamNeed.teamName);
  if (needsLogo) tradeNeedsEmbed.setThumbnail(needsLogo);
  return tradeNeedsEmbed;
}



async function ensureMaddenTradeBlockTables() {
  await ensureMaddenPlayerPersistenceTables();
  await pool.query(`
    CREATE TABLE IF NOT EXISTS madden_trade_block_entries (
      guild_id TEXT NOT NULL,
      league_id TEXT NOT NULL,
      player_key TEXT NOT NULL,
      player_name TEXT NOT NULL,
      team_name TEXT NOT NULL,
      position TEXT,
      overall INTEGER,
      value_score NUMERIC NOT NULL DEFAULT 0,
      trade_tier TEXT,
      seeking TEXT,
      notes TEXT,
      submitted_by TEXT NOT NULL,
      is_active BOOLEAN NOT NULL DEFAULT TRUE,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      PRIMARY KEY (guild_id, league_id, player_key)
    )
  `);
  await pool.query(`ALTER TABLE madden_trade_block_entries ADD COLUMN IF NOT EXISTS value_score NUMERIC NOT NULL DEFAULT 0`);
  await pool.query(`ALTER TABLE madden_trade_block_entries ADD COLUMN IF NOT EXISTS trade_tier TEXT`);
  await pool.query(`ALTER TABLE madden_trade_block_entries ADD COLUMN IF NOT EXISTS seeking TEXT`);
  await pool.query(`ALTER TABLE madden_trade_block_entries ADD COLUMN IF NOT EXISTS notes TEXT`);
  await pool.query(`ALTER TABLE madden_trade_block_entries ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT TRUE`);
  await pool.query(`CREATE INDEX IF NOT EXISTS idx_madden_trade_block_entries_league_active ON madden_trade_block_entries (guild_id, league_id, is_active, team_name)`);
}



async function ensureMaddenTradeNegotiationTables() {
  await ensureMaddenTradeBlockTables();
  await pool.query(`
    CREATE TABLE IF NOT EXISTS madden_trade_negotiations (
      id UUID PRIMARY KEY,
      guild_id TEXT NOT NULL,
      league_id TEXT NOT NULL,
      player_key TEXT,
      player_name TEXT NOT NULL,
      listing_team TEXT,
      requesting_team TEXT,
      listing_user_id TEXT,
      requesting_user_id TEXT,
      offer_text TEXT,
      message TEXT,
      thread_id TEXT,
      selected_package_json JSONB,
      selected_package_index INTEGER,
      committee_offer_id TEXT,
      requesting_confirmed_by TEXT,
      requesting_confirmed_at TIMESTAMPTZ,
      listing_confirmed_by TEXT,
      listing_confirmed_at TIMESTAMPTZ,
      status TEXT NOT NULL DEFAULT 'open',
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    )
  `);
  await pool.query(`ALTER TABLE madden_trade_negotiations ADD COLUMN IF NOT EXISTS offer_text TEXT`);
  await pool.query(`ALTER TABLE madden_trade_negotiations ADD COLUMN IF NOT EXISTS message TEXT`);
  await pool.query(`ALTER TABLE madden_trade_negotiations ADD COLUMN IF NOT EXISTS thread_id TEXT`);
  await pool.query(`ALTER TABLE madden_trade_negotiations ADD COLUMN IF NOT EXISTS selected_package_json JSONB`);
  await pool.query(`ALTER TABLE madden_trade_negotiations ADD COLUMN IF NOT EXISTS selected_package_index INTEGER`);
  await pool.query(`ALTER TABLE madden_trade_negotiations ADD COLUMN IF NOT EXISTS committee_offer_id TEXT`);
  await pool.query(`ALTER TABLE madden_trade_negotiations ADD COLUMN IF NOT EXISTS requesting_confirmed_by TEXT`);
  await pool.query(`ALTER TABLE madden_trade_negotiations ADD COLUMN IF NOT EXISTS requesting_confirmed_at TIMESTAMPTZ`);
  await pool.query(`ALTER TABLE madden_trade_negotiations ADD COLUMN IF NOT EXISTS listing_confirmed_by TEXT`);
  await pool.query(`ALTER TABLE madden_trade_negotiations ADD COLUMN IF NOT EXISTS listing_confirmed_at TIMESTAMPTZ`);
  await pool.query(`CREATE INDEX IF NOT EXISTS idx_madden_trade_negotiations_lookup ON madden_trade_negotiations (guild_id, league_id, status, player_name)`);
}

async function getMaddenTradeBlockPlayerAutocompleteChoices(guildId, leagueId, focusedValue) {
  await ensureMaddenTradeBlockTables();
  const query = String(focusedValue || '').trim();
  const result = await pool.query(
    `SELECT player_name, team_name, position, overall, value_score
     FROM madden_trade_block_entries
     WHERE guild_id = $1::text
       AND league_id = $2::text
       AND is_active = TRUE
       AND ($3::text = '' OR LOWER(player_name) LIKE LOWER($4) OR LOWER(team_name) LIKE LOWER($4) OR LOWER(position) = LOWER($3))
     ORDER BY team_name ASC, value_score DESC NULLS LAST, overall DESC NULLS LAST, player_name ASC
     LIMIT 25`,
    [guildId, leagueId, query, `%${query}%`]
  );
  return (result.rows || []).map(row => ({
    name: `${row.player_name} (${getMaddenTeamAbbrev(row.team_name) || row.team_name} • ${row.position || 'POS'} • ${row.overall || 'N/A'} OVR)`.slice(0, 100),
    value: String(row.player_name || '').slice(0, 100),
  }));
}

async function findMaddenTradeBlockListing(guildId, leagueId, playerName) {
  await ensureMaddenTradeBlockTables();
  const query = String(playerName || '').trim();
  const result = await pool.query(
    `SELECT * FROM madden_trade_block_entries
     WHERE guild_id = $1::text
       AND league_id = $2::text
       AND is_active = TRUE
       AND (LOWER(player_name) = LOWER($3) OR LOWER(player_name) LIKE LOWER($4) OR LOWER(player_key) = LOWER($3))
     ORDER BY value_score DESC NULLS LAST, updated_at DESC
     LIMIT 1`,
    [guildId, leagueId, query, `%${query}%`]
  );
  return result.rows?.[0] || null;
}

async function getMaddenTradeNegotiationById(id) {
  if (!id) return null;
  await ensureMaddenTradeNegotiationTables();
  const result = await pool.query(`SELECT * FROM madden_trade_negotiations WHERE id = $1 LIMIT 1`, [id]);
  return result.rows?.[0] || null;
}

