async function createMaddenTradeNegotiationHub(guildId, league, member, userId, playerName) {
  await ensureMaddenTradeNegotiationTables();
  let listing = await findMaddenTradeBlockListing(guildId, league.league_id, playerName);

  if (!listing) {
    // Not explicitly listed on the trade block — negotiations aren't limited to
    // listed players, so resolve the player directly and find their team's owner
    // via the same role-based mechanism the rest of the bot uses for ownership.
    const player = await findMaddenImportedPlayer(guildId, league.league_id, playerName, null)
      || await findMaddenPlayerFromWeeklyStats(guildId, league.league_id, playerName, null);

    if (!player) {
      return {
        ok: false,
        embed: new EmbedBuilder().setTitle('Madden Trade Negotiation Hub').setColor(0xED4245).setDescription(`Could not find a player named "${String(playerName || '').slice(0, 80)}" in this league.`).setFooter({ text: 'GG Sports • 7J-10BX-G Private Negotiation Workflow' }).setTimestamp(),
        components: [],
      };
    }

    const teamName = player.resolved_team_name || player.team_name || null;
    const isFreeAgent = player.is_free_agent || !teamName || ['fa', 'free agent', 'free agents', 'freeagent'].includes(String(teamName).toLowerCase());
    if (isFreeAgent) {
      return {
        ok: false,
        embed: new EmbedBuilder().setTitle('Madden Trade Negotiation Hub').setColor(0xED4245).setDescription(`**${maddenPlayerDisplayName(player)}** is a free agent, not on a roster — there's no team to negotiate a trade with. Use the free agents board or \`/maddenfreeagents sign\` to sign them instead.`).setFooter({ text: 'GG Sports • 7J-10BX-G Private Negotiation Workflow' }).setTimestamp(),
        components: [],
      };
    }

    const ownerUserId = await findMaddenOwnerForTeamName(guildId, league.league_id, teamName).catch(() => null);
    const value = calculateMaddenPlayerValue(player);
    listing = {
      player_key: maddenTradeFinderPlayerKey(player),
      player_name: maddenPlayerDisplayName(player) || playerName,
      team_name: teamName,
      position: player.position || null,
      overall: player.overall || null,
      value_score: value?.valueScore || 0,
      seeking: null,
      notes: null,
      submitted_by: ownerUserId,
    };
  }

  // 7J-NOSELFTRADE: per Hxxdie — same fix as the generic negotiation
  // system. listing.submitted_by is the current owner of the player's
  // team; if that's the same person opening the negotiation, they're
  // trying to trade with their own team.
  if (listing.submitted_by && String(listing.submitted_by) === String(userId)) {
    return {
      ok: false,
      embed: new EmbedBuilder().setTitle('Madden Trade Negotiation Hub').setColor(0xED4245).setDescription("You can't start a trade negotiation with your own team.").setFooter({ text: 'GG Sports • 7J-10BX-G Private Negotiation Workflow' }).setTimestamp(),
      components: [],
    };
  }

  const userTeam = member ? await getMemberTeamForLeague(member, league) : null;

  // 7J-CPUNEGOTIATION: per Hxxdie — a CPU-owned team's listing.submitted_by
  // is genuinely null (no real GM), so this negotiation would otherwise sit
  // waiting forever on a dual confirmation that can never actually happen.
  // Blocks outright if this league doesn't allow CPU trades at all
  // (matches the generic, non-Madden negotiation system's existing
  // behavior); otherwise proceeds but immediately marks the CPU side as
  // confirmed, since requiring a button click from a user who doesn't
  // exist was the actual bug.
  const isCpuTarget = !listing.submitted_by;
  if (isCpuTarget) {
    const cpuCustomSettings = await ensureLeagueCustomSettings(league).catch(() => ({}));
    if (cpuCustomSettings.cpu_trades_allowed === false) {
      return {
        ok: false,
        embed: new EmbedBuilder().setTitle('Madden Trade Negotiation Hub').setColor(0xED4245).setDescription(`**${maddenTeamDisplayName(listing.team_name)}** does not currently have an owner assigned, and this league does not allow trades with CPU-controlled teams (League Customization → Trades).`).setFooter({ text: 'GG Sports • 7J-10BX-G Private Negotiation Workflow' }).setTimestamp(),
        components: [],
      };
    }
  }

  const negotiationId = randomUUID();
  await pool.query(
    `INSERT INTO madden_trade_negotiations (
       id, guild_id, league_id, player_key, player_name, listing_team, requesting_team,
       listing_user_id, requesting_user_id, status, cpu_target, created_at, updated_at
     ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, 'open', $10, NOW(), NOW())`,
    [negotiationId, guildId, league.league_id, listing.player_key || null, listing.player_name, listing.team_name, userTeam?.name || null, listing.submitted_by || null, userId, isCpuTarget]
  );
  const negotiation = await getMaddenTradeNegotiationById(negotiationId);
  if (userTeam?.name && listing.team_name) {
    const rumorGuild = await client.guilds.fetch(guildId).catch(() => null);
    if (rumorGuild) {
      await maybeGenerateMaddenTradeRumor(rumorGuild, league, userTeam.name, listing.team_name).catch(() => null);
    }
  }
  return {
    ok: true,
    embed: buildMaddenTradeNegotiationHubEmbed(league, listing, negotiation, userId),
    components: buildMaddenTradeNegotiationButtons(negotiationId),
  };
}



async function createMaddenTradeNegotiationThread(negotiation, discordClient, fallbackChannelId = null) {
  if (!negotiation) return { ok: false, message: 'Negotiation not found.' };

  if (negotiation.thread_id) {
    return { ok: true, message: `Interest already registered. Negotiation thread: <#${negotiation.thread_id}>` };
  }

  const guild = await discordClient.guilds.fetch(negotiation.guild_id).catch(() => null);
  if (!guild) return { ok: false, message: 'Interest registered, but I could not access the server to create a thread.' };

  const league = await getLeagueById(negotiation.league_id).catch(() => null);
  const candidateChannelIds = [
    league?.trade_negotiation_channel_id,
    league?.offer_a_trade_channel_id,
    league?.trade_offer_channel_id,
    league?.committee_channel_id,
    league?.approved_channel_id,
    fallbackChannelId,
  ].filter(Boolean);

  let channel = null;
  let chosenChannelId = null;
  for (const channelId of candidateChannelIds) {
    const possible = await guild.channels.fetch(channelId).catch(() => null);
    if (possible && possible.isTextBased?.()) {
      channel = possible;
      chosenChannelId = channelId;
      break;
    }
  }

  if (!channel) {
    console.warn('[7J-10BX-A NEGOTIATION THREAD] No valid channel found ' + JSON.stringify({
      league: league?.league_name || negotiation.league_id,
      player: negotiation.player_name,
      candidateChannelIds,
      fallbackChannelId,
    }));
    return { ok: false, message: 'Interest registered, but I could not find a valid text channel for the negotiation thread. Set a trade block or offer-a-trade channel, then try again.' };
  }

  const safeName = String(negotiation.player_name || 'trade').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'trade';
  let thread = null;

  if (channel.isThread?.()) {
    thread = channel;
  } else if (channel.threads?.create) {
    thread = await channel.threads.create({
      name: `trade-negotiation-${safeName}`.slice(0, 90),
      type: ChannelType.PrivateThread,
      invitable: false,
      autoArchiveDuration: 1440,
      reason: 'GG Sports trade negotiation hub',
    }).catch(async () => channel.threads.create({
      name: `trade-negotiation-${safeName}`.slice(0, 90),
      autoArchiveDuration: 1440,
      reason: 'GG Sports trade negotiation hub',
    }).catch(() => null));
  }

  if (!thread && channel.send) {
    const starter = await channel.send({
      content: `Trade negotiation interest registered for **${negotiation.player_name}**.`,
      allowedMentions: { users: [], roles: [] },
    }).catch(() => null);
    if (starter?.startThread) {
      thread = await starter.startThread({
        name: `trade-negotiation-${safeName}`.slice(0, 90),
        autoArchiveDuration: 1440,
        reason: 'GG Sports trade negotiation hub',
      }).catch(() => null);
    }
  }

  if (!thread) {
    console.warn('[7J-10BX-A NEGOTIATION THREAD] Thread create failed ' + JSON.stringify({
      league: league?.league_name || negotiation.league_id,
      player: negotiation.player_name,
      chosenChannelId,
      channelType: channel?.type,
    }));
    return { ok: false, message: `Interest registered, but I could not create a thread in <#${chosenChannelId}>. Check bot permissions: View Channel, Send Messages, Create Private Threads, and Send Messages in Threads.` };
  }

  await thread.members?.add?.(negotiation.listing_user_id).catch(() => null);
  await thread.members?.add?.(negotiation.requesting_user_id).catch(() => null);
  await pool.query(`UPDATE madden_trade_negotiations SET thread_id = $1, status = 'interested', updated_at = NOW() WHERE id = $2`, [thread.id, negotiation.id]);
  // 7J-CPUNEGOTIATION: negotiation.listing_user_id is genuinely null for a
  // CPU-controlled team — filtering it out here avoids a literal broken
  // "<@null>" mention appearing in the thread-opening message.
  const openingMentionIds = [negotiation.listing_user_id, negotiation.requesting_user_id].filter(Boolean);
  // 7J-THREADHUBNA: per Hxxdie — this re-posted hub embed (inside the newly
  // opened private thread) was hand-building a stripped-down listing object
  // from only what's stored on the negotiation row (player_name, team,
  // owner) — position/overall/value were never part of that row, so they
  // always rendered "N/A" here even though the original hub message showed
  // them correctly. Re-resolving via getMaddenPlayerValueAsset (same live
  // madden_players-backed lookup used everywhere else in the trade tools
  // after the 7J-VALUESYNC fix) fills them back in.
  const threadListingAsset = await getMaddenPlayerValueAsset(negotiation.guild_id, negotiation.league_id, negotiation.player_name, negotiation.listing_team).catch(() => null);
  const threadListing = {
    player_name: negotiation.player_name,
    team_name: negotiation.listing_team,
    submitted_by: negotiation.listing_user_id,
    seeking: 'See trade block listing',
    notes: 'Private negotiation thread',
    position: threadListingAsset?.position || null,
    overall: threadListingAsset?.overall || null,
    value_score: threadListingAsset?.value_score || 0,
  };
  await thread.send({
    content: `${openingMentionIds.map(id => `<@${id}>`).join(' ')} private trade negotiation opened for **${negotiation.player_name}**${negotiation.cpu_target ? ' (CPU-controlled team, no owner to notify)' : ''}.`,
    embeds: [buildMaddenTradeNegotiationHubEmbed(league, threadListing, negotiation, negotiation.requesting_user_id)],
    components: buildMaddenTradeNegotiationThreadButtons(negotiation.id),
    allowedMentions: { users: openingMentionIds, roles: [] },
  }).catch(() => null);

  console.log('[7J-10BX-A NEGOTIATION THREAD] ' + JSON.stringify({
    league: league?.league_name || negotiation.league_id,
    player: negotiation.player_name,
    chosenChannelId,
    fallbackChannelId,
    threadId: thread.id,
    result: 'created',
  }));

  return { ok: true, message: `Interest registered and negotiation thread created: <#${thread.id}>` };
}

async function openMaddenNegotiationThreadForFinalizedOffer(interaction, negotiation, league, pkg) {
  await pool.query(`UPDATE madden_trade_negotiations SET status = 'interested', updated_at = NOW() WHERE id = $1`, [negotiation.id]);
  const refreshedBeforeThread = await getMaddenTradeNegotiationById(negotiation.id) || negotiation;
  const threadResult = await createMaddenTradeNegotiationThread(refreshedBeforeThread, interaction.client, interaction.channelId);
  const refreshedAfterThread = await getMaddenTradeNegotiationById(negotiation.id) || refreshedBeforeThread;
  const threadId = refreshedAfterThread.thread_id;
  if (!threadResult.ok || !threadId) return threadResult;

  const thread = await interaction.client.channels.fetch(threadId).catch(() => null);
  if (thread?.send) {
    const hydrated = await hydrateMaddenNegotiationPackageTargetSide(interaction.guild.id, league, refreshedAfterThread, pkg);
    await thread.send({
      content: `<@${refreshedAfterThread.requesting_user_id}> <@${refreshedAfterThread.listing_user_id}> initial offer finalized for **${refreshedAfterThread.player_name}**. Review, edit if needed, then both GMs confirm before committee submission.`,
      embeds: [buildMaddenNegotiationPackageEmbed(league, refreshedAfterThread, hydrated)],
      components: [buildMaddenNegotiationPackageButtons(refreshedAfterThread.id, Number(hydrated.index || 0), true)],
      allowedMentions: { users: [refreshedAfterThread.requesting_user_id, refreshedAfterThread.listing_user_id], roles: [] },
    }).catch(() => null);
    await thread.send({
      embeds: [buildMaddenNegotiationSubmitConfirmEmbed(league, refreshedAfterThread, hydrated)],
      components: [buildMaddenNegotiationSubmitConfirmButtons(refreshedAfterThread.id)],
      allowedMentions: { users: [refreshedAfterThread.requesting_user_id, refreshedAfterThread.listing_user_id], roles: [] },
    }).catch(() => null);
  }
  return { ok: true, message: `Private negotiation thread opened: <#${threadId}>` };
}


// 7J-10BX-F: no-typing negotiation helpers. Trade Suggestions and custom offers use dropdown/edit panels instead of text modals.
async function buildMaddenNegotiationGeneratedPackages(guildId, league, negotiation, limit = 5) {
  const filters = {
    teamFilter: negotiation.requesting_team || null,
    excludeTeam: negotiation.listing_team || null,
    maxAssets: 3,
    prioritizeNeed: true,
    contendersOnly: false,
    rebuildersOnly: false,
    tradeBlockOnly: false,
    page: 0,
    pageSize: limit,
    limit: Math.max(60, limit * 12),
  };
  const payload = await buildMaddenTradeFinderPayload(guildId, league, negotiation.player_name, filters);
  let packages = (payload.allMatches || payload.matches || [])
    .slice(0, limit)
    .map((candidate, index) => maddenTradeNegotiationPackageToJson(candidate, index));
  packages = await Promise.all(packages.map(pkg => hydrateMaddenNegotiationPackageTargetSide(guildId, league, negotiation, pkg)));
  return packages.filter(Boolean);
}

async function postMaddenNegotiationGeneratedPackages(interaction, negotiation, league, { ephemeral = true } = {}) {
  const packages = await buildMaddenNegotiationGeneratedPackages(negotiation.guild_id, league, negotiation, 5);
  if (!packages.length) {
    return { ok: false, message: 'No generated packages were found for this negotiation. Try creating a custom offer with dropdowns instead.' };
  }
  let sent = 0;
  for (const pkg of packages) {
    const payload = {
      embeds: [buildMaddenNegotiationPackageEmbed(league, negotiation, pkg)],
      components: [buildMaddenNegotiationPackageButtons(negotiation.id, pkg.index)],
      ephemeral: true,
    };
    let msg = null;
    if (interaction.followUp) msg = await interaction.followUp(payload).catch(() => null);
    if (!msg && interaction.reply && !interaction.replied && !interaction.deferred) msg = await interaction.reply(payload).catch(() => null);
    if (msg) sent += 1;
  }
  return {
    ok: sent > 0,
    message: sent > 0
      ? `Sent **${sent}** private trade suggestion(s). Choose **Select Package**, then use **Edit Package**, **Analyze**, or **Submit**. Nothing is posted publicly until the offer is finalized and a private thread is opened.`
      : 'I could not send private trade suggestions. Try again or create a custom offer.',
  };
}

async function buildMaddenNegotiationCustomPackage(guildId, league, negotiation) {
  const target = await getMaddenPlayerValueAsset(guildId, league.league_id, negotiation.player_name, negotiation.listing_team);
  return recalculateMaddenNegotiationPackage({
    index: 98,
    is_custom: true,
    custom_offer: true,
    players: [],
    picks: [],
    target_players: target ? [target] : [],
    target_picks: [],
    total: 0,
    target_value: Number(target?.value_score || 0),
    diff: -Number(target?.value_score || 0),
    fit_score: 100,
    asset_count: 0,
    generated_at: new Date().toISOString(),
  });
}

// 7J-10BX-D: Button-based negotiation package workflow.
function maddenTradeNegotiationPackageToJson(candidate, index = 0) {
  const players = (candidate?.players || []).filter(Boolean).map(player => ({
    player_name: maddenValuePlayerName(player),
    team_name: player.resolved_team_name || player.team_name || null,
    position: player.position || null,
    overall: player.overall || null,
    value_score: Number(calculateMaddenPlayerValue(player).valueScore || 0),
  }));
  const pick = candidate?.pick ? {
    raw: candidate.pick.raw || candidate.pick.label || null,
    label: candidate.pick.label || String(candidate.pick.raw || 'Draft Pick'),
    year: candidate.pick.year || null,
    round: candidate.pick.round || null,
    pick: candidate.pick.pick || null,
    team: candidate.pick.team || null,
    value_score: Number(candidate.pick.valueScore || 0),
  } : null;
  return {
    index,
    players,
    picks: pick ? [pick] : [],
    total: Number(candidate?.total || 0),
    diff: Number(candidate?.diff || 0),
    fit_score: Number(candidate?.fitScore || 0),
    asset_count: Number(candidate?.assetCount || players.length + (pick ? 1 : 0)),
    availability: candidate?.availability || null,
    need: candidate?.needInfo || null,
    generated_at: new Date().toISOString(),
  };
}

function maddenTradeNegotiationPackageTitle(pkg) {
  const offerPlayerText = (pkg.players || []).map(p => p.player_name).filter(Boolean).join(' + ');
  const offerPickText = (pkg.picks || []).map(p => p.label).filter(Boolean).join(' + ');
  const targetPlayerText = (pkg.target_players || []).map(p => p.player_name).filter(Boolean).join(' + ');
  const targetPickText = (pkg.target_picks || []).map(p => p.label).filter(Boolean).join(' + ');
  const offer = [offerPlayerText, offerPickText].filter(Boolean).join(' + ') || 'No assets';
  const target = [targetPlayerText, targetPickText].filter(Boolean).join(' + ') || 'Target player';
  return `${offer} ⇄ ${target}`;
}

function buildMaddenNegotiationPackageEmbed(league, negotiation, pkg) {
  const playerLines = (pkg.players || []).length
    ? pkg.players.map((p, i) => `${i + 1}. **${p.player_name}** — ${getMaddenTeamAbbrev(p.team_name) || p.team_name || 'FA'} ${p.position || 'POS'} • ${p.overall || 'N/A'} OVR • ${Number(p.value_score || 0).toFixed(0)}`).join('\n')
    : 'No players in this package.';
  const pickLines = (pkg.picks || []).length
    ? pkg.picks.map((p, i) => `${i + 1}. **${p.label}** — ${Number(p.value_score || 0).toFixed(1)}`).join('\n')
    : 'No picks in this package.';
  const targetPlayerLines = (pkg.target_players || []).length
    ? pkg.target_players.map((p, i) => `${i + 1}. **${p.player_name}** — ${getMaddenTeamAbbrev(p.team_name) || p.team_name || 'FA'} ${p.position || 'POS'} • ${p.overall || 'N/A'} OVR • ${Number(p.value_score || 0).toFixed(0)}`).join('\n')
    : `1. **${negotiation.player_name}**`;
  const targetPickLines = (pkg.target_picks || []).length
    ? '\n' + (pkg.target_picks || []).map((p, i) => `${i + 1}. **${p.label}** — ${Number(p.value_score || 0).toFixed(1)}`).join('\n')
    : '';
  const diffText = Number(pkg.diff || 0) >= 0 ? `+${Number(pkg.diff || 0).toFixed(1)} offer side` : `${Number(pkg.diff || 0).toFixed(1)} offer side`;
  return new EmbedBuilder()
    .setTitle(`Generated Trade Package #${Number(pkg.index || 0) + 1}`)
    .setColor(0xFEE75C)
    .setDescription(`${league?.league_name || 'Madden League'} • Target: **${negotiation.player_name}**`)
    .addFields(
      { name: `${maddenTeamDisplayName(negotiation.listing_team || 'Listed Team')} Receive`, value: maddenSafeEmbedText([playerLines, pickLines !== 'No picks in this package.' ? '\nDraft Picks:\n' + pickLines : ''].filter(Boolean).join('\n'), 1024), inline: false },
      { name: `${maddenTeamDisplayName(negotiation.requesting_team || 'Offering Team')} Receive`, value: maddenSafeEmbedText((targetPlayerLines + targetPickLines), 1024), inline: false },
      { name: 'Package Summary', value: `Offer Value: **${Number(pkg.total || 0).toFixed(1)}** • Target Value: **${Number(pkg.target_value || 0).toFixed(1)}** • Difference: **${diffText}** • Fit: **${Number(pkg.fit_score || 0)}**`, inline: false }
    )
    .setFooter({ text: 'GG Sports • 7J-10BX-F No-Typing Negotiation' })
    .setTimestamp();
}

