async function buildMaddenGmPanelHomeEmbed(guildId, league, teamName) {
  const teamRow = await pool.query(
    `SELECT * FROM madden_imported_team_stats WHERE guild_id = $1 AND league_id = $2 AND LOWER(team_name) = LOWER($3) LIMIT 1`,
    [String(guildId), String(league.league_id), teamName]
  ).then(r => r.rows?.[0]).catch(() => null);
  const model = await buildMaddenTeamNeedsModel(guildId, league.league_id, teamName).catch(() => new Map());
  const wanted = maddenTradeNormalizeTeamKey(teamName);
  const teamNeed = model.get(wanted) || Array.from(model.values()).find(item => String(item.teamName || '').toLowerCase().includes(String(teamName || '').toLowerCase()));
  const topNeed = teamNeed?.weaknesses?.[0];

  const embed = new EmbedBuilder()
    .setTitle(`🏈 ${maddenTeamDisplayName(teamName)} • GM Panel`)
    .setColor(0x5865F2)
    .setDescription(league.league_name)
    .addFields(
      { name: 'Record', value: teamRow ? `${teamRow.wins || 0}-${teamRow.losses || 0}${teamRow.ties ? '-' + teamRow.ties : ''} • PF ${teamRow.points_for || 0} • PA ${teamRow.points_against || 0}` : 'No record yet', inline: true },
      { name: 'Avg Overall', value: teamNeed ? Number(teamNeed.teamAvgOverall || 0).toFixed(1) : 'N/A', inline: true },
      { name: 'Top Need', value: topNeed ? `${topNeed.position} — ${maddenTeamNeedSeverity(topNeed.needScore).label}` : 'None detected', inline: true },
    )
    .setFooter({ text: 'GG Sports • GM Panel • Pick a section below' })
    .setTimestamp();
  const logo = getMaddenTeamLogoUrl(teamName);
  if (logo) embed.setThumbnail(logo);
  return embed;
}

async function showMaddenGmPanelHome(interaction, leagueId, teamName, { update = true } = {}) {
  const league = await getLeagueById(leagueId);
  if (!league) {
    const payload = { content: 'League not found.', embeds: [], components: [] };
    return update ? interaction.update(payload) : interaction.reply({ ...payload, ephemeral: true });
  }
  const embed = await buildMaddenGmPanelHomeEmbed(interaction.guild.id, league, teamName);
  const payload = { content: null, embeds: [embed], components: buildMaddenGmPanelHomeComponents(leagueId, teamName) };
  return update ? interaction.update(payload) : interaction.reply({ ...payload, ephemeral: true });
}

async function buildMaddenAddToBlockPickerPayload(guildId, leagueId, teamName, page, selectCustomId, navCustomIdPrefix) {
  const { rows, total } = await getMaddenTeamRosterPage(guildId, leagueId, teamName, { offset: page * 25, limit: 25, excludeFreeAgents: true });
  if (!rows.length) {
    return { content: page > 0 ? 'No more players on this page.' : 'No roster data found for this team yet.', components: [] };
  }
  const menu = new StringSelectMenuBuilder()
    .setCustomId(selectCustomId)
    .setPlaceholder(`Choose a player from ${teamName} to add`)
    .addOptions(rows.map(r => ({
      label: String(r.player_name || 'Unknown').slice(0, 100),
      value: String(r.player_name || 'unknown').slice(0, 100),
      description: `${r.position || 'POS'} • ${r.overall || 'N/A'} OVR`.slice(0, 100),
    })));
  const rowsOut = [new ActionRowBuilder().addComponents(menu)];
  if (total > 25) {
    const totalPages = Math.ceil(total / 25);
    rowsOut.push(new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId(`${navCustomIdPrefix}:${Math.max(0, page - 1)}`).setLabel(`Previous (${page + 1}/${totalPages})`).setStyle(ButtonStyle.Secondary).setDisabled(page <= 0),
      new ButtonBuilder().setCustomId(`${navCustomIdPrefix}:${Math.min(totalPages - 1, page + 1)}`).setLabel(`Next (${page + 1}/${totalPages})`).setStyle(ButtonStyle.Primary).setDisabled(page >= totalPages - 1),
    ));
  }
  return { content: `**Add to Trade Block** — ${teamName}`, components: rowsOut };
}

async function buildMaddenGmBlockCategoryPayload(interaction, league, teamName) {
  const member = await interaction.guild.members.fetch(interaction.user.id).catch(() => null);
  const embed = await buildMaddenTradeBlockTeamEmbed(interaction.guild.id, league, member, teamName);
  const encTeam = encodeURIComponent(teamName).slice(0, 80);
  const actionRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId(`gmpanel_addblock:${league.league_id}:${encTeam}`).setLabel('Add to Block').setEmoji('➕').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId(`gmpanel_removeblock:${league.league_id}:${encTeam}`).setLabel('Remove from Block').setEmoji('➖').setStyle(ButtonStyle.Danger),
  );
  return { embeds: [embed], components: [actionRow, buildMaddenGmPanelBackRow(league.league_id, teamName)] };
}

async function showMaddenGmPanelCategory(interaction, leagueId, teamName, category, { update = true, page = 0 } = {}) {
  const league = await getLeagueById(leagueId);
  if (!league) {
    const payload = { content: 'League not found.', embeds: [], components: [] };
    return update ? interaction.update(payload) : interaction.editReply(payload);
  }
  const backRow = [buildMaddenGmPanelBackRow(leagueId, teamName)];
  let payload;

  if (category === 'roster') {
    const encTeam = encodeURIComponent(teamName).slice(0, 80);
    const fullRoster = await getMaddenTeamRosterPage(interaction.guild.id, league.league_id, teamName, { offset: 0, limit: 100 });
    const pageRows = await getMaddenTeamRosterPage(interaction.guild.id, league.league_id, teamName, { offset: page * 25, limit: 25 });
    const rosterComponents = [];
    if (pageRows.rows.length) {
      const menu = new StringSelectMenuBuilder()
        .setCustomId(`gmpanel_roster_view:${leagueId}:${encTeam}:${page}`)
        .setPlaceholder('View a player\'s full profile...')
        .addOptions(pageRows.rows.map(r => ({
          label: String(r.player_name || 'Unknown').slice(0, 100),
          value: String(r.player_name || 'unknown').slice(0, 100),
          description: `${r.position || 'POS'} • ${r.overall || 'N/A'} OVR`.slice(0, 100),
        })));
      rosterComponents.push(new ActionRowBuilder().addComponents(menu));
    }
    if (pageRows.total > 25) {
      const totalPages = Math.ceil(pageRows.total / 25);
      rosterComponents.push(new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId(`gmpanel_roster_page:${leagueId}:${encTeam}:${Math.max(0, page - 1)}`).setLabel(`Previous (${page + 1}/${totalPages})`).setStyle(ButtonStyle.Secondary).setDisabled(page <= 0),
        new ButtonBuilder().setCustomId(`gmpanel_roster_page:${leagueId}:${encTeam}:${Math.min(totalPages - 1, page + 1)}`).setLabel(`Next (${page + 1}/${totalPages})`).setStyle(ButtonStyle.Primary).setDisabled(page >= totalPages - 1),
      ));
    }
    rosterComponents.push(buildMaddenGmPanelBackRow(leagueId, teamName));
    payload = { content: null, embeds: [buildMaddenRosterEmbed(league, teamName, fullRoster.rows, {})], components: rosterComponents };
  } else if (category === 'stats') {
    const embed = await buildMaddenTeamProfileEmbed(interaction.guild.id, league, teamName);
    const teamRow = await pool.query(
      `SELECT * FROM madden_imported_team_stats WHERE guild_id = $1 AND league_id = $2 AND LOWER(team_name) = LOWER($3) LIMIT 1`,
      [String(interaction.guild.id), String(league.league_id), teamName]
    ).then(r => r.rows?.[0]).catch(() => null);
    if (teamRow) {
      embed.addFields({ name: 'Record', value: `${teamRow.wins || 0}-${teamRow.losses || 0}${teamRow.ties ? '-' + teamRow.ties : ''} • PF ${teamRow.points_for || 0} • PA ${teamRow.points_against || 0}`, inline: true });
    }
    payload = { content: null, embeds: [embed], components: backRow };
  } else if (category === 'needs') {
    const embed = await buildMaddenTradeNeedsEmbed(interaction.guild.id, league, teamName);
    payload = { content: null, embeds: [embed], components: backRow };
  } else if (category === 'assistant') {
    const embed = await buildMaddenTradeGmAssistantEmbed(interaction.guild.id, league, teamName);
    payload = { content: null, embeds: [embed], components: backRow };
  } else if (category === 'block') {
    const blockPayload = await buildMaddenGmBlockCategoryPayload(interaction, league, teamName);
    payload = { content: null, ...blockPayload };
  } else if (category === 'finder') {
    const { rows } = await getMaddenTeamRosterPage(interaction.guild.id, league.league_id, teamName, { offset: 0, limit: 25, excludeFreeAgents: true });
    const encTeam = encodeURIComponent(teamName).slice(0, 80);
    if (!rows.length) {
      payload = { content: 'No roster data found for this team yet.', embeds: [], components: backRow };
    } else {
      const menu = new StringSelectMenuBuilder()
        .setCustomId(`gmpanel_finder_player:${leagueId}:${encTeam}`)
        .setPlaceholder('Choose a player to find trade packages for')
        .addOptions(rows.map(r => ({
          label: String(r.player_name || 'Unknown').slice(0, 100),
          value: String(r.player_name || 'unknown').slice(0, 100),
          description: `${r.position || 'POS'} • ${r.overall || 'N/A'} OVR`.slice(0, 100),
        })));
      payload = {
        content: `**Trade Finder** — pick a player from ${teamName} to find close trade packages for.`,
        embeds: [],
        components: [new ActionRowBuilder().addComponents(menu), buildMaddenGmPanelBackRow(leagueId, teamName)],
      };
    }
  } else if (category === 'builder') {
    const token = randomBytes(6).toString('hex');
    maddenTradeWizardSessions.set(token, {
      leagueId,
      mode: 'builder',
      maxPlayers: 3,
      includePicks: true,
      currentSide: 'A',
      sideA: { team: teamName, players: [], picks: [], rosterPage: 0 },
      sideB: { team: null, players: [], picks: [], rosterPage: 0 },
      returnToTeam: teamName,
      userId: interaction.user.id,
      createdAt: Date.now(),
    });
    await showMaddenTradeWizardSidePickers(interaction, token, { update: true });
    return;
  } else if (category === 'transactions') {
    const embed = await buildMaddenTransactionsRecentEmbed(interaction.guild.id, league, { team: teamName, limit: 15 });
    payload = { content: null, embeds: [embed], components: backRow };
  } else if (category === 'signings') {
    const embed = await buildMaddenSuggestedSigningsEmbed(interaction.guild.id, league, teamName);
    payload = { content: null, embeds: [embed], components: backRow };
  } else {
    payload = { content: 'Unknown section.', embeds: [], components: backRow };
  }

  return update ? interaction.update(payload) : interaction.editReply(payload);
}

// ---------------------------------------------------------------------------
// Admin Panel — server-wide (not per-league) controls for economy, shop, and
// sportsbook. Consolidates existing staff-only slash commands into one panel,
// same pattern as the Commissioner and GM panels.
// ---------------------------------------------------------------------------
function getAdminPanelCategories(lang) {
  return [
    // 7J-115REORDER: Server Setup moved to the top per Hxxdie.
    // English-only (not run through t()) like several other strings added
    // this session — this bot's i18n coverage is still Phase 1 (Admin Panel
    // core only, per the tracking doc's rollout plan), so plain English here
    // is consistent with precedent rather than a regression. Revisit when
    // i18n Phase 2+ actually happens.
    { value: 'serversetup', label: 'Server Setup', description: 'Auto Setup Server Channels, Ticket Settings, Welcome/Leave, Multi-Channel Panels', emoji: '🏗️' },
    { value: 'leagues', label: t(lang, 'cat_leagues_label'), description: t(lang, 'cat_leagues_desc'), emoji: '🏟️' },
    { value: 'economy', label: t(lang, 'cat_economy_label'), description: t(lang, 'cat_economy_desc'), emoji: '💰' },
    { value: 'shop', label: t(lang, 'cat_shop_label'), description: t(lang, 'cat_shop_desc'), emoji: '🛍️' },
    { value: 'sportsbook', label: t(lang, 'cat_sportsbook_label'), description: t(lang, 'cat_sportsbook_desc'), emoji: '📊' },
    { value: 'tournament', label: t(lang, 'cat_tournament_label'), description: t(lang, 'cat_tournament_desc'), emoji: '🏆' },
    // 7J-PREMIUM-PANEL: guild-level, not league-level, so this lives here
    // (Admin Panel) rather than the per-league Commissioner Panel — same
    // reasoning as Server Setup above.
    { value: 'premium', label: 'Premium & Billing', description: 'Subscription status, trial, billing manager', emoji: '💎' },
    { value: 'settings', label: t(lang, 'cat_settings_label'), description: t(lang, 'cat_settings_desc'), emoji: '⚙️' },
  ];
}

function buildAdminPanelHomeEmbed(guild, lang) {
  return new EmbedBuilder()
    .setTitle(t(lang, 'admin_panel_title', { guildName: guild.name }))
    .setColor(0x5865F2)
    .setDescription(t(lang, 'admin_panel_description'))
    .setFooter({ text: t(lang, 'admin_panel_footer') })
    .setTimestamp();
}

function buildAdminPanelHomeComponents(lang) {
  const menu = new StringSelectMenuBuilder()
    .setCustomId('adminpanel_category')
    .setPlaceholder(t(lang, 'admin_panel_category_placeholder'))
    .addOptions(getAdminPanelCategories(lang).map(c => ({ label: c.label, value: c.value, description: c.description, emoji: c.emoji })));
  return [new ActionRowBuilder().addComponents(menu)];
}

function buildAdminPanelBackRow(lang) {
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('adminpanel_back').setLabel(t(lang, 'admin_panel_back')).setStyle(ButtonStyle.Secondary)
  );
}

async function showAdminPanelHome(interaction, { update = true } = {}) {
  const lang = await getEffectiveLanguage(interaction.guild.id, interaction.user.id);
  const payload = { content: null, embeds: [buildAdminPanelHomeEmbed(interaction.guild, lang)], components: buildAdminPanelHomeComponents(lang) };
  return update ? interaction.update(payload) : interaction.reply({ ...payload, ephemeral: true });
}

async function buildAdminLeagueSetupPayload(guild, lang) {
  const result = await pool.query(
    `SELECT * FROM leagues WHERE guild_id = $1 AND is_active = TRUE ORDER BY league_name ASC LIMIT 25`,
    [guild.id]
  );
  const embed = new EmbedBuilder()
    .setTitle(t(lang, 'league_setup_title'))
    .setColor(0x5865F2)
    .setDescription(result.rows.length
      ? result.rows.map(l => `**${l.league_name}** — ${(l.game_key || 'general').toUpperCase()}${l.season_length ? ' • ' + l.season_length + ' games' : ''}`).join('\n')
      : t(lang, 'league_setup_none'))
    .setFooter({ text: t(lang, 'admin_panel_footer') })
    .setTimestamp();

  const components = [];
  if (result.rows.length) {
    // 7J-146REMOVETEAMROLE: "Choose a league to add a team role to" removed
    // per Hxxdie — Auto-Create Team Roles (below) and /league teamrole
    // already cover this; this extra picker was redundant.
    const deleteMenu = new StringSelectMenuBuilder()
      .setCustomId('adminpanel_league_delete_select')
      .setPlaceholder(t(lang, 'league_setup_delete_placeholder'))
      .addOptions(result.rows.map(l => ({ label: l.league_name.slice(0, 100), value: l.league_id.slice(0, 100), description: (l.game_key || 'general').toUpperCase().slice(0, 100) })));
    components.push(new ActionRowBuilder().addComponents(deleteMenu));
  }
  // 7J-112SERVERSETUP: Auto Setup Channels moved OUT of here to the new Server
  // Setup category, per Hxxdie — it was never actually league-specific (it only
  // ever touched guild-wide infrastructure), so Server Setup is the more honest
  // home for it. Auto Create League Roles stays here since roles genuinely ARE
  // per-league settings — clicking it opens a league picker rather than acting
  // on all of them at once. Only shown once at least one league exists.
  // 7J-BUTTONORDER: Create League now sits above Auto Create League Roles —
  // per Hxxdie, the natural order is create the league first, roles second,
  // and the previous order (roles above create) contributed to a misclick
  // that auto-created duplicate roles for an already-set-up league.
  components.push(new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('adminpanel_league_create').setLabel(t(lang, 'league_setup_create_button')).setEmoji('➕').setStyle(ButtonStyle.Success)
  ));
  if (result.rows.length) {
    components.push(new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('adminpanel_autosetup_roles').setLabel('Auto Create League Roles').setEmoji('🏗️').setStyle(ButtonStyle.Secondary),
    ));
  }
  components.push(buildAdminPanelBackRow(lang));
  return { embeds: [embed], components };
}

async function buildAdminEconomyPayload(guild, lang) {
  const settings = await getCurrencySettings(guild.id);
  // Balance is global now (not scoped to this guild), so this reflects total
  // circulation and richest users bot-wide — same treatment as /economy richest.
  const totalResult = await pool.query(
    `SELECT COALESCE(SUM(balance), 0)::int AS total_balance, COUNT(*)::int AS users_with_balance
     FROM user_currency_balances WHERE balance > 0`
  );
  const richest = await pool.query(
    `SELECT * FROM user_currency_balances ORDER BY balance DESC, lifetime_earned DESC LIMIT 5`
  );
  const totals = totalResult.rows?.[0] || { total_balance: 0, users_with_balance: 0 };
  const embed = new EmbedBuilder()
    .setTitle(t(lang, 'economy_title', { currencyName: settings.currency_name }))
    .setColor(0xFEE75C)
    .addFields(
      { name: t(lang, 'economy_total_circulation'), value: `${settings.currency_icon} ${totals.total_balance}`, inline: true },
      { name: t(lang, 'economy_users_with_balance'), value: String(totals.users_with_balance), inline: true },
    )
    .setDescription(richest.rows.length
      ? t(lang, 'economy_top5') + '\n' + richest.rows.map((row, i) => `${i + 1}. <@${row.user_id}> — ${settings.currency_icon} ${row.balance}`).join('\n')
      : t(lang, 'economy_no_balances'))
    .setFooter({ text: t(lang, 'admin_panel_footer') })
    .setTimestamp();
  const row1 = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('adminpanel_econ:give').setLabel(t(lang, 'economy_give_button')).setEmoji('➕').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId('adminpanel_econ:take').setLabel(t(lang, 'economy_take_button')).setEmoji('➖').setStyle(ButtonStyle.Danger),
  );
  const row2 = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('adminpanel_econ:transactions').setLabel(t(lang, 'economy_transactions_button')).setEmoji('📜').setStyle(ButtonStyle.Secondary),
    new ButtonBuilder().setCustomId('adminpanel_econ:settings').setLabel(t(lang, 'economy_settings_button')).setEmoji('⚙️').setStyle(ButtonStyle.Secondary),
  );
  return { embeds: [embed], components: [row1, row2, buildAdminPanelBackRow(lang)] };
}

async function buildAdminShopPayload(guild, lang) {
  const settings = await getCurrencySettings(guild.id);
  const items = await pool.query(
    `SELECT * FROM shop_items WHERE (guild_id = $1 OR guild_id IS NULL) AND is_active = TRUE ORDER BY price ASC, item_name ASC LIMIT 25`,
    [guild.id]
  );
  const embed = new EmbedBuilder()
    .setTitle(t(lang, 'shop_title'))
    .setColor(0xFEE75C)
    .setDescription(items.rows.length
      ? items.rows.map(item => {
          const onSale = item.sale_price !== null && Number(item.sale_price) < Number(item.price);
          const priceText = onSale ? `~~${item.price}~~ **${item.sale_price}** 🔥` : String(item.price);
          return `**${shortShopItemId(item.id)} • ${item.item_name}** — ${settings.currency_icon} ${priceText}${item.stock === null ? '' : ' • Stock: ' + item.stock}`;
        }).join('\n')
      : t(lang, 'shop_none'))
    .setFooter({ text: t(lang, 'admin_panel_footer') })
    .setTimestamp();
  const row1 = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('adminpanel_shop:create').setLabel(t(lang, 'shop_create_button')).setEmoji('➕').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId('adminpanel_shop:remove').setLabel(t(lang, 'shop_remove_button')).setEmoji('➖').setStyle(ButtonStyle.Danger),
    new ButtonBuilder().setCustomId('adminpanel_shop:sales').setLabel(t(lang, 'shop_sales_button')).setEmoji('🔥').setStyle(ButtonStyle.Success),
  );
  return { embeds: [embed], components: [row1, buildAdminPanelBackRow(lang)] };
}

async function buildAdminSportsbookPayload(guild, lang) {
  const settings = await getCurrencySettings(guild.id);
  const games = await pool.query(
    `SELECT * FROM sportsbook_games WHERE guild_id = $1 AND status = 'open' ORDER BY created_at DESC LIMIT 20`,
    [guild.id]
  );
  const embed = buildSportsbookEmbed(settings, games.rows);
  const bounds = await getGuildSportsbookBounds(guild.id);
  embed.addFields({
    name: t(lang, 'sportsbook_limits_field'),
    value: `Bet: ${bounds.min_bet ?? 'none'}–${bounds.max_bet ?? 'none'} • Payout: ${bounds.min_payout ?? 'none'}–${bounds.max_payout ?? 'none'}`,
    inline: false,
  });
  const row1 = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('adminpanel_sb:create').setLabel(t(lang, 'sportsbook_create_button')).setEmoji('➕').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId('adminpanel_sb:settle').setLabel(t(lang, 'sportsbook_settle_button')).setEmoji('🏁').setStyle(ButtonStyle.Primary),
    new ButtonBuilder().setCustomId('adminpanel_sb:refund').setLabel(t(lang, 'sportsbook_refund_button')).setEmoji('↩️').setStyle(ButtonStyle.Danger),
    new ButtonBuilder().setCustomId('adminpanel_sb:limits').setLabel(t(lang, 'sportsbook_limits_button')).setEmoji('📏').setStyle(ButtonStyle.Secondary),
  );
  return { embeds: [embed], components: [row1, buildAdminPanelBackRow(lang)] };
}

// 7J-112SERVERSETUP: Welcome/Leave and Ticket Settings moved OUT of here to
// the new Server Setup category per Hxxdie, leaving just Language +
// Onboarding — freed up enough row budget that this no longer needs to be
// split at all.
// 7J-PREMIUM-PANEL: Premium & Billing category — mirrors /premium's
// subcommands as buttons/selects so nobody has to leave the panel or know
// the slash commands exist, matching how the rest of this bot's setup flow
// works. Viewing is gated the same as every other Admin Panel category
// (userCanUseLeagueSetup, checked before this ever gets called); the
// specific owner-only actions (billing manager assignment, trial start)
// re-check live guild ownership inside their own handlers below, same as
// the /premium slash command does.
async function buildAdminPremiumPayload(guild, lang) {
  const entitlement = await getGuildEntitlement(guild.id);
  const isActive = isEntitlementPremiumActive(entitlement);

  const embed = buildPremiumStatusEmbed(guild, entitlement);
  const components = [];

  if (!isActive && entitlement.status === 'free') {
    components.push(new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('adminpanel_premium_trial').setLabel('Start 14-Day Trial').setEmoji('🎉').setStyle(ButtonStyle.Success),
      new ButtonBuilder().setCustomId('adminpanel_premium_subscribe:monthly').setLabel(`Subscribe Monthly (${PREMIUM_MONTHLY_PRICE_DISPLAY})`).setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('adminpanel_premium_subscribe:annual').setLabel(`Subscribe Annual (${PREMIUM_ANNUAL_PRICE_DISPLAY})`).setStyle(ButtonStyle.Primary),
    ));
  } else if (entitlement.status === 'trialing') {
    components.push(new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('adminpanel_premium_subscribe:monthly').setLabel(`Subscribe Monthly (${PREMIUM_MONTHLY_PRICE_DISPLAY})`).setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('adminpanel_premium_subscribe:annual').setLabel(`Subscribe Annual (${PREMIUM_ANNUAL_PRICE_DISPLAY})`).setStyle(ButtonStyle.Primary),
    ));
  } else if (entitlement.source === 'stripe' && (entitlement.status === 'active' || entitlement.status === 'past_due')) {
    components.push(new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('adminpanel_premium_cancel').setLabel(entitlement.cancel_at_period_end ? 'Cancellation Already Scheduled' : 'Cancel Subscription').setStyle(ButtonStyle.Danger).setDisabled(!!entitlement.cancel_at_period_end),
    ));
  } else if (entitlement.status === 'lapsed') {
    components.push(new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('adminpanel_premium_subscribe:monthly').setLabel(`Reactivate Monthly (${PREMIUM_MONTHLY_PRICE_DISPLAY})`).setStyle(ButtonStyle.Primary),
      new ButtonBuilder().setCustomId('adminpanel_premium_subscribe:annual').setLabel(`Reactivate Annual (${PREMIUM_ANNUAL_PRICE_DISPLAY})`).setStyle(ButtonStyle.Primary),
    ));
  }

  components.push(new ActionRowBuilder().addComponents(
    new UserSelectMenuBuilder().setCustomId('adminpanel_premium_billingmanager_select').setPlaceholder(entitlement.billing_manager_user_id ? 'Change billing manager (owner only)' : 'Set a billing manager (owner only)')
  ));
  if (entitlement.billing_manager_user_id) {
    components.push(new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('adminpanel_premium_billingmanager_clear').setLabel('Clear Billing Manager').setStyle(ButtonStyle.Secondary),
    ));
  }
  components.push(buildAdminPanelBackRow(lang));

  return { embeds: [embed], components };
}

async function buildAdminSettingsPayload(guild, lang) {
  const settings = await getGuildSettings(guild.id, guild.name);
  const currentLang = SUPPORTED_LANGUAGES.find(l => l.value === settings.language) || SUPPORTED_LANGUAGES[0];
  const embed = new EmbedBuilder()
    .setTitle(t(lang, 'settings_title'))
    .setColor(0x5865F2)
    .addFields(
      { name: t(lang, 'settings_language_field'), value: `${currentLang.emoji} ${currentLang.label}`, inline: true },
      { name: t(lang, 'settings_onboarding_field'), value: settings.onboarding_enabled ? t(lang, 'settings_onboarding_enabled') : t(lang, 'settings_onboarding_disabled'), inline: true },
    )
    .setDescription(t(lang, 'settings_description') + '\n\nWelcome/Leave and Ticket Settings moved to **Server Setup**.')
    .setFooter({ text: t(lang, 'admin_panel_footer') })
    .setTimestamp();

  const languageMenu = new StringSelectMenuBuilder()
    .setCustomId('adminpanel_settings_language_select')
    .setPlaceholder(t(lang, 'settings_language_placeholder'))
    .addOptions(SUPPORTED_LANGUAGES.map(l => ({ label: l.label, value: l.value, emoji: l.emoji, default: l.value === settings.language })));

  const toggleRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder()
      .setCustomId('adminpanel_settings_onboarding_toggle')
      .setLabel(settings.onboarding_enabled ? t(lang, 'settings_onboarding_disable_button') : t(lang, 'settings_onboarding_enable_button'))
      .setEmoji(settings.onboarding_enabled ? '🚫' : '✅')
      .setStyle(settings.onboarding_enabled ? ButtonStyle.Danger : ButtonStyle.Success),
  );

  return { embeds: [embed], components: [new ActionRowBuilder().addComponents(languageMenu), toggleRow, buildAdminPanelBackRow(lang)] };
}

// 7J-112SERVERSETUP: entry point for everything guild-wide-infrastructure —
// Auto Setup Server Channels (renamed from Auto Setup Channels, moved from
// League Setup — it was never league-specific), Ticket Settings and
// Welcome/Leave (both moved from Server Settings), and the Multi-Channel
// Panels manager (moved from Commissioner Panel's Setup Dashboard/Panels —
// per Hxxdie these 7 panel types were never league-specific either, so they
// don't belong on a per-league page). Kept to 3 rows so there's headroom.
async function buildAdminServerSetupPayload(guild, lang) {
  const settings = await getGuildSettings(guild.id, guild.name);
  const embed = new EmbedBuilder()
    .setTitle('🏗️ Server Setup')
    .setColor(0x5865F2)
    .setDescription('Guild-wide infrastructure — none of this is tied to a specific league.')
    .addFields(
      { name: 'Welcome/Leave Announcements', value: settings.welcome_leave_enabled ? '✅ Enabled' : '🚫 Disabled', inline: true },
      { name: 'Ticket Channel', value: settings.ticket_channel_id ? `<#${settings.ticket_channel_id}>` : 'Not set', inline: true },
      { name: 'Support Channel', value: settings.support_channel_id ? `<#${settings.support_channel_id}>` : 'Not set', inline: true },
    )
    .setFooter({ text: t(lang, 'admin_panel_footer') })
    .setTimestamp();

  // 7J-124TICKETMERGE: Ticket Settings' standalone button folded into this
  // same select, per Hxxdie — one consistent entry point for every guild-
  // wide channel setting instead of a separate button living outside it.
  // Tickets/Support aren't true multi-channel panels underneath (each is
  // still a single configured channel, not "post in as many channels as you
  // want" like the other 7) — selecting either one here routes to
  // buildAdminTicketSettingsPayload instead of buildMultiChannelPanelManagerPayload,
  // see the adminpanel_serversetup_multichannel_select handler.
  const actionRow = new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('adminpanel_serversetup_autosetup').setLabel('Auto Setup Server Channels').setEmoji('🏗️').setStyle(ButtonStyle.Success),
    new ButtonBuilder().setCustomId('adminpanel_serversetup_welcomeleave').setLabel('Welcome/Leave Setup').setEmoji('👋').setStyle(ButtonStyle.Secondary),
    new ButtonBuilder().setCustomId('adminpanel_serversetup_checkperms').setLabel('Check Bot Permissions').setEmoji('🔐').setStyle(ButtonStyle.Secondary),
  );

  const multiChannelMenu = new StringSelectMenuBuilder()
    .setCustomId('adminpanel_serversetup_multichannel_select')
    .setPlaceholder('Manage a Multi-Channel Panel')
    .addOptions([
      ...Object.entries(MULTI_CHANNEL_DASHBOARD_MAP).map(([, panelType]) => {
        const info = getMultiChannelPanelInfo(panelType);
        return { label: info?.label || panelType, value: panelType, description: `Manage which channel(s) the ${info?.label || panelType} panel is posted in`.slice(0, 100) };
      }),
      { label: 'Tickets', value: 'ticket', description: 'Ticket Channel, Support Channel, and Admin Notify Role' },
      { label: 'Support', value: 'support', description: 'Ticket Channel, Support Channel, and Admin Notify Role' },
    ]);

  return { embeds: [embed], components: [actionRow, new ActionRowBuilder().addComponents(multiChannelMenu), buildAdminPanelBackRow(lang)] };
}

