async function expandFullLeagueTeamDiscovery(context, guild, league, hub, label = 'full-discovery') {
  const enabled = String(process.env.EA_FULL_TEAM_DISCOVERY_ENABLED || 'true').toLowerCase() !== 'false';
  if (!enabled) return null;

  const discovery = await loadImportedMaddenTeamSeedMap(guild, league);

  // Source 1: recursively discovered analytics objects from the full 811 hub.
  const recursiveObjects = deepFindMaddenTeamAnalyticsObjects(hub);
  for (const item of recursiveObjects) {
    mergeTeamIntoDiscoveryMap(discovery, item.normalized, item.path || 'hub:recursive');
  }

  // Source 2: explicit RequestInfo season-game analytics.
  const careerHubInfo = getAnyValue(hub, ['careerHubInfo'], {}) || {};
  const requestInfoList =
    getAnyValue(careerHubInfo, ['requestInfoList'], null) ||
    getAnyValue(hub, ['requestInfoList'], null) ||
    [];

  if (Array.isArray(requestInfoList)) {
    for (let i = 0; i < requestInfoList.length; i++) {
      const analytics = extractRequestInfoSeasonGameAnalytics(requestInfoList[i], i);
      if (!analytics) continue;
      mergeTeamIntoDiscoveryMap(discovery, analytics.awayTeamInfo, 'careerHubInfo.requestInfoList[' + i + '].awayTeamInfo');
      mergeTeamIntoDiscoveryMap(discovery, analytics.homeTeamInfo, 'careerHubInfo.requestInfoList[' + i + '].homeTeamInfo');
    }
  }

  // Source 3: schedule rows can seed team names for all 32 even without score.
  const scheduleRows = collectEaScheduleCandidateRows(hub);
  const teamMapsForDiscovery =
    typeof buildEaTeamNameMapsFromHub === 'function'
      ? buildEaTeamNameMapsFromHub(hub)
      : (typeof buildEaTeamNameMaps === 'function'
        ? buildEaTeamNameMaps(hub)
        : (typeof buildEaTeamNameMapsFromLeagueHub === 'function'
          ? buildEaTeamNameMapsFromLeagueHub(hub)
          : {}));

  for (const row of scheduleRows) {
    const game = row.item?.seasonGameInfo || row.item?.gameInfo || row.item || {};
    const homeTeam = safeDiscoveryTeamNameFromGameSide(game, 'home', teamMapsForDiscovery);
    const awayTeam = safeDiscoveryTeamNameFromGameSide(game, 'away', teamMapsForDiscovery);

    if (homeTeam) mergeTeamIntoDiscoveryMap(discovery, { canonicalName: homeTeam, teamName: homeTeam }, row.sourceLabel + ':home');
    if (awayTeam) mergeTeamIntoDiscoveryMap(discovery, { canonicalName: awayTeam, teamName: awayTeam }, row.sourceLabel + ':away');

    const homeScore = parseNumberOrNull(getAnyValue(game, ['homeScore', 'home_score'], null));
    const awayScore = parseNumberOrNull(getAnyValue(game, ['awayScore', 'away_score'], null));

    if (hasUsableMaddenScorePair(homeScore, awayScore)) {
      mergeTeamIntoDiscoveryMap(discovery, {
        canonicalName: homeTeam,
        teamTotalPointsScored: homeScore,
        teamTotalPointsAllowed: awayScore,
      }, row.sourceLabel + ':score:home');

      mergeTeamIntoDiscoveryMap(discovery, {
        canonicalName: awayTeam,
        teamTotalPointsScored: awayScore,
        teamTotalPointsAllowed: homeScore,
      }, row.sourceLabel + ':score:away');
    }
  }

  const teams = Array.from(discovery.values()).sort((a, b) => String(a.canonicalName).localeCompare(String(b.canonicalName)));
  const pfPaTeams = teams.filter(team =>
    parseNumberOrNull(team.teamTotalPointsScored) !== null &&
    parseNumberOrNull(team.teamTotalPointsAllowed) !== null &&
    (
      Number(team.teamTotalPointsScored || 0) > 0 ||
      Number(team.teamTotalPointsAllowed || 0) > 0
    )
  );

  console.log('[FULL TEAM DISCOVERY 7J-5D] ' + JSON.stringify({
    label,
    totalTeams: teams.length,
    pfPaTeams: pfPaTeams.length,
    teams: teams.map(team => ({
      team: team.canonicalName,
      wins: team.wins,
      losses: team.losses,
      ties: team.ties,
      pf: team.teamTotalPointsScored,
      pa: team.teamTotalPointsAllowed,
      sources: team.sourcePaths,
      topThreats: (team.topThreats || []).slice(0, 2).map(p => ({
        name: [p.firstName, p.lastName].filter(Boolean).join(' '),
        ovr: p.ovr,
        s1: p.stat1Label,
        v1: p.stat1Value,
      })),
    })),
  }).slice(0, 24000));

  const shouldWrite = String(process.env.EA_FULL_TEAM_DISCOVERY_WRITE || 'true').toLowerCase() !== 'false';
  if (shouldWrite) {
    let updated = 0;
    const updateResults = [];

    for (const team of pfPaTeams) {
      const pf = parseNumberOrNull(team.teamTotalPointsScored);
      const pa = parseNumberOrNull(team.teamTotalPointsAllowed);
      if (pf === null || pa === null) continue;

      const result = await pool.query(
        `UPDATE madden_imported_team_stats
         SET points_for = CASE WHEN COALESCE(scored_games, 0) = 0 THEN $3 ELSE points_for END,
             points_against = CASE WHEN COALESCE(scored_games, 0) = 0 THEN $4 ELSE points_against END,
             imported_at = NOW()
         WHERE guild_id = $1 AND league_id = $2 AND LOWER(team_name) = LOWER($5)`,
        [guild.id, league.league_id, pf, pa, team.canonicalName]
      );

      updated += Number(result.rowCount || 0);
      updateResults.push({
        teamName: team.canonicalName,
        pf,
        pa,
        rowCount: Number(result.rowCount || 0),
      });
    }

    console.log('[FULL TEAM DISCOVERY WRITE 7J-5D] ' + JSON.stringify({
      updated,
      updateResults,
    }).slice(0, 12000));
  }

  return { teams, pfPaTeams };
}



function normalizeMaddenScheduleScoreCandidate(gameLike) {
  const game = gameLike?.seasonGameInfo || gameLike?.gameInfo || gameLike || {};

  const deep = resolveMaddenScoresFromRawGameDeep(game);
  const shallow = resolveMaddenScoresFromRawGame(game);

  const candidates = [
    {
      source: 'direct-seasonGameInfo',
      homeScore: getAnyValue(game, ['homeScore', 'home_score', 'homeTeamScore', 'homePts', 'homePoints'], null),
      awayScore: getAnyValue(game, ['awayScore', 'away_score', 'awayTeamScore', 'awayPts', 'awayPoints'], null),
    },
    {
      source: 'deep-resolver',
      homeScore: deep.homeScore,
      awayScore: deep.awayScore,
    },
    {
      source: 'shallow-resolver',
      homeScore: shallow.homeScore,
      awayScore: shallow.awayScore,
    },
    {
      source: 'seasonGameInfo-raw',
      homeScore: getAnyValue(game, ['seasonGameInfo.homeScore', 'seasonGameInfo.home_score'], null),
      awayScore: getAnyValue(game, ['seasonGameInfo.awayScore', 'seasonGameInfo.away_score'], null),
    },
    {
      source: 'scoreInfo',
      homeScore: getAnyValue(game, ['scoreInfo.homeScore', 'scoreInfo.home_score', 'scoreInfo.home'], null),
      awayScore: getAnyValue(game, ['scoreInfo.awayScore', 'scoreInfo.away_score', 'scoreInfo.away'], null),
    },
    {
      source: 'boxScore',
      homeScore: getAnyValue(game, ['boxScore.homeScore', 'boxScore.home_score', 'boxScore.home'], null),
      awayScore: getAnyValue(game, ['boxScore.awayScore', 'boxScore.away_score', 'boxScore.away'], null),
    },
  ];

  for (const candidate of candidates) {
    const homeScore = parseNumberOrNull(candidate.homeScore);
    const awayScore = parseNumberOrNull(candidate.awayScore);
    if (hasUsableMaddenScorePair(homeScore, awayScore)) {
      return {
        hasScore: true,
        source: candidate.source,
        homeScore,
        awayScore,
        deep,
        shallow,
      };
    }
  }

  return {
    hasScore: false,
    source: 'none',
    homeScore: parseNumberOrNull(candidates[0].homeScore) ?? 0,
    awayScore: parseNumberOrNull(candidates[0].awayScore) ?? 0,
    deep,
    shallow,
  };
}

function buildScheduleScoreAccumulatorFromHub(hub) {
  const teamMaps =
    typeof buildEaTeamNameMapsFromHub === 'function'
      ? buildEaTeamNameMapsFromHub(hub)
      : (typeof buildEaTeamNameMaps === 'function'
        ? buildEaTeamNameMaps(hub)
        : (typeof buildEaTeamNameMapsFromLeagueHub === 'function'
          ? buildEaTeamNameMapsFromLeagueHub(hub)
          : {}));

  const rows = collectEaScheduleCandidateRows(hub);
  const accumulator = new Map();
  const scoredGames = [];
  const unscoredGames = [];

  function ensure(teamName) {
    const canonical = canonicalMaddenTeamNameFromAny(teamName);
    if (!canonical) return null;

    const key = canonical.toLowerCase();
    if (!accumulator.has(key)) {
      accumulator.set(key, {
        teamName: canonical,
        points_for: 0,
        points_against: 0,
        scored_games: 0,
        sources: [],
      });
    }
    return accumulator.get(key);
  }

  for (const row of rows) {
    const game = row.item?.seasonGameInfo || row.item?.gameInfo || row.item || {};

    const homeTeam = safeDiscoveryTeamNameFromGameSide(game, 'home', teamMaps);
    const awayTeam = safeDiscoveryTeamNameFromGameSide(game, 'away', teamMaps);

    if (!homeTeam || !awayTeam) continue;

    ensure(homeTeam);
    ensure(awayTeam);

    const score = normalizeMaddenScheduleScoreCandidate(game);
    const status = String(
      getAnyValue(game, ['status', 'result', 'gameStatus'], '') ||
      getAnyValue(row.item, ['status', 'result', 'gameStatus'], '') ||
      ''
    ).toLowerCase();

    const isCompleted =
      status.includes('complete') ||
      status.includes('final') ||
      getAnyValue(game, ['isComplete', 'isCompleted', 'isGamePlayed'], false) === true ||
      getAnyValue(game, ['isGamePlayed'], false) === true ||
      getAnyValue(game, ['homeWin'], null) !== null ||
      getAnyValue(game, ['awayWin'], null) !== null ||
      getAnyValue(game, ['homeLoss'], null) !== null ||
      getAnyValue(game, ['awayLoss'], null) !== null;

    const gameSummary = {
      sourceLabel: row.sourceLabel,
      week: getAnyValue(game, ['week', 'displayedWeek', 'weekLabel'], null),
      matchup: getAnyValue(game, ['matchup'], null) || (awayTeam + ' @ ' + homeTeam),
      homeTeam,
      awayTeam,
      status,
      isCompleted,
      homeScore: score.homeScore,
      awayScore: score.awayScore,
      scoreSource: score.source,
      hasScore: score.hasScore,
      keys: Object.keys(game || {}).slice(0, 100),
      excerpt: compactMaddenRawExcerpt(game),
    };

    if (!isCompleted || !score.hasScore) {
      if (unscoredGames.length < 40) unscoredGames.push(gameSummary);
      continue;
    }

    const home = ensure(homeTeam);
    const away = ensure(awayTeam);
    if (!home || !away) continue;

    home.points_for += score.homeScore;
    home.points_against += score.awayScore;
    home.scored_games += 1;
    home.sources.push(row.sourceLabel + ':' + score.source);

    away.points_for += score.awayScore;
    away.points_against += score.homeScore;
    away.scored_games += 1;
    away.sources.push(row.sourceLabel + ':' + score.source);

    scoredGames.push(gameSummary);
  }

  return {
    teams: Array.from(accumulator.values()).sort((a, b) => String(a.teamName).localeCompare(String(b.teamName))),
    scoredGames,
    unscoredGames,
    totalScheduleRows: rows.length,
  };
}

async function accumulatePfPaFromHubScheduleScores(context, guild, league, hub, label = 'hub-schedule-accumulator') {
  const enabled = String(process.env.EA_HUB_SCHEDULE_SCORE_ACCUMULATOR_ENABLED || 'true').toLowerCase() !== 'false';
  if (!enabled) return null;

  const result = buildScheduleScoreAccumulatorFromHub(hub);
  const pfPaTeams = result.teams.filter(team => team.scored_games > 0 && (team.points_for > 0 || team.points_against > 0));

  console.log('[HUB SCHEDULE SCORE ACCUMULATOR 7J-5D] ' + JSON.stringify({
    label,
    totalScheduleRows: result.totalScheduleRows,
    totalTeamsSeeded: result.teams.length,
    scoredGames: result.scoredGames.length,
    unscoredGameSamples: result.unscoredGames.slice(0, 20).map(g => ({
      week: g.week,
      matchup: g.matchup,
      status: g.status,
      isCompleted: g.isCompleted,
      homeScore: g.homeScore,
      awayScore: g.awayScore,
      scoreSource: g.scoreSource,
      hasScore: g.hasScore,
      keys: g.keys,
    })),
    scoredGameSamples: result.scoredGames.slice(0, 20).map(g => ({
      week: g.week,
      matchup: g.matchup,
      homeScore: g.homeScore,
      awayScore: g.awayScore,
      source: g.scoreSource,
    })),
    pfPaTeams,
    conclusion: pfPaTeams.length
      ? 'Hub schedule exposed usable scores; PF/PA accumulator can write full league values.'
      : 'Hub schedule did not expose usable nonzero scores; preserving RequestInfo/DB PF/PA values only.',
  }).slice(0, 24000));

  const shouldWrite = String(process.env.EA_HUB_SCHEDULE_SCORE_ACCUMULATOR_WRITE || 'true').toLowerCase() !== 'false';
  if (shouldWrite && pfPaTeams.length) {
    let updated = 0;
    const updateResults = [];

    for (const team of pfPaTeams) {
      const queryResult = await pool.query(
        `UPDATE madden_imported_team_stats
         SET points_for = CASE WHEN COALESCE(scored_games, 0) = 0 THEN $3 ELSE points_for END,
             points_against = CASE WHEN COALESCE(scored_games, 0) = 0 THEN $4 ELSE points_against END,
             imported_at = NOW()
         WHERE guild_id = $1 AND league_id = $2 AND LOWER(team_name) = LOWER($5)`,
        [guild.id, league.league_id, team.points_for, team.points_against, team.teamName]
      );

      updated += Number(queryResult.rowCount || 0);
      updateResults.push({
        teamName: team.teamName,
        pf: team.points_for,
        pa: team.points_against,
        scoredGames: team.scored_games,
        rowCount: Number(queryResult.rowCount || 0),
      });
    }

    console.log('[HUB SCHEDULE SCORE ACCUMULATOR WRITE 7J-5D] ' + JSON.stringify({
      updated,
      updateResults,
    }).slice(0, 12000));
  }

  return result;
}


async function synthesizeFullLeaguePfPaFromSchedule(guild, league, label = 'schedule-derived') {
  const enabled = String(process.env.EA_SCHEDULE_DERIVED_PFPA_ENABLED || 'true').toLowerCase() !== 'false';
  if (!enabled) return null;

  const gamesResult = await pool.query(
    `SELECT *
     FROM madden_imported_games
     WHERE guild_id = $1
       AND league_id = $2
       AND LOWER(COALESCE(status, '')) IN ('completed', 'final', 'completed_with_real_score', 'away_win', 'home_win', 'tie')
     ORDER BY week_label ASC, imported_at ASC`,
    [guild.id, league.league_id]
  );

  const records = new Map();
  const samples = [];
  let scoredGames = 0;
  let unscoredGames = 0;

  function ensure(teamName) {
    const canonical = canonicalMaddenTeamNameFromAny(teamName);
    const key = String(canonical || teamName || '').toLowerCase();
    if (!key) return null;
    if (!records.has(key)) {
      records.set(key, {
        teamName: canonical || teamName,
        points_for: 0,
        points_against: 0,
        scored_games: 0,
      });
    }
    return records.get(key);
  }

  for (const game of gamesResult.rows || []) {
    const homeTeam = canonicalMaddenTeamNameFromAny(game.home_team);
    const awayTeam = canonicalMaddenTeamNameFromAny(game.away_team);
    if (!homeTeam || !awayTeam) continue;

    const deep = resolveMaddenScoresFromRawGameDeep(game);
    const shallow = resolveMaddenScoresFromRawGame(game);

    let homeScore = parseNumberOrNull(deep.homeScore);
    let awayScore = parseNumberOrNull(deep.awayScore);
    let source = 'raw-deep';

    if (!hasUsableMaddenScorePair(homeScore, awayScore)) {
      homeScore = parseNumberOrNull(shallow.homeScore);
      awayScore = parseNumberOrNull(shallow.awayScore);
      source = 'raw-shallow';
    }

    if (!hasUsableMaddenScorePair(homeScore, awayScore)) {
      homeScore = parseNumberOrNull(game.home_score);
      awayScore = parseNumberOrNull(game.away_score);
      source = 'db-columns';
    }

    const usable = hasUsableMaddenScorePair(homeScore, awayScore);

    if (!usable) {
      unscoredGames += 1;
      if (samples.length < 20) {
        samples.push({
          week: game.week_label,
          matchup: awayTeam + ' @ ' + homeTeam,
          usable: false,
          dbHomeScore: game.home_score,
          dbAwayScore: game.away_score,
          deep,
          shallow,
        });
      }
      continue;
    }

    const home = ensure(homeTeam);
    const away = ensure(awayTeam);
    if (!home || !away) continue;

    home.points_for += homeScore;
    home.points_against += awayScore;
    home.scored_games += 1;

    away.points_for += awayScore;
    away.points_against += homeScore;
    away.scored_games += 1;

    scoredGames += 1;
    if (samples.length < 20) {
      samples.push({
        week: game.week_label,
        matchup: awayTeam + ' @ ' + homeTeam,
        source,
        homeScore,
        awayScore,
      });
    }
  }

  const scheduleTeams = Array.from(records.values())
    .filter(row => row.scored_games > 0)
    .sort((a, b) => String(a.teamName).localeCompare(String(b.teamName)));

  console.log('[SCHEDULE PFPA SYNTHESIS 7J-5D] ' + JSON.stringify({
    label,
    totalCompletedGames: gamesResult.rows.length,
    scoredGames,
    unscoredGames,
    scheduleTeamCount: scheduleTeams.length,
    scheduleTeams,
    samples,
  }).slice(0, 18000));

  const shouldWrite = String(process.env.EA_SCHEDULE_DERIVED_PFPA_WRITE || 'true').toLowerCase() !== 'false';
  if (shouldWrite && scheduleTeams.length) {
    let updated = 0;
    const updateResults = [];

    for (const team of scheduleTeams) {
      const result = await pool.query(
        `UPDATE madden_imported_team_stats
         SET points_for = CASE WHEN COALESCE(scored_games, 0) = 0 THEN $3 ELSE points_for END,
             points_against = CASE WHEN COALESCE(scored_games, 0) = 0 THEN $4 ELSE points_against END,
             imported_at = NOW()
         WHERE guild_id = $1 AND league_id = $2 AND LOWER(team_name) = LOWER($5)`,
        [guild.id, league.league_id, team.points_for, team.points_against, team.teamName]
      );

      updated += Number(result.rowCount || 0);
      updateResults.push({
        teamName: team.teamName,
        pf: team.points_for,
        pa: team.points_against,
        scoredGames: team.scored_games,
        rowCount: Number(result.rowCount || 0),
      });
    }

    console.log('[SCHEDULE PFPA WRITE 7J-5D] ' + JSON.stringify({
      updated,
      updateResults,
    }).slice(0, 12000));
  }

  return { records, scheduleTeams, scoredGames, unscoredGames };
}


async function harvestFullLeagueRequestInfoAnalytics(context, guild, league, hub) {
  const enabled = String(process.env.EA_FULL_LEAGUE_ANALYTICS_EXPANSION_ENABLED || 'true').toLowerCase() !== 'false';
  if (!enabled) return null;

  const allObjects = deepFindMaddenTeamAnalyticsObjects(hub);
  const mergedTeams = mergeMaddenTeamAnalyticsObjects(allObjects);

  const pfPaTeams = mergedTeams.filter(team =>
    team.teamTotalPointsScored !== null &&
    team.teamTotalPointsAllowed !== null &&
    team.teamTotalPointsScored !== undefined &&
    team.teamTotalPointsAllowed !== undefined
  );

  console.log('[FULL LEAGUE ANALYTICS EXPANSION 7J-5D] ' + JSON.stringify({
    leagueId: context.externalLeagueId,
    leagueName: league?.league_name,
    rawTeamObjectCount: allObjects.length,
    mergedTeamCount: mergedTeams.length,
    pfPaTeamCount: pfPaTeams.length,
    pfPaTeams: pfPaTeams.map(team => ({
      team: team.canonicalName,
      displayName: team.displayName,
      teamName: team.teamName,
      wins: team.wins,
      losses: team.losses,
      ties: team.ties,
      pf: team.teamTotalPointsScored,
      pa: team.teamTotalPointsAllowed,
      pfRank: team.teamTotalPointsScoredRank,
      paRank: team.teamTotalPointsAllowedRank,
      sourcePaths: team.sourcePaths,
      topThreats: (team.topThreats || []).slice(0, 3).map(p => ({
        name: [p.firstName, p.lastName].filter(Boolean).join(' '),
        ovr: p.ovr,
        s1: p.stat1Label,
        v1: p.stat1Value,
        s2: p.stat2Label,
        v2: p.stat2Value,
      })),
    })).slice(0, 40),
    mergedTeamsSample: mergedTeams.slice(0, 40).map(team => ({
      team: team.canonicalName,
      wins: team.wins,
      losses: team.losses,
      pf: team.teamTotalPointsScored,
      pa: team.teamTotalPointsAllowed,
      qualityScore: team.qualityScore,
      sourcePaths: team.sourcePaths,
    })),
  }).slice(0, 30000));

  const shouldWrite = String(process.env.EA_FULL_LEAGUE_ANALYTICS_WRITE || 'true').toLowerCase() !== 'false';
  if (shouldWrite) {
    let updated = 0;
    const updateResults = [];

    for (const team of pfPaTeams) {
      const teamName = team.canonicalName || team.displayName || team.teamName;
      const pf = parseNumberOrNull(team.teamTotalPointsScored);
      const pa = parseNumberOrNull(team.teamTotalPointsAllowed);
      if (!teamName || pf === null || pa === null) continue;

      // 7J-85PPGFIX: same bug as harvestRequestInfoTeamAnalytics above, and
      // this one runs even later in the sync pipeline — CASE WHEN $3 > 0 OR
      // $4 > 0 is true for virtually any real game data, so this was an
      // unconditional overwrite in practice, re-clobbering the correct
      // per-game accumulator totals on every sync regardless of the sibling
      // fix. Same guard applied: only fill in when we have no game-log data
      // of our own (scored_games = 0), never override good data.
      const result = await pool.query(
        `UPDATE madden_imported_team_stats
         SET points_for = CASE WHEN COALESCE(scored_games, 0) = 0 THEN $3 ELSE points_for END,
             points_against = CASE WHEN COALESCE(scored_games, 0) = 0 THEN $4 ELSE points_against END,
             imported_at = NOW()
         WHERE guild_id = $1 AND league_id = $2 AND LOWER(team_name) = LOWER($5)`,
        [guild.id, league.league_id, pf, pa, teamName]
      );

      updated += Number(result.rowCount || 0);
      updateResults.push({ teamName, pf, pa, rowCount: Number(result.rowCount || 0) });
    }

    console.log('[FULL LEAGUE ANALYTICS WRITE 7J-5D] ' + JSON.stringify({
      updated,
      updateResults,
    }).slice(0, 12000));
  }

  return { allObjects, mergedTeams, pfPaTeams };
}


function extractRequestInfoSeasonGameAnalytics(entry, index) {
  const requestData = getAnyValue(entry, ['requestData', 'data'], {}) || {};
  const value = getAnyValue(requestData, ['value'], requestData) || {};

  const awayTeamInfo =
    getAnyValue(value, ['awayTeamInfo'], null) ||
    getAnyValue(value, ['awayTeam'], null) ||
    null;

  const homeTeamInfo =
    getAnyValue(value, ['homeTeamInfo'], null) ||
    getAnyValue(value, ['homeTeam'], null) ||
    null;

  const hasTeamInfo = Boolean(awayTeamInfo || homeTeamInfo);

  if (!hasTeamInfo) return null;

  const awayScore = parseNumberOrNull(getAnyValue(value, ['awayScore'], null));
  const homeScore = parseNumberOrNull(getAnyValue(value, ['homeScore'], null));
  const hasRealScore = awayScore !== null && homeScore !== null && (awayScore !== 0 || homeScore !== 0);

  return {
    index,
    title: getAnyValue(entry, ['title'], null),
    type: getAnyValue(entry, ['type'], null),
    description: getAnyValue(entry, ['description'], null),
    requestId: getAnyValue(entry, ['requestId'], null),
    gameContext: {
      week: getAnyValue(value, ['week'], null),
      weekTitle: getAnyValue(value, ['weekTitle'], null),
      gameTime: getAnyValue(value, ['gameTime'], null),
      gameLocation: getAnyValue(value, ['gameLocation'], null),
      gameGoalKey: getAnyValue(value, ['gameGoalKey'], null),
      gameSetupKey: getAnyValue(value, ['gameSetupKey'], null),
      isComplete: getAnyValue(value, ['isComplete'], null),
      navigationString: getAnyValue(value, ['navigationString'], null),
      awayScore,
      homeScore,
      hasRealScore,
    },
    awayTeamInfo: normalizeRequestInfoTeamAnalytics(awayTeamInfo, 'away'),
    homeTeamInfo: normalizeRequestInfoTeamAnalytics(homeTeamInfo, 'home'),
    valueKeys: Object.keys(value || {}).slice(0, 120),
  };
}





async function harvestRequestInfoTeamAnalytics(context, guild, league, hub) {
  const enabled = String(process.env.EA_REQUEST_INFO_HARVEST_ENABLED || 'true').toLowerCase() !== 'false';
  if (!enabled) return null;

  const careerHubInfo = getAnyValue(hub, ['careerHubInfo'], {}) || {};
  const requestInfoList =
    getAnyValue(careerHubInfo, ['requestInfoList'], null) ||
    getAnyValue(hub, ['requestInfoList'], null) ||
    [];

  if (!Array.isArray(requestInfoList)) {
    console.log('[REQUESTINFO HARVEST 7J-5D] ' + JSON.stringify({
      leagueId: context.externalLeagueId,
      found: false,
      requestInfoType: typeof requestInfoList,
    }));
    return null;
  }

  const seasonGameAnalytics = requestInfoList
    .map((entry, index) => extractRequestInfoSeasonGameAnalytics(entry, index))
    .filter(Boolean);

  const teamsByName = new Map();

  function mergeTeam(team) {
    if (!team) return;
    const key = String(team.canonicalName || team.displayName || team.teamName || '').toLowerCase();
    if (!key) return;

    const existing = teamsByName.get(key) || {};
    teamsByName.set(key, {
      ...existing,
      ...Object.fromEntries(Object.entries(team).filter(([, value]) => value !== null && value !== undefined && value !== '')),
      topThreats: team.topThreats?.length ? team.topThreats : (existing.topThreats || []),
      seenInRequestInfo: true,
    });
  }

  for (const item of seasonGameAnalytics) {
    mergeTeam(item.awayTeamInfo);
    mergeTeam(item.homeTeamInfo);
  }

  const teamAnalytics = Array.from(teamsByName.values());

  console.log('[REQUESTINFO HARVEST 7J-5D] ' + JSON.stringify({
    leagueId: context.externalLeagueId,
    leagueName: league?.league_name,
    totalRequests: requestInfoList.length,
    seasonGameAnalyticsCount: seasonGameAnalytics.length,
    teamAnalyticsCount: teamAnalytics.length,
    seasonGameAnalytics: seasonGameAnalytics.slice(0, 8),
    teamAnalytics: teamAnalytics.slice(0, 16),
    scoreCandidates: seasonGameAnalytics
      .filter(item => item.gameContext?.awayScore !== null || item.gameContext?.homeScore !== null)
      .map(item => ({
        index: item.index,
        title: item.title,
        away: item.awayTeamInfo?.displayName || item.awayTeamInfo?.teamName,
        home: item.homeTeamInfo?.displayName || item.homeTeamInfo?.teamName,
        awayScore: item.gameContext.awayScore,
        homeScore: item.gameContext.homeScore,
        hasRealScore: item.gameContext.hasRealScore,
      })),
    pfPaCandidates: teamAnalytics.map(team => ({
      team: team.displayName || team.teamName,
      wins: team.wins,
      losses: team.losses,
      pf: team.teamTotalPointsScored,
      pa: team.teamTotalPointsAllowed,
      pfRank: team.teamTotalPointsScoredRank,
      paRank: team.teamTotalPointsAllowedRank,
      topThreats: (team.topThreats || []).slice(0, 3).map(p => ({
        name: [p.firstName, p.lastName].filter(Boolean).join(' '),
        ovr: p.ovr,
        s1: p.stat1Label,
        v1: p.stat1Value,
        s2: p.stat2Label,
        v2: p.stat2Value,
      })),
    })),
  }).slice(0, 30000));

  // Optional controlled write: only use requestInfo PF/PA when it looks real and complete enough.
  const shouldWrite = String(process.env.EA_REQUEST_INFO_HARVEST_WRITE || 'true').toLowerCase() !== 'false';
  if (shouldWrite) {
    let updated = 0;
    for (const team of teamAnalytics) {
      const teamName = team.canonicalName || team.displayName || team.teamName;
      const pf = team.teamTotalPointsScored;
      const pa = team.teamTotalPointsAllowed;
      if (!teamName || pf === null || pa === null) continue;

      // 7J-85PPGFIX: this ran every sync, right after
      // recalculateMaddenStandingsFromImportedGames — the per-game accumulator
      // proven correct by the 7J-47PPG fix above — and unconditionally
      // overwrote its points_for/points_against with EA's requestInfoList
      // totals, with no plausibility check despite the comment above claiming
      // otherwise. EA's requestInfoList appears to only cover a recent window
      // of games rather than the full season, so this was silently
      // reintroducing a PPG/PAPG deflation on every single sync — exactly why
      // a plain re-sync alone never fixed it. Now only used as a bootstrap
      // fallback for teams with no game-log-derived data of our own yet
      // (scored_games = 0), never as a standing override of good data.
      const result = await pool.query(
        `UPDATE madden_imported_team_stats
         SET points_for = CASE WHEN COALESCE(scored_games, 0) = 0 THEN $3 ELSE points_for END,
             points_against = CASE WHEN COALESCE(scored_games, 0) = 0 THEN $4 ELSE points_against END,
             imported_at = NOW()
         WHERE guild_id = $1 AND league_id = $2 AND LOWER(team_name) = LOWER($5)`,
        [guild.id, league.league_id, pf, pa, teamName]
      );

      updated += Number(result.rowCount || 0);
    }

    console.log('[REQUESTINFO HARVEST WRITE 7J-5D] ' + JSON.stringify({
      updated,
      candidateTeams: teamAnalytics.map(team => ({
        canonicalName: team.canonicalName,
        displayName: team.displayName,
        teamName: team.teamName,
        pf: team.teamTotalPointsScored,
        pa: team.teamTotalPointsAllowed,
      })).slice(0, 16),
    }));
  }

  return { seasonGameAnalytics, teamAnalytics };
}


async function inspectMaddenRequestInfoListExcavation(context, guild, league, hub) {
  const enabled = String(process.env.EA_REQUEST_INFO_EXCAVATION_ENABLED || 'false').toLowerCase() === 'true';
  if (!enabled) return null;

  const careerHubInfo = getAnyValue(hub, ['careerHubInfo'], {}) || {};
  const requestInfoList =
    getAnyValue(careerHubInfo, ['requestInfoList'], null) ||
    getAnyValue(hub, ['requestInfoList'], null) ||
    [];

  if (!Array.isArray(requestInfoList)) {
    console.log('[REQUESTINFOLIST EXCAVATION 7J-5BW] ' + JSON.stringify({
      leagueId: context.externalLeagueId,
      leagueName: league?.league_name,
      found: false,
      requestInfoType: typeof requestInfoList,
      careerHubInfoKeys: Object.keys(careerHubInfo || {}).slice(0, 80),
    }));
    return null;
  }

  const summaries = requestInfoList.map((entry, index) => summarizeMaddenRequestInfoEntry(entry, index));

  const candidates = summaries.filter(summary =>
    summary.knownArrays.some(array => Number(array.length || 0) > 0) ||
    summary.potentialArrays.some(array => Number(array.length || 0) > 0) ||
    summary.scorePairs.some(pair => pair.hasRealScore) ||
    Object.keys(summary.scoreLikeFields || {}).length > 0 ||
    summary.keyMatches.length > 0
  );

  const compact = {
    leagueId: context.externalLeagueId,
    leagueName: league?.league_name,
    totalRequests: requestInfoList.length,
    careerHubInfoKeys: Object.keys(careerHubInfo || {}).slice(0, 100),
    indexOverview: summaries.map(summary => ({
      index: summary.index,
      title: summary.entryMeta.title,
      type: summary.entryMeta.type,
      description: summary.entryMeta.description,
      requestId: summary.entryMeta.requestId,
      valueKeys: summary.valueKeys.slice(0, 30),
      knownArrayHits: summary.knownArrays.map(a => ({ path: a.path, key: a.key, length: a.length })).slice(0, 8),
      potentialArrayHits: summary.potentialArrays.map(a => ({ path: a.path, length: a.length, sampleKeys: a.sampleKeys })).slice(0, 5),
      scoreLikeFieldCount: summary.scoreLikeFieldCount,
      hasRealScorePair: summary.scorePairs.some(pair => pair.hasRealScore),
      keyMatchPaths: summary.keyMatches.map(k => ({ path: k.path, matchingKeys: k.matchingKeys })).slice(0, 6),
    })),
    candidateCount: candidates.length,
    candidates: candidates.slice(0, 12),
  };

  console.log('[REQUESTINFOLIST EXCAVATION 7J-5BW] ' + JSON.stringify(compact).slice(0, 30000));

  return compact;
}


