let maddenAutosyncTimer = null;
let maddenAutosyncRunning = false;

async function runDueMaddenAutosyncs(client) {
  if (maddenAutosyncRunning) return;
  maddenAutosyncRunning = true;
  try {
    const due = await pool.query(
      `SELECT mls.*, l.guild_id AS league_guild_id, l.league_name
       FROM madden_league_settings mls
       JOIN leagues l ON l.league_id = mls.league_id
       WHERE mls.autosync_enabled = TRUE
         AND (mls.next_sync_at IS NULL OR mls.next_sync_at <= NOW())
       ORDER BY mls.next_sync_at ASC NULLS FIRST
       LIMIT 10`
    );

    lastMaddenAutosyncTickAt = new Date();

    for (const row of due.rows) {
      const guildId = row.guild_id || row.league_guild_id;
      const guild = await client.guilds.fetch(guildId).catch(() => null);
      if (!guild) continue;
      const league = await getLeagueById(row.league_id);
      if (!league) continue;

      let run;
      try {
        run = await runMaddenExternalFetchSync(guild, league, { week: null });
      } catch (error) {
        run = { status: 'failed', source: row.sync_source || 'unknown', message: error.message || 'Autosync failed.', imported_teams: 0, imported_games: 0, imported_players: 0 };
      }
      await postMaddenSyncFeed(guild, league, run).catch(() => null);
      // Game thread creation now happens inside autoDetectAfterSync, gated on the
      // confirmed newWeekLabel — see handoff notes in the tracking doc.

      await autoDetectAfterSync(guild, league).catch(error => {
        console.error('[Madden Autosync] Auto detect failed:', error?.message || error);
      });

      const interval = Math.max(Number(row.autosync_interval_minutes || 60), 15);
      await pool.query(
        `UPDATE madden_league_settings
         SET next_sync_at = NOW() + ($2::int * INTERVAL '1 minute'), updated_at = NOW()
         WHERE league_id = $1`,
        [row.league_id, interval]
      );
    }
  } catch (error) {
    console.error('Madden autosync loop failed:', error);
  } finally {
    maddenAutosyncRunning = false;
  }
}

function startMaddenAutosyncLoop(client) {
  if (maddenAutosyncTimer) clearInterval(maddenAutosyncTimer);
  maddenAutosyncTimer = setInterval(() => {
    runDueMaddenAutosyncs(client).catch(error => console.error('Madden autosync tick failed:', error));
  }, 60 * 1000);
  setTimeout(() => runDueMaddenAutosyncs(client).catch(() => null), 10 * 1000);
}

// ---------------------------------------------------------------------------
// Trade negotiation thread cleanup — deletes negotiation threads that have
// had no real Discord activity for a few days. Checks actual message
// timestamps rather than the negotiation row's updated_at, since a thread
// can have live chat happening in it without ever touching that row.
// ---------------------------------------------------------------------------
const TRADE_THREAD_INACTIVITY_DAYS = 3;
let tradeThreadCleanupTimer = null;
let tradeThreadCleanupRunning = false;

async function cleanupInactiveTradeNegotiationThreads(client) {
  if (tradeThreadCleanupRunning) return;
  tradeThreadCleanupRunning = true;
  try {
    const result = await pool.query(
      `SELECT id, guild_id, thread_id, player_name FROM madden_trade_negotiations WHERE thread_id IS NOT NULL`
    ).catch(() => ({ rows: [] }));

    const cutoffMs = TRADE_THREAD_INACTIVITY_DAYS * 24 * 60 * 60 * 1000;
    let deletedCount = 0;

    for (const row of result.rows) {
      const guild = client.guilds.cache.get(row.guild_id);
      if (!guild) continue;

      const thread = await guild.channels.fetch(row.thread_id).catch(() => null);
      if (!thread || !thread.isThread?.()) {
        // Thread already gone (deleted manually, etc.) — clear the stale reference so we stop checking it.
        await pool.query(`UPDATE madden_trade_negotiations SET thread_id = NULL WHERE id = $1`, [row.id]).catch(() => null);
        continue;
      }

      const recentMessages = await thread.messages.fetch({ limit: 1 }).catch(() => null);
      const lastMessage = recentMessages?.first();
      const lastActivityMs = lastMessage?.createdTimestamp || thread.createdTimestamp || Date.now();

      if (Date.now() - lastActivityMs > cutoffMs) {
        await thread.delete(`GG Sports: inactive trade negotiation thread (${TRADE_THREAD_INACTIVITY_DAYS}+ days no activity)`).catch(() => null);
        await pool.query(`UPDATE madden_trade_negotiations SET thread_id = NULL WHERE id = $1`, [row.id]).catch(() => null);
        console.log(`[TRADE THREAD CLEANUP] Deleted inactive thread for ${row.player_name} (guild ${row.guild_id})`);
        deletedCount += 1;
      }
    }
    lastTradeThreadCleanupAt = new Date();
    lastTradeThreadCleanupDeleted = deletedCount;
  } catch (error) {
    console.error('Trade negotiation thread cleanup failed:', error);
  } finally {
    tradeThreadCleanupRunning = false;
  }
}

function startTradeThreadCleanupLoop(client) {
  if (tradeThreadCleanupTimer) clearInterval(tradeThreadCleanupTimer);
  tradeThreadCleanupTimer = setInterval(() => {
    cleanupInactiveTradeNegotiationThreads(client).catch(error => console.error('Trade thread cleanup tick failed:', error));
  }, 6 * 60 * 60 * 1000); // Every 6 hours — this is housekeeping, not time-sensitive.
  setTimeout(() => cleanupInactiveTradeNegotiationThreads(client).catch(() => null), 60 * 1000);
}

// 7J-48LOCK: Track H item 26 — anti-late-betting exploit. Sweeps for any
// sportsbook_games whose 5-minute bets_lock_at window has passed and
// finalizes the lock. Deliberately a persisted-timestamp + periodic-sweep
// pattern rather than a per-game in-memory setTimeout — a 5-minute
// in-memory timer could get silently dropped by a bot restart/redeploy
// mid-window, which is an unacceptable failure mode for something with
// real financial-integrity stakes (unlike, say, the voice-activity
// tracking earlier this session, where losing a partial session on
// restart is a low-stakes, acceptable tradeoff). This self-heals
// regardless of restarts, since it's driven off a real DB timestamp
// checked every minute.
let sportsbookBettingLockTimer = null;

async function sweepSportsbookBettingLocks(client) {
  const dueResult = await pool.query(
    `SELECT id, guild_id, league_id, game_label
     FROM sportsbook_games
     WHERE status = 'open' AND bets_locked = FALSE AND bets_lock_at IS NOT NULL AND bets_lock_at <= NOW()`
  ).catch(() => ({ rows: [] }));

  if (!dueResult.rows.length) return;

  await pool.query(
    `UPDATE sportsbook_games SET bets_locked = TRUE
     WHERE status = 'open' AND bets_locked = FALSE AND bets_lock_at IS NOT NULL AND bets_lock_at <= NOW()`
  ).catch(error => console.error('[7J-48LOCK] Failed to finalize betting locks:', error?.message || error));

  const byGuildLeague = new Map();
  for (const row of dueResult.rows) {
    const key = `${row.guild_id}:${row.league_id || ''}`;
    if (!byGuildLeague.has(key)) byGuildLeague.set(key, { guildId: row.guild_id, leagueId: row.league_id || null, rows: [] });
    byGuildLeague.get(key).rows.push(row);
  }

  for (const { guildId, leagueId, rows } of byGuildLeague.values()) {
    const guild = await client.guilds.fetch(guildId).catch(() => null);
    if (!guild) continue;
    const lines = rows.map(r => `🔒 ${r.game_label}`).join('\n');
    const embed = new EmbedBuilder()
      .setTitle('🔒 Betting Closed')
      .setColor(0xED4245)
      .setDescription(lines.slice(0, 3900))
      .setFooter({ text: 'GG Sports • Anti-Late-Betting Protection' })
      .setTimestamp();
    await postSportsbookFeed(guild, embed, leagueId).catch(() => null);
  }
}

function startSportsbookBettingLockLoop(client) {
  if (sportsbookBettingLockTimer) clearInterval(sportsbookBettingLockTimer);
  sportsbookBettingLockTimer = setInterval(() => {
    sweepSportsbookBettingLocks(client).catch(error => console.error('[7J-48LOCK] sweep tick failed:', error?.message || error));
  }, 60 * 1000); // Every minute — this IS time-sensitive, unlike the 6-hour housekeeping loop above.
  setTimeout(() => sweepSportsbookBettingLocks(client).catch(() => null), 15 * 1000);
}

// 7J-PLAYOFFTHREADCLEANUP: per Hxxdie — once the 15-minute dispute window
// for a completed round closes (the next round's unlocksAt passes), that
// completed round's threads should delete themselves automatically, the
// same way regular season's round-to-round cleanup already works on
// Advance. This is genuinely time-based (checking against a clock, not
// reacting to an event), so it needs its own sweep — same once-a-minute
// cadence as the sportsbook lock sweep above, for the same reason.
// Skips any round with an active dispute (never delete a thread staff might
// still need to review) and tracks per-series threadDeleted so a sweep tick
// never re-attempts a thread that's already gone.
//
// 7J-PLAYOFFUNLOCKREFRESH: also handles a separate, real bug — a series'
// Report Score button disabled state is baked into the message at
// send/edit time. Nothing was ever re-editing that message purely because
// the clock passed unlocksAt (only an actual game report or dispute
// triggered a re-render), so the button stayed visibly — and actually —
// unclickable well past its real unlock time, even though the server-side
// check would have allowed it. Tracks series.unlockRefreshed so this only
// ever re-renders the message once per series, not every tick forever.
async function sweepPlayoffRoundThreadCleanup(client) {
  const bracketsResult = await pool.query(`SELECT * FROM league_playoff_brackets WHERE status = 'in_progress'`).catch(() => ({ rows: [] }));
  for (const bracketState of bracketsResult.rows) {
    const bracket = Array.isArray(bracketState.bracket) ? bracketState.bracket : [];
    if (!bracket.length) continue;

    const league = await getLeagueById(bracketState.league_id).catch(() => null);
    if (!league) continue;
    const guild = await client.guilds.fetch(league.guild_id).catch(() => null);
    if (!guild) continue;

    let bracketMutated = false;

    // Unlock refresh — every round, not just ones with a "next round"
    // after them, since this just fixes stale button state.
    for (let ri = 0; ri < bracket.length; ri++) {
      const round = bracket[ri];
      if (!round?.length) continue;
      for (const series of round) {
        if (series.bye || series.winner || series.unlockRefreshed || !series.unlocksAt) continue;
        if (new Date(series.unlocksAt).getTime() > Date.now()) continue; // still actually locked
        await refreshPlayoffSeriesThreadMessage(guild, league, series, ri + 1).catch(() => null);
        series.unlockRefreshed = true;
        bracketMutated = true;
      }
    }

    if (bracket.length >= 2) {
      for (let ri = 0; ri < bracket.length - 1; ri++) {
        const round = bracket[ri];
        const nextRound = bracket[ri + 1];
        if (!round?.length || !nextRound?.length) continue;
        if (!round.every(s => s.winner)) continue; // round isn't actually complete
        if (round.some(s => s.disputed)) continue; // active dispute — leave the thread alone
        if (round.every(s => s.bye || s.threadDeleted)) continue; // already cleaned up

        const nextUnlocksAt = nextRound.find(s => s.unlocksAt)?.unlocksAt;
        if (!nextUnlocksAt || new Date(nextUnlocksAt).getTime() > Date.now()) continue; // window still open

        for (const series of round) {
          if (series.bye || series.threadDeleted) { series.threadDeleted = true; continue; }
          if (series.thread_id) {
            const thread = await guild.channels.fetch(series.thread_id).catch(() => null);
            if (thread?.isThread?.()) await thread.delete('GG Sports: playoff dispute window closed, round thread cleanup').catch(() => null);
          }
          series.threadDeleted = true;
          bracketMutated = true;
        }
      }
    }

    if (bracketMutated) {
      await pool.query(`UPDATE league_playoff_brackets SET bracket = $2, updated_at = NOW() WHERE league_id = $1`, [bracketState.league_id, JSON.stringify(bracket)]).catch(() => null);
    }
  }
}

let playoffThreadCleanupTimer = null;
function startPlayoffThreadCleanupLoop(client) {
  if (playoffThreadCleanupTimer) clearInterval(playoffThreadCleanupTimer);
  playoffThreadCleanupTimer = setInterval(() => {
    sweepPlayoffRoundThreadCleanup(client).catch(error => console.error('[Playoffs] Thread cleanup sweep tick failed:', error?.message || error));
  }, 60 * 1000);
  setTimeout(() => sweepPlayoffRoundThreadCleanup(client).catch(() => null), 20 * 1000);
}

