async function buildMaddenFranchiseEmbed(guild, league, teamRoleId = null, userId = null) {
  await syncMaddenFranchises(guild, league).catch(() => null);

  let franchise;
  if (teamRoleId) {
    const result = await pool.query(
      `SELECT * FROM madden_franchises WHERE guild_id = $1 AND league_id::text = $2::text AND team_role_id = $3 LIMIT 1`,
      [guild.id, league.league_id, teamRoleId]
    );
    franchise = result.rows[0];
  } else if (userId) {
    const result = await pool.query(
      `SELECT * FROM madden_franchises WHERE guild_id = $1 AND league_id::text = $2::text AND owner_user_id = $3 LIMIT 1`,
      [guild.id, league.league_id, userId]
    );
    franchise = result.rows[0];
  } else {
    const result = await pool.query(
      `SELECT * FROM madden_franchises WHERE guild_id = $1 AND league_id::text = $2::text ORDER BY updated_at DESC LIMIT 1`,
      [guild.id, league.league_id]
    );
    franchise = result.rows[0];
  }

  if (!franchise) {
    return new EmbedBuilder()
      .setTitle('Madden Franchise')
      .setColor(0xED4245)
      .setDescription('No franchise found. Add league team roles with /league teamrole, then run /madden setup.')
      .setTimestamp();
  }

  const teamName = franchise.team_name;
  const [teamStatsResult, detailedRanks, leaders, topPlayers, recentGamesResult, nextGame, powerRankResult] = await Promise.all([
    pool.query(
      `SELECT *
       FROM madden_imported_team_stats
       WHERE guild_id = $1::text
         AND league_id::text = $2::text
         AND (
           LOWER(team_name) = LOWER($3)
           OR LOWER(team_name) = LOWER($4)
         )
       LIMIT 1`,
      [guild.id, league.league_id, teamName, getMaddenTeamAbbrev(teamName)]
    ),
    getMaddenTeamDetailedRanks(guild.id, league.league_id, teamName).catch(() => null),
    getMaddenTeamLeaders(guild.id, league.league_id, teamName).catch(() => []),
    getMaddenTeamTopPlayers(guild.id, league.league_id, teamName, 5).catch(() => []),
    pool.query(
      `SELECT *
       FROM madden_imported_games
       WHERE guild_id = $1::text
         AND league_id::text = $2::text
         AND (
           LOWER(home_team) = LOWER($3)
           OR LOWER(away_team) = LOWER($3)
           OR LOWER(home_team) = LOWER($4)
           OR LOWER(away_team) = LOWER($4)
         )
       ORDER BY
         CASE WHEN LOWER(status) = 'completed' THEN 0 ELSE 1 END,
         COALESCE(NULLIF(regexp_replace(week_label, '[^0-9]', '', 'g'), ''), '0')::int DESC,
         imported_at DESC
       LIMIT 3`,
      [guild.id, league.league_id, String(teamName).toLowerCase(), String(getMaddenTeamAbbrev(teamName) || '').toLowerCase()]
    ),
    findMaddenGameCenterGame(guild.id, league.league_id, teamName, null, null).catch(() => null),
    pool.query(
      `SELECT *
       FROM madden_power_rankings
       WHERE league_id::text = $1::text
         AND LOWER(team_name) = LOWER($2)
       LIMIT 1`,
      [league.league_id, teamName]
    ).catch(() => ({ rows: [] })),
  ]);

  const teamStats = teamStatsResult.rows?.[0] || {};
  const record = formatMaddenStandingsRecord(teamStats);
  const pf = Number(teamStats.points_for || 0);
  const pa = Number(teamStats.points_against || 0);
  const diff = pf - pa;
  const powerRank = powerRankResult?.rows?.[0] || null;
  const powerRankText = powerRank ? `Power Rank: #${powerRank.rank} ${formatMaddenPowerMovement(powerRank)}` : 'Power Rank: Not calculated';

  const leadersText = leaders.length
    ? leaders.map(item => `**${item.label}:** ${item.text}`).join('\n')
    : 'No team leaders found yet.';

  const topPlayersText = topPlayers.length
    ? topPlayers.map((player, index) => `${index + 1}. ${maddenPlayerDisplayName(player)} — ${player.position || 'UNK'} • ${player.overall || 'N/A'} OVR • ${maddenPlayerDevEmojiOnly(player.dev_trait)}`).join('\n')
    : 'No imported roster players found.';

  const recentGames = recentGamesResult.rows || [];
  const recentText = recentGames.length
    ? recentGames.map(game => formatMaddenGameResultForTeam(game, teamName)).join('\n')
    : 'No imported games found.';

  const nextGameText = nextGame
    ? `**${nextGame.week_label || 'Week TBD'}** ${nextGame.away_team} @ ${nextGame.home_team} — ${formatMaddenGameStatus(nextGame)}`
    : 'No featured game found.';

  return new EmbedBuilder()
    .setTitle(`Madden Franchise Hub • ${teamName} (${getMaddenTeamAbbrev(teamName) || 'NFL'})`)
    .setColor(0xFEE75C)
    .setDescription(`**${league.league_name}**`)
    .addFields(
      { name: 'Coach', value: franchise.owner_user_id ? '<@' + franchise.owner_user_id + '>' : 'Unassigned', inline: true },
      { name: 'Team Role', value: franchise.team_role_id ? '<@&' + franchise.team_role_id + '>' : 'Unassigned', inline: true },
      { name: 'Record', value: `${record}\nPF ${pf} | PA ${pa} | DIFF ${diff >= 0 ? '+' : ''}${diff}`, inline: true },
      { name: 'Power Rank', value: powerRankText, inline: true },
      { name: 'Team Rankings', value: buildMaddenDetailedRankText(detailedRanks), inline: false },
      { name: 'Team Leaders', value: leadersText.slice(0, 1024), inline: false },
      { name: 'Top Players', value: topPlayersText.slice(0, 1024), inline: false },
      { name: 'Recent / Upcoming Games', value: recentText.slice(0, 1024), inline: false },
      { name: 'Featured Game', value: nextGameText.slice(0, 1024), inline: false },
      { name: 'Franchise Tools', value: '`/madden team` • `/madden game` • `/madden leaders` • `/madden standings`', inline: false }
    )
    .setFooter({ text: 'GG Sports • Madden Franchise Hub' })
    .setTimestamp();
}




// 7J-10BY-GT3 — Auto Detection System
//
// Fires after every sync. Uses a week-label dedup guard so nothing runs twice
// even if the commissioner syncs multiple times before advancing.
//
// What it does on each NEW week advance:
//   1.  Transaction scan (with anomaly threshold + commissioner review path)
//   2.  Retirement detection (baseline diff)
//   3.  Game results: scores, big performances, streak alerts, award race
//   4.  Sportsbook: auto-lines for user vs user games in new week
//   5.  Persistent embed refresh: standings, free agents, power rankings
//   6.  ESPN-style news via Claude API (falls back to templates)
//
//   // 7J-10AX Madden Compare Value + Trade Foundation
//


// ---------------------------------------------------------------------------
// DB migrations — add to initDatabase()
// ---------------------------------------------------------------------------
async function ensureMaddenAutoDetectColumns() {
  // Week-advance dedup guard + detection settings
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS last_auto_detect_week_label TEXT`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS ea_reported_current_week TEXT`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS ea_hub_is_preseason BOOLEAN NOT NULL DEFAULT FALSE`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS auto_detect_enabled BOOLEAN NOT NULL DEFAULT FALSE`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS auto_detect_threshold INTEGER NOT NULL DEFAULT 30`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS auto_detect_review_channel_id TEXT`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS espn_news_enabled BOOLEAN NOT NULL DEFAULT TRUE`);
  // Persistent embed message IDs
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS standings_channel_id TEXT`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS standings_message_id TEXT`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS standings_scope TEXT NOT NULL DEFAULT 'conference'`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS power_rankings_channel_id TEXT`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS power_rankings_message_id TEXT`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS free_agents_message_id TEXT`);
  // Sportsbook auto-lines
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS sportsbook_auto_lines_enabled BOOLEAN NOT NULL DEFAULT TRUE`);
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS madden_sportsbook_channel_id TEXT`);
  // 7J-ROOKIEAWARDSNAPSHOT: see the comment at its write site
  // (handleMaddenPlayoffBracketTransition) and read site
  // (getMaddenYearEndAwardWinners) for why this exists.
  await pool.query(`ALTER TABLE madden_league_settings ADD COLUMN IF NOT EXISTS rookie_award_snapshot JSONB`);
  // Link madden games to sportsbook games for auto-settlement
  await pool.query(`ALTER TABLE madden_imported_games ADD COLUMN IF NOT EXISTS sportsbook_game_id UUID REFERENCES sportsbook_games(id) ON DELETE SET NULL`);
  await pool.query(`ALTER TABLE madden_imported_games ADD COLUMN IF NOT EXISTS is_user_vs_user BOOLEAN`);
  await pool.query(`CREATE INDEX IF NOT EXISTS idx_madden_imported_games_sb ON madden_imported_games(guild_id, league_id, sportsbook_game_id)`);
}


// ---------------------------------------------------------------------------
// Week advance dedup guard
// Returns the new week label if this is a fresh advance, null if already seen.
// ---------------------------------------------------------------------------
async function getMaddenNewAdvanceWeek(guildId, leagueId) {
  const settingsResult = await pool.query(
    `SELECT last_auto_detect_week_label, ea_reported_current_week, current_season_stage FROM madden_league_settings WHERE league_id = $1 LIMIT 1`,
    [leagueId]
  ).catch(() => ({ rows: [] }));
  const lastLabel = settingsResult.rows[0]?.last_auto_detect_week_label || null;
  const eaReportedWeek = settingsResult.rows[0]?.ea_reported_current_week || null;
  const currentSeasonStage = settingsResult.rows[0]?.current_season_stage || null;

  // Season key computed once here and reused below (the "cap to next known
  // week" lookup and the preseason-completion check both need it) — see
  // 7J-10BY-SEASONKEYALLWEEKS further down for why this scoping matters.
  const seasonYearForAllWeeks = await pool.query(
    `SELECT madden_season_year FROM league_settings WHERE league_id = $1`,
    [leagueId]
  ).catch(() => ({ rows: [] }));
  const currentSeasonKeyForAllWeeks = await getMaddenCurrentSeasonKey({
    league_id: leagueId,
    madden_season_year: seasonYearForAllWeeks.rows[0]?.madden_season_year ?? null,
  }).catch(() => null);

  // 7J-PRESEASONTHREADSENABLE: per Hxxdie — the gate this comment used to
  // sit above (7J-10BY-GAMEGROUNDEDPRESEASON, kept below purely as
  // historical record of why a game-data-grounded signal was chosen over
  // EA's unreliable stage flags) suppressed ALL advance processing —
  // threads included — until Preseason Week 3 fully completed. That was
  // solving a real problem (the one genuinely tricky moment: detecting the
  // OFFSEASON -> preseason transition, since that crosses an actual
  // season boundary and EA's own stage flags can't be trusted for it) with
  // a much blunter tool than necessary: suppressing three entire weeks of
  // real coverage to get one transition right. That transition is now
  // handled directly and correctly by 7J-PRESEASONADVANCEBLIND below (the
  // looksLikeGenuineSeasonStart check, broadened this session to recognize
  // "Preseason Week N" while stuck in 'offseason'). Once that one moment is
  // handled, WITHIN preseason (Week 1 -> 2 -> 3 -> real Week 1) is ordinary
  // same-season forward progress — preseason (group 0) sorting before
  // regular season (group 1) in maddenWeekLabelSortKey is correct, not a
  // cross-season collision, so the normal genuinelyMovedForward comparison
  // just below already handles all of it with no special-casing needed.
  // Removed the gate rather than patching around it — the underlying
  // per-game data was already confirmed reliable (see the preserved
  // comment below), so nothing here was actually protecting against bad
  // data, only delaying real coverage that can now run on schedule.
  const MADDEN_PRESEASON_WEEKS_WITH_GAMES = 3; // kept for reference below; no longer gates anything


  // Known week sequence from the schedule — shared by both paths below. Used by
  // the EA-hub path specifically as a hard cap: never advance more than one step
  // per sync, regardless of how far ahead eaReportedWeek claims to be. This is a
  // deliberate circuit breaker, not just a preference — after three straight
  // rounds of this detection logic still being wrong in production, trusting any
  // single computed value for an unbounded jump is exactly the failure mode to
  // stop allowing. One step at a time is always safe: a genuinely multi-week-
  // behind league just takes multiple syncs to catch up, each one fully
  // processed, and a wrongly-computed value can only ever cause a one-week
  // false advance instead of a four-week one.
  const allGamesResult = await pool.query(
    `SELECT week_label, status, home_score, away_score FROM madden_imported_games
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND week_label IS NOT NULL AND TRIM(week_label) <> ''
       AND LOWER(TRIM(week_label)) NOT LIKE '%tbd%'
       AND ($3::text IS NULL OR season_key = $3::text)`,
    [guildId, String(leagueId), currentSeasonKeyForAllWeeks]
  ).catch(() => ({ rows: [] }));
  const rows = allGamesResult.rows || [];
  const allWeeks = Array.from(new Set(rows.map(r => r.week_label)));
  allWeeks.sort(compareMaddenWeekLabels);

  // Primary path: EA's own reported current week (persisted fresh every sync in
  // runMaddenEaDirectSync) is genuine ground truth — read directly from the
  // franchise hub's nextSeasonWeek/displayWeek/weekIndex fields, not inferred
  // from game completion at all.
  if (eaReportedWeek) {
    if (!lastLabel) {
      // First sync ever — anchor to whatever EA currently reports, don't process.
      await markMaddenAdvanceProcessed(guildId, leagueId, eaReportedWeek);
      console.log(`[AUTO DETECT] First run — anchored to EA-reported current week: ${eaReportedWeek}. Will detect NEXT real advance.`);
      return null;
    }
    // 7J-CORRUPTEDLABELFIX: per Hxxdie — confirmed live. This shortcut used
    // to trust lastLabel unconditionally the moment EA reports the same
    // thing twice in a row — but if a PRIOR sync (before 7J-POSTPLAYOFFWEEKFIX2
    // above existed) already wrote a raw, uncorrected value like "Week 1"
    // into last_auto_detect_week_label while the league was genuinely in
    // the playoffs, that corrupted value gets trusted forever — EA keeps
    // reporting "Week 1", lastLabel is already "Week 1", this shortcut
    // fires every single time, and the override logic below (which would
    // otherwise catch and correct exactly this) never even gets a chance
    // to run. Detects the one specific signal that can only mean the
    // stored label is corrupted: the league is still in the playoffs
    // stage, but the stored label itself doesn't classify as a playoff
    // week and isn't the known-safe "Pro Bowl" fallback either — that
    // combination is otherwise impossible under correct operation.
    //
    // 7J-CUTWEEKLABELCOLLISION: real bug, confirmed live via direct evidence
    // (Session 44 continued 18) — same corrupted-label shape as above, one
    // stage earlier, never extended to it. EA appears to have no distinct
    // signal for the roster-cut stage between Preseason Week 3 and real
    // Week 1 — it reports "Week 1" prematurely, before real Week 1 games
    // exist. Confirmed live: two consecutive sync summaries, one during
    // that stage and one after the user had genuinely advanced into real
    // Week 1, both showed "EA reports current week: Week 1" — identical
    // raw text. Once that label got stored as last_auto_detect_week_label
    // during the earlier (premature) sync, the real transition into Week 1
    // could never be detected — this shortcut saw the same "Week 1" twice
    // and returned null both times, silently swallowing the entire
    // regular-season kickoff (stat wipe, trade count reset, bracket delete,
    // power ranking reset, old-thread cleanup, new threads, the season
    // announcement — none of it ran). Same fix shape as the playoffs case:
    // if the league is still sitting in 'preseason' stage but the STORED
    // label is a genuine real-season "Week N" (not a "Preseason Week N"),
    // that combination is exactly as impossible as the playoffs one — it
    // can only mean the label was captured early, not that the season
    // genuinely already started while the stage never moved. Re-evaluates
    // instead of trusting it, same as the playoffs case does.
    if (eaReportedWeek === lastLabel) {
      const [lastLabelGroup] = maddenWeekLabelSortKey(lastLabel);
      const lastLabelLooksCorruptedForPlayoffs = currentSeasonStage === 'playoffs' && lastLabelGroup !== 2 && lastLabel !== 'Pro Bowl';
      const lastLabelLooksCorruptedForPreseason = currentSeasonStage === 'preseason' && /^week\s+\d+$/i.test(String(lastLabel || '').trim());
      const lastLabelLooksCorrupted = lastLabelLooksCorruptedForPlayoffs || lastLabelLooksCorruptedForPreseason;
      if (!lastLabelLooksCorrupted) return null; // EA still reports the same week — nothing has actually advanced.
      console.log(`[AUTO DETECT] Stored last-processed week "${lastLabel}" is inconsistent with the league's current stage ("${currentSeasonStage}") — treating as corrupted from a prior sync and re-evaluating instead of trusting it.`);
      // 7J-CUTWEEKLABELCOLLISION: unlike the playoffs case (which needs a
      // SAFE SYNTHETIC label below, since raw "Week 1" text right after
      // playoffs would otherwise collide with old real Week 1 games from
      // months ago), there's no equivalent collision risk here — eaReportedWeek
      // genuinely IS the correct target label once we know the stage/label
      // combination is impossible. genuinelyMovedForward below will
      // evaluate to false regardless (eaReportedWeek and lastLabel are the
      // identical string), so this returns eaReportedWeek directly rather
      // than falling through to a check that could never fire for an
      // exact-string-match case — same reasoning, correct outcome, no
      // synthetic label needed.
      if (lastLabelLooksCorruptedForPreseason) {
        console.log(`[AUTO DETECT] Treating "${eaReportedWeek}" as genuine forward progress out of a stuck 'preseason' stage despite matching the stored label exactly.`);
        return eaReportedWeek;
      }
    }

    const [lastG, lastN] = maddenWeekLabelSortKey(lastLabel);
    const [curG, curN] = maddenWeekLabelSortKey(eaReportedWeek);
    const genuinelyMovedForward = curG > lastG || (curG === lastG && curN > lastN);
    // 7J-POSTPLAYOFFWEEKFIX: per Hxxdie — real bug, confirmed live twice.
    // A franchise can never genuinely regress out of the playoffs back to
    // an earlier regular-season week — but EA reports the week right
    // after Conference Championship as literally "Week 1" (not "Pro
    // Bowl"), which classifies as early regular season and sorts BEFORE
    // "Conf. Playoff." checking current_season_stage (still 'playoffs'
    // until Super Bowl is actually detected) instead of re-classifying
    // lastLabel keeps this override working correctly even across
    // whatever confusingly-labeled week EA reports NEXT, not just this
    // one specific case.
    //
    // 7J-POSTPLAYOFFWEEKFIX2: per Hxxdie — the first version of this fix
    // stopped at "treat this as forward progress" and let the raw
    // "Week 1" label flow straight through to thread/game creation —
    // which blindly matched it against real Week 1 games from months ago
    // (this season's actual Week 1) and recreated an old thread live.
    // Now returns a safe synthetic label instead whenever the override is
    // what made this count as forward progress, so nothing downstream can
    // ever mistake old historical data for new content again — matches
    // the label the user's own real Madden confirmed this stage is
    // ("Pro Bowl week"). autoCreateGameThreadsAfterSync/game-import will
    // correctly find zero existing rows for this label and create
    // nothing, which is exactly right — Pro Bowl has no real matchups to
    // announce.
    if (!genuinelyMovedForward && currentSeasonStage === 'playoffs') {
      const safeLabel = 'Pro Bowl';
      console.log(`[AUTO DETECT] EA reported "${eaReportedWeek}" right after a playoff week ("${lastLabel}") while still in playoffs — treating as "${safeLabel}" instead of trusting the raw (potentially colliding) report.`);
      return safeLabel;
    }
    // 7J-10BY-SKIPPRESEASON: this used to ground against real unthreaded
    // "Preseason Week N" rows in the DB to avoid a raw-label collision with
    // stale prior-season data. That grounding is now actively wrong: with
    // preseason permanently out of scope (see the ea_hub_is_preseason gate
    // above), preseason game rows are NEVER threaded any more, so an
    // unthreaded "Preseason Week N" row would ALWAYS exist by the time the
    // league reaches real Week 1 — which would keep routing the genuine
    // season-start detection back into a preseason label forever, exactly
    // undoing the point of this change. Every league is now treated like
    // the already-proven "no-preseason league reaching a real Week 1" case:
    // trust EA's raw report directly. The season_key scoping added above
    // (7J-10BY-SEASONKEYALLWEEKS) already covers the original stale-data
    // collision concern for the labels that still matter.
    //
    // 7J-PRESEASONADVANCEBLIND: real bug, confirmed live — this only ever
    // matched bare "Week N", never "Preseason Week N", so a league that
    // DOES run a preseason (the normal case) could never have its
    // offseason → preseason transition recognized as forward progress at
    // all. genuinelyMovedForward structurally can't catch it either
    // (Preseason Week 1 is group 0, always sorting "before" whatever
    // group-1/2 label the league was last stuck on at the end of last
    // season, regardless of real time having moved forward — the same
    // cross-season group-number shape found several times elsewhere this
    // session). With getMaddenNewAdvanceWeek returning null, the entire
    // per-week catch-up loop that calls it never even starts processing
    // that week — not just game threads, but sportsbook lines, prop
    // generation, and news too, all silently skipped. This one broadened
    // regex is the actual root cause fix; the earlier
    // 7J-THREADANCHORSEASONSCOPE fix to thread creation was real and
    // still needed, but could never have taken effect on its own, since
    // the function it lives in was never being reached in the first place.
    const looksLikeGenuineSeasonStart = currentSeasonStage === 'offseason' &&
      /^(preseason\s+)?week \d+$/i.test(String(eaReportedWeek || '').trim());
    if (!genuinelyMovedForward && looksLikeGenuineSeasonStart) {
      console.log(`[AUTO DETECT] EA reported "${eaReportedWeek}" while league was stuck in 'offseason' stage — recognizing as the start of the (pre)season despite not sorting after the stale last-processed label ("${lastLabel}").`);
      return eaReportedWeek;
    }
    if (!genuinelyMovedForward) return null;

    // Find the single next known week after lastLabel in the schedule sequence,
    // and cap to that — never jump straight to eaReportedWeek itself.
    const lastIdx = allWeeks.indexOf(lastLabel);
    const nextWeek = lastIdx >= 0 && lastIdx + 1 < allWeeks.length ? allWeeks[lastIdx + 1] : eaReportedWeek;
    if (nextWeek !== eaReportedWeek) {
      console.log(`[AUTO DETECT] ⚠️ EA reported "${eaReportedWeek}" but last processed was "${lastLabel}" — that's more than one step. Capping advance to the next week in sequence ("${nextWeek}") instead of jumping directly, and will re-check EA's report again on the next sync.`);
    }
    return nextWeek;
  }

  // Fallback path — only reached for leagues that haven't synced since this fix
  // shipped (no ea_reported_current_week persisted yet) or non-EA-Direct sync
  // sources where that hub data isn't available at all. Same hardened
  // game-completion heuristic as before: a week only counts as fully played once
  // every game in it has a real score attached, not just a status label (which
  // the importer can set from an unreliable marker field alone).
  if (!rows.length) return null;

  const MADDEN_COMPLETED_STATUSES = new Set(['completed', 'final', 'complete', 'completed_with_real_score', 'away_win', 'home_win', 'tie']);
  const isGameGenuinelyComplete = (row) => {
    const statusMatch = MADDEN_COMPLETED_STATUSES.has(String(row.status || '').toLowerCase());
    const hasRealScore = Number(row.home_score || 0) > 0 || Number(row.away_score || 0) > 0;
    return statusMatch && hasRealScore;
  };
  const incompleteWeeks = new Set(
    rows.filter(r => !isGameGenuinelyComplete(r)).map(r => r.week_label)
  );

  if (!lastLabel) {
    const currentWeek = allWeeks.find(w => incompleteWeeks.has(w)) || allWeeks[allWeeks.length - 1];
    await markMaddenAdvanceProcessed(guildId, leagueId, currentWeek);
    console.log(`[AUTO DETECT] First run (fallback path, no EA hub data) — anchored to current week: ${currentWeek}. Will detect NEXT real advance.`);
    return null;
  }

  const [lastG, lastN] = maddenWeekLabelSortKey(lastLabel);
  const weeksAfterLast = allWeeks.filter(w => {
    const [g, n] = maddenWeekLabelSortKey(w);
    return g > lastG || (g === lastG && n > lastN);
  });

  for (const candidate of weeksAfterLast) {
    const idx = allWeeks.indexOf(candidate);
    const precedingWeek = idx > 0 ? allWeeks[idx - 1] : null;
    if (precedingWeek && incompleteWeeks.has(precedingWeek)) {
      // The week right before this candidate hasn't actually finished in the
      // real league yet — the candidate isn't a legitimate advance, it's just
      // sitting there pre-loaded in the schedule. Stop here rather than skip to
      // it or to anything further out.
      return null;
    }
    return candidate;
  }

  return null;
}

async function markMaddenAdvanceProcessed(guildId, leagueId, weekLabel) {
  await pool.query(
    `UPDATE madden_league_settings SET last_auto_detect_week_label = $2, updated_at = NOW()
     WHERE league_id = $1`,
    [leagueId, weekLabel]
  ).catch(() => null);
}


// ---------------------------------------------------------------------------
// Persistent embed updater
// Edits the stored message in place, or posts a new one and saves the new ID.
// ---------------------------------------------------------------------------
async function updatePersistentMaddenEmbed(guild, league, channelId, messageIdKey, buildEmbedFn, buildComponentsFn = null) {
  if (!channelId) return null; // Not configured, skip

  const channel = await guild.channels.fetch(channelId).catch(() => null);
  if (!channel?.isTextBased?.()) return null;

  const settings = await ensureMaddenLeagueSettings(league);
  const embed = await buildEmbedFn(settings).catch(error => {
    console.error(`[7J-62HUBDIAG] Persistent embed build failed (messageIdKey=${messageIdKey}, league=${league?.league_id}):`, error?.stack || error?.message || error);
    return null;
  });
  if (!embed) return null;
  const components = buildComponentsFn ? await buildComponentsFn(settings).catch(() => undefined) : undefined;
  const payload = components ? { embeds: [embed], components } : { embeds: [embed] };

  const existingMessageId = settings[messageIdKey];
  if (existingMessageId) {
    const existing = await channel.messages.fetch(existingMessageId).catch(() => null);
    if (existing) {
      await existing.edit(payload).catch(() => null);
      return existing;
    }
  }

  // Message gone or not yet set — post new one and store the ID
  const posted = await channel.send(payload).catch(() => null);
  if (posted) {
    await pool.query(
      `UPDATE madden_league_settings SET ${messageIdKey} = $2, updated_at = NOW() WHERE league_id = $1`,
      [league.league_id, posted.id]
    ).catch(() => null);
  }
  return posted;
}

// 7J-60FRANCHISEHUB: reuses the exact same 8 embed builder functions
// /madden franchise already calls — this board is purely a navigable
// persistent home for them, not a parallel reimplementation. Diagnostic-
// only views (results_diag, endpoint_discovery, etc.) are deliberately
// excluded — those are internal sync-debugging tools, not member-facing.
const MADDEN_FRANCHISE_HUB_VIEWS = {
  hub: { label: 'Franchise Hub', emoji: '🏟️', build: (guild, league, teamRoleId) => buildMaddenFranchiseEmbed(guild, league, teamRoleId) },
  news: { label: 'News Feed', emoji: '📰', build: (guild, league) => buildMaddenNewsFeedEmbed(guild.id, league) },
  records: { label: 'League Records', emoji: '🏆', build: (guild, league) => buildMaddenLeagueRecordsEmbed(guild.id, league) },
  hof: { label: 'Hall of Fame', emoji: '⭐', build: (guild, league) => buildMaddenHallOfFameEmbed(guild.id, league) },
  championships: { label: 'Championship History', emoji: '🏅', build: (guild, league) => buildMaddenChampionshipHistoryEmbed(guild.id, league) },
  dynasty: { label: 'Dynasty Tracker', emoji: '👑', build: (guild, league) => buildMaddenDynastyTrackerEmbed(guild.id, league) },
  award_history: { label: 'Award History', emoji: '🎖️', build: (guild, league) => buildMaddenAwardHistoryEmbed(guild.id, league) },
  season_close: { label: 'Season Close Preview', emoji: '📋', build: (guild, league) => buildMaddenSeasonClosePreviewEmbed(guild.id, league) },
};

async function buildMaddenFranchiseHubBoardEmbed(guild, league, view = 'hub', teamRoleId = null) {
  const viewConfig = MADDEN_FRANCHISE_HUB_VIEWS[view] || MADDEN_FRANCHISE_HUB_VIEWS.hub;
  return viewConfig.build(guild, league, teamRoleId);
}

function buildMaddenFranchiseHubBoardComponents(leagueId, currentView = 'hub', teamOptions = []) {
  const menu = new StringSelectMenuBuilder()
    .setCustomId('madfranchisehub:view:' + leagueId)
    .setPlaceholder('View: ' + (MADDEN_FRANCHISE_HUB_VIEWS[currentView]?.label || 'Franchise Hub'))
    .addOptions(Object.entries(MADDEN_FRANCHISE_HUB_VIEWS).map(([value, cfg]) => ({
      label: cfg.label,
      value,
      emoji: cfg.emoji,
      default: value === currentView,
    })));
  const rows = [new ActionRowBuilder().addComponents(menu)];

  // 7J-68TEAMPAGE: only shown for the Hub view — the other 7 views are
  // league-wide, a per-team filter doesn't apply to them. Discord hard-caps
  // a single select menu at 25 options — a 32-team league (all of the NFL)
  // doesn't fit in one, so this splits into two menus, same 1/2, 2/2
  // pattern already used for the setup dashboard's own long option list,
  // rather than silently truncating to the first 25 teams.
  if (currentView === 'hub' && teamOptions.length) {
    const half = Math.ceil(teamOptions.length / 2);
    const groupA = teamOptions.slice(0, half);
    const groupB = teamOptions.slice(half);

    const teamMenuA = new StringSelectMenuBuilder()
      .setCustomId('madfranchisehub:team:' + leagueId)
      .setPlaceholder(groupB.length ? 'Choose a team (1/2)' : 'Choose a team to view')
      .addOptions(groupA);
    rows.push(new ActionRowBuilder().addComponents(teamMenuA));

    if (groupB.length) {
      const teamMenuB = new StringSelectMenuBuilder()
        .setCustomId('madfranchisehub:team2:' + leagueId)
        .setPlaceholder('Choose a team (2/2)')
        .addOptions(groupB);
      rows.push(new ActionRowBuilder().addComponents(teamMenuB));
    }
  }

  return rows;
}

// 7J-63HUBTEAM: pulled out separately so both the board's initial
// post/refresh and the team-select handler can build the same option list
// without duplicating the query. Capped at 50 (Discord's max across the two
// 25-option menus above), not 25 — a real NFL-sized league (32 teams) needs
// more than one menu's worth.
async function getMaddenFranchiseHubTeamOptions(guildId, leagueId) {
  const result = await pool.query(
    `SELECT team_name, team_role_id FROM madden_franchises WHERE guild_id = $1 AND league_id::text = $2::text AND team_role_id IS NOT NULL ORDER BY team_name ASC LIMIT 50`,
    [guildId, String(leagueId)]
  ).catch(() => ({ rows: [] }));
  return result.rows.map(row => ({ label: maddenTeamDisplayName(row.team_name).slice(0, 100), value: row.team_role_id }));
}

function buildMaddenStandingsScopeComponents(leagueId, currentScope = 'conference') {
  const mk = (label, value) => new ButtonBuilder()
    .setCustomId(`madstand:scope:${leagueId}:${value}`)
    .setLabel(label)
    .setStyle(currentScope === value ? ButtonStyle.Primary : ButtonStyle.Secondary);
  return [new ActionRowBuilder().addComponents(mk('League', 'league'), mk('Conference', 'conference'), mk('Division', 'division'))];
}

async function refreshPersistentMaddenEmbeds(guild, league) {
  const standingsRows = await pool.query(
    `SELECT * FROM madden_imported_team_stats
     WHERE guild_id = $1 AND league_id::text = $2::text
     ORDER BY wins DESC, losses ASC, points_for DESC`,
    [guild.id, String(league.league_id)]
  ).then(r => r.rows).catch(() => []);

  await Promise.allSettled([
    updatePersistentMaddenEmbed(guild, league, league.madden_standings_channel_id, 'standings_message_id',
      (settings) => buildMaddenImportedStandingsEmbed(league, standingsRows, (settings && settings.standings_scope) || 'conference'),
      (settings) => buildMaddenStandingsScopeComponents(league.league_id, (settings && settings.standings_scope) || 'conference')),
    updatePersistentMaddenEmbed(guild, league, league.madden_power_rankings_channel_id, 'power_rankings_message_id',
      async () => {
        // 7J-52POWERPANEL: was `SELECT * FROM madden_power_rankings` directly
        // — but that table only ever stored rank/previous_rank/power_score
        // (confirmed via schema), never wins/losses/points_for/points_against.
        // Every row here always had those fields undefined, so the panel
        // embed always rendered 0-0 records regardless of the real
        // standings — not a staleness bug, it never had the data at all.
        // recalculateMaddenPowerRankings (same function the /madden
        // powerrankings slash command already uses correctly) computes
        // fresh from live madden_imported_team_stats every call, including
        // the actual record.
        const rows = await recalculateMaddenPowerRankings(guild.id, league.league_id).catch(() => []);
        return buildMaddenPowerRankingsEmbed(league, rows);
      }),
    // 7J-60FRANCHISEHUB: re-renders whatever view was last picked
    // (settings.franchise_hub_current_view) so an active board doesn't
    // silently reset to the default Hub view on every sync.
    updatePersistentMaddenEmbed(guild, league, league.madden_franchise_hub_channel_id, 'franchise_hub_message_id',
      async (settings) => {
        const currentView = (settings && settings.franchise_hub_current_view) || 'hub';
        const currentTeamRoleId = (settings && settings.franchise_hub_current_team_role_id) || null;
        return buildMaddenFranchiseHubBoardEmbed(guild, league, currentView, currentTeamRoleId);
      },
      async (settings) => {
        const currentView = (settings && settings.franchise_hub_current_view) || 'hub';
        const teamOptions = currentView === 'hub' ? await getMaddenFranchiseHubTeamOptions(guild.id, league.league_id) : [];
        return buildMaddenFranchiseHubBoardComponents(league.league_id, currentView, teamOptions);
      }),
    // Free agents board is intentionally NOT refreshed here. It has its own
    // separate, correct auto-refresh path (refreshMaddenFreeAgentsPanelForLeague,
    // called right after sync, backed by the madden_free_agent_panels table).
    // This function used to also call updatePersistentMaddenEmbed for free
    // agents using a madden_league_settings.madden_free_agents_channel_id
    // column that was never actually populated (the real column lives on
    // league_settings) — so it silently no-op'd. Removed rather than "fixed"
    // to avoid running two competing refresh systems against the same board.
    refreshMaddenTradeBlockBoardForLeague(guild, league),
    refreshMaddenLeagueLeadersPanelForLeague(guild, league),
    refreshMaddenAwardRacePanelForLeague(guild, league),
  ]);
}


// ---------------------------------------------------------------------------
// Transaction auto-detect with anomaly threshold guard
// ---------------------------------------------------------------------------
async function autoDetectMaddenTransactions(guild, league) {
  const settings = await ensureMaddenLeagueSettings(league);
  if (settings.auto_detect_enabled !== true) return [];

  // 7J-25WEEKLY: previously held any batch over auto_detect_threshold (default
  // 30) for manual commissioner review via `/maddentransactions scan
  // confirm:false` then `confirm:true` — existed specifically to protect the
  // news channel from a bad sync flooding it with individual posts. That risk
  // is gone now that transactions batch by team into the dedicated Weekly
  // Updates channel instead of posting individually to news, so the guard
  // (and the manual-review step it required commissioners to do) is removed
  // entirely per Hxxdie's request — "one more unnecessary manual thing."
  const rows = await scanMaddenOffseasonTransactions(guild, league, true).catch(err => {
    console.error('[AUTO DETECT TRANSACTIONS] Scan failed:', err?.message);
    return null;
  });
  const count = Array.isArray(rows) ? rows.length : 0;
  if (count === 0) return [];

  // 7J-26STORY: major roster movement — the same transaction data already
  // gets batched into Weekly Updates as routine churn, but a genuinely big
  // move (high OVR, a real signing/release/trade rather than a draft pick or
  // minor re-sign) deserves the same dramatic Claude-written treatment as
  // game results and streaks, not just a line in a per-team digest. Fed into
  // the same events array generateMaddenESPNNews already reads from.
  const MAJOR_MOVEMENT_TYPES = new Set(['signed', 'free_agency_signing', 'released', 'team_change']);
  const majorEvents = rows
    .filter(row => MAJOR_MOVEMENT_TYPES.has(String(row.event_type)) && Number(row.overall) >= 85)
    .map(row => ({
      type: 'major_movement',
      playerName: row.player_name,
      eventType: row.event_type,
      team: row.new_team_name || row.team_name || null,
      oldTeam: row.old_team_name || null,
      overall: row.overall,
      position: row.position,
      teamEmoji: getMaddenTeamEmoji(row.new_team_name || row.team_name || ''),
    }));

  return [{ type: 'transactions', count }, ...majorEvents];
}


// ---------------------------------------------------------------------------
// Retirement auto-detect (baseline diff)
// ---------------------------------------------------------------------------
async function autoDetectMaddenRetirements(guild, league) {
  const rows = await scanMaddenRetirements(guild, league, true).catch(() => null);
  if (!Array.isArray(rows) || !rows.length) return [];
  return rows.map(p => ({ type: 'retirement', player: p }));
}


// ---------------------------------------------------------------------------
// Madden-specific sportsbook odds generator
// Uses Madden tables instead of league game role IDs.
// ---------------------------------------------------------------------------
async function getMaddenTeamStandingsForOdds(guildId, leagueId, teamName) {
  const result = await pool.query(
    `SELECT wins, losses, ties, points_for, points_against, scored_games
     FROM madden_imported_team_stats
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND LOWER(team_name) = LOWER($3)
     LIMIT 1`,
    [guildId, String(leagueId), teamName]
  ).catch(() => ({ rows: [] }));
  return result.rows[0] || null;
}

async function getMaddenTeamAvgOvr(guildId, leagueId, teamName) {
  const result = await pool.query(
    `SELECT AVG(overall) AS avg_ovr
     FROM madden_players
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND LOWER(team_name) = LOWER($3)
       AND overall IS NOT NULL AND overall > 0`,
    [guildId, String(leagueId), teamName]
  ).catch(() => ({ rows: [] }));
  return Number(result.rows[0]?.avg_ovr || 0) || null;
}

async function getMaddenH2HHistory(guildId, leagueId, homeTeamName, awayTeamName) {
  const result = await pool.query(
    `SELECT
       SUM(CASE WHEN LOWER(home_team) = LOWER($3) AND home_score > away_score THEN 1 ELSE 0 END) AS home_wins,
       SUM(CASE WHEN LOWER(away_team) = LOWER($4) AND away_score > home_score THEN 1 ELSE 0 END) AS away_wins
     FROM madden_imported_games
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND LOWER(status) IN ('final', 'completed', 'completed_with_real_score')
       AND (
         (LOWER(home_team) = LOWER($3) AND LOWER(away_team) = LOWER($4))
         OR (LOWER(home_team) = LOWER($4) AND LOWER(away_team) = LOWER($3))
       )`,
    [guildId, String(leagueId), homeTeamName, awayTeamName]
  ).catch(() => ({ rows: [] }));
  return {
    homeWins: Number(result.rows[0]?.home_wins || 0),
    awayWins: Number(result.rows[0]?.away_wins || 0),
  };
}

async function getMaddenTeamPowerRank(leagueId, teamName) {
  const result = await pool.query(
    `SELECT rank, power_score FROM madden_power_rankings
     WHERE league_id::text = $1::text AND LOWER(team_name) = LOWER($2)
     LIMIT 1`,
    [String(leagueId), teamName]
  ).catch(() => ({ rows: [] }));
  return result.rows[0] || null;
}

async function generateMaddenMatchupOdds(guildId, league, homeTeamName, awayTeamName) {
  const [homeStandings, awayStandings, homeOvr, awayOvr, homePower, awayPower, h2h] =
    await Promise.all([
      getMaddenTeamStandingsForOdds(guildId, league.league_id, homeTeamName),
      getMaddenTeamStandingsForOdds(guildId, league.league_id, awayTeamName),
      getMaddenTeamAvgOvr(guildId, league.league_id, homeTeamName),
      getMaddenTeamAvgOvr(guildId, league.league_id, awayTeamName),
      getMaddenTeamPowerRank(league.league_id, homeTeamName),
      getMaddenTeamPowerRank(league.league_id, awayTeamName),
      getMaddenH2HHistory(guildId, league.league_id, homeTeamName, awayTeamName),
    ]);

  const winPct = (row) => row
    ? row.wins / Math.max(row.wins + row.losses + row.ties, 1)
    : 0.5;
  const homeWinPct = winPct(homeStandings);
  const awayWinPct = winPct(awayStandings);

  const pointDiff = (row) => row ? (row.points_for - row.points_against) : 0;

  let homeScore = 50;

  // Win % differential (weight 35)
  homeScore += (homeWinPct - awayWinPct) * 35;

  // Point differential per game (weight 0.06)
  // 7J-47PPG: was Math.max(wins+losses+ties, 1) — the same games-played bug
  // as the matchup preview PPG/PAPG fields, except here it's silently
  // skewing the actual sportsbook spread/odds a member bets real currency
  // against, not just a display number. Uses maddenTeamGamesPlayed's
  // scored_games (with its own wins+losses+ties fallback for teams that
  // haven't synced since this fix shipped).
  const homeGames = maddenTeamGamesPlayed(homeStandings);
  const awayGames = maddenTeamGamesPlayed(awayStandings);
  homeScore += (pointDiff(homeStandings) / homeGames - pointDiff(awayStandings) / awayGames) * 0.6;

  // Power rank (weight 1.5 — lower rank = better, so invert)
  if (homePower?.rank && awayPower?.rank) {
    homeScore += (awayPower.rank - homePower.rank) * 1.5;
  }

  // Roster OVR differential (weight 0.5)
  if (homeOvr && awayOvr) {
    homeScore += (homeOvr - awayOvr) * 0.5;
  }

  // Head-to-head Madden history (weight 2.5 per game advantage)
  homeScore += (h2h.homeWins - h2h.awayWins) * 2.5;

  // Home field advantage
  homeScore += 3;

  const homeProbability = Math.max(0.2, Math.min(0.8, homeScore / 100));
  const awayProbability = 1 - homeProbability;

  return {
    homeOdds: probabilityToAmericanOdds(homeProbability),
    awayOdds: probabilityToAmericanOdds(awayProbability),
    homeProbability: Math.round(homeProbability * 100),
    awayProbability: Math.round(awayProbability * 100),
  };
}


// ---------------------------------------------------------------------------
// Stat-prop auto-generation for Madden user vs user games.
// Real sportsbooks set player-prop lines off a blend of season-long production and
// recent form, then price both sides close to even (the skill is in where the
// number sits, not lopsided odds) — this mirrors that rather than inventing a
// black-box "confidence score." Deliberately conservative: skips a player/stat
// entirely rather than project off less than 2 games of data, since a bad
// projection here creates a real line people bet real currency on.
// ---------------------------------------------------------------------------
const MADDEN_PROP_POSITION_STATS = [
  { positions: ['QB'], statKey: 'passing_yards', roundTo: 5 },
  { positions: ['HB', 'RB'], statKey: 'rushing_yards', roundTo: 5 },
  { positions: ['WR'], statKey: 'receiving_yards', roundTo: 5 },
];

async function getMaddenPlayerStatHistory(guildId, leagueId, playerRef, statType, statField, beforeWeekIndex) {
  const result = await pool.query(
    `SELECT week_index, raw_payload
     FROM madden_player_weekly_stats
     WHERE guild_id = $1 AND league_id::text = $2::text AND stat_type = $3
       AND (roster_id = $4 OR presentation_id = $4)
       AND week_index < $5
     ORDER BY week_index DESC
     LIMIT 10`,
    [guildId, String(leagueId), statType, playerRef, beforeWeekIndex]
  ).catch(() => ({ rows: [] }));

  return result.rows
    .map(row => Number(row.raw_payload?.[statField]))
    .filter(value => Number.isFinite(value));
}

function projectMaddenStatLine(history, roundTo) {
  if (history.length < 2) return null; // Not enough games to project responsibly.
  const seasonAvg = history.reduce((sum, v) => sum + v, 0) / history.length;
  const recent = history.slice(0, 3);
  const recentAvg = recent.reduce((sum, v) => sum + v, 0) / recent.length;
  const projected = history.length >= 3 ? (seasonAvg * 0.4 + recentAvg * 0.6) : seasonAvg;

  // Round to the nearest step, then nudge to a half-step so the line can't land
  // exactly on a plausible final stat (avoids most pushes without needing a
  // separate push rule at settlement).
  const stepped = Math.round(projected / roundTo) * roundTo;
  return stepped + roundTo / 2;
}

// Finds the single best candidate per (team, stat) — most recent-game volume at
// the relevant position — rather than every rostered player at that position, to
// keep the number of props per game reasonable (3 per team, 6 per game).
async function findMaddenPropCandidate(guildId, leagueId, teamName, positions, statType, statField, beforeWeekIndex) {
  const result = await pool.query(
    `SELECT roster_id, presentation_id, full_name, position,
            SUM(COALESCE((raw_payload->>$6)::numeric, 0)) AS recent_total
     FROM madden_player_weekly_stats
     WHERE guild_id = $1 AND league_id::text = $2::text AND stat_type = $3
       AND LOWER(team_name) = LOWER($4) AND position = ANY($5) AND week_index < $7
     GROUP BY roster_id, presentation_id, full_name, position
     ORDER BY recent_total DESC
     LIMIT 1`,
    [guildId, String(leagueId), statType, teamName, positions, statField, beforeWeekIndex]
  ).catch(() => ({ rows: [] }));
  return result.rows[0] || null;
}

async function generateMaddenPlayerPropLines(guild, league, weekLabel) {
  const settings = await ensureMaddenLeagueSettings(league);
  if (!settings.sportsbook_auto_lines_enabled) {
    console.log('[PLAYER PROP GEN 7J-13PROP] sportsbook_auto_lines_enabled is false — skipping entirely.');
    return { created: 0 };
  }

  // week_label (games schedule) and week_index (player weekly stats) are two
  // separate EA sync streams with no guaranteed shared numbering — rather than
  // parse the label into a guessed index (risky: a wrong index would silently
  // orphan these props from ever matching real stats at settlement time), derive
  // the upcoming week's index directly from the data: one past the highest
  // week_index already synced for this league. Stats sync in lockstep with
  // advancing weeks, so this is a real data-driven inference, not a guess.
  const maxWeekResult = await pool.query(
    `SELECT COALESCE(MAX(week_index), 0) AS max_week FROM madden_player_weekly_stats WHERE guild_id = $1 AND league_id::text = $2::text`,
    [guild.id, String(league.league_id)]
  ).catch(() => ({ rows: [{ max_week: 0 }] }));
  const weekIndex = Number(maxWeekResult.rows[0]?.max_week || 0) + 1;
  console.log('[PLAYER PROP GEN 7J-13PROP] weekLabel: ' + weekLabel + ', derived weekIndex: ' + weekIndex);
  if (weekIndex <= 1) {
    console.log('[PLAYER PROP GEN 7J-13PROP] weekIndex <= 1 — no prior-week stats synced yet, skipping entirely.');
    return { created: 0 }; // No prior-week stats synced yet — nothing to project off of.
  }

  const games = await pool.query(
    `SELECT * FROM madden_imported_games
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND LOWER(week_label) = LOWER($3) AND is_user_vs_user = TRUE`,
    [guild.id, String(league.league_id), weekLabel]
  ).catch(() => ({ rows: [] }));
  console.log('[PLAYER PROP GEN 7J-13PROP] user-vs-user games found for ' + weekLabel + ': ' + (games.rows?.length || 0)
    + (games.rows?.length ? ' (' + games.rows.map(g => `${g.away_team}@${g.home_team}`).join(', ') + ')' : ''));

  let created = 0;
  for (const game of games.rows || []) {
    for (const team of [game.home_team, game.away_team]) {
      for (const { positions, statKey, roundTo } of MADDEN_PROP_POSITION_STATS) {
        const statConfig = SPORTSBOOK_PROP_STAT_TYPES[statKey];
        const candidate = await findMaddenPropCandidate(guild.id, league.league_id, team, positions, statConfig.statType, statConfig.field, weekIndex);
        if (!candidate) {
          console.log('[PLAYER PROP GEN 7J-13PROP] ' + team + ' ' + statKey + ' (' + positions.join('/') + '): no candidate found — skipping.');
          continue;
        }
        const playerRef = candidate.roster_id || candidate.presentation_id;
        if (!playerRef) {
          console.log('[PLAYER PROP GEN 7J-13PROP] ' + team + ' ' + statKey + ': candidate ' + (candidate.full_name || '?') + ' has no roster_id/presentation_id — skipping.');
          continue;
        }

        const existing = await pool.query(
          `SELECT id FROM sportsbook_games
           WHERE guild_id = $1 AND league_id = $2::uuid AND bet_type = 'stat_prop'
             AND subject_ref = $3 AND stat_key = $4 AND prop_week_index = $5`,
          [guild.id, league.league_id, playerRef, statKey, weekIndex]
        ).catch(() => ({ rows: [] }));
        if (existing.rows.length) {
          console.log('[PLAYER PROP GEN 7J-13PROP] ' + team + ' ' + statKey + ': ' + candidate.full_name + ' already has an open line for week ' + weekIndex + ' — skipping.');
          continue;
        }

        const history = await getMaddenPlayerStatHistory(guild.id, league.league_id, playerRef, statConfig.statType, statConfig.field, weekIndex);
        const threshold = projectMaddenStatLine(history, roundTo);
        if (threshold === null) {
          console.log('[PLAYER PROP GEN 7J-13PROP] ' + team + ' ' + statKey + ': ' + candidate.full_name + ' has ' + (history?.length || 0) + ' game(s) of history — not enough to project, skipping.');
          continue; // Not enough game history to project responsibly — skip, don't guess.
        }

        // 7J-108PROPTEAM: same reasoning as the manual creation path — the
        // outer loop already knows which team this candidate belongs to
        // (that's literally how findMaddenPropCandidate found them).
        const teamAbbrev = getMaddenTeamAbbrev(team);
        const displayName = (candidate.full_name || 'Unknown Player') + (teamAbbrev ? ` (${teamAbbrev})` : '');
        const statLine = `${displayName} — Over/Under ${threshold} ${statConfig.label} (Week ${weekIndex})`;
        const sportsbookGameId = randomUUID();
        const insertResult = await pool.query(
          `INSERT INTO sportsbook_games
            (id, guild_id, league_id, game_label, home_label, away_label, home_odds, away_odds,
             created_by_user_id, bet_type, subject_type, subject_ref, subject_display_name,
             stat_key, stat_threshold, stat_line, prop_week_index, source, auto_generated, league_game_id)
           VALUES ($1, $2, $3::uuid, $4, $5, $6, -110, -110, 'system', 'stat_prop', 'player',
             $7, $8, $9, $10, $4, $11, 'madden_auto_prop', TRUE, $12)`,
          [sportsbookGameId, guild.id, league.league_id, statLine, `Over ${threshold} ${statConfig.label}`, `Under ${threshold} ${statConfig.label}`, playerRef, displayName, statKey, threshold, weekIndex, game.id]
        ).catch(err => {
          console.error('[MADDEN PROP AUTO] Failed to create prop:', err?.message || err);
          return null;
        });
        // 7J-14REF: only counts as created if the insert actually returned a
        // row — was incrementing unconditionally before, which would have made
        // this log lie about a real insert failure exactly like the one this
        // round was chasing (turned out not to be the case here, but the log
        // shouldn't have been able to mislead on that point either way).
        if (insertResult) created += 1;
      }
    }
  }
  console.log('[PLAYER PROP GEN 7J-13PROP] Done — created: ' + created + ' for ' + weekLabel + ' (weekIndex ' + weekIndex + ')');
  // 7J-14REF: props were inserting correctly into sportsbook_games the whole
  // time (confirmed directly via DB query — all showed status = 'open') but the
  // board never re-rendered to show them. autoCreateMaddenSportsbookLines (the
  // moneyline equivalent of this function) always refreshes the panel after
  // creating a line; this function never did. That's the entire bug — nothing
  // wrong with candidate matching or the insert itself.
  if (created > 0) await updateSportsbookPanel(guild).catch(() => null);
  return { created };
}

// ---------------------------------------------------------------------------
// User vs user detection for Madden games
// Returns true if both teams have a confirmed human owner in madden_imported_team_stats.
// ---------------------------------------------------------------------------
async function isMaddenUserVsUserGame(guildId, leagueId, homeTeam, awayTeam) {
  // 7J-12OWN: was checking madden_imported_team_stats.owner_user_id only — that
  // column comes from the EA sync, which has no concept of Discord accounts, so
  // it's NULL for nearly every team regardless of whether a real owner is
  // configured elsewhere. Same root cause confirmed in getMaddenTeamOwnerForGameThread
  // (game thread owner tagging) this session — madden_franchises is the actual
  // source of truth for owner assignments made through the bot. Check both and
  // prefer whichever has a real value for each team.
  const result = await pool.query(
    `SELECT team_name, owner_user_id FROM madden_imported_team_stats
       WHERE guild_id = $1 AND league_id::text = $2::text
         AND LOWER(team_name) = ANY(ARRAY[LOWER($3), LOWER($4)])
     UNION ALL
     SELECT team_name, owner_user_id FROM madden_franchises
       WHERE guild_id = $1 AND league_id::text = $2::text
         AND LOWER(team_name) = ANY(ARRAY[LOWER($3), LOWER($4)])`,
    [guildId, String(leagueId), homeTeam, awayTeam]
  ).catch(() => ({ rows: [] }));

  const rows = result.rows || [];
  const ownerFor = (teamName) => rows.find(r =>
    r.team_name?.toLowerCase() === teamName?.toLowerCase() && r.owner_user_id
  )?.owner_user_id || null;

  return !!(ownerFor(homeTeam) && ownerFor(awayTeam));
}


// ---------------------------------------------------------------------------
// Sportsbook auto-lines for Madden user vs user games
// Creates betting lines for new scheduled games in the upcoming week.
// ---------------------------------------------------------------------------
async function autoCreateMaddenSportsbookLines(guild, league, weekLabel) {
  const settings = await ensureMaddenLeagueSettings(league);
  if (!settings.sportsbook_auto_lines_enabled) return;

  // Get all scheduled games for the upcoming week that don't have a sportsbook line yet
  const games = await pool.query(
    `SELECT * FROM madden_imported_games
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND LOWER(week_label) = LOWER($3)
       AND LOWER(status) = 'scheduled'
       AND sportsbook_game_id IS NULL`,
    [guild.id, String(league.league_id), weekLabel]
  ).catch(() => ({ rows: [] }));

  // 7J-12CHN: was checking settings.madden_sportsbook_channel_id first — that's
  // the "Madden Sportsbook Channel," where the persistent board itself posts
  // (confirmed with Hxxdie). Betting-line announcements belong in the actual
  // Sportsbook Feed Channel (league.sportsbook_channel_id) instead — posting
  // alerts into the board channel clutters the channel the board is meant to
  // live in undisturbed. Feed channel now takes priority; falls back to the
  // board channel or news channel only if the feed channel isn't configured.
  const feedChannelId = league.sportsbook_channel_id
    || settings.madden_sportsbook_channel_id
    || settings.madden_news_channel_id
    || await getMaddenNewsChannelId(league.league_id).catch(() => null);

  for (const game of games.rows || []) {
    // Only create lines for user vs user matchups
    const isUvU = await isMaddenUserVsUserGame(
      guild.id, league.league_id, game.home_team, game.away_team
    );

    await pool.query(
      `UPDATE madden_imported_games SET is_user_vs_user = $3 WHERE id = $1 AND guild_id = $2`,
      [game.id, guild.id, isUvU]
    ).catch(() => null);

    if (!isUvU) continue;

    // Check for existing sportsbook line to avoid duplicates
    const existing = await pool.query(
      `SELECT id FROM sportsbook_games
       WHERE guild_id = $1 AND league_id = $2::uuid AND source = 'madden_auto'
         AND game_label = $3
         AND status = 'open'`,
      [guild.id, league.league_id, `${game.away_team} @ ${game.home_team}`]
    ).catch(() => ({ rows: [] }));
    if (existing.rows.length) continue;

    const odds = await generateMaddenMatchupOdds(
      guild.id, league, game.home_team, game.away_team
    ).catch(() => ({ homeOdds: -110, awayOdds: -110, homeProbability: 50, awayProbability: 50 }));

    const homeEmoji = getMaddenTeamEmoji(game.home_team);
    const awayEmoji = getMaddenTeamEmoji(game.away_team);
    const gameLabel = `${game.away_team} @ ${game.home_team}`;
    const homeLabel = `${homeEmoji} ${game.home_team}`.trim();
    const awayLabel = `${awayEmoji} ${game.away_team}`.trim();

    const sbGameId = randomUUID();
    await pool.query(
      `INSERT INTO sportsbook_games
        (id, guild_id, league_id, game_label, home_label, away_label, home_odds, away_odds,
         source, auto_generated, created_by_user_id, league_game_id)
       VALUES ($1, $2, $3::uuid, $4, $5, $6, $7, $8, 'madden_auto', TRUE, 'system', $9)`,
      [sbGameId, guild.id, league.league_id, gameLabel, homeLabel, awayLabel,
       odds.homeOdds, odds.awayOdds, game.id]
    ).catch(err => {
      console.error('[MADDEN SPORTSBOOK AUTO] Failed to create line:', err?.message || err);
      return null;
    });

    // Link the madden game to the sportsbook game for auto-settlement
    await pool.query(
      `UPDATE madden_imported_games SET sportsbook_game_id = $3 WHERE id = $1 AND guild_id = $2`,
      [game.id, guild.id, sbGameId]
    ).catch(() => null);

    // Post to sportsbook feed channel
    if (feedChannelId) {
      const feedChannel = await guild.channels.fetch(feedChannelId).catch(() => null);
      if (feedChannel?.isTextBased?.()) {
        await feedChannel.send({
          embeds: [new EmbedBuilder()
            .setTitle(`${GG_EMOJI} Madden Betting Line Opened`)
            .setColor(0x57F287)
            .setDescription(`**${weekLabel}** — ${awayLabel} @ ${homeLabel}`)
            .addFields(
              { name: awayLabel, value: `ML **${odds.awayOdds > 0 ? '+' : ''}${odds.awayOdds}** (${odds.awayProbability}%)`, inline: true },
              { name: homeLabel, value: `ML **${odds.homeOdds > 0 ? '+' : ''}${odds.homeOdds}** (${odds.homeProbability}%)`, inline: true },
              { name: 'How to bet', value: `Use \`/placebet\` to place your wager.`, inline: false }
            )
            .setFooter({ text: 'GG Sports • Madden Sportsbook • Auto-Generated' })
            .setTimestamp()],
        }).catch(() => null);
      }
    }
  }

  // Refresh the sportsbook panel
  await updateSportsbookPanel(guild).catch(() => null);
}


// ---------------------------------------------------------------------------
// 7J-50MADDENREWARD: Madden game_played/game_win currency + activity/legacy
// rewards. Did not exist before this — verified via code search that no
// Madden-specific reward for playing/winning a game existed anywhere;
// game_played_payout/win_payout were only ever wired to the Game Center
// (league_games) path. Built new, per Hxxdie's explicit "1" answer: yes,
// build a real parallel reward system, gated on game_started_at from day
// one so it can never pay out for a game that might have been auto-simmed
// rather than actually played. Mirrors Game Center's existing reward
// shape/values exactly for consistency: game_played_payout currency + 3
// activity to both owners for playing, win_payout currency + 0 activity /
// 2 legacy to the winner (matching the current Track H #27 values, not the
// old pre-audit ones). Same safe-every-sync pattern as
// autoSettleCompletedMaddenSportsbookGames below: its own idempotency
// guard (rewards_paid_at) makes repeat calls harmless.
// ---------------------------------------------------------------------------
async function autoDistributeCompletedMaddenGameRewards(guild, league) {
  const completedGames = await pool.query(
    `SELECT * FROM madden_imported_games
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND game_started_at IS NOT NULL
       AND rewards_paid_at IS NULL
       AND LOWER(status) IN ('final', 'completed', 'completed_with_real_score')
       AND home_score IS NOT NULL AND away_score IS NOT NULL
       AND (home_score > 0 OR away_score > 0)`,
    [guild.id, String(league.league_id)]
  ).catch(() => ({ rows: [] }));

  for (const game of completedGames.rows || []) {
    await distributeMaddenGameCompletionReward(guild, league, game).catch(err =>
      console.error('[7J-50MADDENREWARD] Reward distribution failed for game', game.id, ':', err?.message));
  }
}

async function distributeMaddenGameCompletionReward(guild, league, game) {
  const homeScore = Number(game.home_score || 0);
  const awayScore = Number(game.away_score || 0);

  const settings = await getCurrencySettings(guild.id);
  const homeOwner = await getMaddenTeamOwnerForGameThread(guild, league, game.home_team, game.home_team_role_id).catch(() => null);
  const awayOwner = await getMaddenTeamOwnerForGameThread(guild, league, game.away_team, game.away_team_role_id).catch(() => null);
  // Tie (homeScore === awayScore) falls through both comparisons to null —
  // no win bonus paid, game_played still pays to both owners below.
  const winnerOwner = homeScore > awayScore ? homeOwner : awayScore > homeScore ? awayOwner : null;

  // 7J-USERVSUSERPAYOUTS: same requirement as the generic Game Center path
  // (reportLeagueGameCore) — a CPU/unclaimed opponent means no real
  // opposing stakes, so neither game-played nor win payouts should fire,
  // even for whichever side does have a real owner.
  const isUserVsUserMaddenGame = Boolean(homeOwner && awayOwner);

  // 7J-USERHEADTOHEAD: same recording as the generic path.
  if (isUserVsUserMaddenGame) {
    await recordUserHeadToHead(guild.id, homeOwner.id, awayOwner.id, winnerOwner?.id || null);
  }

  const paidOwners = new Set();
  if (isUserVsUserMaddenGame) {
    for (const owner of [homeOwner, awayOwner]) {
      if (owner && !paidOwners.has(owner.id)) {
        paidOwners.add(owner.id);
        if (Number(settings.game_played_payout) > 0) {
          await addCurrency(
            guild.id,
            owner.id,
            Number(settings.game_played_payout),
            'game_played',
            `Game played: ${game.away_team} @ ${game.home_team}`,
            'system'
          ).catch(() => null);
        }
        await addActivityPoints(guild.id, owner.id, 3, 0, league.league_id).catch(() => null);
        await addParticipationScore(guild.id, owner.id, 1, league.league_id).catch(() => null);
        // 7J-GAMESPLAYEDMILESTONE: same fix as the generic Game Center
        // path — see comment there.
        await incrementRecognitionStat(guild.id, owner.id, 'games_played', 1).catch(() => null);
      }
    }
  }
  // 7J-97SUSPEND: same decrement as the other game-played path.
  await decrementActiveSuspensionsForTeam(guild.id, league.league_id, game.home_team).catch(() => null);
  await decrementActiveSuspensionsForTeam(guild.id, league.league_id, game.away_team).catch(() => null);
  await refreshSuspensionsBoard(guild, league).catch(() => null);
  // 7J-99WAGER: settle any accepted wager tied to this game now that it has
  // a real final score.
  await settleGameWager(guild, game).catch(err => console.error('[Wager] Settlement failed:', err?.message));

  if (isUserVsUserMaddenGame && winnerOwner) {
    if (Number(settings.win_payout) > 0) {
      await addCurrency(
        guild.id,
        winnerOwner.id,
        Number(settings.win_payout),
        'game_win',
        `Game win: ${homeScore > awayScore ? game.home_team : game.away_team}`,
        'system'
      ).catch(() => null);
    }
    await addActivityPoints(guild.id, winnerOwner.id, 0, 3, league.league_id).catch(() => null);
  }

  await pool.query(`UPDATE madden_imported_games SET rewards_paid_at = NOW() WHERE id = $1`, [game.id]);
}

// ---------------------------------------------------------------------------
// Auto-settle Madden sportsbook bets when game results come in
// Called when a game's status changes to final/completed.
// ---------------------------------------------------------------------------
// Narrow and deliberately separate from autoProcessMaddenGameResults below: this
// ONLY settles sportsbook bets on newly-completed games, nothing else. Safe to
// call on every single sync regardless of week-advance status, because
// autoSettleMaddenSportsbookBet's own idempotency guard (skips anything not
// still 'open') makes repeat calls harmless. autoProcessMaddenGameResults itself
// can't be run this freely — its news/streak/performance detection has no such
// guard and would duplicate-post every sync until the week actually advances.
async function autoSettleCompletedMaddenSportsbookGames(guild, league) {
  const completedGames = await pool.query(
    `SELECT * FROM madden_imported_games
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND sportsbook_game_id IS NOT NULL
       AND LOWER(status) IN ('final', 'completed', 'completed_with_real_score', 'away_win', 'home_win', 'tie')
       AND home_score IS NOT NULL AND away_score IS NOT NULL
       AND (home_score > 0 OR away_score > 0)`,
    [guild.id, String(league.league_id)]
  ).catch(() => ({ rows: [] }));

  for (const game of completedGames.rows || []) {
    await autoSettleMaddenSportsbookBet(guild, league, game).catch(err =>
      console.error('[AUTO DETECT] Individual game sportsbook settlement failed:', err?.message));
  }
}

async function autoSettleMaddenSportsbookBet(guild, league, maddenGame) {
  if (!maddenGame.sportsbook_game_id) return;
  const homeScore = Number(maddenGame.home_score || 0);
  const awayScore = Number(maddenGame.away_score || 0);
  if (homeScore === 0 && awayScore === 0) return; // No real score yet

  const sportsbookGameResult = await pool.query(
    `SELECT * FROM sportsbook_games WHERE id = $1 AND guild_id = $2 LIMIT 1`,
    [maddenGame.sportsbook_game_id, guild.id]
  ).catch(() => ({ rows: [] }));
  const sportsbookGame = sportsbookGameResult.rows[0];
  // Idempotency guard — critical now that this can be called on every sync
  // (decoupled from the week-advance gate below) rather than only once. Without
  // this, an already-settled game would get re-processed on every subsequent
  // sync: harmless for bets themselves (performSportsbookSettlement only ever
  // pays out 'open' bets), but it would spam a duplicate settlement feed post
  // every single sync until the week finally advances.
  if (!sportsbookGame || sportsbookGame.status !== 'open') return;

  const winnerSide = homeScore > awayScore ? 'home' : awayScore > homeScore ? 'away' : null;
  if (!winnerSide) {
    // Tie — refund rather than silently leave every bet sitting open forever.
    await refundSportsbookGameBets(guild, sportsbookGame, 'system', 'Game ended in a tie').catch(err =>
      console.error('[MADDEN SPORTSBOOK SETTLE] Tie refund failed:', err?.message));
    return;
  }

  // 7J-49MADDEN: Track H item 26 extension, per Hxxdie. If "Game Started"
  // was never pressed, refund every bet instead of settling — this is the
  // real vs. simulated game filter: EA's sync data carries no signal
  // distinguishing a game a human actually played from one the franchise
  // auto-simmed, so requiring this button before any payout is possible
  // becomes that missing signal. Members get nothing at all for a
  // simulated game, exactly as intended — no win/loss settlement, bet
  // amount just comes back.
  if (!maddenGame.game_started_at) {
    await refundSportsbookGameBets(
      guild,
      sportsbookGame,
      'system',
      '"Game Started" was never pressed before this game completed — refunded rather than settled, since this may have been a simulated game rather than one actually played.'
    ).catch(err => console.error('[MADDEN SPORTSBOOK SETTLE] Unstarted-game refund failed:', err?.message));
    return;
  }

  // Settle through the same full settlement path /sportsbook settle uses — this
  // is a real fix, not just a refactor: the previous version of this function
  // only ever settled parlay legs riding on the game and then marked the game
  // 'settled' directly, but never touched straight (non-parlay) bets on
  // sportsbook_bets at all. Anyone with a plain moneyline bet on an
  // auto-settled Madden game was never paid out or marked lost — their bet just
  // sat 'open' forever, silently, with no error anywhere.
  const settings = await getCurrencySettings(guild.id);
  await performSportsbookSettlement(guild, sportsbookGame, winnerSide, 'system', settings).catch(err =>
    console.error('[MADDEN SPORTSBOOK SETTLE]', err?.message));

  // 7J-PROPSTUCKFIX: per Hxxdie — a player prop tied to this exact game
  // (T. Benson rushing yards, etc.) was staying listed on the board
  // indefinitely. Root cause: this function settles the game's moneyline
  // line the moment its score comes in via sync, individually, mid-week —
  // but player props for that same game only ever got swept by
  // autoSettleOpenStatProps as part of the *full week advancing*
  // (7J-26STORY's 4b step). If the week never advances again after this
  // game (end of season, or simply no further games synced), that prop
  // stays 'open' forever with nothing left to ever settle it. Running the
  // same idempotent stat-prop sweep here too closes that gap — it only
  // settles a prop where the matching stat data actually already exists,
  // so calling it opportunistically like this is safe to repeat.
  await autoSettleOpenStatProps({ guild, user: { id: 'system' } }, league, { confirm: true }).catch(err =>
    console.error('[MADDEN SPORTSBOOK SETTLE] Stat prop sweep for this game failed:', err?.message));
}


// ---------------------------------------------------------------------------
// Game results processor
// Detects newly completed games and generates event objects for the news system.
// ---------------------------------------------------------------------------
async function autoProcessMaddenGameResults(guild, league, weekLabel) {
  const events = [];

  // 7J-10BY-PLAYOFFCOVERAGEGATE: real bug, confirmed live — per the
  // original 7J-PLAYOFFCOVERAGE intent (see handleMaddenPlayoffBracketTransition/
  // postMaddenPlayoffMatchupPreview), playoff coverage was meant to REPLACE
  // regular-season narrative content, not run alongside it — but nothing
  // ever actually suppressed the regular-season blocks below once the
  // league reached playoffs. Confirmed live: eliminated teams (no games
  // left to play) kept generating "3 straight" streak/hot-seat/power-rank-
  // mover stories from whatever their last 3 regular-season games happened
  // to be, weeks after being knocked out — stale, contextless noise
  // competing with the actual playoff coverage for space. Fetched once
  // here and used to gate the streak/hot-seat/undefeated-watch/division-
  // race/power-ranking-mover blocks below, none of which make sense once
  // most of the league isn't playing anymore ("division race" and "coach
  // hot seat" are meaningless after the regular season ends). Game results
  // themselves and stat leaders are untouched — those still matter for
  // whichever teams are still alive.
  const stageForNarrativeGate = (await ensureMaddenLeagueSettings(league).catch(() => ({}))).current_season_stage || 'preseason';

  // Find games that just completed (have scores, status = final)
  const completedGames = await pool.query(
    `SELECT * FROM madden_imported_games
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND week_label IS NOT NULL
       AND LOWER(status) IN ('final', 'completed', 'completed_with_real_score')
       AND home_score IS NOT NULL AND away_score IS NOT NULL
       AND (home_score > 0 OR away_score > 0)
     ORDER BY updated_at DESC
     LIMIT 32`,
    [guild.id, String(league.league_id)]
  ).catch(() => ({ rows: [] }));

  // 7J-GAMERESULTDEDUP: per Hxxdie — real bug, found while investigating
  // the safety of syncing again shortly after a previous "new week
  // detected" cycle. This query had NO dedup at all: every time a new
  // week is detected, it re-pulls the top 32 most-recently-updated
  // completed games unconditionally and rebuilds fresh news events for
  // every one of them. A game already covered in a previous cycle would
  // get silently re-announced as "news" a second time if it was still
  // sitting in that top-32 window on a later cycle — a real, live risk
  // once a transitional week (like the "Pro Bowl" safe-label fallback)
  // could legitimately fire more than once in a row. Filters out games
  // that have already had their result posted, using the same
  // shouldPostMaddenStoryline dedup infrastructure already proven
  // elsewhere in this codebase, keyed by each game's stable UUID id —
  // so a repeat cycle can never re-cover an already-announced result,
  // regardless of how many times it fires.
  const games = [];
  for (const game of completedGames.rows || []) {
    const shouldAnnounce = await shouldPostMaddenStoryline(guild.id, league.league_id, 'game_result_news', game.id, 'posted').catch(() => false);
    if (shouldAnnounce) games.push(game);
  }

  for (const game of games) {
    const homeScore = Number(game.home_score || 0);
    const awayScore = Number(game.away_score || 0);
    const winner = homeScore > awayScore ? game.home_team : game.away_team;
    const loser = homeScore > awayScore ? game.away_team : game.home_team;
    const margin = Math.abs(homeScore - awayScore);

    events.push({
      type: 'game_result',
      winner,
      loser,
      homeTeam: game.home_team,
      awayTeam: game.away_team,
      homeScore,
      awayScore,
      margin,
      weekLabel: game.week_label || weekLabel,
      winnerEmoji: getMaddenTeamEmoji(winner),
      loserEmoji: getMaddenTeamEmoji(loser),
    });

    // Auto-settle sportsbook if linked
    if (game.sportsbook_game_id) {
      await autoSettleMaddenSportsbookBet(guild, league, game).catch(() => null);
    }
  }

  // 7J-10BY-STATLEADERSWEEKINDEX: real bug, confirmed live — latestWeekIndex
  // used to be the global MAX(week_index) across the whole table, which was
  // silently correct before the catch-up loop existed (autoProcessMaddenGameResults
  // was only ever called once per sync, always for the truly-latest week, so
  // "global max" and "this week" were always the same number by coincidence).
  // With catch-up now processing several historical weeks in one sync, that
  // coincidence breaks: every iteration computed the SAME global max
  // regardless of which historical week it was actually processing, so
  // Week 15 and Week 16's "Stat Leaders"/big-performance posts showed
  // identical, always-latest-week data instead of each week's own. Derives
  // the target week_index from the specific weekLabel this call is for
  // instead — matches the displayWeek = weekIndex + 1 relationship already
  // established at import time (see the weekly-stat import above).
  //
  // 7J-PLAYOFFSTATLEADERSFIX: per Hxxdie — real bug, confirmed live (a
  // "Super Bowl Stat Leaders" post showed players from teams that weren't
  // even in the Super Bowl). The playoff branch used to fall back to a
  // genuinely global MAX(week_index) with no stage_index awareness — but
  // 7J-PLAYOFFSTATDISCOVERY's playoff stat probes store one of their two
  // candidate conventions at week_index=0 (the SAME value real
  // regular-season Week 1 uses), which a global MAX() can never surface
  // once any regular-season week has been imported. The result was always
  // just whichever regular-season week happened to be numerically
  // highest, mislabeled with the playoff round's name — exactly what was
  // seen live. Separately, even once the right week_index is identified,
  // week_index alone doesn't uniquely identify a playoff round's stats —
  // the postseason-stage convention's week_index=0 collides with real
  // Week 1 data, distinguished only by stage_index, which nothing
  // downstream (this query or getMaddenAwardRaceLeaders) ever filtered on.
  // Fixed both together: computes the same two real candidate
  // (week_index, stage_index) pairs 7J-PLAYOFFSTATDISCOVERY already probes
  // EA with for the current playoff round, checks which one actually has
  // rows on file (same "whichever convention actually returns real rows is
  // the one that gets used" reasoning as that fix, rather than guessing
  // independently here), and carries stage_index through to every
  // downstream query alongside week_index instead of week_index alone.
  const regularSeasonWeekMatch = String(weekLabel || '').trim().match(/^week\s+(\d+)$/i);
  let latestWeekIndex;
  let latestStageIndex = 1; // EA_PLAYER_STAT_DISCOVERY_STAGE_INDEX default — matches regular-season import
  if (regularSeasonWeekMatch) {
    latestWeekIndex = Number(regularSeasonWeekMatch[1]) - 1; // displayWeek = weekIndex + 1
  } else {
    const [labelGroup, labelIdx] = maddenWeekLabelSortKey(weekLabel);
    const playoffCandidates = [];
    if (labelGroup === 2 && labelIdx >= 0 && labelIdx <= 3) {
      // labelIdx: 0=Wild Card, 1=Divisional, 2=Conference Championship, 3=Super Bowl
      const scheduleWeekIndex = 18 + labelIdx + (labelIdx === 3 ? 1 : 0); // skips 21 (Pro Bowl)
      const postseasonStageIndex = 2 + labelIdx + (labelIdx === 3 ? 1 : 0); // skips 5 (Pro Bowl)
      playoffCandidates.push({ weekIndex: scheduleWeekIndex, stageIndex: 1 });
      playoffCandidates.push({ weekIndex: 0, stageIndex: postseasonStageIndex });
    }
    let foundCandidate = null;
    for (const candidate of playoffCandidates) {
      const probeResult = await pool.query(
        `SELECT 1 FROM madden_player_weekly_stats
         WHERE guild_id = $1 AND league_id::text = $2::text AND week_index = $3 AND stage_index = $4 LIMIT 1`,
        [guild.id, String(league.league_id), candidate.weekIndex, candidate.stageIndex]
      ).catch(() => ({ rows: [] }));
      if (probeResult.rows.length) { foundCandidate = candidate; break; }
    }
    if (foundCandidate) {
      latestWeekIndex = foundCandidate.weekIndex;
      latestStageIndex = foundCandidate.stageIndex;
    } else {
      // Not a recognized playoff label, or EA hasn't exported that round's
      // stats yet — same global-max fallback as before, now also reading
      // back whichever stage_index that row actually used so downstream
      // queries stay consistent instead of silently assuming stage 1.
      const latestWeekResult = await pool.query(
        `SELECT week_index, stage_index FROM madden_player_weekly_stats
         WHERE guild_id = $1 AND league_id::text = $2::text
         ORDER BY week_index DESC, imported_at DESC LIMIT 1`,
        [guild.id, String(league.league_id)]
      ).catch(() => ({ rows: [] }));
      latestWeekIndex = Number(latestWeekResult.rows[0]?.week_index || 0);
      latestStageIndex = Number(latestWeekResult.rows[0]?.stage_index ?? 1);
    }
  }

  const bigPerfs = (latestWeekIndex > 0 || latestStageIndex > 1) ? await pool.query(
    `SELECT ws.*, p.first_name, p.last_name, p.position, p.team_name, p.age
     FROM madden_player_weekly_stats ws
     LEFT JOIN madden_players p ON p.id = ws.player_key
       AND p.guild_id = ws.guild_id
     WHERE ws.guild_id = $1 AND ws.league_id = $2 AND ws.week_index = $3 AND ws.stage_index = $4
       AND (
         (ws.stat_type = 'passing' AND (ws.raw_payload->>'passYds')::numeric > 300) OR
         (ws.stat_type = 'rushing' AND (ws.raw_payload->>'rushYds')::numeric > 125) OR
         (ws.stat_type = 'receiving' AND (ws.raw_payload->>'recYds')::numeric > 100) OR
         (ws.stat_type = 'passing' AND (ws.raw_payload->>'passTDs')::numeric >= 3) OR
         (ws.stat_type = 'rushing' AND (ws.raw_payload->>'rushTDs')::numeric >= 2) OR
         (ws.stat_type = 'receiving' AND (ws.raw_payload->>'recTDs')::numeric >= 2)
       )
     LIMIT 10`,
    [guild.id, String(league.league_id), latestWeekIndex, latestStageIndex]
  ).catch(() => ({ rows: [] })) : { rows: [] };

  // Budding star watch — a young player (24 or under) having a big game gets
  // flagged as its own story type, distinct from a routine veteran highlight.
  const BUDDING_STAR_MAX_AGE = 24;

  // 7J-29STORY: season-high / record-setting performance — checks whether a
  // big performance is literally the best any player has posted in the
  // league THIS season for that stat category, not just "a good game."
  // Scoped to yardage stats only (passYds/rushYds/recYds) — TD-count
  // triggers are already exciting without needing season context.
  const YARDAGE_FIELD_BY_STAT_TYPE = { passing: 'passYds', rushing: 'rushYds', receiving: 'recYds' };
  const seasonMaxByStatType = {};
  for (const [statType, field] of Object.entries(YARDAGE_FIELD_BY_STAT_TYPE)) {
    const maxResult = await pool.query(
      `SELECT MAX((raw_payload->>$4)::numeric) AS max_val FROM madden_player_weekly_stats
       WHERE guild_id = $1 AND league_id::text = $2::text AND stat_type = $3 AND week_index <= $5`,
      [guild.id, String(league.league_id), statType, field, latestWeekIndex]
    ).catch(() => ({ rows: [{ max_val: null }] }));
    seasonMaxByStatType[statType] = Number(maxResult.rows[0]?.max_val) || 0;
  }

  for (const perf of bigPerfs.rows || []) {
    const raw = perf.raw_payload || {};
    const name = [perf.first_name, perf.last_name].filter(Boolean).join(' ') || 'Unknown';
    const dedupKey = `${name}|${perf.stat_type}|${latestWeekIndex}`;
    const canPost = await shouldPostMaddenStoryline(guild.id, league.league_id, 'big_performance', dedupKey, 'posted').catch(() => true);
    if (!canPost) continue;
    const isBuddingStar = Number(perf.age) > 0 && Number(perf.age) <= BUDDING_STAR_MAX_AGE;
    const yardageField = YARDAGE_FIELD_BY_STAT_TYPE[perf.stat_type];
    const perfValue = yardageField ? Number(raw[yardageField]) || 0 : 0;
    const isSeasonHigh = !!yardageField && perfValue > 0 && perfValue >= seasonMaxByStatType[perf.stat_type];
    events.push({
      type: isSeasonHigh ? 'season_record' : (isBuddingStar ? 'budding_star' : 'big_performance'),
      playerName: name,
      team: perf.team_name,
      position: perf.position,
      statType: perf.stat_type,
      stats: raw,
      age: perf.age || null,
      isBuddingStar,
      isSeasonHigh,
      teamEmoji: getMaddenTeamEmoji(perf.team_name),
    });
  }

  // Streak detection
  // 7J-26STORY: the previous version of this query was broken two ways — its
  // status filter ('final'/'completed_with_real_score') doesn't match the
  // real values madden_imported_games actually stores (confirmed:
  // home_win/away_win/tie/completed), and its DISTINCT ON (team) collapsed
  // each team to one arbitrary row before summing, which structurally could
  // never produce a real multi-game streak count. It's very likely never
  // returned a result in practice. Replaced with computeMaddenTeamStreak
  // (verified correct, most-recent-first per team) and a dedup gate so a
  // streak that's already been reported doesn't get reported again on every
  // subsequent sync while it holds — only when it crosses to a new milestone.
  // 7J-26STORY: coach hot seat — composite of two signals already computed
  // elsewhere in this function (losing skid + power ranking drop), not new
  // detection. Queried separately here (rather than reordering the existing
  // power_ranking_movers block below) to avoid any risk of disturbing that
  // already-correct code's position/behavior.
  // 7J-10BY-PLAYOFFCOVERAGEGATE: see the gate comment at the top of this
  // function — everything from here through the division-race block below
  // is regular-season-only narrative content.
  //
  // 7J-OFFSEASONNARRATIVEGATE: real bug, confirmed live — this was written
  // as "not playoffs" instead of "is regular", which is a broader
  // condition than the comment above (and the original 7J-10BY-
  // PLAYOFFCOVERAGEGATE intent) ever meant: 'preseason' and 'offseason'
  // both also satisfy "not playoffs", so this whole block silently
  // re-enabled itself the moment the league moved past playoffs into
  // offseason/Pro Bowl — confirmed live producing "3 straight" hot-streak
  // and "picks up their first win" storylines for already-eliminated teams
  // during Pro Bowl week, using whatever games computeMaddenTeamStreak
  // happened to consider each team's most recent (itself not season-key
  // scoped — same root cause shape as the bracket bugs earlier this
  // session, just never exercised until an actual offseason transition
  // ran). Narrowed to the literal condition the comment already describes.
  if (stageForNarrativeGate === 'regular') {
  const powerDropLookup = await pool.query(
    `SELECT team_name, (previous_rank - rank) AS movement
     FROM madden_power_rankings
     WHERE league_id::text = $1::text AND previous_rank IS NOT NULL AND (previous_rank - rank) <= -3`,
    [String(league.league_id)]
  ).catch(() => ({ rows: [] }));
  const powerDropByTeam = new Map((powerDropLookup.rows || []).map(r => [r.team_name, r.movement]));

  const streakTeamsResult = await pool.query(
    `SELECT DISTINCT team_name, coach_name FROM madden_franchises WHERE guild_id = $1 AND league_id = $2`,
    [guild.id, league.league_id]
  ).catch(() => ({ rows: [] }));
  const currentSeasonKeyForStreaks = await getMaddenCurrentSeasonKey(league).catch(() => null);
  for (const { team_name: teamName, coach_name: coachName } of streakTeamsResult.rows || []) {
    if (!teamName) continue;
    const streak = await computeMaddenTeamStreak(guild.id, league.league_id, teamName, currentSeasonKeyForStreaks);
    if (!streak.type || streak.type === 'tie') continue;

    // 7J-29STORY: bounce-back / snapped streak needs to run when the CURRENT
    // streak is just 1 game (a single win right after a skid) — the
    // `streak.count < 3` check below would otherwise skip these teams
    // entirely before this ever got a chance to run, so it has to happen
    // before that continue, not after.
    if (streak.type === 'win' && streak.count === 1) {
      const snapped = await checkMaddenStreakSnapped(guild.id, league.league_id, teamName, currentSeasonKeyForStreaks);
      if (snapped) {
        const snapKey = snapped.isFirstWinEver ? 'first_win' : `snapped_${snapped.priorRunLength}`;
        const canPostSnap = await shouldPostMaddenStoryline(guild.id, league.league_id, 'bounce_back', teamName, snapKey).catch(() => false);
        if (canPostSnap) {
          events.push({
            type: 'bounce_back',
            team: teamName,
            priorRunLength: snapped.priorRunLength,
            isFirstWinEver: snapped.isFirstWinEver,
            teamEmoji: getMaddenTeamEmoji(teamName),
          });
        }
      }
    }

    if (streak.count < 3) continue;
    if (![3, 5, 7, 9, 11, 13, 15].includes(streak.count)) continue;
    const storyType = streak.type === 'win' ? 'hot_streak' : 'losing_skid';
    const canReport = await shouldPostMaddenStoryline(guild.id, league.league_id, storyType, teamName, streak.count).catch(() => false);
    if (!canReport) continue;
    events.push({
      type: 'streak',
      team: teamName,
      streakType: streak.type,
      streakLen: streak.count,
      teamEmoji: getMaddenTeamEmoji(teamName),
    });

    if (storyType === 'losing_skid' && powerDropByTeam.has(teamName)) {
      const hotSeatCanPost = await shouldPostMaddenStoryline(guild.id, league.league_id, 'coach_hot_seat', teamName, streak.count).catch(() => false);
      if (hotSeatCanPost) {
        events.push({
          type: 'coach_hot_seat',
          team: teamName,
          coachName: coachName || null,
          streakLen: streak.count,
          rankDrop: Math.abs(powerDropByTeam.get(teamName)),
          teamEmoji: getMaddenTeamEmoji(teamName),
        });
      }
    }
  }

  // 7J-29STORY: undefeated / winless watch — a "state of the league" angle,
  // distinct from a generic streak post. Gated to week 4+ (maddenWeekSortValue)
  // to skip trivial early-season noise where most teams are still 1-0/0-1,
  // and dedup-gated per week so it only posts once even across repeat syncs.
  if (maddenWeekSortValue(weekLabel) >= 4) {
    const recordsResult = await pool.query(
      `SELECT team_name, wins, losses FROM madden_imported_team_stats WHERE guild_id = $1 AND league_id::text = $2::text`,
      [guild.id, String(league.league_id)]
    ).catch(() => ({ rows: [] }));
    const undefeated = (recordsResult.rows || []).filter(r => r.wins > 0 && r.losses === 0).map(r => r.team_name);
    const winless = (recordsResult.rows || []).filter(r => r.losses > 0 && r.wins === 0).map(r => r.team_name);
    if (undefeated.length || winless.length) {
      const watchKey = [...undefeated, ...winless].sort().join(',');
      const canPostWatch = await shouldPostMaddenStoryline(guild.id, league.league_id, 'undefeated_winless_watch', weekLabel, watchKey).catch(() => false);
      if (canPostWatch) {
        events.push({ type: 'undefeated_winless_watch', undefeated, winless });
      }
    }
  }

  // 7J-29STORY: division race — fires when the current division leader (best
  // win%) changes from what was last reported. Explicitly checks whether a
  // prior leader was ever recorded before treating it as news — otherwise the
  // very first sync of the season would fire one post per division just for
  // establishing the initial status quo, which isn't really a "race" story.
  const divisionRecordsResult = await pool.query(
    `SELECT team_name, wins, losses FROM madden_imported_team_stats WHERE guild_id = $1 AND league_id::text = $2::text`,
    [guild.id, String(league.league_id)]
  ).catch(() => ({ rows: [] }));
  const byDivision = new Map();
  for (const row of divisionRecordsResult.rows || []) {
    const { division } = await getTeamConferenceDivisionForLeague(guild.id, league.league_id, row.team_name, league).catch(() => ({ division: null }));
    if (!division) continue;
    if (!byDivision.has(division)) byDivision.set(division, []);
    byDivision.get(division).push(row);
  }
  for (const [division, teams] of byDivision) {
    if (teams.length < 2) continue;
    let leader = null;
    let bestPct = -1;
    for (const t of teams) {
      const total = t.wins + t.losses;
      const pct = total > 0 ? t.wins / total : 0;
      if (pct > bestPct) { bestPct = pct; leader = t; }
    }
    if (!leader) continue;
    const existingLeader = await pool.query(
      `SELECT last_value FROM madden_storyline_posts WHERE guild_id = $1 AND league_id::text = $2::text AND story_type = 'division_leader' AND subject_key = $3`,
      [guild.id, String(league.league_id), division]
    ).catch(() => ({ rows: [] }));
    const hadPriorLeader = existingLeader.rows.length > 0;
    const changed = await shouldPostMaddenStoryline(guild.id, league.league_id, 'division_leader', division, leader.team_name).catch(() => false);
    if (changed && hadPriorLeader) {
      events.push({ type: 'division_race', division, leader: leader.team_name, record: `${leader.wins}-${leader.losses}` });
    }
  }

  // 7J-PLAYOFFPICTURESEEDFIX: per Hxxdie — this used to rank all 32 teams
  // league-wide by raw win pct and take a flat top-N cutoff, which isn't how
  // NFL playoffs work at all: seeding is PER CONFERENCE, and the 4 division
  // winners are guaranteed a top-4 seed in their conference regardless of
  // record — a flat cross-conference sort can and did push genuinely-in
  // teams (a weaker conference's division winner, or its 3rd wildcard) below
  // the cutoff line while a stronger conference's non-division-winning
  // 8th-best team incorrectly looked "in." Real case that surfaced this:
  // Packers (9-7) and Texans (8-8) were both actually seeded playoff teams
  // (NFC 6, AFC 7) but got reported as the bubble because their pct ranked
  // outside a flat top-14 cut. Mirrors the real seeding rule already
  // implemented in selectNflPlayoffTeams (division winners 1-4 by
  // within-conference record, next-3 records fill wildcards 5-7), sourced
  // from madden_imported_team_stats since Madden leagues never populate
  // league_standings (selectNflPlayoffTeams's normal data source). Only
  // applied for NFL-format leagues — other sports' storyline behavior is
  // left exactly as it was, since there's no reported issue there and no
  // reason to touch working code while fixing this.
  // 7J-PLAYOFFPICTUREPOSTSEASON: per Hxxdie — this only ever checked a raw
  // week-number threshold (>= 8), so it kept posting "who's fighting for
  // the last playoff spot" content even after the regular season ended and
  // the real bracket was already set — stale and confusing once there's no
  // more race left to speculate about.
  //
  // 7J-PLAYOFFPICTURESTAGEFIX: per Hxxdie — real regression, confirmed
  // live. The first fix here checked maddenWeekLabelSortKey(weekLabel)[0]
  // === 1 (regular season) to decide whether to stop — but "Pro Bowl"
  // (the safe synthetic label 7J-POSTPLAYOFFWEEKFIX2 introduced later
  // this session, deliberately NOT taught to the classifier since doing
  // so would have shifted the Super Bowl's index in the 4-round
  // bracket-building logic used throughout this session) falls through to
  // that same default regular-season classification, so this gate wrongly
  // let the playoff-picture story fire again during Pro Bowl week — well
  // after the real bracket was set. Checks current_season_stage directly
  // instead — the same authoritative DB field already relied on elsewhere
  // this session specifically because parsing EA's week-label strings
  // keeps being unreliable for exactly this kind of "are we still in the
  // regular season" question. Stage is 'regular' only during the actual
  // regular season; 'playoffs' and 'offseason' both correctly stop this,
  // regardless of what confusing label a transitional week happens to get.
  const seasonStageForPicture = (await ensureMaddenLeagueSettings(league).catch(() => ({}))).current_season_stage;
  if (maddenWeekSortValue(weekLabel) >= 8 && seasonStageForPicture === 'regular') {
    const canPostPicture = await shouldPostMaddenStoryline(guild.id, league.league_id, 'playoff_picture', weekLabel, 'posted').catch(() => false);
    if (canPostPicture) {
      const allTeamsResult = await pool.query(
        `SELECT team_name, wins, losses, points_for, points_against FROM madden_imported_team_stats WHERE guild_id = $1 AND league_id::text = $2::text`,
        [guild.id, String(league.league_id)]
      ).catch(() => ({ rows: [] }));
      // 7J-SEEDTIEBREAKFIX2: same non-deterministic-tie bug as
      // selectMaddenPlayoffTeams (see 7J-SEEDTIEBREAKFIX), plus the same
      // head-to-head tiebreaker (7J-H2HTIEBREAK) — kept consistent with the
      // bracket's own seeding computation so this storyline can't report a
      // different team than the bracket actually seeds in a future week.
      const h2hGamesForPicture = await pool.query(
        `SELECT home_team, away_team, home_score, away_score, status
         FROM madden_imported_games
         WHERE guild_id = $1 AND league_id::text = $2::text
           AND LOWER(COALESCE(status, '')) IN ('completed', 'final', 'completed_with_real_score', 'away_win', 'home_win', 'tie')`,
        [guild.id, String(league.league_id)]
      ).catch(() => ({ rows: [] }));
      const h2hWinnerForPicture = new Map();
      for (const g of h2hGamesForPicture.rows || []) {
        const home = String(g.home_team || '').toLowerCase();
        const away = String(g.away_team || '').toLowerCase();
        if (!home || !away) continue;
        const homeScore = Number(g.home_score) || 0;
        const awayScore = Number(g.away_score) || 0;
        let winner = null;
        if (homeScore > awayScore) winner = home;
        else if (awayScore > homeScore) winner = away;
        else {
          const s = String(g.status || '').toLowerCase();
          if (s === 'home_win') winner = home;
          else if (s === 'away_win') winner = away;
        }
        if (winner) h2hWinnerForPicture.set([home, away].sort().join('|'), winner);
      }
      const ranked = (allTeamsResult.rows || [])
        .map(t => ({ team: t.team_name, wins: t.wins, losses: t.losses, pct: (t.wins + t.losses) > 0 ? t.wins / (t.wins + t.losses) : 0, pointDiff: Number(t.points_for || 0) - Number(t.points_against || 0) }))
        .sort((a, b) => {
          if (b.pct !== a.pct) return b.pct - a.pct;
          if (b.wins !== a.wins) return b.wins - a.wins;
          const h2hKey = [a.team.toLowerCase(), b.team.toLowerCase()].sort().join('|');
          const h2hResult = h2hWinnerForPicture.get(h2hKey);
          if (h2hResult === a.team.toLowerCase()) return -1;
          if (h2hResult === b.team.toLowerCase()) return 1;
          return b.pointDiff - a.pointDiff || a.team.localeCompare(b.team);
        });

      if (getPlayoffFormatKey(league) === 'nfl') {
        const withMeta = await Promise.all(ranked.map(async t => {
          const { conference, division } = await getTeamConferenceDivisionForLeague(guild.id, league.league_id, t.team, league).catch(() => ({}));
          return { ...t, resolvedConference: conference || 'Conference', resolvedDivision: division || 'Division' };
        }));
        const conferences = [...new Set(withMeta.map(t => t.resolvedConference))];
        const bubbles = [];
        for (const conference of conferences) {
          const inConf = withMeta.filter(t => t.resolvedConference === conference);
          const divisions = [...new Set(inConf.map(t => t.resolvedDivision))];
          const divisionWinners = divisions.map(d => inConf.filter(t => t.resolvedDivision === d)[0]).filter(Boolean)
            .sort((a, b) => inConf.indexOf(a) - inConf.indexOf(b));
          const winnerNames = new Set(divisionWinners.map(t => t.team));
          const wildcardEligible = inConf.filter(t => !winnerNames.has(t.team));
          const lastIn = wildcardEligible[2]; // 3rd wildcard = last team actually in
          const firstOut = wildcardEligible[3]; // next-best non-division-winner = true bubble miss
          if (lastIn && firstOut) {
            bubbles.push({
              conference,
              lastIn: { team: lastIn.team, record: `${lastIn.wins}-${lastIn.losses}` },
              firstOut: { team: firstOut.team, record: `${firstOut.wins}-${firstOut.losses}` },
            });
          }
        }
        if (bubbles.length) {
          events.push({ type: 'playoff_picture', bubbles });
        }
      } else {
        const playoffCount = Number(league.playoff_team_count || 8);
        if (ranked.length > playoffCount) {
          const lastIn = ranked[playoffCount - 1];
          const firstOut = ranked[playoffCount];
          events.push({
            type: 'playoff_picture',
            inTeams: ranked.slice(0, playoffCount).map(r => r.team),
            bubbles: [{
              conference: null,
              lastIn: lastIn ? { team: lastIn.team, record: `${lastIn.wins}-${lastIn.losses}` } : null,
              firstOut: firstOut ? { team: firstOut.team, record: `${firstOut.wins}-${firstOut.losses}` } : null,
            }],
          });
        }
      }
    }
  }
  } // end 7J-10BY-PLAYOFFCOVERAGEGATE (streak/hot-seat/undefeated-watch/division-race/playoff-picture)

  // Award race leaders
  const awardLeaders = await getMaddenAwardRaceLeaders(guild.id, league.league_id, latestWeekIndex != null ? latestWeekIndex : null, latestStageIndex != null ? latestStageIndex : null).catch(() => null);
  if (awardLeaders) {
    events.push({ type: 'award_race', leaders: awardLeaders });
  }

  // Power ranking movers (biggest jumps/drops) — see 7J-10BY-PLAYOFFCOVERAGEGATE
  // and 7J-OFFSEASONNARRATIVEGATE above: same reasoning, gated the same
  // way (regular season only, not just "not playoffs"), just a separate
  // block since stat leaders (directly above) needed to stay ungated in
  // between.
  if (stageForNarrativeGate === 'regular') {
  const powerMovers = await pool.query(
    `SELECT team_name, rank, previous_rank,
       (previous_rank - rank) AS movement
     FROM madden_power_rankings
     WHERE league_id::text = $1::text
       AND previous_rank IS NOT NULL
       AND ABS(previous_rank - rank) >= 3
     ORDER BY ABS(previous_rank - rank) DESC
     LIMIT 4`,
    [String(league.league_id)]
  ).catch(() => ({ rows: [] }));

  if (powerMovers.rows?.length) {
    events.push({
      type: 'power_ranking_movers',
      movers: powerMovers.rows.map(r => ({
        team: r.team_name,
        rank: r.rank,
        previousRank: r.previous_rank,
        movement: r.movement,
        emoji: getMaddenTeamEmoji(r.team_name),
      })),
    });
  }
  }

  return events;
}

// 7J-33FIX: two bugs of the same shape as the earlier big-performance/streak
// fixes. (1) No week filter at all — this ran every sync and summed every
// week of the season to date, despite being posted under a "Week N" title as
// if it were that week's leaders. (2) A single query ordered by pass_yds with
// one shared LIMIT 20 meant passing rows (one per team with a passing stat
// line) could fill the entire limit before any rushing/receiving row was ever
// reached — not "no rushing data happened," structurally impossible for
// rushing rows to survive the cutoff most weeks. Split into three
// per-stat-type queries, each with its own limit, so all three categories are
// guaranteed a fair shot regardless of how many passing rows exist.
async function getMaddenAwardRaceLeaders(guildId, leagueId, weekIndex = null, stageIndex = null) {
  // 7J-PLAYOFFSTATLEADERSFIX: week_index alone doesn't uniquely identify a
  // playoff round's stats — see the comment at this function's caller.
  // Only applied when a specific week is being asked for (weekIndex !=
  // null); season-long aggregate calls (weekIndex == null) are unaffected
  // and keep summing across every stage exactly as before.
  const filters = [];
  const values = [guildId, String(leagueId)];
  if (weekIndex != null) {
    values.push(weekIndex);
    filters.push(`week_index = $${values.length}`);
    if (stageIndex != null) {
      values.push(stageIndex);
      filters.push(`stage_index = $${values.length}`);
    }
  }
  const weekFilter = filters.length ? `AND ${filters.join(' AND ')}` : '';

  const [passing, rushing, receiving] = await Promise.all([
    pool.query(
      `SELECT full_name, position, team_name, 'passing' AS stat_type,
              SUM((raw_payload->>'passYds')::numeric) AS pass_yds,
              SUM((raw_payload->>'passTDs')::numeric) AS pass_tds
       FROM madden_player_weekly_stats
       WHERE guild_id = $1 AND league_id = $2 AND stat_type = 'passing' ${weekFilter}
       GROUP BY full_name, position, team_name
       ORDER BY pass_yds DESC NULLS LAST
       LIMIT 10`,
      values
    ).catch(() => ({ rows: [] })),
    pool.query(
      `SELECT full_name, position, team_name, 'rushing' AS stat_type,
              SUM((raw_payload->>'rushYds')::numeric) AS rush_yds,
              SUM((raw_payload->>'rushTDs')::numeric) AS rush_tds
       FROM madden_player_weekly_stats
       WHERE guild_id = $1 AND league_id = $2 AND stat_type = 'rushing' ${weekFilter}
       GROUP BY full_name, position, team_name
       ORDER BY rush_yds DESC NULLS LAST
       LIMIT 10`,
      values
    ).catch(() => ({ rows: [] })),
    pool.query(
      `SELECT full_name, position, team_name, 'receiving' AS stat_type,
              SUM((raw_payload->>'recYds')::numeric) AS rec_yds,
              SUM((raw_payload->>'recTDs')::numeric) AS rec_tds
       FROM madden_player_weekly_stats
       WHERE guild_id = $1 AND league_id = $2 AND stat_type = 'receiving' ${weekFilter}
       GROUP BY full_name, position, team_name
       ORDER BY rec_yds DESC NULLS LAST
       LIMIT 10`,
      values
    ).catch(() => ({ rows: [] })),
  ]);

  return [...passing.rows, ...rushing.rows, ...receiving.rows];
}


// ---------------------------------------------------------------------------
// ESPN-style news via Claude API
// Generates headlines + blurbs for the week's notable events.
// Falls back to templates if the API fails.
// ---------------------------------------------------------------------------
// 7J-STATLEADERSWEEKFIX: per Hxxdie — weekLabel here is newWeekLabel from
// the caller: the week that was just DETECTED as starting, not the week
// these results/stats actually happened in. That's correct for
// forward-looking content (the Game of the Week preview genuinely is
// about the upcoming matchup), but the Stat Leaders post specifically
// titled itself with weekLabel too, making "Conf. Playoff Stat Leaders"
// show Divisional's actual leaders — a real, confusing mismatch, since
// those games hadn't been played yet under that label. resultsWeekLabel
// (the real prior week these events are FROM, already computed by the
// caller as previousWeekLabel) is used specifically for that post instead.
async function generateMaddenESPNNews(guild, league, events, weekLabel, resultsWeekLabel = null) {
  const newsChannelId = await getMaddenNewsChannelId(league.league_id).catch(() => null);
  if (!newsChannelId) return;
  const newsChannel = await guild.channels.fetch(newsChannelId).catch(() => null);
  if (!newsChannel?.isTextBased?.()) return;

  const settings = await ensureMaddenLeagueSettings(league);
  const useClaudeApi = settings.espn_news_enabled !== false;

  // Build structured event summary for Claude
  const gameResults = events.filter(e => e.type === 'game_result');
  const bigPerfs   = events.filter(e => e.type === 'big_performance');
  const buddingStars = events.filter(e => e.type === 'budding_star');
  const seasonRecords = events.filter(e => e.type === 'season_record');
  const streaks    = events.filter(e => e.type === 'streak');
  const bounceBacks = events.filter(e => e.type === 'bounce_back');
  const movers     = events.find(e => e.type === 'power_ranking_movers');
  const awards     = events.find(e => e.type === 'award_race');
  const majorMoves = events.filter(e => e.type === 'major_movement');
  const gotw       = events.find(e => e.type === 'game_of_the_week');
  const hotSeats   = events.filter(e => e.type === 'coach_hot_seat');
  const undefeatedWatch = events.find(e => e.type === 'undefeated_winless_watch');
  const divisionRaces = events.filter(e => e.type === 'division_race');
  const playoffPicture = events.find(e => e.type === 'playoff_picture');

  const hasAnyEvent = gameResults.length || bigPerfs.length || streaks.length || movers || awards
    || majorMoves.length || buddingStars.length || gotw || hotSeats.length || seasonRecords.length
    || bounceBacks.length || undefeatedWatch || divisionRaces.length || playoffPicture;
  if (!hasAnyEvent) return;

  let newsItems = [];

  if (useClaudeApi && hasAnyEvent) {
    try {
      const [weekGroup, weekIdx] = maddenWeekLabelSortKey(weekLabel);
      const isPlayoffWeek = weekGroup === 2;
      const playoffRoundLabel = isPlayoffWeek ? tournamentBracketRoundLabel(weekIdx + 1, 4, weekIdx, 'nfl') : null;
      const context = {
        leagueName: league.league_name,
        weekLabel,
        isPlayoffWeek,
        playoffRoundLabel,
        gameResults: gameResults.slice(0, 8).map(g => ({
          matchup: `${g.awayTeam} @ ${g.homeTeam}`,
          score: `${g.awayTeam} ${g.awayScore} - ${g.homeTeam} ${g.homeScore}`,
          winner: g.winner,
          margin: g.margin,
        })),
        bigPerformances: bigPerfs.slice(0, 5).map(p => ({
          player: p.playerName,
          team: p.team,
          position: p.position,
          statType: p.statType,
          stats: p.stats,
        })),
        streaks: streaks.slice(0, 4).map(s => ({
          team: s.team,
          type: s.streakType,
          length: s.streakLen,
        })),
        majorRosterMovements: majorMoves.slice(0, 4).map(m => ({
          player: m.playerName,
          movementType: m.eventType,
          team: m.team,
          previousTeam: m.oldTeam,
          overall: m.overall,
          position: m.position,
        })),
        buddingStarWatch: buddingStars.slice(0, 3).map(b => ({
          player: b.playerName,
          team: b.team,
          position: b.position,
          age: b.age,
          statType: b.statType,
          stats: b.stats,
        })),
        gameOfTheWeek: gotw ? {
          matchup: `${gotw.awayTeam} (${gotw.awayRecord}) @ ${gotw.homeTeam} (${gotw.homeRecord})`,
          isUserVsUser: gotw.isUserVsUser,
        } : null,
        coachHotSeat: hotSeats.slice(0, 2).map(h => ({
          team: h.team,
          coach: h.coachName,
          losingStreak: h.streakLen,
          powerRankingDrop: h.rankDrop,
        })),
        seasonHighPerformances: seasonRecords.slice(0, 2).map(p => ({
          player: p.playerName,
          team: p.team,
          position: p.position,
          statType: p.statType,
          stats: p.stats,
        })),
        bounceBackWins: bounceBacks.slice(0, 3).map(b => ({
          team: b.team,
          priorLosingStreak: b.priorRunLength,
          isFirstWinOfSeason: b.isFirstWinEver,
        })),
        undefeatedWinlessWatch: undefeatedWatch ? {
          undefeated: undefeatedWatch.undefeated,
          winless: undefeatedWatch.winless,
        } : null,
        divisionRaces: divisionRaces.slice(0, 3).map(d => ({
          division: d.division,
          newLeader: d.leader,
          record: d.record,
        })),
        playoffPicture: playoffPicture ? {
          bubbles: playoffPicture.bubbles,
        } : null,
      };

      const parsed = await callClaudeNewsApi(
        `You are an ESPN sports journalist covering a Madden NFL franchise league called "${league.league_name}". 
Write punchy, authentic sports news headlines and one-line blurbs for this week's results. 
Rules:
- Each item: a headline (under 80 chars) and a blurb (1-2 sentences, under 150 chars).
- Vary your angles: underdog stories, dominant performances, individual highlights, team narratives, streaks, big roster moves.
- For team narratives on a losing streak or a team sliding in the power rankings, lean into real "team drama" framing — concern, pressure, fans losing patience — not just a neutral stat report.
- Major roster movements (majorRosterMovements) are genuinely big news — a star player signed, released, or traded. Write these with real weight, like a real trade/signing reaction piece, not a routine transaction log entry.
- buddingStarWatch entries are young players (24 or under) putting up big numbers — frame these as "one to watch" / breakout-potential stories, genuinely excited about a player's future, not just a stat line.
- gameOfTheWeek, if present, should always be included as one of the items — write it as a genuine preview/hype piece for the marquee matchup of the upcoming week, not a past result.
- coachHotSeat entries are teams struggling on multiple fronts at once (a real losing streak AND a real power-rankings slide happening together) — this is the most serious drama angle available. Write it like real "is the seat getting hot" sports-radio speculation, naming the coach if given, but don't invent anything not in the data.
- If isPlayoffWeek is true, EVERY gameResult this week is single-elimination — the loser's season is over, the winner advances toward playoffRoundLabel's next round. Write these with real playoff stakes and finality (a losing team's season ending is genuinely heavier than a regular-season loss), not the same neutral tone as a Week 6 result.
- seasonHighPerformances are the single best game any player has posted in the league THIS season for that stat, not just a good game — write these with extra weight, like a real "best performance of the year (so far)" piece.
- bounceBackWins are teams that just snapped a real losing streak (or a still-winless team's first win) — genuine feel-good redemption stories, warm and triumphant in tone, the opposite of the drama framing used for skids.
- undefeatedWinlessWatch is a "state of the league" angle — write about which team(s) remain perfect or still winless, especially compelling if there's only one of either.
- divisionRaces fire when a division's first-place team changes hands — real "there's a new team atop the division" news.
- playoffPicture, if present, has a bubbles array — one entry per conference for NFL leagues (each with a conference label), or a single entry for other sports. Cover who's in and who's right on the bubble for each entry, real "playoff race" content, mentioning both the last team in and first team out by name and by conference when a conference label is present.
- Never use the same sentence structure twice. Mix tones: hype, surprise, concern, admiration.
- Sound like a real ESPN writer, not a bot. Use sports vernacular naturally.
- Return ONLY valid JSON: array of objects with "headline", "blurb", and "team" keys ("team" is the single primary team this story is about, in the exact team name/abbreviation format used in the data above — e.g. "49ers" or "SF" — or null if the story isn't really about one specific team, like a league-wide playoff picture update). No markdown, no preamble.
- Max 5 items. Pick the most compelling stories.`,
        JSON.stringify(context),
        1000
      );
      if (Array.isArray(parsed)) newsItems = parsed.slice(0, 5);
    } catch (err) {
      console.warn('[MADDEN ESPN NEWS] Claude API failed, falling back to templates:', err?.message);
    }
  }

  // Template fallback — always runs if Claude API returned nothing
  if (!newsItems.length) {
    for (const g of gameResults.slice(0, 3)) {
      newsItems.push({
        headline: `${g.winner} defeat ${g.loser === g.homeTeam ? g.loser : g.loser}`,
        blurb: `Final score: ${g.awayTeam} ${g.awayScore} – ${g.homeTeam} ${g.homeScore}. ${g.margin >= 21 ? 'A dominant performance.' : g.margin <= 3 ? 'A nail-biter to the end.' : ''}`,
        team: g.winner,
      });
    }
    for (const s of streaks.slice(0, 2)) {
      newsItems.push({
        headline: `${s.team} ${s.streakType === 'win' ? 'on fire' : 'struggling'} at ${s.streakLen} straight`,
        blurb: s.streakType === 'win'
          ? `${s.team} have won ${s.streakLen} in a row and are building serious momentum.`
          : `${s.team} have dropped ${s.streakLen} straight and need answers fast.`,
        team: s.team,
      });
    }
    if (movers?.movers?.length) {
      const bigMover = movers.movers[0];
      const dir = bigMover.movement > 0 ? '▲' : '▼';
      const isDrop = bigMover.movement < 0;
      newsItems.push({
        headline: `${bigMover.team} ${dir} ${Math.abs(bigMover.movement)} in power rankings`,
        blurb: isDrop
          ? `${bigMover.team} have tumbled from #${bigMover.previousRank} to #${bigMover.rank} — the questions are starting to pile up.`
          : `${bigMover.team} moved from #${bigMover.previousRank} to #${bigMover.rank} in this week's power rankings.`,
        team: bigMover.team,
      });
    }
    for (const m of majorMoves.slice(0, 2)) {
      const teamName = m.team ? maddenTeamDisplayName(m.team) : 'a team';
      const verb = m.eventType === 'released' ? 'released' : m.eventType === 'team_change' ? 'traded for' : 'signed';
      newsItems.push({
        headline: `${teamName} ${verb} ${m.playerName}${m.overall ? ` (${m.overall} OVR)` : ''}`,
        blurb: `A significant roster move for ${teamName}${m.position ? ` at ${m.position}` : ''} — one worth keeping an eye on.`,
        team: m.team,
      });
    }
    for (const b of buddingStars.slice(0, 2)) {
      const teamName = b.team ? maddenTeamDisplayName(b.team) : 'his team';
      newsItems.push({
        headline: `Budding Star Watch: ${b.playerName}${b.age ? ` (${b.age})` : ''} is turning heads`,
        blurb: `${b.playerName} put together a big game for ${teamName} — a name to keep watching this season.`,
        team: b.team,
      });
    }
    if (gotw) {
      newsItems.push({
        headline: `Game of the Week: ${gotw.awayTeam} @ ${gotw.homeTeam}`,
        blurb: `${gotw.awayTeam} (${gotw.awayRecord}) travel to face ${gotw.homeTeam} (${gotw.homeRecord}) in this week's marquee matchup.`,
        team: gotw.homeTeam,
      });
    }
    for (const h of hotSeats.slice(0, 1)) {
      const teamName = maddenTeamDisplayName(h.team);
      newsItems.push({
        headline: h.coachName ? `Is ${h.coachName} on the hot seat?` : `${teamName} head coach on the hot seat`,
        blurb: `${teamName} have dropped ${h.streakLen} straight and slid ${h.powerRankingDrop} spots in the power rankings — the pressure is mounting.`,
        team: h.team,
      });
    }
    for (const p of seasonRecords.slice(0, 1)) {
      const teamName = p.team ? maddenTeamDisplayName(p.team) : 'his team';
      newsItems.push({
        headline: `${p.playerName} posts the best game of the season so far`,
        blurb: `${p.playerName}'s outing for ${teamName} is the top single-game performance the league has seen this season.`,
        team: p.team,
      });
    }
    for (const b of bounceBacks.slice(0, 1)) {
      const teamName = maddenTeamDisplayName(b.team);
      newsItems.push({
        headline: b.isFirstWinEver ? `${teamName} picks up their first win of the season` : `${teamName} snap a ${b.priorRunLength}-game skid`,
        blurb: b.isFirstWinEver
          ? `${teamName} finally get in the win column after starting the season winless.`
          : `${teamName} put an end to a ${b.priorRunLength}-game losing streak with a much-needed win.`,
        team: b.team,
      });
    }
    if (undefeatedWatch && (undefeatedWatch.undefeated.length || undefeatedWatch.winless.length)) {
      const undefeatedNames = undefeatedWatch.undefeated.map(maddenTeamDisplayName).join(', ');
      const winlessNames = undefeatedWatch.winless.map(maddenTeamDisplayName).join(', ');
      newsItems.push({
        headline: undefeatedWatch.undefeated.length === 1 ? `${undefeatedNames} remain the league's last unbeaten team` : 'State of the League: perfect and winless teams',
        blurb: [
          undefeatedWatch.undefeated.length ? `Still perfect: ${undefeatedNames}.` : '',
          undefeatedWatch.winless.length ? `Still searching for a win: ${winlessNames}.` : '',
        ].filter(Boolean).join(' '),
      });
    }
    for (const d of divisionRaces.slice(0, 1)) {
      const teamName = maddenTeamDisplayName(d.leader);
      newsItems.push({
        headline: `${teamName} take over first place in the ${d.division}`,
        blurb: `${teamName} (${d.record}) have moved to the top of the ${d.division} standings.`,
        team: d.leader,
      });
    }
    if (playoffPicture?.bubbles?.length) {
      const parts = playoffPicture.bubbles.map(b => {
        const lastInName = b.lastIn ? maddenTeamDisplayName(b.lastIn.team) : null;
        const firstOutName = b.firstOut ? maddenTeamDisplayName(b.firstOut.team) : null;
        if (!lastInName || !firstOutName) return null;
        const prefix = b.conference ? `In the ${b.conference}, ` : '';
        return `${prefix}${lastInName} (${b.lastIn.record}) currently hold the last playoff spot, with ${firstOutName} (${b.firstOut.record}) right on the outside looking in.`;
      }).filter(Boolean);
      newsItems.push({
        headline: 'Playoff Picture Update',
        blurb: parts.length ? parts.join(' ') : 'The playoff race is heating up as the season enters its final stretch.',
      });
    }
  }

  // Post each news item as a separate embed to the news channel
  for (const item of newsItems) {
    if (!item.headline) continue;

    // Pick event color based on content
    let color = 0x3498DB;
    const h = String(item.headline || '').toLowerCase();
    if (h.includes('fire') || h.includes('win') || h.includes('dominant')) color = 0x57F287;
    if (h.includes('strug') || h.includes('drop') || h.includes('skid')) color = 0xED4245;
    if (h.includes('power') || h.includes('rank')) color = 0xFEE75C;

    await newsChannel.send({
      embeds: [(() => {
        const embed = new EmbedBuilder()
          .setTitle(`${GG_EMOJI} ${item.headline}`)
          .setDescription(item.blurb || '')
          .setColor(color)
          .setFooter({ text: `GG Sports • ${league.league_name} • ${weekLabel}` })
          .setTimestamp();
        // 7J-MADDENNEWSLOGO: per Hxxdie — Madden's news feed is a fully
        // separate pipeline from the generic (non-Madden) one, and never
        // got the same logo treatment. Reuses getMaddenTeamLogoUrl, the
        // exact same lookup already proven working in the transaction/
        // roster embeds shown right next to this feed.
        const logoUrl = item.team ? getMaddenTeamLogoUrl(item.team) : null;
        if (logoUrl) embed.setThumbnail(logoUrl);
        return embed;
      })()],
    }).catch(() => null);

    await new Promise(r => setTimeout(r, 300)); // small delay to avoid rate limits
  }

  // Post award race summary if we have stats
  if (awards?.leaders?.length) {
    const qbs = awards.leaders.filter(r => r.position === 'QB' && r.pass_yds > 0).slice(0, 3);
    const rbs = awards.leaders.filter(r => ['HB', 'FB'].includes(r.position) && r.rush_yds > 0).slice(0, 3);
    const wrs = awards.leaders.filter(r => ['WR', 'TE'].includes(r.position) && r.rec_yds > 0).slice(0, 3);
    if (qbs.length || rbs.length || wrs.length) {
      const qbLines = qbs.map(r => `**${r.full_name}** (${r.team_name}) — ${r.pass_yds} YDS ${r.pass_tds} TD`).join('\n') || 'No data';
      const rbLines = rbs.map(r => `**${r.full_name}** (${r.team_name}) — ${r.rush_yds} YDS ${r.rush_tds} TD`).join('\n') || 'No data';
      const wrLines = wrs.map(r => `**${r.full_name}** (${r.team_name}) — ${r.rec_yds} YDS ${r.rec_tds} TD`).join('\n') || 'No data';
      await newsChannel.send({
        embeds: [new EmbedBuilder()
          .setTitle(`${GG_EMOJI} ${resultsWeekLabel || weekLabel} Stat Leaders`)
          .setColor(0x9B59B6)
          .addFields(
            { name: '🏈 Passing', value: qbLines, inline: true },
            { name: '🏃 Rushing', value: rbLines, inline: true },
            { name: '🙌 Receiving', value: wrLines, inline: true },
          )
          .setFooter({ text: `GG Sports • ${league.league_name} Weekly Stat Leaders` })
          .setTimestamp()],
      }).catch(() => null);
    }
  }
}


// ---------------------------------------------------------------------------
// Season transition handler — fires when preseason → regular season detected
// ---------------------------------------------------------------------------
// 7J-OLDSEASONTHREADCLEANUP: real bug, confirmed live — the previous
// season's game threads (including the Super Bowl thread itself) were
// still sitting around, undeleted, once the new season's preseason began.
// The existing per-week rotation cleanup (getPreviousWeekWithThreads /
// deleteMaddenWeekThreadsSilent) only ever compares week labels within
// what it assumes is a single season — a prior season's Super Bowl
// (group 2 in maddenWeekLabelSortKey) can never be found as "before" a
// new season's Preseason Week 1 (group 0) by that comparison, the same
// cross-season group-number problem confirmed multiple times elsewhere
// this session (thread creation's own anchor query hit the identical
// shape — see 7J-THREADANCHORSEASONSCOPE). Rather than trying to make
// that week-by-week comparison season-aware, cleans up every thread NOT
// belonging to the season now starting, in one pass, at the one reliable
// point every league passes through when a new season begins.
async function cleanupMaddenPriorSeasonGameThreads(guild, league) {
  const currentSeasonKey = await getMaddenCurrentSeasonKey(league).catch(() => null);
  const staleThreadGames = await pool.query(
    `SELECT id, thread_id FROM madden_imported_games
     WHERE guild_id = $1 AND league_id::text = $2::text
       AND thread_id IS NOT NULL
       AND season_key IS DISTINCT FROM $3::text`,
    [guild.id, String(league.league_id), currentSeasonKey]
  ).catch(() => ({ rows: [] }));
  let deletedCount = 0;
  for (const game of staleThreadGames.rows || []) {
    const thread = await guild.channels.fetch(game.thread_id).catch(() => null);
    if (thread) await thread.delete('GG Sports: new season started, old game thread cleanup').catch(() => null);
    deletedCount += 1;
  }
  if (staleThreadGames.rows?.length) {
    await pool.query(
      `UPDATE madden_imported_games SET thread_id = NULL, thread_created_at = NULL
       WHERE guild_id = $1 AND league_id::text = $2::text
         AND thread_id IS NOT NULL AND season_key IS DISTINCT FROM $3::text`,
      [guild.id, String(league.league_id), currentSeasonKey]
    ).catch(() => null);
  }
  console.log('[SEASON TRANSITION] Cleaned up old-season game threads:', deletedCount);
  return deletedCount;
}
function maddenIsPreseasonWeek(weekLabel) {
  return maddenWeekLabelSortKey(weekLabel)[0] === 0;
}
// 7J-OFFSEASONSTAGEFALLBACKFIX: real bug, confirmed live — used to check
// maddenWeekLabelSortKey(weekLabel)[0] === 1, same shape mistake as
// 7J-DIVPLAYOFFFIX/7J-10BY-PROBOWLFIX before it, just hitting a different
// set of labels. Group 1 in that sort key is BOTH the genuine "Week N"
// regular-season match AND the catch-all fallback for anything totally
// unrecognized — which, per 7J-OFFSEASONGATEFIX just below, is exactly
// what most offseason sub-stage labels are (Resign Players, Free Agency
// Preview, Free Agency Stage 1/2, Draft, Draft Recap, etc. — EA's
// reported "current week" has no concept of these, so whatever stale/
// unrecognized value it's sitting on during any of them falls straight
// into that same fallback bucket). Confirmed live: with the league still
// in Draft Recap week — the last offseason stage before preseason even
// begins — this returned true, firing the real "Regular Season Starts
// NOW" season-kickoff flow (and, bundled into that same flow, a power
// rankings regeneration that pulled whatever was still sitting in
// madden_imported_team_stats — the just-finished season's final
// standings, since real Week 1 hadn't been played or synced yet) weeks
// before either should have happened. Checks the literal "Week N" pattern
// directly instead of trusting the sort key's group number, so it can
// never again match anything the sort key had to fall back on.
function maddenIsRegularSeasonWeek(weekLabel) {
  return /^week\s+\d+$/i.test(String(weekLabel || '').trim());
}

// Regular/playoffs -> offseason transition, mirroring the preseason -> regular pattern
// above. Per user instruction: for Madden leagues, league history should post
// automatically once the league has advanced past Super Bowl week and synced — no
// manual `/maddenseason yearend confirm:true` or `/maddenseason offseasonlock
// confirm:true` needed; both fire together here. Guarded by current_season_stage
// so this only fires once per season even though autosync runs every 60 seconds; the
// stage is reset back to 'preseason' the moment next year's preseason weeks are
// detected (see the reset branch below), so the cycle repeats correctly year over year.
// 7J-NOPRESEASONKICKOFF: real gap, confirmed live via user report — not all
// Madden leagues run a preseason. For one that doesn't, EA reports the
// first real "Week 1" label directly after the offseason stages (Free
// Agency, Draft, etc.) with no "Preseason Week N" label ever appearing in
// between. Extracted the kickoff steps (stat wipe, embed reset, stage flip,
// announcement, draft recap) into their own function so both real paths —
// normal preseason→regular (handleMaddenSeasonTransition, unchanged
// behavior) and offseason→regular directly (handleMaddenOffseasonTransition,
// new) — can call the exact same steps instead of one of them being
// missing entirely. Previously a no-preseason league's stage would never
// leave 'offseason' at all (handleMaddenOffseasonTransition's reset only
// checked for a preseason week label; handleMaddenSeasonTransition's
// kickoff only checked for a preseason→regular transition) — both would
// silently never fire, permanently blocking the wipe, the kickoff
// announcement, and next year's Super Bowl→offseason detection (which
// itself is gated on stage no longer being stuck at 'offseason').
async function wipeMaddenWeeklyStats(guildId, leagueId) {
  const wiped = await pool.query(
    `DELETE FROM madden_player_weekly_stats
     WHERE guild_id = $1 AND league_id::text = $2::text`,
    [guildId, String(leagueId)]
  ).catch(err => {
    console.error('[SEASON TRANSITION] Stats wipe failed:', err?.message);
    return null;
  });
  return wiped?.rowCount || 0;
}

async function performMaddenRegularSeasonKickoff(guild, league, newWeekLabel) {
  // 1. Wipe weekly stats accumulated before the regular season (preseason
  // exhibition games, or whatever leftover rows exist for a league with no
  // preseason at all) so nobody's regular-season numbers start inflated.
  const wipedCount = await wipeMaddenWeeklyStats(guild.id, league.league_id);
  console.log('[SEASON TRANSITION] Wiped pre-regular-season stats:', wipedCount, 'rows');

  // 1a. Old-season game thread cleanup — no-op if the preseason-entry
  // branch already handled this (same season_key, nothing left stale);
  // the real coverage this adds is for leagues that skip preseason
  // entirely (7J-NOPRESEASONKICKOFF) and hit this function directly.
  await cleanupMaddenPriorSeasonGameThreads(guild, league).catch(err =>
    console.error('[SEASON TRANSITION] Old-season thread cleanup failed:', err?.message || err));

  // 2. Reset persistent embed message IDs so they repost fresh for regular season
  await pool.query(
    `UPDATE madden_league_settings
     SET standings_message_id = NULL,
         power_rankings_message_id = NULL,
         free_agents_message_id = NULL,
         current_season_stage = 'regular',
         updated_at = NOW()
     WHERE league_id = $1`,
    [league.league_id]
  ).catch(() => null);

  // 2a. 7J-10BY-TRADECOUNTRESET: real bug, confirmed live — league_trade_counts
  // had no season scoping and nothing anywhere ever reset it, despite
  // trade_limit_per_season (checked against this exact counter — see the
  // negotiate/confirm flow) being explicitly a PER-SEASON limit. Without a
  // reset, a team's count only ever goes up across the league's entire
  // history, meaning any team that ever hit the limit once would be
  // permanently locked out of trading forever, every season after, with no
  // automatic recovery — only the existing manual staff override command
  // could unstick them, one team at a time, every single season. Resets
  // every team back to 0 at the same reliable kickoff point that already
  // resets weekly stats and the persistent boards.
  const tradeCountResetResult = await pool.query(
    `UPDATE league_trade_counts SET trade_count = 0 WHERE league_id = $1`,
    [league.league_id]
  ).catch(err => {
    console.error('[SEASON TRANSITION] Trade count reset failed:', err?.message);
    return null;
  });
  console.log('[SEASON TRANSITION] Reset trade counts:', tradeCountResetResult?.rowCount || 0, 'teams');
  await updateTradeCountPanel(guild, league).catch(err =>
    console.error('[SEASON TRANSITION] Trade count panel refresh failed:', err?.message));

  // 2b. 7J-10BY-BRACKETRESET: real bug, confirmed live — league_playoff_brackets
  // is a single mutable row per league that was never deleted or reset
  // anywhere. handleMaddenPlayoffBracketTransition's "don't build a second
  // bracket on top of an existing one" safety check (correctly meant to
  // stop duplicate builds mid-season) reads that same row — so once a
  // league finished its first season, that row permanently existed
  // forever, and every SUBSEQUENT season's playoffs would silently skip
  // building a real bracket, just catching the stage flag up on top of the
  // previous season's stale bracket/champion data. Deletes it at the same
  // reliable kickoff point already resetting trade counts and stats, so
  // handleMaddenPlayoffBracketTransition finds no existing row and builds
  // a genuine fresh bracket the next time this league reaches Wild Card.
  const bracketResetResult = await pool.query(
    `DELETE FROM league_playoff_brackets WHERE league_id = $1`,
    [league.league_id]
  ).catch(err => {
    console.error('[SEASON TRANSITION] Playoff bracket reset failed:', err?.message);
    return null;
  });
  console.log('[SEASON TRANSITION] Reset playoff bracket:', bracketResetResult?.rowCount || 0, 'row(s) cleared');

  // 2c. 7J-10BY-POWERRANKRESET: lower-stakes than the two above (cosmetic,
  // not a lockout) but same root cause — previous_rank in
  // madden_power_rankings gets overwritten every week regardless, so by
  // itself it's not a permanent-accumulator bug. But without a reset here,
  // the FIRST power-ranking calc of a new season would compare fresh
  // preseason-less rankings against whatever previous_rank was left over
  // from last season's final week, producing a nonsensical "jumped from
  // #8 to #1" mover post right at kickoff. Nulling it means the first
  // real comparison starts clean, same as everything else this season.
  await pool.query(
    `UPDATE madden_power_rankings SET previous_rank = NULL WHERE league_id = $1`,
    [league.league_id]
  ).catch(err => console.error('[SEASON TRANSITION] Power ranking reset failed:', err?.message));

  // 3. Post season kickoff announcement to news channel
  const newsChannelId = await getMaddenNewsChannelId(league.league_id).catch(() => null);
  if (newsChannelId) {
    const newsChannel = await guild.channels.fetch(newsChannelId).catch(() => null);
    if (newsChannel?.isTextBased?.()) {
      await newsChannel.send({
        embeds: [new EmbedBuilder()
          .setTitle(`${GG_EMOJI} 🏈 ${league.league_name} Regular Season Starts NOW`)
          .setColor(0x57F287)
          .setDescription([
            '**The wait is over.** Rosters are set, and every game counts.',
            '',
            `Preseason/offseason records and stats have been cleared. Every team enters ${newWeekLabel} at **0-0**.`,
            '',
            'Game threads, standings, sportsbook lines, and news will auto-update after every advance.',
            '',
            '**May the best GM win.** 🏆',
          ].join('\n'))
          .setFooter({ text: `GG Sports • ${league.league_name} • Season Kickoff` })
          .setTimestamp()],
      }).catch(() => null);
    }
  }

  // 4. Draft Recap backstop — checkAndPostMaddenDraftRecap (run every sync,
  // see 7J-DRAFTRECAPTIMING) is the real, timely trigger now; this is just
  // a safety net in case that never caught a real class for some reason.
  // Its own dedup (shouldPostMaddenStoryline, keyed on class size) means
  // this naturally no-ops if the recap already posted.
  await checkAndPostMaddenDraftRecap(guild, league).catch(err =>
    console.error('[SEASON TRANSITION] Draft recap backstop failed:', err?.message));

  console.log('[SEASON TRANSITION] Complete — regular season is live for league', league.league_id);
}

async function handleMaddenOffseasonTransition(guild, league, newWeekLabel) {
  const settings = await ensureMaddenLeagueSettings(league);
  const stage = settings.current_season_stage || 'preseason';

  // Reset for next year: once a new preseason begins after an offseason was finalized,
  // clear the flag so the next Super Bowl can trigger this again.
  // 7J-10BY-SKIPPRESEASON / STATUS CORRECTED (Session 44 continued 12-14):
  // this comment used to say this branch was "effectively dead" because
  // getMaddenNewAdvanceWeek could never return a "Preseason Week N" label.
  // That's no longer true and hasn't been since 7J-PRESEASONTHREADSENABLE
  // removed the gate that suppressed preseason processing, and
  // 7J-PRESEASONLABELRECONCILE (relocated to the point ea_reported_current_week
  // is persisted) made that field correctly carry the "Preseason " prefix.
  // getMaddenNewAdvanceWeek DOES return "Preseason Week N" now — this is a
  // live, load-bearing branch (offseason -> preseason: stat wipe, old-season
  // thread cleanup, stage flip to 'preseason'), not dead code. Do not
  // assume this doesn't fire without re-checking getMaddenNewAdvanceWeek's
  // current behavior directly.
  if (stage === 'offseason' && maddenIsPreseasonWeek(newWeekLabel)) {
    // 7J-PRESEASONSTATWIPE: per user request — stats should also wipe at
    // the START of preseason, not just at the preseason→regular
    // transition. Without this, whatever weekly-stat rows were left over
    // from last season's playoffs would still be sitting in the table when
    // preseason exhibition games start accumulating new ones on top —
    // technically harmless to real-season stats (the existing
    // preseason→regular wipe still clears everything before Week 1), but
    // means any preseason-stats-dependent view (leaders, awards races)
    // would show stale mixed data for the whole preseason window.
    const wipedCount = await wipeMaddenWeeklyStats(guild.id, league.league_id);
    console.log('[SEASON TRANSITION] Wiped leftover stats at preseason start:', wipedCount, 'rows');
    await cleanupMaddenPriorSeasonGameThreads(guild, league).catch(err =>
      console.error('[SEASON TRANSITION] Old-season thread cleanup failed:', err?.message || err));
    await pool.query(
      `UPDATE madden_league_settings SET current_season_stage = 'preseason', updated_at = NOW() WHERE league_id = $1`,
      [league.league_id]
    ).catch(() => null);
    return;
  }

  // 7J-NOPRESEASONKICKOFF: not every league runs a preseason — EA can go
  // straight from offseason stages to a real "Week 1" with no "Preseason
  // Week N" label ever appearing. Without this branch, the check above
  // never matches (newWeekLabel isn't a preseason label) and this stage
  // gets permanently stuck on 'offseason', which also blocks next year's
  // Super Bowl→offseason detection since that's gated on the stage not
  // already being 'offseason'. Runs the exact same kickoff a preseason
  // league gets via handleMaddenSeasonTransition, just triggered directly
  // off leaving 'offseason' instead of off a preseason→regular transition.
  if (stage === 'offseason' && maddenIsRegularSeasonWeek(newWeekLabel)) {
    console.log('[SEASON TRANSITION] No preseason detected for league', league.league_id, '— offseason → regular season directly.');
    await performMaddenRegularSeasonKickoff(guild, league, newWeekLabel);
    return;
  }

  if (stage === 'offseason') return; // already finalized this season, nothing to do

  const sb = await getMaddenSuperBowlResult(guild.id, league.league_id).catch(() => null);
  if (!sb?.isFinal) return;

  console.log('[SEASON TRANSITION] Super Bowl final detected for league', league.league_id, '— auto-finalizing year-end and offseason lock.');
  try {
    await buildMaddenYearEndPrepEmbed(guild, league, true, null);
  } catch (error) {
    console.error('[SEASON TRANSITION] Auto year-end finalization failed:', error?.message || error);
    return; // don't flip the stage flag if it failed — retry next sync tick
  }

  // 7J-AUTOOFFSEASONLOCK: per Hxxdie — offseasonlock previously only ran as
  // a manual command that nothing else ever called, despite being part of
  // the documented flow. Year-end just finalized successfully above, so
  // the readiness snapshot this saves is meaningful now — running it here
  // means the commissioner never needs to run either command for the
  // normal flow, only readiness remains manual (it's a pure status check
  // with no side effects, so there's nothing to automate there).
  try {
    await buildMaddenOffseasonLockEmbed(guild, league, true, null);
  } catch (error) {
    console.error('[SEASON TRANSITION] Auto offseason lock failed:', error?.message || error);
    // Year-end already succeeded and is the part that actually matters
    // (awards, champion, currency, history) — don't block flipping the
    // stage flag over the lock checkpoint, which is an audit record only.
  }

  // 7J-10BY-DRAFTRECAPRESET: clears the draft-recap lock here rather than
  // keying it to any computed season identity. See checkAndPostMaddenDraftRecap
  // for why: this table's first version keyed its primary key on season_key,
  // which depends on league.madden_season_year — the exact same kind of
  // EA-hub-populated-mid-stream field that's proven unstable multiple times
  // today. If that key shifted between the first post and a later sync, the
  // lock-check would look for a snapshot under a DIFFERENT key, find
  // nothing, and post again — same failure shape, one layer over. This
  // deletes the lock at the one event that's been reliable ALL DAY without
  // a single miss — Super Bowl finalize, confirmed right above this line —
  // so a fresh draft class can post again next season with no key
  // comparison involved at all: the row's mere existence is the lock.
  await pool.query(
    `DELETE FROM madden_draft_recap_snapshots WHERE guild_id = $1 AND league_id::text = $2::text`,
    [guild.id, String(league.league_id)]
  ).catch(err => console.error('[SEASON TRANSITION] Draft recap snapshot reset failed:', err?.message));

  // 7J-10BY-STORYLINERESET: real bug, confirmed live and much bigger in
  // scope than just the playoff preview that surfaced it — madden_storyline_posts
  // is the shared dedup table behind nearly every AI narrative story type
  // this bot posts (win/loss streaks, coach hot seat, division leader
  // changes, undefeated/winless watch, playoff picture, playoff round
  // previews, playoff upsets), and it has NO season scoping anywhere.
  // Every one of those dedup keys is subject+value pairs that legitimately
  // repeat every season verbatim — a team hitting a 3-game win streak, a
  // "Week 1" label, a "Div. Playoff" round label, a division leader who
  // happens to repeat. Once any of those combinations was used once, EVER,
  // that exact story could never post again for that league in any future
  // season — not a one-time miss, a permanent, silent, ever-growing gap
  // in narrative coverage as more seasons pass and more combinations get
  // "used up." Clears the whole table for this league at the same
  // reliable Super Bowl finalize point as the other resets, so every
  // dedup-guarded story gets a genuinely fresh slate each season.
  const storylineResetResult = await pool.query(
    `DELETE FROM madden_storyline_posts WHERE guild_id = $1 AND league_id::text = $2::text`,
    [guild.id, String(league.league_id)]
  ).catch(err => {
    console.error('[SEASON TRANSITION] Storyline dedup reset failed:', err?.message);
    return null;
  });
  console.log('[SEASON TRANSITION] Reset storyline dedup state:', storylineResetResult?.rowCount || 0, 'entries cleared');

  await pool.query(
    `UPDATE madden_league_settings SET current_season_stage = 'offseason', updated_at = NOW() WHERE league_id = $1`,
    [league.league_id]
  ).catch(() => null);
  console.log('[SEASON TRANSITION] Offseason finalization complete for league', league.league_id);
}

// 7J-PLAYOFFCOVERAGE: per Hxxdie — the regular season gets real
// narrative coverage (Game of the Week, streaks, breakouts, division
// races), but once a league actually reaches the playoffs — the thing
// every team spent the whole season playing toward — coverage dropped
// back to generic weekly stat leaders. Real sports media goes deeper on
// playoff coverage, not shallower. Two pieces: this one previews every
// matchup in a newly-built round with real seed/record context and a
// simple prediction (the AI news writer already has a defined voice for
// hype/stakes framing — this just gives it the playoff-specific data to
// work with); postMaddenPlayoffUpsetAlert (below, wired into the
// results-processing loop) flags it when a lower seed actually beats a
// higher one. Posted directly rather than folded into the generic weekly
// AI recap, since a full round preview is substantial enough to deserve
// its own moment rather than competing for space with stat leaders.
async function postMaddenPlayoffMatchupPreview(guild, league, round, roundLabel) {
  // 7J-FINALPREVIEWFLAG: returns whether it actually sent a new post (vs.
  // an early return for no channel/already-posted) so callers responsible
  // for the FINAL round can mark that state durably on the bracket row
  // itself — see the callers' own comments for why the shared dedup table
  // alone isn't sufficient for that one case.
  const newsChannelId = await getMaddenNewsChannelId(league.league_id).catch(() => null);
  if (!newsChannelId) return false;
  const newsChannel = await guild.channels.fetch(newsChannelId).catch(() => null);
  if (!newsChannel?.isTextBased?.()) return false;

  // Dedup — never repost the same round's preview twice, even across
  // repeat syncs or a retry. Not posting here because the dedup already
  // has a record for it counts as "confirmed posted," not a failure —
  // only returns false below for a genuine failure to send, so callers
  // tracking this durably (see 7J-FINALPREVIEWFLAG) don't mistake "already
  // posted" for "needs retrying."
  const shouldPost = await shouldPostMaddenStoryline(guild.id, league.league_id, 'playoff_preview', roundLabel, 'posted').catch(() => false);
  if (!shouldPost) return true;

  const teamsResult = await pool.query(
    `SELECT team_name, wins, losses, ties FROM madden_imported_team_stats WHERE guild_id = $1 AND league_id::text = $2::text`,
    [guild.id, String(league.league_id)]
  ).catch(() => ({ rows: [] }));
  const recordByTeam = new Map((teamsResult.rows || []).map(t => [String(t.team_name).toLowerCase(), `${t.wins}-${t.losses}${t.ties ? `-${t.ties}` : ''}`]));

  const conferences = [...new Set(round.map(s => s.conference).filter(Boolean))];
  const lines = [];
  for (const conference of conferences.length ? conferences : [null]) {
    const confSeries = round.filter(s => s.conference === conference);
    if (!confSeries.length) continue;
    if (conference) lines.push(`**${conference}**`);
    for (const s of confSeries) {
      if (s.bye) {
        lines.push(`${getMaddenTeamEmoji(s.teamA.name)} **${maddenTeamDisplayName(s.teamA.name)}** — first-round bye`);
        continue;
      }
      const recA = recordByTeam.get(s.teamA.name.toLowerCase()) || '—';
      const recB = recordByTeam.get(s.teamB.name.toLowerCase()) || '—';
      const seedA = typeof s.teamA.seed === 'number' ? `#${s.teamA.seed} ` : '';
      const seedB = typeof s.teamB.seed === 'number' ? `#${s.teamB.seed} ` : '';
      // Simple, transparent prediction basis: better seed favored when
      // both are known; better record as a fallback when seed is missing
      // for one side (e.g. a wildcard team the tiebreak computation
      // didn't land on — see 7J-REALBRACKETMATCHUPS). Never claims more
      // certainty than this actually has.
      let favorite = null;
      if (typeof s.teamA.seed === 'number' && typeof s.teamB.seed === 'number') {
        favorite = s.teamA.seed < s.teamB.seed ? s.teamA.name : s.teamB.name;
      }
      const favoriteNote = favorite ? ` — ${maddenTeamDisplayName(favorite)} favored` : '';
      lines.push(`${getMaddenTeamEmoji(s.teamA.name)} **${seedA}${maddenTeamDisplayName(s.teamA.name)}** (${recA}) vs ${getMaddenTeamEmoji(s.teamB.name)} **${seedB}${maddenTeamDisplayName(s.teamB.name)}** (${recB})${favoriteNote}`);
    }
    lines.push('');
  }

  const embed = new EmbedBuilder()
    .setTitle(`🏈 ${roundLabel} Preview — ${league.league_name}`)
    .setColor(0xED4245)
    .setDescription(lines.join('\n').trim().slice(0, 4000) || 'Matchups set.')
    .setFooter({ text: 'GG Sports • Playoff Coverage' })
    .setTimestamp();

  const sendResult = await newsChannel.send({ embeds: [embed] }).catch(() => null);
  return !!sendResult;
}

// Fires when a completed playoff series' winner had a numerically worse
// (higher) seed than the loser — a real upset, not just "a team won."
// Never fires for a bye. Dedup-gated per series id so it can't repeat
// across syncs.
async function postMaddenPlayoffUpsetAlert(guild, league, series, roundLabel) {
  if (series.bye || !series.teamA?.seed || !series.teamB?.seed) return; // need both real seeds to call it an upset at all
  const winnerTeam = series.teamA.name === series.winner ? series.teamA : series.teamB;
  const loserTeam = series.teamA.name === series.winner ? series.teamB : series.teamA;
  if (typeof winnerTeam.seed !== 'number' || typeof loserTeam.seed !== 'number') return;
  if (winnerTeam.seed <= loserTeam.seed) return; // not an upset — better or equal seed won

  const shouldPost = await shouldPostMaddenStoryline(guild.id, league.league_id, 'playoff_upset', series.id, 'posted').catch(() => false);
  if (!shouldPost) return;

  const newsChannelId = await getMaddenNewsChannelId(league.league_id).catch(() => null);
  if (!newsChannelId) return;
  const newsChannel = await guild.channels.fetch(newsChannelId).catch(() => null);
  if (!newsChannel?.isTextBased?.()) return;

  const embed = new EmbedBuilder()
    .setTitle('🚨 Upset Alert')
    .setColor(0xFEE75C)
    .setDescription(`${getMaddenTeamEmoji(winnerTeam.name)} **#${winnerTeam.seed} ${maddenTeamDisplayName(winnerTeam.name)}** knock out **#${loserTeam.seed} ${maddenTeamDisplayName(loserTeam.name)}** ${getMaddenTeamEmoji(loserTeam.name)} in the ${roundLabel}.`)
    .setFooter({ text: 'GG Sports • Playoff Coverage' })
    .setTimestamp();

  await newsChannel.send({ embeds: [embed] }).catch(() => null);
}


// The playoff bracket channel and league_settings column were already
// auto-configured (singleChannelSpecs' playoff_bracket_channel_id entry),
// but autoPostPlayoffBracketPanel was only ever called from the manual
// "Start Playoffs" commissioner button — a structured-league flow with no
// Madden equivalent, so nothing ever built or posted a bracket for a Madden
// league at all. Fires once, the moment Wild Card week is first detected
// while the league is still in 'regular' stage, mirroring the exact same
// once-per-season auto-trigger pattern as handleMaddenSeasonTransition and
// handleMaddenOffseasonTransition. Reuses the same real bracket-building
// pipeline the manual flow uses (buildInitialPlayoffRound,
// createPlayoffSeriesThreads, the league_playoff_brackets upsert,
// refreshPlayoffBracketPanel, autoPostPlayoffBracketPanel) — only the seed
// source differs (selectMaddenPlayoffTeams instead of
// selectPlayoffTeamsForLeague, since Madden leagues don't populate
// league_standings). Checks group === 2 (any playoff week), not
// specifically "Wild Card", so a sync that happens to skip straight past
// Wild Card week (a missed sync tick) still catches the bracket start
// rather than silently never firing.
async function handleMaddenPlayoffBracketTransition(guild, league, newWeekLabel) {
  if (getPlayoffFormatKey(league) !== 'nfl') return;
  const settings = await ensureMaddenLeagueSettings(league);
  const stage = settings.current_season_stage || 'preseason';
  // 7J-BRACKETRECOVERY: per Hxxdie — real stuck state, confirmed live.
  // Manually clearing a corrupted league_playoff_brackets row (the
  // documented recovery step for the season_key matchup bug,
  // 7J-BRACKETSEASONSCOPE) did nothing, because current_season_stage was
  // already sitting at 'playoffs' from the league's earlier, real
  // transition — this function's gate only ever let it past this point
  // while stage === 'regular'. The round-advance function further below
  // has the mirror-image gate (only acts when a bracket row already
  // exists). Together those two gates left "stage is playoffs, bracket
  // row is missing" — reachable any time a row goes missing for any
  // reason, not just this specific recovery case — with no path back.
  // Widened to also allow entry while already in 'playoffs'; the
  // "does a bracket already exist" check right below still makes this a
  // cheap no-op for the normal case (bracket present) that covers the
  // vast majority of playoff-stage syncs.
  if (stage !== 'regular' && stage !== 'playoffs') return; // preseason/offseason — nothing to do
  if (maddenWeekLabelSortKey(newWeekLabel)[0] !== 2) return; // not a playoff week yet

  // Safety net: if a bracket already exists (started manually, or a prior
  // run of this handler that failed after the insert but before the stage
  // flag flip), don't build a second one on top of it — just catch the
  // stage flag up so this stops re-checking every sync.
  const existingBracket = await pool.query(
    `SELECT league_id, bracket FROM league_playoff_brackets WHERE league_id = $1`,
    [league.league_id]
  ).catch(() => ({ rows: [] }));
  if (existingBracket.rows.length) {
    await pool.query(
      `UPDATE madden_league_settings SET current_season_stage = 'playoffs', updated_at = NOW() WHERE league_id = $1`,
      [league.league_id]
    ).catch(() => null);
    // 7J-10BY-PREVIEWRETRY: same fix as the round-advance loop below — the
    // Wild Card preview used to only get attempted at build time, with no
    // retry if that one attempt silently failed. Retries it here too on
    // every sync that finds an already-built bracket, relying entirely on
    // postMaddenPlayoffMatchupPreview's own internal dedup for idempotency.
    const existingFirstRound = Array.isArray(existingBracket.rows[0]?.bracket) ? existingBracket.rows[0].bracket[0] : null;
    if (Array.isArray(existingFirstRound) && existingFirstRound.length) {
      await postMaddenPlayoffMatchupPreview(guild, league, existingFirstRound, 'Wild Card').catch(err =>
        console.error('[SEASON TRANSITION] Wild Card matchup preview retry failed:', err?.message || err));
    }
    return;
  }

  console.log('[SEASON TRANSITION] Playoff week detected for league', league.league_id, stage === 'playoffs' ? '(no existing bracket row — building fresh, recovery path)' : '', '— auto-starting playoff bracket.');
  try {
    // 7J-REALBRACKETMATCHUPS: reads Round 1 directly from EA's real synced
    // Wild Card schedule instead of predicting it — see the function's own
    // comment for why. seriesLengths/buildInitialPlayoffRound are no longer
    // used here.
    const firstRound = await buildMaddenWildCardRoundFromRealGames(guild, league);
    if (firstRound.length < 2) {
      console.warn('[SEASON TRANSITION] Wild Card games not yet synced for league', league.league_id, '— will retry next sync.');
      return; // retry next sync tick rather than flipping the stage on a no-op
    }
    // 7J-NOMADDENBRACKETTHREADS: per Hxxdie — real bug, not a cosmetic
    // duplicate. Madden playoff-week games already get their own native
    // Game Center threads from the regular weekly sync (autoCreateGameThreadsAfterSync
    // runs earlier in the same sync tick, for whatever week_label EA
    // currently reports — including "Wild Card", since EA exports playoff
    // weeks the same way as any other week). createPlayoffSeriesThreads is
    // the structured-league playoff-series thread style (Report Score /
    // Series Score / Best-of-N framing) — calling it here created a second,
    // redundant thread set on top of the real Madden game threads that
    // already existed. This bracket only needs to exist as a visual/embed
    // panel for Madden; the actual games are tracked through the normal
    // Madden sync path, not through series threads.
    const bracket = [firstRound];
    await pool.query(
      `INSERT INTO league_playoff_brackets (league_id, bracket, current_round, status, champion_team, updated_at)
       VALUES ($1, $2, 1, 'in_progress', NULL, NOW())
       ON CONFLICT (league_id) DO UPDATE SET bracket = $2, current_round = 1, status = 'in_progress', champion_team = NULL, channel_id = league_playoff_brackets.channel_id, message_id = league_playoff_brackets.message_id, updated_at = NOW()`,
      [league.league_id, JSON.stringify(bracket)]
    );
    await refreshPlayoffBracketPanel(guild, league).catch(() => null);
    await autoPostPlayoffBracketPanel(guild, league).catch(() => null);
    await postMaddenPlayoffMatchupPreview(guild, league, firstRound, 'Wild Card').catch(err =>
      console.error('[SEASON TRANSITION] Wild Card matchup preview failed:', err?.message || err));
  } catch (error) {
    console.error('[SEASON TRANSITION] Auto playoff bracket start failed:', error?.message || error);
    return; // don't flip the stage flag if it failed — retry next sync tick
  }

  // 7J-ROOKIEAWARDSNAPSHOT: real bug, confirmed live — OROY/DROY determine
  // rookie eligibility off each player's CURRENT years_pro/experience value
  // from madden_players (see isMaddenRookieCandidate / getMaddenLeagueLeaders'
  // join against that table) — a live snapshot, overwritten in place on
  // every roster sync, not season-scoped like the weekly stat totals it's
  // joined against. That's fine while the season is still being played, but
  // by the time year-end finalization actually runs (after the Super Bowl,
  // once the league has moved into offseason), a roster sync may have
  // already reflected the team's NEXT-season state — real rookies who
  // played the whole season now show years_pro=1, so OROY/DROY come back
  // "Not detected" despite having genuinely qualified all season. Playoffs
  // starting is the last point at which every player who has been a rookie
  // all season is still guaranteed to read as one — no further regular-
  // season games remain to change who was actually a rookie this year, and
  // this handler already only fires once per season. Freezing the race
  // winners here, rather than the years_pro values themselves, keeps the
  // fix scoped to exactly the two award categories affected instead of
  // touching every other rookie-status read site in the file.
  //
  // 7J-BRACKETRECOVERY: only take this snapshot on the genuine first-time
  // 'regular' -> 'playoffs' transition, not on a recovery rebuild (stage
  // already 'playoffs', bracket row was missing). A recovery rebuild can
  // happen arbitrarily later than the real transition — re-running this
  // then would overwrite a correct, already-frozen snapshot with current
  // (possibly next-season-drifted) roster data, silently reintroducing the
  // exact bug this snapshot exists to prevent.
  if (stage === 'regular') try {
    const [oroyRows, droyRows] = await Promise.all([
      getMaddenAwardsRace(guild.id, league.league_id, 'oroy', 1).catch(() => []),
      getMaddenAwardsRace(guild.id, league.league_id, 'droy', 1).catch(() => []),
    ]);
    const snapshot = {};
    if (oroyRows[0]) snapshot.oroy = oroyRows[0];
    if (droyRows[0]) snapshot.droy = droyRows[0];
    if (Object.keys(snapshot).length) {
      await pool.query(
        `UPDATE madden_league_settings SET rookie_award_snapshot = $2, updated_at = NOW() WHERE league_id = $1`,
        [league.league_id, JSON.stringify(snapshot)]
      ).catch(err => console.error('[SEASON TRANSITION] Rookie award snapshot failed to save:', err?.message || err));
    }
  } catch (error) {
    console.error('[SEASON TRANSITION] Rookie award snapshot failed:', error?.message || error);
    // Non-fatal — year-end finalization falls back to a live (possibly
    // stale) rookie check if this snapshot never got taken.
  }

  await pool.query(
    `UPDATE madden_league_settings SET current_season_stage = 'playoffs', updated_at = NOW() WHERE league_id = $1`,
    [league.league_id]
  ).catch(() => null);
  console.log('[SEASON TRANSITION] Playoff bracket auto-start complete for league', league.league_id);
}

// 7J-MADDENBRACKETADVANCE: per Hxxdie — the piece handleMaddenPlayoffBracketTransition
// was explicitly missing. Structured leagues advance their bracket
// (winsA/winsB/winner, next-round generation, champion) exclusively through
// the "Report Score" button inside a series thread — see
// recordPlayoffGameResult. Madden playoff games don't have series threads
// (7J-NOMADDENBRACKETTHREADS — they get real Game Center threads from the
// normal weekly sync instead), so nothing was ever feeding real results
// into the bracket JSON. This is that missing feed: for the bracket's
// CURRENT round, looks up each still-undecided series' real EA-synced game
// (matched by week_label + team names) and, once every series in the round
// has a winner, either builds the next round (reusing buildNextPlayoffRound
// — the same real NFL reseed logic the structured-league path already
// trusts) or marks the bracket completed with a champion. Deliberately
// does NOT grant any championship award/currency here — Madden already has
// its own Super-Bowl-triggered payout pipeline (getMaddenSuperBowlResult +
// handleMaddenOffseasonTransition + buildMaddenYearEndPrepEmbed), and
// duplicating that here would risk double-paying the champion. This
// function's only job is keeping the bracket's visual/embed state correct.
async function syncMaddenPlayoffBracketFromResults(guild, league) {
  if (getPlayoffFormatKey(league) !== 'nfl') return;

  // 7J-10BY-COMPLETEDBRACKETRETRY: real gap, confirmed live — the previous
  // preview-retry fix only runs while bracketState.status === 'in_progress'
  // (below). Confirmed live: the Super Bowl round can get built AND
  // decided within the SAME sync (a catch-up pass that reaches Super Bowl
  // for the first time with the game already complete), collapsing its
  // retry window to a single pass — completely unlike every earlier round,
  // which gets many sync-cycles of retry opportunity while still
  // 'in_progress'. Once status flips to 'completed', the function's own
  // stage/status gates below block it forever, so a missed Super Bowl
  // preview had zero remaining chances to retry, ever. Checked here,
  // before either of those gates, specifically for this one case: the
  // FINAL round only (never intermediate rounds — those had their normal
  // in-progress retry window already).
  //
  // 7J-FINALPREVIEWFLAG: real bug, confirmed live — this used to rely
  // solely on postMaddenPlayoffMatchupPreview's own dedup
  // (madden_storyline_posts) to stay a no-op once already posted. That
  // table gets deliberately wiped clean for the whole league the moment
  // the Super Bowl finalizes (7J-10BY-STORYLINERESET, for next season's
  // stories) — which also erased THIS preview's "already posted" record,
  // and this retry (running every single sync forever once completed)
  // reposted the identical Super Bowl preview right after. Gated on the
  // bracket row's own final_preview_posted flag instead — this is about
  // this specific bracket's lifecycle, unaffected by a table that resets
  // for unrelated reasons.
  const completedBracketCheck = await pool.query(
    `SELECT bracket, status, final_preview_posted FROM league_playoff_brackets WHERE league_id = $1`,
    [league.league_id]
  ).catch(() => ({ rows: [] }));
  const completedBracketState = completedBracketCheck.rows[0];
  if (completedBracketState?.status === 'completed') {
    const finishedBracket = Array.isArray(completedBracketState.bracket) ? completedBracketState.bracket : [];
    const finalRoundIndex = finishedBracket.length - 1;
    const finalRound = finishedBracket[finalRoundIndex];
    if (!completedBracketState.final_preview_posted && Array.isArray(finalRound) && finalRound.length) {
      const finalRoundLabel = tournamentBracketRoundLabel(finalRoundIndex + 1, 4, finalRoundIndex, 'nfl');
      const posted = await postMaddenPlayoffMatchupPreview(guild, league, finalRound, finalRoundLabel).catch(err => {
        console.error('[MADDEN BRACKET] Completed-bracket preview retry for', finalRoundLabel, 'failed:', err?.message || err);
        return false;
      });
      if (posted) {
        await pool.query(
          `UPDATE league_playoff_brackets SET final_preview_posted = TRUE, updated_at = NOW() WHERE league_id = $1`,
          [league.league_id]
        ).catch(() => null);
      }
    }
    return;
  }

  const settings = await ensureMaddenLeagueSettings(league);
  if ((settings.current_season_stage || 'preseason') !== 'playoffs') return; // only relevant mid-playoffs

  const bracketResult = await pool.query(`SELECT * FROM league_playoff_brackets WHERE league_id = $1`, [league.league_id]).catch(() => ({ rows: [] }));
  const bracketState = bracketResult.rows[0];
  if (!bracketState || bracketState.status !== 'in_progress') return;

  const bracket = Array.isArray(bracketState.bracket) ? bracketState.bracket : [];
  let currentRoundNum = Number(bracketState.current_round || 1);
  let currentStatus = bracketState.status;

  // 7J-BRACKETCATCHUPLOOP: real bug, confirmed live — the previous
  // single-pass version processed at most ONE round per call: it would
  // decide the current round, build the next round's shell, and return —
  // never checking whether that freshly-built round's game was *already*
  // finished. That's exactly what happens when a sync jumps straight past
  // a round that got stuck (e.g. Conference Championship sat undetected
  // for a tick, and by the time it's caught up the Super Bowl itself has
  // already been played). Worse, `current_season_stage` flips to
  // 'offseason' later in this SAME outer sync (via
  // handleMaddenOffseasonTransition, driven independently off
  // getMaddenSuperBowlResult — unaffected by this table). Once that flips,
  // this function's own stage gate above blocks it on every future call,
  // so a round built-but-unresolved here would stay stuck forever with no
  // winner/champion ever recorded in league_playoff_brackets. Fix: loop
  // and keep advancing — build a round, immediately check whether it's
  // already decided too, and keep going — until there's genuinely nothing
  // left to do, all within this one call.
  for (let iteration = 0; iteration < 5; iteration++) {
    const roundIndex = currentRoundNum - 1;
    if (roundIndex > 3) break; // shouldn't happen — real NFL bracket is always exactly 4 rounds
    const roundSeries = bracket[roundIndex];
    if (!roundSeries || !roundSeries.length) break;

    // 7J-BRACKETREALCHECK: per Hxxdie — replaces the old guess-based reseed
    // correction (7J-BRACKETRESEED), which tried to fix a wrong matchup by
    // recomputing seeding and swapping in "whichever team should be at this
    // seed" — a second and third attempt at the same underlying guess that
    // still didn't match what actually happened live (see
    // buildMaddenWildCardRoundFromRealGames's comment for the full story).
    // This instead compares the bracket's current round against a freshly
    // rebuilt version straight from real synced games. If they don't match,
    // the whole round is replaced wholesale — simpler and safer than
    // patching individual series, and it cannot reproduce the old
    // wrong-conference bug since there's no seed-number lookup involved at
    // all anymore. Any previously-recorded result against a since-corrected
    // matchup is discarded along with it — the results-processing loop
    // right below this will immediately re-attach the real result for the
    // corrected matchup on this same sync.
    //
    // Only run this check on the round we STARTED this call at (iteration
    // 0). Rounds built later in this same loop came straight out of
    // buildMaddenNextRoundFromRealGames already — re-verifying them against
    // themselves is redundant work, not a correctness need.
    if (iteration === 0) {
      const realRound = roundIndex === 0
        ? await buildMaddenWildCardRoundFromRealGames(guild, league).catch(() => [])
        : await buildMaddenNextRoundFromRealGames(guild, league, bracket[roundIndex - 1] || [], maddenBracketRoundToWeekIdx(roundIndex)).catch(() => []);
      if (realRound.length >= 2) {
        const pairKey = (s) => s.bye ? `bye:${s.teamA.name.toLowerCase()}` : [s.teamA.name.toLowerCase(), s.teamB.name.toLowerCase()].sort().join('|');
        const currentKeys = roundSeries.map(pairKey);
        const realKeys = realRound.map(pairKey);
        const matches = currentKeys.length === realKeys.length && currentKeys.every((k, i) => k === realKeys[i]);
        if (!matches) {
          console.log('[MADDEN BRACKET] Round', currentRoundNum, 'did not match real synced games for league', league.league_id, '— replacing with real matchups.');
          bracket[roundIndex] = realRound;
          roundSeries.length = 0;
          roundSeries.push(...realRound);
          await pool.query(`UPDATE league_playoff_brackets SET bracket = $2, updated_at = NOW() WHERE league_id = $1`, [league.league_id, JSON.stringify(bracket)]).catch(() => null);
          await refreshPlayoffBracketPanel(guild, league).catch(() => null);
        }
      }
    }

    // 7J-10BY-PREVIEWRETRY2: real gap in the previous preview-retry fix,
    // caught before it could repeat the Div/Conf miss for Super Bowl —
    // that fix only retried a round's preview at the moment of TRANSITION
    // into it (advancing from the prior round). Once current_round has
    // already moved past that transition, every later sync starts this
    // loop already sitting AT the current round and, if it's not decided
    // yet, breaks out immediately without ever reaching that transition
    // code again — so a preview missed at build time would never retry
    // while the round sits undecided, only once genuinely re-entered
    // (which mostly never happens). Retries THIS round's preview every
    // single sync while it's active, relying entirely on the internal
    // dedup for idempotency — so a missed preview retries on every sync
    // until it succeeds, not just once. Placed AFTER the correctness check
    // above (not before) so it always previews the corrected matchups, not
    // stale ones about to be replaced.
    const activeRoundLabel = tournamentBracketRoundLabel(roundIndex + 1, 4, roundIndex, 'nfl');
    await postMaddenPlayoffMatchupPreview(guild, league, roundSeries, activeRoundLabel).catch(err =>
      console.error('[MADDEN BRACKET] Active-round preview retry for', activeRoundLabel, 'failed:', err?.message || err));

    let mutated = false;
    for (const series of roundSeries) {
      if (series.bye || series.winner || !series.teamB) continue;
      // 7J-DIVPLAYOFFFIX2: per Hxxdie — this used to match week_label against
      // a hardcoded guess ('Divisional', etc.), which silently never matched
      // anything once EA's real label turned out to be "Div. Playoff"
      // instead. Now pulls every candidate completed game for this matchup
      // and confirms the round via maddenWeekLabelSortKey — the same real
      // classification the rest of the auto-detect pipeline already relies
      // on — instead of requiring an exact label string this codebase can't
      // fully verify for every round.
      //
      // 7J-BRACKETSWEEPSEASONSCOPE: real gap, same shape as
      // 7J-BRACKETSEASONSCOPE earlier this session — this matches purely by
      // team pair + round type, with no season_key filter. Narrower risk
      // than the original bug (needs the exact same two teams to have met
      // in the exact same round type across two different seasons to
      // misfire), but the same underlying hazard: madden_imported_games
      // never stops accumulating past seasons' games. Scoped for
      // consistency and to close this out properly rather than leave one
      // instance of the pattern unfixed.
      const seasonKeyForRoundCheck = await getMaddenCurrentSeasonKey(league).catch(() => null);
      const gameResult = await pool.query(
        `SELECT week_label, home_team, away_team, home_score, away_score, status
         FROM madden_imported_games
         WHERE guild_id = $1 AND league_id::text = $2::text
           AND season_key = $3::text
           AND ((LOWER(home_team) = LOWER($4) AND LOWER(away_team) = LOWER($5)) OR (LOWER(home_team) = LOWER($5) AND LOWER(away_team) = LOWER($4)))
           AND LOWER(COALESCE(status, '')) IN ('completed', 'final', 'completed_with_real_score', 'away_win', 'home_win', 'tie')
         ORDER BY imported_at DESC`,
        [guild.id, String(league.league_id), seasonKeyForRoundCheck, series.teamA.name, series.teamB.name]
      ).catch(() => ({ rows: [] }));
      const game = (gameResult.rows || []).find(g => {
        const [group, idx] = maddenWeekLabelSortKey(g.week_label);
        return group === 2 && idx === maddenBracketRoundToWeekIdx(roundIndex);
      });
      if (!game) continue; // not played/synced yet — check again next sync

      const homeScore = Number(game.home_score) || 0;
      const awayScore = Number(game.away_score) || 0;
      let winningTeamName = null;
      if (homeScore !== awayScore) {
        winningTeamName = homeScore > awayScore ? game.home_team : game.away_team;
      } else {
        // No real score difference (e.g. a fallback-flag-resolved win with no
        // raw score at all — see 7J-47PPG) — fall back to the same
        // status-encoded winner every other completion check in this
        // codebase already trusts, rather than guessing or leaving a
        // single-elimination series stuck forever on an ambiguous 0-0.
        const lowerStatus = String(game.status || '').toLowerCase();
        if (lowerStatus === 'home_win') winningTeamName = game.home_team;
        else if (lowerStatus === 'away_win') winningTeamName = game.away_team;
      }
      if (!winningTeamName) continue; // genuinely unresolved — retry next sync

      const winnerIsA = String(winningTeamName).toLowerCase() === String(series.teamA.name).toLowerCase();
      series.winsA = winnerIsA ? 1 : 0;
      series.winsB = winnerIsA ? 0 : 1;
      series.winner = winnerIsA ? series.teamA.name : series.teamB.name;
      mutated = true;
      const currentRoundLabel = tournamentBracketRoundLabel(roundIndex + 1, 4, roundIndex, 'nfl');
      await postMaddenPlayoffUpsetAlert(guild, league, series, currentRoundLabel).catch(err =>
        console.error('[MADDEN BRACKET] Upset alert check failed:', err?.message || err));
    }

    // 7J-BRACKETSTUCKROUND: real bug, confirmed live — a round whose series
    // already all had winners (from an earlier tick) was invisible to the
    // `mutated` flag above, since the per-series loop skips anything that
    // already has a winner. Without this, a round stuck between "fully
    // decided" and "next round built" (or, for the last round, between
    // "decided" and "marked completed") would never get picked back up.
    // Detect that state explicitly instead of relying solely on `mutated`.
    const roundAlreadyComplete = roundSeries.every(s => s.bye || s.winner);
    const isFinalRoundCandidate = roundSeries.length === 1;
    const needsAdvanceRetry = roundAlreadyComplete && !isFinalRoundCandidate && !bracket[roundIndex + 1];
    const needsFinalizeRetry = roundAlreadyComplete && isFinalRoundCandidate && currentStatus !== 'completed';
    if (!mutated && !needsAdvanceRetry && !needsFinalizeRetry) break; // genuinely nothing to do — stop looping

    const roundComplete = roundSeries.every(s => s.bye || s.winner);
    if (!roundComplete) {
      bracket[roundIndex] = roundSeries;
      await pool.query(`UPDATE league_playoff_brackets SET bracket = $2, updated_at = NOW() WHERE league_id = $1`, [league.league_id, JSON.stringify(bracket)]).catch(() => null);
      await refreshPlayoffBracketPanel(guild, league).catch(() => null);
      break;
    }

    const isFinalRound = roundSeries.length === 1;
    if (isFinalRound) {
      const champion = roundSeries[0].winner;
      bracket[roundIndex] = roundSeries;
      await pool.query(
        `UPDATE league_playoff_brackets SET bracket = $2, status = 'completed', champion_team = $3, updated_at = NOW() WHERE league_id = $1`,
        [league.league_id, JSON.stringify(bracket), champion]
      ).catch(() => null);
      currentStatus = 'completed';
      console.log('[MADDEN BRACKET] Champion decided for league', league.league_id, ':', champion);
      await refreshPlayoffBracketPanel(guild, league).catch(() => null);
      break; // nothing more to advance to — done
    }

    // 7J-REALBRACKETMATCHUPS: reads the next round from EA's real synced
    // schedule instead of predicting it via a reseed formula — see
    // buildMaddenNextRoundFromRealGames's comment. If EA hasn't exported
    // this round's schedule yet even though the previous round is fully
    // decided, wait and retry rather than advancing into an empty round.
    const nextRound = bracket[roundIndex + 1]?.length
      ? bracket[roundIndex + 1] // already built by a previous tick — just move into it
      : await buildMaddenNextRoundFromRealGames(guild, league, roundSeries, maddenBracketRoundToWeekIdx(roundIndex + 1));
    if (!nextRound.length) {
      bracket[roundIndex] = roundSeries;
      await pool.query(`UPDATE league_playoff_brackets SET bracket = $2, updated_at = NOW() WHERE league_id = $1`, [league.league_id, JSON.stringify(bracket)]).catch(() => null);
      await refreshPlayoffBracketPanel(guild, league).catch(() => null);
      console.log('[MADDEN BRACKET] Round', currentRoundNum, 'complete for league', league.league_id, '— next round not yet synced by EA, will retry.');
      break;
    }
    const alreadyHadNextRound = !!bracket[roundIndex + 1]?.length;
    bracket[roundIndex] = roundSeries;
    if (!alreadyHadNextRound) bracket.push(nextRound);
    await pool.query(
      `UPDATE league_playoff_brackets SET bracket = $2, current_round = $3, updated_at = NOW() WHERE league_id = $1`,
      [league.league_id, JSON.stringify(bracket), currentRoundNum + 1]
    ).catch(() => null);
    // 7J-10BY-PREVIEWRETRY: real bug, confirmed live — this used to only
    // attempt postMaddenPlayoffMatchupPreview inside the `!alreadyHadNextRound`
    // branch, meaning it had exactly ONE chance to succeed, ever, for a
    // given round: the single sync where the round was first built into
    // the bracket JSON. If that one attempt silently failed for any reason
    // (confirmed live: a stale storyline dedup entry from an earlier test
    // season), there was no way to retry — alreadyHadNextRound is
    // permanently true from that point on, so the outer gate could never
    // open again for that round, even after the underlying dedup problem
    // was fixed. Now calls it every time this round is processed,
    // regardless of alreadyHadNextRound, relying entirely on
    // postMaddenPlayoffMatchupPreview's OWN internal dedup (shouldPostMaddenStoryline)
    // to guarantee it only actually posts once — which also means a
    // transient failure of any kind now self-heals on the next sync
    // instead of being silently permanent.
    const nextRoundLabel = tournamentBracketRoundLabel(roundIndex + 2, 4, roundIndex + 1, 'nfl');
    await postMaddenPlayoffMatchupPreview(guild, league, nextRound, nextRoundLabel).catch(err =>
      console.error('[MADDEN BRACKET] Matchup preview for', nextRoundLabel, 'failed:', err?.message || err));
    console.log('[MADDEN BRACKET] Round', currentRoundNum, 'complete for league', league.league_id, '— advanced to round', currentRoundNum + 1);
    await refreshPlayoffBracketPanel(guild, league).catch(() => null);
    currentRoundNum += 1;
    // loop continues — immediately check whether the round we just moved
    // into is *also* already decided (e.g. Super Bowl already played by
    // the time a stuck earlier round got caught up).
  }
}

async function handleMaddenSeasonTransition(guild, league, previousWeekLabel, newWeekLabel) {
  if (!previousWeekLabel || !newWeekLabel) return;
  const wasPreseason = maddenIsPreseasonWeek(previousWeekLabel);
  const isRegular = maddenIsRegularSeasonWeek(newWeekLabel);
  // 7J-CUTWEEKLABELCOLLISION: real bug, confirmed live (Session 44 continued
  // 18) — wasPreseason alone isn't enough to catch every real preseason ->
  // regular transition any more. The 7J-CUTWEEKLABELCOLLISION recovery in
  // getMaddenNewAdvanceWeek can now return a genuine "Week N" advance even
  // when previousWeekLabel is ALSO "Week N" (the poisoned, already-stored
  // label from EA reporting the real week's text prematurely, before real
  // Week 1 games existed) — in that exact recovery case, previousWeekLabel
  // is "Week 1", not "Preseason Week 3", so wasPreseason evaluates false
  // and this function would silently no-op, exactly the way it did live:
  // the detector correctly recognized the advance, but the actual kickoff
  // (stat wipe, trade count reset, bracket delete, power ranking reset,
  // thread cleanup, new threads, the announcement) never fired because
  // THIS function's own gate was still looking at label sequence alone.
  // Falls back to checking current_season_stage directly — if it's still
  // 'preseason' despite newWeekLabel being a genuine regular week, that's
  // just as reliable a signal as wasPreseason ever was (the league cannot
  // legitimately be in 'preseason' stage while a real "Week N" is the
  // confirmed current week), and covers this recovery path without
  // requiring a trustworthy previousWeekLabel at all.
  let qualifies = wasPreseason;
  if (!qualifies && isRegular) {
    const stageSettings = await ensureMaddenLeagueSettings(league).catch(() => ({}));
    qualifies = (stageSettings.current_season_stage || 'preseason') === 'preseason';
    if (qualifies) {
      console.log('[SEASON TRANSITION] previousWeekLabel ("' + previousWeekLabel + '") didn\'t look like preseason, but current_season_stage is still \'preseason\' — treating as the same recovery case getMaddenNewAdvanceWeek already handled.');
    }
  }
  if (!qualifies || !isRegular) return;

  // EA keeps preseason games as 'scheduled' forever after advancing past them —
  // they never update statuses. Since EA only exports current-week games, the
  // mere appearance of regular season Week 1 in the DB confirms we've advanced.
  console.log('[SEASON TRANSITION] Preseason → Regular Season confirmed for league', league.league_id);
  await performMaddenRegularSeasonKickoff(guild, league, newWeekLabel);
}


// ---------------------------------------------------------------------------
// Master orchestrator — called at the end of every sync
// Replaces the existing autoCreateGameThreadsAfterSync pattern by
// wrapping it and adding all the new detection on top.
// ---------------------------------------------------------------------------
// 7J-AUTODETECTLOCK: real bug, confirmed live — a manual Run Sync and the
// scheduled background autosync (runDueMaddenAutosyncs) both call this
// function independently, with no coordination between them. Retirement/
// transaction detection now runs unconditionally every sync (see
// 7J-OFFSEASONGATEFIX above) rather than being gated behind a week-advance
// check, which widened the window for both to land within the same minute.
// scanMaddenOffseasonTransactions' dedup relies on reading the "previous"
// snapshot, then later writing the new one back — if two calls overlap,
// both can read the same stale snapshot before either writes, both see the
// same signing as new, and both post their own news event. Confirmed live:
// a single Brandon Aubrey signing posted twice, same minute. Simple
// per-league in-memory lock — a second call for the same league while one
// is still in flight is skipped rather than run concurrently, and retried
// naturally on the next tick instead.
const maddenAutoDetectInFlightLeagues = new Set();

async function autoDetectAfterSync(guild, league) {
  const lockKey = String(league.league_id);
  if (maddenAutoDetectInFlightLeagues.has(lockKey)) {
    console.log(`[AUTO DETECT] Already in progress for league ${lockKey} — skipping this overlapping call.`);
    return { advanced: false, weekLabel: null, skipped: 'already_in_progress' };
  }
  maddenAutoDetectInFlightLeagues.add(lockKey);
  try {
    return await autoDetectAfterSyncInner(guild, league);
  } finally {
    maddenAutoDetectInFlightLeagues.delete(lockKey);
  }
}

async function autoDetectAfterSyncInner(guild, league) {
  await ensureMaddenAutoDetectColumns();

  // Runs every sync, independent of whether the week as a whole has advanced —
  // an individual user can finish their own game well before everyone else in
  // the week has played (confirmed: a user-controlled team beating a CPU team,
  // not CPU-vs-CPU auto-sim as originally assumed), and that game's bets need to
  // settle the moment it's actually done, not sit open until the whole week's
  // advance is detected, possibly days later. Safe to call unconditionally
  // thanks to the idempotency guard inside autoSettleMaddenSportsbookBet.
  await autoSettleCompletedMaddenSportsbookGames(guild, league).catch(err =>
    console.error('[AUTO DETECT] Per-game sportsbook settlement:', err?.message));
  // 7J-50MADDENREWARD: same every-sync safety pattern as the sportsbook pass
  // above — its own idempotency guard (rewards_paid_at) makes repeat calls
  // harmless, so this runs unconditionally too rather than waiting for a
  // full week-advance.
  await autoDistributeCompletedMaddenGameRewards(guild, league).catch(err =>
    console.error('[AUTO DETECT] Per-game reward distribution:', err?.message));

  // 7J-PLAYOFFBRACKETCATCHUP: per Hxxdie — handleMaddenPlayoffBracketTransition
  // is also reachable via the newWeekLabel edge-trigger further below, but
  // that only fires on the ONE sync where the week actually changes. If this
  // feature's deploy lands after a league has already advanced into a
  // playoff week (EA reports the same week on every subsequent sync from
  // then on), that edge event has already been consumed and won't fire
  // again this season — silently leaving the bracket unposted for the rest
  // of the playoffs with no further chance to self-correct. Runs
  // unconditionally every sync instead, using EA's raw reported current
  // week rather than the edge-triggered "new advance" value, so a league
  // already sitting in a playoff week still gets caught. Safe to call every
  // sync thanks to handleMaddenPlayoffBracketTransition's own stage and
  // existing-bracket guards — same "idempotent, so call it unconditionally"
  // pattern as the sportsbook/reward passes just above.
  const eaCurrentWeekSettings = await ensureMaddenLeagueSettings(league).catch(() => ({}));
  if (eaCurrentWeekSettings.ea_reported_current_week) {
    await handleMaddenPlayoffBracketTransition(guild, league, eaCurrentWeekSettings.ea_reported_current_week).catch(err =>
      console.error('[AUTO DETECT] Playoff bracket catch-up check failed:', err?.message));
  }

  // 7J-MADDENBRACKETADVANCE: runs every sync, same reasoning as the
  // sportsbook/reward passes above — playoff games complete at different
  // times throughout the week just like regular season games, not all at
  // once, so this can't wait for a full week-advance. Safe to call
  // unconditionally thanks to syncMaddenPlayoffBracketFromResults' own
  // stage/status guards and the fact that it only ever acts on series that
  // don't already have a winner set.
  await syncMaddenPlayoffBracketFromResults(guild, league).catch(err =>
    console.error('[AUTO DETECT] Playoff bracket result sync failed:', err?.message));

  // 7J-DRAFTRECAPTIMING: see checkAndPostMaddenDraftRecap's own comment —
  // posts the moment a real draft class appears rather than waiting all
  // the way until preseason exhibition games conclude. Own dedup guard
  // (shouldPostMaddenStoryline) makes this safe to call every sync.
  await checkAndPostMaddenDraftRecap(guild, league).catch(err =>
    console.error('[AUTO DETECT] Draft recap check failed:', err?.message));

  // 7J-OFFSEASONGATEFIX: real bug, confirmed live — retirement and
  // transaction detection (and the weekly updates digests/news they drive)
  // silently stopped firing for an entire offseason. Root cause: both used
  // to live below the newWeekLabel gate further down, which only opens when
  // EA's own reported "current week" (ea_reported_current_week, sourced
  // from the hub's displayedWeek field) actually changes. That field
  // tracks real season weeks — it has no concept of offseason SUB-stages
  // (Resign Players, Free Agency Preview, Free Agency Stage 1, Stage 2,
  // etc.), so it can report the exact same value across several real
  // offseason advances in a row. The gate never opened, so retirements,
  // signings, and the "who just moved" news recap all silently went dark
  // the moment the season ended — exactly matching what was seen live:
  // a wave of Free Agency Stage 2 signings produced zero weekly updates.
  // Moved here so both run every sync regardless of week-label staleness,
  // same reasoning and same idempotency-guard safety as the sportsbook/
  // reward/bracket passes above — scanMaddenRetirements' retirement_key
  // unique constraint and scanMaddenOffseasonTransactions' snapshot-diff
  // approach both already make repeat calls harmless.
  const retirements = await autoDetectMaddenRetirements(guild, league).catch(() => []);
  const transactionEvents = await autoDetectMaddenTransactions(guild, league).catch(err => {
    console.error('[AUTO DETECT] Transactions:', err?.message);
    return [];
  });
  const majorMovementEvents = (transactionEvents || []).filter(e => e.type === 'major_movement');
  // Fires the same "big splashy signing/release" AI news recap the
  // regular-season path below also generates from allEvents — offseason
  // free agency is exactly when this matters most (a 90+ OVR player
  // signing is genuinely headline news), and it was previously unreachable
  // all offseason for the same reason as above.
  if (majorMovementEvents.length > 0) {
    await generateMaddenESPNNews(guild, league, majorMovementEvents, eaCurrentWeekSettings.ea_reported_current_week || null, null).catch(err =>
      console.error('[AUTO DETECT] Offseason transaction news:', err?.message));
  }

  // 7J-10BY-CATCHUPLOOP: per Hxxdie — a league that advances many real
  // weeks in Madden between syncs (e.g. straight to Week 15 without
  // syncing along the way) used to require one manual sync per missed
  // week, because getMaddenNewAdvanceWeek deliberately caps to one step
  // forward at a time (see its own comment — that cap is a real, hard-won
  // safety property from three earlier rounds of this logic being wrong in
  // production, and stays exactly as-is). Rather than remove that safety
  // cap, this loops it automatically within a single sync instead of
  // requiring repeated manual syncs — each step is still the same proven
  // single-week advance, just chained.
  //
  // Two passes on purpose:
  // Pass 1 discovers the FULL sequence of missed weeks by repeatedly
  // calling the existing, unmodified single-step detector and advancing
  // the anchor each time — this is the exact same mechanism a human
  // manually re-syncing 13 times would trigger, just automatic. Knowing
  // the whole sequence up front is what lets pass 2 below tell which week
  // is the real current one vs. a historical catch-up week, without any
  // lookahead trickery.
  // Pass 2 processes each discovered week individually — its own results,
  // streaks, news, retirements, standings — exactly as if each had been
  // synced separately in sequence, per Hxxdie's explicit ask. Only the
  // FINAL (most current) week gets game threads and sportsbook lines/
  // props: per Hxxdie, a catch-up week is by definition already fully
  // decided by the time the bot reaches it, so a thread inviting people to
  // schedule a game that's already over, or a betting line on a result
  // that already happened, is meaningless and would just spam dead
  // threads/lines across every historical week.
  //
  // Trade-off, stated plainly: the original single-week design marked a
  // week processed only as the very last step, specifically so a mid-run
  // crash would retry that whole week on the next sync. Pass 1 here
  // advances the anchor for ALL discovered weeks up front, before pass 2's
  // heavier processing runs for each — so a crash partway through pass 2
  // (rare: this only runs at all when catching up more than one week)
  // could leave a historical week's news/streaks processing incomplete
  // without retrying it automatically. Threads/lines for the final week
  // are unaffected (pass 2 still runs those in order, and the final week
  // is always processed since it's last in the list) — the risk is
  // narrowly scoped to historical catch-up weeks' informational
  // recaps, not to anything player-facing like threads or money.
  // 7J-10BY-CATCHUPLOOPFIX: real bug, confirmed live — the original
  // two-pass design (discover the FULL week list first, process second)
  // assumed detecting "the next week" is a pure function of DB state that
  // doesn't depend on side effects from processing earlier-discovered
  // weeks. That assumption breaks for exactly one real scenario: the
  // 7J-POSTPLAYOFFWEEKFIX2 "Pro Bowl" safe-label override only stops
  // firing once current_season_stage flips away from 'playoffs' — which
  // only happens via handleMaddenOffseasonTransition's Super Bowl finalize,
  // a PROCESSING-time side effect. Under the two-pass design, that side
  // effect lived in pass 2, which never got a chance to run until pass 1's
  // pure-detection loop finished — but pass 1 could never finish on its
  // own here, since nothing in a detection-only loop can ever flip the
  // stage. Confirmed live: this produced a real infinite-loop-shaped bug,
  // stuck re-detecting "Pro Bowl" as the new week 20 times in a row (the
  // safety cap) without ever reaching Super Bowl or the new season's real
  // Week 1. Single pass now, with a 1-step lookahead: each week's
  // season-transition handlers run IMMEDIATELY as it's discovered, before
  // the next detection call — so a stage flip takes effect right away
  // instead of being deferred behind an entire batch. Threads/sportsbook
  // lines still only fire for the confirmed-final week, via the lookahead
  // (a week is only known to be non-final once a NEWER week is discovered
  // after it) — same behavior as before, different mechanism.
  const MADDEN_CATCHUP_MAX_WEEKS_PER_SYNC = 20; // full-season safety cap, not a practical limit
  const preLoopSettings = await ensureMaddenLeagueSettings(league);
  let previousWeekLabelForLoop = preLoopSettings.last_auto_detect_week_label || null;

  const allEvents = [];
  const weeksSeen = [];
  let pending = null; // { weekLabel, previousWeekLabel } — most recently discovered week, held back until confirmed final

  // Finishes the non-transition parts of one week's processing (threads/
  // lines only when isFinalWeek). Season-transition handlers are NOT
  // called here — they already ran immediately at discovery time, above.
  const finishMaddenCatchupWeek = async (weekLabel, prevWeekLabel, isFinalWeek) => {
    const weekEvents = [];
    console.log(`[AUTO DETECT] Processing ${weekLabel} for league ${league.league_id}` + (isFinalWeek ? ' (current week)' : ' (catch-up week)'));

    if (isFinalWeek) {
      await autoCreateGameThreadsAfterSync(guild, league, weekLabel).catch(err =>
        console.error('[AUTO DETECT] Game thread creation failed:', err?.message || err));
    } else {
      console.log(`[AUTO DETECT] Skipping game threads for ${weekLabel} — already-decided catch-up week, not the current one.`);
    }

    const gameOfWeek = await selectMaddenGameOfTheWeek(guild, league, weekLabel).catch(() => null);
    if (gameOfWeek) weekEvents.push(gameOfWeek);

    const gameEvents = await autoProcessMaddenGameResults(guild, league, weekLabel).catch(() => []);
    weekEvents.push(...gameEvents);

    // 7J-PRESEASONTHREADSENABLE: threads/results/news now run for preseason
    // weeks same as any other week (see the gate removal above), but
    // sportsbook lines/props are deliberately kept out of preseason —
    // Hxxdie asked specifically for game threads, not betting lines on
    // exhibition games, and this is the one piece with real-money
    // implications, so it stays opt-in rather than silently inherited
    // from a broader fix. Checked directly off the week label, not
    // current_season_stage, so it can't be thrown off by the exact
    // handoff timing between "Preseason Week 3" and the stage flag
    // flipping to 'regular'.
    const isPreseasonWeekForBetting = maddenIsPreseasonWeek(weekLabel);
    if (isFinalWeek && !isPreseasonWeekForBetting) {
      await autoCreateMaddenSportsbookLines(guild, league, weekLabel).catch(err =>
        console.error('[AUTO DETECT] Sportsbook lines:', err?.message));
      await generateMaddenPlayerPropLines(guild, league, weekLabel).catch(err =>
        console.error('[AUTO DETECT] Player prop lines:', err?.message));
    } else if (isPreseasonWeekForBetting) {
      console.log(`[AUTO DETECT] Skipping sportsbook lines/props for ${weekLabel} — preseason, betting lines not enabled for exhibition games.`);
    } else {
      console.log(`[AUTO DETECT] Skipping sportsbook lines/props for ${weekLabel} — already-decided catch-up week.`);
    }

    await autoSettleOpenStatProps({ guild, user: { id: 'system' } }, league, { confirm: true }).catch(err =>
      console.error('[AUTO DETECT] Stat prop settlement:', err?.message));

    if (weekEvents.length > 0) {
      await generateMaddenESPNNews(guild, league, weekEvents, weekLabel, prevWeekLabel).catch(err =>
        console.error('[AUTO DETECT] ESPN news:', err?.message));
    }
    allEvents.push(...weekEvents);
  };

  for (let iteration = 0; iteration < MADDEN_CATCHUP_MAX_WEEKS_PER_SYNC; iteration++) {
    const newWeekLabel = await getMaddenNewAdvanceWeek(guild.id, league.league_id);
    if (!newWeekLabel) break;

    // 7J-10BY-STUCKANCHORGUARD: defensive backstop, not the primary fix
    // (that's the sort-key correction and the immediate-transition restructure
    // above) — if getMaddenNewAdvanceWeek ever returns the exact same label
    // twice in a row despite the anchor having just advanced, that's a clear
    // signal of a stuck-anchor bug of some kind, known or not yet found.
    // Stops immediately and logs loudly instead of silently grinding to the
    // safety cap the way the Pro Bowl bug did.
    if (pending && newWeekLabel === pending.weekLabel) {
      console.error(`[AUTO DETECT] League ${league.league_id} — getMaddenNewAdvanceWeek returned "${newWeekLabel}" twice in a row despite the anchor advancing. Stopping catch-up here rather than looping — this needs investigation.`);
      break;
    }

    // The previously-pending week is now confirmed NOT final, since a
    // newer one was just discovered — finish its (non-final) processing.
    if (pending) {
      await finishMaddenCatchupWeek(pending.weekLabel, pending.previousWeekLabel, false);
    }

    console.log(`[AUTO DETECT] New week detected: ${newWeekLabel} for league ${league.league_id}`);

    // Season-transition side effects run IMMEDIATELY — before the next
    // detection call above — so a stage flip (e.g. Super Bowl finalize)
    // takes effect right away instead of being deferred behind a whole
    // pre-discovered batch. This is the actual fix for the stuck-loop bug.
    await handleMaddenSeasonTransition(guild, league, previousWeekLabelForLoop, newWeekLabel).catch(err =>
      console.error('[AUTO DETECT] Season transition handler failed:', err?.message));
    await handleMaddenOffseasonTransition(guild, league, newWeekLabel).catch(err =>
      console.error('[AUTO DETECT] Offseason transition handler failed:', err?.message));

    await markMaddenAdvanceProcessed(guild.id, league.league_id, newWeekLabel);
    weeksSeen.push(newWeekLabel);
    pending = { weekLabel: newWeekLabel, previousWeekLabel: previousWeekLabelForLoop };
    previousWeekLabelForLoop = newWeekLabel;
  }

  if (!pending) {
    console.log(`[AUTO DETECT] No new advance detected for league ${league.league_id} — skipping week-level processing.`);
    return { advanced: false, weekLabel: null };
  }

  if (weeksSeen.length > 1) {
    console.log(`[AUTO DETECT] Catch-up: league ${league.league_id} advanced ${weeksSeen.length} weeks since last sync (${weeksSeen.join(' -> ')}) — processing each individually, threads/lines only for the final week.`);
  }

  // The last pending week really is final — nothing newer was discovered
  // after it.
  await finishMaddenCatchupWeek(pending.weekLabel, pending.previousWeekLabel, true);

  // 6. Persistent embed refresh (standings, free agents, power rankings) —
  // once at the end is enough; each intermediate week would only refresh
  // the same boards to the same eventual final state.
  await refreshPersistentMaddenEmbeds(guild, league).catch(err =>
    console.error('[AUTO DETECT] Persistent embeds:', err?.message));

  const finalWeekLabel = pending.weekLabel;
  console.log(`[AUTO DETECT] Completed for ${finalWeekLabel}, league ${league.league_id}` + (weeksSeen.length > 1 ? ` — caught up ${weeksSeen.length} weeks (${weeksSeen.join(', ')})` : ''));
  return { advanced: true, weekLabel: finalWeekLabel, weeksProcessed: weeksSeen.length, weeksList: weeksSeen, eventCount: allEvents.length };
}


