// 7J-LEAGUERULESET: shared builder so the commissioner-editable view, the
// public member-facing view, and (eventually) any recruitment/discovery
// surface all render this identically instead of drifting apart.
function buildLeagueRulesetEmbed(league, customSettings) {
  const sportKey = getLeagueSportKey(league);
  const isMadden = sportKey === 'madden';
  const gameEdition = customSettings.game_edition || 'Not set';
  const embed = new EmbedBuilder()
    .setTitle(`📝 League Info • ${league.league_name}`)
    .setColor(0x5865F2)
    .addFields(
      { name: 'Sport', value: sportKey.toUpperCase(), inline: true },
      { name: 'Season Length', value: league.season_length ? `${league.season_length} games` : 'Not set', inline: true },
      { name: 'Quarter Length', value: customSettings.quarter_length || 'Not set', inline: true },
      { name: 'Difficulty', value: customSettings.game_difficulty || 'Not set', inline: true },
      { name: 'Sim / Comp', value: customSettings.sim_or_comp || 'Not set', inline: true },
      { name: 'CPU Trades', value: customSettings.cpu_trades_allowed === false ? 'Not Allowed' : 'Allowed', inline: true },
      { name: 'Game Edition', value: gameEdition, inline: true },
    );
  if (!isMadden) {
    embed.addFields({ name: 'Schedule Style', value: customSettings.schedule_style === 'structured' ? 'Structured' : 'Open', inline: true });
  }
  if (customSettings.ruleset_notes) {
    embed.addFields({ name: 'Additional Notes', value: customSettings.ruleset_notes.slice(0, 1024), inline: false });
  }
  // 7J-GAMEEDITIONHOME: per Hxxdie — moved here from the Awards section.
  // Game Edition is stored on the same league_custom_settings.game_edition
  // column and used the same way (see 7J-ARCHIVESEASONNUMBER), just
  // surfaced somewhere a commissioner is more likely to actually look for
  // it — it reads as general league metadata ("what game is this league
  // on"), not something tied to Awards specifically, and most
  // commissioners won't make that connection on their own.
  embed.addFields({ name: 'About Game Edition', value: 'Tags which year\'s game (e.g. "Madden 26") each archived season was actually played on — set it once, then update it whenever the league switches to the new year\'s game. Doesn\'t affect the "Season 1, Season 2..." numbering, which keeps counting straight through; this just makes it possible to tell which real game a given season came from when looking back at league history later.', inline: false });
  embed.setFooter({ text: 'GG Sports • League Info' }).setTimestamp();
  return embed;
}

const LEAGUE_CUSTOMIZATION_SECTIONS = [
  { value: 'season', label: 'Season & Schedule', description: 'Season length, schedule style, matchup frequency', emoji: '📅' },
  { value: 'standings', label: 'Standings', description: 'W/L, points system, ties', emoji: '📊' },
  { value: 'playoffs', label: 'Playoffs', description: 'Team count, seeding, series length per round', emoji: '🏆' },
  { value: 'trades', label: 'Trades', description: 'CPU trades, trade limit per season', emoji: '🔀' },
  // 7J-ROSTERSECTION: per Hxxdie — Team Rosters (Pro-Am/Club) was living in
  // the Trades section, which was an awkward fit — it's about who can help
  // manage a team's roster in Discord, nothing to do with trading. Split
  // into its own section.
  { value: 'rosters', label: 'Team Rosters', description: 'Pro-Am/Club leagues — multiple players per team instead of 1 owner', emoji: '👥' },
  { value: 'awards', label: 'Awards', description: 'Which awards this league tracks', emoji: '🎖️' },
  { value: 'conferences', label: 'Team Conferences/Divisions', description: 'Turn conferences/divisions on/off, assign each team', emoji: '🗺️' },
  { value: 'wagers', label: 'Wagers', description: '1v1 game-thread wagers between owners, separate from the sportsbook', emoji: '💰' },
  // 7J-LEAGUERULESET: not Madden-hidden like season/playoffs/standings —
  // this is manually-entered descriptive info (quarter length, difficulty,
  // sim/comp) that EA sync never provides regardless of sport, so it's
  // just as relevant for a Madden league as any other.
  { value: 'ruleset', label: 'League Info / Ruleset', description: 'Quarter length, difficulty, sim/comp — shown to prospective members', emoji: '📝' },
];

// 7J-54LEAGUESETTINGS: per Hxxdie — Madden leagues follow EA's own sync
// data for season/schedule/playoff structure, so manually editing these is
// misleading (the values aren't actually read by any Madden code path).
// Confirmed via code search before filtering rather than assumed: the
// Madden playoff bracket is built entirely from EA-synced game/schedule
// rows (madden_imported_games with EA scheduleId) — playoff_team_count and
// playoff_seeding_method are never referenced anywhere in a Madden-specific
// path. Same for season_length/schedule_style.
// 7J-COMMANDHUB-MADDENSETTINGS: per Hxxdie (live-tested) — Standings and
// Conferences/Divisions belong on this list too, for the same reason:
// re-verified via code search (not just taken on faith) that
// standings_system and conferences/divisions are never read anywhere in a
// Madden-specific path — Madden's standings board and team
// conference/division alignment both come entirely from EA sync data, not
// these manual settings. Trades and Awards were checked at the time of the
// original filter and weren't confirmed inapplicable, so they're still
// left alone.
const MADDEN_HIDDEN_CUSTOMIZATION_SECTIONS = new Set(['season', 'playoffs', 'standings', 'conferences']);

function filterLeagueCustomizationSections(isMaddenLeague) {
  if (!isMaddenLeague) return LEAGUE_CUSTOMIZATION_SECTIONS;
  return LEAGUE_CUSTOMIZATION_SECTIONS.filter(s => !MADDEN_HIDDEN_CUSTOMIZATION_SECTIONS.has(s.value));
}

async function buildCommissionerLeagueEmbed(league) {
  const customSettings = await ensureLeagueCustomSettings(league).catch(() => ({}));
  const sportKey = getLeagueSportKey(league);
  const isMadden = sportKey === 'madden';
  const embed = new EmbedBuilder()
    .setTitle(`📋 League Customization • ${league.league_name}`)
    .setColor(0x5865F2)
    .setDescription(`Sport: **${sportKey.toUpperCase()}**\nPick a section below to configure. These settings apply to standings, playoffs, and future schedule/trade features as they're built.` + (isMadden ? '\n\n*Season/schedule, playoff structure, standings, and conferences/divisions all follow this league\'s Madden sync and aren\'t manually configurable — those sections are hidden below.*' : ''))
    .addFields(
      { name: 'CPU Trades', value: customSettings.cpu_trades_allowed === false ? 'Not Allowed' : 'Allowed', inline: true },
    )
    .setFooter({ text: 'GG Sports • Commissioner Panel' })
    .setTimestamp();
  if (!isMadden) {
    embed.addFields(
      { name: 'Standings System', value: customSettings.standings_system === 'points' ? 'Points-based' : 'W/L Record', inline: true },
      { name: 'Season Length', value: league.season_length ? `${league.season_length} games` : 'Not set', inline: true },
      { name: 'Schedule Style', value: customSettings.schedule_style === 'structured' ? 'Structured' : 'Open', inline: true },
      { name: 'Playoff Teams', value: String(league.playoff_team_count || 8), inline: true },
      { name: 'Seeding Method', value: customSettings.playoff_seeding_method || 'overall_record', inline: true },
    );
  }
  return embed;
}

function buildCommissionerLeagueComponents(leagueId, isMaddenLeague = false) {
  const menu = new StringSelectMenuBuilder()
    .setCustomId('commissioner_league_section:' + leagueId)
    .setPlaceholder('Choose a section to configure')
    .addOptions(filterLeagueCustomizationSections(isMaddenLeague).map(s => ({ label: s.label, value: s.value, description: s.description, emoji: s.emoji })));
  return [new ActionRowBuilder().addComponents(menu), buildCommissionerBackRow(leagueId)];
}

// 7J-SETUPORDER: per Hxxdie — nothing was visually guiding a commissioner
// toward the correct setup order, and nothing stopped them from doing
// things out of sequence in ways that silently produce broken results
// (Staff channel with no staff role to lock it to, boards that reference
// team roles at posting time coming out empty). Order here matches
// /setupguide exactly: League Roles before League Settings, League
// Settings before Team Roles/Channels, Team Roles before Channels.
async function showCommissionerSetupChecklist(interaction, leagueId) {
  const league = await getLeagueById(leagueId);
  if (!league) { await interaction.update({ content: 'League not found.', embeds: [], components: [] }); return; }

  const customSettings = await ensureLeagueCustomSettings(league).catch(() => ({}));
  const teamRoles = await getLeagueTeamRoles(league.league_id).catch(() => []);
  const isMadden = getLeagueSportKey(league) === 'madden';
  const isPremiumGuild = await isGuildPremiumActive(interaction.guild.id).catch(() => false);
  const guildPanelCount = await pool.query(`SELECT COUNT(*)::int AS n FROM multi_channel_panels WHERE guild_id = $1`, [interaction.guild.id])
    .then(r => r.rows[0]?.n || 0).catch(() => 0);

  const steps = [
    { done: true, label: 'Create the League', doneNote: 'Done.' },
    { done: Boolean(league.staff_role_id && league.league_role_id && league.trade_committee_role_id), label: 'Auto Create League Roles', note: 'League Setup → Auto Create League Roles', doneNote: 'League/Staff/Trade Committee roles all exist.' },
  ];
  // League Settings has no clean "done" state (settings can always be
  // adjusted), so it's shown as a recommended checkpoint rather than a
  // pass/fail checkbox — schedule_style being set at all is used as a
  // loose signal that this section has actually been visited.
  if (!isMadden) {
    steps.push({ done: customSettings.schedule_style !== null && customSettings.schedule_style !== undefined, label: 'League Settings (season length, schedule style, etc.)', note: 'Commissioner Panel → League Settings', doneNote: 'Schedule style has been set.' });
  }
  // 7J-CHECKLISTREORDER: per Hxxdie — guild-wide Server Channels has no
  // dependency on this specific league's roles/teams (it's one-time-per-
  // server), so it doesn't actually need to wait for Team Roles the way
  // Auto-Setup Channels genuinely does. Moved ahead of it.
  if (isPremiumGuild) {
    steps.push({
      done: guildPanelCount > 0,
      label: 'Auto Setup Server Channels (Shop/Sportsbook/etc.)',
      note: 'Admin Panel → Server Setup — guild-wide, once per server',
      doneNote: 'Already set up for this server — this is a one-time, guild-wide step, not per-league, so there\'s nothing more to do here. Move on to the next step.',
    });
  }
  steps.push({ done: teamRoles.length >= 2, label: 'Auto Create Team Roles (at least 2)', note: 'Channels & Roles → Auto Create Team Roles', doneNote: `${teamRoles.length} team role(s) registered.` });
  steps.push({ done: Boolean(league.league_announcement_channel_id), label: 'Auto-Setup Channels', note: 'Channels & Roles → Auto-Setup Channels', doneNote: 'Channels have been created for this league.' });
  if (!isMadden && customSettings.schedule_style === 'structured') {
    steps.push({ done: Number(customSettings.current_round || 0) > 0, label: 'Start League', note: 'Commissioner Panel → Operations → Advance', doneNote: 'Season is underway.' });
  }

  const NL = String.fromCharCode(10);
  const lines = steps.map((s, i) => `${s.done ? '✅' : '⬜'} **${i + 1}. ${s.label}**${NL}   ↳ ${s.done ? (s.doneNote || 'Done.') : s.note}`);
  const nextStep = steps.find(s => !s.done);

  const embed = new EmbedBuilder()
    .setTitle(`✅ Setup Checklist • ${league.league_name}`)
    .setColor(nextStep ? 0xFEE75C : 0x57F287)
    .setDescription(lines.join(NL) + NL + NL + (nextStep ? `**Next up:** ${nextStep.label}` : '**All core setup steps are done.**') + NL + NL + 'Full written walkthrough: `/setupguide`. Short version: `/quicksetup`.')
    .setFooter({ text: 'GG Sports • Commissioner Panel' })
    .setTimestamp();

  const payload = { content: null, embeds: [embed], components: [buildCommissionerBackRow(leagueId)] };
  if (interaction.deferred || interaction.replied) {
    await interaction.editReply(payload);
  } else {
    await interaction.update(payload);
  }
}

async function showCommissionerLeagueSettings(interaction, leagueId) {
  const league = await getLeagueById(leagueId);
  if (!league) {
    await interaction.update({ content: 'League not found.', embeds: [], components: [] });
    return;
  }
  const payload = { content: null, embeds: [await buildCommissionerLeagueEmbed(league)], components: buildCommissionerLeagueComponents(leagueId, getLeagueSportKey(league) === 'madden') };
  if (interaction.deferred || interaction.replied) {
    await interaction.editReply(payload);
  } else {
    await interaction.update(payload);
  }
}

function buildLeagueCustomizationBackRow(leagueId) {
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder().setCustomId('leaguecustom_back:' + leagueId).setLabel('⬅ Back to Sections').setStyle(ButtonStyle.Secondary)
  );
}

async function showLeagueCustomizationSection(interaction, leagueId, section, { update = true } = {}) {
  const league = await getLeagueById(leagueId);
  if (!league) { await interaction.update({ content: 'League not found.', embeds: [], components: [] }); return; }
  const customSettings = await ensureLeagueCustomSettings(league).catch(() => ({}));
  let embed;
  let components;

  if (section === 'season') {
    embed = new EmbedBuilder()
      .setTitle(`📅 Season & Schedule • ${league.league_name}`)
      .setColor(0x5865F2)
      .addFields(
        { name: 'Season Length', value: league.season_length ? `${league.season_length} games` : 'Not set', inline: true },
        { name: 'Schedule Style', value: customSettings.schedule_style === 'structured' ? 'Structured (advance-to-next-opponent + auto threads)' : 'Open (no fixed schedule)', inline: true },
        { name: 'Matchup Frequency', value: `${customSettings.matchup_frequency || 1}x per opponent (structured mode only)`, inline: true },
      )
      .setFooter({ text: 'GG Sports • League Customization' })
      .setTimestamp();
    const styleMenu = new StringSelectMenuBuilder()
      .setCustomId('leaguecustom_schedulestyle:' + leagueId)
      .setPlaceholder('Choose a schedule style')
      .addOptions([
        { label: 'Open Schedule', value: 'open', description: 'No fixed schedule, teams arrange games freely', default: customSettings.schedule_style !== 'structured' },
        { label: 'Structured Schedule', value: 'structured', description: 'Advance-to-next-opponent, auto thread creation', default: customSettings.schedule_style === 'structured' },
      ]);
    components = [
      new ActionRowBuilder().addComponents(styleMenu),
      new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('leaguecustom_season_modal:' + leagueId).setLabel('Edit Season Length & Matchup Frequency').setStyle(ButtonStyle.Primary)),
      buildLeagueCustomizationBackRow(leagueId),
    ];
  } else if (section === 'standings') {
    embed = new EmbedBuilder()
      .setTitle(`📊 Standings • ${league.league_name}`)
      .setColor(0x5865F2)
      .addFields(
        { name: 'System', value: customSettings.standings_system === 'points' ? 'Points-based' : customSettings.standings_system === 'point_differential' ? 'Point Differential' : 'W/L Record', inline: true },
        { name: 'Win / Loss / Tie Points', value: `${customSettings.win_points ?? 2} / ${customSettings.loss_points ?? 0} / ${customSettings.tie_points ?? 1}`, inline: true },
        { name: 'Ties Allowed', value: customSettings.ties_allowed ? 'Yes' : 'No', inline: true },
        { name: 'OTL Allowed', value: customSettings.otl_allowed ? `Yes (${customSettings.otl_points ?? 1} pts)` : 'No', inline: true },
        { name: 'Sudden Death OT', value: customSettings.sudden_death_ot ? 'Yes — OT/SO losses must be by exactly 1' : 'No', inline: true },
      )
      .setFooter({ text: 'GG Sports • League Customization' })
      .setTimestamp();
    const sysMenu = new StringSelectMenuBuilder()
      .setCustomId('leaguecustom_standingssys:' + leagueId)
      .setPlaceholder('Choose a standings system')
      .addOptions([
        { label: 'W/L Record', value: 'wl', default: customSettings.standings_system === 'wl' || !customSettings.standings_system },
        { label: 'Points-based (win/loss/tie values)', value: 'points', default: customSettings.standings_system === 'points' },
        { label: 'Point Differential', value: 'point_differential', default: customSettings.standings_system === 'point_differential' },
      ]);
    components = [
      new ActionRowBuilder().addComponents(sysMenu),
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('leaguecustom_points_modal:' + leagueId).setLabel('Edit Win/Loss/Tie Points').setStyle(ButtonStyle.Primary),
        new ButtonBuilder().setCustomId('leaguecustom_toggle_ties:' + leagueId).setLabel(customSettings.ties_allowed ? 'Disable Ties' : 'Enable Ties').setStyle(ButtonStyle.Secondary),
      ),
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('leaguecustom_toggle_otl:' + leagueId).setLabel(customSettings.otl_allowed ? 'Disable OTL' : 'Enable OTL').setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('leaguecustom_otlpoints_modal:' + leagueId).setLabel('Edit OTL Points').setStyle(ButtonStyle.Primary).setDisabled(!customSettings.otl_allowed),
      ),
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('leaguecustom_toggle_suddendeath:' + leagueId).setLabel(customSettings.sudden_death_ot ? 'Disable Sudden Death OT' : 'Enable Sudden Death OT').setStyle(ButtonStyle.Secondary).setDisabled(!customSettings.otl_allowed),
      ),
      buildLeagueCustomizationBackRow(leagueId),
    ];
  } else if (section === 'playoffs') {
    const seriesLengths = Array.isArray(customSettings.playoff_series_lengths) ? customSettings.playoff_series_lengths : [];
    embed = new EmbedBuilder()
      .setTitle(`🏆 Playoffs • ${league.league_name}`)
      .setColor(0x5865F2)
      .addFields(
        { name: 'Playoff Teams', value: String(league.playoff_team_count || 8), inline: true },
        { name: 'Seeding Method', value: customSettings.playoff_seeding_method || 'overall_record', inline: true },
        { name: 'Series Length Per Round', value: seriesLengths.length ? seriesLengths.map((n, i) => `Round ${i + 1}: Bo${n}`).join(', ') : 'Not set (defaults to single game)', inline: false },
      )
      .setFooter({ text: 'GG Sports • League Customization' })
      .setTimestamp();
    const seedMenu = new StringSelectMenuBuilder()
      .setCustomId('leaguecustom_seeding:' + leagueId)
      .setPlaceholder('Choose a seeding method')
      .addOptions([
        { label: 'Overall Record', value: 'overall_record', default: customSettings.playoff_seeding_method === 'overall_record' || !customSettings.playoff_seeding_method },
        { label: 'By Conference', value: 'conference', default: customSettings.playoff_seeding_method === 'conference' },
        { label: 'By Division', value: 'division', default: customSettings.playoff_seeding_method === 'division' },
      ]);
    components = [
      new ActionRowBuilder().addComponents(seedMenu),
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('leaguecustom_playoffteams_modal:' + leagueId).setLabel('Edit Playoff Team Count').setStyle(ButtonStyle.Primary),
        new ButtonBuilder().setCustomId('leaguecustom_series_modal:' + leagueId).setLabel('Edit Series Lengths').setStyle(ButtonStyle.Primary),
      ),
      buildLeagueCustomizationBackRow(leagueId),
    ];
  } else if (section === 'trades') {
    // 7J-COMMITTEEVOTES: shows current committee role size alongside the
    // votes-needed setting, per Hxxdie — a commissioner picking a
    // threshold needs to know how many actual committee members there are
    // to set a sensible number (e.g. don't require 5 votes with only 3
    // members).
    let committeeSize = 'Unknown';
    if (league.trade_committee_role_id) {
      const committeeRole = await interaction.guild.roles.fetch(league.trade_committee_role_id).catch(() => null);
      if (committeeRole) committeeSize = String(committeeRole.members.filter(m => !m.user.bot).size);
    }
    embed = new EmbedBuilder()
      .setTitle(`🔀 Trades • ${league.league_name}`)
      .setColor(0x5865F2)
      .addFields(
        { name: 'CPU Trades', value: customSettings.cpu_trades_allowed === false ? 'Not Allowed' : 'Allowed', inline: true },
        { name: 'Trade Limit Per Season', value: customSettings.trade_limit_per_season ? `${customSettings.trade_limit_per_season} trades` : 'Unlimited', inline: true },
        { name: 'Committee Votes Needed', value: String(customSettings.trade_committee_votes_needed || 3), inline: true },
        { name: 'Current Committee Size', value: committeeSize, inline: true },
      )
      .setFooter({ text: 'GG Sports • League Customization' })
      .setTimestamp();
    components = [
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('leaguecustom_toggle_cpu:' + leagueId).setLabel(customSettings.cpu_trades_allowed === false ? 'Allow CPU Trades' : 'Disallow CPU Trades').setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('leaguecustom_tradelimit_modal:' + leagueId).setLabel('Edit Trade Limit').setStyle(ButtonStyle.Primary),
      ),
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('leaguecustom_committeevotes_modal:' + leagueId).setLabel('Edit Committee Votes Needed').setStyle(ButtonStyle.Primary),
      ),
      buildLeagueCustomizationBackRow(leagueId),
    ];
  } else if (section === 'rosters') {
    // 7J-ROSTERSECTION: relocated out of Trades, per Hxxdie — this is about
    // who can help manage a team's roster in Discord (Pro-Am/Club style),
    // unrelated to trading.
    embed = new EmbedBuilder()
      .setTitle(`👥 Team Rosters • ${league.league_name}`)
      .setColor(0x5865F2)
      .setDescription('For Pro-Am/Club style leagues — where a "team" is a group of multiple players rather than one owner controlling the whole roster, unlike a typical 1-to-1 owner-to-team league. When enabled, a team owner can add other members as player/coach/GM to help manage their team. GM is treated as functionally equivalent to the owner for actions gated on "do you own this team" (score reporting, trades, etc.) — player/coach are organizational only.')
      .addFields(
        { name: 'Team Rosters', value: customSettings.use_team_roster ? 'On — owners can add players/coaches/GMs' : 'Off', inline: true },
      )
      .setFooter({ text: 'GG Sports • League Customization' })
      .setTimestamp();
    components = [
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('leaguecustom_toggle_roster:' + leagueId).setLabel(customSettings.use_team_roster ? 'Disable Team Rosters' : 'Enable Team Rosters').setStyle(ButtonStyle.Secondary),
      ),
      buildLeagueCustomizationBackRow(leagueId),
    ];
  } else if (section === 'wagers') {
    embed = new EmbedBuilder()
      .setTitle(`💰 Wagers • ${league.league_name}`)
      .setColor(0x5865F2)
      .setDescription('A straight 1v1 bet between the two owners in a game thread — propose an amount, the other owner accepts or declines, winner takes both. Nothing to do with the sportsbook or moneylines.')
      .addFields(
        { name: 'Wagers', value: customSettings.wagers_enabled ? 'Enabled' : 'Disabled', inline: true },
      )
      .setFooter({ text: 'GG Sports • League Customization' })
      .setTimestamp();
    components = [
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('leaguecustom_toggle_wagers:' + leagueId).setLabel(customSettings.wagers_enabled ? 'Disable Wagers' : 'Enable Wagers').setStyle(ButtonStyle.Secondary),
      ),
      buildLeagueCustomizationBackRow(leagueId),
    ];
  } else if (section === 'ruleset') {
    embed = buildLeagueRulesetEmbed(league, customSettings);
    components = [
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('leaguecustom_ruleset_modal:' + leagueId).setLabel('Edit League Info').setStyle(ButtonStyle.Primary),
        new ButtonBuilder().setCustomId('leaguecustom_gameedition:' + leagueId).setLabel('Edit Game Edition').setEmoji('🎮').setStyle(ButtonStyle.Secondary),
      ),
      buildLeagueCustomizationBackRow(leagueId),
    ];
  } else if (section === 'awards') {
    const awards = Array.isArray(customSettings.awards) ? customSettings.awards : [];
    const trophyName = getChampionshipTrophyName(league, customSettings);
    embed = new EmbedBuilder()
      .setTitle(`🎖️ Awards • ${league.league_name}`)
      .setColor(0x5865F2)
      .addFields(
        { name: 'Championship Trophy Name', value: trophyName, inline: true },
      )
      .setDescription((awards.length ? awards.map((a, i) => `${i + 1}. ${a.label}${a.tieredCosmetic ? ' 🎁' : ''}`).join('\n') : 'No awards configured yet.')
        + '\n\n🎁 = grants an automated tiered cosmetic item (usually the MVP-equivalent award); every other award pays currency instead.'
        + '\n\nThis is the list of awards this league recognizes. There\'s no live stat-driven race for non-Madden leagues — record each season\'s winners from **Operations → Season History** at season end, which walks through the champion and each configured award with team/user pickers, posts everything in the League History channel, and updates franchise legacy.')
      .setFooter({ text: 'GG Sports • League Customization' })
      .setTimestamp();
    const rows = [new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId('leaguecustom_award_add:' + leagueId).setLabel('Add Award').setEmoji('➕').setStyle(ButtonStyle.Success),
      new ButtonBuilder().setCustomId('leaguecustom_trophyname:' + leagueId).setLabel('Edit Trophy Name').setEmoji('🏆').setStyle(ButtonStyle.Secondary),
    )];
    if (awards.length) {
      const removeMenu = new StringSelectMenuBuilder()
        .setCustomId('leaguecustom_award_remove:' + leagueId)
        .setPlaceholder('Remove an award')
        .addOptions(awards.slice(0, 25).map(a => ({ label: a.label.slice(0, 100), value: a.key.slice(0, 100) })));
      rows.push(new ActionRowBuilder().addComponents(removeMenu));
    }
    rows.push(buildLeagueCustomizationBackRow(leagueId));
    components = rows;
  } else if (section === 'conferences') {
    // 7J-CONFTEAMCAP: per Hxxdie — this LIMIT 25 silently capped both the
    // team list shown here AND the assignment dropdown at 25 teams, so any
    // league with more than that (NHL's 32, for example) could never fully
    // set up conferences/divisions — the remaining teams were never even
    // visible, let alone assignable. Same root cause class as the
    // recruitment/tournament dropdown caps fixed earlier; every menu like
    // this needs every team reachable or league setup can't ever finish.
    const teamsResult = await pool.query(`SELECT * FROM league_team_roles WHERE league_id = $1 ORDER BY role_name ASC`, [leagueId]);
    const confUseConferences = customSettings.use_conferences ?? isNbaLeague(league);
    const confUseDivisions = customSettings.use_divisions ?? false;
    embed = new EmbedBuilder()
      .setTitle(`🗺️ Team Conferences/Divisions • ${league.league_name}`)
      .setColor(0x5865F2)
      .addFields(
        { name: 'Conferences', value: confUseConferences ? '✅ On — grouped in standings/playoffs' : '❌ Off', inline: true },
        { name: 'Divisions', value: confUseDivisions ? '✅ On — grouped in standings/playoffs' : '❌ Off', inline: true },
      )
      .setDescription(teamsResult.rows.length
        ? teamsResult.rows.map(t => `**${t.role_name}** — ${t.conference || 'No conference'}${t.division ? ' / ' + t.division : ''}`).join('\n').slice(0, 4096)
        : 'No team roles found for this league yet.')
      .setFooter({ text: 'GG Sports • League Customization' })
      .setTimestamp();
    components = [
      new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('leaguecustom_toggle_conferences:' + leagueId).setLabel(confUseConferences ? 'Disable Conferences' : 'Enable Conferences').setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('leaguecustom_toggle_divisions:' + leagueId).setLabel(confUseDivisions ? 'Disable Divisions' : 'Enable Divisions').setStyle(ButtonStyle.Secondary),
      ),
    ];
    if (teamsResult.rows.length) {
      // 7J-CONFTEAMCAP: split across up to 5 select menus (125 teams) same
      // as the recruitment/tournament dropdown fixes, instead of a single
      // menu silently truncating at Discord's 25-option cap.
      for (let i = 0; i < teamsResult.rows.length && i < 125; i += 25) {
        const chunk = teamsResult.rows.slice(i, i + 25);
        const menuIndex = i / 25;
        const teamMenu = new StringSelectMenuBuilder()
          .setCustomId(`leaguecustom_team_select${menuIndex ? menuIndex : ''}:${leagueId}`)
          .setPlaceholder(teamsResult.rows.length <= 25 ? 'Choose a team to assign conference/division' : `Choose a team (${i + 1}-${Math.min(i + 25, teamsResult.rows.length)})`)
          .addOptions(chunk.map(t => ({ label: t.role_name.slice(0, 100), value: t.role_id.slice(0, 100) })));
        components.push(new ActionRowBuilder().addComponents(teamMenu));
      }
    }
    components.push(buildLeagueCustomizationBackRow(leagueId));
  } else {
    embed = new EmbedBuilder().setTitle('Unknown section').setColor(0xED4245);
    components = [buildLeagueCustomizationBackRow(leagueId)];
  }

  const payload = { content: null, embeds: [embed], components };
  return update ? interaction.update(payload) : interaction.editReply(payload);
}

// 7J-10AX Madden Compare Value + Trade Foundation